window.POEM_DB=window.POEM_DB||{};POEM_DB["yangwanli"]={"n":"杨万里","dyn":"宋","poems":[{"t":"题王才臣南山隐居六咏 其一 庄敬日强斋","f":"五言绝句","c":["居人晏犹眠，行子夕未宿。","此心从何生，却道力不足。"]},{"t":"一鹭先立池中，有双鹭自外来。先立者逐之，双鹭亟去，莫敢敌者","f":"七言绝句","c":["鹭鸶各自有食邑，长恐诸侯客子来。","一鹭忽追双鹭去，穷追尽处始飞回。"]},{"t":"丁亥正月新晴晚步二首 其二","f":"七言绝句","c":["急下柴车踏晚晴，青鞋步步有沙声。","忽逢野沼无人处，两鸭浮沉最眼明。"]},{"t":"丁亥正月新晴晚步二首 其一","f":"七言绝句","c":["嫩水春来别样光，草芽绿甚却成黄。","东风似与行人便，吹尽寒云放夕阳。"]},{"t":"丁酉四月十日之官毗陵舟行阻风宿椆陂江口二首 其一","f":"七言绝句","c":["虫声两岸不堪闻，把烛销愁且一尊。","谁宿此船愁似我，船篷犹带烛烟痕。"]},{"t":"丁酉四月十日之官毗陵舟行阻风宿椆陂江口二首 其二","f":"七言绝句","c":["十里江行一日程，出山似被北风嗔。","东窗水影西窗月，并照船中不睡人。"]},{"t":"七夕新凉","f":"七言绝句","c":["商量秋思是寒螀，将息荷花得早凉。","五岭从来说炎热，朝来已怯葛衣裳。"]},{"t":"七月二十三日题李亨之墨梅","f":"五言绝句","c":["夏热秋逾甚，寒梅暑亦开。","无尘管城子，幻出雪枝来。"]},{"t":"七月二十五日晓登多稼亭","f":"七言绝句","c":["风将烟雨入亭寒，城引山林拓眼宽。","六月登临浑觉热，朝来不敢傍危栏。"]},{"t":"七月十四日雨后毗陵郡圃荷桥上纳凉","f":"五言绝句","c":["荷叶迎风听，荷花过雨看。","移床桥上坐，堕我镜中寒。"]},{"t":"七月既望晚观菱壕","f":"七言绝句","c":["官壕水落两三痕，正是秋初雨后天。","菱荇中间开一路，晓来谁过采菱船。"]},{"t":"九月十五夜月细看桂枝北茂南缺未经古人拈出纪以二绝句 其二","f":"七言绝句","c":["青天如水月如空，月色天容一皎中。","若遣桂华生塞了，姮娥无殿兔无宫。"]},{"t":"九月十五夜月细看桂枝北茂南缺未经古人拈出纪以二绝句 其一","f":"七言绝句","c":["桂树冰轮两不齐，桂圆不似月圆时。","吴刚玉斧何曾巧，斫尽南枝放北枝。"]},{"t":"二月一日雨寒五首 其五","f":"七言绝句","c":["只见春晴道是晴，不知半夜嫩寒生。","疾风吹落林间雨，细雨还成大雨声。"]},{"t":"二月一日雨寒五首 其四","f":"七言绝句","c":["姚黄魏紫向谁赊，郁李樱桃也没些。","却是南中春色别，满城都是木绵花。"]},{"t":"二月一日雨寒五首 其三","f":"七言绝句","c":["梳头正美睡相催，理尽霜丝梦恰回。","窗隙小风能几许，也吹蛛网去还来。"]},{"t":"二月一日雨寒五首 其二","f":"七言绝句","c":["补尽窗棂闭尽门，茶瓯火阁对炉熏。","中庭浅水休教扫，政要留看雨点纹。"]},{"t":"二月一日雨寒五首 其一","f":"七言绝句","c":["南方气候北方殊，春里清寒腊里无。","雨入竹林浑不见，只来叶尾作真珠。"]},{"t":"二月一日郡圃寻春二首 其二","f":"七言绝句","c":["花绕朱檐柳绕栏，小亭面面锦团栾。","春风横欲欺诗瘦，且下东窗护嫩寒。"]},{"t":"二月一日郡圃寻春二首 其一","f":"七言绝句","c":["中和节里半春天，一拂清寒半点暄。","憔悴不胜梅欲落，娇饶无对杏初繁。"]},{"t":"二月一日晓渡太和江三首 其三","f":"七言绝句","c":["二月初头春向中，花梢薄日柳梢风。","折花客子浑无赖，狼藉须教满路红。"]},{"t":"二月一日晓渡太和江三首 其二","f":"七言绝句","c":["晓翠妨人看远山，小风偏入客衣单。","桃花爱做春寒信，只恐桃花也自寒。"]},{"t":"二月一日晓渡太和江三首 其一","f":"七言绝句","c":["绿杨接叶杏交花，嫩水新生尚露沙。","过了春江偶回首，隔江一片好人家。"]},{"t":"二月二十三日南雄解舟二首 其二","f":"七言绝句","c":["水没蒲芽尚有梢，风吹屋角半无茅。","急滩未到先闻浪，枯树遥看只见巢。"]},{"t":"二月二十三日南雄解舟二首 其一","f":"七言绝句","c":["昨夜新雷九地鸣，今朝春涨一篙清。","顺流更借江风便，此去韶州只两程。"]},{"t":"二月十一日夜梦作东都蚤春绝句","f":"五言绝句","c":["道是春来早，如何未见春。","小桃三四点，偏报有情人。"]},{"t":"二月十九日度大庾岭题云封寺四首 其四","f":"七言绝句","c":["行者南来今几春，一回举似一回新。","钵盂夺得知何用，不怕梅花解笑人。"]},{"t":"二月十九日度大庾岭题云封寺四首 其三","f":"七言绝句","c":["梅叶成阴梅子肥，梅花应恨我来迟。","明年若寄江西信，莫折南枝折北枝。"]},{"t":"二月十九日度大庾岭题云封寺四首 其二","f":"七言绝句","c":["小立峰头望故乡，故乡不见只苍苍。","客心恨杀云遮却，不道无云即断肠。"]},{"t":"二月十九日度大庾岭题云封寺四首 其一","f":"七言绝句","c":["梅山未到未教休，到得梅山始欲愁。","知道望乡看不见，也须一步一回头。"]},{"t":"二月十四日晓起看海棠八首 其八","f":"五言绝句","c":["除却牡丹了，海棠当亚元。","艳超红白外，香在有无间。"]},{"t":"二月十四日晓起看海棠八首 其七","f":"五言绝句","c":["老子侵星起，蜂儿先我忙。","渊才无鼻孔，信口道无香。"]},{"t":"二月十四日晓起看海棠八首 其六","f":"五言绝句","c":["外种百来树，中安一小亭。","放眸红未了，红了是天青。"]},{"t":"二月十四日晓起看海棠八首 其五","f":"五言绝句","c":["花密无重数，看来眼转迷。","化为花世界，忘却日东西。"]},{"t":"二月十四日晓起看海棠八首 其四","f":"五言绝句","c":["四面花光合，一身香雾红。","忽从霞绮上，跳下锦城中。"]},{"t":"二月十四日晓起看海棠八首 其三","f":"五言绝句","c":["晚得看花诀，丁宁趁绝晨。","乘他醉眠起，别是一精神。"]},{"t":"二月十四日晓起看海棠八首 其二","f":"五言绝句","c":["初日光殊薄，晴梢露正浓。","真珠妆未稳，更著柳边风。"]},{"t":"二月十四日晓起看海棠八首 其一","f":"五言绝句","c":["过雨天犹湿，新晴日尚寒。","悬知晓妆好，破雾急来看。"]},{"t":"二月十四日梅花二首 其二","f":"五言绝句","c":["树劲春犹瘦，花寒暮更明。","平生岂无句，此外不须清。"]},{"t":"二月十四日梅花二首 其一","f":"五言绝句","c":["雨打知无那，春暄绝不禁。","小风千点雪，落日一须金。"]},{"t":"二月将半寒暄不常","f":"七言绝句","c":["南中冷暖直难齐，一日之间具四时。","脱了又添添又脱，寒衣暑服镇相随。"]},{"t":"二月望日","f":"七言绝句","c":["海棠著意唤诗愁，桃李才开又落休。","小雨轻风春一半，去年今日在严州。"]},{"t":"二月望日劝农既归散策郡圃二首 其二","f":"七言绝句","c":["今年花事许迟迟，九十春光已半归。","风急杏花吹不脱，落梅无数掠人飞。"]},{"t":"二月望日劝农既归散策郡圃二首 其一","f":"七言绝句","c":["荆溪老守劝农归，吏散还从郡圃嬉。","拾得落英才一掬，春风苦向掌中吹。"]},{"t":"二含笑俱作秋花","f":"七言绝句","c":["秋来二笑再芬芳，紫笑何如白笑强。","只有此花偷不得，无人知处忽然香。"]},{"t":"人日出游湖上十首 其十","f":"五言绝句","c":["此行殊匆匆，天色不肯借。","更待海棠晴，满意孤山下。"]},{"t":"人日出游湖上十首 其九","f":"五言绝句","c":["上竺雪来时，四山都作冻。","团团玉屏风，围绕浑无缝。"]},{"t":"人日出游湖上十首 其八","f":"五言绝句","c":["客爱清殊绝，僧愁冻不胜。","可怜兜率寺，斋供一湖冰。"]},{"t":"人日出游湖上十首 其七","f":"五言绝句","c":["去岁游春屐，苔痕故可寻。","人家随岸远，塔影落湖深。"]},{"t":"人日出游湖上十首 其六","f":"五言绝句","c":["城中雪一尺，山中雪一丈。","地上都已消，却在松梢上。"]},{"t":"人日出游湖上十首 其五","f":"五言绝句","c":["树隐重重竹，溪穿曲曲峰。","林深那有寺，烟远忽闻钟。"]},{"t":"人日出游湖上十首 其四","f":"五言绝句","c":["肩舆岂不稳，万象非我有。","呼童换马来，湖山落吾手。"]},{"t":"人日出游湖上十首 其三","f":"五言绝句","c":["旧腊缘多雪，新年未有梅。","殷勤下天竺，隔水两株开。"]},{"t":"人日出游湖上十首 其二","f":"五言绝句","c":["去时数点雨，归时数片雪。","雨雪两不多，山路双清绝。"]},{"t":"人日出游湖上十首 其一","f":"五言绝句","c":["放闸冷泉亭，抽动一天碧。","平地跳雪山，晴空下霹雳。"]},{"t":"人日后归自郡城","f":"七言绝句","c":["倦来睡思酒般醲，晓起东园看晓风。","孤负梅花三四日，新年人事到城中。"]},{"t":"人日宿味田驿","f":"七言绝句","c":["破驿荒凉晚解鞍，急呼重碧敌轻寒。","南中气候从头错，人日青梅已酽酸。"]},{"t":"儿啼索饭","f":"七言绝句","c":["饱暖君恩岂不知，小儿穷惯只长饥。","朝朝听得儿啼处，正是炊粱欲熟时。"]},{"t":"入上饶界道中野酴醾盛开二首 其二","f":"七言绝句","c":["走上松梢绕却它，为它满插一头花。","未论似得酴醾否，且是幽香野得些。"]},{"t":"入上饶界道中野酴醾盛开二首 其一","f":"七言绝句","c":["千朵齐开雪面皮，一芽初长紫兰枝。","一芽来岁还千朵，谁见开花似雪时。"]},{"t":"入长安闸","f":"七言绝句","c":["船入长安恰五更，归人都喜近临平。","阴晴天色知何似，篷上惟闻扫雪声。"]},{"t":"入北昭庆寺","f":"七言绝句","c":["两岸芙蓉雨洗妆，愁将红泪照银塘。","抬头不起珠玑重，柳外西风特地狂。"]},{"t":"入城","f":"七言绝句","c":["杜鹃有底怨春啼，燕子无端贴水飞。","不种自红仍自白，野酴醾压野蔷薇。"]},{"t":"入郡城泊文家宅子夜热不寐","f":"七言绝句","c":["毒热通宵不得眠，起来弄水绕庭前。","大星跳下银盆底，翻动琉璃一镜天。"]},{"t":"入常山界二首 其二","f":"七言绝句","c":["昨日愁霖今喜晴，好山夹路玉亭亭。","一峰忽被云偷去，留得峥嵘半截青。"]},{"t":"入常山界二首 其一","f":"七言绝句","c":["老随千骑赴毗陵，骑吏朝来有喜声。","未到常山三十里，此身已在浙中行。"]},{"t":"入程乡县界","f":"七言绝句","c":["长乐昏岚著地凝，程乡毒雾噀人腥。","吾诗不是南征集，只合标题作瘴经。"]},{"t":"十一月十九日折梅二首 其二","f":"七言绝句","c":["也知春向岁前回，不道春前早有梅。","折得数枝撚归去，蜂儿一路趁人来。"]},{"t":"十一月十九日折梅二首 其一","f":"七言绝句","c":["初爱寒香一朵斜，又逢奇朵出高丫。","折来折去花多了，忘却前花与后花。"]},{"t":"十二月二十七日大雪中过吉水小盘渡西归三首 其三","f":"七言绝句","c":["雪吹醉面不知寒，信脚千山与万山。","天甃琼街三十里，更飞柳絮与君看。"]},{"t":"十二月二十七日大雪中过吉水小盘渡西归三首 其二","f":"七言绝句","c":["腊残滕六不归家，白昼乘风撒玉沙。","旋种琼田茁瑶草，更栽琪树著银花。"]},{"t":"十二月二十七日大雪中过吉水小盘渡西归三首 其一","f":"七言绝句","c":["风卷寒江浪湿天，斜吹乱雪忽平船。","碧琉璃上琼花里，独载诗人孟浩然。"]},{"t":"十山歌呈太守胡平一 其九","f":"七言绝句","c":["北门今早顿然清，怀璧操金尽夜行。","却有一般可怜底，群偷枉却费家兄。"]},{"t":"十山歌呈太守胡平一 其十","f":"七言绝句","c":["行人满路喜歌呼，小盗何须辱庙谟。","早个使君归鼎轴，为禽颉利系单于。"]},{"t":"十山歌呈太守胡平一 其七","f":"七言绝句","c":["近有村人带血论，使君亲与验伤痕。","鹜行刚道非行劫，只是行人两作喧。"]},{"t":"十山歌呈太守胡平一 其四","f":"七言绝句","c":["说似行人且细听，螺冈门外莫宵征。","前头石斧韩婆岭，第一单身不要行。"]},{"t":"十山歌呈太守胡平一 其六","f":"七言绝句","c":["王黄二盗久驰声，手棒腰刀白昼行。","逢著村人持一物，喝令放下敢谁争。"]},{"t":"十山歌呈太守胡平一 其一","f":"七言绝句","c":["豺虎深交雁鹜行，到官管取汝无妨。","只将剽劫为喧闹，喝放归来尽陆梁。"]},{"t":"十月朝补种杏花","f":"七言绝句","c":["百株种杏自今春，度夏荣枯不解匀。","要看补栽新树子，荼糜红刺絓头巾。"]},{"t":"十里塘观鱼","f":"七言绝句","c":["银塘打尽万银梭，岸上笭箵来正多。","船载月明犹有月，无船无月欲如何。"]},{"t":"又和二绝句 其二","f":"七言绝句","c":["剪剪轻风未是轻，犹吹花片作红声。","一生情重嫌春浅，老去与春无点情。"]},{"t":"又和二绝句 其一","f":"七言绝句","c":["一冬寒不到深山，岂有春来更会寒。","幸自趁晴行脚好，却嫌沙入破鞋间。"]},{"t":"又和风雨二首 其一","f":"七言绝句","c":["东风未得颠如许，定被春光引得颠。","晚雨何妨略弹压，不应犹自借渠权。"]},{"t":"又和风雨二首 其二","f":"七言绝句","c":["风风雨雨又春穷，白白朱朱已眼空。","拚却老红一万点，换将新绿百千重。"]},{"t":"又和梅雨","f":"七言绝句","c":["管得天公雨更晴，何关客子病心情。","得归此意良不恶，且住微躯也自轻。"]},{"t":"又除夕绝句","f":"七言绝句","c":["紫陌相逢谁不客，青灯作伴未为孤。","何须家里作时节，只问旗亭有酒无。"]},{"t":"又题寺后竹亭","f":"七言绝句","c":["行尽空房忽画栏，竹光和月入亭寒。","壁间题字知谁句，醉把残灯子细看。"]},{"t":"万安出郭早行","f":"七言绝句","c":["玉花小朵是山矾，香杀行人只欲颠。","风掠水衣无处去，柳塘著在角头边。"]},{"t":"万安道中书事三首 其三","f":"七言绝句","c":["桃花薄相点燕脂，输与梨花雪作肌。","只有垂杨不脂粉，缕金铺翠衬腰支。"]},{"t":"万安道中书事三首 其二","f":"七言绝句","c":["携家满路踏春华，儿女欣欣不忆家。","骑吏也忘行役苦，一人人插一枝花。"]},{"t":"万安道中书事三首 其一","f":"七言绝句","c":["玉峰云剥逗斜明，花径泥乾得晚行。","细细一风寒里暖，时时数点雨中晴。"]},{"t":"万花川谷","f":"七言绝句","c":["无数花枝略说些，万花两字即非夸。","东山西畔南溪北，更没溪山只有花。"]},{"t":"三三径","f":"七言绝句","c":["三径初开自蒋卿，再开三径是渊明。","诚斋奄有三三径，一径花开一径行。"]},{"t":"三月二十七日送春绝句","f":"七言绝句","c":["只馀三日便清和，尽放春归莫恨他。","落尽千花飞尽絮，留春肯住欲如何。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其二","f":"七言绝句","c":["草藉轮蹄翠织成，花围巷陌锦帏屏。","早来指点游人处，今在游人行处行。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其一","f":"七言绝句","c":["暖轿行春底见春，遮栏春色不教亲。","急呼青伞小凉轿，又被春光著莫人。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其五","f":"七言绝句","c":["游人不是上坟回，便是清湍禊事来。","最苦相逢无处避，天禧寺及雨花台。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其四","f":"七言绝句","c":["天公也自喜良辰，上巳风光忽斩新。","点检一春好天色，更无两日似今晨。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其七","f":"七言绝句","c":["粉捏孩儿活逼真，象生果子更时新。","输赢一掷浑闲事，空手入城羞杀人。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其八","f":"七言绝句","c":["长干桥外即乌衣，今著屠沽卖菜儿。","晋殿吴宫犹碧草，玉亭谢馆尽黄鹂。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其三","f":"七言绝句","c":["淮山脚下大江横，御柳梢头绛阙明。","览尽山川更城郭，雨花台上太奇生。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其十","f":"七言绝句","c":["切忌寻春预作谋，教君行乐定成愁。","老夫乘兴翩然出，不遣风知雨觉休。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其九","f":"七言绝句","c":["除却钟山与石城，六朝遗迹问难真。","里名只道新名好，不道新名误后人。"]},{"t":"三月三日上忠襄坟因之行散得十绝句 其六","f":"七言绝句","c":["女唱儿歌去踏青，阿婆笑语伴渠行。","只亏郎罢优轻杀，櫑子双担挈酒瓶。"]},{"t":"三月三日雨作遣闷十绝句 其五","f":"七言绝句","c":["今年春事底匆匆，雨急风颠恼得侬。","不见一林如许笋，犹嫌三日向来风。"]},{"t":"三月三日雨作遣闷十绝句 其二","f":"七言绝句","c":["出门著雨不能归，借得青蓑著片时。","春染万花知了未，云偷千嶂忽何之。"]},{"t":"三月三日雨作遣闷十绝句 其三","f":"七言绝句","c":["归得茅斋松竹边，看风看雨亦欣然。","空檐知与阶何故，须把青苔滴似穿。"]},{"t":"三月三日雨作遣闷十绝句 其六","f":"七言绝句","c":["荒馀只怪不愁声，好语烦君细细听。","秧早不由田父懒，蚕迟端待柘阴成。"]},{"t":"三月三日雨作遣闷十绝句 其七","f":"七言绝句","c":["迟日何缘似个长，睡乡未苦怯茶枪。","春风解恼诗人鼻，非叶非花只是香。"]},{"t":"三月三日雨作遣闷十绝句 其九","f":"七言绝句","c":["报答春光酒一卮，贫中无酒著春欺。","作诗细与东风道，未必东风肯要诗。"]},{"t":"三月三日雨作遣闷十绝句 其一","f":"七言绝句","c":["行春莫放一日一，修禊仍逢三月三。","忍遣晴光作阴雨，更将急溅涴春衫。"]},{"t":"三月三日雨作遣闷十绝句 其八","f":"七言绝句","c":["村落寻花特地无，有花亦自只愁予。","不如卧听春山雨，一阵繁声一阵疏。"]},{"t":"三月三日雨作遣闷十绝句 其十","f":"七言绝句","c":["却是春残景更佳，诗人须记许生涯。","平田涨绿村村麦，嫩水浮红岸岸花。"]},{"t":"三月三日雨作遣闷十绝句 其四","f":"七言绝句","c":["旧与酴醾颇不疏，今春半朵未逢渠。","千花一雨俱红雨，问讯孤芳小住无。"]},{"t":"三月晦日","f":"七言绝句","c":["春光九十更三旬，暗准三旬赚杀人。","未到晓钟君莫喜，暮钟声里已无春。"]},{"t":"三月晦日闲步西园","f":"七言绝句","c":["岭南春去尽从伊，元自无花可得飞。","只有草花偏称意，强留蝴蝶不教归。"]},{"t":"三月晦日游越王台二首 其二","f":"七言绝句","c":["越王台上落花春，一掬山光两袖尘。","随分杯盘随处醉，自怜不及踏青人。"]},{"t":"三月晦日游越王台二首 其一","f":"七言绝句","c":["榕树梢头访古台，下看碧海一琼杯。","越王歌舞春风处，今日春风独自来。"]},{"t":"三江小渡","f":"七言绝句","c":["溪水将桥不复回，小舟犹倚短篙开。","交情得似山溪渡，不管风波去又来。"]},{"t":"三老董公","f":"七言绝句","c":["一色三军雪染衣，拔山气力陡然衰。","三王事业无多子，却是良平不得知。"]},{"t":"三衢登舟午睡","f":"七言绝句","c":["午思昏昏不肯醒，倦投竹枕睡难成。","晓然有梦疑非梦，听得人声及水声。"]},{"t":"上巳三首 其三","f":"七言绝句","c":["正是春光最盛时，桃花枝映李花枝。","鞦韆日暮人归尽，只有春风弄彩旗。"]},{"t":"上巳三首 其二","f":"七言绝句","c":["雨冷风酸数日强，老怀不可更禁当。","春寒幸自归将去，唤取重来是海棠。"]},{"t":"上巳三首 其一","f":"七言绝句","c":["上巳春阴政未开，寒窗愁坐冷于灰。","冻蝇触纸飞还落，仰面翻身起不来。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其七","f":"七言绝句","c":["湖上春游只爱晴，何朝何夕不晴明。","绝怜疏雨微云里，点缀湖山分外清。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其五","f":"七言绝句","c":["篮舆休上马休骑，湿却青鞋也不辞。","拣取雨丝疏处去，携筇且谒水仙祠。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其二","f":"七言绝句","c":["总宜亭子小如拳，著得西湖不见痕。","湖上轩窗无不好，何须抵死拣名园。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其三","f":"七言绝句","c":["孤山山后北山前，十里长堤隔两边。","一行垂杨绿无缝，石桥通处过春船。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其六","f":"七言绝句","c":["雨催杖屦却须回，捲上疏帘眼顿开。","十里湖光平似镜，柳梢梢外一船来。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其四","f":"七言绝句","c":["天色䰒松未肯收，吾侪自乐不曾愁。","随宜旋旋商量著，晴即闲行雨即休。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其九","f":"七言绝句","c":["今年山路少人来，酒肆萧然绮席埃。","政尔坐愁春寂寞，画船箫鼓忽如雷。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其十","f":"七言绝句","c":["岸上湖中各自奇，山觞水酌两皆宜。","只言游舫浑如画，身在画中元不知。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其八","f":"七言绝句","c":["凭久栏干可一杯，湖山飞入水中来。","多情燕子能相劝，舞破东风去却回。"]},{"t":"上巳同沈虞卿尤延之王顺伯林景思游湖上得十绝句呈同社 其一","f":"七言绝句","c":["鹄袍林里过芳辰，闻道春来不识春。","及至识春春已老，于中更老是诗人。"]},{"t":"上巳后一日同子文伯庄永年步东园三首 其三","f":"七言绝句","c":["只爱酴醾雪作葩，不知雪后减金沙。","春归道是无情著，试看游丝舞落花。"]},{"t":"上巳后一日同子文伯庄永年步东园三首 其二","f":"七言绝句","c":["九径阴阴一一穿，前谈后笑各欣然。","缓行不是身无力，满地残红不忍前。"]},{"t":"上巳后一日同子文伯庄永年步东园三首 其一","f":"七言绝句","c":["兄弟相过看牡丹，牡丹看了看东园。","攀翻花木来还去，九径还行十八番。"]},{"t":"上元日晚过顺溪","f":"七言绝句","c":["恰恰元宵雨脚垂，天风为我扫除之。","怪来平地寒如许，雪满远峰人未知。"]},{"t":"上元后一日往山庄访子仁中涂望见庄里李花二首 其二","f":"七言绝句","c":["李花十里纵长围，漏出桃花片子儿。","千丈越罗初水冻，中间一点涴燕脂。"]},{"t":"上元后一日往山庄访子仁中涂望见庄里李花二首 其一","f":"七言绝句","c":["庄里李花何似生，山头转处最分明。","轿中举首聊东望，不见花枝见雪城。"]},{"t":"上元前一日游东园看红梅三首 其三","f":"七言绝句","c":["儿牵黄犊父担犁，社鼓迎神簇纸旗。","不是丰年那得此，今春大胜去春时。"]},{"t":"上元后犹寒二首 其二","f":"七言绝句","c":["道是春工做物华，春工元自不由它。","杏花只作去年面，萱草别抽今岁芽。"]},{"t":"上元后犹寒二首 其一","f":"七言绝句","c":["雪后不妨寒较差，莫教一并放千花。","旧来池上金丝柳，新学江西鹰爪茶。"]},{"t":"上印有日代者未至","f":"七言绝句","c":["不是新人不肯来，天教老子小徘徊。","坐看桃李缤纷落，等得酴醾烂熳开。"]},{"t":"上岑水岭二首 其二","f":"七言绝句","c":["天上云泉脚下鸣，玉虹倒挂客心惊。","试教转落峰头石，衮到深溪作么声。"]},{"t":"上岑水岭二首 其一","f":"七言绝句","c":["危峰上面更危峰，特地无梯上碧空。","遥望白云生绝顶，如今身在白云中。"]},{"t":"上章戴滩","f":"七言绝句","c":["脱巾枕手仰哦诗，醉上诸滩总不知。","回看他船上滩苦，方知它看我船时。"]},{"t":"上濛悴滩","f":"七言绝句","c":["清江斜抱岭根来，暗石冲波却倒回。","幸自琉璃青一片，落滩碎作雪花堆。"]},{"t":"下鸡鸣山诸滩望柯山不见三首 其三","f":"七言绝句","c":["却忆归舟是去年，上滩浑似上青天。","诸滩知我怀馀怨，急送秋风下水船。"]},{"t":"下鸡鸣山诸滩望柯山不见三首 其二","f":"七言绝句","c":["莫怯诸滩水怒号，下滩不似上滩劳。","长年三老无多巧，稳送惊湍只一篙。"]},{"t":"下鸡鸣山诸滩望柯山不见三首 其一","f":"七言绝句","c":["地近莲花江渐深，一滩一过快人心。","贪看下水船如箭，失却柯山无处寻。"]},{"t":"下横山滩头望金华山四首 其四","f":"七言绝句","c":["玉立金华霄汉间，帝封天女锡仙山。","被他走下严滩去，一水穷追竟不还。"]},{"t":"下横山滩头望金华山四首 其三","f":"七言绝句","c":["道是兰溪水较宽，兰溪欲到怪生难。","后船只羡前船快，不觉前船阁在滩。"]},{"t":"下横山滩头望金华山四首 其二","f":"七言绝句","c":["山思江情不负伊，雨姿晴态总成奇。","闭门觅句非诗法，只是征行自有诗。"]},{"t":"下横山滩头望金华山四首 其一","f":"七言绝句","c":["篙师只管信船流，不作前滩水石谋。","却被惊湍漩三转，倒将船尾作船头。"]},{"t":"与子上野步","f":"五言绝句","c":["篱落深深巷，茅茨小小家。","冬晴好行脚，何处不梅花。"]},{"t":"与子仁登天柱冈过胡家塘莼塘归东园四首 其四","f":"七言绝句","c":["厌看家园桃李春，踏青行遍四山村。","芳菲看尽还归看，看得园花特地新。"]},{"t":"与子仁登天柱冈过胡家塘莼塘归东园四首 其三","f":"七言绝句","c":["数间茅屋傍山根，一队儿童出竹门。","只爱行穿杨柳渡，不知失却李花村。"]},{"t":"与子仁登天柱冈过胡家塘莼塘归东园四首 其二","f":"七言绝句","c":["胡床脚底万峰寒，拄杖锥尖乱藓斑。","天柱冈头行未饱，相携更上一重山。"]},{"t":"与子仁登天柱冈过胡家塘莼塘归东园四首 其一","f":"七言绝句","c":["嫩晴无日也无风，政是春光酒样醲。","行到中峰元未觉，回头已度打头峰。"]},{"t":"与山庄子仁侄东园看梅四首 其一","f":"七言绝句","c":["仰树看花不见梅，闻香疑在别园开。","更行数步偶回首，却被青松映出来。"]},{"t":"与山庄子仁侄东园看梅四首 其二","f":"七言绝句","c":["梅花不是雪家仙，雪里如何不怕寒。","冻脱龙髯冰却海，千花试与斗来看。"]},{"t":"与刘景明晚步","f":"七言绝句","c":["行尽南溪溪北涯，李花看了看桃花。","归来倦卧呼童子，旋煮山泉瀹建茶。"]},{"t":"与次公夜酌","f":"七言绝句","c":["汤盂深浅任横斜，酒力微醺略减些。","剪烛小童殊解事，不留烛烬却留花。"]},{"t":"与伯勤子文幼楚同登南溪奇观戏道傍群儿","f":"七言绝句","c":["䰒松睡眼熨难开，曳杖缘溪啄紫苔。","偶见群儿聊与戏，布衫青底捉将来。"]},{"t":"久雨小霁东园行散","f":"七言绝句","c":["雨寒两月勒春迟，初喜云间漏霁晖。","道是攀花无雨点，忽然放手溅人衣。"]},{"t":"久病小愈雨中端午试笔四首 其一","f":"七言绝句","c":["病较欣逢五五辰，宫衣忽忆拜天恩。","旧时叠雪含风眼，今看空山雨点痕。"]},{"t":"之官五羊过太和县登快阁观山谷石刻赋两绝句呈知县李绅公垂主簿赵蕃昌父 其二","f":"七言绝句","c":["庐陵山水说西昌，天遣金华印此邦。","诗本道他将取去，如何遗下一澄江。"]},{"t":"之官五羊过太和县登快阁观山谷石刻赋两绝句呈知县李绅公垂主簿赵蕃昌父 其一","f":"七言绝句","c":["阁中陈迹故依然，欲问风流已百年。","南岸一峰东一塔，自言曾识老诗仙。"]},{"t":"大儿长孺同罗时清寻凉盐桥","f":"七言绝句","c":["灯火希疏夜向中，追凉只与热相逢。","意行行到新桥上，两岸无人四面风。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其四","f":"七言绝句","c":["船开便与世尘疏，飘若乘风度太虚。","坐上偶然遗饼饵，波间无数出龟鱼。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其一","f":"七言绝句","c":["凤城鱼钥晓开银，国子先生领搢绅。","山水光中金凿落，芙蕖香里葛头巾。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其三","f":"七言绝句","c":["岸岸园亭傍水滨，裴园飞入水心横。","旁人莫问游何许，只拣荷花闹处行。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其六","f":"七言绝句","c":["小泛西湖六月船，船中人即水中仙。","外铺云锦千弓地，中度琉璃百摺天。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其八","f":"七言绝句","c":["故人京尹剧风流，走送厨珍佐胜游。","青李来禽沈冰雪，黄金白璧斫蝤蛑。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其五","f":"七言绝句","c":["西湖旧属野人家，今属天家不属他。","水月亭前且杨柳，集芳园下尽荷花。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其十","f":"七言绝句","c":["游尽西湖赏尽莲，玉壶落日泊楼船。","莫嫌当处荷花少，剩展湖光几镜天。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其九","f":"七言绝句","c":["人间暑气正如炊，上了湖船便不知。","湖上四时无不好，就中最说藕花时。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其二","f":"七言绝句","c":["小步深登野寺幽，古松将影入茶瓯。","铃声忽起九天半，有塔危峰最上头。"]},{"t":"大丞相益国周公访予于碧瑶洞天刘敏叔写以为图求予书其后","f":"七言绝句","c":["平叔曾过魏秀才，何如老子致元台。","苍松翠竹青苔径，也不传呼宰相来。"]},{"t":"子上持豫章画扇其上牡丹三株黄白相间盛开一猫将二子戏其旁","f":"七言绝句","c":["暄风暖景政春迟，开尽好花人未知。","输与狸奴得春色，牡丹香里弄双儿。"]},{"t":"子年刘郎写余老貌求赞","f":"五言绝句","c":["鬓少梳欲无，髭短镊更少。","搔鬓祗撚髭，觅句何日了。"]},{"t":"小立净远亭","f":"五言绝句","c":["清景无终极，频来未属厌。","远山秋后出，茅屋近来添。"]},{"t":"小池","f":"七言绝句","c":["泉眼无声惜细流，树阴照水爱晴柔。","小荷才露尖尖角，早有蜻蜓立上头。"]},{"t":"小舟晚兴四首 其四","f":"七言绝句","c":["一船在后忽搀前，前后篙师各粲然。","山入春来肥更秀，向人依旧耸寒肩。"]},{"t":"小舟晚兴四首 其三","f":"七言绝句","c":["潮痕初落水犹肥，雨点才来已复微。","半湿岸沙危欲落，牵船稚子去如飞。"]},{"t":"小舟晚兴四首 其二","f":"七言绝句","c":["人在非晴非雨天，船行不浪不风间。","坐来堪喜还堪恨，看得南山失北山。"]},{"t":"小饮俎豆颇备江西淮浙之品戏题二首 其二","f":"词","c":["味含霜气洞庭柑，鲊带桃花楚水?。","春暖著人君会否，不教淮白过江南。"]},{"t":"小饮俎豆颇备江西淮浙之品戏题二首 其一","f":"七言绝句","c":["满盘山海眩芳珍，未借前筹已咽津。","鲎酱子鱼总佳客，玉狸黄雀是乡人。"]},{"t":"小泊英洲二首 其二","f":"七言绝句","c":["数家草草劣无多，跕水飞鸢也不过。","道是荒城斗来大，向来此地著东坡。"]},{"t":"小泊英洲二首 其一","f":"七言绝句","c":["人人藤叶嚼槟榔，户户茅檐覆土床。","只有春风不寒乞，隔溪吹度柚花香。"]},{"t":"小泊梅堰登明孝寺","f":"七言绝句","c":["泊船梅堰日微升，一径深深唤我登。","随分垂杨兼老桧，备员野寺更残僧。"]},{"t":"小泊新丰市","f":"七言绝句","c":["也知小倦泊楼船，何苦争先柳岸边。","须把碧篙摇绿净，舟人不惜水中天。"]},{"t":"小雨","f":"七言绝句","c":["雨来细细复疏疏，纵不能多不肯无。","似妒诗人山入眼，千峰故隔一帘珠。"]},{"t":"小雨","f":"七言绝句","c":["雨才放脚又还无，叶上萧萧半霎馀。","贮得千珠无点漏，丝窠元自不胜疏。"]},{"t":"小斋晚兴","f":"七言绝句","c":["不会邻家养鸽儿，清晨齐放晚齐归。","网丝到处萦人鬓，欲打蜘蛛拣最肥。"]},{"t":"小桃","f":"七言绝句","c":["小桃著子可怜渠，疏处全疏无处无。","并缀一梢三十颗，缒枝欲折没人扶。"]},{"t":"小瓶梅花","f":"七言绝句","c":["梅萼才开已乱飞，不堪雨打更风吹。","萧萧只隔窗间纸，瓶里梅花总不知。"]},{"t":"小酌","f":"五言绝句","c":["酒入春逾劲，天寒烛始明。","偶然倾一盏，政尔忽三更。"]},{"t":"小集食藕极嫩","f":"五言绝句","c":["比雪犹松在，无丝可得飘。","轻拈愁欲碎，未嚼已先销。"]},{"t":"小楼晚眺云日","f":"七言绝句","c":["小楼挂上绿窗棂，落日孤云万态生。","碧玉峰峦白银缘，峰峦暗处缘偏明。"]},{"t":"小溪至新田四首 其四","f":"七言绝句","c":["懊恼春光欲断肠，来时长缓去时忙。","落红满路无人惜，踏作花泥透脚香。"]},{"t":"小溪至新田四首 其三","f":"七言绝句","c":["晚云解事忽离披，放出千峰特地奇。","欲拣一峰谁子是，总如笔未退尖时。"]},{"t":"小溪至新田四首 其二","f":"七言绝句","c":["只爱孤峰惹寸云，忽惊头上雨翻盆。","北来南去缘何事，路上君看屐子痕。"]},{"t":"小溪至新田四首 其一","f":"七言绝句","c":["人烟懡㦬不成村，溪水微茫劣半分。","流到前滩忙似箭，不容雨点稍成纹。"]},{"t":"小滩三首 其三","f":"七言绝句","c":["船里征人政念归，居人来看却嗟咨。","居人祗羡征人著，世世安生不自知。"]},{"t":"小醉折梅","f":"七言绝句","c":["死爱花枝不忍吹，醉来恣意折芳菲。","鬓边插得梅花满，更撚南枝满把归。"]},{"t":"小憩栟楮","f":"七言绝句","c":["笋舆放下倦腾腾，睡倚胡床撼不应。","榉柳细花吹面落，误挥团扇扑飞蝇。"]},{"t":"小憩揭家冈谛观桐阴","f":"七言绝句","c":["仰看阳光只见空，不如影里看梧桐。","莫言日脚无行迹，偷转零分破寸中。"]},{"t":"山云","f":"七言绝句","c":["春从底处领云来，日日山头絮作堆。","恋著好峰那肯去，欲开犹绕两三回。"]},{"t":"山庄李花","f":"七言绝句","c":["山庄又报李花秾，火急来看细雨中。","除却断肠千树雪，别无春恨诉东风。"]},{"t":"山行","f":"七言绝句","c":["山行两日厌荒凉，田少山多多更长。","一望不曾亏碧草，半分何似借青秧。"]},{"t":"山居午睡起弄花三首 其三","f":"七言绝句","c":["浸得荷花水一盆，将来洗面漱牙根。","凉生须鬓香生颊，沉麝龙涎却是村。"]},{"t":"山居午睡起弄花三首 其二","f":"七言绝句","c":["数片荷花漾水盆，忽然相聚忽然分。","从教压捺沉盆底，依旧浮来无水痕。"]},{"t":"山居午睡起弄花三首 其一","f":"七言绝句","c":["五年出仕喜还家，双桂成阴不阙些。","午睡起来无理会，银盆清水弄荷花。"]},{"t":"山居雪后二首 其二","f":"七言绝句","c":["一点红尘未敢生，松间雪后政堪行。","日光半破风微度，时作高林落果声。"]},{"t":"山居雪后二首 其一","f":"七言绝句","c":["春近能馀几许寒，雪花才落便销残。","青松梢上兰根下，犹得三朝两日看。"]},{"t":"山店松声二首 其二","f":"七言绝句","c":["松本无声风亦无，适然相值两相呼。","非金非石非丝竹，万顷云涛殷五湖。"]},{"t":"山店松声二首 其一","f":"七言绝句","c":["脩涂残暑仆夫劳，午憩茅檐尺许高。","忽有凉风飒然起，小松呼舞大松号。"]},{"t":"已至湖尾望见西山三首 其三","f":"七言绝句","c":["千里都无半点山，如何敢望有人烟。","不教远树遮拦却，芦荻生来直到天。"]},{"t":"已至湖尾望见西山三首 其二","f":"七言绝句","c":["芦荻中间一港深，蒌蒿如柱不成簪。","正愁半日无村落，远有人家在树林。"]},{"t":"已至湖尾望见西山三首 其一","f":"七言绝句","c":["好风稳送五湖船，万顷银涛半霎间。","已入江西犹未觉，忽然对面是西山。"]},{"t":"已过吴江阻风上湖口二首 其二","f":"七言绝句","c":["南风捲水入湖去，落尽波痕不复回。","更被纲船碍归舫，一船过尽一船来。"]},{"t":"已过吴江阻风上湖口二首 其一","f":"七言绝句","c":["五日姑苏一醉中，醉中看尽牡丹红。","阻风只怕松江渡，过了松江却阻风。"]},{"t":"己未春日山居杂兴十二解 其十一","f":"七言绝句","c":["半晴半雨半暄凉，拖带春光未要忙。","为报州家兼县里，吾乡改作万花乡。"]},{"t":"己未春日山居杂兴十二解 其四","f":"七言绝句","c":["百舌殷勤报晓晴，花梢做出百般声。","饶渠学遍山禽语，至竟何曾学得莺。"]},{"t":"己未春日山居杂兴十二解 其十二","f":"七言绝句","c":["一春两脚滞东园，柳绊花牵不暂闲。","今日酽晴天气好，杖藜看水更看山。"]},{"t":"己未春日山居杂兴十二解 其五","f":"七言绝句","c":["海棠重叶更妖斜，青帝翻腾别一家。","格外出奇人不识，大红抹利小莲花。"]},{"t":"己未春日山居杂兴十二解 其三","f":"七言绝句","c":["海棠雨后不胜佳，子细看来不是花。","西子织成新样锦，清晨濯出锦江霞。"]},{"t":"己未春日山居杂兴十二解 其一","f":"七言绝句","c":["今岁春迟雨亦然，生愁无水打秧田。","不消三日如麻脚，线样溪流浪拍天。"]},{"t":"己未春日山居杂兴十二解 其六","f":"七言绝句","c":["春寒偏勒牡丹迟，晚似常年半月期。","上巳清明同一日，那时恰好放花枝。"]},{"t":"己未春日山居杂兴十二解 其八","f":"七言绝句","c":["金作林檎花绝秾，十年花少怨东风。","即今遍地栾枝锦，不则梢头几点红。"]},{"t":"己未春日山居杂兴十二解 其十","f":"七言绝句","c":["日影云光学镀金，好风不肯碎花阴。","人言春色醲于酒，不醉衰容只醉心。"]},{"t":"己未春日山居杂兴十二解 其七","f":"七言绝句","c":["手种花王五百窠，半来枯瘁半萌芽。","东风未要都开了，每日教开三两花。"]},{"t":"己未春日山居杂兴十二解 其二","f":"七言绝句","c":["半月春晴探物华，山园走得脚酸麻。","从教三日风和雨，闭户烧香不看花。"]},{"t":"己未春日山居杂兴十二解 其九","f":"七言绝句","c":["寒久花迟也大奇，雨膏饱足土膏肥。","牡丹芍药君须记，管取花房二尺围。"]},{"t":"不寐","f":"七言绝句","c":["脚底神通也自强，三更报我有飞霜。","人言冬夜长如岁，不寐方知岁未长。"]},{"t":"不寐听雨","f":"七言绝句","c":["雨到中宵寂不鸣，只闻风拂树梢轻。","瓦沟收拾残零水，并作檐间一滴声。"]},{"t":"不睡四首 其四","f":"七言绝句","c":["眊氉浑如病起初，冬烘又似酒醒馀。","睡乡幸有闲田地，不放诗人僦一居。"]},{"t":"不睡四首 其三","f":"七言绝句","c":["清愁无数暗相随，酒是渠雠也是媒。","醉里不知何处亸，等人醒后一时来。"]},{"t":"不睡四首 其二","f":"七言绝句","c":["望后更深月未明，暗蛩冻得总无声。","闲心幸自清如水，万感还从不睡生。"]},{"t":"不睡四首 其一","f":"七言绝句","c":["夜永无眠非为茶，无风灯影自横斜。","拥裯仰面书帷薄，数尽承尘一簟花。"]},{"t":"中元日早起","f":"七言绝句","c":["欲借微凉问万松，万松自热诉无风。","清晨秋暑已如许，那更斜阳与日中。"]},{"t":"中和节日步东园三首 其三","f":"七言绝句","c":["一年佳节又中和，三分春光一已过。","莫恨峭寒花较晚，留连春色尽从他。"]},{"t":"中和节日步东园三首 其二","f":"七言绝句","c":["五出桃花千叶绯，团栾绕树问芳菲。","攀来欲折还休去，看到残红教自飞。"]},{"t":"中和节日步东园三首 其一","f":"七言绝句","c":["两晨又不到东园，沙径朝来合小乾。","可惜红梅将落去，怕风怕雨不来看。"]},{"t":"中秋无月既望月甚佳二首 其二","f":"七言绝句","c":["月到中秋故故无，今宵月好莫渠孤。","旧传月径圜千里，影落金杯只粒珠。"]},{"t":"中秋无月既望月甚佳二首 其一","f":"七言绝句","c":["中秋无月莫尤天，月入秋来夜夜妍。","且道今宵明月色，何曾减却半分圜。"]},{"t":"中秋无月宿青弋江晓行新寒","f":"七言绝句","c":["新寒催我索衣裘，凉雨凄云总是愁。","耐冷素娥今老去，夜来桂殿罢中秋。"]},{"t":"中秋前二夕钓雪舟中静坐二首 其二","f":"七言绝句","c":["去岁中秋政病馀，爱它月色强支吾。","今年老矣差无病，后夜中秋有月无。"]},{"t":"中秋前二夕钓雪舟中静坐二首 其一","f":"七言绝句","c":["月到南窗小半扉，无灯始觉室生辉。","人间何处冰壶是，身在冰壶却道非。"]},{"t":"为崇辨法沄师作林野二大字","f":"七言绝句","c":["天下何人不爱官，弃官出世古今难。","向来一觉钧天梦，便作林居野处看。"]},{"t":"乌臼烛","f":"七言绝句","c":["焰白光寒泪亦收，臼灯十倍蜜灯休。","忘情也似诚斋叟，烧尽心时不泪流。"]},{"t":"乌祈酒二首 其二","f":"七言绝句","c":["毛永乌祈山两崖，家家酒肆向江开。","也知第一蒲萄色，只问米从何处来。"]},{"t":"乌祈酒二首 其一","f":"七言绝句","c":["入到严州不识田，一江两岸万青山。","乌祈酒味君休问，费尽江波卖尽钱。"]},{"t":"乌贼鱼","f":"七言绝句","c":["秦帝东巡渡浙江，中流风紧坠书囊。","至今收得磨残墨，犹带宫车载鲍香。"]},{"t":"书孙公谈圃谈圃载子由为黄白术将举火一猫据炉而溺须臾不见","f":"七言绝句","c":["少许丹砂和水银，鍊成紫磨赚痴人。","颍滨莫笑狸奴著，却恐狸奴笑颍滨。"]},{"t":"书斋夜坐二首 其二","f":"七言绝句","c":["酒力欺人正作眠，梦中得句忽醒然。","寒生更点当当里，雨在梅花蔌蔌边。"]},{"t":"书斋夜坐二首 其一","f":"七言绝句","c":["棐几吹灯丈室虚，隔窗雨点响阶除。","胡床枕手昏昏著，卧听儿童读汉书。"]},{"t":"云际寺前山顶却望幡竿鹧鸪诸山二首 其二","f":"七言绝句","c":["远近青山列画屏，近山浓抹远山轻。","高屏已出低屏外，更有孤峰出一层。"]},{"t":"云际寺前山顶却望幡竿鹧鸪诸山二首 其一","f":"七言绝句","c":["幡竿岭带鹧鸪山，雪后霜前紫翠间。","自掇胡床移好处，莫教漏眼一烟鬟。"]},{"t":"云际院小池荷花才落一叶急承之","f":"七言绝句","c":["欲落荷花先自愁，如何落后免沉浮。","谁将碧玉圆盘子，和蕊和花一一收。"]},{"t":"五月十六夜病中无聊起来步月五首 其五","f":"七言绝句","c":["道是月明星便稀，阿瞒此句未为奇。","今宵斗柄也不见，一镜孤光天四垂。"]},{"t":"五月十六夜病中无聊起来步月五首 其四","f":"七言绝句","c":["夏日虽炎夜却清，四更还更胜三更。","露从玉兔须根落，风在银河浪底生。"]},{"t":"五月十六夜病中无聊起来步月五首 其三","f":"七言绝句","c":["人睡方酣鸡未知，起来叫转月华西。","南风吹落北斗柄，细数月中丹桂枝。"]},{"t":"五月十六夜病中无聊起来步月五首 其二","f":"七言绝句","c":["无求不必位三公，一饱何须禄万钟。","只有人生安乐好，享它明月与清风。"]},{"t":"五月十六夜病中无聊起来步月五首 其一","f":"七言绝句","c":["抛官放浪十三年，底事今年病懒残。","旧健肯饶梅摘索，新羸翻羡竹平安。"]},{"t":"元举叔莲花","f":"七言绝句","c":["不著芙蓉近路栽，菰蒲深处却花开。","晚香特地清人骨，多谢西风得得来。"]},{"t":"六月九日晓登连天观","f":"七言绝句","c":["小立层台岸幅巾，除莺作伴更无人。","晓风草草君知么，不为高荷惜水银。"]},{"t":"六月二十三日立秋","f":"七言绝句","c":["暑中剩喜立秋初，特地西风半点无。","旋汲井花浇睡眼，洒将荷叶看跳珠。"]},{"t":"六月六日小集二首 其二","f":"七言绝句","c":["新蝉声涩亦无多，强与娇莺和好歌。","尽日舞风浑不倦，无人奈得柳条何。"]},{"t":"六月六日小集二首 其一","f":"七言绝句","c":["青李来禽已眼明，新瓜入夏见何曾。","酒边忘却人间暑，消尽金盆一丈冰。"]},{"t":"六月喜雨三首 其三","f":"七言绝句","c":["今年不是雨来悭，不后秧时亦不前。","自古浙西长苦涝，近来无涝恰三年。"]},{"t":"六月喜雨三首 其二","f":"七言绝句","c":["玄云直下素光开，雨到前山只恐回。","霹雳一声风一阵，为侬催上半天来。"]},{"t":"六月喜雨三首 其一","f":"七言绝句","c":["守臣两月祷山川，诏旨才颁便沛然。","不是格天缘诏旨，忧民天子本如天。"]},{"t":"分宜逆旅逢同郡客子","f":"七言绝句","c":["在家儿女亦心轻，行路逢人总弟兄。","未问后来相忆否，其如临别不胜情。"]},{"t":"午过横林回望惠山二首 其二","f":"七言绝句","c":["雪馀官路已生尘，犹喜长河水稍深。","恨杀惠山寻不见，忽然追我到横林。"]},{"t":"午过横林回望惠山二首 其一","f":"七言绝句","c":["道是冰销快水程，不知青女解藏冰。","芦花多处竹阴底，砌作瑶堤不计层。"]},{"t":"午坐卧治斋","f":"七言绝句","c":["雨后朝阴到午晴，空斋孤坐纳秋清。","一蝉也解怜幽寂，柳外飞来叶底鸣。"]},{"t":"午热登多稼亭五首 其五","f":"七言绝句","c":["御风不必问雌雄，只有炎风最不中。","却是竹君殊解事，炎风筛过作清风。"]},{"t":"午热登多稼亭五首 其四","f":"七言绝句","c":["柳外花边忽飒然，好风一点破愁颜。","岸巾独倚千寻树，闲看南云度北山。"]},{"t":"午热登多稼亭五首 其三","f":"七言绝句","c":["不是城中是甑中，雨馀日色更明红。","若为飞上金山顶，独立长江万里风。"]},{"t":"午热登多稼亭五首 其二","f":"七言绝句","c":["芒鞋葵扇颇萧然，倦倚胡床不是眠。","避暑无藏身去处，追凉行尽竹旁边。"]},{"t":"午热登多稼亭五首 其一","f":"七言绝句","c":["矮屋炎天不可居，高亭爽气亦元无。","小风不被蝉餐却，合有些凉到老夫。"]},{"t":"午睡闻子规","f":"七言绝句","c":["睡眼䰒松未爽时，一声杜宇顿开眉。","不须报道思归乐，今我真归不用思。"]},{"t":"午憩二首 其二","f":"七言绝句","c":["晴边雨后麦秋时，风色轻轻日色微。","已隔深溪仍蘸水，却教人折野蔷薇。"]},{"t":"午憩二首 其一","f":"七言绝句","c":["嫩绿桐阴夹道遮，烂红野果压枝斜。","日烘细草香无价，况有三枝两朵花。"]},{"t":"双峰定水璘老送木犀香五首 其二","f":"五言绝句","c":["万杵黄金屑，九烝碧梧骨。","诗老坐雪窗，天香来月窟。"]},{"t":"双峰定水璘老送木犀香五首 其一","f":"五言绝句","c":["春得鄞江信，香从定水来。","今年有奇事，正月木犀开。"]},{"t":"壬子正月四日后圃行散四首 其四","f":"七言绝句","c":["传语春光恰好秾，太秾恐怕恼衰翁。","日华五色无寻处，只在蛛丝来去中。"]},{"t":"壬子正月四日后圃行散四首 其三","f":"七言绝句","c":["双鹊营巢浪苦辛，拣条衔折不辞频。","旧条老硬新条韧，却向篱根拾落薪。"]},{"t":"壬子正月四日后圃行散四首 其二","f":"七言绝句","c":["勃姑偶下小梅枝，要看渠侬褐锦衣。","柱后藏身教不见，却因不见转惊飞。"]},{"t":"壬子正月四日后圃行散四首 其一","f":"七言绝句","c":["淡日微舒又急收，兜罗绵隔紫灯毬。","更将数点无声雨，不湿人衣却湿头。"]},{"t":"壬戌人日南溪暮景三首 其三","f":"七言绝句","c":["翡翠惊飞不作行，沙鸥乱下自成双。","一天霞绮沉波底，便是西川濯锦江。"]},{"t":"壬戌人日南溪暮景三首 其二","f":"七言绝句","c":["春暖溪暄出小鱼，沉浮上下巧相娱。","一跳一浪钱来大，开作瑶环忽丈馀。"]},{"t":"壬戌人日南溪暮景三首 其一","f":"七言绝句","c":["坐看青天起白云，化成龙子钑银鳞。","霎时塞得青天满，只见龙鳞不见身。"]},{"t":"壬辰别头胡元伯丞公折双梅见赠作一绝以谢之","f":"七言绝句","c":["一花怪结双青子，独蒂还藏两玉花。","薄相春工宁底巧，眼明初见雪枝斜。"]},{"t":"无题","f":"七言绝句","c":["坐看胡孙上树头，旁人只恐堕深沟。","渠侬狡狯何须教，说与旁人莫浪愁。"]},{"t":"月下果饮七首 其七","f":"七言绝句","c":["人静更深丈室虚，欲眠聊复小踟蹰。","竹床最冷也成热，羽扇不凉差胜无。"]},{"t":"月下果饮七首 其六","f":"七言绝句","c":["斜斜花影欲愁予，唧唧虫声亦爱渠。","月与诗人元不薄，侬于欢伯未应疏。"]},{"t":"月下果饮七首 其五","f":"七言绝句","c":["坐久轻云次第开，月光飞入酒杯来。","今宵只有半边月，一半桂枝何处栽。"]},{"t":"月下果饮七首 其四","f":"七言绝句","c":["月初生处薄云生，到得云销月政明。","两处打更如一处，二更还作四更声。"]},{"t":"月下果饮七首 其三","f":"七言绝句","c":["一年遇暑一番愁，六月梢时七月头。","今夕追凉还得热，何时遇夏却逢秋。"]},{"t":"月下果饮七首 其二","f":"七言绝句","c":["酒边无物伴长瓶，一颗新莲一段冰。","月下不风终是爽，烛光何罪也堪憎。"]},{"t":"月下梅花","f":"七言绝句","c":["天恐梅花不耐寒，遣将孤月问平安。","未须一夜都开尽，留取前前后后看。"]},{"t":"月中炬火发仙山驿小睡射亭五首 其五","f":"七言绝句","c":["轿中兀得软如痴，逢店投床片子时。","睡觉不知天晓未，半窗花影木犀枝。"]},{"t":"月中炬火发仙山驿小睡射亭五首 其四","f":"七言绝句","c":["长庚初让月先行，不料姮娥也世情。","趣驾冰轮渡银浦，乱抛玉李掷长庚。"]},{"t":"月中炬火发仙山驿小睡射亭五首 其三","f":"七言绝句","c":["月轮已落尚残光，一似西山没夕阳。","次第长庚都落去，日华犹未出扶桑。"]},{"t":"月中炬火发仙山驿小睡射亭五首 其二","f":"七言绝句","c":["踏月何销秉炬行，也防月落未天明。","果然留下长庚去，更赚行人作晓星。"]},{"t":"月中炬火发仙山驿小睡射亭五首 其一","f":"七言绝句","c":["道是宵征即晓光，若言明发未朝阳。","月华露气山兼水，享尽人间第一凉。"]},{"t":"日午","f":"七言绝句","c":["揭竿借日自烘衣，背立晴暄片子时。","雪后春生人未觉，弄丝蟢子独先知。"]},{"t":"月夜观雪三首 其三","f":"七言绝句","c":["月色还将雪色同，雪光却与月光通。","都将大地作月窟，仍榜碧天名雪宫。"]},{"t":"月夜观雪三首 其二","f":"七言绝句","c":["月光雪色两清寒，见月初疑是雪团。","看得雪光还似月，元来雪月一般般。"]},{"t":"月夜观雪三首 其一","f":"七言绝句","c":["仙人爱雪不嫌寒，挈月来看夜不眠。","游遍琼楼霜欲晓，却将玉镜挂青天。"]},{"t":"月夜散策县圃有飞蝶仍闻笛声","f":"七言绝句","c":["月明未许人早睡，笛声解与秋争清。","夜深不应有飞蝶，渠侬似欲伴人行。"]},{"t":"木犀","f":"七言绝句","c":["天将秋气蒸寒馥，月借金波滴小黄。","不会溪堂老居士，更谈桂子是天香。"]},{"t":"木犀二绝句 其一","f":"七言绝句","c":["只道秋花艳未强，此花尽更有商量。","东风染得千红紫，曾有西风半点香。"]},{"t":"木犀二绝句 其二","f":"七言绝句","c":["轻薄西风未办霜，夜揉黄雪作秋光。","吹残六出犹馀四，匹似天花更著香。"]},{"t":"木犀芙蓉盛开","f":"七言绝句","c":["先生深住万山村，雾裹云包不见痕。","也被闲人知去处，芙蓉巷里木犀门。"]},{"t":"木犀落尽有感二首 其二","f":"七言绝句","c":["姮娥收去广寒秋，太息花中无此流。","花品已高香更绝，却缘韵胜得清愁。"]},{"t":"木犀落尽有感二首 其一","f":"七言绝句","c":["一岁秋香又一空，落英憔悴怨西风。","开时占断西风晓，岂念荷花脱病红。"]},{"t":"水中山花影","f":"七言绝句","c":["闭轿那知山色浓，山花影落水田中。","水中细数千红紫，点对山花一一同。"]},{"t":"水仙花四首 其四","f":"五言绝句","c":["开处谁为伴，萧然不可亲。","雪宫孤弄影，水殿四无人。"]},{"t":"水仙花四首 其三","f":"五言绝句","c":["韵绝香仍绝，花清月未清。","天仙不行地，且借水为名。"]},{"t":"水仙花四首 其二","f":"七言绝句","c":["额间拂杀御袍黄，衣上偷将月姊香。","待倩春风作媒却，西湖嫁与水仙王。"]},{"t":"水仙花四首 其一","f":"七言绝句","c":["江妃虚却蕊珠宫，银汉仙人谪此中。","偶趁月明波上戏，一身冰雪舞春风。"]},{"t":"水沤二首 其二","f":"七言绝句","c":["至宝何缘识得全，骊珠浮没只俄然。","金仙额上庄严底，只许凡人见半边。"]},{"t":"水沤二首 其一","f":"七言绝句","c":["淡日轻云雨点疏，大沤随雨起清渠。","跳来走去琼盘里，创见龙宫径寸珠。"]},{"t":"水纹二首 其二","f":"五言绝句","c":["初作眉头皱，还成簟面斑。","小风来不住，织遍一池间。"]},{"t":"水纹二首 其一","f":"五言绝句","c":["池面尖风起，烟痕一拂微。","无形还有影，掠水去如飞。"]},{"t":"水落二首 其二","f":"七言绝句","c":["轻寒瑟瑟入船中，闭却船门下却篷。","要得新晴江水落，不应更恨打头风。"]},{"t":"水落二首 其一","f":"七言绝句","c":["桑椹垂红似荔支，荻芽如臂与人齐。","夜来水落知深浅，看取芭蕉五尺泥。"]},{"t":"火阁午睡起负暄二首 其二","f":"七言绝句","c":["黄菊霜枝已懒残，瑞香紫笋政团栾。","盆池影里看题壁，上字还成下字看。"]},{"t":"火阁午睡起负暄二首 其一","f":"七言绝句","c":["火阁红销雪尚香，睡魔引我入渠乡。","觉来一阵寒无柰，自掇胡床负太阳。"]},{"t":"王式之命刘秀才写予真因署其上","f":"七言绝句","c":["浙水东兼浙水西，千岩万壑总遨嬉。","游山祗欠金华债，乘兴今随王式之。"]},{"t":"瓦店雨作四首 其四","f":"七言绝句","c":["近岸人家欲闭门，远林烟树半昏昏。","鸬鹚白鹭归何晚，今夜定投何处村。"]},{"t":"瓦店雨作四首 其三","f":"七言绝句","c":["诗人长怨没诗材，天遣斜风细雨来。","领了诗材还又怨，问天风雨几时开。"]},{"t":"瓦店雨作四首 其二","f":"七言绝句","c":["天嫌平野树分明，便恐丹青画得成。","收入晚风烟雨里，自将水墨替丹青。"]},{"t":"瓦店雨作四首 其一","f":"七言绝句","c":["斜风吹雨打船窗，一阵疏来一阵忙。","听作山斋声点滴，不知作客在山阳。"]},{"t":"风定过垂虹亭","f":"七言绝句","c":["松江未过不胜愁，过了垂虹百不忧。","忽见石湖山上塔，定知塔背是苏州。"]},{"t":"丙辰岁朝行东园","f":"七言绝句","c":["元日扶衰看早春，嫩苔一径落梅新。","何人舞罢凌波袜，踏匾真珠满绿絪。"]},{"t":"东园社日","f":"七言绝句","c":["风雨摧残桃李枝，东园无树不离披。","海棠过后残花在，恰似上春初发时。"]},{"t":"东园探桃李二首 其二","f":"七言绝句","c":["有花无叶也孤寒，有叶无花草一般。","最是桃花饶态度，醉红娇绿恼人看。"]},{"t":"东园探桃李二首 其一","f":"七言绝句","c":["偶逢李径一花开，从此东园日日来。","更约桃花同坼好，红红白白两相催。"]},{"t":"东园晴步二首 其二","f":"七言绝句","c":["金沙绕架卧春风，节节新条出嫩丛。","一色匀排绿瓶子，忽然半缕漏深红。"]},{"t":"东园晴步二首 其一","f":"七言绝句","c":["浅暖疏寒十日晴，桃花红暗李花明。","小蜂扑得浑无益，羽扇徒劳不作声。"]},{"t":"东园新种桃李，结子成阴，喜而赋之","f":"七言律诗","c":["桃李今春胜去春，添新换旧却重新。","冥搜奇特根窠底，妙简团栾树子匀。","移处带花非差事，登时著子亦娱人。","坡云十载方成荫，未解诚斋别有神。"]},{"t":"东园墙隅双松可爱栽酴醾金沙以绕其上","f":"七言绝句","c":["双松树子碧团栾，红锦缠头白锦冠。","尽放花枝过墙去，不妨分与路人看。"]},{"t":"东窗梅影上有寒雀往来","f":"七言绝句","c":["梅花寒雀不须摹，日影描窗作画图。","寒雀解飞花解舞，君看此画古今无。"]},{"t":"兰溪解舟四首 其一","f":"七言绝句","c":["两岸千千万万峰，看来冷白复寒红。","人言雪岭非银岭，三日晴光晒不融。"]},{"t":"兰溪解舟四首 其四","f":"七言绝句","c":["际晚江风刮面来，晓寒已去却重回。","也知青女嫁滕六，巽二何须强作媒。"]},{"t":"兰溪解舟四首 其三","f":"七言绝句","c":["只愁滩浅阁行舟，到得江深又不流。","水鸟避人飞不彻，看他没去看他浮。"]},{"t":"兰溪解舟四首 其二","f":"七言绝句","c":["日开五色暖征裘，雪满群山爽病眸。","道是诗人穷到骨，暖边爽里放兰舟。"]},{"t":"冬至日归自天庆观二首 其二","f":"七言绝句","c":["节里人家笑语饶，日高犹自烛光交。","霜林遮眼八九叶，露竹出墙三四梢。"]},{"t":"冬至日归自天庆观二首 其一","f":"七言绝句","c":["逗晓清寒未苦严，轻霜随分点茅檐。","雾中失却溪边寺，不见浮屠只见尖。"]},{"t":"冬至前三日","f":"七言绝句","c":["故山千里几时回，又见初阳动琯灰。","酒不逢人还易醉，诗如得句偶然来。"]},{"t":"冬暖绝句","f":"七言绝句","c":["今岁无寒祇有暄，腊前浑似半春天。","醉中苦有薰香癖，烧得春衫两袖穿。"]},{"t":"出永丰县西石桥上闻子规二首 其二","f":"七言绝句","c":["怨笛哀筝总不如，一声声彻九天虚。","若逢雨夜如何听，幸得花时莫管渠。"]},{"t":"出永丰县西石桥上闻子规二首 其一","f":"七言绝句","c":["花愁月恨只长啼，雨夕风晨不住飞。","自出锦江归未得，至今犹劝别人归。"]},{"t":"出城途中小憩","f":"七言绝句","c":["未到江城已日斜，山烟白处是人家。","秋风毕竟无多巧，只把燕支滴蓼花。"]},{"t":"出蛱二首 其二","f":"七言绝句","c":["船行尽缓底须忙，诗卷聊堪度日长。","瓶里柚花偷触鼻，忽然将谓是烧香。"]},{"t":"出真阳峡十首 其十","f":"七言绝句","c":["未必阳山天下穷，英州穷到骨中空。","郡官只怨无供给，支与真阳数石峰。"]},{"t":"出真阳峡十首 其九","f":"七言绝句","c":["春光浓里更江行，画舫分明是水亭。","出了真阳恰惆怅，数峰如笋雨中青。"]},{"t":"出真阳峡十首 其八","f":"七言绝句","c":["今岁春流涨又销，水痕犹印石间茅。","浮槎却被春流误，长挂江边小树梢。"]},{"t":"出真阳峡十首 其七","f":"七言绝句","c":["只言英石冠南中，未识真阳一两峰。","遮莫坡陀将不去，将诗描取小玲珑。"]},{"t":"出真阳峡十首 其六","f":"七言绝句","c":["入峡长思出峡行，出来却忆峡中清。","一江碧水供诗砚，两岸青山作砚屏。"]},{"t":"出真阳峡十首 其五","f":"七言绝句","c":["江枫新染绿衣衫，知费春风几把蓝。","道是春光在桃李，试除桃李尽教参。"]},{"t":"出真阳峡十首 其四","f":"七言绝句","c":["峡中出了又逢滩，破浪牵船分外难。","只是峡山临欲别，此滩留我再看山。"]},{"t":"出真阳峡十首 其三","f":"七言绝句","c":["峡岭分明是假山，乱堆怪石入云间。","上头更种青琼树，下照春江玉镜寒。"]},{"t":"出真阳峡十首 其二","f":"七言绝句","c":["细雨初来刺水纹，三针两线未教繁。","不知忽有何忙处，急洒千千万万痕。"]},{"t":"出真阳峡十首 其一","f":"七言绝句","c":["过尽危矶出小潭，回头失却石峰巉。","春寒料峭元无事，知我犹藏一布衫。"]},{"t":"出惠山遥望横山","f":"七言绝句","c":["三日横山反覆看，殷勤送我惠山前。","常州更在横山外，只望横山已杳然。"]},{"t":"半山寺三首 其三","f":"七言绝句","c":["日边赐额寺名新，鸡犬犹迎旧主人。","见说小儿齐拍手，半山寺主裹头巾。"]},{"t":"半山寺三首 其二","f":"七言绝句","c":["老无稚子为应门，病有毗耶伴此身。","相府梵宫均是幻，却须舍宅即离尘。"]},{"t":"半山寺三首 其一","f":"七言绝句","c":["霜松雪竹老重寻，南荡东陂水自深。","凤去宅存谁与住，不如作寺免伤心。"]},{"t":"去瑞香病叶","f":"七言绝句","c":["紫蕤落尽长青枝，政是添新换旧时。","辛苦为渠耘病叶，殷勤挽住是游丝。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其十","f":"七言绝句","c":["水夹横堤柳万株，雨馀新沐更新梳。","柔条如线长而细，不贯双鱼只贯珠。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其九","f":"七言绝句","c":["清晓新凉惬老怀，只愁傔从可怜哉。","泥行寸步无由到，雨去前山却复回。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其八","f":"七言绝句","c":["雨入秋空细复轻，松梢积得太多生。","忽然落点拳来大，偏作行人滴伞声。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其七","f":"七言绝句","c":["行穿诘曲更崔嵬，野店柴门半未开。","皂荚树阴黄草屋，隔篱犬吠出头来。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其六","f":"七言绝句","c":["君看人迹蝶来轻，踏得林间路作坑。","古路今人行不得，一时移上上头行。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其五","f":"七言绝句","c":["斫地烧畬旋旋开，豆花麻荚更菘栽。","荒山半寸无遗土，田父何曾一饱来。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其四","f":"七言绝句","c":["不但秋原雨冒田，坐看平地路成川。","隔田山下青松外，不见人家只见烟。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其三","f":"七言绝句","c":["雨入秋田恰及时，禾头相枕卧相依。","路南路北皆秋水，净洗行人屦上泥。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其二","f":"七言绝句","c":["可堪衰病两相缠，更苦悬车尚五年。","羡杀雨中山上水，留它不住竟归田。"]},{"t":"发孔镇晨炊漆桥道中纪行十首 其一","f":"七言绝句","c":["梦中一夜雨浪浪，晓过田间尚雨香。","塘水溉田能几许，雨馀田水却归塘。"]},{"t":"发通衢驿见梅有感","f":"七言绝句","c":["忙中掠眼雪枝斜，落片纷纷点玉沙。","虚过一冬妨底事，不曾款曲是梅花。"]},{"t":"发慈湖过烈山望见历阳一带山二首 其二","f":"七言绝句","c":["一出还添二百诗，风光投到费推辞。","江湖物色休吟尽，留取西归一半题。"]},{"t":"发慈湖过烈山望见历阳一带山二首 其一","f":"七言绝句","c":["梦绕天津月再湾，慈湖解缆已开颜。","淮山到眼浑相识，直北青梢是定山。"]},{"t":"四月一日三衢阻雨二首 其二","f":"七言绝句","c":["小诗苦雨当云笺，寄似南风一问天。","漏得银河乾见底，却将什么作丰年。"]},{"t":"四月一日三衢阻雨二首 其一","f":"七言绝句","c":["无朝无夕雨翻盆，村北村南水接天。","断却市桥君莫笑，前头野渡更无船。"]},{"t":"四月中休日闻蝉","f":"七言绝句","c":["荔枝叶底暑阴清，已有新蝉一两声。","荷露柳风餐未饱，怪来学语不分明。"]},{"t":"左藏南库西庑下纸閤负暄戏题","f":"七言绝句","c":["水衡仙客住冰天，雪齧风餐更禁烟。","不是移来小旸谷，老夫冻折两诗肩。"]},{"t":"归云三首 其三","f":"七言绝句","c":["坐看山头托宿云，一云才动万云奔。","霍然散作千村雾，远处昏来近处昏。"]},{"t":"归云三首 其二","f":"七言绝句","c":["三足鸦儿出海东，飞光一朵染天红。","只销半点归云动，立地濛濛暗太空。"]},{"t":"归云三首 其一","f":"七言绝句","c":["可杀归云也爱山，夜来都宿好山间。","偶看一絮翩然起，引得崩腾相趁还。"]},{"t":"归自豫章复过西山","f":"七言绝句","c":["一眼苕花十里明，忽疑九月雪中行。","我行莫笑无驺从，自有西山管送迎。"]},{"t":"归途轿中读参寥诗","f":"七言绝句","c":["车中无作惟生睡，卷里何佳却胜闲。","会意贪看三五句，回头悔失数重山。"]},{"t":"归路过南溪桥二首 其二","f":"七言绝句","c":["爱它风物重徘徊，归路迟迟却快哉。","曲折缘溪非细好，忽逢断岸却回来。"]},{"t":"归路过南溪桥二首 其一","f":"七言绝句","c":["霜风一动岭云开，云外樵歌暮更哀。","童子隔溪呼伴侣，并驱水牯过溪来。"]},{"t":"戊戌正月二日雪作二首 其二","f":"七言绝句","c":["梦回纸帐怪生寒，童子传呼雪作团。","已被晓风融作水，头巾不裹起来看。"]},{"t":"戊戌正月二日雪作二首 其一","f":"七言绝句","c":["雪与新春作伴回，捣霜为片雹为埃。","只愁雪虐梅无奈，不道梅花领雪来。"]},{"t":"正月二十八日峡外见燕子二首 其二","f":"七言绝句","c":["不宿青枫学子规，不穿绿柳伴莺啼。","双飞只爱清江水，自喜身轻照舞衣。"]},{"t":"正月二十八日峡外见燕子二首 其一","f":"七言绝句","c":["社日今年定几时，元宵过了燕先归。","一双贴水娇无奈，不肯平飞故仄飞。"]},{"t":"正月二十四夜朱师古少卿招饮小楼看灯二首 其二","f":"七言绝句","c":["南北高峰醒醉眸，市喧都寂似岩幽。","君言去岁西湖雨，城外荷声到此楼。"]},{"t":"正月二十四夜朱师古少卿招饮小楼看灯二首 其一","f":"七言绝句","c":["光射琉璃贯水精，玉虹垂地照天明。","风流谁似朱夫子，解放元宵过后灯。"]},{"t":"正月三日骤暖多稼亭前梅花盛开四首 其四","f":"七言绝句","c":["却缘腊雪勒孤芳，等待晴光晒麝囊。","小立树西人不会，东风供我打头香。"]},{"t":"正月三日骤暖多稼亭前梅花盛开四首 其三","f":"七言绝句","c":["初开犹见蒂和心，今日来看花满林。","日照一团都是雪，更无红蜡与黄金。"]},{"t":"正月三日骤暖多稼亭前梅花盛开四首 其二","f":"七言绝句","c":["绝爱西湖疏影诗，要知犹是未开时。","如今开尽浑无缝，只见花头不见枝。"]},{"t":"正月三日骤暖多稼亭前梅花盛开四首 其一","f":"七言绝句","c":["春被梅花抵死催，今年春向去年回。","春回十日梅初觉，一夜商量一并开。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其四","f":"七言绝句","c":["千官拜舞仰虚皇，奉上瑶池万寿觞。","殿上双传送御酒，槛前一曲绕虹梁。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其三","f":"七言绝句","c":["金鬣狻猊立玉台，双瞻御坐首都回。","水沉山麝蔷薇露，漱作香云喷出来。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其二","f":"七言绝句","c":["一点胡行朝汉天，英符来自玉门关。","旧时千岁琵琶语，新学三声万岁山。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其九","f":"七言绝句","c":["广场妙戏斗程材，未得天颜一笑开。","角抵罢时还宴罢，卷班出殿戴花回。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其一","f":"七言绝句","c":["殿下鞭声再掣雷，玉皇徐下九天来。","阴晴不定朝来定，五色祥云霍地开。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其八","f":"七言绝句","c":["赐花新剪茜香罗，篸遍乌纱未觉多。","花重纱轻人更老，抬头不起奈春何。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其七","f":"七言绝句","c":["猛士缘竿亦壮哉，踏空舞阔四裴回。","一声白雨催花鼓，十二竿头总下来。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其五","f":"七言绝句","c":["太极重开万物新，绍熙天子宴群臣。","梨园好语君须听，玉历初颁第一春。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其十","f":"七言绝句","c":["贺老如何尾从班，真官也作借官看。","君恩至重无真假，赐酒何曾味两般。"]},{"t":"正月将晦繁星满天","f":"七言绝句","c":["兔冷蟾寒不出时，群仙无睡尚游嬉。","可怜深夜无灯火，碧玉枰前暗著棋。"]},{"t":"永丰驿逢故人赵伯庭过叔","f":"七言绝句","c":["同官赣水总青春，消息中间两不闻。","道我未衰君莫戏，不须看我只看君。"]},{"t":"永和放船二首 其一","f":"七言绝句","c":["永和不到又经秋，淡日微风好放舟。","最是可怜江上路，人来人去几时休。"]},{"t":"永和放船二首 其二","f":"七言绝句","c":["濒江楼阁祇遥看，却恐登临不足观。","已是老来无眼力，更供两岸万峰寒。"]},{"t":"玉山道中","f":"七言绝句","c":["村北村南水响齐，巷头巷尾树阴低。","青山自负无尘色，尽日殷勤照碧溪。"]},{"t":"玉壶饯客独赵达明末至云迓族长于龙山且谈道中事戏为纪之二首 其二","f":"七言绝句","c":["公子从来火伞中，解衣未定语匆匆。","山行触热端何事，夹路杨梅树树红。"]},{"t":"玉壶饯客独赵达明末至云迓族长于龙山且谈道中事戏为纪之二首 其一","f":"七言绝句","c":["南山行尽到西湖，却上扁舟赴玉壶。","十里便成三十里，暑中何处不长涂。"]},{"t":"甘瓠","f":"七言绝句","c":["笑杀桑根甘瓠苗，乱它桑叶上它条。","向人更逞廋藏巧，怪道桑梢挂一瓢。"]},{"t":"田家乐","f":"七言绝句","c":["稻穗堆场谷满车，家家鸡犬更桑麻。","漫栽木槿成篱落，已得清阴又得花。"]},{"t":"甲子初春即事六首 其六","f":"五言绝句","c":["人怨花迟发，天教暖早催。","不知要催落，却道是催开。"]},{"t":"甲子初春即事六首 其五","f":"五言绝句","c":["骤暖如初夏，通身退裌衣。","只言寒已去，却等五更归。"]},{"t":"甲子初春即事六首 其四","f":"五言绝句","c":["只有观书乐，其如病眼何。","但令吾意适，不必卷头多。"]},{"t":"甲子初春即事六首 其三","f":"五言绝句","c":["径李浑秾白，山桃半淡红。","杏花红又白，非淡亦非秾。"]},{"t":"甲子初春即事六首 其二","f":"五言绝句","c":["腊去寒犹在，春来花未开。","东风忽然到，放尽一园梅。"]},{"t":"甲子初春即事六首 其一","f":"五言绝句","c":["老子烧香罢，蜂儿作队来。","徘徊绕襟袖，将谓是花开。"]},{"t":"甲午出知漳州晚发船龙山暮宿桐庐二首 其二","f":"七言绝句","c":["道涂奔走不曾安，却羡山家住得闲。","记取还山安住日，更忘奔走道涂间。"]},{"t":"甲午出知漳州晚发船龙山暮宿桐庐二首 其一","f":"七言绝句","c":["一席清风万壑云，送将华发得归身。","海潮也怯桐江净，不遣涛头过富春。"]},{"t":"甲申上元前闻家君不快西归见梅有感二首 其二","f":"七言绝句","c":["千里来为五斗谋，老亲望望且归休。","春光尽好关侬事，细雨梅花只做愁。"]},{"t":"甲申上元前闻家君不快西归见梅有感二首 其一","f":"七言绝句","c":["官路桐江西复西，野梅千树压疏篱。","昨来都下筠篮底，三百青钱买一枝。"]},{"t":"甲寅二月十八日牡丹初发","f":"五言绝句","c":["排日上牙牌，记花先后开。","看花不子细，过了却重回。"]},{"t":"白头吟二首 其二","f":"七言绝句","c":["除却共姜是女师，柏舟便到白头辞。","劝渠莫怨终难劝，不道前夫怨阿谁。"]},{"t":"白头吟二首 其一","f":"七言绝句","c":["文君自制白头吟，怨思来时海未深。","怨杀相如偿底事，初头苦信一张琴。"]},{"t":"白含笑","f":"七言绝句","c":["薰风晓破碧莲莟，花意犹低白玉颜。","一粲不曾容易发，清香何自遍人间。"]},{"t":"白鱼羹戏题","f":"七言绝句","c":["秋水寒鱼白锦鳞，姜花枨实献芳辛。","东坡玉糁真穷相，得似先生此味珍。"]},{"t":"白莲","f":"七言绝句","c":["井花新插白芙蕖，坐看纷纷脱雪肤。","自拾落英浮水面，玉舟撩乱满江湖。"]},{"t":"白莲","f":"七言绝句","c":["花头素片剪成冰，叶背青琼刻作棱。","珍重儿童轻手折，绿针刺手却渠憎。"]},{"t":"白菊二首 其二","f":"七言绝句","c":["霜后黄花顿不中，独馀白菊斗霜浓。","与霜更斗晴天日，斗得霜融菊不融。"]},{"t":"白菊二首 其一","f":"七言绝句","c":["白菊初开也自黄，开来开去白如霜。","小蜂劣得针来大，不怕清寒嗅冷香。"]},{"t":"立春日","f":"五言绝句","c":["何处新春好，深山处士家。","风光先著柳，日色款催花。"]},{"t":"立春日有怀二首 其一","f":"七言绝句","c":["飘蓬敢恨一年迟，客里春光也自宜。","白玉青丝那得说，一杯咽下少陵诗。"]},{"t":"立春日有怀二首 其二","f":"七言绝句","c":["玉堂著句转春风，诸老从前亦寓忠。","谁为君王供帖子，丁宁绮语不须工。"]},{"t":"立秋日闻蝉","f":"七言绝句","c":["老火薰人欲破头，唤秋不到得人愁。","夜来一雨将秋至，今晚蝉声始报秋。"]},{"t":"立秋后一日雨天欲暮小立问月亭","f":"七言绝句","c":["雨后林中别样凉，意行幽径不知长。","风蝉幸自无星事，强为闲人报夕阳。"]},{"t":"记丘宗卿咽冰语","f":"七言绝句","c":["醉咽冰丸不作难，不须碎嚼不须餐。","听渠历历胸中过，一寸诗肠一寸寒。"]},{"t":"记梦三首 其三","f":"五言绝句","c":["雾外知何寺，钟声只隔山。","望来无里许，还在九霄间。"]},{"t":"记梦三首 其二","f":"五言绝句","c":["水动花梢动，花摇水影摇。","不知各无意，为复两相招。"]},{"t":"记梦三首 其一","f":"五言绝句","c":["云袖危相复，霜钟韵政迟。","忽然数声急，却是住撞时。"]},{"t":"龙山送客二首 其二","f":"七言绝句","c":["无奈乡愁只强忘，龙山唤起再思乡。","故乡依旧千山外，却被龙山断杀肠。"]},{"t":"龙山送客二首 其一","f":"七言绝句","c":["念念还乡未得还，偶因送客到龙山。","分明认得西归路，只是回车却入关。"]},{"t":"亦山亭前梅子","f":"七言绝句","c":["道傍小树复低枝，摘尽青梅肯更遗。","偶尔叶间留一个，且看漏眼几多时。"]},{"t":"仲冬诏追造朝供尚书郎职舟行阻风青泥三首 其二","f":"七言绝句","c":["破篱外面即江流，枯树梢头总客愁。","隔水远山浓复淡，殷勤点缀一川秋。"]},{"t":"休日城上三首 其三","f":"七言绝句","c":["望中远树各依行，春后新晴未断霜。","池面得风呈绉碧，梅须经雨褪危黄。"]},{"t":"休日城上三首 其二","f":"七言绝句","c":["休日呼儿上古城，胡床何处不随行。","莫嫌一阵东风恶，分外教他数日晴。"]},{"t":"休日城上三首 其一","f":"七言绝句","c":["到得荆溪鬓尽斑，二年心力不曾闲。","如今归去无馀恋，只有梅花惨别颜。"]},{"t":"休日晚步二绝句 其一","f":"七言绝句","c":["未须急访社中狂，且到西园探海棠。","今岁行春虽较晚，也胜雨里度春光。"]},{"t":"休日晚步二绝句 其二","f":"七言绝句","c":["晚云欲雨又欲晴，天借吾人作此行。","莫道行春无去处，山矾香里听溪声。"]},{"t":"休日登城","f":"七言绝句","c":["爱他休日更新晴，忍却春寒上古城。","废垒荒芦无一好，春来微径总堪行。"]},{"t":"晓登万花川谷看海棠二首 其二","f":"七言绝句","c":["准拟今春乐事浓，依前枉却一东风。","年年不带看花福，不是愁中即病中。"]},{"t":"再病书怀呈仲良四首 其一","f":"七言绝句","c":["病身谁伴亦谁怜，赢得昏昏几觉眠。","睡起不知身是病，踞床看尽水沉烟。"]},{"t":"再病书怀呈仲良四首 其二","f":"七言绝句","c":["病中嫌雨又嫌晴，自是情怀未苦平。","两日雨多端不恶，市声洗尽只檐声。"]},{"t":"再病书怀呈仲良四首 其四","f":"七言绝句","c":["方外诗豪张仲良，义风今日更谁双。","绝怜病客无半眼，粥饭随宜到小窗。"]},{"t":"再病书怀呈仲良四首 其三","f":"七言绝句","c":["功名销尽向来心，诗酒从今也不禁。","夜雨遣人归思动，不知湘水几篙深。"]},{"t":"再登垂虹亭三首 其三","f":"七言绝句","c":["长年三老不须催，且据胡床未拟回。","白昼惊人星满地，日光碎处万波来。"]},{"t":"再登垂虹亭三首 其二","f":"七言绝句","c":["宿酲作恼未惺松，一对湖光酒病空。","身到吴中无好处，三年两度上垂虹。"]},{"t":"再登垂虹亭三首 其一","f":"七言绝句","c":["红尘不解送诗来，身在烟波句自佳。","银汉光中有诗客，玉虹背上曳芒鞋。"]},{"t":"农家叹","f":"七言绝句","c":["两月春霖三日晴，久寒初暖稍秧青。","春工只要花迟著，愁损农家管得星。"]},{"t":"刘村渡二首 其二","f":"七言绝句","c":["旷野风从脚底生，远峰顶与额般平。","何人知道诚斋叟，独著驼裘破雨行。"]},{"t":"刘村渡二首 其一","f":"七言绝句","c":["隔岸轻舟不可呼，小桥独木有如无。","落松满地金钗瘦，远树黏天菌子孤。"]},{"t":"同子文材翁子直萧巨济中元夜东园望月二首 其二","f":"七言绝句","c":["月到东园分外光，行行坐坐间传觞。","生愁踏碎千花影，回顾千花总不妨。"]},{"t":"同子文材翁子直萧巨济中元夜东园望月二首 其一","f":"七言绝句","c":["杂碎轻云白锦鳞，十分圆月湿银盆。","锦鳞散尽银盆在，依旧青天无点痕。"]},{"t":"同才翁弟游东园","f":"七言绝句","c":["东园花径半莓苔，老子多时不到来。","一巷江梅都落尽，祇今开底是红梅。"]},{"t":"同尤延之京仲远玉壶饯客二首 其二","f":"七言绝句","c":["金杯玉酒沈寒冰，青李来禽尚带生。","不是此间无暑气，湖风吹取过临平。"]},{"t":"同尤延之京仲远玉壶饯客二首 其一","f":"七言绝句","c":["南漪亭上据胡床，不负西湖五月凉。","十里水风已无价，水风底里更荷香。"]},{"t":"同刘季游登天柱冈四首 其四","f":"七言绝句","c":["偶然乘兴上孱颜，若待偷闲何日闲。","脚力到时皆我有，不须更问是谁山。"]},{"t":"同次公观细陂小坐行店","f":"五言绝句","c":["店歇疑为旅，溪行当出郊。","莓苔依断蓼，翡翠上寒梢。"]},{"t":"同君俞季永步至普济寺晚泛西湖以归得四绝句 其四","f":"七言绝句","c":["曲曲都城缭翠微，鳞鳞湖浪动斜晖。","天寒日暮游人少，两岸轻舟星散归。"]},{"t":"同君俞季永步至普济寺晚泛西湖以归得四绝句 其一","f":"七言绝句","c":["阁日微阴不碍晴，杖藜小倦且须行。","湖山有意留侬款，约束疏钟未要声。"]},{"t":"同君俞季永步至普济寺晚泛西湖以归得四绝句 其三","f":"七言绝句","c":["西湖虽老为人容，不必花时十里红。","卷取郭熙真水墨，枯荷折苇小霜风。"]},{"t":"同君俞季永步至普济寺晚泛西湖以归得四绝句 其二","f":"七言绝句","c":["烟艇横斜柳港湾，云山出没柳行间。","登山得似游湖好，却是湖心看尽山。"]},{"t":"同岳大用甫抚干雪后游西湖早饭显明寺步至四圣观访林和靖故居观鹤听琴得四绝句时去除夕二日 其三","f":"七言绝句","c":["冰壶底里步金沙，真到林逋处士家。","未办寒泉荐秋菊，且将瘦句了梅花。"]},{"t":"同岳大用甫抚干雪后游西湖早饭显明寺步至四圣观访林和靖故居观鹤听琴得四绝句时去除夕二日 其二","f":"七言绝句","c":["紫陌微乾未放尘，青鞋不惜涴泥痕。","春风已入寒蒲节，残雪犹依古柳根。"]},{"t":"同岳大用甫抚干雪后游西湖早饭显明寺步至四圣观访林和靖故居观鹤听琴得四绝句时去除夕二日 其一","f":"七言绝句","c":["湖暖开冰已借春，山晴留雪要娱人。","昨游未当清奇在，踏冻重来眼却新。"]},{"t":"同岳大用甫抚干雪后游西湖早饭显明寺步至四圣观访林和靖故居观鹤听琴得四绝句时去除夕二日 其四","f":"七言绝句","c":["道堂高绝俯空明，上下跻攀取意行。","净阁虚廊人寂寂，鹤声断处忽琴声。"]},{"t":"回望峡山二首 其二","f":"五言绝句","c":["浪喜出峡来，峡亦何曾出。","两岸只无山，依旧江刻屈。"]},{"t":"回望峡山二首 其一","f":"五言绝句","c":["英州挽不来，峡山推不去。","行了一日船，依旧朝来处。"]},{"t":"圩丁词十解 其五","f":"七言绝句","c":["两岸沿堤有水门，万波随吐复随吞。","君看红蓼花边脚，补去脩来无水痕。"]},{"t":"圩丁词十解 其一","f":"七言绝句","c":["圩田元是一平湖，凭仗儿郎筑作圩。","万雉长城倩谁守，两堤杨柳当防夫。"]},{"t":"圩丁词十解 其三","f":"七言绝句","c":["上通建德下当涂，千里江湖缭一圩。","本是阳侯水精国，天公敕赐上农夫。"]},{"t":"圩丁词十解 其八","f":"七言绝句","c":["岸头石板紫纵横，不是修圩是筑城。","传语赫连莫蒸土，霸图未必赛春耕。"]},{"t":"圩丁词十解 其六","f":"七言绝句","c":["年年圩长集圩丁，不要招呼自要行。","万杵一鸣千畚土，大呼高唱总齐声。"]},{"t":"圩丁词十解 其七","f":"七言绝句","c":["儿郎辛苦莫呼天，一日修圩一岁眠。","六七月头无点雨，试登高处望圩田。"]},{"t":"圩田二首 其二","f":"七言绝句","c":["古来圩岸护堤防，岸岸行行种绿杨。","岁久树根无寸土，绿杨走入水中央。"]},{"t":"圩田二首 其一","f":"七言绝句","c":["周遭圩岸缭金城，一眼圩田翠不分。","行到秋苗初熟处，翠茸锦上织黄云。"]},{"t":"夙兴待旦二绝 其二","f":"五言绝句","c":["村里无铜漏，金鸡管杀更。","百声犹未晓，却等第三声。"]},{"t":"夙兴待旦二绝 其一","f":"五言绝句","c":["觉后难重睡，醉馀还独醒。","东窗不肯白，挑尽一灯青。"]},{"t":"多稼亭上望三山中峰独秀而低","f":"七言绝句","c":["三山道是远连天，亭上看来只近檐。","可惜当初低少许，三山幸有一峰尖。"]},{"t":"多稼亭日色甚暖忽有雪数片自晴空而下已而复无","f":"七言绝句","c":["霁日何曾惹寸云，忽飞些子雪如尘。","不知底处天花落，风里吹来数点春。"]},{"t":"多稼亭前小步","f":"七言绝句","c":["樱桃抛过隔墙莟，芍药丛抽刺土芽。","最是蜜蜂无意思，忍将尘脚踏梅花。"]},{"t":"多稼亭看梅二首 其二","f":"七言绝句","c":["梅花不合太争春，政盛开时却恼人。","试折一枝轻著手，惊飞万点扑衣巾。"]},{"t":"多稼亭看梅二首 其一","f":"七言绝句","c":["先生次第即还家，更上城头一望赊。","行尽荒寒无意思，不如来此看梅花。"]},{"t":"多稼亭宴客","f":"七言绝句","c":["归来不省醉还醒，只怪谯门打一更。","秉烛径穿梅下过，此身真在雪中行。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其六","f":"七言绝句","c":["急雪穿帘绕蜡灯，梅花微笑古铜瓶。","朔风恶剧惊人杀，吹倒琉璃六曲屏。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其二","f":"七言绝句","c":["长廊尽处绕梅行，过尽风声得雪声。","醉里不愁飘湿面，自舒翠袖点琼英。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其四","f":"七言绝句","c":["梅花得雪更清妍，折入灯前细撚看。","下却珠帘教到地，横枝太瘦不禁寒。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其九","f":"七言绝句","c":["酒香端的似梅无，小摘梅花浸酒壶。","莫遣南枝独醒著，一杯聊劝雪肌肤。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其五","f":"七言绝句","c":["雪政飞时梅政开，倩人和雪折庭梅。","莫教颤脱梢头雪，千万轻轻折取来。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其八","f":"七言绝句","c":["不是今宵雪不清，只愁清杀老书生。","不知落得几多雪，做尽北风无限声。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其一","f":"七言绝句","c":["晚饮西邻大阮家，天风吹雪入檐牙。","呼僮净扫青苔地，莫遣纤尘涴玉花。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其三","f":"七言绝句","c":["老子那知鬓脚凋，忍寒拚命看珠跳。","却嫌地暖无冰冻，恰则飞来恰则销。"]},{"t":"廷弼弟座上绝句","f":"七言绝句","c":["黄雀初肥入口销，玉醅新熟得春饶。","主人更恐香无味，沉水龙涎作伴烧。"]},{"t":"戏咏陈氏女剪綵花二绝句 其一 拒霜","f":"五言绝句","c":["染露金风里，宜霜玉水滨。","莫嫌开最晚，元自不争春。"]},{"t":"戏咏陈氏女剪綵花二绝句 其二 菊","f":"五言绝句","c":["味苦谁能爱，香寒只自珍。","长将潭底水，普供世间人。"]},{"t":"戏笔二首 其二","f":"七言绝句","c":["哦诗只道更无题，物物秋来总是诗。","著意染须玄尚白，梳头得虱素成缁。"]},{"t":"戏綵堂前海棠","f":"七言绝句","c":["露揉雨渍柳方浓，日晒风曛杏政烘。","祗有海棠非旋染，粟来大小便鲜红。"]},{"t":"戏跋朱元晦楚辞解二首 其二","f":"七言绝句","c":["霜后藜枯无可羹，饥吟长作候虫声。","藏神上诉天应泣，支赐江蓠与杜蘅。"]},{"t":"戏跋朱元晦楚辞解二首 其一","f":"七言绝句","c":["注易笺诗解鲁论，一帆径度浴沂天。","无端又被湘累唤，去看西川竞渡船。"]},{"t":"戏嘲金灯花上皂蝶","f":"七言绝句","c":["花须为饭露为浆，黑雾玄霜剪薄裳。","飞绕金灯来又去，不知能有几多香。"]},{"t":"戏题","f":"七言绝句","c":["蜂居笔管没人知，谁遣啾啾不住时。","最是蜗牛太多事，长将宅子自相随。"]},{"t":"戏题水墨山水屏","f":"七言绝句","c":["棹郎大似半边蝇，摘蕙为船折草撑。","今夜不知何处泊，浪头正与岭头平。"]},{"t":"戏题岸柳","f":"七言绝句","c":["斫尽江边杨柳梢，要教新岁换新条。","老夫也镊霜须鬓，镊却霜根出雪苗。"]},{"t":"戏题郡斋水墨坐屏二面二首 其二","f":"七言绝句","c":["荆溪四面四无山，不是荒林即野田。","忽有石崖天半出，飞泉落处稍人烟。"]},{"t":"戏题郡斋水墨坐屏二面二首 其一","f":"七言绝句","c":["两客呼船一急行，树林半落半犹青。","诸峰最是中峰好，我欲峰头筑小亭。"]},{"t":"戏赠子仁侄","f":"七言绝句","c":["小阮新来觅句忙，自携破砚汲寒江。","天公念子抄诗苦，借与朝阳小半窗。"]},{"t":"早行鸣山二首 其二","f":"七言绝句","c":["灵山未见见龟山，且捲诗书子细看。","春日幸从年后暖，春风须带腊前寒。"]},{"t":"早行鸣山二首 其一","f":"七言绝句","c":["淡淡清霜薄薄冰，晓寒端为作新晴。","殷勤唤醒梅花睡，枝上春禽一两声。"]},{"t":"早朝紫宸殿贺雪呈尤延之二首 其二","f":"七言绝句","c":["雪妃月姊宴群仙，珠阁银楼集玉鸾。","老子来看收不彻，梅梢拾得水精盘。"]},{"t":"早朝紫宸殿贺雪呈尤延之二首 其一","f":"七言绝句","c":["雪花将瑞献君王，晴早销迟恋建章。","不肯独清须带月，犹嫌未冷更吹霜。"]},{"t":"曲湾放船","f":"七言绝句","c":["梅子成阴夹道周，木绵吐焰满江头。","春来不是无桃李，腊月开花已落休。"]},{"t":"有叹","f":"七言绝句","c":["饱喜饥嗔笑杀侬，凤皇未可笑狙公。","尽逃暮四朝三外，犹在桐花竹实中。"]},{"t":"有叹","f":"七言绝句","c":["老来无面见毛锥，犹把闲愁付小诗。","若道愁多头易白，鹭鸶从小鬓成丝。"]},{"t":"江上松径","f":"七言绝句","c":["一日江行百折中，回头犹见夜来峰。","好山十里都如画，更与横排一径松。"]},{"t":"江下送客","f":"七言绝句","c":["却因送客动归心，过市逢喧闷不禁。","偶见人家好池馆，柳行尽处一亭深。"]},{"t":"江山道中蚕麦大熟三首 其一","f":"七言绝句","c":["衢信中央两尽头，蚕麰今岁十分收。","穗初黄后枝无绿，不但麦秋桑亦秋。"]},{"t":"江天暮景有叹二首 其二","f":"七言绝句","c":["一鹭南飞道偶然，忽然百百复千千。","江淮总属天家管，不肯营巢向北边。"]},{"t":"江天暮景有叹二首 其一","f":"七言绝句","c":["只争一水是江淮，日暮风高云不开。","白鹭倦飞波政阔，都从淮上过江来。"]},{"t":"江行七日阻风至繁昌舍舟出陆二首 其二","f":"七言绝句","c":["山行辛苦水行愁，只是诗人薄命休。","管取如今遵陆了，云开风顺水东流。"]},{"t":"江行七日阻风至繁昌舍舟出陆二首 其一","f":"七言绝句","c":["日日江行怖杀侬，逆风恶浪打船篷。","只今判却肩舆去，遮莫掀天浪与风。"]},{"t":"江郎峰三石山在江山县南三十五里礼贤镇望之极正里人又呼为郎峰","f":"七言绝句","c":["走遍名山脚不停，见渠令我眼偏明。","郎峰好处端何似，笋剥三竿紫水精。"]},{"t":"江雨三首 其三","f":"七言绝句","c":["翡翠洲横绿锦山，真珠汁洗水精砖。","江天万景无拘管，乞与诗人塞满船。"]},{"t":"江雨三首 其二","f":"七言绝句","c":["雨里油窗莫要关，滴来堪玩洒堪闻。","万珠贡入龙宫了，剩得檐前数颗看。"]},{"t":"江雨三首 其一","f":"七言绝句","c":["雨点飞来水面初，湿银盘里走真珠。","龙宫可是忙收拾，万斛齐倾半霎无。"]},{"t":"题代度寺","f":"七言绝句","c":["一别重来十五年，残僧半在寺依然。","黄杨当日绝低小，已过危檐也可怜。"]},{"t":"池冰二首 其二","f":"七言绝句","c":["怕寒不敢上高台，上得高台急急回。","日欲消冰风不允，天犹未夕月先来。"]},{"t":"池冰二首 其一","f":"七言绝句","c":["池底枯荷瘦不胜，池冰新琢玉壶凝。","如何留到炎蒸日，上有荷花下有冰。"]},{"t":"池亭双树梅花","f":"七言绝句","c":["开尽梅花半欲残，两株晴雪作双寒。","团栾绕树元无见，只合池亭隔水看。"]},{"t":"汤田早行见李花甚盛二首 其二","f":"五言绝句","c":["似妒梅花早，同时斗雪肤。","新年三二月，还解再开无。"]},{"t":"汤田早行见李花甚盛二首 其一","f":"五言绝句","c":["此地先春信，年年只是梅。","南中春更早，腊日李花开。"]},{"t":"竹枝歌七首 其七","f":"七言绝句","c":["幸自通宵暖更晴，何劳细雨送残更。","知侬笠漏芒鞋破，须遣拖泥带水行。"]},{"t":"竹枝歌七首 其六","f":"七言绝句","c":["月子弯弯照几州，几家驩乐几家愁。","愁杀人来关月事，得休休处且休休。"]},{"t":"竹枝歌七首 其五","f":"七言绝句","c":["岸旁燎火莫阑残，须念儿郎手脚寒。","更把绿荷包热饭，前头不怕上高滩。"]},{"t":"竹枝歌七首 其四","f":"七言绝句","c":["积雪初融做晚晴，黄昏恬静到三更。","小风不动还知么，且只牵船免打冰。"]},{"t":"竹枝歌七首 其三","f":"七言绝句","c":["船头更鼓恰三槌，底事荒鸡早个啼。","戏学当年度关客，且图一笑过前溪。"]},{"t":"竹枝歌七首 其二","f":"七言绝句","c":["莫笑楼船不解行，识侬号令听侬声。","一人唱了千人和，又得蹉前五里程。"]},{"t":"竹枝歌七首 其一","f":"七言绝句","c":["吴侬一队好儿郎，只要船行不要忙。","著力大家齐一拽，前头管取到丹阳。"]},{"t":"米囊花二首 其二","f":"七言绝句","c":["鸟语蜂喧蝶亦忙，争传天诏诏花王。","东皇羽卫无供给，探借春风十日粮。"]},{"t":"米囊花二首 其一","f":"七言绝句","c":["铅膏细细点花梢，道是春深雪未销。","一斛千囊苍玉粟，东风吹作米长腰。"]},{"t":"红叶","f":"七言绝句","c":["诗人满腹著清愁，吐作千诗未肯休。","写遍壁间无去处，却将红叶强题秋。"]},{"t":"自生米小路出舞阳渡","f":"七言绝句","c":["独径千盘绕水田，初逢官路一欣然。","舞阳渡口新河水，白发重来二十年。"]},{"t":"自金陵西归至豫章发南浦亭宿黄家渡","f":"七言绝句","c":["过了重湖雪浪堆，章江欲尽淦江来。","到家无此江山景，画舫行迟不用催。"]},{"t":"自值夏小溪泛舟出大江","f":"七言绝句","c":["放溜山溪一叶轻，山溪尽处大江横。","舟中寂寂无人语，只有波声及雨声。"]},{"t":"自彭田铺至汤田道旁梅花十馀里","f":"七言绝句","c":["一行谁栽十里梅，下临溪水恰齐开。","此行便是无官事，只为梅花也合来。"]},{"t":"自跋江西道院集戏答客问 其二","f":"七言绝句","c":["客从南渡向侬来，我马西征拜此台。","若问个中何所有，一腔热血和诗裁。"]},{"t":"自跋江西道院集戏答客问 其一","f":"七言绝句","c":["问我来朝南内南，便从花底趁朝参。","新诗犹作江西集，为带筠州刺史衔。"]},{"t":"自遣","f":"七言绝句","c":["莫将一病苦忧煎，山尚能游石可眠。","匹似病风兼病脚，老夫犹是地行仙。"]},{"t":"自嘲白须三首 其一","f":"五言绝句","c":["强惜数茎须，惟愁白却渠。","朝来都白尽，愁惜两何如。"]},{"t":"自嘲白须三首 其三","f":"五言绝句","c":["涅髭只诳客，那可诳妻儿。","诳得妻儿著，还能诳面皮。"]},{"t":"至日前思亲","f":"五言绝句","c":["节近亲庭远，天寒日暮时。","未风窗已报，欲雪脚先知。"]},{"t":"至永和","f":"七言绝句","c":["出城即便见青原，正在长江出处天。","却到青原望城里，楼台些子水云边。"]},{"t":"至后入城道中杂兴十首 其十","f":"七言绝句","c":["春时宿处雨浪浪，至后重投张氏庄。","际晚乌银何许买，夕阳特地恋寒窗。"]},{"t":"至后入城道中杂兴十首 其九","f":"七言绝句","c":["忽见轻绡三两重，横遮万丈翠屏风。","老夫细熨䰒松眼，却是青原隐雾中。"]},{"t":"至后入城道中杂兴十首 其八","f":"七言绝句","c":["谁练苕花作雪茸，更将枫叶染猩红。","姮娥不认推青女，青女又还推化工。"]},{"t":"至后入城道中杂兴十首 其七","f":"七言绝句","c":["山路肩舆倦仆夫，家兄为我酒频沽。","卖薪人散知城近，啼柳乌忙觉日晡。"]},{"t":"至后入城道中杂兴十首 其六","f":"七言绝句","c":["丰年物物总欣驩，不但人和畜亦蕃。","簸处金肤肥彘母，舂馀珠屑饱鸡孙。"]},{"t":"至后入城道中杂兴十首 其五","f":"七言绝句","c":["长亭阿姥短亭翁，探借桃花作面红。","酒熟自尝仍自卖，一生割据醉乡中。"]},{"t":"至后入城道中杂兴十首 其四","f":"七言绝句","c":["畦蔬甘似卧沙羊，正为新经几夜霜。","芦菔过拳菘过膝，北风一路菜羹香。"]},{"t":"至后入城道中杂兴十首 其三","f":"七言绝句","c":["问渠田父定无饥，却道官人那得知。","未送太仓新玉粒，敢先云子滑流匙。"]},{"t":"至后入城道中杂兴十首 其二","f":"七言绝句","c":["大熟仍教得大晴，今年又是一升平。","升平不在箫韶里，只在诸村打稻声。"]},{"t":"至后入城道中杂兴十首 其一","f":"七言绝句","c":["至后寒梅未苦繁，腊前暖蝶已偷还。","隔林日射池光动，碎却池中倒影山。"]},{"t":"至后与履常探梅东园三首 其三","f":"七言绝句","c":["雨涩风酸闷却春，日光初暖倍精神。","天如一面青罗扇，仰看横枝自写真。"]},{"t":"至后与履常探梅东园三首 其二","f":"七言绝句","c":["两朵三枝梅正新，不疏不密最忺人。","花枝夹径嗔人过，絓脱老夫头上巾。"]},{"t":"至后与履常探梅东园三首 其一","f":"七言绝句","c":["雨后霜前梅欲开，欲开犹懒雪风催。","一秋不到东园里，从此朝朝暮暮来。"]},{"t":"舟中元夕雨作三首 其三","f":"七言绝句","c":["此生万事有期程，多取抛饶竟不曾。","谁遣夜来南馆里，千花预借上元灯。"]},{"t":"舟中元夕雨作三首 其二","f":"七言绝句","c":["佳辰三五是今宵，恰则今宵细雨飘。","天念孤舟人寂寞，不教月色故相撩。"]},{"t":"舟中元夕雨作三首 其一","f":"七言绝句","c":["道是今宵好上元，新晴白昼雨黄昏。","红灯皎月侬无用，关上船门倒一尊。"]},{"t":"舟中戏题","f":"七言绝句","c":["花处青山柳处溪，新来宿处旧曾炊。","到家失却行程历，只检西归小集诗。"]},{"t":"舟中夜坐","f":"五言绝句","c":["与月隔一簟，去天争半篷。","若无篷与簟，身在大虚中。"]},{"t":"舟中雨望二首 其二","f":"七言绝句","c":["船窗深闭懒看书，独倚船门撚白须。","雨共长河织青锦，金钱晕上滴真珠。"]},{"t":"舟中雨望二首 其一","f":"七言绝句","c":["雨里船中只好眠，不堪景物妒人闲。","岩如玉案平铺却，饤饾真山作假山。"]},{"t":"舟中晚酌二首 其二","f":"七言绝句","c":["一日寒暄自不同，绣帘下却护轻风。","杨花可是多情思，飞入船中落酒中。"]},{"t":"舟中晚酌二首 其一","f":"七言绝句","c":["竹陵春酒绝清严，解割诗肠快似镰。","雪藕逢暄偏觉爽，鹅梨欲烂不胜甜。"]},{"t":"舟中晚望二首 其二","f":"七言绝句","c":["晚浪翻风玉作鳞，夕阳捲玉药成金。","忽然濯出西川锦，制就霞衣不用针。"]},{"t":"舟中晚望二首 其一","f":"七言绝句","c":["河岸前头松树林，树林尽处见行人。","行人又被山遮断，风飐酒家青布巾。"]},{"t":"舟次西径","f":"七言绝句","c":["夜来徐汊伴鸥眠，西径晨炊小泊船。","芦荻渐多人渐少，鄱阳湖尾水如天。"]},{"t":"舟过安仁五首 其五","f":"七言绝句","c":["渭川千顷在诗胸，不管屠羊肆里空。","踏破菜园妨底事，莫教踏到竹园中。"]},{"t":"舟过安仁五首 其四","f":"七言绝句","c":["南风作雨北风休，岂是春云得自由。","只者天时过湖得，长年报道不须愁。"]},{"t":"舟过安仁五首 其三","f":"七言绝句","c":["一叶渔船两小童，收篙停棹坐船中。","怪生无雨都张伞，不是遮头是使风。"]},{"t":"舟过安仁五首 其二","f":"七言绝句","c":["初受遥山献画图，忽然卷去淡如无。","莫欺老眼犹明在，和雾和烟数得渠。"]},{"t":"舟过安仁五首 其一","f":"七言绝句","c":["恰则油窗雨点声，霎时花屿日华明。","不须覆手仍翻手，可杀春云没十成。"]},{"t":"舟过青羊望横山塔二首 其二","f":"七言绝句","c":["孤塔分明是故人，一回一见一情亲。","朝来走上山头望，报道兰溪酒恰新。"]},{"t":"舟过青羊望横山塔二首 其一","f":"七言绝句","c":["莫问兰溪双只牌，青羊已见玉崔嵬。","去年辞了横山塔，不谓今年却再来。"]},{"t":"舟过城门村清晓雨止日出 其五","f":"七言绝句","c":["地锦花铺地锦衣，碧茸上织紫花枝。","垂杨舞罢莺停唱，不捲华絪待阿谁。"]},{"t":"舟过城门村清晓雨止日出 其四","f":"七言绝句","c":["行人都上半山青，记得前朝傍险行。","左右回身看不彻，两边已失一滩声。"]},{"t":"舟过城门村清晓雨止日出 其三","f":"七言绝句","c":["䰒松睡起揽诗编，信手翻来诵数篇。","忽有篙声仍绝叫，隔篷知是上滩船。"]},{"t":"舟过城门村清晓雨止日出 其二","f":"七言绝句","c":["深村可笑是居民，生长深山野水滨。","总出篱东携稚子，走来岸上看官人。"]},{"t":"舟过城门村清晓雨止日出 其一","f":"七言绝句","c":["五日银丝织一笼，金乌捉取送笼中。","知谁放在扶桑树，祗怪满溪烟浪红。"]},{"t":"舟过凌歊台望见谢家青山","f":"七言绝句","c":["南风久别忽言还，又苦河流九曲湾。","若要顺风兼顺水，柂头背指谢家山。"]},{"t":"舟过望亭三首 其三","f":"七言绝句","c":["此去苏州半日期，归心长是觉船迟。","一村树暗知何处，两岸草青无了时。"]},{"t":"舟过望亭三首 其二","f":"七言绝句","c":["雨罢风回花柳晴，忽然数点打窗声。","游蜂误入船窗里，飞去飞来总是情。"]},{"t":"舟过望亭三首 其一","f":"七言绝句","c":["常州尽处是望亭，已离常州第四程。","柳线绊船知不住，却教飞絮送侬行。"]},{"t":"舟过黄田谒龙母护应庙二首 其二","f":"七言绝句","c":["南康名酒有残樽，急唤荷杯作好春。","紫幕能排北风冷，夕阳偏惜半船温。"]},{"t":"舟过黄田谒龙母护应庙二首 其一","f":"七言绝句","c":["远山相别忽相寻，水到黄田渐欲深。","见说前头山更好，且留好句未须吟。"]},{"t":"舟过谢潭三首 其三","f":"七言绝句","c":["碧酒时倾一两杯，船门才闭又还开。","好山万皱无人见，都被斜阳拈出来。"]},{"t":"舟过谢潭三首 其二","f":"七言绝句","c":["夹江百里没人家，最苦江流曲更斜。","岭草已青今岁叶，岸芦犹白去年花。"]},{"t":"舟过谢潭三首 其一","f":"七言绝句","c":["风头才北忽成南，转眼黄田到谢潭。","髣髴一峰船外影，褰帷急看紫巉岩。"]},{"t":"舟过鹅行口回望和州鸡笼山","f":"七言绝句","c":["两月青山不暂离，入城未见有山时。","万峰送我都回去，只有鸡笼未肯辞。"]},{"t":"舟过德清","f":"七言绝句","c":["人家两岸柳阴边，出得门来便入船。","不是全无最佳处，何窗何户不清妍。"]},{"t":"舟泊吴江三首 其三","f":"七言绝句","c":["东是吴江西太湖，长桥横截万寻馀。","江妃舞倦凌波袜，玉带围腰揽镜初。"]},{"t":"舟泊吴江三首 其二","f":"七言绝句","c":["江湖便是老生涯，佳处何妨且泊家。","自汲松江桥下水，垂虹亭上试新茶。"]},{"t":"舟泊吴江三首 其一","f":"七言绝句","c":["独立吴江第四桥，桥南桥北渺银涛。","此身真在吴江里，不用并州快剪刀。"]},{"t":"芍药初生","f":"五言绝句","c":["芍药新移种，红拳餐万雏。","看来已可爱，未问有花无。"]},{"t":"芗林五十咏 其九 山斋","f":"五言绝句","c":["老子斋中宿，同来无一人。","若非明月客，谁伴白云身。"]},{"t":"芗林五十咏 其三十五 文杏坞","f":"五言绝句","c":["道白非真白，言红不苦红。","请君红白外，别眼看天工。"]},{"t":"芗林五十咏 其十九 无热轩","f":"五言绝句","c":["南北与东西，溪光仍树色。","人间无热轩，物外清凉国。"]},{"t":"芗林五十咏 其八 丛桂","f":"五言绝句","c":["不是人间种，移从月胁来。","广寒香一点，吹得满山开。"]},{"t":"芗林五十咏 其四十 东皋","f":"五言绝句","c":["避世无功酒，临流元亮诗。","鹤鸣入天听，叶下报秋悲。"]},{"t":"芗林五十咏 其十一 兰畹","f":"五言绝句","c":["健碧缤缤叶，斑红浅浅芳。","幽香空自秘，风肯秘幽香。"]},{"t":"芗林五十咏 其五 北垞","f":"五言绝句","c":["住处何曾远，林间别是凉。","清风酣一枕，底许觅羲皇。"]},{"t":"芗林五十咏 其四十九 瓜田","f":"五言绝句","c":["独酌圣贤酒，新尝子母瓜。","丁宁林下友，莫道故侯家。"]},{"t":"芗林五十咏 其二十三 白鹤亭","f":"五言绝句","c":["可怜林下鹤，独肯伴先生。","犹有冲天志，君听叫月声。"]},{"t":"芗林五十咏 其三十三 岁寒亭","f":"五言绝句","c":["冷笑元无味，孤高别有心。","谁将桃李眼，雪里解相寻。"]},{"t":"芗林五十咏 其四十六 有山堂","f":"五言绝句","c":["阁皂风烟外，江西小有天。","兹山本无主，掇入笔床前。"]},{"t":"芗林五十咏 其十四 竹斋","f":"五言绝句","c":["凛凛冰霜节，脩脩玉雪身。","便无文与可，不有月传神。"]},{"t":"芗林五十咏 其一 芗林","f":"五言绝句","c":["一代芗林老，吾生不并时。","来寻白玉柄，祗见紫兰枝。"]},{"t":"芗林五十咏 其四十三 西崦","f":"五言绝句","c":["坡垄端何似，波涛起复低。","醉眠桂花雪，不觉月华西。"]},{"t":"芗林五十咏 其二十七 过花桥","f":"五言绝句","c":["北垞通南埭，前花映后花。","雨多桥板断，拆碎两涯霞。"]},{"t":"芗林五十咏 其四十一 听水亭","f":"五言绝句","c":["泠泠无弦筝，汹汹自鸣鼓。","最是醉梦中，唤作松风雨。"]},{"t":"芗林五十咏 其四十八 折蔬亭","f":"五言绝句","c":["芦菔鼠尾大，蔓菁兔耳长。","先生不忍摘，野客却同尝。"]},{"t":"芗林五十咏 其四 泛宅","f":"五言绝句","c":["犹道山中浅，仍移水上居。","俗人又剥啄，棹入白芙蕖。"]},{"t":"芗林五十咏 其三十八 芙蓉沜","f":"五言绝句","c":["岸植木菡萏，池栽水拒霜。","那知一家种，同艳不同香。"]},{"t":"芗林五十咏 其五十 连辉观","f":"五言绝句","c":["极目斜阳树，乘风落月梁。","更和山与水，并作一秋光。"]},{"t":"芗林五十咏 其二十二 放鱼矶","f":"五言绝句","c":["为惜丹砂尾，亲投碧草潭。","前头有香饵，千万不须贪。"]},{"t":"芗林五十咏 其四十七 松湖","f":"五言绝句","c":["已讶松生市，更将湖入城。","如何造物者，百巧供先生。"]},{"t":"芗林五十咏 其十二 驾月桥","f":"五言绝句","c":["紫霓横天度，银盘涌水来。","先生骑霓脊，盘上捲金杯。"]},{"t":"芗林五十咏 其二十六 南埭","f":"五言绝句","c":["高谢三公府，来耕五亩园。","园中有何好，老子笑无言。"]},{"t":"芗林五十咏 其二十一 柑子园","f":"五言绝句","c":["秋颗酣天酒，春花噀国香。","芗林亲手种，中有洞庭霜。"]},{"t":"芗林五十咏 其二十 柔桑陌","f":"五言绝句","c":["茧馆三眠老，桑村独树春。","坐看黄更陨，应有一寒人。"]},{"t":"芗林五十咏 其三 归来桥","f":"五言绝句","c":["已赓彭泽辞，更拟辋川诗。","未老还山了，犹嫌归较迟。"]},{"t":"芗林五十咏 其三十六 药栏","f":"五言绝句","c":["日出花药丽，风生芝朮香。","枕中兼肘后，别有不传方。"]},{"t":"芗林五十咏 其六 退斋","f":"五言绝句","c":["争进千岐捷，辞荣一著难。","生龟教脱壳，试作个般看。"]},{"t":"芗林五十咏 其二十八 桃李蹊","f":"五言绝句","c":["白雪堆秾李，红蓝染靓桃。","晨妆须蚤看，莫待日华高。"]},{"t":"芗林五十咏 其三十二 海棠洞","f":"五言绝句","c":["艳翠春销骨，妖红醉入肌。","花仙别无诀，一味服燕支。"]},{"t":"芗林五十咏 其十七 读书堂","f":"五言绝句","c":["老以书为命，眼将书作雠。","芗林与诚叟，同贩短檠愁。"]},{"t":"芗林五十咏 其十六 通幽径","f":"五言绝句","c":["点检苔花晕，微茫拄杖痕。","酴醾几开落，山雨湿黄昏。"]},{"t":"芗林五十咏 其三十一 梨花原","f":"五言绝句","c":["禁火晓未暖，踏青昏恰归。","何堪一原雪，将冷入春衣。"]},{"t":"芗林五十咏 其四十二 雪台","f":"五言绝句","c":["玉树参差出，天花顷刻开。","先生倚栏处，指点是瑶台。"]},{"t":"芗林五十咏 其七 寓斋","f":"五言绝句","c":["宇宙一行店，谁为店主人。","主人亦解去，而况爨馀薪。"]},{"t":"芗林五十咏 其二十五 鹅篆滩","f":"五言绝句","c":["不博右军字，且留房相池。","新雏黄似酒，把酒看群嬉。"]},{"t":"芗林五十咏 其二十四 羃翠庭","f":"五言绝句","c":["软甃琉璃地，生揉翡翠帏。","莫教星月入，玉镜点金徽。"]},{"t":"芗林五十咏 其三十九 槐阴墿","f":"五言绝句","c":["阴作官街绿，花催举子黄。","公家有三树，犹带凤池香。"]},{"t":"芗林五十咏 其十八 碧芦潨","f":"五言绝句","c":["春笋肥堪菜，秋花暖可毡。","何须双野鸭，屏上五湖天。"]},{"t":"芗林五十咏 其四十四 碧梧垷","f":"五言绝句","c":["往往游西崦，时时憩午阴。","凤来人不见，飞入碧枝深。"]},{"t":"芗林五十咏 其十 醉石","f":"五言绝句","c":["晚酌居然醉，昏昏不自持。","奇哉苍玉枕，眠到月来时。"]},{"t":"行圃","f":"七言绝句","c":["薤本新痕割复齐，豆苗初叶合仍离。","莺声政好还飞去，不为诗人更许时。"]},{"t":"行圃二首 其二","f":"七言绝句","c":["澹天薄日倦春游，苍桧丛篁引径幽。","忽有小风人未觉，荠花无数总摇头。"]},{"t":"行圃二首 其一","f":"五言绝句","c":["摘杞搜枯梗，攀花脱脆包。","蝶呈新样粉，柳送隔城梢。"]},{"t":"行部决狱宿新隆寺观邹至完题壁","f":"七言绝句","c":["道乡千古一清风，雪壁银钩墨尚浓。","若爱殿前苍玉佩，断无身后碧纱笼。"]},{"t":"行阙养种园千叶杏花二首 其二","f":"七言绝句","c":["白白红红两不真，重重叠叠是精神。","谁言跂石眠云客，也见长杨五柞春。"]},{"t":"行阙养种园千叶杏花二首 其一","f":"七言绝句","c":["不信东皇也有私，如何偏宠杏花枝。","于中更出红千叶，且道此花奇不奇。"]},{"t":"西园早梅二首 其一","f":"七言绝句","c":["已刻酥花趁腊前，更团蜡糁等春妍。","不知天巧能多少，一朵梅花占两年。"]},{"t":"西园晚步二首 其二","f":"七言绝句","c":["为爱荷池日日来，一来一度眼双开。","画船不晓风相戏，猛触花堤得倒回。"]},{"t":"西园晚步二首 其一","f":"七言绝句","c":["龙眼初如菉豆肥，荔枝已似佛螺儿。","南荒北客难将息，最是残春首夏时。"]},{"t":"西斋睡起","f":"七言绝句","c":["小睡西斋听雨凉，竹鸡声里梦难长。","开门山色都争入，只放青苍一册方。"]},{"t":"西湖晚归","f":"七言绝句","c":["际晚游人也合归，画船犹自弄斜晖。","西湖两岸千株柳，絮不因风暖自飞。"]},{"t":"观田中鸲鹆啄粟因悟象耕鸟耘之说戏题二首 其二","f":"七言绝句","c":["粟黄荞白未全秋，谁报乌衣早作偷。","只在林梢筑仓廪，便知去处若为搜。"]},{"t":"观田中鸲鹆啄粟因悟象耕鸟耘之说戏题二首 其一","f":"七言绝句","c":["乌衣缁布外无华，白锦中单分外嘉。","只么跳行人不觉，忽然飞起自成花。"]},{"t":"观汤田铺溪边汤泉","f":"七言绝句","c":["下泓堪浴上堪煎，阴火熬成未必然。","海底日升波自沸，偶分一眼作汤泉。"]},{"t":"观陂水","f":"七言绝句","c":["波缓沤迟似让行，忽然赴壑怒还生。","东归到底谁先后，何用争流作许声。"]},{"t":"观蚁二首 其二","f":"七言绝句","c":["一骑初来只又双，全军突出阵成行。","策勋急报千夫长，渡水还争一苇杭。"]},{"t":"观蚁二首 其一","f":"七言绝句","c":["偶尔相逢细问途，不知何事数迁居。","微躯所馔能多少，一猎归来满后车。"]},{"t":"观荷上雨","f":"七言绝句","c":["细雨沾荷散玉尘，聚成颗颗小珠新。","跳来跳去还收去，祇有琼柈弄水银。"]},{"t":"观棋感兴","f":"七言绝句","c":["本是输棋强作赢，看来终与好棋争。","君看国手无双底，何用旁人救败兵。"]},{"t":"观稼","f":"七言绝句","c":["三年再旱独堪闻，一熟诸村稍作欣。","老子朝朝弄田水，眼看翠浪作黄云。"]},{"t":"访周仲觉夜宿南岭月色粲然晓起路湿闻有夜雨","f":"七言绝句","c":["夜晴那得晓来泥，才见金钲浴绀池。","一阵五更松上雨，元来睡著不曾知。"]},{"t":"访蓬莱老人","f":"七言绝句","c":["不到蓬莱又几时，凉花渐盛暑花稀。","我来不是忘归去，忘却来时况道归。"]},{"t":"过八尺遇雨三首 其三","f":"七言绝句","c":["细雨无声忽有声，乱珠跳作万银钉。","呼僮速买庉村酒，更煮鲈鱼莼菜羹。"]},{"t":"过八尺遇雨三首 其二","f":"七言绝句","c":["去年今日凤山头，儿女团栾争劝酬。","不及松江烟雨里，独搔华发一扁舟。"]},{"t":"过八尺遇雨三首 其一","f":"七言绝句","c":["垂虹登了劣归船，又复毛空暗水天。","节里无多好天色，阑风长雨饯残年。"]},{"t":"过三衢徐载叔采菊载酒夜酌走笔二首 其二","f":"七言绝句","c":["疾风动地雨倾荷，一事商量君信么。","试问糟床与檐溜，雨声何似酒声多。"]},{"t":"过三衢徐载叔采菊载酒夜酌走笔二首 其一","f":"七言绝句","c":["征涂半月客尘黄，今夕初逢一雨凉。","冷笑菊花堪计会，为君八月作重阳。"]},{"t":"过上湖","f":"七言绝句","c":["上湖名是实全非，只合松江雁鹜池。","若与五湖通谱系，澹台湖弟太湖儿。"]},{"t":"过上湖岭望招贤江南北山四首 其四","f":"七言绝句","c":["晓日秋山破格奇，青红明灭舞清漪。","画工著色饶渠巧，便有此容无此姿。"]},{"t":"过上湖岭望招贤江南北山四首 其三","f":"七言绝句","c":["一水横拖两岸峰，千痕万摺碧重重。","谁言老子经行处，身在江山障子中。"]},{"t":"过上湖岭望招贤江南北山四首 其二","f":"七言绝句","c":["岭下看山似伏涛，见人上岭旋争豪。","一登一陟一回顾，我脚高时他更高。"]},{"t":"过上湖岭望招贤江南北山四首 其一","f":"七言绝句","c":["远山高绝近山低，未必低山肯下伊。","定是远山矜狡狯，跳青涌碧角幽奇。"]},{"t":"过下梅","f":"七言绝句","c":["不特山盘水亦回，溪山信美暇徘徊。","行人自趁斜阳急，关得归鸦更苦催。"]},{"t":"过丫头岩","f":"七言绝句","c":["告老身心日互催，又将乌帽点黄埃。","丫头岩下来仍往，四十三年十二回。"]},{"t":"过大皋渡","f":"七言绝句","c":["隔岸横州十里青，黄牛无数放春晴。","船行非与牛相背，何事黄牛却倒行。"]},{"t":"过广济圩三首 其三","f":"七言绝句","c":["桑畴一眼郁金黄，麦垄千机绿锦坊。","诗卷且留灯下看，轿中只好看春光。"]},{"t":"过广济圩三首 其二","f":"七言绝句","c":["两渠水夹一堤宽，个是东皇大御园。","旋插绿杨能几日，新枝已自不胜繁。"]},{"t":"过广济圩三首 其一","f":"七言绝句","c":["圩田岁岁镇逢秋，圩户家家不识愁。","夹路垂杨一千里，风流国是太平州。"]},{"t":"过乌石大小二浪滩俗呼浪为郎因戏作竹枝歌二首 其二","f":"七言绝句","c":["小郎滩下大郎滩，伯仲分司水府关。","谁为行媒教作赘，大姑山与小姑山。"]},{"t":"过乌石大小二浪滩俗呼浪为郎因戏作竹枝歌二首 其一","f":"七言绝句","c":["滩声十里响千鼙，跃雪跳霜入眼奇。","记得年时上滩苦，如今也有下滩时。"]},{"t":"过五里径三首 其三","f":"七言绝句","c":["入山无路出无门，鸟语猿声更断魂。","当处迷涂何处问，一溪引我得前村。"]},{"t":"过五里径三首 其二","f":"七言绝句","c":["野水奔流不小停，知渠何事太忙生。","也无一个人催促，自爱争先落涧声。"]},{"t":"过五里径三首 其一","f":"七言绝句","c":["瘦日当中暖稍回，冷山未许瘴全开。","溪光远隔深深竹，特地穿帘入轿来。"]},{"t":"过双陂","f":"七言绝句","c":["霜后寒溪清更清，冰如溪水水如冰。","闲行也有穷忙事，问讯梅花开未曾。"]},{"t":"过水车铺二首 其二","f":"七言绝句","c":["轿里看书得昼眠，梦中惊浪撼渔船。","觉来书卷风吹乱，忘却前篇与后篇。"]},{"t":"过水车铺二首 其一","f":"七言绝句","c":["尽日涂中断客行，两边山色到云青。","溪光摇碎黄金日，波面跳成白玉星。"]},{"t":"过长峰径遇雨遣闷十绝句 其四","f":"七言绝句","c":["石上菖蒲铁作须，寸根九节许清臞。","安期自是参渠底，却重安期不重渠。"]},{"t":"过长峰径遇雨遣闷十绝句 其八","f":"七言绝句","c":["下到危坡斗处泥，旁临崩岸仄边溪。","不须杜句能驱疟，只诵长峰遣闷诗。"]},{"t":"过长峰径遇雨遣闷十绝句 其二","f":"七言绝句","c":["百里如何一日行，晴天犹自急追程。","山云管得侬愁雨，强做催诗数点声。"]},{"t":"过长峰径遇雨遣闷十绝句 其五","f":"七言绝句","c":["一眼空山空复空，欹芦倒荻雨和风。","却缘小队旌旗过，教得青枫学著红。"]},{"t":"过长峰径遇雨遣闷十绝句 其三","f":"七言绝句","c":["野炊未到也饥嗔，到得炊边却可人。","伞作旅亭泥处坐，水漂地灶雨中薪。"]},{"t":"过长峰径遇雨遣闷十绝句 其六","f":"七言绝句","c":["何须人迹到来曾，点污松风涧水声。","不是先生爱山水，是间却遣阿谁行。"]},{"t":"过长峰径遇雨遣闷十绝句 其十","f":"七言绝句","c":["鳅是虾兄非善地，橘和瓣种带禳灾。","乌椑不熟还无事，小艇难乘莫载来。"]},{"t":"过长峰径遇雨遣闷十绝句 其七","f":"七言绝句","c":["猿藤陂子枉惊吁，未抵长峰小半涂。","今夕前头何许宿，不知出得径来无。"]},{"t":"过长峰径遇雨遣闷十绝句 其一","f":"七言绝句","c":["说著长峰十日愁，夜来发处四更头。","莫令炬火风吹黑，未说红纱绛蜡休。"]},{"t":"过长峰径遇雨遣闷十绝句 其九","f":"七言绝句","c":["出得山来未见村，已知村近稍多田。","坐看云脚都垂地，回望峰头已入天。"]},{"t":"过乐平县","f":"七言绝句","c":["笋蕨都无且则休，菜无半叶也堪羞。","满城都卖雪花荠，昨日愁人未是愁。"]},{"t":"过玉山东三塘五首 其五","f":"七言绝句","c":["缲车香里过征衫，白茧黄丝两两三。","不是秋风上饶路，一生不信有冰蚕。"]},{"t":"过玉山东三塘五首 其四","f":"七言绝句","c":["身行衢信两中间，夹路尖峰面面寒。","只道秋山似春笋，不知春笋似秋山。"]},{"t":"过玉山东三塘五首 其三","f":"七言绝句","c":["赤日中涂绿树阴，肯将碧伞借行人。","片云忽在树头上，失却勋劳庇得身。"]},{"t":"过玉山东三塘五首 其二","f":"七言绝句","c":["远峰隔水醒人心，一半斜阳一半阴。","仙子更衣晚妆束，紫茸领子翠毛衿。"]},{"t":"过玉山东三塘五首 其一","f":"七言绝句","c":["笋舆拾得小凉天，旋与开窗急捲帘。","十里轻云阁秋日，日光移在远峰尖。"]},{"t":"过白沙竹枝歌六首 其六","f":"七言绝句","c":["绝壁临江千尺馀，上头一径过肩舆。","舟人仰看胆俱破，为问行人知得无。"]},{"t":"过白沙竹枝歌六首 其五","f":"七言绝句","c":["昨日下滩风打头，羡他上水似轻鸥。","朝来上水帆都卸，真个轻鸥也自愁。"]},{"t":"过白沙竹枝歌六首 其四","f":"七言绝句","c":["东沿西溯浙江津，去去来来暮复晨。","上岸牵樯推稚子，隔船招手认乡人。"]},{"t":"过白沙竹枝歌六首 其三","f":"七言绝句","c":["绝怜山崦两三家，不种香粳只种麻。","耕遍沿堤锄遍岭，都来能得几生涯。"]},{"t":"过白沙竹枝歌六首 其二","f":"七言绝句","c":["田亩浑无寸尺强，真成水国更山乡。","夹江黄去堤堤粟，一望青来谷谷桑。"]},{"t":"过白沙竹枝歌六首 其一","f":"七言绝句","c":["穹崖绝嶂入云天，乌鹊才飞半壁间。","远渚长汀草如积，牛羊须上最高山。"]},{"t":"过石塘","f":"七言绝句","c":["万石中通一线流，千盘百折过孤舟。","滩头未下人犹笑，下了滩头始觉愁。"]},{"t":"过石磨岭岭皆创为田直至其顶","f":"七言绝句","c":["翠带千镮束翠峦，青梯万级搭青天。","长淮见说田生棘，此地都将岭作田。"]},{"t":"过吕城闸六首 其六","f":"七言绝句","c":["道是行船也未行，老夫误喜可怜生。","要知开闸真消息，记取金钲第二声。"]},{"t":"过吕城闸六首 其五","f":"七言绝句","c":["才闻开闸总驩欣，第一牵夫有喜声。","只得片时天未黑，后来天黑也甘行。"]},{"t":"过吕城闸六首 其四","f":"七言绝句","c":["等到船齐闸欲开，船船捩柁整帆桅。","一船最后知何故，日许时间独不来。"]},{"t":"过吕城闸六首 其三","f":"七言绝句","c":["昨宵听尽棹讴声，愁里无眠达五更。","今夕雨寒泥又滑，作何计会速天明。"]},{"t":"过吕城闸六首 其二","f":"七言绝句","c":["泊船到得暮钟时，等待诸船不肯齐。","等得船齐方过闸，又须五鼓到荆溪。"]},{"t":"过吕城闸六首 其一","f":"七言绝句","c":["闸头洲子许团栾，古庙萧条暮雨寒。","榆柳千株无半叶，冬青一树碧琅玕。"]},{"t":"过安仁市得风挂帆二首 其二","f":"七言绝句","c":["西望柯山正蔚蓝，衢州只在此山南。","却愁路尽风犹剩，回纳清风与破帆。"]},{"t":"过安仁市得风挂帆二首 其一","f":"七言绝句","c":["明发山溪一雨馀，昨来暑气半分无。","何人道是三衢远，挂起东风十幅蒲。"]},{"t":"过百家渡四绝句 其三","f":"七言绝句","c":["柳子祠前春已残，新晴特地却春寒。","疏篱不与花为护，只为蛛丝作网竿。"]},{"t":"过百家渡四绝句 其四","f":"七言绝句","c":["一晴一雨路乾湿，半淡半浓山叠重。","远草平中见牛背，新秧疏处有人踪。"]},{"t":"过百家渡四绝句 其二","f":"七言绝句","c":["园花落尽路花开，白白红红各自媒。","莫问早行奇绝处，四方八面野香来。"]},{"t":"过百家渡四绝句 其一","f":"七言绝句","c":["出得城来事事幽，涉湘半济值渔舟。","也知渔父趁鱼急，翻著春衫不裹头。"]},{"t":"过西坑","f":"七言绝句","c":["乾风无那湿云何，吹不能开只助他。","野水落溪生蟹眼，一番过了一番多。"]},{"t":"过杨二渡三首 其三","f":"七言绝句","c":["柳见风时舞便轻，解将衮遍趁莺声。","道它誇逞腰肢著，风罢元来倦不胜。"]},{"t":"过杨二渡三首 其二","f":"七言绝句","c":["两日山寻尽野花，今晨水眺始桑麻。","春风娇得千垂柳，恰限身才个个斜。"]},{"t":"过杨二渡三首 其一","f":"七言绝句","c":["春迹无痕可得寻，不将诗眼看春心。","莺边杨柳鸥边草，一日青来一日深。"]},{"t":"过杨子桥二首 其一","f":"七言绝句","c":["浪说春归已四旬，淮南元自不知春。","明朝却是中和节，野次谁怜寂寞人。"]},{"t":"过杨子桥二首 其二","f":"七言绝句","c":["客愁满目政无聊，忽报船经杨子桥。","未到江南心已喜，隔江山色碧相招。"]},{"t":"过沙头三首 其三","f":"七言绝句","c":["昨来飞橹下危泷，不敢窥窗只闭窗。","莫叹江平船不进，只将行役当游江。"]},{"t":"过沙头三首 其二","f":"七言绝句","c":["过了沙头渐有村，地平江阔气清温。","暗潮已到无人会，只有篙师识水痕。"]},{"t":"过沙头三首 其一","f":"七言绝句","c":["非烟非雨淡濛濛，深闭窗扉护晚风。","船外山光帘里翠，岸头花影镜中红。"]},{"t":"过苏岩","f":"七言绝句","c":["仰望苍岩高更深，岩中佳处著禅林。","琼泉万仞峰头落，一滴泉声一醒心。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其七","f":"七言绝句","c":["山穷喜见一平川，不似林中不识天。","只出此山灾便散，何须更问小行年。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其四","f":"七言绝句","c":["为怜上轿齧人肩，下轿行来脚底穿。","客子心心愁欲暮，碧云偏作半阴天。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其二","f":"七言绝句","c":["草光叶润亦清佳，翠里生香不是花。","一事说来人不信，蕨长如树蚓如蛇。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其三","f":"七言绝句","c":["芦深石路旋芟开，藤絓肩舆却倒回。","兰蕙连山为谁好，芭蕉满谷不缘栽。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其六","f":"七言绝句","c":["涧泉劝我出山迟，曲曲遮留步步随。","泉自多情侬自闷，今宵会有出山时。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其一","f":"七言绝句","c":["林中亭午始微明，枫倒杉倾满路横。","黄叶青苔深一丈，先生却爱此中行。"]},{"t":"过陂子径五十馀里乔木蔽天遣闷柒绝句 其五","f":"七言绝句","c":["晚风寂寂树阴阴，松不悲鸣竹不吟。","只有清泉逢白石，向人刺口说山林。"]},{"t":"过陈公径二首 其二","f":"七言绝句","c":["江行十日厌船迟，却换篮舆踏路泥。","江水别来才两日，陈公径下再相随。"]},{"t":"过陈公径二首 其一","f":"七言绝句","c":["去岁陈公径里松，船中仰看爱松风。","只今身在松风里，下看江船西复东。"]},{"t":"过京口以南见竹林","f":"七言绝句","c":["行从江北别梅兄，归到江南见竹君。","却忆西湖湖上寺，梅花如雪竹如云。"]},{"t":"过周陂江","f":"七言绝句","c":["溪暖无冰可得销，清波白石小鱼跳。","忽逢寸碧翩然起，翡翠惊飞上柳条。"]},{"t":"过宝应县新开湖十首 其十","f":"七言绝句","c":["五湖佳处是荒寒，却为无山水更宽。","归去江南无此景，未须吃饭且来看。"]},{"t":"过宝应县新开湖十首 其六","f":"七言绝句","c":["雨里楼船即钓矶，碧云便是绿蓑衣。","沧波万顷平如镜，一只鸬鹚贴水飞。"]},{"t":"过宝应县新开湖十首 其五","f":"七言绝句","c":["湖堤插柳早青葱，犹带隋家旧土风。","莫笑千株尺来许，看渠揽尽夕阳红。"]},{"t":"过宝应县新开湖十首 其四","f":"七言绝句","c":["渔家可是厌尘嚣，结屋圆沙最尽梢。","外面更栽杨柳树，上头无数鹭鸶巢。"]},{"t":"过宝应县新开湖十首 其二","f":"七言绝句","c":["细雨初如弄隙尘，须臾化作舞空蚊。","作团面旋还分散，只见轻烟与薄云。"]},{"t":"过宝应县新开湖十首 其一","f":"七言绝句","c":["寒里船门不可开，试开一望兴悠哉。","空濛烟雨微茫树，都向湖光外面来。"]},{"t":"过建封寺下连鱼滩二首 其二","f":"七言绝句","c":["梦里篙师忽叫滩，老夫惊杀起来看。","前船过尽知无虑，末后孤舟胆自寒。"]},{"t":"过建封寺下连鱼滩二首 其一","f":"七言绝句","c":["江收众水赴单槽，石壁当流斗雪涛。","将取危舟飞过去，黄头郎只两三篙。"]},{"t":"过招贤渡四首 其四","f":"七言绝句","c":["岸上行人莫叹劳，长年三老政呼号。","也知滩恶船难上，仰踏桅竿卧著篙。"]},{"t":"过招贤渡四首 其三","f":"七言绝句","c":["倦游客子自无聊，不是江山景不饶。","危岸崩沙新改路，断渠横石自成桥。"]},{"t":"过招贤渡四首 其二","f":"七言绝句","c":["一江故作两江分，立杀呼船隔岸人。","柳上青虫宁许劣，垂丝到地却回身。"]},{"t":"过招贤渡四首 其一","f":"七言绝句","c":["归舟曾被此滩留，说著招贤梦亦愁。","五月雪飞人不信，一来滩下看涛头。"]},{"t":"过松源晨炊漆公店六首 其五","f":"七言绝句","c":["莫言下岭便无难，赚得行人错喜欢。","政入万山围子里，一山放出一山拦。"]},{"t":"过松源晨炊漆公店六首 其四","f":"七言绝句","c":["日高谷底始微暄，岚翠依然透骨寒。","说与行人忙底事，金鸡声里促银鞍。"]},{"t":"过松源晨炊漆公店六首 其二","f":"七言绝句","c":["山北溪声一路迎，山南溪响送人行。","也知流向金陵去，若过金陵莫寄声。"]},{"t":"过罗溪南望抚州泉岭","f":"七言绝句","c":["泉岭诸峰太劣生，与侬争走学侬行。","苍官总上山头去，一色前驱娖翠旌。"]},{"t":"过虎头矶","f":"七言绝句","c":["虎卧中流扼两涯，目光须怒首仍回。","真阳峡里君须记，个是瞿塘滟滪堆。"]},{"t":"过金台天气顿热三首 其三","f":"七言绝句","c":["入到船中气郁蒸，出来船外日侵陵。","绿波欲沸清何在，青盖张来似不曾。"]},{"t":"过金台天气顿热三首 其二","f":"七言绝句","c":["日晒船篷四面炊，几时却得出船时。","江西未到何须恨，且到三衢也自奇。"]},{"t":"过金台天气顿热三首 其一","f":"七言绝句","c":["江云山翠借朝凉，晚日晴波挟暑光。","旧说长江无六月，暮春已自不禁当。"]},{"t":"过青阳县望九华山云中不真来早大雾竟不见其全三首 其三","f":"七言绝句","c":["懊恼西来不见山，五更指准月中看。","却将香雾宽裁幕，性燥和天总一漫。"]},{"t":"过青阳县望九华山云中不真来早大雾竟不见其全三首 其二","f":"七言绝句","c":["肩舆过了九华西，恨杀秋云故故低。","遮尽奇峰时放出，逐峰放出不教齐。"]},{"t":"过青阳县望九华山云中不真来早大雾竟不见其全三首 其一","f":"七言绝句","c":["山长百里玉孱颜，百里何缘尽好山。","只是县前青一簇，九芙蓉出五云间。"]},{"t":"过临平二首 其二","f":"七言绝句","c":["人家点缀荻花林，水绕阶除雪湿衿。","最是疏篱与脩竹，脚根半入小河深。"]},{"t":"过临平二首 其一","f":"七言绝句","c":["临平放目渺无涯，莲荡蘋汀不钉牌。","雪后轻船四捞漉，断芦残荻总成柴。"]},{"t":"过临平莲荡四首 其四","f":"七言绝句","c":["人家星散水中央，十里芹羹菰饭香。","想得薰风端午后，荷花世界柳丝乡。"]},{"t":"过临平莲荡四首 其三","f":"七言绝句","c":["朝来采藕夕来渔，水种菱荷岸种芦。","寒浪落时分作荡，新流涨后合成湖。"]},{"t":"过临平莲荡四首 其二","f":"七言绝句","c":["莲荡中央劣露沙，上头便著野人家。","篱边随处插垂柳，檐下小船萦钓车。"]},{"t":"过临平莲荡四首 其一","f":"七言绝句","c":["莲荡层层镜样方，春来嫩玉斩新光。","角头一一张芦箔，不遣鱼虾过别塘。"]},{"t":"过南荡三首 其三","f":"七言绝句","c":["政好行时莫懒行，犹寒未热雨初晴。","江西休问何时到，已离南屏第一程。"]},{"t":"过南荡三首 其二","f":"七言绝句","c":["近岫遥峰翠作围，平田小港碧行迟。","垂杨一径深深去，阿那人家住得奇。"]},{"t":"过南荡三首 其一","f":"七言绝句","c":["秧才束发幼相依，麦已掀髯喜可知。","笑杀槿篱能耐事，东扶西倒野酴醾。"]},{"t":"过显济庙前石矶竹枝词二首 其一","f":"七言绝句","c":["石矶作意恼舟人，束起波涛遣怒奔。","撑折万篙浑不枉，石矶赢得万馀痕。"]},{"t":"过显济庙前石矶竹枝词二首 其二","f":"七言绝句","c":["大矶愁似小矶愁，篙稍宽时船即流。","撑得篙头都是血，一矶又复在前头。"]},{"t":"过洛社望南湖暮景三首 其三","f":"七言绝句","c":["一阵南风似箭来，蒲帆飞上最高桅。","两边岸柳都奔走，不及追船各自回。"]},{"t":"过洛社望南湖暮景三首 其二","f":"七言绝句","c":["暮烟如雨雨如烟，一把珠帘隔远山。","帘影渐浓山渐淡，恍然移入画屏间。"]},{"t":"过洛社望南湖暮景三首 其一","f":"七言绝句","c":["南湖隔水见渔灯，雁落芦汀八字横。","对面双峰烟雨里，双峰外面是宜兴。"]},{"t":"过神助桥亭","f":"七言绝句","c":["下轿浑将野店看，只惊脚底水声寒。","不知竹外长江近，忽有高桅出寸竿。"]},{"t":"过润陂桥三首 其二","f":"七言绝句","c":["却忆庚寅侍板舆，过桥桥断费人扶。","重来一见新桥了，泪湿秋风眼欲枯。"]},{"t":"过真阳峡六首 其六","f":"七言绝句","c":["百滩千港几涛波，聚入真阳也未多。","若遣峡山生塞了，不知江水倒流么。"]},{"t":"过真阳峡六首 其五","f":"七言绝句","c":["榕树阴中一苇横，鹧鸪声里数峰青。","南人到此亦肠断，一是南人作么生。"]},{"t":"过真阳峡六首 其四","f":"七言绝句","c":["堪笑跳波数百滩，如何入峡顿无喧。","人言此峡如巴峡，只欠三声堕泪猿。"]},{"t":"过真阳峡六首 其三","f":"七言绝句","c":["仰见青天尺许青，无波江水不胜平。","只惊白昼山竹裂，杜宇初闻第一声。"]},{"t":"过真阳峡六首 其二","f":"七言绝句","c":["莫道无人径亦穷，尚馀碧筱伴青枫。","白云不是从天降，坐看生从翠崦中。"]},{"t":"过真阳峡六首 其一","f":"七言绝句","c":["玉削双崖一水通，一重一掩更重重。","平生山水看多少，最爱真阳第二峰。"]},{"t":"过秦淮","f":"七言绝句","c":["晓过新桥启轿窗，要看春水弄春光。","东风作意惊诗眼，搅乱垂杨两岸黄。"]},{"t":"过莺斗湖三首 其三","f":"七言绝句","c":["春来已自两旬馀，欲借春看未见渠。","烟树隔湖三十里，寒梢依旧向人疏。"]},{"t":"过莺斗湖三首 其二","f":"七言绝句","c":["忽闻江上四驩呼，知近吴江莺斗湖。","火炬灯笼不须办，使家行住按程涂。"]},{"t":"过莺斗湖三首 其一","f":"七言绝句","c":["画舫如山水上奔，小船似鸭避河滨。","红旗青盖鸣钲处，都是迎来送往人。"]},{"t":"过望亭六首 其六","f":"七言绝句","c":["晴河不似雨中看，晴里波纹只簟斑。","却是雨河新样巧，簟间织出小金镮。"]},{"t":"过望亭六首 其五","f":"七言绝句","c":["朝朝暮暮见长河，见了长河只厌它。","却爱画师能画水，不看死浪与生波。"]},{"t":"过望亭六首 其四","f":"七言绝句","c":["两岸山林总解行，一层送了一层迎。","天公收却春风面，拈出酸寒水墨屏。"]},{"t":"过望亭六首 其三","f":"七言绝句","c":["暮鸿作阵猛相追，风有何忙也急吹。","恼杀诗人真枉却，云窗雾阁不曾知。"]},{"t":"过望亭六首 其二","f":"七言绝句","c":["窗间雨打泪新斑，破处风来叫得酸。","若是诗人都富贵，遣谁忍饿遣谁寒。"]},{"t":"过望亭六首 其一","f":"七言绝句","c":["望亭昔岁过归船，柳为蹁跹杏为妍。","今日溪山浑似旧，雪芦风荻两萧然。"]},{"t":"过阊门溪","f":"七言律诗","c":["黟祁二邑水分源，到此同流怒政奔。","忽值两山盘作峡，更峨双石插为门。","中通翠浪才容线，仰看青天细似盆。","滟滪瞿唐姑未问，祗经此险已销魂。"]},{"t":"过黄巢矶","f":"七言绝句","c":["黄巢矶与白沙滩，只是闻名已胆寒。","自笑南来三换岁，一年一度犯惊湍。"]},{"t":"过景星山山顶一石孤立又名突星山","f":"词","c":["山头孤立玉竛?，天上何年堕景星。","四面万峰非不峻，如何只是一峰青。"]},{"t":"过新开湖五首 其五","f":"七言绝句","c":["远远人烟点树梢，船门一望一魂消。","几行野鸭数声雁，来为湖天破寂寥。"]},{"t":"过新开湖五首 其四","f":"七言绝句","c":["一鸥得得隔湖来，瞥见鱼儿眼顿开。","只为水深难立脚，翩然飞下却飞回。"]},{"t":"过新开湖五首 其三","f":"七言绝句","c":["白苇黄芦尚带秋，长风远水几时休。","愁人对著君休问，不是愁人也作愁。"]},{"t":"过新开湖五首 其二","f":"七言绝句","c":["渔郎艇子入重湖，老眼殷勤看著渠。","看去看来成怪事，化为独雁立横芦。"]},{"t":"过新开湖五首 其一","f":"七言绝句","c":["奇哉万顷水精盆，一线青罗缘却唇。","只有向南接天去，更和一线也无痕。"]},{"t":"过鼓鸣林小雨二首 其二","f":"七言绝句","c":["下泷小舫戴尖篷，未论千峰与万峰。","只是舟人头上笠，也堪收入画图中。"]},{"t":"过鼓鸣林小雨二首 其一","f":"七言绝句","c":["淅淅船篷雨点声，疏疏江面縠纹生。","石峰斗起三千丈，身在假山园里行。"]},{"t":"过翥山渡","f":"七言绝句","c":["千重溪水万重山，半月深行井底天。","井外还来天大在，江心一眼四无边。"]},{"t":"过蕉坑","f":"七言绝句","c":["枫叶乾馀尚小红，苕花飞尽不留茸。","经旬欲雪还无雪，只作清寒恼杀侬。"]},{"t":"过霸东石桥桐花尽落","f":"七言绝句","c":["老去能逢几个春，今年春事不关人。","红千紫百何曾梦，压尾桐花也作尘。"]},{"t":"问月二首 其二","f":"五言绝句","c":["月入云中去，呼他不出来。","明宵教老子，何面更相陪。"]},{"t":"问月二首 其一","f":"五言绝句","c":["月色幸自好，元无半点云。","移床来一看，云月两昏昏。"]},{"t":"问春二首 其二","f":"七言绝句","c":["元日春回不道迟，匆匆未遣万花知。","道山堂下红梅树，速借晴光染一枝。"]},{"t":"问春二首 其一","f":"七言绝句","c":["今岁春归不小心，合将消息报园林。","苏公堤上千株柳，二月犹悭半缕金。"]},{"t":"馀干溯流至安仁","f":"七言绝句","c":["半篙新涨满帆风，两岸千山一抹中。","惭愧棹郎能袖手，若非袖手更无功。"]},{"t":"冻蝇","f":"七言绝句","c":["隔窗偶见负暄蝇，双脚挼挲弄晓晴。","日影欲移先会得，忽然飞落别窗声。"]},{"t":"初九夜月二首 其二","f":"七言绝句","c":["也知月姊是天姝，天上人间绝世无。","雾刷云撩何不可，却须插一水精梳。"]},{"t":"初九夜月二首 其一","f":"七言绝句","c":["珍重姮娥住广寒，不餐火食不餐烟。","秋空拾得一团饼，随手如何失半边。"]},{"t":"初入淮河四绝句 其二","f":"七言绝句","c":["刘岳张韩宣国威，赵张二相筑皇基。","长淮咫尺分南北，泪湿秋风欲怨谁。"]},{"t":"初入淮河四绝句 其四","f":"七言绝句","c":["中原父老莫空谈，逢著王人诉不堪。","却是归鸿不能语，一年一度到江南。"]},{"t":"初入淮河四绝句 其一","f":"七言绝句","c":["船离洪泽岸头沙，入到淮河意不佳。","何必桑乾方是远，中流以北即天涯。"]},{"t":"初入淮河四绝句 其三","f":"七言绝句","c":["两岸舟船各背驰，波痕交涉亦难为。","只馀鸥鹭无拘管，北去南来自在飞。"]},{"t":"初入筠州界高冈铺","f":"七言绝句","c":["千尺霜松夹道周，国初凉伞至今留。","筠州旧是朝天路，六十年来行信州。"]},{"t":"初四日晨炊横翠亭","f":"七言绝句","c":["近看三峰失一峰，其馀都与昨来同。","多情横翠亭前玉，伴我同行两日中。"]},{"t":"初秋戏作山居杂兴俳体十二解 其八","f":"七言绝句","c":["自暴群书旧间新，净揩白醭拂黄尘。","莫羞空腹无丁字，且免秋阳晒杀人。"]},{"t":"初秋戏作山居杂兴俳体十二解 其七","f":"七言绝句","c":["七月初头六月阑，老夫日醉早禾酸。","莫将煮吃只生吃，更泄天机向达官。"]},{"t":"初秋戏作山居杂兴俳体十二解 其六","f":"七言绝句","c":["甑头云子喜尝新，红嚼桃花白嚼银。","笑杀官人浪驩喜，村人残底到官人。"]},{"t":"初秋戏作山居杂兴俳体十二解 其二","f":"七言绝句","c":["蚤起翻成坐睡昏，鹊声唤我步前轩。","竹扉日隙针来大，射壁千千弹子痕。"]},{"t":"初秋戏作山居杂兴俳体十二解 其九","f":"七言绝句","c":["独对秋筠倒晚壶，喜无吏舍四歌呼。","柳梢一壳兹缁滓，屋角双斑谷古孤。"]},{"t":"初秋戏作山居杂兴俳体十二解 其一","f":"七言绝句","c":["暑入秋来午更强，风排雨遣晓差凉。","如何绕砌千枝蕙，只是开门一阵香。"]},{"t":"初秋戏作山居杂兴俳体十二解 其三","f":"七言绝句","c":["暑后花枝输了春，杂英小巧亦忺人。","素馨解点粉描笔，金凤爱垂鸡下唇。"]},{"t":"初秋戏作山居杂兴俳体十二解 其十一","f":"七言绝句","c":["卓午从它火伞张，先生别有睡为乡。","竹床移遍两头冷，瓦枕翻来四面凉。"]},{"t":"初秋戏作山居杂兴俳体十二解 其四","f":"七言绝句","c":["风骚开国胙寒岩，劳绩批书课翠岚。","梨子要肥千取百，菊苗每摘一生三。"]},{"t":"初秋行圃四首 其四","f":"七言绝句","c":["落日无情最有情，遍催万树暮蝉鸣。","听来咫尺无寻处，寻到旁边却不声。"]},{"t":"初秋行圃四首 其三","f":"七言绝句","c":["花梢飞下两鸣鸠，欲住还行行复留。","拾得来禽吞不得，啄来啄去竟成休。"]},{"t":"初秋行圃四首 其二","f":"七言绝句","c":["小小园亭亦自佳，晚云过雨却成霞。","烂开栀子浑如雪，已熟来禽尚带花。"]},{"t":"初秋行圃四首 其一","f":"七言绝句","c":["今年六月不胜凉，七月炎蒸不可当。","一阵秋风初过雨，个般天气好烧香。"]},{"t":"初秋暮雨","f":"七言绝句","c":["禾穟轻黄尚浅青，村舂已报隔林声。","忽惊暮色翻成晓，仰见双虹雨外明。"]},{"t":"初夏即事十二解 其四","f":"七言绝句","c":["从教节序暗相催，历日尘生懒看来。","却是石榴知立夏，年年此日一花开。"]},{"t":"初夏即事十二解 其九","f":"七言绝句","c":["更无一个子规啼，寂寂空山花自飞。","啼得春归它便去，元来不是劝人归。"]},{"t":"初夏即事十二解 其二","f":"七言绝句","c":["瑞香端合谱离骚，有子传芳韵亦高。","失却薰笼红锦被，化为矮树紫樱桃。"]},{"t":"初夏即事十二解 其六","f":"七言绝句","c":["密有花红绿刺长，似来作伴石榴芳。","金樱身子玫瑰脸，更吃饧枝蜜果香。"]},{"t":"初夏即事十二解 其十一","f":"七言绝句","c":["狭斜只解赏春红，秋菊冬梅不负公。","我道四时俱富贵，一杯催唤藕花风。"]},{"t":"初夏即事十二解 其十二","f":"七言绝句","c":["王家麈柄绿琼香，萱草偷来柄更长。","藏却柿红缨拂子，菖蒲节里放风光。"]},{"t":"初夏即事十二解 其一","f":"七言绝句","c":["莲叶头巾道样裁，仙桃扇子午时回。","扑蝇堕地犹能旋，闭阁生尘底处来。"]},{"t":"初夏即事十二解 其三","f":"七言绝句","c":["百日田乾田父愁，只销一雨百无忧。","更无人惜田中水，放下清溪恣意流。"]},{"t":"初夏病起晓步东园二首 其二","f":"七言绝句","c":["病起乌藤强自扶，三三径里晓晴初。","莺声只在花梢近，行去行来不见渠。"]},{"t":"初夏病起晓步东园二首 其一","f":"七言绝句","c":["低枝碧李压人头，过雨黄梅满道周。","红日漏云初试暑，绿阴酣露已偷秋。"]},{"t":"闲居初夏午睡起二绝句 其一","f":"七言绝句","c":["梅子留酸软齿牙，芭蕉分绿与窗纱。","日长睡起无情思，闲看儿童捉柳花。"]},{"t":"初离常州夜宿小井清晓放船三首 其三","f":"七言绝句","c":["春旱愁人是去年，如今说著尚心酸。","篙师莫遣船迟著，见说苏州好牡丹。"]},{"t":"初离常州夜宿小井清晓放船三首 其二","f":"七言绝句","c":["晨炊只煮野蔬汤，更拣鲜鱼买一双。","病眼未能禁晓日，西窗莫闭闭东窗。"]},{"t":"初离常州夜宿小井清晓放船三首 其一","f":"七言绝句","c":["拦街父老不教行，出得东门已一更。","一事新来偏可意，梦中闻打放船钲。"]},{"t":"初寒","f":"七言绝句","c":["欲雨还晴又作阴，添衣已减却重寻。","绝知不晚新寒到，更用先来破客心。"]},{"t":"含笑","f":"七言绝句","c":["大笑何如小笑香，紫花不似白花妆。","不知自笑还相笑，笑杀人来断杀肠。"]},{"t":"听雨","f":"七言绝句","c":["归舟昔岁宿严陵，雨打疏篷听到明。","昨夜茅檐疏雨作，梦中唤作打篷声。"]},{"t":"听蝉八绝句 其七","f":"七言绝句","c":["望帝啼春夜更多，不知蝉意却如何。","还来入夜便无语，明日将诗理会它。"]},{"t":"听蝉八绝句 其三","f":"七言绝句","c":["渠与斜阳有底雠，千冤万恨诉清秋。","更从谁子做头抵，只放斜阳不落休。"]},{"t":"听蝉八绝句 其八","f":"七言绝句","c":["罪过渠侬商略秋，从朝至暮不曾休。","莫嫌入夜还休去，自有寒蛩替说愁。"]},{"t":"听蝉八绝句 其五","f":"七言绝句","c":["说露谈风有典章，咏秋吟夏入宫商。","蝉声无一些烦恼，自是愁人枉断肠。"]},{"t":"听蝉八绝句 其一","f":"七言绝句","c":["披襟散发晚风清，细细孤斟缓缓行。","道是江东官事冗，绿杨阴里听蝉声。"]},{"t":"听蝉八绝句 其四","f":"七言绝句","c":["一壳空空纸样轻，风前却有许多声。","叫来叫去浑无事，叫到诗人白发生。"]},{"t":"听蝉八绝句 其六","f":"七言绝句","c":["乍来忽去为谁忙，短气抽教强作长。","道是渠侬声不歇，一吟一续万低昂。"]},{"t":"听蝉八绝句 其二","f":"七言绝句","c":["一只初来报早秋，又添一只说新愁。","两蝉对语双垂柳，知斗先休斗后休。"]},{"t":"张子仪太社折送秋日海棠二首 其二","f":"七言绝句","c":["木蕖篱菊总无光，秋色今年付海棠。","为底夜深花不睡，翠纱袖上月和霜。"]},{"t":"张子仪太社折送秋日海棠二首 其一","f":"七言绝句","c":["新样西风较劣些，重阳还放海棠花。","春红更把秋霜洗，且道精神佳不佳。"]},{"t":"张仲良久约出郊以诗督之二首 其一","f":"七言绝句","c":["百花亭下花如海，子厚宅前溪似油。","幕下风流法曹掾，坐窗犹未作遨头。"]},{"t":"张仲良久约出郊以诗督之二首 其二","f":"七言绝句","c":["只道今春不肯晴，已晴谁遣不郊行。","忍违花底提壶语，不虑屋头鸠妇鸣。"]},{"t":"张尉惠诗和韵谢之三首 其三","f":"七言绝句","c":["老去才情半掬悭，不愁不退岂愁前。","清风明月无拘管，与子分张更一年。"]},{"t":"张尉惠诗和韵谢之三首 其二","f":"七言绝句","c":["软红尘里眼曾开，苦被新诗猛唤回。","借问锦心能底巧，更从月胁摘将来。"]},{"t":"张尉惠诗和韵谢之三首 其一","f":"七言绝句","c":["下笔生波便百川，字间句里总超然。","读来清气凉人骨，六月真成九月天。"]},{"t":"忧患感叹二首 其一","f":"五言绝句","c":["醉里还多感，醒来却更愁。","醉醒都不是，愁感几时休。"]},{"t":"怀山庄子仁侄二首 其二","f":"七言绝句","c":["吾家小阮未西归，日日相从郡圃嬉。","黄菊拒霜今笑我，先生也有独来时。"]},{"t":"怀山庄子仁侄二首 其一","f":"七言绝句","c":["危亭独上忽徬徨，欠个山庄堕我傍。","却是向来相聚日，老怀未解忆山庄。"]},{"t":"折花","f":"七言绝句","c":["指似青童折海棠，繁枝仍要艳花房。","痴眉騃眼生疏手，颤脱花房闷一场。"]},{"t":"攸山望石臼湖","f":"七言绝句","c":["雨中深闭轿窗纱，惊见孤光射眼花。","一顾平湖山尽处，碧铜镜外走青蛇。"]},{"t":"旱后喜雨四首 其四","f":"七言绝句","c":["密洒疏飘尽自由，通宵到晓未须休。","平生愁听芭蕉雨，何事今来听不愁。"]},{"t":"旱后喜雨四首 其三","f":"七言绝句","c":["竟夏兴云只苦风，入秋今雨稍宜农。","怪来霹雳轰枯树，知向前山起卧龙。"]},{"t":"旱后喜雨四首 其二","f":"七言绝句","c":["检校西畴首忍回，雨佳小恨较迟来。","抄云淅玉何曾梦，只拟禾孙作粥材。"]},{"t":"旱后喜雨四首 其一","f":"七言绝句","c":["云头造次便能开，雨脚商量半欲来。","旧日催诗元要雨，如今雨却索诗催。"]},{"t":"李与贤来访自言所居幽胜甚似剡溪因以似剡名其庵出闲居五咏因次其韵五首 其五","f":"七言绝句","c":["漫浪江湖天一方，故人不见两三霜。","对床说尽平生话，黄叶声中秋夜长。"]},{"t":"李与贤来访自言所居幽胜甚似剡溪因以似剡名其庵出闲居五咏因次其韵五首 其四","f":"七言绝句","c":["见说幽居绕万松，栽梅能白杏能红。","人行剡曲溪山里，家住辋川图画中。"]},{"t":"李与贤来访自言所居幽胜甚似剡溪因以似剡名其庵出闲居五咏因次其韵五首 其三","f":"七言绝句","c":["溪上新桥是凤林，残风剩雨做秋阴。","先生小试南风手，写得一川山水音。"]},{"t":"李与贤来访自言所居幽胜甚似剡溪因以似剡名其庵出闲居五咏因次其韵五首 其二","f":"七言绝句","c":["山似剡溪溪似油，人如诗句句如秋。","无边春里花饶笑，有底忙时草唤愁。"]},{"t":"李与贤来访自言所居幽胜甚似剡溪因以似剡名其庵出闲居五咏因次其韵五首 其一","f":"七言绝句","c":["玉壶冰段露金茎，未抵闲居五咏清。","休道曹诗成七步，不须三步已诗成。"]},{"t":"李花","f":"七言绝句","c":["李花宜远更宜繁，惟远惟繁始足看。","莫学江梅作疏影，家风各自一般般。"]},{"t":"杨花","f":"七言绝句","c":["只道垂杨管别离，杨花一去不思归。","浮踪浪迹无拘束，飞到蛛丝也不飞。"]},{"t":"极暑题钓雪","f":"七言绝句","c":["暑中北阁望南窗，将谓南窗分外凉。","到得南窗还更热，芙蕖和蕊落幽香。"]},{"t":"沙溪江亭","f":"七言绝句","c":["渔舟竟日不知还，水碓无人也不闲。","斫却江头一丛柳，当愁无地著江山。"]},{"t":"皂角林","f":"七言绝句","c":["水漾霜风冷客襟，苔封战骨动人心。","河边独树知何木，今古相传皂角林。"]},{"t":"社雨","f":"七言绝句","c":["时节从来好雨知，今朝社日顿霏微。","落花只得春风舞，湿却残香不得飞。"]},{"t":"芙蓉盛开戏简子文克信","f":"七言绝句","c":["芙蓉得雨一齐开，开尽秋花客不来。","到得客来花已老，晚妆犹可两三杯。"]},{"t":"芭蕉三首 其三","f":"七言绝句","c":["檐牙窗额两三株，只欠王维画雪图。","开卷不题元字脚，碧窗圜蜡有如无。"]},{"t":"芭蕉三首 其二","f":"七言绝句","c":["萧萧洒洒复婷婷，一半风流一半清。","不为暑窗添午荫，却来愁枕作秋声。"]},{"t":"芭蕉三首 其一","f":"七言绝句","c":["骨相玲珑透八窗，花头倒挂紫荷香。","绕身无数青罗扇，风不来时也不凉。"]},{"t":"花下夜饮","f":"七言绝句","c":["夜深移入小杯盘，回首花枝不忍看。","岂与海棠情分薄，老夫自是怯春寒。"]},{"t":"花果","f":"七言绝句","c":["野花山果绝芳馨，借问行人不识名。","蜂蝶行粮猿鹤饭，一生口分两无争。"]},{"t":"走笔和张功父玉照堂十绝句 其五","f":"七言绝句","c":["红红紫紫尽纭纭，韵处终输庾岭君。","未说玉花冰雪骨，新阴先绿半春云。"]},{"t":"走笔和张功父玉照堂十绝句 其六","f":"七言绝句","c":["常年十月未花开，雪片今年九月回。","便有早梅随早雪，一枝笑看万花摧。"]},{"t":"走笔和张功父玉照堂十绝句 其四","f":"七言绝句","c":["梅诗脱口已流传，要趁梅前更雪前。","唤醒诚斋山里梦，落英如雪枕砖眠。"]},{"t":"走笔和张功父玉照堂十绝句 其八","f":"七言绝句","c":["老见千花眼便昏，忆梅长为赋招魂。","只今身住西湖上，不羡淮南岭上村。"]},{"t":"走笔和张功父玉照堂十绝句 其一","f":"七言绝句","c":["健青新走一梢长，外日东风引得狂。","定自今番春色里，新枝别样占年光。"]},{"t":"走笔和张功父玉照堂十绝句 其二","f":"七言绝句","c":["年年春信遣人疑，赚出诗人枉觅诗。","著意探梅偏不发，月斜偶见一横枝。"]},{"t":"走笔和张功父玉照堂十绝句 其七","f":"七言绝句","c":["今岁略无霜报寒，忽然一夜雪漫漫。","雪花要作梅花地，十月早梅和雪看。"]},{"t":"走笔和张功父玉照堂十绝句 其十","f":"七言绝句","c":["老懒狂吟不要工，爱君七字晋唐风。","更烦传语梅花道，火急齐开小至中。"]},{"t":"走笔和张功父玉照堂十绝句 其三","f":"七言绝句","c":["騃女痴儿总爱梅，道人衲子亦争栽。","何如雪后琼瑶迹，印记诗人独自来。"]},{"t":"走笔和张功父玉照堂十绝句 其九","f":"七言绝句","c":["玉照堂中瀹早茶，下临溪水织纹纱。","十诗小试春风手，催发溪梅两岸花。"]},{"t":"走笔送济翁弟过浙东谒丘宗卿二首 其二","f":"七言绝句","c":["若见丘迟问老夫，为言臞似向来臞。","更将双眼寄吾弟，带去稽山看鉴湖。"]},{"t":"走笔送济翁弟过浙东谒丘宗卿二首 其一","f":"七言绝句","c":["出省还家思已昏，答书见客腹仍烦。","政愁独酌无佳客，家里诗人忽扣门。"]},{"t":"辛酉正月十一日东园桃李盛开","f":"七言绝句","c":["千万重山见复遮，两三点雨直还斜。","行穿锦巷入雪巷，看尽桃花到李花。"]},{"t":"近峡","f":"五言绝句","c":["望峡初愁远，当前忽不知。","如何船进处，却在棹停时。"]},{"t":"近腊暄甚","f":"七言绝句","c":["霜日知春有信归，腊前偷暖漏春晖。","北风也剪寒梢叶，吹作鹅黄乱蝶飞。"]},{"t":"进贤初食白菜因名之以水精菜云二首 其二","f":"七言绝句","c":["江西菜甲要霜栽，逗到炎天总不佳。","浪说水菘水芦菔，硬根瘦叶似生柴。"]},{"t":"进贤初食白菜因名之以水精菜云二首 其一","f":"七言绝句","c":["新舂云子滑流匙，更嚼冰蔬与雪齑。","灵隐山前水精菜，近来种子到江西。"]},{"t":"远树","f":"七言绝句","c":["行行远树惨无聊，脱尽清阴只有梢。","霜干瘦来无可庇，更能庇得鹭鸶巢。"]},{"t":"连日二相过史局不到省中后园杏花开尽","f":"七言绝句","c":["史馆频催史笔迟，道山还解有忙时。","后园两日不曾到，开尽杏花人不知。"]},{"t":"闰三月二日发船广州来归亭下之官宪台","f":"七言绝句","c":["诗人政坐爱闲游，天遣南游天尽头。","到得广州天尽处，方教回首向韶州。"]},{"t":"闰六月立秋后暮热追凉郡圃二首 其二","f":"七言绝句","c":["夏欲尽头秋欲初，小凉未苦爽肌肤。","夕阳幸自西山外，一抹斜红不肯无。"]},{"t":"闰六月立秋后暮热追凉郡圃二首 其一","f":"七言绝句","c":["上得城来眼顿明，暮山争献数尖青。","垂杨舞罢西风叶，一叶多时独未停。"]},{"t":"闲居初夏午睡起二绝句 其二","f":"七言绝句","c":["松阴一架半弓苔，偶欲看书又懒开。","戏掬清泉洒蕉叶，儿童误认雨声来。"]},{"t":"闷歌行十二首 其十二","f":"七言绝句","c":["风力掀天浪打头，只须一笑不须愁。","近看两日远三日，气力穷时会自休。"]},{"t":"闷歌行十二首 其十一","f":"七言绝句","c":["大风动地卷波头，索酒频添醉未休。","不判明朝教作病，却图今夕要忘愁。"]},{"t":"闷歌行十二首 其十","f":"七言绝句","c":["南人方理北归舟，北地风来便作愁。","不道北船等多日，北风不作不成休。"]},{"t":"闷歌行十二首 其九","f":"七言绝句","c":["船上犹馀一日粮，湖心粮尽籴何乡。","仙家辟谷从谁学，明日无炊即秘方。"]},{"t":"闷歌行十二首 其八","f":"七言绝句","c":["湖心何许有人烟，上下双天两点山。","犬吠鸡鸣四船里，旋成水国一家村。"]},{"t":"闷歌行十二首 其七","f":"七言绝句","c":["新诗哦罢倦来眠，蝴蝶飞游八极边。","船外风涛如霹雳，一声不到睡乡天。"]},{"t":"闷歌行十二首 其六","f":"七言绝句","c":["一风抛起万琼楼，几子康郎总掉头。","莫怕浪高洲尽没，海船下碇并无洲。"]},{"t":"闷歌行十二首 其五","f":"七言绝句","c":["书策看来已觉烦，诗篇厌了更休论。","客心未便无安顿，试数油窗雨点痕。"]},{"t":"闷歌行十二首 其四","f":"七言绝句","c":["问来邬子到南康，水路都来两日强。","屈指行程谁道远，如今不敢问都昌。"]},{"t":"闷歌行十二首 其三","f":"七言绝句","c":["一夜颠风翻却天，簸将白浪到天边。","康郎尚自无根脚，斗大洲头却系船。"]},{"t":"闷歌行十二首 其二","f":"七言绝句","c":["同列诸公总劝予，归时切莫过重湖。","婺源五岭祁门峡，今是危涂是坦涂。"]},{"t":"闷歌行十二首 其一","f":"七言绝句","c":["山行旧路不堪重，及汎湖波又阻风。","世上舟车无一稳，乾坤可是剩诗翁。"]},{"t":"阻风钟家村观岸傍物化二首 其二","f":"七言绝句","c":["壳如蝉蜕湿仍新，那复浮嬉浪底春。","却把今身飞照水，不知石上是前身。"]},{"t":"阻风钟家村观岸傍物化二首 其一","f":"七言绝句","c":["水虫才出绿波来，细看爬沙上石崖。","化作蜻蜓忽飞去，几时飞去却飞回。"]},{"t":"阻风泊钟家村离英州已三日才行二十里二首 其二","f":"七言绝句","c":["满船儿女厌江行，我爱江行怕入城。","惭愧风师教款曲，为分一舍作三程。"]},{"t":"阻风泊钟家村离英州已三日才行二十里二首 其一","f":"七言绝句","c":["南游端为看山来，过眼匆匆首屡回。","不是阻风船不进，何缘看尽万崔嵬。"]},{"t":"饭罢散策遇细雨二首 其二","f":"七言绝句","c":["极知秋旱已难医，所喜阴云忽四垂。","毕竟不成檐半滴，辛勤枉费雨千丝。"]},{"t":"饭罢散策遇细雨二首 其一","f":"七言绝句","c":["秋暄团扇尚堪携，病脚朝来健似飞。","偶到溪头晴唤出，未穷山顶雨催归。"]},{"t":"鸠衔枝营巢树间经月不成而去","f":"七言绝句","c":["鸠妇那知自不材，树阴疏处起楼台。","可怜积木如山样，一桷何曾架得来。"]},{"t":"麦田","f":"七言绝句","c":["无边绿锦织云机，全幅青罗作地衣。","个是农家真富贵，雪花销尽麦苗肥。"]},{"t":"净远亭午望二首 其二","f":"七言绝句","c":["竹径殊疏欠补栽，兰芽欲吐未全开。","初暄乍冷飞犹倦，一蝶新从底处来。"]},{"t":"净远亭午望二首 其一","f":"七言绝句","c":["城外春光染远山，池中嫩水涨微澜。","回身小却深檐里，野鸭双浮欲近栏。"]},{"t":"净远亭晚望","f":"七言绝句","c":["鸂鶒娇红野鸭青，为人浮没为人鸣。","忽闻风起仍波起，乃是飞声与落声。"]},{"t":"卧治斋夜坐","f":"七言绝句","c":["今年一雪遍江淮，半月晴光冻不开。","孤坐郡斋人寂寂，一枝红烛两瓶梅。"]},{"t":"卧治斋盆池","f":"七言绝句","c":["旧来菰叶已全衰，旋买新荷带藕栽。","看得荷花作莲子，可怜时节被花催。"]},{"t":"和丁端叔菊花","f":"五言绝句","c":["忽忽还重九，匆匆又岁华。","不妨将白发，剩与插黄花。"]},{"t":"和子上弟春雹","f":"七言绝句","c":["雹子何孤竹屋声，只于花事较无情。","青春已在残红里，更著渠侬何似生。"]},{"t":"和元举叔见谢载酒之韵二首 其二","f":"七言绝句","c":["南溪溪北北山边，风月公何得独专。","挈榼惭无桑落酒，赠诗如得汉阴鳊。"]},{"t":"和元举叔见谢载酒之韵二首 其一","f":"七言绝句","c":["雪久自消犹半在，雨来正密更无休。","硬黄字里真添瘦，重碧杯中且避愁。"]},{"t":"和冯倅投赠韵二首 其二","f":"七言绝句","c":["茧纸松煤细作行，两诗字字可珍藏。","书生伎俩成何事，只博虚名万古香。"]},{"t":"和冯倅投赠韵二首 其一","f":"七言绝句","c":["先生弹铗冻吟时，此岂求他一世知。","只怨送穷穷不去，元来却不怨工诗。"]},{"t":"和仲良分送柚花沉三首 其三","f":"七言绝句","c":["鹤骨龙筋金玉相，诗人十袭几年藏。","已惊好手夺天巧，更遣馀芬恼楚狂。"]},{"t":"和仲良分送柚花沉三首 其二","f":"七言绝句","c":["锯沉百叠糁琼英，一日三薰更九烝。","却悔香成太清绝，龙涎生妒木犀憎。"]},{"t":"和仲良催看黄才叔秀才南园牡丹","f":"七言绝句","c":["愁雨留花花已阑，作晴犹喜两朝寒。","山城春事无多子，可缓黄园探牡丹。"]},{"t":"和吴监丞景雪中湖上访梅四首 其四","f":"七言绝句","c":["闻君踏雪访梅花，不怕苏堤十里赊。","老子怯寒那敢出，地炉榾柮是生涯。"]},{"t":"和吴监丞景雪中湖上访梅四首 其三","f":"七言绝句","c":["雪与梅花两逼真，不知谁好复谁新。","无端更入吴融手，剪取西湖半段春。"]},{"t":"和吴监丞景雪中湖上访梅四首 其二","f":"七言绝句","c":["七字全胜五字城，清于庾信及钟嵘。","君诗妙绝端何似，不似梅花似么生。"]},{"t":"和吴监丞景雪中湖上访梅四首 其一","f":"七言绝句","c":["朔风敢傍贵人严，约束天花莫入檐。","药玉船宽初潋潋，销金帐暖政厌厌。"]},{"t":"和张功父梅诗十绝句 其八","f":"七言绝句","c":["横斜影里惜花残，忘却人间一鼠肝。","莫怨梅残看不足，请君明岁早来看。"]},{"t":"和张功父梅诗十绝句 其六","f":"七言绝句","c":["约斋句子已清圜，更赋梅花分外妍。","不饮销金传玉手，却来齧雪耸诗肩。"]},{"t":"和张功父梅诗十绝句 其十","f":"七言绝句","c":["老子年来不愿馀，祇惭霜鬓入金铺。","故山自有梅千树，梦绕横枝撚断须。"]},{"t":"和张功父梅诗十绝句 其四","f":"七言绝句","c":["淡淡梅花不要装，真珠楼阁水精乡。","骚人词客犹愁冷，紫蝶黄蜂更敢忙。"]},{"t":"和张功父梅诗十绝句 其三","f":"七言绝句","c":["不是春光不早回，却缘春雪勒疏梅。","诗人纵有催花手，有雪堪推花只推。"]},{"t":"和张功父梅诗十绝句 其七","f":"七言绝句","c":["道是梅兄不解琴，南枝风雪自成音。","玉绳低后金盆落，独与此君谈此心。"]},{"t":"和张功父梅诗十绝句 其九","f":"七言绝句","c":["要与梅花巧斗新，恨无诗句敌黄陈。","约斋诗好人仍好，不怕梅花赛却人。"]},{"t":"和张功父梅诗十绝句 其二","f":"七言绝句","c":["道山堂后数株梅，为底偏于雨里开。","到得晴来无一朵，乱飞白雪点苍苔。"]},{"t":"和张功父梅诗十绝句 其五","f":"七言绝句","c":["东皇岁岁驾苍龙，只许仙妃万玉从。","天上冰霜清入骨，人间桃李若为容。"]},{"t":"和张功父梅诗十绝句 其一","f":"七言绝句","c":["今岁柴车总未巾，孤山龙井不曾行。","老无半点看花意，遮莫明朝雨及晴。"]},{"t":"和张寺丞功父八绝句 其七","f":"七言绝句","c":["湖边花底旧论诗，再要寻盟今若为。","道是莺啼无点泪，教莺闻此也垂洟。"]},{"t":"和张寺丞功父八绝句 其二","f":"七言绝句","c":["古来官职妒诗篇，二物双违不肯全。","君被诗篇折官职，如何又寄一新编。"]},{"t":"和张寺丞功父八绝句 其五","f":"七言绝句","c":["问讯南湖作么生，日撞金玉奏英茎。","无人打杀净饭子，放出渠头七步行。"]},{"t":"和张寺丞功父八绝句 其四","f":"七言绝句","c":["金华不敢比东坡，此后东坡尔许多。","扰扰胸中百周孔，不愁柳柳笑人何。"]},{"t":"和张寺丞功父八绝句 其八","f":"七言绝句","c":["断当湖山我与公，问公别后却谁同。","一生海内金石友，万事人间牛马风。"]},{"t":"和张寺丞功父八绝句 其三","f":"七言绝句","c":["与子相望天一方，有书无使倩谁将。","归鸿欲下还飞去，不作书邮有底忙。"]},{"t":"和张寺丞功父八绝句 其一","f":"七言绝句","c":["约斋太瘦古仙真，寄我诗篇字字新。","受业陈三能几日，无端参换谪仙人。"]},{"t":"和张寺丞功父八绝句 其六","f":"七言绝句","c":["新岁南湖春又浓，海棠旧入我诗中。","别来若有相思字，寄与江西花信风。"]},{"t":"和张倅子仪送鞓红魏紫崇宁红醉西施四种牡丹二首 其二","f":"七言绝句","c":["洛花移种到松江，国色天香内样妆。","老里懒边无好思，为渠觅句却穷忙。"]},{"t":"和张倅子仪送鞓红魏紫崇宁红醉西施四种牡丹二首 其一","f":"七言绝句","c":["朱墨勾添眼底尘，今年春尽不知春。","鞓红魏紫能相访，西子崇宁更可人。"]},{"t":"和张器先十绝 其十","f":"七言绝句","c":["台家搜遍北山莱，倾国如君不用媒。","次第幽人出空谷，鹤书即傍日边来。"]},{"t":"和张器先十绝 其六","f":"七言绝句","c":["不随俗子作蝇营，深入书林寄此生。","已与杜郎争笔阵，更传侯喜有诗声。"]},{"t":"和张器先十绝 其九","f":"七言绝句","c":["学成不必要心斋，眼到前脩脚自偕。","挽住春风还独笑，更无一物可装怀。"]},{"t":"和张器先十绝 其八","f":"七言绝句","c":["老夫端欲买江天，抹月批风咽圣贤。","他日君来相问当，南溪溪北北山前。"]},{"t":"和张器先十绝 其七","f":"七言绝句","c":["漏黄官柳已垂墙，针水公畦未种秧。","多谢诗人来得得，踏开三径雨中荒。"]},{"t":"和张器先十绝 其二","f":"七言绝句","c":["向来一别十番秋，消息中间风马牛。","只道故人霄汉去，不应林壑小淹留。"]},{"t":"和张器先十绝 其四","f":"七言绝句","c":["我自穷愁坐缀文，何堪见子可怜生。","两穷政好同诗社，一战犹须倩酒兵。"]},{"t":"和张器先十绝 其三","f":"七言绝句","c":["谁云涸辙困波臣，合脱青鞋立缙绅。","寄与有司高著眼，后来文格待渠新。"]},{"t":"和张器先十绝 其五","f":"七言绝句","c":["散尽千金买尽书，短檠雨夜趁三馀。","相如自倚多文富，不问家无担石储。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其八","f":"七言绝句","c":["南丰每见每津津，茧纸松煤幻好春。","幸与李侯成二妙，更添杨子作三人。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其七","f":"七言绝句","c":["谪仙下笔不曾休，句似金盘柘弹流。","我欲将渠卜邻著，对披蓑笠刺渔舟。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其六","f":"七言绝句","c":["守臣闵雨几曾欣，两月天高叫不闻。","黄纸带将今雨至，分明端为圣明君。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其五","f":"七言绝句","c":["苏湖元以水为乡，春早偏欺润与常。","一雨忽来三昼夜，两公卷入八诗章。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其四","f":"七言绝句","c":["梦中檐溜作滩声，幼竹新荷总解鸣。","晓色满城浑是喜，更无一寸旱时情。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其三","f":"七言绝句","c":["雨早些时打麦残，雨迟许日即秧乾。","阿谁会得天公意，只道今年乞雨难。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其二","f":"七言绝句","c":["尘涨街头不识泥，朝来也解滑霜蹄。","两公玉句惊风雨，把玩都忘日脚西。"]},{"t":"和李子寿通判曾庆祖判院投赠喜雨口号八首 其一","f":"七言绝句","c":["雷起嘉山半点苍，乖龙无地著身藏。","莫嫌白雨来差晚，但遣黄云作大穰。"]},{"t":"和李天麟秋怀五绝句 其一","f":"七言绝句","c":["漫浪归来岁又秋，依然风月替人愁。","奉酬只么随缘句，懒更雕肝与探钩。"]},{"t":"和李天麟秋怀五绝句 其四","f":"七言绝句","c":["缀玉联珠辱见投，要知词客解悲秋。","侬家幸自无烦恼，却被新诗嫁许愁。"]},{"t":"和李天麟秋怀五绝句 其三","f":"七言绝句","c":["小立南溪暮未还，略容老子照衰颜。","颇惊暝色来天外，未必秋声在树间。"]},{"t":"和李天麟秋怀五绝句 其二","f":"七言绝句","c":["双井无人后山死，只今谁子定传灯。","老夫言语浑无味，不但秋来面可憎。"]},{"t":"和李天麟秋怀五绝句 其五","f":"七言绝句","c":["夜把新诗百遍开，句如红药与苍苔。","如何作许无端甚，押尽车斜始送来。"]},{"t":"和周仲容春日二绝句 其二","f":"五言绝句","c":["端忧更贫病，不分又花时。","只说春何好，犹堪入小诗。"]},{"t":"和周仲容春日二绝句 其一","f":"五言绝句","c":["春半花全退，诗人尚道迟。","惟应读书苦，声调作吾伊。"]},{"t":"和严州添倅赵彦先寄四绝句 其三","f":"七言绝句","c":["昌歜佳辰风自南，黄梅酿出雨鬖鬖。","绮琴绣段能分似，报不如仪独不惭。"]},{"t":"和严州添倅赵彦先寄四绝句 其一","f":"七言绝句","c":["不见王孙今九春，新词丽曲爽心神。","只言风月平分破，却是江湖一散人。"]},{"t":"和严州添倅赵彦先寄四绝句 其二","f":"七言绝句","c":["自抟苍壁自抄书，雪乳一瓯香一炉。","有得俸钱无吏责，如公官况世间无。"]},{"t":"和严州添倅赵彦先寄四绝句 其四","f":"七言绝句","c":["雏凤今年又一鸣，芝兰秀发不曾停。","州前争探黄金榜，却报城隅最冷厅。"]},{"t":"和范至能参政寄二绝句 其二","f":"七言绝句","c":["梦中相见慰相思，玉立长身漆点髭。","不遣紫宸朝补衮，却教雪屋夜哦诗。"]},{"t":"和范至能参政寄二绝句 其一","f":"七言绝句","c":["生憎雁鹜只盈前，忽览新诗意豁然。","锦字展来看未足，玉虫挑尽不成眠。"]},{"t":"和侯彦周知县招饮","f":"七言绝句","c":["乘兴山阴更灞桥，人间此事久寥寥。","客心也欲将归去，小为故人留一宵。"]},{"t":"和段季承左藏惠四绝句 其三","f":"七言绝句","c":["道是诗坛万丈高，端能办却一生劳。","阿谁不识珠将玉，若个关渠风更骚。"]},{"t":"和段季承左藏惠四绝句 其四","f":"七言绝句","c":["四诗赠我尽新奇，万象从君听指麾。","流水落花春寂寞，小风淡日燕差池。"]},{"t":"和段季承左藏惠四绝句 其一","f":"七言绝句","c":["个个诗家各筑坛，一家横割一江山。","祇知轻薄唐将晚，更解攀翻晋以还。"]},{"t":"和段季承左藏惠四绝句 其二","f":"七言绝句","c":["遮莫蟠胸书似山，更饶落笔语如泉。","阴何绝倒无人怨，却怨渠侬秘不传。"]},{"t":"和皇太子雨中赏梅偶成二首 其二","f":"七言绝句","c":["玉渊堂下一梢长，倚赖春风压众芳。","妙句忽从天上落，千花从此总无香。"]},{"t":"和皇太子雨中赏梅偶成二首 其一","f":"七言绝句","c":["日到青宫分外长，梅兼白雪一时芳。","储皇更著琼瑶句，句里天葩别样香。"]},{"t":"和皇太子梅诗二首 其二","f":"七言绝句","c":["梅仙踏雪步生尘，储后梅诗雪共新。","玉句金章云锦字，问天觅得隔年春。"]},{"t":"和皇太子梅诗二首 其一","f":"七言绝句","c":["清赏堂前隔俗尘，南枝得雪晓争新。","独将却月凌风影，搀献储皇第一春。"]},{"t":"和皇太子瑞雪二首 其二","f":"七言绝句","c":["揉云挼雾碎成尘，落不曾休酉达辰。","鹤禁镂冰成七字，野人拜赐敢辞频。"]},{"t":"和皇太子瑞雪二首 其一","f":"七言绝句","c":["白玉花开碧玉天，萦楼绕殿舞翩然。","储皇善颂天皇德，瑞应金穰万万年。"]},{"t":"和唐德明问病二首 其二","f":"七言绝句","c":["俟命循天更不疑，朵颐那可换灵龟。","逍遥岂在榆枋外，问著扶摇总不知。"]},{"t":"和唐德明问病二首 其一","f":"七言绝句","c":["罢却微官且客居，庭闱不近信全疏。","更无竹下子唐子，谁与过逢说异书。"]},{"t":"和彭仲庄对牡丹止酒二首 其二","f":"七言绝句","c":["老里心情客里怀，逢花不饮若为开。","虚名身后真何用，更判生前酒一杯。"]},{"t":"和彭仲庄对牡丹止酒二首 其一","f":"七言绝句","c":["病身无伴卧空山，石友相从慰眼寒。","呼酒撚花谈旧事，牡丹匹似梦中看。"]},{"t":"和谢昌国送韦俊臣相访","f":"七言绝句","c":["芒屩为车不必巾，天穷未害子能文。","谢家有句元无继，枉却催诗头上云。"]},{"t":"和谢昌国送管相士韵","f":"七言绝句","c":["半世缘痴自作劳，万人争处我方逃。","怜渠识尽公卿得，一马归来骨转高。"]},{"t":"咏荷花中小莲蓬","f":"七言绝句","c":["山蜂愁雨损蜂儿，叶底安巢更倒垂。","只有荷蜂不愁雨，蜡房仰卧万花枝。"]},{"t":"咏酥","f":"五言绝句","c":["似腻还成爽，才凝又欲飘。","玉来盘底碎，雪到口边销。"]},{"t":"垂丝海棠二首 其二","f":"七言绝句","c":["不关残醉未醒松，不为春愁懒散中。","自是新晴生睡思，起来无力对东风。"]},{"t":"垂丝海棠二首 其一","f":"七言绝句","c":["无波可照底须窥，与柳争娇也学垂。","破晓骤晴天有意，生红新晒一絇丝。"]},{"t":"垂丝海棠半落","f":"七言绝句","c":["雨后精神退九分，病香愁态不胜春。","落阶一寸轻红雪，卷地风来政恼人。"]},{"t":"垂虹亭观打鱼斫鲙四首 其四","f":"七言绝句","c":["鲈鱼小底最为佳，一白双腮是当家。","旋看冰盘堆白雪，急风吹去片银花。"]},{"t":"垂虹亭观打鱼斫鲙四首 其三","f":"七言绝句","c":["渔郎妙手绝多机，一网收鱼未足奇。","刚向人前撰勋绩，不教速得只教迟。"]},{"t":"垂虹亭观打鱼斫鲙四首 其二","f":"七言绝句","c":["六只轻舠搅四旁，两船不动水中央。","网丝一撒还空举，笑得倚栏人断肠。"]},{"t":"垂虹亭观打鱼斫鲙四首 其一","f":"七言绝句","c":["桥柱疏疏四寂然，亭前突出八鱼船。","一声磔磔鸣榔起，惊出银刀跃玉泉。"]},{"t":"夜同文远祷雨老冈祠","f":"七言绝句","c":["秋热常年无此例，今宵有月不能凉。","槁苗似妒诗人懒，作意催成祷雨章。"]},{"t":"夜观庭中梅花","f":"五言绝句","c":["雾质云为屋，琼肤玉作裳。","花明不是月，夜静偶闻香。"]},{"t":"夜过杨州二首 其二","f":"七言绝句","c":["新晴残冻未全销，月恋冰河雪恋桥。","两岸红灯成白昼，杨州腊月看元宵。"]},{"t":"夜过杨州二首 其一","f":"七言绝句","c":["祗今何许问迷楼，更有垂杨记御沟。","除却琼花与红药，杨州不是古杨州。"]},{"t":"夜坐二首 其二","f":"七言绝句","c":["寒宵老眼只长醒，蝴蝶频催梦不成。","不是三更三四点，如何一睡到天明。"]},{"t":"夜坐二首 其一","f":"七言绝句","c":["绣帘无力护东风，烛影何曾正当红。","兽炭貂裘犹道冷，梅花不易玉霜中。"]},{"t":"夜饮周同年权府家","f":"七言绝句","c":["老趁渔船泊馆娃，月明夜饮故人家。","春风吹酒不肯醒，嚼尽酴醾一架花。"]},{"t":"夜泊平望二首 其二","f":"七言绝句","c":["一色河边卖酒家，于中酒客一家多。","青帘不饮能样醉，弄杀霜风舞杀它。"]},{"t":"夜泊平望二首 其一","f":"七言绝句","c":["夜来微雪晓还晴，平望维舟嫩月生。","道是烛花总无恨，为谁须暗为谁明。"]},{"t":"夜泊平望终夕不寐三首 其三","f":"七言绝句","c":["一生行路便多愁，落得星星两鬓秋。","数尽归程到家了，此身犹未出苏州。"]},{"t":"夜泊平望终夕不寐三首 其二","f":"七言绝句","c":["樱桃湖里月如霜，偏照征人寸断肠。","醉里不知家尚远，梦回忽觉路初长。"]},{"t":"夜泊平望终夕不寐三首 其一","f":"七言绝句","c":["船中新热睡难成，听尽渔舟掠水声。","不分两窗窗外月，如何不为别人明。"]},{"t":"夜泊曲湾","f":"七言绝句","c":["顺流一日快舟行，薄暮风涛特地生。","不是江神惊客子，劝人早泊莫追程。"]},{"t":"夜泊钓台小酌","f":"七言绝句","c":["牛狸送我止严陵，黄雀随人或帝城。","海错未来乡味尽，一杯今夕笑先生。"]},{"t":"夜泊鸦矶","f":"七言绝句","c":["峡中尽日没人烟，船泊鸦矶也有村。","已被子规酸骨死，今宵第一莫啼猿。"]},{"t":"夜闻萧伯和与子上弟读书","f":"七言绝句","c":["少日耽书病得臞，何曾灯火稍相疏。","如今老懒那能许，卧听邻斋夜读书。"]},{"t":"夜坐小集","f":"七言绝句","c":["霜馀雪后夜无风，人在灯前梅影中。","玉作寒蔬冰作酒，诗人犹自怨天穷。"]},{"t":"夜离零陵以避同僚追送之劳留二绝简诸友 其二","f":"七言绝句","c":["思归日日只空言，一棹今真水月间。","半夜犹闻郡楼鼓，明朝应失永州山。"]},{"t":"夜离零陵以避同僚追送之劳留二绝简诸友 其一","f":"七言绝句","c":["已坐诗臞病更羸，诸公刚欲饯湘湄。","夜浮一叶逃盟去，已被沙鸥圣得知。"]},{"t":"夜窗二首 其二","f":"七言绝句","c":["诗人心绪几时休，逢著三春似九秋。","数到五更仍五点，明朝还更有新愁。"]},{"t":"夜窗二首 其一","f":"七言绝句","c":["口角哦诗细有声，不妨半醉不妨行。","青灯一点才如黍，解作书窗彻夜明。"]},{"t":"官道古松","f":"七言绝句","c":["翠旌绿纛夹车轮，龙作长身铁作鳞。","莫笑道傍数松树，古来老却几官人。"]},{"t":"初夏三绝句 其三","f":"七言绝句","c":["竹间露重午方乾，松里云深夏亦寒。","只道一溪无十里，为谁百屈更千盘。"]},{"t":"初夏三绝句 其一","f":"七言绝句","c":["麦黄秧碧百家衣，已热犹寒四月时。","雨后觅春无一寸，野蔷薇发酽燕脂。"]},{"t":"初夏三绝句 其二","f":"七言绝句","c":["手种琅玕劣十年，今年新笋不胜繁。","不知明早添多少，日暮闲来数一番。"]},{"t":"岸沙","f":"七言绝句","c":["水嫌岸窄要冲开，细荡沙痕似剪裁。","荡去荡来元不觉，忽然一片岸沙摧。"]},{"t":"岸树二首 其二","f":"七言绝句","c":["岸树枝枝秃影中，雪风一半半春风。","楝梢落尽黄金弹，犹有纷纷缀弹茸。"]},{"t":"岸树二首 其一","f":"七言绝句","c":["岸头树子直如筠，谁遣相招住水滨。","不合镜中贪照影，照来照去总斜身。"]},{"t":"庚子正月五日晓过大皋渡二首 其二","f":"七言绝句","c":["危沙崩岸欲侵墙，直下清江百尺强。","过了笋舆元未觉，忽然回首冷思量。"]},{"t":"庚子正月五日晓过大皋渡二首 其一","f":"七言绝句","c":["雾外江山看不真，只凭鸡犬认前村。","渡船满板霜如雪，印我青鞋第一痕。"]},{"t":"庚申东园花发二首 其二","f":"七言绝句","c":["桃蹊李径旧分栽，红白教它各自开。","可是桃花逞颜色，一枝穿过李花来。"]},{"t":"庚申东园花发二首 其一","f":"七言绝句","c":["晓风细细复鲜鲜，也不鸣条也不喧。","却被花枝勾引著，掀桃舞柳恣它颠。"]},{"t":"庚戌正月三日约同舍游西湖十首 其十","f":"七言绝句","c":["闸住清泉似镜平，闸开奔浪作潮声。","放开一板还收去，依旧穿沙绕石行。"]},{"t":"庚戌正月三日约同舍游西湖十首 其九","f":"七言绝句","c":["树生石上土全无，只见青葱不见枯。","好在冷泉亭下水，为渠凭槛数游鱼。"]},{"t":"庚戌正月三日约同舍游西湖十首 其八","f":"七言绝句","c":["家家砌下过清泉，寺寺云边占碧山。","走马来看已心醒，更教选胜住中间。"]},{"t":"庚戌正月三日约同舍游西湖十首 其七","f":"七言绝句","c":["上竺诸峰深复深，一重一掩翠云衿。","只言人迹无来路，动地钟声与梵音。"]},{"t":"庚戌正月三日约同舍游西湖十首 其六","f":"七言绝句","c":["补种杉松径已成，泥乾尘净正堪行。","草芽并作伤心碧，只欠先生屐子声。"]},{"t":"庚戌正月三日约同舍游西湖十首 其五","f":"七言绝句","c":["下竺泉从上竺来，前波后浪紧相催。","泉声似说西湖好，流到西湖不要回。"]},{"t":"庚戌正月三日约同舍游西湖十首 其四","f":"七言绝句","c":["南北高峰巧避人，旋生云雾半腰横。","纵然遮得青苍面，玉塔双尖分外明。"]},{"t":"庚戌正月三日约同舍游西湖十首 其三","f":"七言绝句","c":["黄金榜揭集芳园，只隔墙头便是天。","西母云车寒未降，莺花作意办新年。"]},{"t":"庚戌正月三日约同舍游西湖十首 其二","f":"七言绝句","c":["春光欲动意犹迟，未许游人浪见伊。","只有梅花藏不得，隔篱穿竹出横枝。"]},{"t":"庚戌正月三日约同舍游西湖十首 其一","f":"七言绝句","c":["不到西湖又两年，西湖风物故依然。","道旁松桧俱无恙，笑我重来雪满颠。"]},{"t":"往安福宿代度寺","f":"七言绝句","c":["春前腊后暖还寒，陌上泥中湿更乾。","野寺鸣钟招我宿，远峰留雪待谁看。"]},{"t":"披仙阁上观酴醾二首 其二","f":"七言绝句","c":["酴醾约我早来看，及至来看花已残。","动地寒风君莫怯，乱吹香雪洒栏干。"]},{"t":"披仙阁上观酴醾二首 其一","f":"七言绝句","c":["仰架遥看时见些，登楼下瞰脱然佳。","酴醾蝴蝶浑无辨，飞去方知不是花。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其七","f":"七言绝句","c":["梅香不是不寒清，参遍横枝酒未醒。","梦入西湖疏影里，觉来失却冷泉亭。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其六","f":"七言绝句","c":["雪冻霜封稍欲残，殷勤折向坐中看。","绮疏深闭珠帘密，不遣花愁半点寒。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其五","f":"七言绝句","c":["衣染龙涎与麝脐，裁云剪月作冰肌。","小瓶雪水无多子，只篸横斜一两枝。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其四","f":"七言绝句","c":["寒尽春生夜未央，酒狂狂似醒时狂。","吾人何用餐烟火，揉碎梅花和蜜霜。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其三","f":"七言绝句","c":["酒兵半已卧长瓶，更看梅兄巧尽情。","醉插寒花望松雪，人间曾有个般清。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其二","f":"七言绝句","c":["胆样银瓶玉样梅，北枝折得未全开。","为怜落莫空山里，唤入诗人几案来。"]},{"t":"昌英知县叔作岁坐上赋瓶里梅花时坐上九人七首 其一","f":"七言绝句","c":["销冰作水旋成家，犹似江头竹外斜。","试问坐中还几客，九人而已更梅花。"]},{"t":"明发三衢三首 其三","f":"七言绝句","c":["云欲开时又不开，问天觅阵好风催。","雨无多落泥偏滑，溪不胜深岸故颓。"]},{"t":"明发三衢三首 其二","f":"七言绝句","c":["冲风破雨正愁人，愁得心情没半分。","风处吹来好消息，诸峰放散夜来云。"]},{"t":"明发三衢三首 其一","f":"七言绝句","c":["拔尽新秧插尽田，出城一眼翠无边。","不关雨水愁行客，政是年年雨水天。"]},{"t":"明发龙川二首 其二","f":"七言绝句","c":["优入蛮溪受瘴烟，一生谁料到龙川。","早书实历远山考，便是中书九闰年。"]},{"t":"明发龙川二首 其一","f":"七言绝句","c":["山有浓岚水有氛，非烟非雾亦非云。","北人不识南中瘴，只到龙川指似君。"]},{"t":"明发曲坑二首 其二","f":"七言绝句","c":["露草欣逢晓日新，各将珠琲斗呈珍。","红光影里如何拣，颗颗圜明颗颗匀。"]},{"t":"明发曲坑二首 其一","f":"七言绝句","c":["云横平野近人低，似縠如纱只隔溪。","行到溪东元不见，回头却复在溪西。"]},{"t":"明发西馆晨炊蔼冈四首 其四","f":"七言绝句","c":["何须名苑看春风，一路山花不负侬。","日日锦江呈锦样，清溪倒照映山红。"]},{"t":"明发西馆晨炊蔼冈四首 其三","f":"七言绝句","c":["也知水碓妙通神，长听舂声不见人。","若要十分无漏逗，莫将戽斗镇随身。"]},{"t":"明发西馆晨炊蔼冈四首 其二","f":"七言绝句","c":["人家争住水东西，不是临溪即背溪。","拶得一家无去处，跨溪结屋更清奇。"]},{"t":"明发西馆晨炊蔼冈四首 其一","f":"七言绝句","c":["盘蔬盂饭趁朝饥，争指枯肠作地基。","不觉南山新笋蕨，搀先占却未多时。"]},{"t":"明发阶口岸下","f":"七言绝句","c":["破晓篙师报放船，今朝不似昨朝寒。","梦中草草披衣起，爱看轻舟下急滩。"]},{"t":"明发房溪二首 其二","f":"七言绝句","c":["青天白日十分晴，轿上萧萧忽雨声。","却是松梢霜水落，雨声那得此声清。"]},{"t":"明发房溪二首 其一","f":"七言绝句","c":["山路婷婷小树梅，为谁零落为谁开。","多情也恨无人赏，故遣低枝拂面来。"]},{"t":"明发泷头","f":"七言绝句","c":["黑甜偏至五更浓，强起侵星敢小慵。","轮与山云能样懒，日高犹宿夜来峰。"]},{"t":"明发祁门悟法寺溪行险绝六首 其六","f":"七言绝句","c":["已是山寒更水寒，酸风苦雨并无端。","诗人瘦骨无半把，一任残春料理看。"]},{"t":"明发祁门悟法寺溪行险绝六首 其五","f":"七言绝句","c":["山行政好又逢溪，况是危峰斗下时。","知与此溪有何隙，遣它不去祗相随。"]},{"t":"明发祁门悟法寺溪行险绝六首 其四","f":"七言绝句","c":["溪行尽处却穿山，忽有人家并有田。","幸自惊心小宁贴，误看田水作深川。"]},{"t":"明发祁门悟法寺溪行险绝六首 其三","f":"七言绝句","c":["山不人烟水不桥，溪声浩浩雨萧萧。","何须双鹭相温暖，鹭过还教转寂寥。"]},{"t":"明发祁门悟法寺溪行险绝六首 其二","f":"七言绝句","c":["一派泉从千丈崖，轰霆跳雪泻将来。","无论惊杀行人著，两岸诸峰震欲摧。"]},{"t":"明发祁门悟法寺溪行险绝六首 其一","f":"七言绝句","c":["右缘绝壁左深溪，头上春霖脚底泥。","溪里仰看应落胆，闭窗关轿不教知。"]},{"t":"明发青泥冲雪刺船三首 其三","f":"七言绝句","c":["红玉麒麟未作灰，自温琼液写银杯。","雪花万片江千顷，更欠人间底物来。"]},{"t":"明发青泥冲雪刺船三首 其二","f":"七言绝句","c":["碧玉波头绿锦絪，玉妃踏舞袜生尘。","先生奇观谁分却，不分孤舟独钓人。"]},{"t":"明发青泥冲雪刺船三首 其一","f":"七言绝句","c":["冰棹风船雪满篷，诗人醉卧水晶宫。","追程未到君休问，且启琼窗看玉峰。"]},{"t":"明发海智寺遇雨二首 其二","f":"七言绝句","c":["可惜新年雨未多，不妨剩与决天河。","农人皱得眉头破，无水种秧君奈何。"]},{"t":"明发海智寺遇雨二首 其一","f":"七言绝句","c":["枉教一月费春风，不及朝来细雨功。","草色染来蓝样翠，桃花洗得肉般红。"]},{"t":"明发窄溪晚次严州","f":"七言绝句","c":["夕照落帆乌石滩，朝来解缆窄溪边。","篙师好语君知否，一日风行两日船。"]},{"t":"明发鸭步","f":"七言绝句","c":["两岁春船各一时，今年船快去年迟。","青山面目何曾改，清晓看来别样奇。"]},{"t":"明发梅州","f":"五言绝句","c":["市小山城寂，船稀野渡忙。","金暄梅蕊日，玉冷草根霜。"]},{"t":"明发韶州过赤水渴尾滩","f":"七言绝句","c":["船下惊滩浪政喧，花汀水退走沙痕。","一峰忽自云端出，只见孤尖不见根。"]},{"t":"松关","f":"七言绝句","c":["竹林行尽到松关，分付双松为把门。","若放俗人来一个，罚渠老瓦十分盆。"]},{"t":"松阴小憩","f":"七言绝句","c":["不但先生倦不苏，仆夫也自要人扶。","青松数了还重数，只是从前八九株。"]},{"t":"松声","f":"七言绝句","c":["哦诗口角恰微鸣，唤得风从月胁生。","端为先生醒醉耳，绕山搜出万松声。"]},{"t":"泊光口","f":"七言绝句","c":["风平浪静不生纹，水面浑如镜面新。","忽有暗流江底出，衮翻水面作车轮。"]},{"t":"泊舟无锡雨止遂游惠山","f":"七言绝句","c":["天教老子不空回，船泊山根雨顿开。","归去江西人问我，也曾一到惠山来。"]},{"t":"泊流潢驿潮风大作二首 其二","f":"七言绝句","c":["潮来潮去有何功，费尽辛勤办一风。","若使无风潮自至，信他海伯有神通。"]},{"t":"泊流潢驿潮风大作二首 其一","f":"七言绝句","c":["忽看草树总离披，记得沙行昨日时。","除却潮来无别事，海风动地亦何为。"]},{"t":"泊鸭步","f":"七言绝句","c":["江流自在水风轻，云去天来半欲晴。","两岸东西三十里，李花独树隔江明。"]},{"t":"泊船百花洲登姑苏台二首 其二","f":"七言绝句","c":["客里逢春了不知，牡丹剩买十来枝。","东风动地从渠恶，吹尽杨花无可吹。"]},{"t":"泊船百花洲登姑苏台二首 其一","f":"七言绝句","c":["二月尽头三月初，系船杨柳拂菰蒲。","姑苏台上斜阳里，眼度灵岩到太湖。"]},{"t":"浅夏独行奉新县圃","f":"七言绝句","c":["我来官下未多时，梅已黄深李绿肥。","只怪南风吹紫雪，不知屋角楝花飞。"]},{"t":"炬火发誓节渡勇家店二首 其二","f":"七言绝句","c":["昨午秋阳尚壮哉，今晨莫待日光催。","麻蒸一照三十里，底用金莲花炬来。"]},{"t":"炬火发誓节渡勇家店二首 其一","f":"七言绝句","c":["飘炉飞空落晓星，随风入草化秋萤。","莎虫误认天明了，却变寒声作暖声。"]},{"t":"盱眙军无梅郡圃止有蜡梅两株二首 其二","f":"七言绝句","c":["腊里花开已是迟，西湖十月见琼肌。","岭头犹说南枝暖，却向淮南觅北枝。"]},{"t":"盱眙军无梅郡圃止有蜡梅两株二首 其一","f":"七言绝句","c":["只道横枝春未回，又疑不肯犯寒开。","逢人问讯花消息，不识江梅只蜡梅。"]},{"t":"直宿南宫三首 其三","f":"七言绝句","c":["秋热连宵睡不成，移床换枕到天明。","今宵不热还无睡，却为宫檐泻雨声。"]},{"t":"直宿南宫三首 其二","f":"七言绝句","c":["今年秋暑更禁它，无计商量奈热何。","一霎飘萧凉一日，雨来销得几多多。"]},{"t":"直宿南宫三首 其一","f":"七言绝句","c":["独直南宫午独吟，祥云淡淡竹阴阴。","小风慢落鹅黄雪，看到槐花一寸深。"]},{"t":"练湖放闸二首 其二","f":"七言绝句","c":["水簟南舒去转虚，天檐北卸望来无。","相传一万四千顷，老眼初惊见练湖。"]},{"t":"练湖放闸二首 其一","f":"七言绝句","c":["满耳雷声动地来，窥窗银浪打船开。","练湖才放一寸水，跳作冰河万雪堆。"]},{"t":"细雨","f":"七言绝句","c":["孤闷无言独倚门，梅花细雨欲黄昏。","可怜檐滴不脱洒，点点何曾离旧痕。"]},{"t":"罗溪望夫岭二首 其二","f":"七言绝句","c":["行役家家寄刀尺，谁将枯骨带心头。","惟有望夫心志苦，甘霖偏为七娘流。"]},{"t":"罗溪望夫岭二首 其一","f":"七言绝句","c":["藁砧不寄大刀头，化作峰头石也愁。","岂有心情管风雨，向人弹泪绕天流。"]},{"t":"苕溪登舟","f":"七言绝句","c":["深于池沼浅于河，动地风来也不波。","只道东来行役苦，胡床面面是菱荷。"]},{"t":"苦寒三首 其三","f":"七言绝句","c":["冰和菜把菜和冰，心喜冬菹齿却憎。","且忍牙车寒一点，教他胸次雪千层。"]},{"t":"苦寒三首 其二","f":"七言绝句","c":["添尽红炉著尽衣，一杯方觉暖如痴。","人言霜后寒无奈，春在瓮中渠不知。"]},{"t":"苦寒三首 其一","f":"七言绝句","c":["畏暑长思雪绕身，苦寒却愿柳回春。","晚来斜日无多暖，映著西窗亦可人。"]},{"t":"芗林五十咏 其二 虎川","f":"五言绝句","c":["居士欹黄帽，曾来照晚晴。","至今流㶁㶁，犹学咏诗声。"]},{"t":"表弟周明道工于传神而山水亦佳久别来访赠以绝句二首 其二","f":"七言绝句","c":["侬家有轴郭熙山，堕在冰溪雪岭间。","有弟新来眼如月，为侬洗手拾将还。"]},{"t":"表弟周明道工于传神而山水亦佳久别来访赠以绝句二首 其一","f":"七言绝句","c":["笔端人物更江山，外弟周郎两不难。","可把吴松半江水，博他头上进贤冠。"]},{"t":"诗情","f":"七言绝句","c":["只要雕诗不要名，老来也复减诗情。","虚名满世真何用，更把虚名赚后生。"]},{"t":"诚斋步月 其二","f":"七言绝句","c":["桂树何曾不长枝，月轮却有不圆时。","若教桂树只管长，拶拆月轮谁补伊。"]},{"t":"诚斋步月 其一","f":"七言绝句","c":["先生散发步庭中，孤月行天露满空。","已入广寒宫里去，如何别觅广寒宫。"]},{"t":"诚斋待月","f":"七言绝句","c":["红稠碧秀暗山园，只有诚斋眼界宽。","月近竹梢偏不上，要人不看要人看。"]},{"t":"郎石峰","f":"七言绝句","c":["四旁不与众山连，特地孤尖立半天。","碧落诸峰非不好，让它郎石一峰先。"]},{"t":"金凤花","f":"七言绝句","c":["细看金凤小花丛，费尽司花染作工。","雪色白边袍色紫，更饶深浅四般红。"]},{"t":"金鸡石在玉山东二首 其二","f":"七言绝句","c":["头高尾下翠毵毵，却恐相传是妄谈。","十七里头徐老店，檐东道北北桥南。"]},{"t":"金鸡石在玉山东二首 其一","f":"七言绝句","c":["相传石里两金鸡，不记胡商凿取时。","一只遭擒一飞去，至今月落不曾啼。"]},{"t":"金陵官舍后圃散策二首 其二","f":"七言绝句","c":["旋种花窠二百株，不知种了有花无。","阿谁便向春工说，急捣红蓝染玉酥。"]},{"t":"金陵官舍后圃散策二首 其一","f":"七言绝句","c":["江梅未落杏先繁，萱草都齐柳半匀。","却是浅寒花较耐，东风未要十分温。"]},{"t":"金溪道中","f":"七言绝句","c":["野花垂路止人行，田水偏寻缺处鸣。","近浦人家随曲折，插秧天气半阴晴。"]},{"t":"金罂花联句","f":"七言绝句","c":["两日风狂雨更颠，取将暖去正衣单。","金罂花发关谁事，何用夜来如许寒。"]},{"t":"钓雪舟倦睡","f":"七言绝句","c":["小阁明窗半掩门，看书作睡政昏昏。","无端却被梅花恼，特地吹香破梦魂。"]},{"t":"雨中入城送赵吉州器之二首 其二","f":"七言绝句","c":["村店农忙半不开，入城客子去还来。","阿耶乌伞儿青笠，卖却松柴买菜回。"]},{"t":"雨中入城送赵吉州器之二首 其一","f":"七言绝句","c":["拂溪杨柳缕生金，栏路山矾香杀人。","不是冲泥送行客，外头放过若干春。"]},{"t":"雨中出湖上送客","f":"七言绝句","c":["细雨轻烟著地昏，湖波真个解生尘。","净慈灵隐君休觅，失却诸峰不恼人。"]},{"t":"雨中过沙滩二首 其二","f":"七言绝句","c":["烟雨新图学不成，烟能明晦雨能声。","莫教一点春风起，卷尽空濛写晚晴。"]},{"t":"雨中过沙滩二首 其一","f":"七言绝句","c":["常州草虫天下无，可怜枉却许工夫。","濛濛拂拂沙滩艇，别是荆溪烟雨图。"]},{"t":"雨中远望惠山二首 其二","f":"七言绝句","c":["诗人也是可怜生，不及穿云渡水僧。","不是惠山看不见，只教遥见不教登。"]},{"t":"雨中远望惠山二首 其一","f":"七言绝句","c":["准拟归时到未迟，归时不到悔来时。","惠山不识空归去，枉与常州作住持。"]},{"t":"雨中梅花","f":"七言绝句","c":["霜晴三日不胜佳，忽作阴霖送岁华。","客里清愁自无奈，却教和雨看梅花。"]},{"t":"雨中道旁丛竹","f":"五言绝句","c":["竹色岂不好，道旁端可嗔。","只教寒雨里，将冷洒行人。"]},{"t":"雨中遣闷","f":"七言绝句","c":["船篷深闭膝难安，四面千峰不得看。","莫厌霏微闷人雨，插秧怕热爱轻寒。"]},{"t":"雨中酴醾","f":"七言绝句","c":["翡翠堆头乱不梳，梅花脑子糁肌肤。","夜来急雨元无事，晓起看花一片无。"]},{"t":"雨中懒困","f":"七言绝句","c":["城头欲上苦新泥，暖气薰人软欲痴。","睡又不成行不是，强来看打洛神碑。"]},{"t":"雨后田间杂纪五首 其五","f":"七言绝句","c":["正是山花最闹时，浓浓淡淡未离披。","映山红与昭亭紫，挽住行人赠一枝。"]},{"t":"雨后田间杂纪五首 其四","f":"七言绝句","c":["晴路无泥亦未埃，野云尽薄不全开。","满山都是长松树，无数杨花何处来。"]},{"t":"雨后田间杂纪五首 其三","f":"七言绝句","c":["行到深村麦更深，放低小轿过桑阴。","再三传语春寒道，好为农家惜绿针。"]},{"t":"雨后田间杂纪五首 其二","f":"七言绝句","c":["田水高低各斗鸣，溪流奔放更驩声。","小儿倒撚青梅朵，独立茅檐看客行。"]},{"t":"雨后田间杂纪五首 其一","f":"七言绝句","c":["稻田滴水价千金，溪涧求分不肯分。","一雨万畦都水足，却将倾泻作溪浑。"]},{"t":"雨后行郡圃","f":"七言绝句","c":["雨馀行脚古城隈，为爱危亭首屡回。","无数菊苗齐老去，多时花径不曾来。"]},{"t":"雨后步东园","f":"七言绝句","c":["晴缫金线不胜垂，寒勒青针未放齐。","拄杖能言忽相报，三三径里已无泥。"]},{"t":"雨后独登舍北山顶","f":"七言绝句","c":["山下生愁热不除，山头小立气全苏。","自缘著脚高低别，万壑清风岂是无。"]},{"t":"雨后晚步郡圃二首 其二","f":"七言绝句","c":["风勒归云带雨回，不容老子小徘徊。","拨忙也到池亭上，昨日卷荷今尽开。"]},{"t":"雨后晚步郡圃二首 其一","f":"七言绝句","c":["画舫鸣钲野寺钟，暮声惊破翠烟重。","好风不解藏天巧，彫碎孤云作数峰。"]},{"t":"雨后登度雪台","f":"七言绝句","c":["三日东园近却赊，东风剪剪雨斜斜。","春容雨打风吹尽，犹有金沙最后花。"]},{"t":"雨作抵暮复晴五首 其五","f":"七言绝句","c":["风伯颠狂太劣生，雨师懒困洒来轻。","若言不被云君误，谁放斜阳作晚晴。"]},{"t":"雨作抵暮复晴五首 其四","f":"七言绝句","c":["清平如席是淮流，风起雷奔怒不休。","一浪飞来惊落胆，早知祇要打船头。"]},{"t":"雨作抵暮复晴五首 其三","f":"七言绝句","c":["雨痕拂水有如无，雨点飞空密复疏。","白鹭窥鱼浑欲下，被风吹起不由渠。"]},{"t":"雨作抵暮复晴五首 其二","f":"七言绝句","c":["细雨如尘复似烟，两淮渡口各收船。","南商北贾俱星散，古庙无人烧纸钱。"]},{"t":"雨作抵暮复晴五首 其一","f":"七言绝句","c":["栖鹊无阴庇湿衣，行人仄伞避斜丝。","船兵归后轿兵去，独立淮河暮雨时。"]},{"t":"雨足晓立郡圃荷桥","f":"七言绝句","c":["郡池六月水方生，便有新荷贴水轻。","雨后独来无个事，闲听啼鸟话升平。"]},{"t":"雨里问讯张定叟通判西园杏花二首 其二","f":"七言绝句","c":["梅不嫌疏杏要繁，主人何忍折令残。","也知雨意将无恶，为勒芳菲故故寒。"]},{"t":"雨里问讯张定叟通判西园杏花二首 其一","f":"七言绝句","c":["白白红红一树春，晴光炫眼看难真。","无端昨夜萧萧雨，细锦全机卸作茵。"]},{"t":"雨夜独酌","f":"七言绝句","c":["清明未到未和柔，过了清明春又休。","烛下看花遍有思，醉中听雨也无愁。"]},{"t":"雨霁","f":"七言绝句","c":["雨为梅花遣尽尘，柳勾日影自传神。","不须苦问春多少，暖幕晴帘总是春。"]},{"t":"促织","f":"七言绝句","c":["一声能遣一人愁，终夕声声晓未休。","不解缫丝替人织，强来出口促衣裘。"]},{"t":"南华道中二首 其二","f":"七言绝句","c":["骑吏欢呼不要嗔，二千里外北归人。","殷勤自掬曹溪水，净洗先生面上尘。"]},{"t":"南华道中二首 其一","f":"七言绝句","c":["清晓新晴物物熙，小风淡日暖归旗。","不堪回首南华路，去岁梅花细雨时。"]},{"t":"南斋前众树披猖红梅居间不肆因为剪剔","f":"七言绝句","c":["道是司花定有神，元来造化在诗人。","扫除碧树无情朵，放出红梅恣意春。"]},{"t":"南斋前梅花二首 其二","f":"七言绝句","c":["朝朝蚤起挂南窗，要看梅花试晓妆。","两树相挨前后发，老夫一月不烧香。"]},{"t":"南望阁皂山","f":"七言绝句","c":["惭愧多情阁皂山，去年迎我上西船。","今来送我还东去，四日相随到进贤。"]},{"t":"南雄驿前双柳","f":"七言绝句","c":["外计堂前柳绝奇，南中无此两涡丝。","午风不动休嫌暑，要看枝枝自在垂。"]},{"t":"南雄解舟","f":"七言绝句","c":["一昨春江上水船，即非上水是登天。","如今下濑江无水，始信登天却易然。"]},{"t":"南溪上种芙蓉","f":"七言绝句","c":["夹水芙容密密栽，缘溪斜立照溪开。","放教十里红将去，不尽溪流不要回。"]},{"t":"南溪山居秋日睡起","f":"七言绝句","c":["客至从嗔不著冠，起来信手揽书看。","小蜂得计欺侬睡，偷饮晴窗砚滴乾。"]},{"t":"南溪弄水回望山园梅花","f":"七言绝句","c":["梅从山上过溪来，近爱清溪远爱梅。","溪水声声留我住，梅花朵朵唤人回。"]},{"t":"南溪薄晚观水","f":"七言绝句","c":["谁将沙砾壅堤斜，水怒冲堤自决沙。","无数小鱼齐乱跳，琉璃盘底簸银花。"]},{"t":"城头秋望 其二","f":"七言绝句","c":["未得霜晴未是晴，霜晴无复点云生。","鹭鸶不遣鱼惊散，移却惟愁水作声。"]},{"t":"城头秋望 其一","f":"七言绝句","c":["秋光好处顿胡床，旋唤茶瓯浅著汤。","隔树漏天青破碎，惊风度竹碧匆忙。"]},{"t":"城头晓步二首 其二","f":"七言绝句","c":["城东行遍却城西，欲问梅花乞一枝。","雪糁久团霜后朵，嗔人频看故开迟。"]},{"t":"城头晓步二首 其一","f":"七言绝句","c":["古城秋后不胜荒，人迹新行一径长。","竹影已摇将午日，草根犹有夜来霜。"]},{"t":"城壕冰泮","f":"七言绝句","c":["雪力平欺半月晴，东风今日始开冰。","长壕彻底都销尽，只有楼阴玉一棱。"]},{"t":"将至永丰县","f":"七言绝句","c":["清和天气半阴晴，下轿携筇取次行。","不奈永丰山色好，云窥雾看未分明。"]},{"t":"将至建昌","f":"七言绝句","c":["梅雨芹泥路不佳，闷来小歇野人家。","绿萍池沼垂杨里，初见芙蕖第一花。"]},{"t":"将至萍乡欲宿为重客据馆乃出西郊","f":"七言绝句","c":["哦诗浑忘路高低，忽怪松梢与路齐。","准拟醉眠萍实驿，驿西西去更山西。"]},{"t":"将近许市望见虎丘","f":"七言绝句","c":["许市人家远树前，虎丘山色夕阳边。","石桥分水入别港，茅屋垂杨仍钓船。"]},{"t":"将赴高安出吉水报谒县官归涂宿五峰寺二首 其二","f":"七言绝句","c":["野寺重来记昨游，一弹指顷几经秋。","五峰绝顶双松树，相识儿时到白头。"]},{"t":"将赴高安出吉水报谒县官归涂宿五峰寺二首 其一","f":"七言绝句","c":["风暄雨暖日和柔，道是秾春不道秋。","楚楚江枫新结束，柿红衫子锦缠头。"]},{"t":"将睡四首 其四","f":"五言绝句","c":["睡去非不愿，热来无奈何。","蒙渠致西爽，为汝守南柯。"]},{"t":"将睡四首 其三","f":"五言绝句","c":["已被诗为祟，更添茶作魔。","端能去二者，一武到无何。"]},{"t":"将睡四首 其二","f":"五言绝句","c":["一更打二点，夜夜此时睡。","今夜当此时，不睡缘底事。"]},{"t":"将睡四首 其一","f":"五言绝句","c":["老夫岂不眠，只是眠未得。","若到睡思来，华胥是谁国。"]},{"t":"尝桃","f":"七言绝句","c":["金桃两饤照银杯，一是栽来一买来。","香味比尝无两样，人情毕竟爱亲栽。"]},{"t":"峡山寺竹枝词五首 其五","f":"七言绝句","c":["天齐浪自说浯溪，峡与天齐真个齐。","未必峡山高尔许，看来只恐是天低。"]},{"t":"峡山寺竹枝词五首 其四","f":"七言绝句","c":["一滩过了一滩奔，一石横来一石蹲。","若怨古来天设险，峡山不到也由君。"]},{"t":"峡山寺竹枝词五首 其三","f":"七言绝句","c":["龟鱼到此总回头，不但龟鱼蟹亦愁。","底事诗人轻老命，犯滩冲石去韶州。"]},{"t":"峡山寺竹枝词五首 其二","f":"七言绝句","c":["一水双崖千万萦，有天无地只心惊。","无人打杀杜鹃子，雨外飞来头上声。"]},{"t":"峡山寺竹枝词五首 其一","f":"七言绝句","c":["峡里撑船更不行，棹郎相语改行程。","却从西岸抛东岸，依旧船头不可撑。"]},{"t":"幽居三咏 其三 诚斋","f":"七言绝句","c":["浯溪见了紫岩回，独笑春风尽放怀。","谩向世人谈昨梦，便来唤我作诚斋。"]},{"t":"幽居三咏 其一 钓雪舟","f":"七言绝句","c":["青鞋黄帽绿蓑衣，钓雪舟中雪政飞。","归自严州无一物，扁舟载得钓台归。"]},{"t":"幽居感兴","f":"七言绝句","c":["葛制冰餐消几钱，云栖水宿本臞仙。","回头背汗浑如雨，赚却闲身四十年。"]},{"t":"度雪台","f":"七言绝句","c":["二月尽头三月来，红红白白一齐开。","酴醾正要金沙映，莫道金沙只漫栽。"]},{"t":"彦通以诗送石菖蒲和谢之","f":"七言绝句","c":["笑拂孤芳旋汲泉，忽如身堕晓霜天。","一生寒瘦知何用，只得清名垂万年。"]},{"t":"彦通叔祖约游云水寺二首 其二","f":"七言绝句","c":["竹深草长绿冥冥，有路如无又断行。","风亦恐吾愁寺远，殷勤隔雨送钟声。"]},{"t":"彦通叔祖约游云水寺二首 其一","f":"七言绝句","c":["出门天色阴晴半，著雨途间进退难。","知得招提在何许，只凭田父指林间。"]},{"t":"拾柏子","f":"七言绝句","c":["皱壳倾来紫麦新，中藏琼米不胜珍。","胡桃松实何曾吃，却嚼秋风柏子仁。"]},{"t":"春日六绝句 其一","f":"五言绝句","c":["远目随天去，斜阳著树明。","犬知何处吠，人在半山行。"]},{"t":"春日六绝句 其五","f":"五言绝句","c":["日落碧簪外，人行红雨中。","幽人诗酒里，又是一春风。"]},{"t":"春日六绝句 其二","f":"五言绝句","c":["春醉非关酒，郊行不问涂。","青天何处了，白鸟入空无。"]},{"t":"春日六绝句 其六","f":"五言绝句","c":["春色有情意，桃花生暮寒。","只应催客子，不遣立江干。"]},{"t":"春日六绝句 其三","f":"五言绝句","c":["雾气因山见，波痕到岸消。","诗人元自懒，物色故相撩。"]},{"t":"春日六绝句 其四","f":"五言绝句","c":["江水夜韶乐，海棠春贵妃。","殷勤向春道，莫遣一花飞。"]},{"t":"春半闻归雁","f":"七言绝句","c":["春光深浅没人知，我正南归雁北归。","头上一声如话别，一生长是背人飞。"]},{"t":"春尽夜坐三首 其三","f":"七言绝句","c":["病夫说病诉旁人，它自开眉我自颦。","后有病夫看病句，不须告诉亦沾巾。"]},{"t":"春尽夜坐三首 其二","f":"七言绝句","c":["疾痛呼天天岂知，知而不管亦何为。","偶拈白傅长庆集，又得驩欣片子时。"]},{"t":"春尽夜坐三首 其一","f":"七言绝句","c":["春光草草病中休，病眼逢春道是秋。","祗有青灯怜此老，伴人无睡照人愁。"]},{"t":"春尽舍舟馀杭雨后山行二首 其二","f":"七言绝句","c":["树树低桑不要梯，溪溪新涨总平堤。","杜鹃知我归心急，林外飞来头上啼。"]},{"t":"春尽舍舟馀杭雨后山行二首 其一","f":"七言绝句","c":["前夕船中索簟眠，今朝山下觉衣单。","春归便肯平平过，须做桐花一信寒。"]},{"t":"春阴","f":"七言绝句","c":["春晴幸好却春阴，云意涔涔半欲霖。","日色忽开云又合，急收碎影一帘金。"]},{"t":"春阴忽霁","f":"七言绝句","c":["云膜辛勤护日华，一重縠子一重纱。","玉奁忽透菱花影，淡与油窗描杏花。"]},{"t":"春夜孤坐三首 其三","f":"七言绝句","c":["老来觅句苦难成，细把风斤镂薄冰。","行到长廊人寂寂，隔窗一点读书灯。"]},{"t":"春夜孤坐三首 其二","f":"七言绝句","c":["梅花雪后杏花风，老面逢春只强红。","诗句行来行去里，情怀不醉不醒中。"]},{"t":"春夜孤坐三首 其一","f":"七言绝句","c":["儿女齁齁鼻息声，虚堂谁伴一先生。","春寒夜静灯花落，数尽残更睡不成。"]},{"t":"春雨不止二首 其二","f":"七言绝句","c":["春雨如毛又似埃，云开还合合还开。","怪来春晚寒如许，无赖桐花领取来。"]},{"t":"春雨不止二首 其一","f":"七言绝句","c":["无计奈何春日长，宰予介绍谒羲皇。","蚁才问阵天又雨，蜂欲舂粮花政香。"]},{"t":"春草二首 其二","f":"七言绝句","c":["年年春色属垂杨，金撚千丝翠万行。","今岁草芽先得计，搀它浓翠夺它黄。"]},{"t":"春草二首 其一","f":"七言绝句","c":["天欲游人不踏尘，一年一换翠茸茵。","东风犹自嫌萧索，更遣飞花绣好春。"]},{"t":"春晓三首 其三","f":"七言绝句","c":["一年生活是三春，二月春光尽十分。","不必开窗索花笑，隔窗花影也欣欣。"]},{"t":"春晓三首 其二","f":"七言绝句","c":["风光明淑奈渠何，非暖非寒直是和。","春到千花俱有分，海棠独自得春多。"]},{"t":"春晓三首 其一","f":"七言绝句","c":["拂花红露溅春衣，柳外春禽睡未知。","天借晴光与桃李，更将剩彩弄游丝。"]},{"t":"春望二首 其二","f":"七言绝句","c":["掠削娇云放嫩晴，三朝五日即清明。","垂杨幸自风流杀，莫著啼乌只著莺。"]},{"t":"春望二首 其一","f":"七言绝句","c":["春光放尽百花房，开到林檎与海棠。","青却子城千树柳，高枝犹有一梢黄。"]},{"t":"春梦纷纭","f":"七言绝句","c":["烛花半作紫芝开，诗兴频遭白雨催。","只有睡时愁可遣，春愁又向梦中来。"]},{"t":"春寒","f":"七言绝句","c":["风日晴暄一并来，桃花告报李花开。","待君减尽衣裘了，夜半春寒特地回。"]},{"t":"春寒","f":"七言绝句","c":["春寒尽解粟人肤，敢傍吾侪酒盏无。","雨里杏花如半醉，抬头不起索人扶。"]},{"t":"春寒","f":"七言绝句","c":["阵阵风寒树树斜，不容老子出檐牙。","绣帘半捲门偏启，深倚胡床远看花。"]},{"t":"春寒初晴","f":"七言绝句","c":["峭寒穿屋透衣裘，欺得诗人两鬓秋。","从此莫教三日暖，花开花落却成愁。"]},{"t":"春寒绝句","f":"七言绝句","c":["几丝微雨噀前山，半点轻寒健牡丹。","只道一春晴较少，到它晴了是春残。"]},{"t":"雨中送客有感","f":"七言绝句","c":["不知春向雨中回，只道春光未苦来。","老子今晨偶然出，李花全落郑花开。"]},{"t":"春暖郡圃散策三首 其三","f":"七言绝句","c":["春禽处处讲新声，细草欣欣贺嫩晴。","曲折遍穿花底路，莫令一步作虚行。"]},{"t":"春暖郡圃散策三首 其二","f":"七言绝句","c":["萱草行间过履絇，杏花影里散文书。","秋风遣我疏团扇，又被春风遣唤渠。"]},{"t":"春暖郡圃散策三首 其一","f":"七言绝句","c":["已觉朝来退裌衣，日光风力软如痴。","倩谁留许春寒著，更放梅花住少时。"]},{"t":"昼倦","f":"七言绝句","c":["爱日曛人欲睡昏，自匀嫩火炷炉薰。","蜘蛛已去惟存网，犹罥窗间一只蚊。"]},{"t":"昼倦","f":"七言绝句","c":["睡眼䰒松倦日长，却抛诗卷步回廊。","狸奴幸自双双戏，忽见人来走似獐。"]},{"t":"柳色","f":"五言绝句","c":["春到四经旬，元来未见春。","柳条将软碧，争献上番新。"]},{"t":"残菊","f":"七言绝句","c":["肠断黄花霜后枝，花乾叶悴两离披。","一花忽秀枯丛里，更胜初开乍见时。"]},{"t":"毗陵郡斋冬至晴寒","f":"七言绝句","c":["竹屋消残半瓦霜，冰河冻裂一渔航。","不须宫线量曦影，化日今年特地长。"]},{"t":"毗陵辞满出舍添倅厅","f":"七言绝句","c":["小住丞厅更一旬，客魂先入故乡春。","未离鼓角声中梦，已是谯门外面人。"]},{"t":"泉石轩初秋乘凉小荷池上","f":"七言绝句","c":["芙蕖落片自成船，吹泊高荷伞柄边。","泊了又离离又泊，看它走遍水中天。"]},{"t":"洗面绝句","f":"七言绝句","c":["浙山两岸送归艎，新捣春蓝浅染苍。","自汲江波供盥漱，清晨满面落花香。"]},{"t":"济翁弟赠白团扇子一面作百竹图有诗和以谢之","f":"七言绝句","c":["月波初上涌寒金，桂树风来细有音。","特地此君偏作恼，为侬隔却半轮阴。"]},{"t":"牵牛花三首 其三","f":"七言绝句","c":["晓思欢欣晚思愁，绕篱萦架太娇柔。","木犀未发芙蓉落，买断西风恣意秋。"]},{"t":"癸丑正月新开东园","f":"七言绝句","c":["长恨无钱买好园，好园还在屋东边。","周遭旋辟三三径，只怕芒鞋却费钱。"]},{"t":"皇恐滩三首 其三","f":"七言绝句","c":["小烦溪友语阳侯，好遣漂沙盖石头。","能费奔流多少力，前头幸有一沙洲。"]},{"t":"皇恐滩三首 其二","f":"七言绝句","c":["只愁江水去无还，石打银涛倒上滩。","道是此滩天下恶，古今放过几樯竿。"]},{"t":"皇恐滩三首 其一","f":"七言绝句","c":["两山夹岸走苍龙，未放中间过玉虹。","只爱当头一峰好，一峰外面更三峰。"]},{"t":"省中见树上啄木鸟戏题","f":"七言绝句","c":["一啄高高一啄低，一声声急一声迟。","可怜去蠹劳心口，蚁入枯梨自不知。"]},{"t":"省中直舍因敲新竹怀周元吉三首 其三","f":"七言绝句","c":["老竹坚刚幼竹柔，此君年少也风流。","锦衣脱体未全瘦，雪粉围腰犹半愁。"]},{"t":"省中直舍因敲新竹怀周元吉三首 其二","f":"七言绝句","c":["尚有周郎手种痕，怀人将竹当人看。","寄言黄鹤楼前客，今岁新添十五竿。"]},{"t":"省中直舍因敲新竹怀周元吉三首 其一","f":"七言绝句","c":["老眼逢书怯细看，抄书一事更应难。","昨携如意敲新箨，右臂朝来作许酸。"]},{"t":"省中新柳","f":"七言绝句","c":["元日新春已早归，却缘春雪勒春迟。","一年柳色今何似，政是犹黄未绿时。"]},{"t":"看小舟除萍二首 其二","f":"七言绝句","c":["岁岁荷花苦未多，绿萍盖水碍新荷。","请君六月重来看，云锦千机不犯梭。"]},{"t":"看小舟除萍二首 其一","f":"七言绝句","c":["花伴吟哦柳伴行，生憎庭外晚衙声。","独携便面巡荷沼，自课兰舟掠水萍。"]},{"t":"看画常州图迎新太守","f":"七言绝句","c":["画工吮笔画常州，老子来看却自羞。","若遣此图还解语，道侬调戏几君侯。"]},{"t":"看雪","f":"七言绝句","c":["揉云剪水作风毬，夜落连明肯便休。","旧说六花元未试，偶看一片上驼裘。"]},{"t":"神堂铺前桃花","f":"七言绝句","c":["北江二月政春寒，初见桃花喜未残。","腊月潮州见桃李，元来不作好春看。"]},{"t":"秋夕不寐二首 其一","f":"七言绝句","c":["每到炎天只愿秋，如何秋到却成愁。","官居也有寒蛩语，不似山间听得幽。"]},{"t":"秋夕不寐二首 其二","f":"七言绝句","c":["夏热通宵睡不成，秋凉老眼又偏醒。","窗虚月白清无梦，却为西风数漏声。"]},{"t":"秋山二首 其二","f":"七言绝句","c":["乌臼平生老染工，错将铁皂作猩红。","小枫一夜偷天酒，却倩孤松掩醉容。"]},{"t":"秋山二首 其一","f":"七言绝句","c":["休道秋山索莫人，四时各自一番新。","西风尽有东风手，柿叶枫林别样春。"]},{"t":"秋虫","f":"七言绝句","c":["蝉哀落日恰才收，蛩怨黄昏正未休。","催得世人头总白，不知替得二虫愁。"]},{"t":"秋花","f":"七言绝句","c":["憔悴牵牛病雨些，凋零木槿怯风斜。","道边篱落聊遮眼，白白红红匾豆花。"]},{"t":"秋夜不寐","f":"七言绝句","c":["秋气侵人冷欲冰，不由老境不愁生。","雨声已遣侬无睡，更著寒蛩泣到明。"]},{"t":"秋夜极热三首 其三","f":"七言绝句","c":["葵扇频挥手已麻，竹床偏热冷无些。","面凉却感须根汗，省得开门汲井花。"]},{"t":"秋夜极热三首 其二","f":"七言绝句","c":["秋神今岁也痴呆，行李如何草草回。","白帝羽衣浑不带，炎官火伞却将来。"]},{"t":"秋夜极热三首 其一","f":"七言绝句","c":["只怨西风不早归，早归何似且归迟。","姮娥一夜摇团扇，更说明朝日午时。"]},{"t":"秋雨叹十解 其十","f":"七言绝句","c":["不是檐声不放眠，只将愁思压衰年。","道他滴沥浑无赖，不到侯门舞袖边。"]},{"t":"秋雨叹十解 其六","f":"七言绝句","c":["老子愁来只苦吟，一吟一叹为秋霖。","居人只道秋霖苦，不道行人泥更深。"]},{"t":"秋雨叹十解 其八","f":"七言绝句","c":["晓起穷忙作么生，雨中安否问秋英。","枯荷倒尽饶渠著，滴损兰花太薄情。"]},{"t":"秋雨叹十解 其一","f":"七言绝句","c":["雨入秋宵滴到明，不知有意复无情。","若言不搅愁人梦，为许千千万万声。"]},{"t":"秋雨叹十解 其七","f":"七言绝句","c":["昼落无声夜有声，只堪醉听不堪醒。","檐牙半点能多少，滴入苔阶一寸青。"]},{"t":"秋雨叹十解 其四","f":"七言绝句","c":["厌听点滴井边桐，起看空濛一望中。","横著东山三十里，真珠帘外翠屏风。"]},{"t":"秋雨叹十解 其二","f":"七言绝句","c":["霖霖滴滴未休休，不解教侬不白头。","却把穷愁比秋雨，犹应秋雨少于愁。"]},{"t":"秋雨叹十解 其五","f":"七言绝句","c":["篱下黄花最恨它，金钿香少泪痕多。","仙人解补银河漏，天上无泥奈许何。"]},{"t":"秋雨叹十解 其三","f":"七言绝句","c":["湿侵团扇不能轻，冷逼孤灯分外明。","蕉叶半黄荷叶碧，两家秋雨一家声。"]},{"t":"秋雨叹十解 其九","f":"七言绝句","c":["似雾如尘有却无，须臾密密复疏疏。","忽忘九月清霜晓，唤作濛濛二月初。"]},{"t":"秋凉晚步","f":"七言绝句","c":["秋气堪悲未必然，轻寒政是可人天。","绿池落尽红蕖却，荷叶犹开最小钱。"]},{"t":"秋晓出郊二绝句 其一","f":"七言绝句","c":["初日新寒政晓霞，残山剩水稍人家。","霜红半脸金罂子，雪白一川荞麦花。"]},{"t":"秋晓出郊二绝句 其二","f":"七言绝句","c":["野菊相依露下丛，冷香自送水边风。","丰年气象无多子，只在鸡鸣犬吠中。"]},{"t":"秋热","f":"七言绝句","c":["今年秋热倍常年，更住西峰落照村。","最是樱桃梢上日，裴回不落等黄昏。"]},{"t":"秋热二首 其二","f":"七言绝句","c":["年年极暑与秋期，日日秋阳在暮时。","我自愁吟无意思，蝉声移近入檐枝。"]},{"t":"秋热二首 其一","f":"七言绝句","c":["多难幽怀惨不舒，秋风残暑扫难除。","一生最怕西窗日，长是酴醾架子疏。"]},{"t":"秋暑二首 其二","f":"七言绝句","c":["追凉能到竹溪无，隔水斜阳未肯晡。","剩暑不蒙蕉扇扇，细云聊倩月梳梳。"]},{"t":"秋暑二首 其一","f":"七言绝句","c":["一年强半走尘埃，触热还山亦快哉。","幸自西风归较早，却教秋暑伴将来。"]},{"t":"秋暑三首 其三","f":"七言绝句","c":["半柳斜阳半柳阴，一蝉飞去一蝉吟。","岸巾亭子钩栏角，送眼江村松树林。"]},{"t":"秋暑三首 其二","f":"七言绝句","c":["汗如雨点涌人肤，一一须根一一珠。","不道去年秋不热，今年秋热去年无。"]},{"t":"秋暑三首 其一","f":"七言绝句","c":["不教老子略眉开，夏热未除秋热来。","一夜凉风吹欲尽，半轮晓日唤将回。"]},{"t":"秋暑午睡起汲泉洗面","f":"七言绝句","c":["大桶双担新井花，松盆满泻莫留些。","刺头蘸入松盆底，不是清凉第二家。"]},{"t":"秋蝇","f":"七言绝句","c":["秋蝇知我政哦诗，得得缘眉复入髭。","欲打群飞还歇去，风光乞与几多时。"]},{"t":"绝句","f":"五言绝句","c":["枫老颜方少，山晴气反昏。","旧贫今更甚，已冷幸犹暄。"]},{"t":"荔枝堂夕眺三首 其三","f":"七言绝句","c":["闰年秋浅似秋深，蟋蟀将愁傍砌吟。","今夕初三元未觉，西楼西角一钩金。"]},{"t":"荔枝堂夕眺三首 其二","f":"七言绝句","c":["病骨秋臞怯暮清，凉风偷带北风轻。","迎寒窗隔重糊遍，只放书边数眼明。"]},{"t":"荔枝堂夕眺三首 其一","f":"七言绝句","c":["夕峰褪日半钲多，秋汉吹云一絮过。","寂寂庭松今两月，鹤雏去尽只留窠。"]},{"t":"贺皇太子九月四日生辰 其十","f":"七言绝句","c":["光尧初御六龙天，上直维参大火躔。","天意分明昌宋德，诞辰三世总丁年。"]},{"t":"贺皇太子九月四日生辰 其九","f":"七言绝句","c":["少阳拜赐太阳旁，黄菊红萸满寿觞。","阳德重重在初四，不须九日是重阳。"]},{"t":"贺皇太子九月四日生辰 其八","f":"七言绝句","c":["禹子汤孙兼圣贤，一身双美古无前。","愿陈万国元良句，不用金昭玉粹篇。"]},{"t":"贺皇太子九月四日生辰 其七","f":"七言绝句","c":["菊花潭上菊花开，不是花潭是寿杯。","天赐生朝千斛水，一年一斛送将来。"]},{"t":"贺皇太子九月四日生辰 其六","f":"七言绝句","c":["大安宫里漆园椿，子干孙枝叶叶新。","今日四株高下碧，相承一样八千春。"]},{"t":"贺皇太子九月四日生辰 其五","f":"七言绝句","c":["明河查上有仙翁，犯月撞星到碧穹。","金阙东边银榜处，大书天地长男宫。"]},{"t":"贺皇太子九月四日生辰 其四","f":"七言绝句","c":["二圣多能似仲尼，储皇家学自庭闱。","银钩已有淳熙脚，玉句仍传德寿衣。"]},{"t":"贺皇太子九月四日生辰 其三","f":"七言绝句","c":["子晋吹笙未是仙，阿丕横槊少全篇。","小吟春著梅梢句，一日东风四海传。"]},{"t":"贺皇太子九月四日生辰 其二","f":"七言绝句","c":["清赏堂中无管弦，凤山楼上有云烟。","储皇侧畔何人侍，黄卷团栾是圣贤。"]},{"t":"赵村","f":"七言绝句","c":["杏花千树洛阳春，白傅年年爱赵村。","月蕊晴葩风露格，老夫移得在东园。"]},{"t":"赵达明太社四月一日招游西湖十首 其十","f":"七言绝句","c":["葱茏晚色正佳哉，苦被归鞍紧紧催。","船压浮荷沈水底，须臾船过却浮来。"]},{"t":"赵达明太社四月一日招游西湖十首 其九","f":"七言绝句","c":["风撩太液小荷欹，日丽长杨花影低。","阑入苑中啼不歇，恨身不及一黄鹂。"]},{"t":"赵达明太社四月一日招游西湖十首 其八","f":"七言绝句","c":["行尽孤山碧四围，却寻初路得来时。","好风借与归船便，吹近琼林却不吹。"]},{"t":"赵达明太社四月一日招游西湖十首 其七","f":"七言绝句","c":["和靖先生坟已荒，空馀松竹故苍苍。","王孙自洗鸬鹚杓，满酌真珠酹一觞。"]},{"t":"赵达明太社四月一日招游西湖十首 其六","f":"七言绝句","c":["橘花如雪细吹香，杏子团枝未可尝。","行到陈朝枯柏处，孤山山背水中央。"]},{"t":"赵达明太社四月一日招游西湖十首 其五","f":"七言绝句","c":["萍生儿子点疏星，荷捲文书立万丁。","回首南高峰上塔，手中攀得玉竛竮。"]},{"t":"赵达明太社四月一日招游西湖十首 其四","f":"七言绝句","c":["御池水满苑门开，泥带飞花路带苔。","到得孤山翻作恶，海棠闹日不曾来。"]},{"t":"赵达明太社四月一日招游西湖十首 其三","f":"七言绝句","c":["船从咏泽过孤山，径度琉璃一簟间。","隔岸多情杨柳树，向人招唤俯烟鬟。"]},{"t":"赵达明太社四月一日招游西湖十首 其二","f":"七言绝句","c":["画舫侵晨系柳枝，主人生怕客来迟。","娇云嫩日无风色，幸是湖船好放时。"]},{"t":"赵达明太社四月一日招游西湖十首 其一","f":"七言绝句","c":["今日清和和又清，王孙领客出都城。","好天胜日能多少，三到西湖始一晴。"]},{"t":"送乡僧德璘二首 其二","f":"七言绝句","c":["湖上诸峰紫翠间，三年欲到几曾闲。","侬今去处渠知么，不是南山即北山。"]},{"t":"送乡僧德璘二首 其一","f":"七言绝句","c":["衲子向来元士子，诗僧遮莫更禅僧。","不妨参透诸方得，别有宫墙第一层。"]},{"t":"送乡僧德璘监寺缘化结夏归天童山二首 其二","f":"七言绝句","c":["七百支郎夜忍饥，木鱼闭口等君归。","还山大众空欢喜，只有诚斋两首诗。"]},{"t":"送乡僧德璘监寺缘化结夏归天童山二首 其一","f":"七言绝句","c":["一别璘公十二年，故当刮目为相看。","问侬收得曹溪水，雩下春风吹已乾。"]},{"t":"送王无咎善邵康节皇极数二首 其二","f":"七言绝句","c":["识尽江淮诸贵人，归来卢水一番新。","问渠福将今谁子，容我升平作倖民。"]},{"t":"送王无咎善邵康节皇极数二首 其一","f":"七言绝句","c":["安乐窝中书一编，君从何许得真传。","我无杜曲桑麻在，也道此生休问天。"]},{"t":"送卢山人二首 其二","f":"七言绝句","c":["有欠牛眠子为寻，剩将朽胔换华簪。","家阡只免牛羊到，此外穷通得上心。"]},{"t":"送卢山人二首 其一","f":"七言绝句","c":["行尽千山又万山，山真何好子能然。","青乌纵妙侬曾问，著眼烟云也自贤。"]},{"t":"送幼舆子之官澧浦慈利监税二首 其二","f":"七言绝句","c":["素王开国道无臣，一榜春风放十人。","莫羡榜头年十八，旧春过了有新春。"]},{"t":"送幼舆子之官澧浦慈利监税二首 其一","f":"七言绝句","c":["估人耕货不耕田，也合供输饷万屯。","若道厚征为报国，厚民却是负君恩。"]},{"t":"送刘北秀二首 其二","f":"七言绝句","c":["赠我盆花十小诗，菖蒲一咏最清奇。","洞庭卷入坚昆椀，更卷青天入寸漪。"]},{"t":"送刘北秀二首 其一","f":"七言绝句","c":["刘子过逢二十年，别来风月几千篇。","黄金卖尽延宾友，囊底何须看一钱。"]},{"t":"送庆基叔往上犹二绝 其二","f":"七言绝句","c":["六十慈亲路一千，郎君归省又何年。","赠行句子真聊尔，且折垂杨当赠鞭。"]},{"t":"送杨山人善谈相及地理","f":"七言绝句","c":["相人何似相山难，惭愧渠侬眼不寒。","木末凉风无半点，如何又欲跨归鞍。"]},{"t":"送罗永年西归","f":"七言律诗","c":["梅莟香边踏雪来，杏花雨里带春回。","明朝解缆还千里，今日看花更一杯。","谁遣文章太惊俗，何缘场屋不遗才。","南溪鸥鹭如相问，为报春吟费麝煤。"]},{"t":"送客山行","f":"七言绝句","c":["岭云为作小凉天，山店重来忆去年。","独树丹枫谁不见，何须更立万松前。"]},{"t":"送客归至郡圃残雪销尽","f":"七言绝句","c":["三日东风入万家，草间残雪不留些。","儿童道是雪犹在，笑指梅花作雪花。"]},{"t":"送客归登净远亭二首 其二","f":"七言绝句","c":["池冰动处水生澜，未觉今朝抵死寒。","便恐雪销难再得，不辞鞋湿数来看。"]},{"t":"送客归登净远亭二首 其一","f":"七言绝句","c":["犯寒送客只劳神，上到危亭眼顿新。","雪汁滴人清入髓，莫将衫袖障头巾。"]},{"t":"送残秋","f":"七言绝句","c":["梦游帝里送残秋，重九真为帝里游。","十月初头方赐对，痴儿枉却一生愁。"]},{"t":"送相士高元善二首 其二","f":"七言绝句","c":["稚子烦君一一看，丁宁莫道好求官。","老来正要团栾坐，伴我秋风把钓竿。"]},{"t":"送相士高元善二首 其一","f":"七言绝句","c":["选官选佛两悠悠，元不关人浪自愁。","洙泗生涯久春草，老夫作么晚回头。"]},{"t":"送翁志道","f":"七言绝句","c":["平生翁子妙谈天，谁爱青山不爱官。","一笑同看岩下井，秋来能更起微澜。"]},{"t":"送谈命曾南翔二首 其二","f":"七言绝句","c":["今年见说也无锥，政坐谈天泄密机。","举世近来憎直语，贵人剩许未为痴。"]},{"t":"送谈命曾南翔二首 其一","f":"七言绝句","c":["官职牵人也可怜，老来那更问行年。","渠侬解事无它语，道我慈亲寿八千。"]},{"t":"送谈星辰许季升二首 其二","f":"七言绝句","c":["连珠合璧转璇霄，也被星家不见饶。","灾曜元来怯梼杌，福星不是背箪瓢。"]},{"t":"送谈星辰许季升二首 其一","f":"七言绝句","c":["许子儒冠怨误身，如今投笔说星辰。","未须道我何时贵，且道何时子脱贫。"]},{"t":"送谈星辰吴山人","f":"七言绝句","c":["牙筹入手风前快，玉李行天镜里看。","紫闼青规吾不梦，子言欲试故应难。"]},{"t":"送傅山人二绝句 其二","f":"七言绝句","c":["谈天渠外更谁先，聊复怜渠与酒钱。","富贵不愁天不管，不应丘壑也关天。"]},{"t":"送傅山人二绝句 其一","f":"七言绝句","c":["江山有约未应疏，浪自忙中白却须。","我昔属官今属我，子能略伴瘦藤无。"]},{"t":"送德轮行者","f":"七言绝句","c":["沥血抄经奈若何，十年依旧一头陀。","袈裟未著愁多事，著了袈裟事更多。"]},{"t":"送瀛洲先生元举叔谈命郡城","f":"七言绝句","c":["谁遣谈天太逼真，取憎造物得辞贫。","不妨小隐君平肆，戏与人间阅贵人。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其七","f":"七言绝句","c":["村里风回市里声，月中人看雪中灯。","满城只道欢犹少，不道谯门冷似冰。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其六","f":"七言绝句","c":["雪后楼台欲暮时，游人只道上灯迟。","月轮贴在梅花背，错认梅枝作桂枝。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其五","f":"七言绝句","c":["不是东风巧剪裁，如何春夜碧莲开。","江城寂寞无歌舞，唤得梅花劝一杯。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其四","f":"七言绝句","c":["儿时行乐几时愁，老去情怀懒出游。","市上人家重时节，典钗卖钏买灯毬。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其三","f":"七言绝句","c":["忆昔三衢看上元，玉虹横贯水精帘。","穷州今夕酸寒杀，老眼看来自不忺。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其二","f":"七言绝句","c":["北使才归南使来，前船未送后船催。","元宵行乐年年事，儿女嗔人夜不回。"]},{"t":"郡中上元灯减旧例三之二而又迎送使客七首 其一","f":"七言绝句","c":["红锦芙蓉碧牡丹，今番灯火减前番。","雪泥没膝霜风紧，也有游人看上元。"]},{"t":"郡圃上巳二首 其二","f":"七言绝句","c":["寻春不见只思还，却在来仙小崦间。","映出一川桃李好，只消外面矮青山。"]},{"t":"郡圃上巳二首 其一","f":"七言绝句","c":["旋收雨夕放晴晨，禊日风光正可人。","间白参红方是锦，疏桃散李不成春。"]},{"t":"郡圃小梅一枝先开","f":"七言绝句","c":["小窠梅树太尖新，先为东风觅得春。","后日千株空玉雪，如今一朵许精神。"]},{"t":"郡圃残雪三首 其三","f":"七言绝句","c":["城外城中雪半开，远峰依旧玉崔嵬。","池冰绽处才如线，便有鸳鸯浮过来。"]},{"t":"郡圃晓步因登披仙阁四首 其四","f":"七言绝句","c":["只道春来不见痕，风邀雨勒未忺人。","暄云淑日消多少，花柳匆匆了却春。"]},{"t":"郡圃晓步因登披仙阁四首 其三","f":"七言绝句","c":["百五佳时更绝晨，园丁犹未放游人。","瘦藤拄上披仙阁，四面花光照杀春。"]},{"t":"郡圃晓步因登披仙阁四首 其二","f":"七言绝句","c":["李花半落雪成堆，末后桃花陆续开。","白锦地衣红锦障，侵晨供张等侬来。"]},{"t":"郡圃晓步因登披仙阁四首 其一","f":"七言绝句","c":["昨来风日较暄些，破晓来游特地佳。","也自低头花下过，依前撞落一头花。"]},{"t":"郡圃雪销已尽惟馀城阴一街雪","f":"七言绝句","c":["阳林日暖雪全销，阴径琼瑶尚寸高。","半疋斜铺白花锦，倩谁裁作水霜袍。"]},{"t":"郡斋梅花","f":"七言绝句","c":["月朵千痕雪半梢，便无雪月更飘萧。","不应腊尾春头里，两岁风光一并饶。"]},{"t":"除夕前一日绝句","f":"七言绝句","c":["雪留远岭半尖白，云漏斜阳一线黄。","天肯放晴差易耳，殷勤剩觅几朝霜。"]},{"t":"除夜小饮叹都下酥乳不至","f":"七言绝句","c":["雪韭霜菘酌岁除，也无牛乳也无酥。","贫中却富何人会，自有村醪不用沽。"]},{"t":"食老菱有感","f":"七言绝句","c":["幸自江湖可避人，怀珠韫玉冷无尘。","何须抵死露头角，荇叶荷花老此身。"]},{"t":"食鸡头","f":"七言绝句","c":["龙宫失晓恼江妃，也养鸣鸡报早晖。","要啄稻粱无半粒，只教满颔饱珠玑。"]},{"t":"食莲子","f":"七言绝句","c":["蜂不禁人采蜜忙，荷花蕊里作蜂房。","不知玉蛹甜于蜜，又被诗人嚼作霜。"]},{"t":"食莲子","f":"七言绝句","c":["绿玉蜂房白玉蜂，折来带露复含风。","玻瓈盆面冰浆底，醉嚼新莲一百蓬。"]},{"t":"食莲子三首 其三","f":"七言绝句","c":["戢戢蜂儿出露房，未生翅股及锋芒。","丁宁莫遣它人剥，要染侬家十指香。"]},{"t":"食莲子三首 其二","f":"七言绝句","c":["城中莲子买将归，未问尝新早与迟。","偶忆涌金门外晓，画船带露摘来时。"]},{"t":"食莲子三首 其一","f":"七言绝句","c":["白玉蜂儿绿玉房，蜂房未绽已闻香。","蜂儿解醒诗人醉，一嚼清冰一咽霜。"]},{"t":"食蛎房","f":"七言绝句","c":["蓬山侧畔屹蚝山，怀玉深藏万壑间。","也被酒徒勾引著，荐它尊俎解它颜。"]},{"t":"鸦","f":"七言绝句","c":["稚子相看只笑渠，老夫亦复小卢胡。","一鸦飞立钩栏角，子细看来还有须。"]},{"t":"夏日绝句","f":"七言绝句","c":["不但春妍夏亦佳，随缘花草是生涯。","鹿葱解插纤长柄，金凤仍开最小花。"]},{"t":"夏月频雨","f":"七言绝句","c":["一番暑雨一番凉，真个令人爱日长。","隔水风来知有意，为吹十里稻花香。"]},{"t":"夏至后初暑登连天观","f":"七言绝句","c":["登台长早下台迟，移遍胡床无处移。","不是清凉罢挥扇，自缘手倦歇些时。"]},{"t":"夏至雨霁与陈履常暮行溪上二首 其二","f":"七言绝句","c":["夕凉恰恰好溪行，暮色催人底急生。","半路蛙声迎步止，一荧松火隔篱明。"]},{"t":"夏至雨霁与陈履常暮行溪上二首 其一","f":"七言绝句","c":["西山已暗隔金钲，犹照东山一抹明。","片子时间弄山色，乍黄乍紫忽全青。"]},{"t":"夏夜追凉","f":"七言绝句","c":["夜热依然午热同，开门小立月明中。","竹深树密虫鸣处，时有微凉不是风。"]},{"t":"悯农","f":"七言绝句","c":["稻云不雨不多黄，荞麦空花早著霜。","已分忍饥度残岁，更堪岁里闰添长。"]},{"t":"料理小荷池","f":"七言绝句","c":["侧塞浮荷更泛苔，为芟数路水痕开。","鱼儿便喜新开港，绕去绕来千百回。"]},{"t":"晓入秘书省过三桥","f":"七言绝句","c":["船底吴侬尚晏眠，一船炊饭数船烟。","行人各自东西岸，抵死回头看两边。"]},{"t":"晓出净慈送林子方二首 其一","f":"七言绝句","c":["出得西湖月尚残，荷花荡里柳行间。","红香世界清凉国，行了南山却北山。"]},{"t":"晓出兜率寺送许耀卿二首 其二","f":"七言绝句","c":["兜率山深露气清，柳阴暗处藕花明。","无端拾得闲烦恼，背却西湖又入城。"]},{"t":"晓出兜率寺送许耀卿二首 其一","f":"七言绝句","c":["天竺兴云线许长，须臾遮尽众苍苍。","何如洒作千峰雨，乞与都城六月凉。"]},{"t":"晓发黄巢矶芭蕉林中","f":"七言绝句","c":["清远山前烟雨濛，黄巢矶畔水连空。","旋芟芦荻炊朝饭，更斫芭蕉补漏篷。"]},{"t":"晓行闻竹鸡二首 其二","f":"七言绝句","c":["一番行路一番愁，还自儿时到白头。","路不唤君君自去，为谁著急不归休。"]},{"t":"晓行闻竹鸡二首 其一","f":"七言绝句","c":["山行三日厌泥行，幸自今晨得一晴。","又听数声泥滑滑，情知浪语也心惊。"]},{"t":"晓行道旁杜鹃花","f":"七言绝句","c":["泣露啼红作么生，开时偏值杜鹃声。","杜鹃口血能多少，不是征人泪滴成。"]},{"t":"晓过丹阳县五首 其五","f":"七言绝句","c":["水从常润路都迷，曲曲长河曲曲堤。","不是两窗供日脚，更无南北与东西。"]},{"t":"晓过丹阳县五首 其四","f":"七言绝句","c":["鸡犬渔翁共一船，生涯都在箬篷间。","小儿不耐初长日，自织筠篮胜打闲。"]},{"t":"晓过丹阳县五首 其三","f":"七言绝句","c":["朱檐碧瓦照青澜，洁馆佳亭使往还。","船上高桥三十尺，市人倚折石栏干。"]},{"t":"晓过丹阳县五首 其二","f":"七言绝句","c":["风从船里出船前，涨起帘帏紫拂天。","点检风来无处觅，破窗一隙小于钱。"]},{"t":"晓过丹阳县五首 其一","f":"七言绝句","c":["朝来稍敢出船门，霜熟依然冷逼人。","刮地风来何处避，可怜岸筱猛回身。"]},{"t":"晓过石门回望净慧塔","f":"七言绝句","c":["昨晚匆匆解画船，石门未到已黄昏。","殷勤净慧烟中塔，送我今朝过石门。"]},{"t":"晓过花桥入宣州界四首 其四","f":"七言绝句","c":["不是青山是画图，南山瘦削北敷腴。","两山名姓君知么，一字玄晖一圣俞。"]},{"t":"晓过花桥入宣州界四首 其三","f":"七言绝句","c":["近山浅绿远深青，两样风姿一样清。","似怨朝阳卷云雾，被侬看著太分明。"]},{"t":"晓过花桥入宣州界四首 其二","f":"七言绝句","c":["敬亭宛水故依然，叠嶂双溪阿那边。","谢守不生梅老死，倩谁海内掌风烟。"]},{"t":"晓过花桥入宣州界四首 其一","f":"七言绝句","c":["路入宣城山便奇，苍虬活走绿鸾飞。","诗人眼毒已先见，却旋褰云作翠帏。"]},{"t":"晓坐","f":"七言绝句","c":["拂晓文书已罢休，却披诗卷散闲愁。","只惊两眼生光彩，日到东窗半角头。"]},{"t":"晓坐多稼亭","f":"七言绝句","c":["日光烘碎一天云，散作濛濛雾满村。","我亦知渠别无事，不教远岫翠当门。"]},{"t":"晓坐卧治斋","f":"七言绝句","c":["夜风甚细不胜酸，霜落无声只是寒。","日上东窗无个事，送将梅影索人看。"]},{"t":"晓坐荷桥四首 其四","f":"七言绝句","c":["帘影窥池到藕根，水光为我弄朝暾。","鱼儿解作晴天雨，波面吹成落点痕。"]},{"t":"晓坐荷桥四首 其二","f":"七言绝句","c":["四叶青蘋点绿池，千重翠盖护红衣。","蜻蜓空里元无见，只见波间仰面飞。"]},{"t":"晓坐荷桥四首 其三","f":"七言绝句","c":["碧玉山边白鸟鸣，绿杨风里翠荷声。","草花踏碎教人惜，为勒芒鞋款款行。"]},{"t":"晓坐荷桥四首 其一","f":"七言绝句","c":["雨后晨前绝爽时，胡床四面是荷池。","荷珠细走惟愁落，为报薰风莫急吹。"]},{"t":"晓炊黄竹庄三首 其三","f":"七言绝句","c":["城中殊未有梅看，莫是冬暄欠浅寒。","行到深山最寒处，两株香雪照冰滩。"]},{"t":"晓炊黄竹庄三首 其二","f":"七言绝句","c":["琯灰蔌蔌欲飞声，日到牵牛第几星。","地底阳生人不觉，烧痕未冷已青青。"]},{"t":"晓炊黄竹庄三首 其一","f":"七言绝句","c":["染练江山宿雨馀，枝枝叶叶润如酥。","丝窠璎珞消多少，破费天公百斛珠。"]},{"t":"晓起探梅四首 其四","f":"七言绝句","c":["江梅小树打头开，便有红梅趁脚来。","趱得杏红开火急，春风已落第三回。"]},{"t":"晓起探梅四首 其三","f":"七言绝句","c":["一祖南枝派五房，红黄萼绿蜡鸳鸯。","杏红千叶元无种，谁子翻腾个样妆。"]},{"t":"晓起探梅四首 其二","f":"七言绝句","c":["打并人间名利心，万山佳处一溪深。","仙家忍饿禅家苦，老子梅边政醉吟。"]},{"t":"晓起探梅四首 其一","f":"七言绝句","c":["一生劫劫只长涂，投老山林始定居。","梦破灯青窗欲白，犹疑雪店听鸡初。"]},{"t":"晓穿芙蓉径二首 其二","f":"七言绝句","c":["芙蓉佳处不胜佳，花不中藏祗外斜。","恰似曲江闻喜宴，绿衣半醉戴宫花。"]},{"t":"晓穿芙蓉径二首 其一","f":"七言绝句","c":["晚妆懒困晓妆新，火急来看趁绝晨。","夹径花枝欺我老，竞将红露洒乌巾。"]},{"t":"晓寒二首 其二","f":"七言绝句","c":["春光唤入百花丛，寒力平欺两鬓蓬。","吹乱众红还复整，海棠却不怕东风。"]},{"t":"晓寒二首 其一","f":"七言绝句","c":["黯黯轻寒淡淡阴，游人便觉减行春。","春风也解嫌萧索，自送鞦韆不要人。"]},{"t":"晓晴发芜湖县吴波亭二首 其二","f":"七言绝句","c":["雨来初做养禾天，雨久还成害稼年。","今日一晴无准在，金鸦飞出卯牌前。"]},{"t":"晓晴发芜湖县吴波亭二首 其一","f":"七言绝句","c":["八日川涂九雨风，船中出得入泥中。","老夫强项谁能那，雨止风休伎自穷。"]},{"t":"晓登多稼亭三首 其三","f":"七言绝句","c":["尚无池水泛荷香，幸有园英照竹窗。","雪白葵花持玉节，柿红萱草立金幢。"]},{"t":"晓登多稼亭三首 其二","f":"七言绝句","c":["雨前田亩不胜荒，雨后农家特地忙。","一眼平畴三十里，际天白水立青秧。"]},{"t":"晓登多稼亭三首 其一","f":"七言绝句","c":["过雨梅无半个黄，冬青枝上雪花香。","不须更要风吹面，看著青林意自凉。"]},{"t":"晓雾","f":"七言绝句","c":["不知香务湿人须，日照须端细有珠。","政是春山眉样翠，被渠淡粉作糊涂。"]},{"t":"晓霜过宝应县三首 其三","f":"七言绝句","c":["落木枯林一夜苏，枝枝节节糁琼酥。","看来忘却腊前景，一色李花三月初。"]},{"t":"晓霜过宝应县三首 其二","f":"七言绝句","c":["看来不信是霜华，白日青天散晓霞。","只怪野田生玉树，更于腊月发琼花。"]},{"t":"晓霜过宝应县三首 其一","f":"七言绝句","c":["江南霜重莫嫌渠，草上还多树上无。","淮甸晓来霜似雪，琼田千里玉平铺。"]},{"t":"栟楮江滨芙蓉一株发红白二色二首 其二","f":"七言绝句","c":["司花手法我能知，说破当知未大奇。","乱剪素罗装一树，略将数朵蘸燕支。"]},{"t":"栟楮江滨芙蓉一株发红白二色二首 其一","f":"七言绝句","c":["芙蓉照水弄娇斜，白白红红各一家。","近日司花出新巧，一枝能著两般花。"]},{"t":"桂源铺","f":"七言绝句","c":["万山不许一溪奔，拦得溪声日夜喧。","到得前头山脚尽，堂堂溪水出前村。"]},{"t":"桐庐道中","f":"七言绝句","c":["肩舆坐睡茶力短，野堠无文山路长。","鸦鹊声欢人不会，枇杷一树十分黄。"]},{"t":"桑茶坑道中八首 其八","f":"七言绝句","c":["山根一径抱溪斜，片地才宽便数家。","漫插漫成堤上柳，半开半落路旁花。"]},{"t":"桑茶坑道中八首 其七","f":"七言绝句","c":["晴明风日雨乾时，草满花堤水满溪。","童子柳阴眠正著，一牛吃过柳阴西。"]},{"t":"桑茶坑道中八首 其六","f":"七言绝句","c":["蚕麰今岁十分强，催得农家日夜忙。","已缚桁竿等新麦，更将丫木撑欹桑。"]},{"t":"桑茶坑道中八首 其五","f":"七言绝句","c":["秧畴夹岸隔深溪，东水何缘到得西。","溪面祗销横一枧，水从空里过如飞。"]},{"t":"桑茶坑道中八首 其四","f":"七言绝句","c":["下山入屋上山锄，图得生涯总近居。","桑眼未开先著椹，麦胎才茁便生须。"]},{"t":"桑茶坑道中八首 其三","f":"七言绝句","c":["沙鸥数个点山腰，一足如钩一足翘。","乃是山农垦斜崦，倚锄无力政无聊。"]},{"t":"桑茶坑道中八首 其二","f":"七言绝句","c":["田塍莫笑细于椽，便是桑园与菜园。","岭脚置锥留结屋，尽驱柿栗上山颠。"]},{"t":"桑茶坑道中八首 其一","f":"七言绝句","c":["两边山束一溪风，尽日行程在井中。","犹喜天围能里许，井中那得个宽通。"]},{"t":"桑畴","f":"七言绝句","c":["夹岸濒河种稚桑，春风吹出万条长。","船行老眼浑多忘，唤作西湖插拒霜。"]},{"t":"桧径晓步二首 其一","f":"七言绝句","c":["老桧阴阴夹古城，露丛迎贯日华明。","晓凉无个人分却，一径深长独自行。"]},{"t":"桧径晓步二首 其二","f":"七言绝句","c":["雨歇林间凉自生，风穿径里晓逾清。","意行偶到无人处，惊起山禽我亦惊。"]},{"t":"海岸七里沙二首 其二","f":"七言绝句","c":["行人莫近岸边行，便恐波头打倒人。","若道岸高波不到，玉沙犹湿万痕新。"]},{"t":"海岸七里沙二首 其一","f":"七言绝句","c":["大风吹起翠瑶山，近岸还成白雪团。","一浪搀先千浪怒，打崖裂石与君看。"]},{"t":"烛下梅花二首 其二","f":"五言绝句","c":["窗外雪犹冻，瓶中梅不开。","烛花将暖气，催得早春回。"]},{"t":"烛下梅花二首 其一","f":"五言绝句","c":["烛下一枝梅，欲开犹未开。","浑如玉冠子，戴月上琼台。"]},{"t":"烟林晓望二首 其二","f":"七言绝句","c":["也没炊烟也没云，日光烘起楚山氛。","却将重碧施轻素，不见天工一笔痕。"]},{"t":"烟林晓望二首 其一","f":"七言绝句","c":["一叠青松一叠烟，横铺平野有无间。","真成万丈鹅溪绢，画出江西秋晓山。"]},{"t":"烧香","f":"七言绝句","c":["小阁疏棂春昼长，沉烟半穗弄轻黄。","老铃略不知人意，故故搴帘放出香。"]},{"t":"瓶中红白二莲五首 其五","f":"七言绝句","c":["折得荷花伴我幽，更搴荷叶伴花愁。","孤芳欲落偏多思，一片先垂半不收。"]},{"t":"瓶中红白二莲五首 其四","f":"七言绝句","c":["白莲半莟未开时，看作红莲更不疑。","到得欲开浑别了，玉肤洗退淡胭脂。"]},{"t":"瓶中红白二莲五首 其三","f":"七言绝句","c":["晚花特地敛新妆，莫道无情总不妨。","中有黄金莲子盏，被人瞥见即深藏。"]},{"t":"瓶中红白二莲五首 其二","f":"七言绝句","c":["拣得新开便折将，忽然到晚敛花房。","只愁花敛香还减，来早重开别是香。"]},{"t":"瓶中红白二莲五首 其一","f":"七言绝句","c":["红白莲花共玉瓶，红莲韵绝白莲清。","空斋不是无秋暑，暑被花销断不生。"]},{"t":"瓶中淮阳红牡丹落尽有叹三首 其三","f":"七言绝句","c":["又是明年看牡丹，未开芍药怯春寒。","落英满地不须扫，一片蔫红也足观。"]},{"t":"瓶中淮阳红牡丹落尽有叹三首 其二","f":"七言绝句","c":["眼中姚魏过匆匆，只有淮阳打底红。","杜宇一声花睡醒，却教老子怨东风。"]},{"t":"瓶中淮阳红牡丹落尽有叹三首 其一","f":"七言绝句","c":["只愁风雨妒花枝，剪入瓷瓶养却伊。","更下重帘深闭阁，忽然花落又关谁。"]},{"t":"病中止酒二首 其二","f":"七言绝句","c":["江草江花怨阿谁，山风山雨总成悲。","春愁万斛无安顿，旋旋分张乞小诗。"]},{"t":"病中止酒二首 其一","f":"七言绝句","c":["葛衣著了却生寒，风势颠时正上滩。","客里无聊已无奈，更教止酒过春残。"]},{"t":"病疟无聊","f":"七言绝句","c":["病身兀兀意昏昏，急挂东窗避夕曛。","坐看云生还有雨，忽然雨止并无云。"]},{"t":"积雨小霁","f":"七言绝句","c":["雨足山云半欲开，新秧犹待小暄催。","一双百舌花梢语，四顾无人忽下来。"]},{"t":"积雨小霁暮立捲书亭前二首 其二","f":"七言绝句","c":["淡紫斜阳嫩碧天，一春今夕始开颜。","看山偶忘归来却，月到西廊第二间。"]},{"t":"积雨小霁暮立捲书亭前二首 其一","f":"七言绝句","c":["报晴底用暮寒为，薄薄春衫横见欺。","似有如无风细甚，柳丝无赖恰先知。"]},{"t":"积雨新晴二月八日东园小步二首 其二","f":"七言绝句","c":["去岁春时政病身，对花不饮被花嗔。","如今急报千花道，还我前来未足春。"]},{"t":"积雨新晴二月八日东园小步二首 其一","f":"七言绝句","c":["醉来忽堕锦网窝，无奈桃围李绕何。","八角小亭无处坐，见花多处背花多。"]},{"t":"荷池","f":"七言绝句","c":["小池岁晚石泉寒，荷叶低垂绿柄乾。","一似渔人暮归后，败蓑破笠挂鱼竿。"]},{"t":"荷池小立","f":"七言绝句","c":["点铁成金未是灵，若教无铁也难成。","阿谁得似青荷叶，解化清泉作水精。"]},{"t":"荷池小立","f":"七言绝句","c":["池小泉多强欲留，留它不住恣它流。","荷盘不放荷尖出，穿破盘来却又休。"]},{"t":"荷桥","f":"五言绝句","c":["桥压荷梢过，花围桥外饶。","荆溪无胜处，胜处是荷桥。"]},{"t":"荷桥暮坐三首 其三","f":"五言绝句","c":["水到荷花蒂，风生菰叶梢。","鸥凫晚声散，天水夕光交。"]},{"t":"荷桥暮坐三首 其二","f":"七言绝句","c":["池似平铺绿锦横，荷花为纬藻为经。","无端织出诗人像，独立飞桥摘斗星。"]},{"t":"荷桥暮坐三首 其一","f":"七言绝句","c":["桥剪荷花两段开，荷花留我不容回。","不胜好处荷桥坐，政是凉时蚊子来。"]},{"t":"读子房传","f":"七言绝句","c":["笑赌乾坤看两龙，淮阴目动即雌雄。","兴王大计无寻处，却在先生一蹑中。"]},{"t":"读元白长庆二集诗","f":"七言绝句","c":["读遍元诗与白诗，一生少傅重微之。","再三不晓渠何意，半是交情半是私。"]},{"t":"读贞观政要","f":"七言绝句","c":["拔士新丰逆旅中，怀贤鸭绿水波东。","酒倾一斗鸢肩客，醋设三杯羊鼻公。"]},{"t":"读汉书二首 其二","f":"五言绝句","c":["乃祖宽仍豁，曾孙察作明。","不将囊底智，分减及元成。"]},{"t":"读汉书二首 其一","f":"五言绝句","c":["猿臂生何晚，彫虫死较迟。","晚生妨底事，迟死独堪悲。"]},{"t":"读严子陵传","f":"七言绝句","c":["客星何补汉中兴，空有清风冷似冰。","早遣阿瞒移汉鼎，人间何处有严陵。"]},{"t":"读张文潜诗二首 其二","f":"七言绝句","c":["山谷前头敢说诗，绝称漱井扫花词。","后来全集教渠见，别有天珍渠得知。"]},{"t":"读张文潜诗二首 其一","f":"七言绝句","c":["晚爱肥仙诗自然，何曾绣绘更雕镌。","春花秋月冬冰雪，不听陈玄只听天。"]},{"t":"读陈蕃传","f":"七言绝句","c":["仲举高谈亦壮哉，白头狼狈只堪哀。","枉教一室尘如积，天下何曾扫得来。"]},{"t":"读武惠妃传","f":"七言绝句","c":["桂折秋风露折兰，千花无朵可天颜。","寿王不忍金宫冷，独献君王一玉环。"]},{"t":"读退之李花诗","f":"七言绝句","c":["近红暮看失燕支，远白宵明雪色奇。","花不见桃惟见李，一生不晓退之诗。"]},{"t":"读梁武帝事","f":"七言绝句","c":["眼见台城作劫灰，一声荷荷可怜哉。","梵王岂是无甘露，不为君王致蜜来。"]},{"t":"读笠泽丛书三首 其三","f":"七言绝句","c":["拈著唐诗废晚餐，傍人笑我病诗癫。","世间尤物言西子，西子何曾直一钱。"]},{"t":"读笠泽丛书三首 其二","f":"七言绝句","c":["松江县尹送图经，中有唐诗喜不胜。","看到灯青仍火冷，双眸如割脚如冰。"]},{"t":"读笠泽丛书三首 其一","f":"七言绝句","c":["笠泽诗名千载香，一回一读断人肠。","晚唐异味同谁赏，近日诗人轻晚唐。"]},{"t":"轿中风翻书卷","f":"七言绝句","c":["挟册登车强出山，展来未读眼先昏。","无端又被春风妒，叶叶吹开更揭翻。"]},{"t":"轿中绝句","f":"五言绝句","c":["雪洗林花颊，金挼陇麦髯。","捲帘双眼远，隔树一峰尖。"]},{"t":"轿中望泛仙山","f":"七言绝句","c":["上却篮舆卷却帘，晓寒旋索熟衣添。","孤松已自三千丈，更在仙山第一尖。"]},{"t":"都下无忧馆小楼春尽旅怀二首 其二","f":"七言绝句","c":["不关老去愿春迟，只恨春归我未归。","最是杨花欺客子，向人一一作西飞。"]},{"t":"都下无忧馆小楼春尽旅怀二首 其一","f":"七言绝句","c":["病眼逢书不敢开，春泥谢客亦无来。","更无短计销长日，且绕栏干一百回。"]},{"t":"酌惠山泉瀹茶","f":"七言绝句","c":["锡作诸峰玉一涓，曲生堪酿茗堪煎。","诗人浪语元无据，却道人间第二泉。"]},{"t":"酒蛤蜊","f":"七言绝句","c":["饮者怜渠有典刑，见渠借箸眼偏青。","平生闭口不论事，晚岁搜肠求独醒。"]},{"t":"高邮野望二首 其二","f":"七言绝句","c":["江南十里九青山，江北无山只野田。","更遣野田无远树，郭熙尽巧若为传。"]},{"t":"高邮野望二首 其一","f":"七言绝句","c":["望中四野掌般平，远树成行一带横。","树外天容仍淡白，不愁树影不分明。"]},{"t":"堑荷池水","f":"七言绝句","c":["雨中来看堑池塘，自与畦丁细校量。","更放水痕高几许，浮荷犹剩若干长。"]},{"t":"宿万安铺","f":"七言绝句","c":["来朝还入鳄鱼乡，未到潮阳到揭阳。","休说春风归路远，只今去路不胜长。"]},{"t":"宿三里店溪声聒睡终夕","f":"七言绝句","c":["破驿荒村山路边，斜风细雨客灯前。","子规一夜啼到晓，更待溪声始不眠。"]},{"t":"宿小沙溪 其二","f":"七言绝句","c":["诸峰知我厌泥行，捲尽痴云放嫩晴。","不分竹梢含宿雨，时将残点滴寒声。"]},{"t":"宿小沙溪 其一","f":"七言绝句","c":["树捧山烟补缺云，风揉花雨作香尘。","绿杨尽道无情著，何苦垂条拂路人。"]},{"t":"宿小粉村","f":"七言绝句","c":["暮宿溪边小粉村，一峰如笔正当门。","看来山色元无粉，拂杀浓蓝浅黛痕。"]},{"t":"宿孔镇观雨中蛛丝五首 其五","f":"七言绝句","c":["网罗最密是蛛丝，却被秋蚊圣得知。","粘著便飞来不再，蛛丝也解有疏时。"]},{"t":"宿孔镇观雨中蛛丝五首 其四","f":"七言绝句","c":["走得团团织得窠，群飞来往不逃它。","网罗外面逃多少，枉了辛勤设网罗。"]},{"t":"宿孔镇观雨中蛛丝五首 其三","f":"七言绝句","c":["空中仰面却飞身，寂似毗耶不动尊。","忽有一蚊来触网，手忙脚乱便星奔。"]},{"t":"宿孔镇观雨中蛛丝五首 其二","f":"七言绝句","c":["雨罢蜘蛛却出檐，网丝小减再新添。","莫言辛苦无功业，便有飞虫密处粘。"]},{"t":"宿孔镇观雨中蛛丝五首 其一","f":"七言绝句","c":["雨打蛛丝不打蛛，雨来蛛入画檐隅。","网罗满腹输渠巧，也只蝇蚊命属渠。"]},{"t":"宿长安闸","f":"七言绝句","c":["野次何销追水程，昏时即住晓时行。","惊眠幸自无更点，犹有船头击柝声。"]},{"t":"宿长林","f":"五言绝句","c":["雾月撩人白，风灯恼客青。","倦多资美睡，酒薄免迟醒。"]},{"t":"宿张家店壁间有赵民则一绝句云舍策投床睡便浓觉来凉叶动西风惊秋念远无穷意客里知谁此夜同因次其韵","f":"七言绝句","c":["督邮不敌客愁浓，那更秋宵一笛风。","公子何曾知许事，旷怀也解与人同。"]},{"t":"宿灵鹫禅寺二首 其二","f":"七言绝句","c":["初疑夜雨忽朝晴，乃是山泉终夜鸣。","流到前溪无半语，在山做得许多声。"]},{"t":"宿灵鹫禅寺二首 其一","f":"七言绝句","c":["暑中带汗入山中，霜满风篁雪满松。","只是山寒清到骨，也无霜雪也无风。"]},{"t":"宿枫平","f":"七言绝句","c":["休说江西西路行，东来骨瘦却诗清。","恐缘桂玉疏云子，敢对溪山唤曲生。"]},{"t":"宿青山市四首 其四","f":"七言绝句","c":["市心酒店客来尝，且酹仙家十二郎。","鹦鹉鸬鹚何处觅，只将老瓦当瑶觞。"]},{"t":"宿青山市四首 其三","f":"七言绝句","c":["近看青山却朗然，更无半点雾和烟。","一峰是石高多少，到得峰头即到天。"]},{"t":"宿青山市四首 其二","f":"七言绝句","c":["云涂雾抹澹葱昽，万匹霜绡罩玉龙。","中有双峰不争长，诸峰情愿长双峰。"]},{"t":"宿青山市四首 其一","f":"七言绝句","c":["青山业主是玄晖，太白无钱典得伊。","总是诗仙休更讼，两蓑分钓一鱼矶。"]},{"t":"宿南岭驿二首 其一","f":"七言绝句","c":["蕨手犹拳已箸长，菊苗初甲可羹尝。","山村富贵无人享，一路春风野菜香。"]},{"t":"宿南岭驿二首 其二","f":"七言绝句","c":["茅花似雪复如茸，一望平原浅草中。","尽日向人挥玉麈，知将何事语春风。"]},{"t":"宿城外张氏庄早起入城三首 其三","f":"七言绝句","c":["眠云跂石十馀年，回首抛官一瞬间。","送旧迎新也辛苦，一番辛苦两年闲。"]},{"t":"宿城外张氏庄早起入城三首 其二","f":"七言绝句","c":["破店无鸡报五更，只将梦觉当鸡鸣。","匆匆上却篮舆了，隔壁人家政睡声。"]},{"t":"宿城外张氏庄早起入城三首 其一","f":"七言绝句","c":["灯火频挑只管残，雨声终夜恼空山。","幸蒙晓月多情白，又遣东风抵死寒。"]},{"t":"宿峨桥化城寺二首 其一","f":"七言绝句","c":["一溪秋水一横桥，近路人家却作遥。","柳绕溪桥荷绕屋，何须更著酒旗招。"]},{"t":"宿峨桥化城寺二首 其二","f":"七言绝句","c":["忽从平地上高城，乃是圩塘堤上行。","厚赛柳神销底物，长腰云子阔腰菱。"]},{"t":"宿新市徐公店二首 其一","f":"七言绝句","c":["篱落疏疏一径深，树头新绿未成阴。","儿童急走追黄蝶，飞入菜花无处寻。"]},{"t":"宿新市徐公店二首 其二","f":"七言绝句","c":["春光都在柳梢头，拣折长条插酒楼。","便作在家寒食看，村歌社舞更风流。"]},{"t":"宿滩头海智寺","f":"七言绝句","c":["平生行路敢求安，便要求安也大难。","古寺无门更无壁，若教半夜作春寒。"]},{"t":"宿潮州海阳馆独夜不寐二首 其二","f":"七言绝句","c":["腊前蚊子已能歌，挥去还来奈尔何。","一只搅人终夕睡，此声元自不须多。"]},{"t":"宿潮州海阳馆独夜不寐二首 其一","f":"七言绝句","c":["醉来还睡睡还醒，长是三更梦便惊。","细数更声有何益，不然作么到天明。"]},{"t":"寄题万元享舍人园亭七景 其六 倚苕","f":"五言绝句","c":["何处苕溪好，请君来倚楼。","西山也驩喜，奔走入帘钩。"]},{"t":"寄题万元享舍人园亭七景 其七 绵隐堂","f":"五言绝句","c":["试问隐绵上，何如隐东山。","出处两无阂，世间出世间。"]},{"t":"寄题万元享舍人园亭七景 其一 意山","f":"五言绝句","c":["不识弁山面，相逢笠泽诗。","祇应晚云散，玉立对门时。"]},{"t":"寄题分宜李克明上舍高居二咏 其一 不碍云山楼","f":"五言绝句","c":["想见谪仙裔，卷帘双眼寒。","云山千叠碧，飞舞入栏干。"]},{"t":"寄题太和宰赵嘉言勤民二图 题通济渡船图","f":"七言绝句","c":["岁岁桃花水到时，野航客子命如丝。","赵侯小试济川手，雪浪翻天不溅伊。"]},{"t":"题停罢坊场图","f":"七言绝句","c":["半山辱国卖丛祠，钟步诸坊卷酒旗。","村里山农语音好，孔方兄已赦鹅儿。"]},{"t":"寄题王国华环秀楼二首 其二","f":"七言绝句","c":["平地看山山绝低，上楼山色逐层奇。","不知山与楼争长，为复楼随山却移。"]},{"t":"寄题王国华环秀楼二首 其一","f":"七言绝句","c":["近山远岫不知重，暖翠晴岚只满空。","珍重主人将好手，尽驱秀色入楼中。"]},{"t":"寄题刘元明环翠阁二首 其二","f":"七言绝句","c":["一夜秋声恼井桐，梦回得句寄西风。","诗成却问题诗处，正在东山东复东。"]},{"t":"寄题刘元明环翠阁二首 其一","f":"七言绝句","c":["阁在青围翠绕中，何时我辈略支筇。","亦闻佳处无多子，只有千峰与万峰。"]},{"t":"寄题刘巨卿家六咏 其一 诣斋","f":"五言绝句","c":["紫鸾自超诣，一日可天地。","儿郎但读书，圣处底难至。"]},{"t":"寄题刘直卿冰壶二首 其二","f":"七言绝句","c":["壶里清冰冰里人，个边无地可留尘。","何时去弄池中月，照我星星白发新。"]},{"t":"寄题刘直卿冰壶二首 其一","f":"七言绝句","c":["外看积翠玉千峰，中有清池月半弓。","更拓长堤三十里，剩栽杨柳与芙蓉。"]},{"t":"寄题安福彭文昌春风楼二首 其二","f":"七言绝句","c":["不到安成二十年，故人相忆两依然。","彭家楼上春风里，梦倚危栏俯百川。"]},{"t":"寄题安福彭文昌春风楼二首 其一","f":"七言绝句","c":["沂水何人解问津，楼中蠹简拂蛛尘。","杏花坛下朱弦瑟，十指风生别是春。"]},{"t":"寄题朱元晦武夷精舍十二咏 其二 仁智堂","f":"五言绝句","c":["学子可怜生，远来参老子。","仁智若为谈，指似秋山水。"]},{"t":"寄题朱元晦武夷精舍十二咏 其四 止宿寮","f":"五言绝句","c":["一老说谈话，诸君未要眠。","开窗放山月，把酒奏溪泉。"]},{"t":"寄题朱元晦武夷精舍十二咏 其一 精舍","f":"五言绝句","c":["忆我南溪北，千岩万壑亭。","妒渠紫阳叟，诧杀一峰青。"]},{"t":"寄题朱元晦武夷精舍十二咏 其八 晚对亭","f":"五言绝句","c":["大隐翠屏孤，何许最正面。","日落未落时，亭上来相见。"]},{"t":"寄题朱元晦武夷精舍十二咏 其七 寒栖馆","f":"五言绝句","c":["鍊玉云粘杵，朝真露湿衣。","一声半夜鹤，月里羽人归。"]},{"t":"寄题朱景元直节轩二首 其二","f":"七言绝句","c":["月到梢头十倍明，风来叶底百分清。","尽言直节无人会，岁晚君看太瘦生。"]},{"t":"寄题朱景元直节轩二首 其一","f":"七言绝句","c":["见说幽居似渭川，一川脩竹雪霜寒。","如何剪得苍苍玉，乞与诚斋作钓竿。"]},{"t":"寄题张商弼葵堂堂下元不种葵花但取面势向阳二首 其二","f":"七言绝句","c":["主人未肯便山林，赏月吟风酒更琴。","每一登堂一揩眼，谁知半点向阳心。"]},{"t":"寄题张商弼葵堂堂下元不种葵花但取面势向阳二首 其一","f":"七言绝句","c":["行尽葵堂西复东，葵花元自不曾逢。","客来问讯名堂意，雪里芭蕉笑杀侬。"]},{"t":"寄题更好轩二首 其二","f":"七言绝句","c":["无梅有竹竹无朋，有竹无梅梅独醒。","雪里霜中两清绝，梅花白白竹青青。"]},{"t":"寄题更好轩二首 其一","f":"七言绝句","c":["经丘寻壑恰忙时，更有工夫到得诗。","政用此时索诗债，素兄青士若为痴。"]},{"t":"寄题荆南抚干胡仲方公廨信美楼 其二","f":"七言绝句","c":["古有仲宣今仲方，二楼分贮一秋江。","散愁幸有杯中月，莫下南窗下北窗。"]},{"t":"寄题荆南抚干胡仲方公廨信美楼 其一","f":"七言绝句","c":["大资孙子大参甥，磊磈胸中万卷横。","楼上已堆千古恨，晚潮更作断肠声。"]},{"t":"寄题袁机仲侍郎殿撰建溪北山四景 其三 玉虹桥","f":"五言绝句","c":["银河月外来，玉虹天上落。","骑虹弄银河，人间无个乐。"]},{"t":"寄题袁机仲侍郎殿撰建溪北山四景 其二 冰壶阁","f":"五言绝句","c":["竹国风世界，梅兄雪友朋。","地清无可比，且道玉壶冰。"]},{"t":"寄题袁机仲侍郎殿撰建溪北山四景 其一 妙净庵","f":"五言绝句","c":["韩子不肯佛，饶操苦出家。","何如妙净老，紫橐碧莲花。"]},{"t":"寄题萧民望扶疏堂二首 其二","f":"七言绝句","c":["株松个竹已奇奇，那更扶疏荫碧漪。","唤醒渊明千载梦，政缘泸水一篇诗。"]},{"t":"寄题萧民望扶疏堂二首 其一","f":"七言绝句","c":["不栽繁杏试晴红，不种垂杨拂暖茸。","堂下生涯无一物，月中脩竹雪中松。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其九 小山","f":"七言绝句","c":["涌岫跳峰尺许宽，坐看云雾起岩间。","九疑荒远巫阳崄，未必真山胜假山。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十二 方池","f":"七言绝句","c":["水精方局石桥仙，知是柯山几代孙。","月借繁星作棋子，夜寒睹得一金盆。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十六 月山","f":"七言绝句","c":["昔人只解笑移山，未信移山不作难。","一昨月山三里外，先生掇取近栏干。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十一 水乐","f":"七言绝句","c":["渠水来从林外泓，水知湖近各争鸣。","何人月下携枯木，写取穿云落涧声。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十 水帘","f":"七言绝句","c":["秧畴水落荇渠尖，玉石当中碧一奁。","石面平铺波面皱，千花织出水精帘。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其一 亦好园","f":"七言绝句","c":["金谷惟堪贮俗尘，辋川今复得诗人。","先生道是贫到骨，犹有山园斗大春。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其五 亦好亭","f":"七言绝句","c":["亦好园中亦好亭，两重好处两重贫。","客来莫道无供给，抹月批风当八珍。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十二 竹岩","f":"七言绝句","c":["石友拳然万仞姿，竹君啸处一川漪。","更无二客随巾屦，谁见先生觅句时。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十六 弄月亭","f":"七言绝句","c":["碧天如水水如天，月入湖中璧样圜。","却被先生来弄碎，一团成百百成千。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其四 芦苇林","f":"七言绝句","c":["春有儿孙夏有朋，月中寒影雨中声。","腊晴销尽一园雪，为底林间雪不晴。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十七 花屿","f":"七言绝句","c":["桃李无言照水光，玻瓈盆底洗新妆。","不须水上红云句，水上红云不解香。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十 花屏","f":"七言绝句","c":["锦障豪华笑騃童，松图冷淡恼山翁。","玉山颓处谁扶著，花作屏风倚暖红。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十八 柳堤","f":"七言绝句","c":["柳下湖光净一天，湖边垂柳起三眠。","小蛮自倚腰支袅，照镜梳头晓月前。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十五 海棠坞","f":"七言绝句","c":["细雨初怜湿翠裳，新晴特地试红妆。","无人会得东风意，春色都将付海棠。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十四 爱山堂","f":"七言绝句","c":["诗人性癖爱看山，晓坐堂中夕懒还。","只对月山无限好，月山外面八双鬟。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其七 清浅池","f":"七言绝句","c":["横枝直下是清池，花映清池水映枝。","知是君描和靖句，不知和靖寄君诗。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十四 菊径","f":"七言绝句","c":["身在京师梦在乡，黄花又是一番黄。","平生不解渊明语，菊却犹存径却荒。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十三 野桥","f":"七言绝句","c":["亦好亭兼弄月亭，磬湖不许两通行。","谁抛螮蝀湖光尾，便有先生拄杖声。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二十三 野塘","f":"七言绝句","c":["雁下菰蒲报夕寒，鹭将荇藻作朝餐。","野塘只许野人到，不要金张许史看。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十一 紫君林","f":"七言绝句","c":["青士从来一径幽，碧衫翠袖佩苍璆。","何年笔战明光殿，夺得诗仙紫绮裘。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其六 横枝","f":"七言绝句","c":["冰为仙骨水为肌，意淡香幽祗自知。","青女素娥非耐冷，一生耐冷是横枝。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其二 磬湖","f":"七言绝句","c":["洞庭张乐起天风，玉磬吹来堕圃中。","却被仙人镕作水，为君到底写秋空。"]},{"t":"寄题舒州宿松知县戴在伯重新紫霄亭二首 其二","f":"七言绝句","c":["万里长江一线横，好风时送晚潮声。","江州司马叫不醒，叫得庐山分一觥。"]},{"t":"寄题舒州宿松知县戴在伯重新紫霄亭二首 其一","f":"七言绝句","c":["一代名臣张右丞，玉山头作紫霄亭。","如今再得戴安道，拈出旧时山色青。"]},{"t":"得省榜见罗仲谋曾无逸策名夜归喜甚通夕不寐得二绝句 其二","f":"七言绝句","c":["两日阴晴较不常，嫩寒轻暖杂花香。","今晨天色休休问，卧看红光点屋梁。"]},{"t":"得省榜见罗仲谋曾无逸策名夜归喜甚通夕不寐得二绝句 其一","f":"七言绝句","c":["淡墨高垂两客名，夜归到晓睡难成。","却缘二喜添三喜，听得黄鹂第一声。"]},{"t":"探杏二首 其二","f":"七言绝句","c":["曾见乾条撼雪飞，一暄爆出万萸枝。","从今日日须来看，看到红红白白时。"]},{"t":"探杏二首 其一","f":"七言绝句","c":["红蓝细细糁晴包，紫玉森森走腻条。","枯梗折教无一寸，并驱春力奔花梢。"]},{"t":"探春","f":"七言绝句","c":["五日才能一日来，眼生方觉有春回。","向来日日频来探，只道园花不肯开。"]},{"t":"探梅","f":"七言绝句","c":["春傍梅梢瘦处回，小花未忍折将来。","却缘久住成幽事，剩看南枝一度开。"]},{"t":"探梅","f":"七言绝句","c":["山间幽步不胜奇，政是深寒浅暮时。","一树梅花开一朵，恼人偏在最高枝。"]},{"t":"探梅偶李判官馈熊掌","f":"七言绝句","c":["小摘梅花篸玉壶，旋糟熊掌削琼肤。","灯前雪里新醅熟，放却先生不醉无。"]},{"t":"晚云酿雨二首 其二","f":"七言绝句","c":["只消旧雨已惊心，莫遣新晴更作阴。","路转绿荷仍翠柳，眼随白鸟度青林。"]},{"t":"晚云酿雨二首 其一","f":"七言绝句","c":["昨来一雨断人行，恰则晴时云又生。","梅月如何休得雨，麦秋却是要它晴。"]},{"t":"晚日二首 其二","f":"七言绝句","c":["贪看波日弄船窗，奇观人间不作双。","忽被竹阴偷捲去，只馀一面拨醅釭。"]},{"t":"晚日二首 其一","f":"七言绝句","c":["日影穿波跳碎银，波光弄日走寒星。","一时飞入船窗里，万草千花变未停。"]},{"t":"晚风二首 其二","f":"七言绝句","c":["晚风不许鉴清漪，却许重帘到地垂。","平野无山遮落日，西窗红到月来时。"]},{"t":"晚风二首 其一","f":"七言绝句","c":["晚日暄温稍霁威，晚风豪横大相欺。","做寒做冷何须怒，来早一霜谁不知。"]},{"t":"晚风寒林二首 其二","f":"七言绝句","c":["树无一叶万梢枯，活底秋江水墨图。","幸自寒林俱淡笔，却将浓墨点栖乌。"]},{"t":"晚风寒林二首 其一","f":"七言绝句","c":["已是霜林叶烂红，那禁动地晚来风。","寒鸦可是矜渠黠，踏折枯梢不堕空。"]},{"t":"晚兴","f":"七言绝句","c":["双井茶芽醒骨甜，蓬莱香烬倦人添。","蜘蛛政苦空庭阔，风为将丝度别檐。"]},{"t":"晚过黄洲铺二绝 其一","f":"七言绝句","c":["数峰残日紫将销，一片新秧绿未交。","道是今年春水小，涨痕也到岸花梢。"]},{"t":"晚步","f":"七言绝句","c":["半疋轻烟束翠山，一梳寒月印青天。","生憎野烧无端甚，直上高林杳霭边。"]},{"t":"晚步","f":"七言绝句","c":["晚暑无凉可得寻，小风一点慰人心。","斜阳碎入高榕叶，翻作青瑶覆作金。"]},{"t":"晚步","f":"七言绝句","c":["清水芙蓉未肯开，暑天花草底差排。","鹿葱金凤何为者，也得园亭护两阶。"]},{"t":"晚步追凉二首 其二","f":"七言绝句","c":["风不须多只是凉，穿花度柳到人傍。","细吹病耳飕飕响，徐弄轻衫拂拂长。"]},{"t":"晚步追凉二首 其一","f":"七言绝句","c":["老眼偏明远岫孤，夕阳故遣树阴疏。","蝉鸣叶底无寻处，随意闲行偶见渠。"]},{"t":"晚春即事二绝 其二","f":"七言绝句","c":["树头吹得叶冥冥，三日颠风不小停。","只是向来枯树子，知他那得许多青。"]},{"t":"晚归再度西桥四首 其四","f":"七言绝句","c":["朝过溪头听水鸣，似哀如怨百般声。","归来依旧鸣未了，知向何人诉不平。"]},{"t":"晚归再度西桥四首 其三","f":"七言绝句","c":["尽日山行意未销，归来再与坐溪桥。","山童抛石落溪水，唤作鱼儿波面跳。"]},{"t":"晚归再度西桥四首 其二","f":"七言绝句","c":["水落沙滩倍有情，漩来漩去不成行。","暗丛飞下小瀑布，拦住溪声独作声。"]},{"t":"晚归再度西桥四首 其一","f":"七言绝句","c":["归近溪桥东复东，蓼花迎路舞西风。","草深一鸟忽飞起，侬不觉它它觉侬。"]},{"t":"晚凉散策二首 其二","f":"七言绝句","c":["半点轻风泛柳丝，忽吹荷叶一时欹。","芙蕖好处无人会，最是将开半落时。"]},{"t":"晚凉散策二首 其一","f":"七言绝句","c":["饭馀浴罢趁凉行，偶憩池头最小亭。","醉倚胡床便成睡，梦闻荷气忽然醒。"]},{"t":"晚宿小罗田四首 其四","f":"五言绝句","c":["白酒聊三盏，青灯欲二更。","倦来乘急睡，过了睡难成。"]},{"t":"晚宿小罗田四首 其三","f":"五言绝句","c":["萧洒低低屋，虚明小小窗。","客间那得许，窗外更寒江。"]},{"t":"晚宿小罗田四首 其一","f":"七言绝句","c":["青林化作万黄金，落日光寒色却深。","仰看松梢数松子，不妨更与数松针。"]},{"t":"晚望二首 其二","f":"七言绝句","c":["万松不掩一枫丹，烟怕山狂约住山。","却被沙鸥恼人损，作行飞去略无还。"]},{"t":"晚望二首 其一","f":"七言绝句","c":["月是小春春未生，节名大雪雪何曾。","夕阳不管西山暗，只照东山八九棱。"]},{"t":"晚眺","f":"五言绝句","c":["晚暖好登临，吾衰也不禁。","雪残千嶂玉，日落万梢金。"]},{"t":"晚寒题水仙花并湖山三首 其三","f":"七言绝句","c":["鍊句炉槌岂可无，句成未必尽缘渠。","老夫不是寻诗句，诗句自来寻老夫。"]},{"t":"晚寒题水仙花并湖山三首 其二","f":"七言绝句","c":["水面无风也自寒，船门已幕更深关。","莫将若下三杯酒，博与湖边几点山。"]},{"t":"晚寒题水仙花并湖山三首 其一","f":"七言绝句","c":["水仙怯暖爱清寒，两日微暄懒欲眠。","料峭晚风人不会，留花且住伴诗仙。"]},{"t":"晚晴二首 其二","f":"七言绝句","c":["先生老态似枯禅，解后东风也欲颠。","才雨便晴寒便暖，四时佳处是春天。"]},{"t":"晚晴二首 其一","f":"七言绝句","c":["风收点滴晓檐声，云放朦胧晚日明。","杨柳染丝才喜雨，梅花泣玉却祈晴。"]},{"t":"晚晴独酌二首 其二","f":"七言绝句","c":["霜熟寒轻际晚时，帘间过影一鸦归。","夕阳端与谁为地，只照游尘絮样飞。"]},{"t":"晚晴独酌二首 其一","f":"七言绝句","c":["冷落杯盘下箸稀，今年淮白较来迟。","异乡黄雀真无价，稍暖琼酥不得时。"]},{"t":"晚登连天观望越台山","f":"七言绝句","c":["暮山如淡复如浓，烟拂山前一两重。","山背更将霞万疋，生红锦障裹青峰。"]},{"t":"晚登净远亭二首 其二","f":"七言绝句","c":["簿书才了晚衙催，且上高亭眼暂开。","野鸭成群忽惊起，定知城背有船来。"]},{"t":"晚登净远亭二首 其一","f":"七言绝句","c":["重阳才过便新寒，去岁如今暑尚残。","云外雁来元不觉，一声唤我举头看。"]},{"t":"晚衙野望","f":"七言绝句","c":["上却城来忘却归，迎它来雁送它飞。","可怜乌臼能缁素，却被清霜染作绯。"]},{"t":"晚憩富阳二首 其二","f":"七言绝句","c":["春馀客里政无聊，忽报潮头雪样高。","急唤清空竹陵酒，旋尝梅子与樱桃。"]},{"t":"晚憩富阳二首 其一","f":"七言绝句","c":["苕溪到得富春滩，度绿穿青半日间。","未出浙西心已喜，眼中初见浙东山。"]},{"t":"晨炊玉田闻莺观鹭二首 其二","f":"七言绝句","c":["清溪欲下影先翻，只鹭还将双鹭看。","绿玉胫长聊试浅，素琼裳冷不禁寒。"]},{"t":"晨炊玉田闻莺观鹭二首 其一","f":"七言绝句","c":["晓寒顾影惜金衣，著意听时不肯啼。","飞入柳阴多去处，数声只许落花知。"]},{"t":"晨炊江山县驿","f":"七言绝句","c":["闻道常山水壮哉，问途何惜小纡回。","平生不到江山县，临老须教作一来。"]},{"t":"晨炊玩鞭亭二首 其二","f":"七言绝句","c":["问著无声是阿兄，坐看家贼只吞声。","戮尸大放经纶手，长柄判将锡茂弘。"]},{"t":"晨炊玩鞭亭二首 其一","f":"七言绝句","c":["老贼平欺晋鼎轻，一轮五色梦中惊。","宝鞭脱急非无策，何似休将日绕营。"]},{"t":"晨炊黄冈望海","f":"七言绝句","c":["望中雪岭界天横，雪外青瑶甃地平。","白底是沙青是海，捲帘看了却心惊。"]},{"t":"晨炊黄宙铺饭后山行","f":"七言绝句","c":["山行行得软如绵，急上篮舆睡霎间。","梦里只闻人喝道，不知过尽数重山。"]},{"t":"晨炊熊家庄","f":"七言绝句","c":["朝饥一眼望炊烟，绕尽长溪过尽山。","承露丝囊世无样，蜘蛛偷得挂篱间。"]},{"t":"望见灵山","f":"七言绝句","c":["旱后催科恼杀侬，且随尺一解而东。","灵山忽近西山远，回首新吴一梦中。"]},{"t":"望清远峡","f":"七言绝句","c":["刺船又入峡山间，江水初平失恶滩。","道是峡山天下险，老夫今作坦涂看。"]},{"t":"望谢家青山太白墓二首 其二","f":"七言绝句","c":["玄晖旧宅略无存，太白来游爱是间。","占作醉眠床一只，谢家山是李家山。"]},{"t":"望谢家青山太白墓二首 其一","f":"七言绝句","c":["阿朓青山自一村，州民岁岁与招魂。","六朝陵墓今安在，只有诗仙月下坟。"]},{"t":"望横山塔","f":"七言绝句","c":["水面生风分外严，竹根剩雪更新添。","六年不见横山塔，茅屋东边忽半尖。"]},{"t":"梅花","f":"五言绝句","c":["花早春何力，香寒晓尽吹。","月摇横水影，雪带入瓶枝。"]},{"t":"梅花二首 其二","f":"七言绝句","c":["带雪虽奇祗粉妆，酣晴别是好风光。","却缘白日青天里，照得花明暖得香。"]},{"t":"梅花二首 其一","f":"七言绝句","c":["东风微破野梅心，著骨清香已不禁。","绿刺一尖双莟子，错书小字带悬针。"]},{"t":"梅花落尽有感","f":"七言绝句","c":["五树梅花一树迟，花迟花早总离披。","春风只解吹梅落，不为愁人染鬓丝。"]},{"t":"梅残","f":"五言绝句","c":["雪已都消去，梅能小住无。","雀争飞落片，蜂猎未蔫须。"]},{"t":"梅菊同插砚滴","f":"七言绝句","c":["两枝残菊两枝梅，同入银罂酿玉醅。","待得陶泓真个渴，二花酒熟与三杯。"]},{"t":"梅熟小雨","f":"七言绝句","c":["风从独树忽然来，雨去前山远却回。","留许枝间慰愁眼，儿童抵死打黄梅。"]},{"t":"梅露堂燕客夜归","f":"七言绝句","c":["药玉船中酒似空，水沉烟上雪都融。","梅堂客散人初静，椽烛烧残一尺红。"]},{"t":"梦作碾试馆中所送建茶绝句","f":"七言绝句","c":["天上蓬山新水芽，群仙远寄野人家。","坐看宝带黄金銙，吹作春风白雪花。"]},{"t":"梳头有感二首 其二","f":"七言绝句","c":["同郡同年总八人，七人零落一人存。","如何独立薰风里，犹怨霜花点鬓根。"]},{"t":"梳头有感二首 其一","f":"七言绝句","c":["身在荷香水影中，晓凉不与夜来同。","且抛书册梳蓬鬓，移转胡床受小风。"]},{"t":"梳头看可正平诗有寄养直时未祝发等篇戏题七字二首 其二","f":"七言绝句","c":["老子平生汤饼肠，客间汤饼亦何尝。","怪来今晚加餐饭，一味卢山笋蕨香。"]},{"t":"梳头看可正平诗有寄养直时未祝发等篇戏题七字二首 其一","f":"七言绝句","c":["却因理发得披文，看尽庐山笔底春。","寄语可师休祝发，癞边犹有去年痕。"]},{"t":"淮河中流肃使客","f":"七言绝句","c":["淮水中流各一波，南船小住北船过。","生憎两岸旌旗脚，引得霜风分外多。"]},{"t":"添盆中石菖蒲水仙花水","f":"七言绝句","c":["旧诗一读一番新，读罢昏然一欠伸。","无数盆花争诉渴，老夫却要作闲人。"]},{"t":"清明日雨雪来早晴霁二首 其二","f":"七言绝句","c":["清明一雪怪生寒，逗晓新晴雪未残。","要见海棠还傅粉，捲帘不彻急来看。"]},{"t":"清明日雨雪来早晴霁二首 其一","f":"七言绝句","c":["清明一雨坏花时，梅杏樱桃总脱枝。","挽住落英供细舞，东风犹自妒游丝。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其六","f":"七言绝句","c":["石门未到未为迟，小泊灵星也自奇。","此去五羊三十里，明朝还有到城时。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其五","f":"七言绝句","c":["波涛端不为君休，风雨何曾管客愁。","自古诗人磨不倒，一樽大笑谢阳侯。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其四","f":"七言绝句","c":["一生行路竟如何，乐事还稀苦事多。","知是风波欺客子，不知客子犯风波。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其三","f":"七言绝句","c":["石门欲到更无疑，隔海风涛未可期。","到得石门非不好，只愁未到石门时。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其二","f":"七言绝句","c":["峡山前夕石间行，泊得船时破胆惊。","惊到今宵已无胆，听风听浪到天明。"]},{"t":"清明日欲宿石门未到而风雨大作泊灵星小海六首 其一","f":"七言绝句","c":["风雨来从海外天，灵星海里泊楼船。","坐吟苦句斟愁酒，也是清明过一年。"]},{"t":"清明雨寒八首 其八","f":"七言绝句","c":["风欹众柳自成妍，雨泣残花不忍看。","急唤曲生尝杏子，及渠小苦未生酸。"]},{"t":"清明雨寒八首 其七","f":"七言绝句","c":["闭户何缘得句来，开窗更倩雨相催。","只言春色都归去，小树桃花政晚开。"]},{"t":"清明雨寒八首 其六","f":"七言绝句","c":["莫嫌细雨苦飘萧，政要寒声伴寂寥。","杏叶犹疏不成响，且将纸瓦当芭蕉。"]},{"t":"清明雨寒八首 其五","f":"七言绝句","c":["苔阶滴雨翠方浓，须把寒珠溅鹿葱。","梅子犹粘雪前蕊，海棠生恨夜来风。"]},{"t":"清明雨寒八首 其四","f":"七言绝句","c":["桃李一空春已归，不须更待絮飞时。","闭门独琢春寒句，只有轻风细雨知。"]},{"t":"清明雨寒八首 其三","f":"七言绝句","c":["今年寒食与清明，各自阴晴作么生。","细雨千丝不成点，如何也解滴檐声。"]},{"t":"清明雨寒八首 其二","f":"七言绝句","c":["脱却单衣著裌衣，禁烟无有不寒时。","一年好处君知么，寒食千门插柳枝。"]},{"t":"清明雨寒八首 其一","f":"七言绝句","c":["整冠忽见镜中霜，挽树浑无蒂上香。","已贮春愁过万斛，更令细细著升量。"]},{"t":"清晓出郭迓客七里庄二首 其二","f":"七言绝句","c":["偏得春怜是柳条，腰支别作一般娇。","微风不动渠犹舞，刚道东风转舞腰。"]},{"t":"清晓出郭迓客七里庄二首 其一","f":"七言绝句","c":["却为迎宾得探春，白门官柳早尖新。","如何霜瓦才逢日，半作青瑶半作银。"]},{"t":"清晓洪泽放闸四绝句 其三","f":"七言绝句","c":["遮藏水面被残冰，流尽残冰水正明。","幸自奔流总驩喜，落洪须做不平声。"]},{"t":"清晓洪泽放闸四绝句 其四","f":"七言绝句","c":["沿河过闸梦中闻，奇观何曾似此晨。","雪溅雷奔乍明眼，天跳地趠也惊人。"]},{"t":"清晓洪泽放闸四绝句 其二","f":"七言绝句","c":["满闸浮河是断冰，等人放闸要前行。","劣能开得两三板，争作摧琼裂玉声。"]},{"t":"清晓洪泽放闸四绝句 其一","f":"七言绝句","c":["起来霜重满淮船，更觉今朝分外寒。","放闸老兵殊耐冷，一丝不挂下冰滩。"]},{"t":"清晓湖上三首 其三","f":"七言绝句","c":["六月西湖锦绣乡，千层翠盖万红妆。","都将月露清凉气，并作侵晨一喷香。"]},{"t":"清晓湖上三首 其二","f":"七言绝句","c":["菰月蘋风逗葛裳，出城趁得上番凉。","荷花笑沐燕支露，将谓无人见晓妆。"]},{"t":"清晓湖上三首 其一","f":"七言绝句","c":["山腰轻束一绡云，湖面初颦半蹙痕。","未说湖山佳处在，清晨小出涌金门。"]},{"t":"渔舟","f":"七言绝句","c":["绝小渔舟叶似轻，荻篷密盖不闻声。","无人无钓无蓑笠，风自吹船船自行。"]},{"t":"理发","f":"七言绝句","c":["发脱心知不再生，新年底急顿星星。","城边老柳也欺我，春里满头依旧青。"]},{"t":"祷雨报恩因到翟园四首 其四","f":"七言绝句","c":["未必钱园似翟园，翟园窠木最宜看。","茂松亭下偏明眼，矮桧平铺翡翠盘。"]},{"t":"祷雨报恩因到翟园四首 其三","f":"七言绝句","c":["绕亭怪石小山幽，夹径低枝压客头。","幸自一来惟不早，梅花满地诉春愁。"]},{"t":"祷雨报恩因到翟园四首 其二","f":"七言绝句","c":["草路无泥未有尘，城南城北总游人。","不缘香火来山墅，孤负今年半段春。"]},{"t":"祷雨报恩因到翟园四首 其一","f":"七言绝句","c":["雾气初迎日脚开，春光偏傍柳边回。","寒暄消息何人会，十指今朝出袖来。"]},{"t":"移瑞香花斛","f":"七言绝句","c":["夜掇香窠沐露华，昼移翠斛馥窗纱。","将身挨起帘帷著，生怕帘帷挨著花。"]},{"t":"晚归遇雨","f":"七言绝句","c":["略略烟痕草许低，初初雨影伞先知。","溪回谷转愁无路，忽有梅花一两枝。"]},{"t":"晚望","f":"七言绝句","c":["病身似怯暮来风，老眼还惊霁后虹。","落日偏明松表里，好山分占水西东。"]},{"t":"船过苏州二首 其二","f":"七言绝句","c":["暮风似箭复如刀，落照那能暖客袍。","天远地平城更阔，千寻玉塔尺来高。"]},{"t":"船过苏州二首 其一","f":"七言绝句","c":["垂近姑苏特转湾，盘门只隔柳行间。","望来望去何时到，且倚船窗看远山。"]},{"t":"菊夏摘则秋茂朝凉试手","f":"七言绝句","c":["种菊君须莫惜它，摘教秃秃不留些。","此花贱相君知么，从此千千万万花。"]},{"t":"野店二绝句 其一","f":"七言绝句","c":["不劳官吏出将迎，山店如何远有声。","人报官来争出看，牛逢轿过忽然惊。"]},{"t":"野店二绝句 其二","f":"七言绝句","c":["山店茅柴强一杯，梨酸藕苦眼慵开。","深红元子轻红鲊，难得江西乡味来。"]},{"t":"野店多卖花木瓜","f":"七言绝句","c":["天下宣城花木瓜，日华露液绣成花。","何须堠子强呈界，自有琼琚先报衙。"]},{"t":"野荼?二首 其二","f":"七言绝句","c":["不识荼糜恨杀人，野花香里度芳晨。","寄笺为报东皇道，不理今年一个春。"]},{"t":"野荼?二首 其一","f":"七言绝句","c":["去岁诸司赏物华，荼糜一会属侬家。","今年不识荼糜面，却买茅柴对野花。"]},{"t":"野望二首 其二","f":"七言绝句","c":["野童撷菜疏移步，客子追程有底忙。","茅屋破时偏入画，布衫洗了晒枯桑。"]},{"t":"野望二首 其一","f":"七言绝句","c":["也知口业欠消磨，造物嗔人奈口何。","莫管诗人例寒饿，且容老子小婆娑。"]},{"t":"野蔷薇","f":"七言绝句","c":["红残绿暗已多时，路上山花也则稀。","藞苴馀春还子细，燕脂浓抹野蔷薇。"]},{"t":"铜雀砚","f":"七言绝句","c":["摸索陶泓不忍研，阿瞒故物尚依然。","浪传铜雀檐间瓦，恐是金凫海底砖。"]},{"t":"银鱼乾","f":"七言绝句","c":["初疑柘茧雪争鲜，又恐杨花糁作毡。","却是剪银成此叶，如何入口软于绵。"]},{"t":"雪中讲堂赐酒二首 其二","f":"七言绝句","c":["袖手垂鞭出帝闉，万花栏马舞新春。","是时也有青油伞，天上归来雪满身。"]},{"t":"雪中讲堂赐酒二首 其一","f":"七言绝句","c":["玉果金柈码碯觞，春坊传令赐云浆。","雪中上马浑如梦，一片飞来醉面凉。"]},{"t":"雪中看梅","f":"七言绝句","c":["犯雪寻梅雪满衣，池边梅映竹边池。","要寻疏影横斜底，拣尽南枝与北枝。"]},{"t":"雪中登净远亭四首 其四","f":"七言绝句","c":["忍却清寒得得来，不堪骑吏苦相催。","雁穿银色界中去，人到水晶宫里回。"]},{"t":"雪中登净远亭四首 其三","f":"七言绝句","c":["壕水深清一镜如，天倾瑶屑打成酥。","琉璃缸面熬琼粥，酿出珠宫白玉腴。"]},{"t":"雪中登净远亭四首 其二","f":"七言绝句","c":["数片初飞点砌苔，须臾不觉玉千堆。","去年无雪非无雪，留作今年一并来。"]},{"t":"雪中登净远亭四首 其一","f":"七言绝句","c":["犯雪来登净远亭，飞花著水旋成冰。","琼田万顷珠千树，真在瑶台十二层。"]},{"t":"雪后晓过八盘岭诣东宫谢受左司告二首 其二","f":"七言绝句","c":["玉京世界大千中，银屋楼台一万重。","好上宝莲山上望，南高峰照北高峰。"]},{"t":"雪后晓过八盘岭诣东宫谢受左司告二首 其一","f":"七言绝句","c":["扶桑梢上上朝暾，起早行迟却载奔。","玉作宫城三万雉，呼僮换马入金门。"]},{"t":"雪后晚晴四山皆青惟东山全白赋最爱东山晴后雪二绝句 其二","f":"七言绝句","c":["群山雪不到新晴，多作泥融少作冰。","最爱东山晴后雪，却愁宜看不宜登。"]},{"t":"雪后晚晴四山皆青惟东山全白赋最爱东山晴后雪二绝句 其一","f":"七言绝句","c":["只知逐胜忽忘寒，小立春风夕照间。","最爱东山晴后雪，软红光里涌银山。"]},{"t":"雪霁出城","f":"七言绝句","c":["梅于雪后较多花，草亦晴初忽几芽。","河冻落痕馀一寸，残冰阁在柳根沙。"]},{"t":"雪晴二首 其二","f":"七言绝句","c":["晴光雪色忽相逢，雨滴空阶日影中。","珍重北檐殊韵胜，苛留残玉不教融。"]},{"t":"雪晴二首 其一","f":"七言绝句","c":["仙人剪水作花飞，忽化琼瑶已大奇。","复把琼瑶化成水，滴来平地总琉璃。"]},{"t":"雪晴窗开展唐诗得一片桃花怅然赋之","f":"七言绝句","c":["偶开诗卷雪窗晨，中有桃花片尚新。","却忆携诗花底看，回头又是一年春。"]},{"t":"领客南园二首 其二","f":"七言绝句","c":["人间俗杀是公筵，最苦沉烟杂烛烟。","何似大家行几步，逢花即饮醉还眠。"]},{"t":"领客南园二首 其一","f":"七言绝句","c":["南园多日不曾来，领客闲行始此回。","独树小梅开一朵，被它栏住劝三杯。"]},{"t":"黄菊","f":"七言绝句","c":["莺样衣裳钱样裁，冷霜凉露溅秋埃。","比他红紫开差晚，时节来时毕竟开。"]},{"t":"黄雀食新二首 其二","f":"七言绝句","c":["侯门信口总称珍，只见陈人不见新。","三日荔枝香味变，况开酱瓿拂蛛尘。"]},{"t":"黄雀食新二首 其一","f":"七言绝句","c":["鹅黄染线织秋衣，杨柳吹绵细细披。","诗债被渠浑索尽，醉乡邀我不容归。"]},{"t":"富阳登舟待潮回文","f":"七言绝句","c":["山接江清江接天，老人渔钓下前滩。","寒潮晚到风无定，船泊小湾春日残。"]},{"t":"寒鸡","f":"七言绝句","c":["寒鸡睡著不知晨，多谢钟声唤起人。","明晓莫教钟睡著，被它鸡笑不须嗔。"]},{"t":"寒夜不寐","f":"五言绝句","c":["雪入迎春鬓，茶醒学古胸。","梦回霜满屋，吟到月斜钟。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十五","f":"七言绝句","c":["万顷湖光一片春，何须割破损天真。","却将葑草分疆界，葑外垂杨属别人。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十四","f":"七言绝句","c":["若道寻春被雨催，如何随处两三杯。","晚晴晓雨如翻手，有底亏侬不好来。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十三","f":"七言绝句","c":["户户游春不放春，只愁春去不愁贫。","今朝道是游人少，处处园亭处处人。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其八","f":"七言绝句","c":["清远溪中小闸头，遮栏溪水不教流。","山僧为我放一板，溅雪奔雷怒未休。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其四","f":"七言绝句","c":["破雨游山也莫嫌，却缘山色雨中添。","人家屋里生松树，穿出茅檐却覆檐。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其一","f":"七言绝句","c":["游山不合作前期，便被山灵圣得知。","只等五更倾一雨，三更犹是月明时。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其五","f":"七言绝句","c":["小溪曲曲乱山中，嫩水溅溅一线通。","两岸桃花总无力，斜红相倚卧春风。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其二","f":"七言绝句","c":["笋舆冲雨复冲泥，一径深深只觉迟。","孤塔忽从云外出，寺门渐近报侬知。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十二","f":"七言绝句","c":["雨里匆匆怨出郊，晴时不出却谁教。","西湖北畔名园里，无数桃花只见梢。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十一","f":"七言绝句","c":["禅房寂寂水潺潺，涧草岩花点缀间。","忽有仙禽发奇响，频伽来自补陀山。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十六","f":"七言绝句","c":["轿顶花枝尽闹装，游人未暮已心忙。","无端更被千株柳，展取苏堤分外长。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其六","f":"七言绝句","c":["老桧如幢翠接连，山茶作塔绿萦缠。","山僧相识浑相忘，不到山中十五年。"]},{"t":"寒食前一日行部过牛首山七首 其七","f":"七言绝句","c":["一春今岁两中和，信道韶华定较多。","二月半头花已尽，脱空日月退还他。"]},{"t":"寒食前一日行部过牛首山七首 其六","f":"七言绝句","c":["捣蓝作雨两宵倾，生怕难乾急放晴。","一路东皇新晒染，桑黄麦绿小枫青。"]},{"t":"寒食前一日行部过牛首山七首 其五","f":"七言绝句","c":["单车一节又行春，敢为观风惜病身。","只是担头无櫑子，枉教唤作踏青人。"]},{"t":"寒食前一日行部过牛首山七首 其四","f":"七言绝句","c":["出了长干过了桥，纸钱风里树萧骚。","若无六代英雄骨，牛首诸山肯尔高。"]},{"t":"寒食前一日行部过牛首山七首 其三","f":"七言绝句","c":["绵山恨骨已寒灰，尽禁厨烟肯更回。","老病不禁馊食冷，杏花饧粥汤将来。"]},{"t":"寒食前一日行部过牛首山七首 其二","f":"七言绝句","c":["头上高垂碧玉盆，谁将漂絮尚残痕。","青天幸自秋江样，须惹三丝两缕云。"]},{"t":"寒食前一日行部过牛首山七首 其一","f":"七言绝句","c":["岭花袍紫不知名，涧草茸青取次生。","便是常州草虫本，只无蚱蜢与蜻蜓。"]},{"t":"寒食相将诸子游翟园得十诗 其三","f":"七言绝句","c":["柳条老去尚青鲜，下有清渠绕野田。","波面落花相趁走，避风争泊岸傍边。"]},{"t":"寒食相将诸子游翟园得十诗 其五","f":"七言绝句","c":["小小茅亭短短窗，海棠围里柳中央。","乍晴萱草浑无力，落尽梅花尚有香。"]},{"t":"寒食相将诸子游翟园得十诗 其七","f":"七言绝句","c":["三月风光一岁无，杏花欲过李花初。","柳丝自为春风舞，竹尾如何也学渠。"]},{"t":"寒食相将诸子游翟园得十诗 其二","f":"七言绝句","c":["鹿葱旧种菊新栽，幽径深行忘却回。","忽有野香寻不得，兰于石背一花开。"]},{"t":"寒食相将诸子游翟园得十诗 其十","f":"七言绝句","c":["荆溪老守底风流，哦就千诗一笑休。","天欲做春无去处，只堆浓绿柳梢头。"]},{"t":"寒食相将诸子游翟园得十诗 其六","f":"七言绝句","c":["儿曹健走尽从渠，老脚微酸半要扶。","未委前头花好否，且令蜂蝶作前驱。"]},{"t":"寒食相将诸子游翟园得十诗 其八","f":"七言绝句","c":["驱使花枝苦未休，平章诗句政冥搜。","无端一窦西窗日，不遣吾人略小留。"]},{"t":"寒食相将诸子游翟园得十诗 其四","f":"七言绝句","c":["尽忙也到翟园休，只见春光不见愁。","屈折海棠团更密，日光下照绣灯毬。"]},{"t":"寒食相将诸子游翟园得十诗 其九","f":"七言绝句","c":["花木从渠取次栽，青山那肯入城隈。","翟公不有驱山手，城里松林底处来。"]},{"t":"寒雀","f":"七言绝句","c":["百千寒雀下空庭，小集梅梢话晚晴。","特地作团喧杀我，忽然惊散寂无声。"]},{"t":"衔命郊劳使客船过崇德县三首 其三","f":"七言绝句","c":["岸树低欹一雪馀，枝头半叶已全无。","油窗过尽千梢影，浓处还浓枯处枯。"]},{"t":"衔命郊劳使客船过崇德县三首 其二","f":"七言绝句","c":["水面光浮赤玉盘，也应知我牵夫寒。","满河圭璧无人要，吹入诗翁冻笔端。"]},{"t":"衔命郊劳使客船过崇德县三首 其一","f":"七言绝句","c":["北关落日送船行，欲到嘉兴天已明。","睡起一河冰片满，槌琼摐玉梦中声。"]},{"t":"揭阳道中二首 其二","f":"七言绝句","c":["地平如掌树成行，野有邮亭浦有梁。","旧日潮州底处所，如今风物冠南方。"]},{"t":"揭阳道中二首 其一","f":"词","c":["厌穿山径石嵚?，喜见川原路坦夷。","更著两行团树子，引人行远不教知。"]},{"t":"晴后再雪四首 其四","f":"七言绝句","c":["八盘岭上雪偏清，万斛琼尘作一倾。","空里仰看都不见，碧山映得却分明。"]},{"t":"晴后再雪四首 其三","f":"七言绝句","c":["天上琼楼万玉妃，月宫学舞试云衣。","霓裳未彻天风起，脑子花钿星散飞。"]},{"t":"晴后再雪四首 其二","f":"七言绝句","c":["滕家仙子六琼娘，煮露为酥不剩浆。","滴作玉虫千万只，一时飞满白云乡。"]},{"t":"晴后再雪四首 其一","f":"七言绝句","c":["幸自晴光雪半开，谁将泥脚涴琼瑰。","水仙上诉姮娥泣，再遣天花散一回。"]},{"t":"晴望","f":"七言绝句","c":["愁于望处一时销，山亦霜前分外高。","枸杞一丛浑落尽，只残红乳似樱桃。"]},{"t":"暑中早起东斋独坐","f":"七言绝句","c":["松竹阴中逗晓光，无风有露自生凉。","黄筠椅子十二只，倚遍琉璃背满霜。"]},{"t":"暑雨后散策","f":"七言绝句","c":["溪南稻紫似溪北，雨后山青非雨前。","芒屦泥深凉不浅，今年六月个般天。"]},{"t":"游云际寺诸僧皆出因过田家","f":"七言绝句","c":["游遍诸峰欲晚霞，倦投野寺觅煎茶。","更无一个残僧在，归路却投田舍家。"]},{"t":"游定林寺即荆公读书处四首 其四","f":"七言绝句","c":["踏月敲门访病夫，问来还是雪堂苏。","不知把烛高谈许，曾举乌台诗帐无。"]},{"t":"游定林寺即荆公读书处四首 其三","f":"七言绝句","c":["半破僧庵半补篱，旧题无复壁间诗。","祗馀手植双桐在，此外仍兼洗砚池。"]},{"t":"游定林寺即荆公读书处四首 其二","f":"七言绝句","c":["一个青童一蹇驴，九年来往定林居。","经纶枉被周公误，罢相归来始读书。"]},{"t":"游定林寺即荆公读书处四首 其一","f":"七言绝句","c":["钟山已在万山深，更过钟山入定林。","穿尽松杉行尽石，一庵犹隔白云岑。"]},{"t":"游翟园三首 其三","f":"七言绝句","c":["翟园从此即相辞，园里春归我亦归。","蜂踏残花容易落，蝶随数片往来飞。"]},{"t":"游翟园三首 其二","f":"七言绝句","c":["柔风软日斩新晴，酽白娇红鼎盛春。","借问主人何处去，春光分付守园人。"]},{"t":"游翟园三首 其一","f":"七言绝句","c":["花枝劣相絓人衣，蜂子颠狂触面皮。","一巷海棠千架锦，两堤杨柳万窝丝。"]},{"t":"湖天暮景五首 其五","f":"七言绝句","c":["断肠浪说贺方回，未抵秦郎剪水才。","欲向湖边问遗唱，鸳鸯鹦鹉两相推。"]},{"t":"湖天暮景五首 其四","f":"七言绝句","c":["雕碎肝脾只坐诗，须髯成雪鬓成丝。","暮云薄倖斜阳劣，合造清愁付阿谁。"]},{"t":"湖天暮景五首 其三","f":"七言绝句","c":["抵暮渔郎初上船，一竿摇入水精天。","忍寒不睡妨底事，来早卖鱼充酒钱。"]},{"t":"湖天暮景五首 其二","f":"七言绝句","c":["坐看西日落湖滨，不是山衔不是云。","寸寸低来忽全没，分明入水只无痕。"]},{"t":"湖天暮景五首 其一","f":"七言绝句","c":["湖面黏天不见堤，湖心茭葑水周围。","暮鸿成阵鸦成队，已落还飞久未栖。"]},{"t":"湖州三里桥取道德清","f":"七言绝句","c":["浙西只欠到湖州，三里桥头转却舟。","不到湖州妨底事，不如元不到桥头。"]},{"t":"登天柱冈","f":"七言绝句","c":["云外千峰斗速行，山尖一树独分明。","不知林下人家密，倚杖忽闻鸡犬声。"]},{"t":"登多稼亭晓望","f":"七言绝句","c":["风不能销晓雾痕，天犹未放宿云根。","城腰折处才三径，山觜前头别一村。"]},{"t":"登净远亭","f":"七言绝句","c":["池冰受日未全开，旋旋波痕百皱来。","野鸭被人惊得惯，作群飞去却飞回。"]},{"t":"登奉圣寺千佛阁四首 其四","f":"七言绝句","c":["何许飞来双白鸥，碧山贴出雪花浮。","倚栏只管移床立，看到双鸥没处休。"]},{"t":"登奉圣寺千佛阁四首 其三","f":"七言绝句","c":["长诵悬崖置屋牢，此诗此阁晚相遭。","阁中未觉高低在，下到山门始是高。"]},{"t":"登奉圣寺千佛阁四首 其二","f":"七言绝句","c":["远山细腻近山粗，别处求粗也则无。","更向远山山外看，教君病眼一双枯。"]},{"t":"登奉圣寺千佛阁四首 其一","f":"七言绝句","c":["一只奇峰入眼中，看来只只是奇峰。","好山道是无重数，少说青苍十万重。"]},{"t":"登南州奇观前临大江浮桥江心起三石台皆有亭子二首 其二","f":"七言绝句","c":["玉壶冰底卧青龙，海外三山堕眼中。","奇观揭名浑未在，只消题作小垂虹。"]},{"t":"登南州奇观前临大江浮桥江心起三石台皆有亭子二首 其一","f":"七言绝句","c":["梅边楼阁海边山，银竹初收霁日寒。","看著南州奇观了，人间山水不须看。"]},{"t":"登度雪台","f":"五言绝句","c":["欲问金沙信，聊登度雪台。","碧桃良解事，开过架梢来。"]},{"t":"登清心阁","f":"七言绝句","c":["苦遭好月唤登楼，脚力虽慵不自由。","上得金梯一回首，冰轮已过树梢头。"]},{"t":"答徐子材谈绝句","f":"七言绝句","c":["受业初参且半山，终须投换晚唐间。","国风此去无多子，关捩挑来祗等闲。"]},{"t":"答提点纲马驿程刘修武翰二首 其二","f":"七言绝句","c":["解道征鸿数字秋，清于雪椀映冰瓯。","老来笔底心无毒，交割风光与子休。"]},{"t":"答提点纲马驿程刘修武翰二首 其一","f":"七言绝句","c":["公干当年子建亲，景文今代大苏宾。","绝知将种仍诗种，不放骚人与外人。"]},{"t":"紫宸殿拜表贺雪二首 其一","f":"七言律诗","c":["怪来腊日起春风，一夜琼花发禁中。","大地山河银色界，九重楼观水精宫。","紫宸廊迥寒无价，文石庭乾扫不融。","又喜来年书大有，谁知圣主是天公。"]},{"t":"缓辔入东宫门望见渔浦山","f":"七言绝句","c":["渔浦孤峰入九城，承华门里最分明。","马头看得山低去，夹道芙蓉红露声。"]},{"t":"腊里立春蜂蝶辈出","f":"七言绝句","c":["嫩日催青出冻荄，小风吹白落疏梅。","残冬未放春交割，早有黄蜂紫蝶来。"]},{"t":"落花","f":"七言绝句","c":["红紫成泥泥作尘，颠风不管惜花人。","落花辞树虽无语，别倩黄鹂告诉春。"]},{"t":"落梅再著晚花","f":"七言绝句","c":["数日春风不奈暄，梅花落尽净无痕。","却将晚莟重收拾，更放南枝第二番。"]},{"t":"落梅有叹","f":"七言绝句","c":["才看腊后得春饶，愁见风前作雪飘。","脱蕊收将熬粥吃，落英仍好当香烧。"]},{"t":"葵叶","f":"七言绝句","c":["箬笠端能直几钱，骑奴不拟雨连天。","盖头旋折山葵叶，擘破青青伞半边。"]},{"t":"蛛网","f":"七言绝句","c":["深山无水又无人，晒网摊罾夺日明。","却是蜘蛛遭积雨，经纶家计趁新晴。"]},{"t":"蛩声","f":"七言绝句","c":["诚斋老子一归休，最感蛩声五报秋。","细听蛩声元自乐，人愁却道是它愁。"]},{"t":"蛩声三首 其三","f":"七言绝句","c":["莫憎苦调太酸辛，月思霜哀亦可人。","村路小家无此客，溧阳少府是前身。"]},{"t":"蛩声三首 其二","f":"七言绝句","c":["床根吟夜句冥搜，莎底啼寒泣怨秋。","人世如何无苦乐，一般蟋蟀两般愁。"]},{"t":"蛩声三首 其一","f":"七言绝句","c":["山行我已厌征尘，夜语谁能伴老身。","幸有暗蛩同店宿，被渠告诉却愁人。"]},{"t":"谢江东耿漕曼老寄书并与沈侍郎唱和诗二首 其一 谢诒书劳苦","f":"七言绝句","c":["朱雀桥边旧使星，五年再照大江明。","端能记忆诚斋叟，千里书来访死生。"]},{"t":"谢江东耿漕曼老寄书并与沈侍郎唱和诗二首 其二 谢唱和佳句","f":"七言绝句","c":["碧落侍郎金作句，瀛洲学士玉为章。","两公唱和君知么，个是安期却老方。"]},{"t":"谢李元德郎中饷家酿二首 其二","f":"七言绝句","c":["惠山山下玉泉香，酿作鹅儿一拂黄。","吏部只知防姓毕，不知吏部有它杨。"]},{"t":"谢李元德郎中饷家酿二首 其一","f":"七言绝句","c":["长史衔杯太白醺，诙词笑杀古来人。","至今太白一船酒，不饮还将饮子云。"]},{"t":"谢赵茂甫惠浙曹中笔蜀越薄笺二首 其二","f":"七言绝句","c":["百楮先生十兔尖，心知奇绝敢言贪。","诗无好语书仍俗，喜气多多抵得惭。"]},{"t":"谢赵茂甫惠浙曹中笔蜀越薄笺二首 其一","f":"七言绝句","c":["公子平生无长物，几研生涯敌玉冰。","二妙端能并送似，便呼毛颖试溪藤。"]},{"t":"赏牡丹","f":"七言绝句","c":["把酒看花绕画栏，病身只得忍轻寒。","主人半醉花微倦，下却珠帘放牡丹。"]},{"t":"赏菊四首 其四","f":"七言绝句","c":["物性从来各一家，谁贪寒瘦厌妍华。","菊花自择风霜国，不是春光外菊花。"]},{"t":"赏菊四首 其三","f":"七言绝句","c":["菊生不是遇渊明，自是渊明遇菊生。","岁晚霜寒心独苦，渊明元是菊花精。"]},{"t":"赏菊四首 其二","f":"七言绝句","c":["菊花肯为别人黄，长怨先生不断肠。","两鬓尽凋无地插，一杯细嚼入神香。"]},{"t":"赏菊四首 其一","f":"七言绝句","c":["老子平生不解愁，花开酒熟万缘休。","更教不为黄花醉，枉却今年一片秋。"]},{"t":"跋天台王仲言乞米诗","f":"七言绝句","c":["改言缩项更长腰，黄独青精也绝苗。","尚有囊中餐玉法，蓝田山里过明朝。"]},{"t":"跋尤延之山水两轴二首 其二","f":"七言绝句","c":["水漱琼沙冰已凘，野凫半起半犹迟。","千竿脩竹一江碧，只欠梅花三两枝。"]},{"t":"跋尤延之山水两轴二首 其一","f":"七言绝句","c":["水际芦青荷叶黄，霜前木落蓼花香。","渔舟去尽天将夕，雪色飞来鹭一行。"]},{"t":"跋刘敏叔梅兰竹石四清图","f":"七言绝句","c":["老夫老伴竹千竿，湖石江梅更畹兰。","不道外人将短纸，一时捲去也无端。"]},{"t":"跋余伯益所藏张钦夫书西铭短纸二首 其二","f":"七言绝句","c":["横渠方寸著乾坤，传到南轩更莫论。","四海交朋霜叶落，半张翰墨雪涛翻。"]},{"t":"跋余伯益所藏张钦夫书西铭短纸二首 其一","f":"七言绝句","c":["一高一下一中央，怙恃兼侬岂别房。","撞过烟楼休劣相，祗如郎罢也无良。"]},{"t":"跋汪省干诗卷二首 其二","f":"七言绝句","c":["自古诗人太瘦生，可怜辛苦选虚名。","诗家杂压君知么，压尽三公况九卿。"]},{"t":"跋汪省干诗卷二首 其一","f":"七言绝句","c":["向来刘翰有诗声，近日汪经更得名。","月在梅花冰在月，与君句子各争清。"]},{"t":"跋袁起岩所藏兰亭帖","f":"七言绝句","c":["南朝千载有斯人，拈出兰亭花草春。","俛仰之间已陈迹，至今此纸尚如新。"]},{"t":"跋陈简斋奏草","f":"七言绝句","c":["诗宗已上少陵坛，笔法仍抽逸少关。","真迹总归天上去，独留奏草在人间。"]},{"t":"跋范文公与尹师鲁帖","f":"七言绝句","c":["佳客千山得得来，主人双眼为渠开。","逢人莫说当时事，且泊南亭把一杯。"]},{"t":"跋临川梁译居士孝德记二首 其二","f":"七言绝句","c":["祗个当时发一心，通天通地总渠临。","芝兰玉树今争秀，岂但一枝生桂林。"]},{"t":"跋临川梁译居士孝德记二首 其一","f":"七言绝句","c":["雪里星奔避乱兵，母先子后赴寒冰。","祗知判得身俱死，不料还同母再生。"]},{"t":"跋徐恭仲省干近诗三首 其三","f":"七言绝句","c":["传派传宗我替羞，作家各自一风流。","黄陈篱下休安脚，陶谢行前更出头。"]},{"t":"跋徐恭仲省干近诗三首 其二","f":"七言绝句","c":["君家诗伯老师川，解道芦花落钓船。","莫笑东湖秋水冷，近来新吐一枝莲。"]},{"t":"跋徐恭仲省干近诗三首 其一","f":"七言绝句","c":["仰枕糟丘俯墨池，左提大剑右毛锥。","朝兰夕菊都餐却，更斫生柴烂煮诗。"]},{"t":"跋常宁县丞葛齐松子固衡永道中行纪诗卷","f":"七言绝句","c":["宜江风月冉溪云，总与诚斋是故人。","老向烟波诗句里，一朝双看两州春。"]},{"t":"跋淳溪汪立义大学致知图二首 其二","f":"七言绝句","c":["此事元无浅与深，著衣吃饭送光阴。","却缘说似痴人梦，便向汪家图里寻。"]},{"t":"跋淳溪汪立义大学致知图二首 其一","f":"七言绝句","c":["杏坛何物是家风，只在当人阿堵中。","谁作新图漏消息，淳溪溪上钓鱼翁。"]},{"t":"跋符发所录上蔡语二首 其二","f":"七言绝句","c":["符君天秀擢炎方，茧足担簦学北方。","不是澹庵谪南海，姓名那得许芬香。"]},{"t":"跋黄文若诗卷","f":"七言绝句","c":["五字长城璧不如，鼠肝虫臂得关渠。","竹坡集里曾相识，惊见兰亭茧纸书。"]},{"t":"跋韩魏公与尹师鲁帖","f":"七言绝句","c":["侍中尺箠挞羌酋，更得河南共运筹。","到得降书来北阙，河南骑马去均州。"]},{"t":"跋虞丞相与赵撙节使帖还其犹子济二首 其一","f":"七言绝句","c":["虞丞相与赵将军，同策江淮第一勋。","大羽进贤今寂寞，凌烟颂里感风云。"]},{"t":"跋虞丞相与赵撙节使帖还其犹子济二首 其二","f":"七言绝句","c":["侧厘一幅落云烟，意豁神倾叹两贤。","从古将门长出将，眼看小阮勒燕然。"]},{"t":"跋澹庵先生辞工部侍郎答诏不允 其二","f":"七言绝句","c":["愿挽天河洗北夷，老臣底用紫荷为。","丹心一寸凌霜雪，祗有隆兴圣主知。"]},{"t":"跋澹庵先生辞工部侍郎答诏不允 其一","f":"七言绝句","c":["高卧崖州二十年，黑头去国白头还。","身居紫禁莺花里，心在青原水石间。"]},{"t":"跋澹庵先生缴张钦夫赐章服答诏二首 其二","f":"七言绝句","c":["紫绶当时赐两人，一为乳臭一名臣。","老韩不要令同传，谁会先生此意真。"]},{"t":"跋澹庵先生缴张钦夫赐章服答诏二首 其一","f":"七言绝句","c":["平生师友两相知，苦为君王惜一衣。","刺口争来争不得，青蝇犹傍太阳飞。"]},{"t":"道旁石榴花","f":"七言绝句","c":["待阙南风欲炷香，东风打并住西堂。","石榴已著乾红蕾，却问春归有底忙。"]},{"t":"道旁店","f":"七言绝句","c":["路旁野店两三家，清晓无汤况有茶。","道是渠侬不好事，青瓷瓶插紫薇花。"]},{"t":"道旁雨中松","f":"七言绝句","c":["莫信秦人五大夫，一生清苦不敷腴。","也将青玉雕钗子，一一钗头缀雨珠。"]},{"t":"道旁桐花","f":"七言绝句","c":["春色来时物喜初，春光归日兴阑馀。","更无人饯春行色，犹有桐花管领渠。"]},{"t":"道傍小憩观物化","f":"七言绝句","c":["蝴蝶新生未解飞，须拳粉湿睡花枝。","后来借得风光力，不记如痴似醉时。"]},{"t":"道傍怪松","f":"七言绝句","c":["夹道长松去去幽，一松奇怪独凌秋。","两枝垂地却翻上，活走双龙戏翠毬。"]},{"t":"道旁草木二首 其二","f":"七言绝句","c":["古树何年涧底生，只今已与岭般平。","千梢万叶无重数，一一分明报雨声。"]},{"t":"道旁草木二首 其一","f":"七言绝句","c":["山无人迹草长青，异彩奇香不识名。","只是苔花兼藓叶，也无半点俗尘生。"]},{"t":"锁宿省中心气大作通昔不寐得两绝句 其二","f":"七言绝句","c":["绝恨诗人浪许痴，四更无睡只哦诗。","老铃枕手眠窗底，急雨颠风总不知。"]},{"t":"锁宿省中心气大作通昔不寐得两绝句 其一","f":"七言绝句","c":["酒病春愁恰并来，更冲花信宿鸾台。","睡乡堠子无三里，玉漏声声只唤回。"]},{"t":"隔岸","f":"五言绝句","c":["隔岸淮南树，中流渡北人。","数来无急务，一数一回新。"]},{"t":"鹅鼻铺前桃花","f":"七言绝句","c":["归来长恐已春迟，恰是东风二月时。","路上桃花亦欢喜，为人浓抹湿燕支。"]},{"t":"塘闸","f":"七言绝句","c":["山逢塘闸冠南中，小大高低十九峰。","东畔连尖尤秀绝，一双铜绿翠铺茸。"]},{"t":"微雨","f":"七言绝句","c":["要知微雨密还疏，空里看来直是无。","不被波间三两点，阿谁见破妙工夫。"]},{"t":"感兴","f":"七言绝句","c":["看书已怯短檠灯，觅句犹锵涧水声。","诗瘦近来惟有骨，可怜辛苦为虚名。"]},{"t":"感秋","f":"七言绝句","c":["旧不悲秋只爱秋，风中吹笛月中楼。","如今秋色浑如旧，欲不悲秋不自由。"]},{"t":"携家小歇严州建德县簿厅晓起","f":"七言绝句","c":["不堪久客只思归，晓起巡檐强撚髭。","偶听梅梢啼一鸟，举头立看独多时。"]},{"t":"携酒夜饯罗季周","f":"七言绝句","c":["夜深未要掩柴门，且放清风入绿尊。","淡月轻云相映著，浅黄帕子裹金盆。"]},{"t":"新竹","f":"七言绝句","c":["东风弄巧补残山，一夜吹添玉数竿。","半脱锦衣犹半著，箨龙未信没春寒。"]},{"t":"新居剪茅","f":"七言绝句","c":["小筑初开一亩基，晚风散策已相宜。","山童何急催归去，正是凉生月上时。"]},{"t":"新柳","f":"七言绝句","c":["辇路金丝半欲垂，外间玉爪未渠开。","上林柳色休多忆，更趁春风看一回。"]},{"t":"新柳","f":"七言绝句","c":["柳条百尺拂银塘，且莫深青只浅黄。","未必柳条能蘸水，水中柳影引它长。"]},{"t":"新秋盛热","f":"七言绝句","c":["度夏今年未觉难，那知秋热政无端。","晚林不动蝉声苦，蝉亦无风可得餐。"]},{"t":"新淦抛江","f":"七言绝句","c":["烟雨横江水著天，不曾夏涝似今年。","缘堤何用千株柳，只与行人碍过船。"]},{"t":"新热送同邸归客有感二首 其二","f":"七言绝句","c":["瘦不缘诗不为春，只教悬罄未教行。","清和天里不归去，六月长途作么生。"]},{"t":"新热送同邸归客有感二首 其一","f":"七言绝句","c":["日日思亲未拜亲，何时乞我自由身。","同来客子送归尽，更送后来无数人。"]},{"t":"新寒","f":"五言绝句","c":["寒力欺谁得，知侬典却衣。","暮禽差慰眼，不作一行归。"]},{"t":"新晴西园散步四首 其四","f":"七言绝句","c":["厌见山居要出来，出来厌了却思回。","人生毕竟如何是，且看桃花晚莟开。"]},{"t":"新晴西园散步四首 其三","f":"七言绝句","c":["红雨斑斑竹外蹊，黄金袅袅水边丝。","举头拣遍低阴处，带叶青梅摘一枝。"]},{"t":"新晴西园散步四首 其二","f":"七言绝句","c":["池水初生盖玉沙，雨馀碧草卧堤斜。","日摇波影缠桥柱，绣出栾枝遍地花。"]},{"t":"新晴西园散步四首 其一","f":"七言绝句","c":["久雨令人不出门，新晴唤我到西园。","要知春事深和浅，试看青梅大几分。"]},{"t":"新晴晓步","f":"七言绝句","c":["冬来暮暮雨丝丝，竹径梅坡迹顿稀。","作意新晴聊一出，行逢湿路却成归。"]},{"t":"溜港滩","f":"七言绝句","c":["此去严州只半程，一江分作两江横。","忽惊洲背青山下，却有帆樯地上行。"]},{"t":"溪边月上二首 其二","f":"五言绝句","c":["片子黄金饼，看来只管高。","忽然落溪水，杂碎作银涛。"]},{"t":"溪边月上二首 其一","f":"五言绝句","c":["正月十四夜，如何月便团。","似知吾辈出，预借上元看。"]},{"t":"溪边回望东园桃李","f":"七言绝句","c":["看花不合在花间，外面看来锦一般。","每一团花三丈许，红花团绕白花团。"]},{"t":"瑞香花二首 其二","f":"七言绝句","c":["树如岩桂不胜低，花比素馨幽更奇。","要作团栾小窠锦，春风不长出丛枝。"]},{"t":"瑞香花二首 其一","f":"七言绝句","c":["织锦天孙矮作机，紫茸翻出白花枝。","更将沈水浓薰却，日淡风微欲午时。"]},{"t":"睡起观山","f":"七言绝句","c":["过雨前汀未可登，搴篷小散睡瞢腾。","船头政好看山色，一点江风冷似冰。"]},{"t":"睡起即事","f":"七言绝句","c":["午时睡起忽心惊，一事关心太懒生。","速摘荼糜薰白酒，不愁香重只愁轻。"]},{"t":"稚子弄冰","f":"七言绝句","c":["稚子金盆脱晓冰，彩丝穿取当银钲。","敲成玉磬穿林响，忽作玻瓈碎地声。"]},{"t":"筠庵晚睡三首 其三","f":"七言绝句","c":["享了荷花上番香，却穿竹径百弓长。","满园亭榭都参遍，祇有筠庵第一凉。"]},{"t":"筠庵晚睡三首 其二","f":"七言绝句","c":["一户元无白板遮，两窗新染藕丝纱。","竹床品字排三只，睡杀山风醉杀霞。"]},{"t":"筠庵晚睡三首 其一","f":"七言绝句","c":["碧玉新篁翳洞天，绀珉方斛贮山泉。","脱巾赤脚长松下，何处人间更有仙。"]},{"t":"简陆务观史君编修二首 其二","f":"七言绝句","c":["员外治中高帝孙，幕中何幸有诗人。","主人不减西湖长，青眼无妨顾德麟。"]},{"t":"简陆务观史君编修二首 其一","f":"七言绝句","c":["闻道云间陆士龙，钓台绝顶啸清风。","却将半掬催诗雨，洒入山村作岁丰。"]},{"t":"蒲桃乾","f":"七言绝句","c":["凉州博酒不胜痴，银汉乘槎领得归。","玉骨瘦来无一把，向来马乳太轻肥。"]},{"t":"蒲桥寓舍剧暑","f":"七言绝句","c":["三岁都城寓远坊，今年一热古无双。","夜来何处山村雨，凉到蒲桥桥北窗。"]},{"t":"解舟上饶明晖阁前","f":"七言绝句","c":["玉水风船擘岸开，一帆飞到雨花台。","思量饶歙山溪路，梦里征行也莫来。"]},{"t":"解舟铜陵望淮山白云二首 其二","f":"七言绝句","c":["银城遮不尽淮山，许事何缘便达天。","谁遣诗人强饶舌，和山失却忽苍然。"]},{"t":"解舟铜陵望淮山白云二首 其一","f":"七言绝句","c":["天惜淮山不惜银，浑银砌起一长城。","淮山裹在银城里，半出诸峰越样青。"]},{"t":"辞满代者未至","f":"七言绝句","c":["一麾来此恰三年，到得终更分外难。","老眼看灯浑作晕，愁心得酒不成欢。"]},{"t":"遣骑问讯范明州参政报章寄二绝句和韵谢之 其一","f":"七言绝句","c":["南海人从东海归，新诗到日恰梅时。","撚梅细比新诗看，未必梅花瘦似诗。"]},{"t":"遣骑问讯范明州参政报章寄二绝句和韵谢之 其二","f":"七言绝句","c":["一别姑苏江上台，绿波碧草恨悠哉。","忽然两袖珠玑满，割取三吴风月来。"]},{"t":"酬阁皂山碧崖道士甘叔怀赠美名人不及佳句法如何十古风二首 其二","f":"七言绝句","c":["赠我新诗字字奇，一奁八百颗珠玑。","问侬佳句如何法，无法无盂也没衣。"]},{"t":"酬阁皂山碧崖道士甘叔怀赠美名人不及佳句法如何十古风二首 其一","f":"七言绝句","c":["桂林户掾旧能文，有弟抛家作道人。","诗似道人人似鹤，看来若个觅纤尘。"]},{"t":"鹊营巢既成为鸠所据","f":"七言绝句","c":["乾鹊平生浪苦辛，一年卜筑一番新。","如何月下空三匝，宅子还将住别人。"]},{"t":"暮立荷桥","f":"七言绝句","c":["欲问红蕖几莟开，忽惊浴罢夕阳催。","也知今夕来差晚，犹胜穷忙不到来。"]},{"t":"暮行田间二首 其二","f":"七言绝句","c":["水满平田无处无，一张雪纸眼中铺。","新秧乱插成井字，却道山农不解书。"]},{"t":"暮行田间二首 其一","f":"七言绝句","c":["布谷声中日脚收，瘦藤叫我看西畴。","露珠走上青秧叶，不到梢头便肯休。"]},{"t":"暮坐中庭","f":"五言绝句","c":["蚊子因凉减，蝉声入暮多。","有愁无处著，不饮欲如何。"]},{"t":"暮春小雨","f":"七言绝句","c":["宿酒微醒尚小醺，似痴如病不多欣。","深深池沼轻轻雨，独倚栏干看水纹。"]},{"t":"暮春即事","f":"七言绝句","c":["花时追赏夜将朝，花过痴眠日尽高。","又与山禽争口腹，执竿挟弹守樱桃。"]},{"t":"暮热游荷池上五首 其五","f":"七言绝句","c":["空中斗起朵云头，旋旋开来旋旋收。","初作䰒松松树子，忽成髣髴柳花毬。"]},{"t":"暮热游荷池上五首 其四","f":"七言绝句","c":["也不多时便立秋，寄声残暑速拘收。","瘦蝉有得许多气，吟落斜阳未肯休。"]},{"t":"暮热游荷池上五首 其三","f":"七言绝句","c":["细草摇头忽报侬，披襟拦得一西风。","荷花入暮犹愁热，低面深藏碧伞中。"]},{"t":"暮热游荷池上五首 其二","f":"七言绝句","c":["寒甃千寻汲井花，病身一浴不胜佳。","追凉不得浑闲事，烧眼生憎半幅霞。"]},{"t":"暮热游荷池上五首 其一","f":"七言绝句","c":["玉砾金沙一径长，暑中无处可追凉。","独行行到荷池上，荷不生风水不香。"]},{"t":"凝露堂前紫薇花两株每自五月盛开九月乃衰二首 其二","f":"七言绝句","c":["似痴如醉弱还佳，露压风欺分外斜。","谁道花无红十日，紫薇长放半年花。"]},{"t":"凝露堂前紫薇花两株每自五月盛开九月乃衰二首 其一","f":"七言绝句","c":["晴霞艳艳覆檐牙，绛雪霏霏点砌沙。","莫管身非香案吏，也移床对紫薇花。"]},{"t":"碧落洞四首 其四","f":"七言绝句","c":["际会诸滩吼怒雷，遭逢江势更萦回。","今宵不到英州定，何用山云送雨来。"]},{"t":"碧落洞四首 其三","f":"七言绝句","c":["洞里仙人枉费功，凿江屈曲做神通。","千萦万绕留江住，毕竟奔流入峡中。"]},{"t":"碧落洞四首 其二","f":"七言绝句","c":["梦中曾泊洞前船，落絮飞花是去年。","今日来寻泊船处，一江风雨草连天。"]},{"t":"碧落洞四首 其一","f":"七言绝句","c":["碧落诸峰是碧簪，忽于平地插瑶岑。","洞中定有神仙宅，玉室金堂不可寻。"]},{"t":"碧落洞前滩水三首 其二","f":"七言绝句","c":["石峰背后即英州，只不教人到岸头。","罗带春风吹不直，故将数摺恼行舟。"]},{"t":"碧落堂晚望","f":"七言绝句","c":["暮笳声里暮云生，白白非烟覆一城。","祇有青林遮不得，兜罗绵上绿琴横。"]},{"t":"碧瑶洞天","f":"七言绝句","c":["青松万树竹千竿，苍翠中间别一天。","从此洞天三十七，初头且数碧瑶仙。"]},{"t":"端午后顿热","f":"七言绝句","c":["只今新暑已歊然，作么禁当六月天。","飞上风前最凉处，年年输与柳梢蝉。"]},{"t":"蜜渍梅花","f":"七言绝句","c":["瓮澄雪水酿春寒，蜜点梅花带露餐。","句里略无烟火气，更教谁上少陵坛。"]},{"t":"蜡烛","f":"五言绝句","c":["未夜身先卧，不春花已开。","泣残双泪雨，愁得寸心灰。"]},{"t":"蜡梅四首 其四","f":"七言绝句","c":["江梅珍重雪衣裳，薄相红梅学杏装。","渠独小参黄面老，额间艳艳发金光。"]},{"t":"蜡梅四首 其三","f":"七言绝句","c":["莟头元不是花房，融蜡熬酥戏滴将。","忽见微舒金爪甲，不知中有紫香囊。"]},{"t":"蜡梅四首 其二","f":"七言绝句","c":["眉间蜜酒发轻黄，对著诗人不惜香。","金作仙衣元自冷，月中仍带一身霜。"]},{"t":"蜡梅四首 其一","f":"七言绝句","c":["蜜蜂底物是生涯，花作糇粮蜡作家。","岁晚略无花可采，却将香蜡吐成花。"]},{"t":"酴醾初发","f":"七言绝句","c":["一春长是怨春迟，过却春光总不知。","已负海棠桃李了，再三莫更负酴醾。"]},{"t":"静坐池亭二首 其二","f":"七言绝句","c":["荷边弄水一身香，竹里招风满扇凉。","道是秋来还日短，秋来闲里日偏长。"]},{"t":"静坐池亭二首 其一","f":"七言绝句","c":["胡床倦坐起凭栏，人正忙时我正闲。","却是闲中有忙处，看书才了又看山。"]},{"t":"鲊鱼潭登舟","f":"七言绝句","c":["船阁寒沙待晚潮，行人舟子各相招。","银山一朵三千丈，隔海飞来对面销。"]},{"t":"嘲报春花","f":"七言绝句","c":["嫩黄老碧已多时，騃紫痴红略万枝。","始有报春三两朵，春深犹自不曾知。"]},{"t":"嘲稚子","f":"七言绝句","c":["雨里船中不自由，无愁稚子亦成愁。","看渠坐睡何曾醒，及至教眠却掉头。"]},{"t":"嘲蜂","f":"七言绝句","c":["薰笼供药较香些，引得蜂儿绕室哗。","笑死老夫缘底事，蜂儿专用鼻看花。"]},{"t":"嘲蜻蜓","f":"七言绝句","c":["饵花春蝶即花仙，饮露秋蝉怕露寒。","只道蜻蜓解餐水，元来照水不曾餐。"]},{"t":"德寿宫庆寿口号 其一","f":"七言绝句","c":["长乐宫前望翠华，玉皇来贺太皇家。","青天白日仍飞雪，错认东风转柳花。"]},{"t":"德寿宫庆寿口号 其五","f":"七言绝句","c":["帝捧瑶觞玉座前，綵衣三世祝尧年。","天皇八十一万岁，休说庄椿两八千。"]},{"t":"德寿宫庆寿口号 其三","f":"七言绝句","c":["春色何须羯鼓催，君王元日领春回。","牡丹芍药蔷薇朵，都向千官帽上开。"]},{"t":"德寿宫庆寿口号 其六","f":"七言绝句","c":["天父晨兴未出房，君王忍冷立风廊。","忽然鸣跸珠帘捲，万岁声传震八荒。"]},{"t":"德寿宫庆寿口号 其十","f":"七言绝句","c":["甲戌王春试集英，小臣曾是老门生。","苍颜华发鹓行里，也听钧天九奏声。"]},{"t":"德寿宫庆寿口号 其四","f":"七言绝句","c":["双金狮子四金龙，喷出香云绕殿中。","太上垂衣今上拜，百王曾有个家风。"]},{"t":"德寿宫庆寿口号 其二","f":"七言绝句","c":["清晓鞭声出禁中，惊开剩雨及残风。","金鸦衔取红鸾扇，飞上玻瓈碧海东。"]},{"t":"德寿宫庆寿口号 其八","f":"七言绝句","c":["甘露祥风天上来，今回恩数赛前回。","都将四海欢声里，酿作慈皇万寿杯。"]},{"t":"德寿宫庆寿口号 其九","f":"七言绝句","c":["尧舜同时已甚都，祖孙四世古今无。","谁将写日摹天手，画作皇王盛事图。"]},{"t":"德远叔坐上赋肴核八首 其六 人面子","f":"七言绝句","c":["喜时能笑醉能歌，眉映青山眼映波。","旧日美如潘骑省，只今瘦似病维摩。"]},{"t":"德远叔坐上赋肴核八首 其二 牛尾狸","f":"七言绝句","c":["琼瑶风骨褐衣裘，野果初红玉露秋。","僧孺唤渠登榜尾，季狸只合隐山头。"]},{"t":"德远叔坐上赋肴核八首 其八 银杏","f":"七言绝句","c":["深灰浅火略相遭，小苦微甘韵最高。","未必鸡头如鸭脚，不妨银杏伴金桃。"]},{"t":"德远叔坐上赋肴核八首 其一 糟蟹","f":"七言绝句","c":["横行湖海浪生花，糟粕招邀到酒家。","酥片满螯凝作玉，金穰镕腹未成沙。"]},{"t":"樊系","f":"七言绝句","c":["册文不做也由伊，做了何须死不辞。","可惜一杯金屑酒，饮来祗较早些时。"]},{"t":"横林望见惠山寄怀尤延之三首 其三","f":"七言绝句","c":["平生玉树伴蒹葭，晚岁春兰隔菊花。","咫尺遂初堂下水，寄诗犹自怨人遐。"]},{"t":"横林望见惠山寄怀尤延之三首 其二","f":"七言绝句","c":["惠山孤绝未为孤，下有诗仙伴却渠。","占断惠山妨底事，无端更占洞庭湖。"]},{"t":"横林望见惠山寄怀尤延之三首 其一","f":"七言绝句","c":["惠山一别十年强，雪后精神老更苍。","白玉屏风三万丈，半天遮断太湖光。"]},{"t":"樱桃花","f":"七言绝句","c":["樱桃花发满晴柯，不赌娇饶只赌多。","落尽江梅馀半朵，依前风韵合还他。"]},{"t":"豫章江皋二绝句 其一","f":"七言绝句","c":["幸自轻阴好片秋，如何馀热未全休。","大江欲近风先冷，平野无边草亦愁。"]},{"t":"豫章江皋二绝句 其二","f":"七言绝句","c":["只今秋稼满江郊，犹记春船掠屋茅。","可是北风寒入骨，荻花争作向南梢。"]},{"t":"醉后撚梅花近壁以灯照之宛然如墨梅","f":"七言绝句","c":["老子年来画入神，凿空幻出墨梅春。","壁为玉板灯为笔，整整斜斜样样新。"]},{"t":"醉眠夜闻霜风甚紧起坐达旦二首 其二","f":"七言绝句","c":["雪花旋落旋成融，横作清霜阵阵风。","一夜急吹君会否，妒它残叶恋丹枫。"]},{"t":"醉眠夜闻霜风甚紧起坐达旦二首 其一","f":"七言绝句","c":["玉酒醺人底易醒，月低梅影恰三更。","只嫌老眼清无睡，不道松声听到明。"]},{"t":"镊白","f":"七言绝句","c":["莫把菱花镊白髭，劝君留取伴吟诗。","锦囊若要添新句，绣口如何减素丝。"]},{"t":"镊白","f":"七言绝句","c":["五十如何是后生，呼儿拔白未忘情。","新年只道无功业，也有霜髭六十茎。"]},{"t":"霅溪","f":"七言绝句","c":["道场山背是吴兴，只不教人到德清。","霅水相留别无计，却将溪曲暗添程。"]},{"t":"题山庄小集","f":"七言绝句","c":["莫笑山庄小集休，篇篇字字爽于秋。","向来枫落吴江冷，一句能销万古愁。"]},{"t":"题山庄草虫扇","f":"七言绝句","c":["风生蚱蜢怒须头，纨扇团圆璧月流。","三蝶商量探花去，不知若个是庄周。"]},{"t":"题太和宰卓士直寄新刻山谷快阁诗真迹二首 其二","f":"七言绝句","c":["太史留题快阁诗，旧碑未必是真题。","六丁搜出严家墨，白日青天横紫蜺。"]},{"t":"题太和宰卓士直寄新刻山谷快阁诗真迹二首 其一","f":"七言绝句","c":["快阁江鸥远避人，西昌山月暗吹尘。","百年卓茂传诗印，印出风光色色新。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其五 太湖秋晚","f":"五言绝句","c":["水气清空外，人家秋色中。","细看千万落，户户水精宫。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其七 西湖夏日","f":"五言绝句","c":["四月曾湖上，荷钱劣可穿。","归来开短纸，十里已红莲。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其三 庐山霁色","f":"五言绝句","c":["彭泽收积雨，庐山放嫩晴。","多情是瀑布，只作雨中声。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其八 灵隐冷泉","f":"五言绝句","c":["小潘诗家子，解作无声诗。","八境俱妙绝，冷泉天下奇。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其一 洞庭波涨","f":"五言绝句","c":["湖水吞天去，湖风送浪还。","银山何处是，青底是君山。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其六 浙江观潮","f":"五言绝句","c":["海涌银为郭，江横玉系腰。","吴侬只言黠，到老也看潮。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其四 海门残照","f":"五言绝句","c":["万里长江白，半规斜日黄。","焦山浑欲到，宛在水中央。"]},{"t":"题王才臣南山隐居六咏 其五 松庵","f":"五言绝句","c":["与花不同色，与竹元同德。","风月偏相寻，携手清凉国。"]},{"t":"题王才臣南山隐居六咏 其三 南谷","f":"五言绝句","c":["我生本南溪，我长寓南谷。","是子底无良，夺我谷中菊。"]},{"t":"题王季安主簿佚老堂二首 其二","f":"七言绝句","c":["布袜青鞋已懒行，不如宴坐听啼莺。","只言此老浑无事，种竹移花作么生。"]},{"t":"题王季安主簿佚老堂二首 其一","f":"七言绝句","c":["造物那能恼我曹，软红尘里漫徒劳。","是中却有商量处，且道青原几许高。"]},{"t":"题邓国材水墨寒林","f":"七言绝句","c":["人间那得个山川，船上渔郎便是仙。","远岭外头江尽处，问渠何许洞中天。"]},{"t":"题东西二梁山三首 其三","f":"七言绝句","c":["传道临春昔丽华，不从陈帝入隋家。","独将亡国千年恨，留下双颦寄岸花。"]},{"t":"题东西二梁山三首 其二","f":"七言绝句","c":["莫恨当初画得偏，却因偏处反成妍。","喜来舒展愁来蹙，各样娇饶更可怜。"]},{"t":"题东西二梁山三首 其一","f":"七言绝句","c":["二梁双黛点东西，牛渚看来活底眉。","阿敞画时微失手，一眉高著一眉低。"]},{"t":"题北山教场亭子","f":"七言绝句","c":["堂样毬场五百弓，帝城何地似亭中。","北山南畔南山北，独受西湖万顷风。"]},{"t":"题龙舜臣逊志斋","f":"七言绝句","c":["龙子辛勤莳纸田，少年笔势已翩翩。","欲知圣处真消息，不是原夫一两联。"]},{"t":"题刘伯山蕃殖图二首画禾黍稌菽麦 其二","f":"七言绝句","c":["黄云翠荚杂玄珠，上熟今年不负渠。","说似田家早收拾，一番风雨一番疏。"]},{"t":"题刘伯山蕃殖图二首画禾黍稌菽麦 其一","f":"七言绝句","c":["老子平生只荷锄，误携破砚到清都。","归来荒尽西畴却，愧见刘家蕃殖图。"]},{"t":"题刘高士看云图","f":"七言绝句","c":["偶为看云且罢琴，万山寒隔一溪深。","谁言咽月餐云客，中有忧时致主心。"]},{"t":"题刘景明百马图扇面","f":"五言绝句","c":["雾鬣如无笔，霜蹄不带埃。","直言明眼著，若个是龙媒。"]},{"t":"题刘景明百牛图扇面","f":"五言绝句","c":["吉语闻田父，新年胜故年。","借侬百觳觫，雨里破荒田。"]},{"t":"题刘翔卿蔚然楼二首 其二","f":"七言绝句","c":["楼上青编入骨香，楼前碧岫透帘光。","乘风飞上广寒殿，下看秋容一点苍。"]},{"t":"题刘翔卿蔚然楼二首 其一","f":"七言绝句","c":["诚叟颠狂与醉题，艮翁珍重洒瑰词。","山棱莫学诗肩瘦，月写云描总是诗。"]},{"t":"题刘德夫真意亭二首 其二","f":"七言绝句","c":["渊明有意自忘言，真处如今底处传。","客子若来问真意，镜中人影水中天。"]},{"t":"题刘德夫真意亭二首 其一","f":"七言绝句","c":["湖上轩窗岸岸开，谁家不傍读书台。","新亭自有人知处，只拣风烟好处来。"]},{"t":"题西湖僧房","f":"七言绝句","c":["竹林深处著禅房，下却疏帘自炷香。","书画随宜遮四壁，闲欹瓦枕小藤床。"]},{"t":"题张坦夫腴庄图三首 其三","f":"七言绝句","c":["花开还喜落还嗟，君被腴庄恼却些。","何似老夫展横轴，一朝看尽四时花。"]},{"t":"题张坦夫腴庄图三首 其二","f":"七言绝句","c":["花光泉响不相参，城市山林难两兼。","不分腴庄最无赖，一时奄有忒伤廉。"]},{"t":"题张坦夫腴庄图三首 其一","f":"七言绝句","c":["百里青山十里溪，荷花万顷照红衣。","临平山下西湖上，总被腴庄掇取归。"]},{"t":"题汪季路太丞魏野草堂图二首 其二","f":"七言绝句","c":["奉常夫子半钱无，不问田园况室庐。","闻道买来新宅子，借看却是草堂图。"]},{"t":"题汪季路太丞魏野草堂图二首 其一","f":"七言绝句","c":["汾阴西祀告升平，四海无波镜样清。","乞与幽人好风月，万山里许听泉声。"]},{"t":"题汪季路所藏李伯时飞骑斫鬃射杨枝及绣毬图二首 其二","f":"七言绝句","c":["君王将幸宝津园，刷洗天驹尚未乾。","禁地何缘有阑入，考官应奉得来看。"]},{"t":"题汪季路所藏李伯时飞骑斫鬃射杨枝及绣毬图二首 其一","f":"七言绝句","c":["虎夫驰射殿西偏，一箭穿毬不再弯。","飞骑新图天上本，龙眠偷得到人间。"]},{"t":"题沈子寿旁观录","f":"七言绝句","c":["逢著诗人沈竹斋，丁宁有口不须开。","被渠谱入旁观录，四马如何挽得回。"]},{"t":"题赤孤同亭馆","f":"七言绝句","c":["数菊能令客眼明，三峰端为此堂横。","仆夫不敢催侬去，只道长沙尚八程。"]},{"t":"题陈叔虎绣梅花扇","f":"五言绝句","c":["指下生寒影，针端即化工。","冰痕将雪点，不受烛光融。"]},{"t":"题周子中司户乘成台三首 其二","f":"七言绝句","c":["只须独立领秋光，何用安排石鼓双。","平揖青原未为差，更于竹外见长江。"]},{"t":"题周子中司户乘成台三首 其一","f":"七言绝句","c":["不烦营筑便成台，自有青松不用栽。","只道先生忙更懒，也须一日一回来。"]},{"t":"题周子中司户乘成台三首 其三","f":"七言绝句","c":["先生无劓何须补，上到乘成尽放怀。","松树尚堪驱使在，为公一一捧诗牌。"]},{"t":"题所寓唐德明书斋","f":"七言绝句","c":["凫鹜行中脱病身，竹林深处得幽人。","只言官满浑无事，也被诗愁搅一春。"]},{"t":"题罗溪李店 其二","f":"七言绝句","c":["谁道村郊野味侵，柴扉竹榻草花清。","行行且止成佳梦，不减崔张惊梦身。"]},{"t":"题罗溪李店 其一","f":"七言绝句","c":["栋宇整齐窗户明，一峰对面一江横。","下程长是无佳店，佳店偏当未下程。"]},{"t":"题钓台二绝句 其一","f":"七言绝句","c":["断崖初未有人踪，只合先生著此中。","汉室也无一抔土，钓台今是几春风。"]},{"t":"题钓台二绝句 其二","f":"七言绝句","c":["同学书生已冕旒，未将换与一羊裘。","子云到老不晓事，不信人间有许由。"]},{"t":"题胡季亨观生亭二首 其二","f":"七言绝句","c":["漏泄春光有阿亨，一双诗眼太乖生。","草根未响渠先觉，不待黄鹂第一声。"]},{"t":"题胡季亨观生亭二首 其一","f":"七言绝句","c":["谁信秋霜腊雪中，雪中霜里有春风。","菊花未了梅花发，休说桃花入嫩红。"]},{"t":"题荐福寺","f":"七言绝句","c":["千山底里著楼台，半夜松风万壑哀。","晓起巡檐看题壁，雨声一片隔林来。"]},{"t":"题赵昌父山居八咏 其五 已矣轩","f":"五言绝句","c":["蛮触无休日，菟裘有别天。","抚松非已矣，采菊未悠然。"]},{"t":"题赵昌父山居八咏 其一 竹隐","f":"五言绝句","c":["大隐隐于酒，小隐隐于竹。","何不呼曲生，来同此君宿。"]},{"t":"题赵昌父山居八咏 其三 苔竹轩","f":"五言绝句","c":["青士长得瘦，翠兄工买贫。","向来素爱者，已赚一诗人。"]},{"t":"题赵昌父山居八咏 其六 倚云亭","f":"五言绝句","c":["俗子令眼白，瑞峰令眼青。","自移听雨榻，且上倚云亭。"]},{"t":"题赵昌父山居八咏 其二 晏斋","f":"五言绝句","c":["五陵槿梢花，千驷草头露。","富贵人始传，屡空今不数。"]},{"t":"题赵昌父山居八咏 其七 霞牖","f":"五言绝句","c":["夕借月为烛，晨将霞作帘。","犹言贫到骨，不悟取伤廉。"]},{"t":"题钟家村石崖二首 其二","f":"七言绝句","c":["水与高崖有底冤，相逢不得镇相喧。","若教渔父头无笠，只著蓑衣便是猿。"]},{"t":"题钟家村石崖二首 其一","f":"七言绝句","c":["莫爱悬崖万丈高，只工险峭作风涛。","看来一一生窠眼，解与行人著过篙。"]},{"t":"题清远峡峡山寺二首 其二","f":"七言绝句","c":["见说岩中雪色猿，啸声时出翠微间。","不看新月初三夜，却觅当时旧玉环。"]},{"t":"题清远峡峡山寺二首 其一","f":"七言绝句","c":["只道真阳天下稀，不知清远亦幽奇。","攀崖下照龙湫水，细咏东坡老子诗。"]},{"t":"题章贡道院","f":"七言绝句","c":["江西道院赋金华，近日当涂共两家。","更著崆峒三道院，只销卧治醉莺花。"]},{"t":"题萧岳英常州草虫轴盖画师之女朱氏之笔二首 其二","f":"七言绝句","c":["笔端春草已如生，点缀虫沙更未停。","浅著鹅黄作蝴蝶，深将猩血染蜻蜓。"]},{"t":"题萧岳英常州草虫轴盖画师之女朱氏之笔二首 其一","f":"七言绝句","c":["常州草虫天下奇，女郎新样不缘师。","未应好手传轮扁，便恐前身是郭熙。"]},{"t":"题曾无己所藏高丽疋纸蔡君谟欧公笔迹","f":"七言绝句","c":["三韩玉叶展明蠲，诸老银钩卷碧鲜。","幸自不逢文与可，一竿秋竹扫风烟。"]},{"t":"题桄榔树","f":"七言绝句","c":["化工到得巧穷时，东补西移也大奇。","君看桄榔一窠子，竹身杏叶海棕枝。"]},{"t":"题谢昌国金牛烟雨图","f":"七言绝句","c":["金牛烟雨最相关，老子方将老是间。","不分艮斋来貌取，更于句里占江山。"]},{"t":"题韩亭韩木二首 其二","f":"七言绝句","c":["笑为先生一问天，身前身后两般看。","亭前树子关何事，也得天公赐姓韩。"]},{"t":"题韩亭韩木二首 其一","f":"七言绝句","c":["老大韩家十八郎，犹将云锦制衣裳。","至今南斗无精彩，只放文星一点光。"]},{"t":"题照上人迎翠轩二首 其一","f":"七言绝句","c":["寺外秋山触眼明，寺根秋水洗心清。","晴岚暖翠来未了，不用高人倒屣迎。"]},{"t":"题照上人迎翠轩二首 其二","f":"七言绝句","c":["参寥癞可去无还，谁踏诗僧最上关。","欲具江西句中眼，犹须作礼问云山。"]},{"t":"题榠查红叶","f":"七言绝句","c":["榠查将叶学丹枫，戏与攀条撼晚风。","一片飞来最奇绝，碧罗袖尾滴猩红。"]},{"t":"题赣州重建思贤阁","f":"七言绝句","c":["赵公遗爱虎头城，直到张公续此声。","前赵后张俱可阁，赣民不用羡西京。"]},{"t":"凝露堂木犀二首 其二","f":"七言绝句","c":["梦骑白凤上青空，径度银河入月宫。","身在广寒香世界，觉来帘外木犀风。"]},{"t":"凝露堂木犀二首 其一","f":"七言绝句","c":["雪花四出剪鹅黄，金屑千麸糁露囊。","看去看来能几大，如何著得许多香。"]},{"t":"憩分水岭望乡二首 其二","f":"七言绝句","c":["岭北泉流分外忙，一声一滴断人肠。","浪愁出却庐陵界，未入梅山总故乡。"]},{"t":"憩分水岭望乡二首 其一","f":"七言绝句","c":["岭头泉眼一涓流，南入虔州北吉州。","只隔中间些子地，水声滴作两乡愁。"]},{"t":"憩冷水村道傍榴花初开","f":"七言绝句","c":["茜罗绉薄剪薰风，已自花明蒂亦同。","不肯染时轻著色，却将密绿护深红。"]},{"t":"憩楹塘驿二首 其二","f":"七言绝句","c":["松鸣竹啸响千崖，为底炎蒸吹不开。","自是笋舆趋北去，薰风不是不南来。"]},{"t":"憩楹塘驿二首 其一","f":"七言绝句","c":["夹路黄茅与树齐，人行茅里似山鸡。","长松不与遮西日，却送清阴过隔溪。"]},{"t":"檃括东坡观棋诗引并四言诗二首 其二","f":"七言绝句","c":["五老峰前松荫庭，风光清美日华明。","独游略不逢一士，时有纹枰落子声。"]},{"t":"檃括东坡观棋诗引并四言诗二首 其一","f":"七言绝句","c":["老坡独往到庐山，白鹤观中俱昼眠。","只有棋声人不见，寂然流水古松间。"]},{"t":"燕脂楼子","f":"五言绝句","c":["楼子燕脂色，灯前艳更鲜。","看花直到晓，今夕不成眠。"]},{"t":"薄晚绝句二首 其二","f":"七言绝句","c":["暂出嫌喧可得除，漫游久废未全无。","路逢盐裹知城近，店有鸡声觉日晡。"]},{"t":"薄晚绝句二首 其一","f":"七言绝句","c":["春气吹人不作醒，病身感物底心情。","斜阳也不藏人老，偏照霜髭一两茎。"]},{"t":"衡山值雨","f":"七言绝句","c":["稍喜归涂中半程，犹愁泥潦未知晴。","雨来也不怜行客，风过何须作许声。"]},{"t":"赠写真刘敏叔秀才二首 其二","f":"七言绝句","c":["江右传神下笔亲，杉溪集里识刘君。","君今有子能传业，撞过烟楼更入神。"]},{"t":"赠写真刘敏叔秀才二首 其一","f":"七言绝句","c":["冰鉴传神苦未工，传来恰恰五秋风。","又将老丑形骸子，般入刘家画苑中。"]},{"t":"赠归宗长老道贤","f":"七言绝句","c":["地下归宗天下传，老夫剩欲到云边。","王弘送酒催归去，且省远公沽酒钱。"]},{"t":"赠刘汉卿太医","f":"七言绝句","c":["炉底金丹妙入神，月中玉兔捣成尘。","臣门如市心如水，只要阴功活万人。"]},{"t":"送刘惠卿二首 其二","f":"七言绝句","c":["旧病诗狂与酒狂，新来泉石又膏肓。","不医则是医还是，更问无方定有方。"]},{"t":"送刘惠卿二首 其一","f":"七言绝句","c":["活却千人药一囊，阴功吹作满城香。","灵椿丹桂君家有，莫羡燕山窦十郎。"]},{"t":"赠阁皂山懒云道士诗客张惟深二首 其二","f":"七言绝句","c":["羽客来从阁皂山，殷勤告诉病诗癫。","古今此病元无药，癫到阴何便是仙。"]},{"t":"赠阁皂山懒云道士诗客张惟深二首 其一","f":"七言绝句","c":["阁皂峰头半朵云，化为道士到吾门。","问渠真个如云懒，为许随风处处村。"]},{"t":"赠相士蓑衣道人杜需二首 其二","f":"七言绝句","c":["坐来小歇过眉拄，客里那能满眼酤。","肯脱蓑衣借侬著，鸥边雨外且江湖。"]},{"t":"赠相士蓑衣道人杜需二首 其一","f":"七言绝句","c":["与子生疏有底仇，谈间容易说封侯。","病身更遣冰山倚，野鹤孤云也替愁。"]},{"t":"赠剪字吴道人","f":"七言绝句","c":["宝晋云烟杂海涛，玉溪花月写风骚。","一生不倩毛锥子，只倩并州快剪刀。"]},{"t":"赠曾相士二首 其二","f":"七言绝句","c":["抛了儒书读相书，却将冷眼看诸儒。","曾生肯伴诚斋否，共个渔舟入五湖。"]},{"t":"赠曾相士二首 其一","f":"七言绝句","c":["富贵真成一聚尘，饥寒选得万年名。","心知那有扬州鹤，更问侬当作么生。"]},{"t":"壕上","f":"七言绝句","c":["壕上朝来眼顿明，小风浅水写秋清。","新霜杀尽浮萍草，放出靴纹水面生。"]},{"t":"壕上书事","f":"七言绝句","c":["十里长壕展碧漪，波痕只去不曾归。","鹭鸶已饱浑无干，独立朝阳理雪衣。"]},{"t":"檐滴","f":"七言绝句","c":["檐滴疏疏亦几何，滴将苔砌出圜窠。","就中漱涤偏精巧，泥土都无石子多。"]},{"t":"藏船屋二首 其二","f":"七言绝句","c":["非港非沟别一涯，茅檐元不是人家。","不居黔首居青雀，动地风涛不到它。"]},{"t":"藏船屋二首 其一","f":"七言绝句","c":["望见官旗衔舳舻，渔船争入沼中芦。","藏船芦底犹有雨，屋底藏船雨也无。"]},{"t":"踏青","f":"五言绝句","c":["雨换溪溪玉，花呈岭岭春。","秧田暄处早，茅屋补痕新。"]},{"t":"霜","f":"七言绝句","c":["天欲吹霜不作难，连宵也费许多寒。","新装琼甲为蔬甲，仍化朱栏作玉栏。"]},{"t":"霜夜","f":"七言绝句","c":["月影全无只有星，如何夜色照人清。","素娥未必饶青女，不道霜明胜月明。"]},{"t":"霜夜无睡闻画角孤雁二首 其二","f":"七言绝句","c":["梅边玉琯月边横，吹落银河与晓星。","城里万家都睡著，孤鸿叫我起来听。"]},{"t":"霜夜无睡闻画角孤雁二首 其一","f":"七言绝句","c":["画角声从枕底鸣，愁霜怨月不堪听。","拥紬起坐何人伴，只有残灯半晕青。"]},{"t":"霜夜望月","f":"七言绝句","c":["人静蛩喧天欲霜，不眠独自步风廊。","闲看月走仍云走，知是云忙复月忙。"]},{"t":"霜草","f":"七言绝句","c":["霜前乱碧未全枯，霜后纷黄却更苏。","偷吃瑶台青女粉，都生琼发与银须。"]},{"t":"霜晓","f":"五言绝句","c":["霜重晓未觉，日高融始寒。","空墙半根湿，落叶片声乾。"]},{"t":"霜晓","f":"七言绝句","c":["荒荒瘦日作秋晖，稍稍微暄破晓霏。","只有江枫偏得意，夜挼霜水染红衣。"]},{"t":"翻破箧得张钦夫唱和诗","f":"七言绝句","c":["年年不是不吟诗，吟得诗成寄阿谁。","留取朱弦不须断，只将瑶匣锁蛛丝。"]},{"t":"衢州近城果园","f":"七言绝句","c":["未到衢州五里时，果林一望蔽江湄。","黄柑绿橘深红柿，树树无风缒脱枝。"]},{"t":"乙丑改元开禧元日","f":"七言律诗","c":["开禧元祀更元正，宿雨新收放晓晴。","夜半梅花添一岁，梦中爆竹报残更。","方知人喜天亦喜，作么钟鸣鸡未鸣。","老子年龄君莫问，屠苏饮了更无兄。"]},{"t":"乙卯春日三三径行散有感","f":"七言律诗","c":["东园一日走千巡，又见龙飞第一春。","桃李成阴侬已老，江山依旧岁还新。","穿花踏影浑无日，隔径闻声不见人。","学省同寮各星散，白云珍重伴闲身。"]},{"t":"乙未和杨谨仲教授春兴","f":"七言律诗","c":["归欤还复换年芳，不分官梅恼石肠。","黄帽政堪供短棹，白头可更献长杨。","忽逢社里催搜句，安得花边对举觞。","天上含香有知己，弹冠端复为王阳。"]},{"t":"乙酉社日偶题","f":"七言律诗","c":["愁边节里两相关，茶罢呼儿检历看。","社日雨多晴较少，春风晚暖晓犹寒。","也思散策郊行去，其奈缘溪路未乾。","绿暗红明非我事，且寻野蕨作蔬盘。"]},{"t":"七夕后一夜月中露坐二首 其二","f":"七言律诗","c":["今古诗人爱月圆，未堪商略玉婵娟。","脩眉半璧各自好，团镜磨镰俱可怜。","一夜一般新样出，几回几换为人妍。","教渠也学金鸦扇，未必清光直一钱。"]},{"t":"七夕后一夜月中露坐二首 其一","f":"七言律诗","c":["火云散作郁金云，檐际移床偃病身。","古井石崖新汲水，花洲苔砌荡晴尘。","风才小动即停吹，竹自不凉那及人。","独感今宵上弦月，桂梢分露滴纱巾。"]},{"t":"七字敬饯周彦敷府判直阁之官虎城","f":"七言律诗","c":["碧落仙人出作州，青原诗伯佐承流。","江山得助催新句，风月平分入胜游。","清献濂溪两宾主，崆峒章贡再赓酬。","旧时绿水红莲客，南望旗幢鬓已秋。"]},{"t":"七字谢绍兴帅丘宗卿惠杨梅二首 其二","f":"七言律诗","c":["越绝诸杨盛一时，与侬瓜葛不曾知。","老夫自笑吾衰矣，此客何从梦见之。","也解过江寻德祖，政缘作尹是丘迟。","渠伊不是南村派，未分先驱事荔支。"]},{"t":"七字谢绍兴帅丘宗卿惠杨梅二首 其一","f":"七言律诗","c":["梅出稽山世少双，情知风味胜他杨。","玉肌半醉红生粟，墨晕微深染紫裳。","火齐堆盘珠径寸，醴泉绕齿柘为浆。","故人解寄吾家果，未变蓬莱阁下香。"]},{"t":"九日即事呈尤延之","f":"七言律诗","c":["昨日茱萸未苦香，今朝篱菊顿然黄。","浮英泛蕊多多著，旧酒新醅细细尝。","节里且追千载事，鬓边管得几茎霜。","正冠落帽都儿态，自笑狂夫老不狂。"]},{"t":"九日都下黄雀食新","f":"五言律诗","c":["九日新霜薄，群飞一网遮。","裘披杨柳絮，色染木犀花。","下箸欣乡味，知侬忆故家。","金杯浮菊蕊，相映两光华。"]},{"t":"九月一日夜宿盈川市","f":"七言律诗","c":["下滩一日抵三程，到得盈川也发更。","两岸渔樵稍灯火，满江风露更波声。","病身只合山间老，半世长怀客里情。","西畔大星如玉李，伴人不睡向人明。"]},{"t":"九日菊未花","f":"七言律诗","c":["旧说黄杨厄闰年，今年并厄菊花天。","但挼青蕊浮新酒，何必黄金铸小钱。","半醉嚼香霜月底，一枝却老鬓丝边。","阿谁会得开迟意，暗展重阳十月前。"]},{"t":"二月十三日谒西庙早起","f":"七言律诗","c":["起来洗面更焚香，粥罢东窗未肯光。","古语旧传春夜短，漏声新觉五更长。","近来事事都无味，老去波波有底忙。","还忆山居桃李晓，酴醾为枕睡为乡。"]},{"t":"二月望日递宿南宫和尤延之右司郎署疏竹之韵","f":"七言律诗","c":["此君见我眼犹青，笑我吟髭雪点成。","忆昔与君同舍日，听渠将雨作秋声。","夜来递宿三更悄，叶底春寒一倍生。","梦入故园数新笋，穿篱破藓几茎茎。"]},{"t":"入弋阳界道旁两石山一曰芦山绝妙一曰石人峰次焉上有一石起立如人形云","f":"五言律诗","c":["一色将苍玉，双堆作假山。","峰峦妙天下，花草半岩间。","旧瘦天风骨，新晞雨髻鬟。","何人缘底恨，化石立孱颜。"]},{"t":"入玉山七里头","f":"七言律诗","c":["诸村不雨数旬馀，此地濒江万宝苏。","晚紫豆花初总角，早黄稻穗已长须。","回头金步野径远，当面玉山秋塔孤。","偶见年时解船处，客愁依旧挂菰蒲。"]},{"t":"入建平界二首 其二","f":"七言律诗","c":["一岁升平在一收，今年田父又无愁。","接天稻穗黄娇日，照水蓼花红滴秋。","风有炎凉才顷刻，雨无朝暮政滂流。","浪言出却金陵界，入却庐陵界始休。"]},{"t":"入建平界二首 其一","f":"七言律诗","c":["溧水南头接建平，丫头儿子便勤耕。","疏麻大豆已前辈，荞麦晚菘初后生。","席卷千山为一囿，天怜春种赐秋成。","不如老圃今真个，樊子何曾透圣扃。"]},{"t":"入浮梁界","f":"五言律诗","c":["湿日云间淡，晴峰雨后鲜。","水吞堤柳膝，麦到野童肩。","沤漩嬉浮叶，炊烟倒入船。","顺流风更顺，只道不双全。"]},{"t":"入溧水界阅堠子","f":"五言律诗","c":["才入溧水界，休教勤吏民。","是谁差堠子，久立待车尘。","苔藓今仍古，风霜秋复春。","不知双与只，迎送几行人。"]},{"t":"八月朔晓起趣办行李","f":"五言律诗","c":["雨后晨先起，花间湿也行。","破除婪尾暑，领略打头清。","蠹果无迟落，枯枝忽再荣。","便须秣吾马，及此半阴晴。"]},{"t":"十一月朔早起","f":"七言律诗","c":["抛笏投簪四见秋，宦情世味两俱休。","尘随日影穿窗喜，叶卷风声刮地愁。","文武自匀香底火，圣贤教带老时篘。","夜来富贵非人世，梦钓沧浪雪满舟。"]},{"t":"十二月二十一日迎春","f":"七言律诗","c":["星淡孤萤月一梳，迎春早起正愁予。","土牛只解催人老，春气自来何事渠。","官柳野梅残雪后，金幡玉胜晓光初。","却思归跨春山犊，茧栗仍将挂汉书。"]},{"t":"十二月二十七日立春夜不寐","f":"七言律诗","c":["冬夜嫌长只望春，春宵又永更何言。","睫梢强合终无睡，脚底相摩也不温。","竟夕松风听到晓，忽明灯火看来昏。","拥裯却起蒙头坐，顾影真成一病猿。"]},{"t":"十五日明发石口遇顺风","f":"七言律诗","c":["溯流浅水刺楼船，百棹千篙祇不前。","一夜波声喧到晓，北风气力欲翻天。","挂帆未了青泥过，转眼相将玉笥边。","无数小舟俱在后，追侬不及指为仙。"]},{"t":"十六日夜再同子文巨济李叔粲南溪步月","f":"七言律诗","c":["际晚溪游暮欲归，追凉逐胜却成迟。","月如醉眼生红晕，山作愁眉带淡姿。","天下无人闲似我，秋边有句说从谁。","弟兄一再更相送，行到更深笑不知。"]},{"t":"十月久雨妨农收二十八日得霜遂晴喜而赋之","f":"五言律诗","c":["雨脚麻相似，禾头耳欲生。","风收白痴雾，霜作上牢晴。","逗晓双栖鹊，巡檐数喜声。","呼儿洗尘甑，忍饿待新粳。"]},{"t":"又和见喜病间","f":"七言律诗","c":["初病杨花犹乱飞，即今梅子已黄稀。","卧惊节物遽如许，起得沉绵更解肥。","云寺耶溪招布袜，斜风细雨欠蓑衣。","半生不结脩门梦，只梦家山唤早归。"]},{"t":"又和春雨","f":"七言律诗","c":["向来一旱鬓成丝，敢道新年雨脚垂。","未必催诗真强管，端令学稼失愁思。","只今且莫倾三峡，此后时须示一犁。","未爱少陵红湿句，可人却是道知时。"]},{"t":"又追和功父病起寄谢之韵","f":"七言律诗","c":["霜何曾傍绣帘寒，酒不能令客脸丹。","勤向竹炉温手脚，懒寻铜镜正衣冠。","无人孤坐月将落，拥鼻清吟夜向阑。","忽忆约斋诗债在，自吹灯火起来看。"]},{"t":"又跋东坡太白瀑布诗示开先序禅师","f":"七言律诗","c":["东坡太白两诗翁，诗到庐山笔更锋。","倒挂银河分一派，擘开玉峡出双龙。","天孙织锦机全别，仙子裁云手自缝。","界破青山安用洗，涴它瀑布却愁侬。"]},{"t":"又题郑店立春后一日","f":"五言律诗","c":["石壁仍丛竹，江亭更小楼。","滩声清客梦，灯影动诗愁。","春日已虚过，元宵看又休。","谁令不行乐，蹙破两眉头。"]},{"t":"三月一日过摩舍那滩阻雨泊清溪镇二首 其二","f":"七言律诗","c":["过尽危滩百不堪，忽惊绝壁翠巉巉。","倒垂不死千年树，下拂奔流万丈潭。","隔岸数峰如笔格，倚天一色染春蓝。","真阳此去无多子，到日应逢三月三。"]},{"t":"三月一日过摩舍那滩阻雨泊清溪镇二首 其一","f":"七言律诗","c":["一声霹雳霁光收，急泊荒茅野渡头。","摩舍那滩冲石过，曼陀罗影漾江流。","山才入眼云遮断，船欲追程雨见留。","夜宿清溪望清远，举头不见隔英州。"]},{"t":"三月二十六殿试进士待罪集英殿门二首 其二","f":"七言律诗","c":["九虎遮藏造化机，御题过午始闻知。","乾坤阖辟兼文武，云汉昭回具训词。","武帝上嘉真戏耳，放勋清问政如斯。","诸儒莫作公孙子，千载何曾遇圣时。"]},{"t":"三月二十六殿试进士待罪集英殿门二首 其一","f":"七言律诗","c":["金戺瑶阶日月边，晓风花柳带非烟。","千官剑佩鸣双阙，万国英豪到九天。","玉座忽临黄伞正，御题初出紫衣传。","小臣何幸陪诸老，待罪重来十六年。"]},{"t":"三花斛三首 其二 水仙","f":"七言律诗","c":["生来体弱不禁风，匹似蘋花较小丰。","脑子醲薰众香国，江妃寒损水精宫。","银台金盏谈何俗，矾弟梅兄品未公。","寄语金华老仙伯，凌波仙子更凌空。"]},{"t":"三花斛三首 其三 兰花","f":"七言律诗","c":["雪径偷开浅碧花，冰根乱吐小红芽。","生无桃李春风面，名在山林处士家。","政坐国香到朝市，不容霜节老云霞。","江蓠圃蕙非吾耦，付与骚人定等差。"]},{"t":"三花斛三首 其一 瑞香","f":"七言律诗","c":["侵雪开花雪不侵，开时色浅未开深。","碧团栾里笋成束，紫蓓蕾中香满襟。","别派近传庐阜顶，孤芳元自洞庭心。","诗人自有薰笼锦，不用衣篝炷水沉。"]},{"t":"上巳前一日欲雨复晴","f":"七言律诗","c":["去年上巳政南来，明日初三忽又催。","雨压云头浑欲落，风翻日脚急吹开。","莫因岭外无花卉，便对春光废酒杯。","只拣茂林脩竹处，兰亭禊事足追回。"]},{"t":"上巳寒食同日后圃行散","f":"七言律诗","c":["百五重三并一朝，风光不怕不娇饶。","鹿葱引道心犹卷，杨柳应门手对招。","筇未唤随非是强，扇聊作伴不须摇。","先生道是无歌舞，花劝莺酬酒自销。"]},{"t":"上元前大雪即晴","f":"七言律诗","c":["腊前三白已奇绝，年后六花仍作团。","才定忽斜偏有思，欲消还冻不胜寒。","且留大地万银屋，要伴青天孤玉盘。","今岁上元君记取，红灯白月雪中看。"]},{"t":"上章休致奉诏不允感恩书怀","f":"五言律诗","c":["纳禄惟愁晚，蒙恩未听辞。","猖狂思再渎，感恋独多时。","但有花开日，无非饮醉时。","白头何所用，满与插花枝。"]},{"t":"下元日诣会庆节所道场呈余处恭尚书","f":"七言律诗","c":["琳宫朝谒早追趋，漏尽铜壶杀点初。","半缕碧云横界月，一规银镜裂成梳。","自拈沉水祈天寿，散作非烟满玉虚。","已被新寒欺病骨，柳阴偏隔日光疏。"]},{"t":"与长孺共读东坡诗前用唐律后用进退格 其二","f":"七言律诗","c":["枉看平生多少书，分明便是蠹书鱼。","万签过眼还休去，一字经心恰似无。","急读何如徐读妙，共看更胜独看渠。","曲生冷笑仍相劝，惜取残零觅句须。"]},{"t":"与长孺共读东坡诗前用唐律后用进退格 其一","f":"七言律诗","c":["急性平生不少徐，读书不喜喜观书。","十行俱下未心醒，两目顿昏还月馀。","偶与儿曹翻故纸，共看诗句煮春蔬。","问来却是东坡集，久别相逢味胜初。"]},{"t":"与长孺共读杜诗","f":"七言律诗","c":["病身兀兀脑岑岑，偶到儿曹文字林。","一卷杜诗揉欲烂，两人齐读味初深。","斲肝枉却期千载，漏眼谁曾更再寻。","笔底奸雄死犹毒，莫将饶舌泄渠心。"]},{"t":"与侯子云溪上晚步","f":"七言律诗","c":["人入溪园自掩门，溪流新落两三痕。","杖藜紫菊霜风径，送眼丹枫夕照村。","行住忽然忘近远，阴晴未肯定寒暄。","多时不出今聊出，牧子樵儿一笑喧。"]},{"t":"久雨妨于农收因访子上有叹","f":"七言律诗","c":["君能过我意殊倾，我每看君脚便轻。","若为泥涂断还往，端令老病底心情。","未霜杨柳秋犹碧，既雨芙蓉晚更明。","旱岁嫌晴不嫌熟，今年教熟不教晴。"]},{"t":"之永和小憩资寿寺","f":"五言律诗","c":["石子密铺径，竹茎疏作行。","不缘憩驺仆，几失此山房。","佛像看都好，林花静自香。","未须清兴尽，归更借僧床。"]},{"t":"千叶水仙花","f":"七言律诗","c":["薤叶葱根两不差，重蕤风味独清嘉。","薄揉肪玉围金钿，浅染鹅黄剩素纱。","台盏元非千叶种，丰容要是小莲花。","向来山谷相看日，知是它家是当家。"]},{"t":"小箬舟中望月","f":"七言律诗","c":["偶于古柳系春船，云放千峰月满川。","跳入广寒宫里坐，下看碧玉镜中天。","斯须万象都成雪，遮莫三更且未眠。","归到金陵入官府，梦中说梦也无缘。"]},{"t":"小箬岭望见灵山","f":"七言律诗","c":["青鞋紫陌倦黄埃，送眼灵山一快哉。","碧玉熏炉天半立，青莲花萼雾中开。","宿云准拟偷将去，晓日殷勤唤出来。","欲琢新诗镵绝壁，梯空上去御风回。"]},{"t":"山丹花","f":"七言律诗","c":["春去无芳可得寻，山丹最晚出云林。","柿红一色明罗袖，金粉群虫集宝簪。","花似鹿葱还耐久，叶如芍药不多深。","青泥瓦斛移山蘤，聊著书窗伴小吟。"]},{"t":"山村二首 其二","f":"七言律诗","c":["歇处何防更歇些，宿头未到日头斜。","风烟绿水青山国，篱落紫茄黄豆家。","雨足一年生事了，我行三日去程赊。","老夫不是如今错，初识陶泓计已差。"]},{"t":"山村二首 其一","f":"七言律诗","c":["一搭山村一搭奇，不堪风物索新诗。","稻花雪白糁柳絮，柘子猩红团荔枝。","行者自愁居者乐，晴时即热雨时泥。","问知桐汭多程在，未说宣城与贵池。"]},{"t":"山居","f":"五言律诗","c":["鬓秃犹云少，书多却道穷。","柴门疏竹处，茅屋万山中。","幽梦时能忆，闲题底要工。","不知蝉报夏，为复自吟风。"]},{"t":"山茶","f":"七言律诗","c":["树子团团映碧岑，初看唤作木犀林。","谁将金粟银丝脍，簇饤朱红菜椀心。","春早横招桃李妒，岁寒不受雪霜侵。","题诗毕竟输坡老，叶厚有棱花色深。"]},{"t":"己丑上元后晚望","f":"五言律诗","c":["雪里晴偏好，寒馀暖尚轻。","山烟春自起，野烧暮方明。","又是元宵过，端令病骨惊。","遣愁聊觅句，得句却愁生。"]},{"t":"已过胥口将近钓台","f":"五言律诗","c":["睡起衣襟乱，头巾百摺痕。","帆端风色紧，船底水声喧。","胥口冤馀浪，严滩钓处村。","因行还访古，故老莫能言。"]},{"t":"马郎中母蒋夫人挽章","f":"五言律诗","c":["文物馀三径，芝兰秀五常。","鱼轩来粉省，象服去黄堂。","此母今谁似，清名死不亡。","一生令吏部，废却蓼莪章。"]},{"t":"不寐四首 其四","f":"七言律诗","c":["初闻一犬两犬声，次第远近鸡都鸣。","今夕明朝何日了，南村北巷几人行。","忽思春雨宿茅店，最苦仆夫催去程。","是时懒起惜残睡，如今不眠愁独醒。"]},{"t":"不寐四首 其三","f":"七言律诗","c":["暗虫夜啼不肯停，直从黄昏啼到明。","不知讨论底事著，为复怨嗟谁子生。","至竟通宵千万语，真实只是两三声。","唧唧唧唧复唧唧，此外何言君试听。"]},{"t":"不寐四首 其二","f":"七言律诗","c":["非关枕上爱哦诗，聊复销愁片子时。","老眼强眠终不梦，空肠暗响诉长饥。","翻来覆去体都痛，乍暗忽明灯为谁。","只道昼长无那著，夜长难奈不曾知。"]},{"t":"不寐四首 其一","f":"七言律诗","c":["老来只愿酒难醒，酒力才醒梦便惊。","露滴新寒欺病骨，宦游如梦记平生。","深山五鼓鸡吹角，落月一窗鹅打更。","等待晓光雕好句，晓光未白句先成。"]},{"t":"中元日午","f":"七言律诗","c":["雨馀赤日尚如炊，亭午青阴不肯移。","蜂过无花绝粮道，蚁行有水遏归师。","今朝道是中元节，天气过于初伏时。","小圃追凉还得热，焚香清坐读唐诗。"]},{"t":"中元前贺余处恭尚书祷雨沛然沾足","f":"七言律诗","c":["数点飘萧供晚清，二更倾泻到天明。","雷驱云气如旋磨，雨遍山村却入城。","簟面顿无秋后暑，檐牙最爱梦中声。","尚书幸有为霖手，偏洒江东作么生。"]},{"t":"中秋与诸子果饮","f":"七言律诗","c":["几年今夕一番逢，千古何人此兴同。","酒入银河波底月，笛吹玉桂树梢风。","莫言秋色无多巧，净洗清光也费工。","老子病来浑不饮，如何频报绿尊空。"]},{"t":"中秋无月至十七日晓晴","f":"七言律诗","c":["劣到中秋云便兴，中秋过了却成晴。","雾横平野村村白，日上疏林叶叶明。","岁事不应如许早，朝来已觉嫩寒生。","春吟不似秋吟好，觅句新来分外清。"]},{"t":"中秋后一夕登清心阁二首 其二","f":"五言律诗","c":["秋夜真成昼，西山却在东。","吹高半轮月，正赖一襟风。","清景今年过，何人此兴同。","青天忽成纸，似欲借诗翁。"]},{"t":"中秋后一夕登清心阁二首 其一","f":"五言律诗","c":["昨夜云为祟，今宵月始妍。","如何一日隔，便减半分圆。","影里偏宜竹，光中不剩天。","客来休遣去，我醉正无眠。"]},{"t":"中秋雨过月出","f":"七言律诗","c":["欲遣清风扫乱云，先将一雨净游尘。","今年大作中秋事，月色何孤我辈人。","照却八方还剩在，看来千古许清新。","不眠不惜明朝补，报答孤光醉是真。"]},{"t":"中秋前一夕玩月","f":"五言律诗","c":["月拟来宵好，吾先今夕遭。","才升半壁许，已复一轮高。","迁坐明相就，群飞影得逃。","望秋惟有此，彻夜敢辞劳。"]},{"t":"中秋前一夕雨中登双溪叠嶂已而月出二首 其二","f":"七言律诗","c":["双溪叠嶂旧知名，投老初登眼不醒。","一雨飞来四天黑，乱云遮断万峰青。","急呼月色开秋色，夺得昭亭与敬亭。","自笑诗翁犹狡狯，不饶山鬼弄精灵。"]},{"t":"中秋前一夕雨中登双溪叠嶂已而月出二首 其一","f":"七言律诗","c":["州在三峰最上头，上头高处更高楼。","都将万壑千岩景，堆作双溪叠嶂秋。","晚雨才收山尽出，暮天似水月如流。","敬亭堪喜还堪恨，领得风光揽得愁。"]},{"t":"中秋前一夕携酒与子仁侄登多稼亭","f":"七言律诗","c":["月忽飞来堕我傍，我还飞入月中央。","如何桂树许多影，不隔冰轮些子光。","自古中秋多苦事，非风即雨断人肠。","醉来不信寒欺酒，露湿杯盘冻作霜。"]},{"t":"中秋前两日别刘彦纯彭仲庄于白马山下","f":"七言律诗","c":["匆匆离合梦非梦，续续谈谐眠不眠。","莫道对床容易著，试思分手几何年。","长亭更放金荷浅，后夜谁同璧月圆。","要得长随二三友，不知由我定由天。"]},{"t":"中秋病中不饮二首后一首用辘轳体 其二","f":"七言律诗","c":["无风无雨并无云，今岁中秋尽十分。","毕竟冰轮谁为转，碾穿玉宇不生痕。","坐看儿辈纷然饮，也遣先生半欲醺。","自是清樽负明月，不关明月负清樽。"]},{"t":"中秋病中不饮二首后一首用辘轳体 其一","f":"七言律诗","c":["去年两浙浙西州，今夕南溪溪上头。","满著玻瓈一盆水，洗开玉镜十分秋。","病来不饮非无酒，老去追驩总是愁。","自笑独醒仍苦咏，枯肠雷转不禁搜。"]},{"t":"丰山小憩","f":"五言律诗","c":["归路元无远，行人倦自迟。","野香寒蝶聚，秋色老枫知。","得得逢清荫，休休憩片时。","江山岂无意，邀我觅新诗。"]},{"t":"为王监簿先生求近诗","f":"七言律诗","c":["林下诗中第一仙，西风吹到日轮边。","杜陵野客还惊市，国子先生小著鞭。","拈出老谋开宇宙，本来清尚只云泉。","新篇未许儿童诵，但得真传敢浪传。"]},{"t":"书黄庐陵伯庸诗卷","f":"七言律诗","c":["句法何曾问外人，单传山谷当家春。","截来云锦花无样，倒写珠胎海亦贫。","汗竹香中翻墨汁，扶桑梢上挂头巾。","诗名官职看双美，向道儒冠不误身。"]},{"t":"五月一日过贵溪舟中苦热","f":"七言律诗","c":["半月阴凉天气佳，今朝新暑不饶些。","一生怕热长逢热，千里还家未到家。","入却船来那得出，恰方日午几时斜。","劝君莫爱高官职，行路难时却怨嗟。"]},{"t":"五更入宣城诣天庆观朝谒","f":"五言律诗","c":["晓雾双溪水，秋风百舫桥。","行穿子城过，却望女墙遥。","落月能相伴，疏钟似见招。","小亭憩山半，换马上岧峣。"]},{"t":"从丁家洲避风行小港出荻港大江三首 其三","f":"七言律诗","c":["芦挥麈尾话清秋，柳弄腰支舞绿洲。","引得江风颠入骨，戏抛波浪过于楼。","十程拟作一程快，一日翻成十日留。","未到大江愁未到，大江到了更添愁。"]},{"t":"从丁家洲避风行小港出荻港大江三首 其二","f":"七言律诗","c":["荻篱萧洒织来新，茅屋横斜画不真。","乾地种禾那用水，湿芦经火自成薪。","岛居莫笑三百里，菜把活它千万人。","白浪打天风动地，何曾惊著一微尘。"]},{"t":"从丁家洲避风行小港出荻港大江三首 其一","f":"七言律诗","c":["蓼岸藤湾隔尽人，大江小汊绕成轮。","围蔬放荻不争地，种柳坚堤非买春。","匏瓠放教俱上屋，渔樵相倚自成邻。","夜来更下西风雪，荞麦梢头万玉尘。"]},{"t":"从范至能参政游石湖精舍坐间走笔二首 其二","f":"五言律诗","c":["震泽分波入，垂虹隔水看。","何须小风起，生怕牡丹寒。","政坐诸峰好，端令落笔难。","催人理归棹，落日许无端。"]},{"t":"从范至能参政游石湖精舍坐间走笔二首 其一","f":"五言律诗","c":["孤塔鸥边迥，千岩镜里看。","折花倩人插，摘叶护窗寒。","不是无相识，相从却是难。","归舟望精舍，已在白云端。"]},{"t":"从提举黄元章登齐山寺后上清岩翠微亭望郡城左清溪右大江盖绝境云","f":"七言律诗","c":["西山落日浴长江，并贯清溪作一光。","千嶂围来天四合，孤城涌出水中央。","楼台玉塔云间见，杨柳金堤镜里长。","客子要穷秋浦眼，翠微亭上上清旁。"]},{"t":"以六一泉煮双井茶","f":"七言律诗","c":["鹰爪新茶蟹眼汤，松风鸣雪兔毫霜。","细参六一泉中味，故有涪翁句子香。","日铸建溪当退舍，落霞秋水梦还乡。","何时归上滕王阁，自看风炉自煮尝。"]},{"t":"以糟蟹洞庭甘送丁端叔端叔有诗因和其韵","f":"七言律诗","c":["斗州只解寄鹅毛，鼎肉何曾馈百牢。","驱使木奴供露颗，催科郭索献霜螯。","乡封万户只名醉，天作一丘都是糟。","却被新诗太清绝，唤将雪虐更风饕。"]},{"t":"元日癸卯占云大熟","f":"五言律诗","c":["造物今年印，司花昨夜交。","雪留芦荻脚，日到瑞香梢。","白叟占嘉应，青精看满抄。","游丝也驩喜，不住舞蟏蛸。"]},{"t":"六月二十四日病起喜雨闻莺与大儿议秋凉一出游山三首 其三","f":"七言律诗","c":["暑气朝来扫地空，南风毕竟让西风。","秋生楚尾吴头外，凉杀天涯地角中。","万叠山连千涧水，双行缠伴一郫筒。","初程道是穷忙著，且宿东山东复东。"]},{"t":"六月二十四日病起喜雨闻莺与大儿议秋凉一出游山三首 其二","f":"七言律诗","c":["病势初来敌颇强，排山倒海也难当。","老夫笑把东西玉，竖子难藏上下肓。","酒阵时闻报三捷，诗坛元不费单枪。","夜来梦入清凉国，风月冰人别是乡。"]},{"t":"六月二十四日病起喜雨闻莺与大儿议秋凉一出游山三首 其一","f":"七言律诗","c":["末伏将催中伏休，匆匆送夏又迎秋。","暑中竹色风仍雨，病里莺声喜破愁。","大熟十年无此作，微生一饱更何求。","急须剩踏莲花曲，药玉新船待拍浮。"]},{"t":"六月十八日立秋送客夜归雨作","f":"七言律诗","c":["青天赤日更黄埃，迎送纷纷正往来。","一夜炎蒸无计奈，三更风雨领秋回。","人生作么禁寒暑，世事何如付酒杯。","遮莫髯间点霜雪，何曾笔下减琼瑰。"]},{"t":"六月将晦夜出凝归门","f":"七言律诗","c":["暑里街头可久停，今宵无月也宵征。","一天星点明归路，十里荷香送出城。","山轿声声柔橹紧，葛衣眼眼野风清。","五更月出还家了，不早相期作伴行。"]},{"t":"午过乌东","f":"五言律诗","c":["险尽涂初坦，寒轻日向中。","稻云迟雨碧，荞雪早霜红。","五日再行役，二年三鞠躬。","只言弃官久，却与在官同。"]},{"t":"午热憩忠义渡","f":"七言律诗","c":["秋阳嗔我紧追程，急泊临流一短亭。","摘索风巾些子倦，苍茫水枕霎时醒。","单牌双堠头都白，万壑千岩眼强青。","不及溪边老亭父，一生卧护竹窗棂。"]},{"t":"午睡起","f":"五言律诗","c":["过雨馀秋暑，移床拣午凉。","小风吹醉面，凛气忽如霜。","日脚何曾动，桐阴有底忙。","倦来聊作睡，睡起更苍茫。"]},{"t":"午憩方虚坐睡","f":"五言律诗","c":["午暑残偏力，长亭歇未行。","睡乡蝇俶扰，诗阵笔专征。","今夕南吾枕，何时北我旌。","不应菊花酒，儿女不同倾。"]},{"t":"午憩堆钱岭","f":"五言律诗","c":["蚤作难为饭，前途又苦饥。","尘劳正未了，眠食且随宜。","小憩那思去，追程得更迟。","馆人只冷眼，还为惜奔驰。"]},{"t":"午憩褚家方清风亭二首 其二","f":"五言律诗","c":["莫道迎春好，迎春是送春。","可怜一条路，知老几多人。","坦绿偏宜袜，飘红并可絪。","青帘好消息，今日榨头新。"]},{"t":"午憩褚家方清风亭二首 其一","f":"五言律诗","c":["此老忒疏放，与春无怨私。","何须寒食日，恰是别家时。","荒店两三只，野花千万枝。","前山有底恨，也学客间眉。"]},{"t":"壬寅岁朝发石塔寺","f":"七言律诗","c":["晓钟梦裹苦相呼，强裹乌纱照白须。","只有铜炉烧柏子，更无玉盏泻屠酥。","佛桑解吐四时艳，铁树还如九节蒲。","省得一朝疲造请，却教终日走长涂。"]},{"t":"太令人田氏挽辞二首 其二","f":"五言律诗","c":["家食初偕隐，君羹晚得尝。","金花千轴告，玉树五枝香。","咫尺相山室，葱昽瓦庙冈。","真令淮水绝，依旧庆源长。"]},{"t":"太令人田氏挽辞二首 其一","f":"五言律诗","c":["天竺琼为岫，西湖锦作春。","轻轩过微雨，小宰太夫人。","游览年年好，恩封日日新。","如何君氏赗，忽费水衡银。"]},{"t":"太宁郡夫人张氏挽词二首 其二","f":"五言律诗","c":["我忆定斋老，壶觞父子间。","西湖梅半落，东馆月初弯。","俄顷王姑酒，嵚岑杜母山。","升堂迟一拜，作诔费频删。"]},{"t":"太宁郡夫人张氏挽词二首 其一","f":"五言律诗","c":["盖世金瓯谱，传家象笏囊。","藁砧八叶相，桂子一枝香。","葱岭参西学，兰陔掩北堂。","能诗饱经史，个是女班扬。"]},{"t":"引见前一夕寓宿徐元达小楼元达招符君俞胡季永小集走笔和君俞韵","f":"七言律诗","c":["主宾呼酒卷沧溟，我亦何人与德星。","高阁连云压潮白，前山倒影入杯青。","细哦秀句清无底，匹似疏梅寒更馨。","不惜坐间作颓玉，只愁宫漏又须听。"]},{"t":"文远叔挽词","f":"五言律诗","c":["气爽尘埃外，川行翰墨间。","匆匆未白首，去去忽青山。","琴在弦安用，人亡鹤不还。","竹林有前约，欲语泪先潸。"]},{"t":"方虚日斜再行宿乌山二首 其二","f":"五言律诗","c":["多稼村村过，垂杨店店迎。","偶然逢客子，问得好山名。","投宿欣犹早，斜阳落更明。","仆人休进扇，得似晚风清。"]},{"t":"方虚日斜再行宿乌山二首 其一","f":"五言律诗","c":["日已衰容去，风仍劈面来。","征徒歇得醒，老子不须催。","绿荫凉过伞，黄泥晒作埃。","欣然片云起，半霎又吹开。"]},{"t":"月下果饮七首 其一","f":"五言律诗","c":["恰则天方暮，如何月正中。","一年无此热，今夕绝无风。","早藕凝松雪，新菱剥酽红。","醉乡堪避暑，只合著衰翁。"]},{"t":"月下闻笛","f":"五言律诗","c":["天色镕成水，蟾光鍊出银。","碧香三酌半，玉笛一声新。","小婉还清壮，多欢忽苦辛。","何人传此曲，此曲怨何人。"]},{"t":"月台夜坐二首 其二","f":"五言律诗","c":["日落片时许，星才数点明。","须臾玉棋子，遍满碧瑶枰。","向晚垂垂雨，通宵得得晴。","秋蛩伴侬语，苦底是谁声。"]},{"t":"月台夜坐二首 其一","f":"五言律诗","c":["秋日非无热，秋宵至竟清。","老夫连数夕，露坐到三更。","风急星明灭，云行月送迎。","追驩追不得，驩却偶然成。"]},{"t":"月夜阻风泊舟太湖石塘南头四首 其四","f":"七言律诗","c":["新年乘兴看春风，来过垂虹东复东。","谁有工夫寒夜底，独寻水月五湖中。","今宵顿觉乾坤大，下笔惟愁造化穷。","太白青山谢公海，可怜一笑偶然同。"]},{"t":"月夜阻风泊舟太湖石塘南头四首 其三","f":"七言律诗","c":["过湖未得匹如闲，何幸湖心泊画船。","宇宙中间都是月，波涛外面更无天。","谁知造物将奇观，不与伧人付谪仙。","管领渠侬无一物，镂冰剪雪作新篇。"]},{"t":"月夜阻风泊舟太湖石塘南头四首 其二","f":"七言律诗","c":["动地颠风政打头，吴江未到且维舟。","五湖波起众山动，一片月明千里愁。","且更放迟些子睡，看它盛怒几时休。","阳侯要与诗人敌，未必诗人输一筹。"]},{"t":"月夜阻风泊舟太湖石塘南头四首 其一","f":"七言律诗","c":["到得松江每不欣，何曾晴快遇清真。","此行作意追胜境，入夜阻风还闷人。","万里青天一轮月，三更雪浪太湖春。","若教白日来经此，不见新镕万顷银。"]},{"t":"木犀初发呈张功父","f":"七言律诗","c":["尘世何曾识桂林，花仙夜入广寒深。","移将天上众香国，寄在梢头一粟金。","露下风高月当户，梦回酒醒客闻砧。","诗情恼得浑无那，不为龙涎与水沈。"]},{"t":"又和六首 其六","f":"七言律诗","c":["帝城底里有山林，桂树团团烟雾深。","玉臂折来数枝月，银髯羞插满头金。","谈间千首有此客，空外一声何处砧。","酒亦销愁亦生病，不须不醉不须沉。"]},{"t":"又和六首 其五","f":"七言律诗","c":["老子江西有故林，万松围里桂花深。","忆曾风露飘寒粟，自领儿童拾落金。","割蜜旋将揉作饼，捣香须记不经砧。","一枝未觉秋光减，灯影相看万籁沈。"]},{"t":"又和六首 其四","f":"七言律诗","c":["约斋诗客坐诗林，派入江西彻底深。","缝雾裁云梭织锦，明堂清庙玉摐金。","已呼毛颖哦齑臼，更约姮娥聘槁砧。","细咏新来木犀句，一灯明灭夜沉沉。"]},{"t":"又和六首 其三","f":"七言律诗","c":["端能小脱簿书林，招唤诗流卜夜深。","老我愁隤半山玉，凭君浅酌一荷金。","水边赏桂秋围坐，雨后摘蔬香满砧。","乘醉却来湖上戏，手翻波月看浮沉。"]},{"t":"又和六首 其二","f":"七言律诗","c":["分得吴刚斫处林，鹅儿酒色不须深。","系从犀首名干木，派别黄香字子金。","衣溅蔷薇兼水麝，韵如月杵应霜砧。","馀芬薰入旃檀骨，从此人间有桂沈。"]},{"t":"又和六首 其一","f":"七言律诗","c":["诗人家在木犀林，万顷湖光一径深。","夹路两行森翠盖，西风半夜散麸金。","邀宾把酒香浮玉，擘水庖霜脍落砧。","掇取仙山入京洛，不妨冷眼看升沈。"]},{"t":"水西野店皆不著宿夜抵石山虚","f":"五言律诗","c":["不著官人宿，无如野店何。","见容幸有此，虽陋更嫌它。","头虱妨归梦，邻鸡伴寤歌。","此生眠食尔，行路总蹉跎。"]},{"t":"王式之直阁不远千里来访野人赠以佳句次韵奉谢","f":"七言律诗","c":["君才陆海与潘江，句里芒寒万丈长。","雪椀冰瓯翻笔墨，锦机绣段出肝肠。","王家龙凤重英特，谢砌芝兰让耿光。","相国登庸衣钵在，郎君努力续前芳。"]},{"t":"王龟龄挽词","f":"五言律诗","c":["佛以偏师胜，天能一手回。","横空立万仞，不为作三魁。","道大身无著，人亡世却哀。","溪梅那解事，寂寞为谁开。"]},{"t":"见王宣子侍郎二首 其二","f":"五言律诗","c":["老去浑多难，愁来敢怨天。","生遭文字误，更结簿书缘。","苦忆悬间榻，难回雪后船。","三年才一见，百岁几三年。"]},{"t":"见王宣子侍郎二首 其一","f":"五言律诗","c":["不作伾文客，投闲可得辞。","高名真自累，了事竟成痴。","到底须良匠，非渠更阿谁。","莫嫌风雪恶，要试岁寒枝。"]},{"t":"见张钦夫二首 其二","f":"五言律诗","c":["不见所知久，有怀何许开。","百书终作恶，千里为渠来。","邹鲁期程远，风霜鬓发催。","不应师友地，只么遣空回。"]},{"t":"见张钦夫二首 其一","f":"五言律诗","c":["克己今颜子，承家小吕申。","只愁无好手，不道欠斯人。","一别时飞几，重来事总新。","祥琴声尚苦，可更话酸辛。"]},{"t":"见周子充舍人叙怀","f":"七言律诗","c":["三年再谒一番逢，两舍相望几讯通。","便有好怀安得尽，不知造物底相穷。","公今贫贱庸非福，我更清愁恶似公。","误辱相期千载事，云泥政自未应同。"]},{"t":"见潭帅刘恭父舍人二首 其二","f":"五言律诗","c":["道合宁嫌晚，心期不用多。","于公犹未见，此恨独如何。","颇辱谈间问，端须雪里过。","门阑当欠士，许寄病身么。"]},{"t":"见潭帅刘恭父舍人二首 其一","f":"五言律诗","c":["云雾开衡岳，波涛息洞庭。","是邦谁岳牧，西掖一文星。","有眼难人物，斯人尚典刑。","如何闲处著，不遣肃朝廷。"]},{"t":"丘母太硕人臧氏挽诗二首 其二","f":"五言律诗","c":["共伯松楸后，宗文玉雪初。","吹灯躬夜绩，听子读残书。","帅阃方兰膳，王畿又版舆。","药成人不见，月里踏蟾蜍。"]},{"t":"丘母太硕人臧氏挽诗二首 其一","f":"五言律诗","c":["行乐潘慈母，荣封卫硕人。","金花五色诰，雨叶六番春。","白露凋萱惨，青山拱木新。","九龄真上寿，一子更名臣。"]},{"t":"丙申岁朝","f":"七言律诗","c":["椒盘又颂一年初，多拜犹欣未要扶。","山色长供青箬笠，春光不为白髭须。","仙家风土闲中是，岁后莺花较早无。","人事驰驱不须叹，倦来添得睡工夫。"]},{"t":"东寺诗僧照上人访予于普明寺赠以诗","f":"七言律诗","c":["故人深住白云隈，欲到何因只寄梅。","岁晚观山吾独立，泥中骑马子能来。","转头不觉三年别，病眼相看一笑开。","说似少陵真句法，未应言下更空回。"]},{"t":"东宫讲退触热入省倦甚小睡","f":"七言律诗","c":["承华下直直几廷，新暑醺人睡不成。","到得曲肱贪梦好，无端急雨打荷声。","起看翠盖如相戏，乱走明珠却细倾。","归路关心最凉处，水风四面一桥横。"]},{"t":"代书呈张功父","f":"五言律诗","c":["不见子张子，令人梦亦思。","只应依旧瘦，近作几多诗。","联句平生事，看花去岁时。","海棠今好不，传语并酴醾。"]},{"t":"代贺郊祀庆成二首 其一","f":"七言律诗","c":["圣主勤民岁自丰，德威怀远塞尘空。","郁金祼鬯周茅屋，瑄玉亲郊汉竹宫。","已刺六经新作制，却追三代与同风。","鸡竿更霈如天泽，殿柳宸梅雪正融。"]},{"t":"代贺郊祀庆成二首 其二","f":"七言律诗","c":["天为君王幸泰禋，飞雵疏雨净香尘。","金波玉李浮苍璧，风马云车降紫旻。","万宝丰年贞上瑞，八方和气蔼成春。","受釐未肯专宣室，鸿号还将寿两亲。"]},{"t":"冬至后贺皇太子及平阳郡王","f":"词","c":["长乐钟声搅梦惊，建章星影照人行。","千官灯语听残点，一夜霜寒在五更。","金钥玉?开北阙，银鞍丝控谒东明。","青宫朱邸环天极，五色祥云覆帝城。"]},{"t":"冬至称贺紫宸殿及德寿宫","f":"七言律诗","c":["宫烛奔忙下玉除，晨曦拂掠丽储胥。","东西班动云开合，警跸声来电卷舒。","隆准衣裳红一点，御香烟雾碧千庐。","勋华二圣天齐寿，亚岁年年贺帝居。"]},{"t":"冬至霜晴","f":"七言律诗","c":["油帘雪白日华红，老子良图策隽功。","自晒绵裘并衲裤，谁知衣桁是薰笼。","绝怜寒菊枯根底，留得残霜过日中。","旧说冬乾年定湿，试将今岁试南翁。"]},{"t":"冬暖","f":"七言律诗","c":["小春活脱是春时，霜熟风酣日上迟。","晚蝶频移猎残蕊，惊禽冲过倒垂枝。","暂闲何似长闲好，无事非关了事痴。","三径一筇人不见，假山以外菊花知。"]},{"t":"出北关门送李舍人使虏","f":"七言律诗","c":["同寮缓辔出承华，又送双星水北涯。","霜外汀洲芦叶晓，雪馀园圃竹梢斜。","只惊睡起犹残月，不觉归时已落霞。","白首鸳行徒索米，故山今日政梅花。"]},{"t":"出横山江口","f":"五言律诗","c":["白壁当江岸，青旗定酒家。","断崖侵屋窄，细路入门斜。","县近瞻双塔，洲横隔一沙。","何须后来客，如信此诗嘉。"]},{"t":"加餐","f":"五言律诗","c":["脱发星星遍，加餐日日新。","二升卧龙玉，一斗谪仙春。","云子恐称屈，曲生能笑人。","吾方有公事，公等不须嗔。"]},{"t":"北风","f":"五言律诗","c":["山雨无休歇，江云政郁葱。","如何急滩水，更著打头风。","草作伤心碧，花能可意红。","一年春好处，却在道涂中。"]},{"t":"去岁四月得淋疾今又四月病犹未愈","f":"五言律诗","c":["去岁四月病，如今一岁来。","越吟三百日，凉剂二千杯。","极痛过于割，通身总是灾。","花时久断酒，红药为谁开。"]},{"t":"发中桥二首 其二","f":"五言律诗","c":["新雨丰今岁，初晴屏积阴。","猛收千疋练，微露一棱金。","天熨粉青嫩，山描愁黛深。","谁言残剩暑，卓午不相寻。"]},{"t":"发中桥二首 其一","f":"五言律诗","c":["湿轿乘凉入，斜灯借路明。","柳欹元不倒，桥阔自多惊。","宿霤停残滴，朝曦放快晴。","溪流太无赖，不作一声声。"]},{"t":"发乌山入溧水县中山驿","f":"五言律诗","c":["雨脚依山见，风头触树回。","泥深行不去，轿兀睡还来。","栩栩情微适，喧喧眼竟开。","梦残那可续，续得转悠哉。"]},{"t":"发杨港渡入交石夹四首 其四","f":"五言律诗","c":["荻岸何时了，松舟几日停。","波来全蜀白，树去两淮青。","柔橹殊清响，征人自厌听。","不知谁子醉，垂手瞰江亭。"]},{"t":"发杨港渡入交石夹四首 其三","f":"五言律诗","c":["山断情相接，江同派暂分。","无风犹细浪，有日却轻云。","生熟衣中半，阴晴气两熏。","还家浑欲早，徐棹也堪欣。"]},{"t":"发杨港渡入交石夹四首 其二","f":"五言律诗","c":["入夹宽中窄，临流慢处深。","朝阳明众岫，西崦自多阴。","脱裤嗔人俭，提壶侑我斟。","老来除饮外，半点没春心。"]},{"t":"发杨港渡入交石夹四首 其一","f":"五言律诗","c":["朝雨匆匆霁，春山历历嘉。","老青交幼绿，暗锦出明花。","渔艇十数只，鸡声三五家。","人生须富贵，此辈亦生涯。"]},{"t":"发枫平","f":"五言律诗","c":["谷暗迷窗晓，山鸣报雨来。","畦丁绝须喜，菜甲正新栽。","倦路愁何那，冲泥惯岂才。","吾诗未大好，也辱片云催。"]},{"t":"发赵屯得风宿杨林池是日行二百里","f":"七言律诗","c":["动地风来觉地浮，拍天浪起带天流。","舞翻柳树知何喜，拜杀芦花未肯休。","两岸万山如走马，一帆千里送归舟。","出笼病鹤孤飞后，回首金笼始欲愁。"]},{"t":"发银树林","f":"七言律诗","c":["莫过溪桥银树林，溪深未抵路泥深。","清风一阵掠人面，晴色半开关客心。","远岭惹云秋里雪，淡天刷墨晓来阴。","几多好句争投我，柳夺花偷底处寻。"]},{"t":"祗召还京题江西道院","f":"七言律诗","c":["病身祇要早投闲，乞得高安政小安。","山水秋来浑是画，楼台高处自生寒。","登临未足还辞去，老大重来毕竟难。","碧落翠微好将息，清风明月梦中看。"]},{"t":"叶叔羽集同年九人于樱桃园钱袭明何同叔即席赋诗追和其韵二首 其二 和何同叔韵","f":"七言律诗","c":["天门金榜出槐宸，四海同年骨肉亲。","走马看花才几日，晓星残月半无人。","谈间平叔元如玉，句里司勋别有春。","欲把清新比梅雪，却愁梅雪未清新。"]},{"t":"叶叔羽集同年九人于樱桃园钱袭明何同叔即席赋诗追和其韵二首 其一 和钱袭明韵","f":"七言律诗","c":["八座能分一日光，题名犹记榜间黄。","看渠超出金闺彦，顾我曾为同舍郎。","高会九人寻水石，纵谈一笑间宫商。","越王孙子琼瑶句，细把重吟恐脱忘。"]},{"t":"叶教授镐乃翁致政一百三岁屡加封仍锡朱银取告命之词名其堂曰介寿","f":"五言律诗","c":["兰玉初攀桂，朱银降自天。","堂中有一老，物外百三年。","紫诰行充栋，霜毛尽满颠。","仁人元自寿，端不羡臞仙。"]},{"t":"四十九叔祖母朱氏孺人挽词","f":"五言律诗","c":["忆哭清湘掾，诸孤未裹头。","盛年能素节，凛气却清秋。","眼底生刍奠，身前汎柏舟。","无龄还有德，此母不应愁。"]},{"t":"四十二叔祖母刘氏太孺人挽词","f":"五言律诗","c":["夫人自七十，有母尚期颐。","不遣千山讣，犹应一病迟。","孝留天下口，身立女中师。","到得君羹美，翻令颍谷悲。"]},{"t":"四月八日尝新荔子","f":"七言律诗","c":["一点胭脂染蒂旁，忽然红遍绿衣裳。","紫琼骨骼丁香瘦，白雪肌肤午暑凉。","掌上冰丸那忍触，樽前风味独难忘。","老饕要啖三百颗，却怕甘寒冻断肠。"]},{"t":"四月十七日侍立集英殿观进士唱名","f":"七言律诗","c":["殿上胪传第一声，殿前拭目万人惊。","名登龙虎黄金榜，人在烟霄白玉京。","香满乾坤书一卷，风吹鬓发雪千茎。","旧时脱却银袍处，还望清光侍集英。"]},{"t":"四月五日车驾朝献景灵宫省前迎驾起居口号","f":"七言律诗","c":["凤辇云行露未销，鸾旗风动柳相高。","晴雷出地传清跸，霁日吹红染御袍。","喜见天颜浮玉藻，归从原庙荐樱桃。","小臣再得瞻黄伞，两鬓星星不满搔。"]},{"t":"四月四日午初出浙东界入信州永丰界","f":"五言律诗","c":["外面千峰合，中间一径通。","日光自摇水，天静本无风。","村酒渟春绿，林花倦午红。","莫欺山堠子，知我入江东。"]},{"t":"四更发青阳县西五里柯家店","f":"七言律诗","c":["轿中万兀路千萦，死尽村鸡无一鸣。","落月正明知未晓，暗泉甚远只闻声。","自缘客子行来早，岂是秋天不肯明。","午热未来先下店，却将昼睡补宵征。"]},{"t":"圣上闵雨遍祷未应下诏避殿减膳感叹赋之","f":"七言律诗","c":["夏旱焚如复入秋，圣皇避殿减琼羞。","数峰北峙云垂合，一阵西风雨又休。","逐日望霓穿却眼，何时倒海作奔流。","诸贤袖有为霖手，不泻天瓢洗主忧。"]},{"t":"圣恩增秩进职致仕感恩述怀","f":"七言律诗","c":["雨露丝纶下玉宸，问天乞得个闲身。","一生无恨长多感，三请归休恰四春。","手板抽还大丞相，安车悬示后来人。","从今万八百场醉，忽自称冤五柳巾。"]},{"t":"宁桥小渡","f":"五言律诗","c":["桥坏仍泥滑，舟横隔水呼。","岸头危径窄，轿子莫人扶。","午漏相将里，秋阳未肯无。","明知近前店，暗觉展脩途。"]},{"t":"平贼班师明发潮州","f":"七言律诗","c":["不是潢池赤白囊，何缘杖屦到潮阳。","官军已扫狐兔窟，归路莫孤山水乡。","便去罗浮参玉局，更登浴日折扶桑。","还家儿女搜行李，满袖云烟雪月香。"]},{"t":"归舟大雪中入运河过万家湖","f":"七言律诗","c":["雪漫水面淡模糊，酿出羔儿酒一壶。","已被膻腴翳醽醁，更添牛乳点春酥。","销金帐下有此否，药玉船中不用酤。","忽见琼缸清彻底，蒲萄一色万家湖。"]},{"t":"戊申元日立春题道山堂前梅花","f":"七言律诗","c":["今年元日不孤来，带领新春一并回。","夜雨初添石渠水，东风先入道山梅。","不妨数朵且微破，未要十分都尽开。","江路野香元自好，阿谁移取种蓬莱。"]},{"t":"未至安乐坊隔林望见霜铿岭两峰特奇","f":"七言律诗","c":["天知老子厌凡山，别放潜瑰伏宝看。","一行横林遮岭脚，两峰如笋出云端。","举头瞥见还惊遁，到骨清奇特地寒。","彼此相遭有缘法，悔将嗔喜触巑岏。"]},{"t":"未到丹徒二十里间见石翁石婆","f":"七言律诗","c":["诏许诗人江海游，丹徒初到晋徐州。","炉边旸谷日长昼，盏底醉乡天不秋。","六代兴亡何处问，一生奔走几时休。","石翁石媪霜前笑，管得南朝陵墓愁。"]},{"t":"正月十九日五更诣天庆观谢雪闻都下尺雪旬日而毗陵三四微雪而已","f":"七言律诗","c":["元宵风物又阑残，闭阁何曾出一看。","尚觉烛光欺病眼，旋添衣著试春寒。","中都尺雪逾旬许，此地飞花逐片乾。","不待珠宫香火了，海风吹上紫金盘。"]},{"t":"玉盘盂","f":"七言律诗","c":["旁招近侍自江都，两岁何曾见国姝。","看尽满栏红芍药，只消一朵玉盘盂。","水精淡白非真色，珠璧空明得似无。","欲比此花无可比，且云冰骨雪肌肤。"]},{"t":"田路泥行","f":"五言律诗","c":["路是新泥作，泥逢积雨滂。","如缘大鲇脊，更绕九羊肠。","前店看殊近，行人觉转长。","商量避五岭，辛苦恰相当。"]},{"t":"白沙买船晚至严州","f":"五言律诗","c":["重雾疑朝雨，斜阳竟晚晴。","万山江外尽，一塔岭尖明。","舟小宁嫌窄，途长已倦行。","子陵台下水，未酌意先清。"]},{"t":"石湾雨作得巩帅采若书约观灯","f":"七言律诗","c":["昨暮颠风浪打头，那知今日得安流。","元宵不为游人好，细雨先供客子愁。","病骨支离妨酒盏，诗仙招唤试灯毬。","书生薄命多磨折，乐事良辰判却休。"]},{"t":"石榴","f":"七言律诗","c":["深著红蓝染暑裳，琢成纹玳敌秋霜。","半含笑里清冰齿，忽绽吟边古锦囊。","雾縠作房珠作骨，水精为醴玉为浆。","刘郎不为文园渴，何苦星槎远取将。"]},{"t":"立春后一日和张功父园梅未花之韵","f":"七言律诗","c":["前夕三更月落时，东风已动万花知。","江梅端合先交割，春色如何未探支。","只欠梁溪冰柱句，追还和靖暗香诗。","张家剩有葱根指，不把琼酥滴一枝。"]},{"t":"立春前一夕二首 其一","f":"五言律诗","c":["春忽明朝是，冬将半夜非。","年华只不住，客子未能归。","微霰疏还密，寒檐滴又稀。","撚须真浪苦，呵笔更成挥。"]},{"t":"立春前一夕二首 其二","f":"五言律诗","c":["腊尽春还好，朝暄暮复寒。","雨晴终日异，衣著一冬难。","生菜知无分，残梅不用看。","本凭书遣睡，转更睡相干。"]},{"t":"立春新晴","f":"七言律诗","c":["宿云送腊晓仍开，日动江光度竹来。","春到更晴谁不喜，时迁不道老相催。","山村敢惜身犹远，边地应怜战未回。","春鸟岂知人意绪，新声只欲劝衔杯。"]},{"t":"节日新晴归自天庆","f":"五言律诗","c":["初日明雁腹，酸风迎马头。","如何一雨过，添却满城秋。","楼观色俱喜，槐榆影独愁。","节中公事少，吏散得吾休。"]},{"t":"记梦中红碧一联","f":"五言律诗","c":["喜教儿联句，那知是梦中。","天窥波底碧，日抹树梢红。","觉后念何说，意间难强通。","元来一夜雪，明晓散晴空。"]},{"t":"仲良见和再和谢焉四首 其四","f":"五言律诗","c":["岂不为寮久，兹焉独愈亲。","卜居如不近，同志竟何因。","山鸟频招饮，江花解笑人。","风颠仍雨急，枉却一年春。"]},{"t":"仲良见和再和谢焉四首 其三","f":"五言律诗","c":["健论开仍阖，清规高更寒。","抗章胡未报，忧世可能宽。","收用今宁晚，飞鶱尚会看。","自怜千虑短，所愿一枝安。"]},{"t":"仲良见和再和谢焉四首 其二","f":"五言律诗","c":["谁谓陈三远，髯张下笔亲。","夫何此意合，恐有宿生因。","我岂慵开眼，年来寡见人。","更烦彫好句，割取楚江春。"]},{"t":"仲良见和再和谢焉四首 其一","f":"五言律诗","c":["未惜诗脾苦，端令鬼胆寒。","吾才三鼓竭，君思九江宽。","作者今犹古，灯前捲又看。","不辞须撚断，只苦句难安。"]},{"t":"休日","f":"五言律诗","c":["休日稀公事，炎天废故书。","未须搔白首，留取试新梳。","不是平生懒，何缘作计疏。","闲携小儿女，桥上看芙蕖。"]},{"t":"再观十里塘捕鱼有叹","f":"五言律诗","c":["渔者都星散，那知不是真。","忽然重举网，何许有逃鳞。","暗漉泥中玉，光跳日下银。","江湖无避处，而况野塘滨。"]},{"t":"再过常州","f":"五言律诗","c":["淮浦回春舫，荆溪又早炊。","向来迎客处，还似迓侬时。","父老今馀几，山川别后奇。","旧游休再至，再至只成悲。"]},{"t":"再和","f":"七言律诗","c":["三月阴晴顷刻分，晚来非午午非晨。","闭门细草新蒲雨，过眼飞花落絮春。","顾我江湖钓竿客，识君台阁步云人。","柯山不患无人作，便合留中作近邻。"]},{"t":"再和袁起岩韵","f":"七言律诗","c":["一岁驩声沸此宵，游人丽服正飘飘。","病夫未暇砖引玉，恶语翻成李报瑶。","天遣素娥提雪月，江涵公子更风标。","君家道是关门卧，却有新诗来见撩。"]},{"t":"再和谢朱叔止机宜投赠奖及南海集之句","f":"七言律诗","c":["重阳风雨不全篇，春草池塘岂满编。","好句谁言较多少，古人信手斲方圆。","自惭下下中中语，只合休休莫莫传。","珍重银钩挥玉唾，竟无瑶报只空然。"]},{"t":"再和错综其韵","f":"七言律诗","c":["家书希到恐缘遥，岂有全无雁拂霄。","屈指大刀违破镜，负渠缩项及长腰。","何当竹外扁舟去，趁取梅梢未雪消。","赖有可人同舍客，破愁得句似参寥。"]},{"t":"冲雪送陆子静","f":"五言律诗","c":["猛落还中歇，疏飞忽骤繁。","平欺芦屋脊，偏护竹篱根。","对面看童子，低头印手痕。","销魂送行客，行客更销魂。"]},{"t":"刘公佐亲家奉议挽词二首 其二","f":"五言律诗","c":["一命华其老，诸昆半作官。","相高仍孝悌，不但盛衣冠。","近别那云诀，临丧独忍看。","心知公不恨，我自泪难乾。"]},{"t":"刘公佐亲家奉议挽词二首 其一","f":"五言律诗","c":["已病身犹健，云瘳讣却闻。","告存非不寿，有子更能文。","嗟我何多难，丧亲又哭君。","两家两翁好，作么并丘坟。"]},{"t":"刘世臣先生挽诗","f":"五言律诗","c":["策第仍为邑，于公未足论。","眼中无佛国，户外即韩门。","道大功非细，人亡德则存。","西风寄双泪，吹到秀峰原。"]},{"t":"刘平甫挽诗二首 其二","f":"五言律诗","c":["忠显肩双庙，屏山箓二程。","岭寒松节苦，坛暖杏花明。","君也孤传业，天乎独短生。","子孙无一物，故纸付渠耕。"]},{"t":"刘平甫挽诗二首 其一","f":"五言律诗","c":["忠孝元家法，经纶岂懒心。","日边迟信息，霞外且山林。","风月诗天巧，乾坤酒陆沉。","一生欠半面，五字寄哀音。"]},{"t":"刘季澄投赠新诗次韵为谢","f":"七言律诗","c":["君操笔耒启新畬，耕遍西溪万卷馀。","藜杖芒鞋来得得，柳风花雨政疏疏。","是家人物孙如祖，惊代诗文我爱渠。","努力收科无早晚，不须灯下独长嘘。"]},{"t":"同三馆饯王恭父监丞分韵予得何字","f":"七言律诗","c":["去岁从游泛绿波，西湖今日又新荷。","生来长是欢悰少，老去更堪离别多。","客里送君留不住，尊前为我饮无何。","休休万事付一醉，为报骊驹未要歌。"]},{"t":"同王见可刘子年循南溪度西桥登天柱冈望东山二首 其二","f":"七言律诗","c":["偶因闲步散顽麻，倦唤胡床小歇些。","飞上山头人似鹤，回看溪畔路如蛇。","云烟极目知何处，松竹为门是我家。","下得山来饥更渴，也无麦饭也无茶。"]},{"t":"同王见可刘子年循南溪度西桥登天柱冈望东山二首 其一","f":"七言律诗","c":["亲交久别忽相从，饭罢相将拄瘦筇。","深涧小桥聊驻步，胡床羽扇对西风。","水声流入肝脾里，日影轻遮云气中。","玉润即看朝玉阙，山居独自卧山翁。"]},{"t":"同刘季游登天柱冈四首 其一","f":"七言律诗","c":["两只胡床小憩些，一枝筇杖拄倾斜。","烟云惨淡天将雪，风日荒寒梅未花。","人去客来酤酒市，鸡鸣犬吠野人家。","清游不用忙归去，强管行程是暮鸦。"]},{"t":"同李簿养直登秋屏","f":"五言律诗","c":["大范今无寺，秋屏故有基。","看山非不好，吊古却成悲。","行役真何苦，同来也未迟。","题诗只恶语，差胜不题诗。"]},{"t":"后一月再宿城外野店夙兴入城谒益公二首 其二","f":"七言律诗","c":["归途未信欲斜阳，只怪行人影转长。","松寿已高犹绿发，枫年方少更红裳。","秋光便是天金谷，画本偷归我锦囊。","只怨冲寒叹行役，青鞋布袜却芬香。"]},{"t":"后一月再宿城外野店夙兴入城谒益公二首 其一","f":"七言律诗","c":["吹灯览镜又匆匆，乌帽新时白鬓空。","残月忙追晓星上，飞霜先到轿窗中。","如何五鼓寒十倍，不肯半分饶一翁。","到得火轮相暖热，山霏特地碧曚昽。"]},{"t":"后圃杏花","f":"五言律诗","c":["小树手初种，当年花便稠。","拣枝那忍折，绕径祗成愁。","淡了犹红在，留渠肯住不。","无端万银竹，判却一春休。"]},{"t":"后圃秋步","f":"五言律诗","c":["夏箑秋新妒，暄窗冷早侵。","病葵萱未悟，落果草偏深。","老矣曾荣望，归欤更懒心。","此冠弹与挂，若个不山林。"]},{"t":"回望黄巢矶之险心悸久之","f":"七言律诗","c":["夜云到晓不教收，初日微明又却休。","雨为岸花新洗面，水撩江草只摇头。","千篙百棹力都竭，十里九矶船正愁。","若到峡中应更险，却思峡外是安流。"]},{"t":"多稼亭前两槛芍药红白对开二百朵","f":"七言律诗","c":["红红白白定谁先，袅袅娉娉各自妍。","最是倚栏娇分外，却缘经雨意醒然。","晚春早夏浑无伴，暖艳晴香政可怜。","好为花王作花相，不应只遣侍甘泉。"]},{"t":"延之寄诗觅道院集遣骑送呈和韵谢之","f":"七言律诗","c":["与君鬓发总星星，诗句输君老更成。","别去多时频梦见，夜来一雨又秋生。","故人金石情犹在，赠我琼琚雪似清。","谁把尤杨语同日，不教李杜独齐名。"]},{"t":"戏题檐间蜘蛛","f":"七言律诗","c":["屋角篱尖竹树阴，可怜用尽许机心。","凝身不动如无物，顿网轻摇试有禽。","丝贯日华明五色，戏随风舞忽千寻。","看渠经纬来还去，忘却摧隤立不禁。"]},{"t":"早发建安寺过大栎虚","f":"五言律诗","c":["睡美那能动，朝凉强作行。","吾方犯星起，人已趁虚声。","近路还如许，长途作么生。","两亲今正老，三釜又须营。"]},{"t":"早行见萤","f":"五言律诗","c":["浅草时双起，深丛忽独明。","情知晓月淡，意欲照人行。","扇扑高无奈，风斜半欲横。","书帷吾已懒，不拟著囊盛。"]},{"t":"早炊高店","f":"七言律诗","c":["过雨溪山十倍明，乍晴风日一番清。","白鸥池沼菰蒲影，红枣村虚鸡犬声。","肉食坐曹良愧死，囊衣行部亦劳生。","不堪有七今成九，伧父年来老更伧。"]},{"t":"早炊童家店","f":"七言律诗","c":["长亭深处小亭奇，杂蘤粗蕤亦有姿。","羊角豆缠松叶架，鸡冠花隔竹枪篱。","不辞雨卧风餐里，可惜橙黄橘绿时。","行到前头杨柳径，平分红白两莲池。"]},{"t":"早起","f":"五言律诗","c":["不分老铃下，苦来惊我眠。","要知甘寝处，最是欲明天。","未了公家事，难销月俸钱。","坐曹临讼罢，残烛正荧然。"]},{"t":"早谒景灵宫","f":"七言律诗","c":["夜雪犹飘天目峰，晓晴先暖太清宫。","云翻孔雀金花碧，日射鸳鸯玉瓦红。","百辟焚香官柳影，一鸦飞立殿檐东。","仰瞻九圣联龙衮，万岁千秋对昊穹。"]},{"t":"早朝垂拱殿晚出东省","f":"五言律诗","c":["请外天难达，留中日不遑。","乌啼金殿月，鹭集玉阶霜。","出晚缘堂白，归时报录黄。","来年六十一，六十鬓苍苍。"]},{"t":"曲江重阳","f":"七言律诗","c":["烟描水写老秋容，岭外秋容也自浓。","如见大宾新露菊，若歌商颂晓风松。","插花醉照濂溪井，吹发慵登帽子峰。","莫问明年衰与健，茱萸何处不相逢。"]},{"t":"朱新仲舍人灊山诗集其子軧叔止见惠且有诗和以谢之","f":"七言律诗","c":["灊山诗伯锦裁篇，玉树郎君手为编。","美似洛花争晓靓，清如江月赴秋圆。","力追杜老今谁拟，亲得陵阳夜半传。","再拜一吟三太息，青灯细雨伴凄然。"]},{"t":"次公满秩来归偶上巳寒食同日父子小酌","f":"七言律诗","c":["又是一年脩禊时，何须曲水泛金卮。","遍尝众酒少亦醉，坐到三更眠未迟。","上巳巧当寒食日，春风悭放牡丹枝。","白头父子灯前语，忘却江湖久别离。"]},{"t":"次主簿叔晚霞","f":"七言律诗","c":["病眼何愁未苦佳，晓看霜了晚看霞。","只惊天上三冬月，那得西湖十里花。","景与诗争酣未退，兴如水涌去难遮。","却嫌醉墨欹倾甚，整整斜斜半似鸦。"]},{"t":"次主簿昌英叔镊白韵","f":"五言律诗","c":["滴尽思亲泪，犹残影吊形。","眼花浑作黑，颔底更能青。","少也投三赋，今焉忽一星。","此生成底事，有脚不曾停。"]},{"t":"次出门韵","f":"五言律诗","c":["有酒何须富，无车却好行。","眼中长得句，身外岂关情。","远岭寒逾瘦，乾枫落更声。","好怀非自閟，且道向谁倾。"]},{"t":"次李倅子寿郡集诗韵","f":"七言律诗","c":["苍璧新煎第二泉，博山深炷古龙涎。","草玄顾我非杨子，能赋如公是仲宣。","诗社自甘编下户，醉乡何苦不开边。","穷州地主惭司业，不解时时与酒钱。"]},{"t":"次韵寄题马少张致政亦乐园","f":"七言律诗","c":["亦乐园将独乐园，两园谁窄复谁宽。","似闻闾里溪深处，下有蛟龙水底蟠。","黄帽已捐苍玉佩，朱颜不借紫金丹。","刺桐花发梅花落，安得乘风去一观。"]},{"t":"次霜月韵","f":"五言律诗","c":["银浦寒无浪，金星澹不芒。","初看霜是月，并爱月和霜。","万里除纤翳，双清作一光。","诗穷只欠许，穷我未渠央。"]},{"t":"戊申四月九日得请补外初出国门宿释迦寺","f":"七言律诗","c":["出却金宫入梵宫，翠微绿雾染衣浓。","三年不识西湖月，一夜初闻南涧钟。","藏室蓬山真昨戏，园翁溪友得今从。","若非朝士相追送，何处冥鸿更有踪。"]},{"t":"送吉州太守朱子渊造朝二首 其二","f":"七言律诗","c":["公在乡邦我在京，百书终不慰生平。","西归一见还倾盖，夜坐相看话短檠。","老去可堪频送客，古来作恶是离情。","云泥隔断从今始，肯倩征鸿访死生。"]},{"t":"送吉州太守朱子渊造朝二首 其一","f":"七言律诗","c":["庐陵难做定何如，请看黟川朱大夫。","秋月满怀春满面，视民如子吏如奴。","万艘白粲何曾欠，百雉金城旧更无。","归侍玉皇香案了，甘棠便是瑞莲图。"]},{"t":"壬午初秋赠写真陈生","f":"五言律诗","c":["居士一丘壑，深衣折角巾。","谁曾令子见，忽漫写吾真。","更不游方外，于何顿若人。","呼儿一笑看，下笔可能亲。"]},{"t":"池陂邓店松林","f":"五言律诗","c":["破店谁相伴，疏松对作行。","捲鳞乾不脱，落子拆犹香。","声搅三更梦，阴和片月凉。","吾庐万株碧，回首暮苍苍。"]},{"t":"池亭","f":"五言律诗","c":["小沼才阶下，孤亭恰水边。","揩磨一玉镜，上下两青天。","可惜无多水，难堪著钓船。","今年非不暑，每到每醒然。"]},{"t":"竹床","f":"七言律诗","c":["已制青奴一壁寒，更支绿玉两头安。","谁言诗老眠云榻，不是渔郎钓月竿。","醉梦那知蕉叶雨，小舟亲过蓼花滩。","蹶然惊起天将晓，窗下书灯耿复残。"]},{"t":"红玫瑰","f":"七言律诗","c":["非关月季姓名同，不与蔷薇谱牒通。","接叶连枝千万绿，一花两色浅深红。","风流各自燕支格，雨露何私造化功。","别有国香收不得，诗人熏入水沈中。"]},{"t":"红锦带花","f":"七言律诗","c":["天女风梭织露机，碧丝地上茜栾枝。","何曾系住春归脚，只解萦长客恨眉。","节节生花花点点，茸茸晒日日迟迟。","后园初夏无题目，小树微芳也得诗。"]},{"t":"约刘彦纯会建安寺","f":"五言律诗","c":["邂逅何时可，平章后月凉。","前期来一夕，古寺作重阳。","白酒多多载，黄花急急香。","遣诗愁已遣，何况更连床。"]},{"t":"纪闻","f":"五言律诗","c":["人道真虚席，心知必数公。","宾王欺钓筑，君实误儿童。","天在升平外，春归小雪中。","何曾忘诸老，渠自爱松风。"]},{"t":"纪闻悼旧","f":"五言律诗","c":["莫说湘南寺，令人绝痛渠。","中间缘国论，偶似绝交书。","衫短枯荷叶，墙高过笋舆。","人生须富贵，富贵竟何如。"]},{"t":"羽檄召诸郡兵","f":"五言律诗","c":["闽盗宵窥粤，南兵晓尽东。","军声动岩谷，旗影喜霜风。","貔虎诸方集，欃枪一笑空。","区区鼠子辈，不足奏肤公。"]},{"t":"老眼废书有叹","f":"五言律诗","c":["老矣书无分，居然眼有花。","墨兵非死友，陆谞且生涯。","雪后霜逾劲，吟边帽只斜。","小儿知我懒，夜诵故喧哗。"]},{"t":"考试湖南漕司南归值雨","f":"七言律诗","c":["我亦知吾生有涯，长将病骨抵风沙。","天寒短日仍为客，酒暖长亭未是家。","又苦征夫催去去，更甘飞雨故斜斜。","旧闻行路令人老，便恐霜毛一半加。"]},{"t":"自音声岩泛小舟下高溪","f":"五言律诗","c":["晚日黄犹暖，寒江白更清。","远山冲岸出，钓艇背人行。","舟稳何妨小，波恬尔许平。","大鱼不相报，拨剌得吾惊。"]},{"t":"至日宿蓝坑小民居竹柱荻壁壁皆不土","f":"五言律诗","c":["一路都岑寂，蓝坑分外荒。","屋疏茅送月，壁密荻分霜。","病趾催趺坐，残更妒晓光。","暖寒无上策，来早借朝阳。"]},{"t":"至日薄寒","f":"七言律诗","c":["旧传冬不到南中，今岁南中稍稍冬。","曦幕暖吹红皱起，霜桥冷步缟声松。","裁缝苦思诗千首，排遣清愁酒一钟。","不是梅花开独早，似怜北客老相逢。"]},{"t":"至永州城外","f":"七言律诗","c":["恋恋庭闱竟北征，槐花唤我试诸生。","了知归近犹看堠，更有愁来即入城。","愚水端能勤入梦，崳峰何得懒相迎。","只应白发持环久，见我跫然笑未成。"]},{"t":"至节宿翁源县与叶景伯小酌","f":"七言律诗","c":["此县谁言是强名，古来十室亦琴鸣。","只嫌六七茅竹舍，也有两三鸡犬声。","村酒分冬胜虚度，霜风一夜办新晴。","半生客路逢佳节，佳节何曾负半生。"]},{"t":"至后十日雪中观梅","f":"七言律诗","c":["小树梅花彻夜开，侵晨雪片趁花回。","即非雪片催梅发，却是梅花唤雪来。","琪树横枝吹脑子，玉妃乘月上瑶台。","世间除却梅梢雪，便是冰霜也带埃。"]},{"t":"至后睡觉","f":"七言律诗","c":["匆匆又过一阳生，睡恰浓时梦忽惊。","帘幕深沉人四寂，阶除点滴雨三更。","灯摇芒角开成晕，风吸窗棂过后声。","不是寒鸡寒似我，如何不肯唤天明。"]},{"t":"舟中小雨","f":"七言律诗","c":["漠漠轻寒粟晓肤，酴醾半落牡丹初。","颠风无赖难拘管，小雨多情为破除。","半世光阴行路里，一年春事客愁馀。","浙西尚远江西在，何日章江买白鱼。"]},{"t":"舟中不寐","f":"七言律诗","c":["醉去昏然卧绿窗，醒来一枕好凄凉。","意中为许无佳况，梦里分明到故乡。","淮水打船千浪雪，燕鸿叫月满天霜。","山城更点元无准，偏到鸡鸣分外长。"]},{"t":"舟中午睡","f":"五言律诗","c":["一叶摇无定，昏然妙思通。","化为漆园蝶，飞入大槐宫。","有酒相勾引，无茶作寇戎。","平生眠不足，还债橹声中。"]},{"t":"舟中即事","f":"七言律诗","c":["阿翁阿囝自相随，赏遍江淮春盛时。","熊白同尝腊前酒，雌黄自改晓间诗。","醉来忽笑天地窄，老去那能儿女悲。","身后升沉各何有，到头谁黠复谁痴。"]},{"t":"舟中奉怀三馆同舍","f":"五言律诗","c":["岸树枝枝瘦，汀芜节节枯。","云留雪且住，风与屋相呼。","一老冻欲死，群仙知也无。","更缘诗作祟，病骨转清臞。"]},{"t":"舟中追和张功父贺赴召之句","f":"七言律诗","c":["两岁千愁寡一欣，故人多问谢张君。","又瞻东阙阙前月，只负南溪溪上云。","宾日扶桑遭圣旦，客星钓濑愧天文。","人生离合风前叶，聚首亡何复离群。"]},{"t":"舟行得风晚至灵洲","f":"五言律诗","c":["春尽侬随去，江行兴未穷。","时烦数点雨，轻洒一孤篷。","岸树苍茫外，人家点缀中。","海神能饯我，借与半帆风。"]},{"t":"舟过大通镇","f":"五言律诗","c":["淮上云垂岸，江中浪拍天。","顺风那敢望，下水更劳牵。","芦荻偏留缆，渔罾最碍船。","何曾怨川后，鱼蟹不论钱。"]},{"t":"舟过兰溪","f":"七言律诗","c":["驾雨颠风过即虚，杀风急雨有还无。","云山奔走无停住，岸树欹斜不要扶。","船底石声知浅水，沙头笠影倦牵夫。","金台祇在横山背，便到金台也日晡。"]},{"t":"舟过杨子桥远望","f":"七言律诗","c":["此日淮堧号北边，旧时南服纪淮堧。","平芜尽处浑无壁，远树梢头便是天。","今古战场谁胜负，华夷险要岂山川。","六朝未可轻嘲谤，王谢诸贤不偶然。"]},{"t":"舟过桐庐三首 其三","f":"五言律诗","c":["后面山无数，南头柳更多。","人家逼江岸，屋柱入沧波。","老去频经此，重来更几何。","牛山动悲感，曾侍板舆过。"]},{"t":"舟过桐庐三首 其二","f":"五言律诗","c":["近县人人喜，来船岸岸移。","偶因小泊处，恰是早餐时。","唤仆答相乱，看山寒不知。","横洲犹半在，今岁水生迟。"]},{"t":"舟过桐庐三首 其一","f":"五言律诗","c":["潇洒桐庐县，寒江缭一湾。","朱楼隔绿柳，白塔映青山。","稚子排窗出，舟人买菜还。","峰头好亭子，不得一跻攀。"]},{"t":"行部有日喜雨","f":"五言律诗","c":["一雨天良苦，连宵酿不成。","强摩昏睡眼，来看滴阶声。","环细开来大，珠跳灭又生。","稻花知我出，喷雪待相迎。"]},{"t":"行部暂辞金陵同列有感","f":"五言律诗","c":["爽气来江外，秋容上柳梢。","生遭女媭骂，老解子云嘲。","衰病聊飞屐，行藏镇把包。","君看社后燕，还忆社前巢。"]},{"t":"西府直舍盆池种莲二首 其二","f":"七言律诗","c":["西府寒泉汲十寻，深浇浅洒碧森森。","高花已照红妆镜，小莟新抽紫玉簪。","钿破尚馀新雨恨，伞疏才作半池阴。","西湖瘦得盆来大，更伴诗人恐不禁。"]},{"t":"西府直舍盆池种莲二首 其一","f":"七言律诗","c":["飞空天镜堕莓苔，玉井移莲旋旋栽。","坐看一花随手长，挨开半叶出头来。","稍添菱荇相萦带，便有龟鱼数往回。","剩欲绕池三两匝，数声排马苦相催。"]},{"t":"观化","f":"五言律诗","c":["道是东风巧，西风未减东。","菊黄霜换紫，树碧露揉红。","须把乖张眼，偷窥造化工。","只愁失天巧，不悔得诗穷。"]},{"t":"观迎神小儿社","f":"五言律诗","c":["花帽铢来重，绡裳水样秋。","强行终较懒，妍唱却成羞。","鹦鹉栖葱指，芙蕖载锦舟。","休看小儿社，只益老人愁。"]},{"t":"观雪二首 其二","f":"七言律诗","c":["坐看深来尺许强，偏于薄暮发寒光。","半空舞倦居然懒，一点风来特地忙。","落尽琼花天不惜，封它梅蕊玉无香。","倩谁细撚成汤饼，换却人间烟火肠。"]},{"t":"观雪二首 其一","f":"七言律诗","c":["银屋瑶阶顷刻成，缓飘急洒总无声。","屑云作粉如何湿，雕玉为花乃尔轻。","空里仰看元不见，日光未透不妨晴。","满庭更遣迟销著，剩借书窗几夜明。"]},{"t":"过九里亭","f":"五言律诗","c":["水渚才容足，渔家便架椽。","屋根些子地，檐外不胜天。","岸岸皆垂柳，门门一钓船。","五湖好风月，乞与不论钱。"]},{"t":"过土笕冈","f":"五言律诗","c":["木落初宜菜，亭荒不复茅。","牛分叉路口，鹳立秃松梢。","秋热方升日，朝凉更迥郊。","衰年走尘鞅，何计返云巢。"]},{"t":"过太湖石塘三首 其三","f":"七言律诗","c":["兀坐船中只欲眠，不如船外看山川。","松江是物皆诗料，兰桨穿湖即水仙。","将取垂虹亭上景，都归却月观中篇。","正缘王事游方外，凿齿弥天未当贤。"]},{"t":"过太湖石塘三首 其二","f":"七言律诗","c":["每过松江得伟观，玻璃盆底饤乾坤。","天边岛屿空无际，烟外人家澹有痕。","笠泽古今多浪士，包山近远在何村。","季鹰鲁望何曾死，雪是衣裳月是魂。"]},{"t":"过太湖石塘三首 其一","f":"七言律诗","c":["才转船头特地寒，初无风色自生湍。","堤横湖面平分白，水拓天围分外宽。","一镜银涛三万顷，独龙玉脊百千蟠。","若为结屋芦花里，月笠云蓑把钓竿。"]},{"t":"过弋阳观竞渡","f":"七言律诗","c":["急鼓繁钲动地呼，碧琉璃上两龙趋。","一声翻倒冯夷国，千载凄凉楚大夫。","银椀锦标誇胜捷，画桡绣臂照江湖。","三年端年真虚过，奇观初逢慰道涂。"]},{"t":"过宁国县","f":"七言律诗","c":["薄日烘云未作霞，好峰怯冷著轻纱。","绝怜山色能随我，政用花时不在家。","骑吏那愁千里远，牡丹各插一枝斜。","细看文脊空多肉，不似青阳看九华。"]},{"t":"过平公桥","f":"五言律诗","c":["高岸行成路，清渠淡不波。","荇花深似菊，芡叶皱于荷。","闻道新桥好，还成带雨过。","如何平氏店，宿处不逢它。"]},{"t":"过平望","f":"七言律诗","c":["望中不著一山遮，四顾平田接水涯。","柳树行中分港汊，竹林多处聚人家。","风将春色归沙草，天放晴光入浪花。","午睡起来情绪恶，急呼蟹眼瀹龙牙。"]},{"t":"过平望三首 其三","f":"五言律诗","c":["小麦田田种，垂杨岸岸栽。","风从平望住，雨傍下塘来。","乱港交穿市，高桥过得桅。","谁言破书箧，担取太湖回。"]},{"t":"过平望三首 其二","f":"五言律诗","c":["行得三吴遍，清奇最是苏。","树围平野合，水隔别村孤。","震泽非尘世，松陵是画图。","更添一诗老，载雪过重湖。"]},{"t":"过平望三首 其一","f":"五言律诗","c":["岂但湖天好，诸村总可人。","麦苗染不就，茅屋画来真。","行止随缘著，江山到处新。","十年三过此，赢得鬓如银。"]},{"t":"过瓜洲镇","f":"七言律诗","c":["夜愁风浪不成眠，晓渡清平却晏然。","数棒金钲到江步，一樯霜日上淮船。","佛狸马死无遗骨，阿亮台倾只野田。","南北休兵三十载，桑畴麦垄正连天。"]},{"t":"过刘村江","f":"五言律诗","c":["波走痕痕日，江呈岸岸秋。","清流堪数石，浅涉不须舟。","野菊知何喜，迎风舞未休。","归涂愁欲暮，未暮我何愁。"]},{"t":"过安仁岸","f":"五言律诗","c":["野水工穿石，疏林不掩巢。","雨蒲拳病叶，风筱秃危梢。","短胫知难续，长腰强自抄。","兹游良不恶，物色困诙嘲。"]},{"t":"过杨子江二首 其二","f":"七言律诗","c":["天将天堑护吴天，不数殽函百二关。","万里银河泻琼海，一双玉塔表金山。","旌旗隔岸淮南近，鼓角吹霜塞北闲。","多谢江神风色好，沧波千顷片时间。"]},{"t":"过杨子江二首 其一","f":"七言律诗","c":["祇有清霜冻太空，更无半点荻花风。","天开云雾东南碧，日射波涛上下红。","千载英雄鸿去外，六朝形胜雪晴中。","携瓶自汲江心水，要试煎茶第一功。"]},{"t":"过岑水","f":"五言律诗","c":["石瘦铜苗绿，溪腥胆水黄。","是间无马迹，何处更羊肠。","恶路今方始，平生梦未尝。","如何寒刮骨，行得汗如浆。"]},{"t":"过张王庙","f":"五言律诗","c":["地迥人烟寂，山盘水势回。","怪松欹岸出，古庙背河开。","晚色催征棹，斜阳恋去桅。","丹徒谁道远，一眺正悠哉。"]},{"t":"过杨村","f":"七言律诗","c":["石桥两畔好人烟，匹似诸村别一川。","杨柳阴中新酒店，蒲萄架底小渔船。","红红白白花临水，碧碧黄黄麦际天。","政尔清和还在道，为谁辛苦不归田。"]},{"t":"过皂口","f":"五言律诗","c":["赣石三百里，春流十八滩。","路从青壁绝，船到半江寒。","不是春光好，谁供客子看。","犹须一尊渌，并遣百忧宽。"]},{"t":"过宜福桥","f":"七言律诗","c":["水乡泽国最输农，无旱无乾只有丰。","碧豆密争桑荫底，绿荷杂出稻花中。","是田是沼浑难辨，何地何村不一同。","若遣明年无种子，却愁闲杀雨和风。"]},{"t":"过查濑","f":"七言律诗","c":["眼底常山一武中，上滩更得半帆风。","青天以水为铜镜，白鹭前身是钓翁。","旧日岸头浑改尽，数尖山觜忽搀空。","老夫只费五六日，行尽浙山西复东。"]},{"t":"过胡骆坑二首 其二","f":"七言律诗","c":["已被山寒病老身，车徒溪涉更艰勤。","雾皆成点元非雨，日出多时未脱云。","猿鸟一声人不见，松杉四塞径无痕。","十分晴暖侬何福，肯借曦光三五分。"]},{"t":"过胡骆坑二首 其一","f":"七言律诗","c":["说尽山寒未识寒，此间寒不是人间。","岩崖泉冻琉璃涧，冰雪云封翡翠山。","一担衣裳都著尽，两边窗子更深关。","耸肩缩颈仍呵手，无策能温两脚顽。"]},{"t":"过胥口江水大涨舟楫不进","f":"七言律诗","c":["北江西水两相逢，胥口波涛特地雄。","万事向侬冰与炭，一生行役雨和风。","急流欲上人声闹，近岸还移牵路穷。","河伯喜欢侬苦恼，并将恩怨恼天公。"]},{"t":"过赵家庄","f":"五言律诗","c":["老子方孤闷，西山忽在旁。","回头邬子砦，明眼赵家庄。","试饮章江味，中涵吉水香。","望乡侬已喜，而况到吾乡。"]},{"t":"过高邮","f":"七言律诗","c":["解缆维杨欲夕阳，过舟覆盎已晨光。","夹河渔屋都编荻，背日船篷尚满霜。","城外城中四通水，堤南堤北万垂杨。","一州斗大君休笑，国士秦郎此故乡。"]},{"t":"过淮阴县","f":"五言律诗","c":["索寞淮阴县，人家草草中。","荻篱纬春胜，茅屋学船篷。","今日非昨日，南风转北风。","霍然香雾散，放出一轮红。"]},{"t":"过淮阴县题韩信庙前用唐律后用进退格 其一","f":"七言律诗","c":["来时月黑过淮阴，归路天花舞故城。","一剑光寒千古泪，三家市出万人英。","少年跨下安无忤，老父圯边愕不平。","人物若非观岁暮，淮阴何必减宣成。"]},{"t":"过章戴岸二首 其二","f":"五言律诗","c":["港汊村村出，江流节节添。","可怜千嶂好，输与一峰尖。","过雨日初软，顺风波更恬。","旋褰篷作屋，更挂簟为帘。"]},{"t":"过章戴岸二首 其一","f":"五言律诗","c":["山水教无暑，牛羊报有村。","近沙经雨净，远树入烟昏。","奔走何时了，升沉未要论。","江鸥大自在，雪影正孤翻。"]},{"t":"过彭泽县望渊明祠堂","f":"五言律诗","c":["梦里邯郸熟，谈间栗里亲。","不闻担板汉，曾羡采薇人。","停待容来日，商量尚小贫。","只欺五斗米，典没万金身。"]},{"t":"过瘦牛岭","f":"七言律诗","c":["行尽天涯未遣休，梅州到了又潮州。","平生岂愿乘肥马，临老须教过瘦牛。","梦里长惊炊剑首，春前应许赋刀头。","夜来尚有馀樽在，急唤渠侬破客愁。"]},{"t":"过鄱阳湖天晴风顺","f":"七言律诗","c":["湖外庐山已见招，春风好送木兰桡。","青天挟日波中浴，白昼繁星地上跳。","万顷琉璃吹一叶，半簪霜雪快今朝。","庐陵归路从西去，却峭东帆趁落潮。"]},{"t":"过髦塘渡","f":"五言律诗","c":["雪浪无坚岸，金沙有退痕。","断桥犹半板，漱树欲枯根。","为问新来涨，今年第几番。","昨来愁此渡，已济不堪论。"]},{"t":"过横山塔下","f":"五言律诗","c":["隔岸山迎我，沿江柳拜人。","日摇秋水面，波闪白龙鳞。","不遣船迷路，俱从塔问津。","一生将玉镜，千古照金身。"]},{"t":"过獭桥湖","f":"五言律诗","c":["圩路抨弦白，圩沟夹柳青。","藻明潜拨剌，日暖冻蜻蜓。","只个新茅店，分明是水亭。","行来惟恐尽，览处不容停。"]},{"t":"问涂有日戏题郡圃","f":"七言律诗","c":["今年郡圃放游人，懊恼游人作挞春。","到得老夫来散策，乱吹花片总成尘。","商量岁后牢关锁，拘管风光属病身。","造物嗔侬先遣去，遣侬侬去不须嗔。"]},{"t":"余处恭少师左相郇公挽辞三首 其一","f":"五言律诗","c":["上圣临三极，维师正百工。","忠清两杨绾，诚一再温公。","衡岳摧天柱，明堂失栋隆。","初元得名相，不待卦非熊。"]},{"t":"余处恭少师左相郇公挽辞三首 其二","f":"五言律诗","c":["孝庙乘乾日，光宗宅震宫。","夔龙池集凤，黄绮翼高鸿。","初政扶皇极，三朝抗大忠。","期年坐黄阁，万古一清风。"]},{"t":"余处恭少师左相郇公挽辞三首 其三","f":"五言律诗","c":["天下非无士，胸中自有人。","如何初拜相，首荐一遗民。","恩我丘山小，怀公骨肉亲。","白头哭知己，东望独伤神。"]},{"t":"克信弟坐上赋梅花二首 其二","f":"七言律诗","c":["月波成露露成霜，借与南枝作淡妆。","寒入玉衣灯下薄，春撩雪骨酒边香。","却于老树半枯处，忽走一梢如许长。","道是疏花不解语，伴人醒醉替人狂。"]},{"t":"克信弟坐上赋梅花二首 其一","f":"七言律诗","c":["对酒初惊发半华，折梅还觉兴殊佳。","如何屋角西南月，只照梢头一两花。","自是向来香寂寞，不须更道影横斜。","北枝别有春无价，和靖何曾觅得些。"]},{"t":"初六日过鄱阳湖入相见湾","f":"七言律诗","c":["阻风两日卸高桅，笑傲江妃纵酒杯。","及至绝湖才一瞬，翻令病眼不双开。","芦洲荻港何时了，南浦西山不肯来。","相见湾中闷人死，一湾九步十萦回。"]},{"t":"初出贡院买山寒毬花数枝","f":"七言律诗","c":["寒毬著意殿馀芳，小底来禽大海棠。","初喜艳红明莟子，忽看淡白散花房。","风光不到棘围里，春色也寻茅舍旁。","便有蜜蜂三两辈，喙长三尺绕枝忙。"]},{"t":"初秋小雨残暑未退","f":"五言律诗","c":["雨好夫何小，凉新竟未多。","飘萧才响瓦，点滴不沾荷。","龙亦如侬否，渠还畏热么。","敢劳频上水，只倩挽天河。"]},{"t":"初食笋蕨","f":"七言律诗","c":["庖凤烹龙世浪传，猩唇熊掌我无缘。","只逢笋蕨杯盘日，便是山林富贵天。","稚子玉肤新脱锦，小儿紫臂未开拳。","只嫌岭外无珍馔，一味春蔬不直钱。"]},{"t":"初食淮白","f":"七言律诗","c":["淮白须将淮水煮，江南水煮正相违。","霜吹柳叶落都尽，鱼吃雪花方解肥。","醉卧糟丘名不恶，下来盐豉味全非。","饔人且莫供羊酪，更买银刀二尺围。"]},{"t":"初凉与次公子共读书册","f":"五言律诗","c":["暑懒归投簟，凉醒打当书。","罢吟唇欲裂，起坐膝难舒。","汲古微澜动，悲秋小雨馀。","五言未针线，百过且阶除。"]},{"t":"初夏日出且雨","f":"五言律诗","c":["笑忆唐人句，无晴还有晴。","斜阳白鸥影，疏雨子规声。","台阁非吾事，溪山且此生。","诗成何用好，诗好却难成。"]},{"t":"初夏即事","f":"七言律诗","c":["旋作东陂已水声，才经急雨恰新晴。","提壶醒眼看人醉，布谷催农不自耕。","一似老夫堪笑死，万方口业拙谋生。","嘲红侮绿成何事，自古诗人没十成。"]},{"t":"初夏清晓赴东宫讲堂行经和宁门外卖花市","f":"七言律诗","c":["剩雨残风一向颠，花枝酒盏两无缘。","忽逢野老从湖上，担取名园到内前。","芍药截留春去路，鹿葱礼上夏初天。","众红半霎聊经眼，不枉皇州第二年。"]},{"t":"利州路提刑秘书张季长送洮研发视乃一段柏木也作诗谢之","f":"七言律诗","c":["绣衣使者凛霜威，方丈仙人旧羽仪。","别去十年真一梦，书来万里寄相思。","如何绿石涵风面，化作青铜溜雨枝。","却送新诗报嘉惠，偷儿当不要新诗。"]},{"t":"别吴教授景衡","f":"五言律诗","c":["道合从人笑，情亲觉别难。","得朋何恨晚，到老几相看。","世路今逾窄，吾徒却自宽。","此心各相勉，不但道加餐。"]},{"t":"别萧挺之泉州二首 其二","f":"五言律诗","c":["八叶今成九，一枝谁敢双。","野人应补外，贤者亦为邦。","夹岸梅临水，孤帆雪涌江。","别愁才半掬，不遣我心降。"]},{"t":"别萧挺之泉州二首 其一","f":"五言律诗","c":["郎署春同宿，州麾晚卜邻。","出山成底事，藉手得斯人。","名实今无对，云霄早致身。","再逢应互笑，谁发不如银。"]},{"t":"吴母叶氏太孺人挽词","f":"五言律诗","c":["发以留宾短，家从教子贫。","斑衣奉常署，象服镜湖春。","许穆诗还废，班姑史尚新。","不堪萱草露，也解泣慈亲。"]},{"t":"张几仲侍郎挽词三首 其三","f":"五言律诗","c":["京口连沧观，洪都孺子亭。","飞觞回落月，洒笔湿寒星。","别去长离索，归来遽杳冥。","知公喜侬句，五字酹英灵。"]},{"t":"张几仲侍郎挽词三首 其二","f":"五言律诗","c":["烈考同心德，中兴异姓王。","勋劳贯三极，文献在诸郎。","公也山林味，天乎日月忙。","一生非不达，晚达却堪伤。"]},{"t":"张几仲侍郎挽词三首 其一","f":"五言律诗","c":["半世金闺彦，中年碧落班。","一般俱紫橐，千古忽青山。","秋入篇章里，春生岳牧间。","汾阳旧部曲，白发万人潸。"]},{"t":"张功父旧字时可慕郭功父故易之求予书其意再赠五字","f":"五言律诗","c":["冰雪相投处，风期一笑间。","只今张桂隐，绝慕郭青山。","功父双何远，相如了不关。","鸟飞暮天碧，此句急追还。"]},{"t":"怀古堂前小梅渐开四首 其四","f":"七言律诗","c":["拣得疏花折得回，银瓶冰水养教开。","忽然灯下数枝影，唤作窗间一树梅。","岁律又残还见此，我头自白不须催。","相看姑置人间事，嚼玉餐香咽一杯。"]},{"t":"怀古堂前小梅渐开四首 其三","f":"七言律诗","c":["绝艳元非著粉团，真香亦不在须端。","何曾天上冰玉质，却怕人间霜雪寒。","枝似去年仍转瘦，花于来岁定谁看。","老夫官满梅应熟，齿软犹禁半点酸。"]},{"t":"怀古堂前小梅渐开四首 其二","f":"七言律诗","c":["随意行穿翠筱林，暗香撩我独关心。","遥看小朵不胜好，走近寒梢无处寻。","未吐谁知肤底雪，半开犹护蕊头金。","老来懒去浑无绪，奈此南枝索苦吟。"]},{"t":"怀古堂前小梅渐开四首 其一","f":"七言律诗","c":["梅边春意未全回，淡日微风暗里催。","近水数株殊小在，一梢双朵忽齐开。","生愁落去轻轻折，不怕清寒得得来。","肠断故园千树雪，大江西处乱云堆。"]},{"t":"拒霜花","f":"七言律诗","c":["木蕖何似水芙蕖，同个声名各自都。","风露商量借膏沐，燕脂深浅入肌肤。","唤回春色秋光里，饶得红妆翠盖无。","字曰拒霜浑不恶，却愁霜重要人扶。"]},{"t":"拟乙巳南郊庆成二首 其二","f":"七言律诗","c":["上瑞今年特地奇，大田多稼与云齐。","星沈析木天街北，波静昆崙渤澥西。","帝在紫坛神在次，穹如苍盖月如圭。","一人执玉千官肃，万马和霜不敢嘶。"]},{"t":"拟乙巳南郊庆成二首 其一","f":"七言律诗","c":["已醊方诸月底泉，更升爟火桂梢烟。","熉黄幄坐明金炬，太紫虚皇下碧天。","玉路旂常龙十二，绣衣卤簿虎三千。","万人随驾还阊阖，看夺金鸡雪柳边。"]},{"t":"拟题绵州推官厅六一堂","f":"五言律诗","c":["一代今文伯，三巴昔产贤。","白珩光宇宙，蓝水暗风烟。","有客曾高枕，升堂见老仙。","梦中五色笔，犹为写鸣蝉。"]},{"t":"晴眺","f":"五言律诗","c":["野意随宜有，山光入望无。","寒曦不自暖，落木几曾枯。","不分霜前树，长啼月下乌。","苦吟徐便悔，可惜数茎须。"]},{"t":"李仁甫侍讲阁学挽诗二首 其二","f":"五言律诗","c":["高议春江壮，长身野鹤孤。","生涯一杯酒，行李五车书。","凡例今迂叟，声名后老苏。","岷峨气悽怆，不为玉将珠。"]},{"t":"李仁甫侍讲阁学挽诗二首 其一","f":"五言律诗","c":["紫橐犹黄帽，青灯到白头。","芝庭过晁董，金鐀续春秋。","晓月承明寂，东风玉垒愁。","殷勤倩潮水，将泪去西州。"]},{"t":"杨村园户栽芙蓉为堑一路凡数万枝","f":"七言律诗","c":["杨村江上绕江园，十里霜红烂欲燃。","都种芙蓉作篱落，真将锦绣裹山川。","晚妆照水密如积，春色入秋寒更鲜。","客舍瓶中两三朵，可怜向客强婵娟。"]},{"t":"步过分水岭","f":"五言律诗","c":["路险劳人杀，侬须下轿行。","石从何代落，蕨傍旧根生。","古树无今态，幽泉有暗声。","只言章贡近，犹自两三程。"]},{"t":"沈虞卿秘监招游西湖","f":"七言律诗","c":["苏公堤远柳生烟，和靖园深竹映关。","船入芰荷香处去，人从云水国中还。","似寒如暖清和在，欲雨翻晴顷刻间。","能为蓬莱老仙伯，一杯痛快吸湖山。"]},{"t":"灵山","f":"五言律诗","c":["饶水回回转，灵山面面逢。","展成青步障，敛作碧芙蓉。","变态百千样，尖新三两峰。","远看方更好，还隔翠云重。"]},{"t":"芙蓉渡酒店前金沙芍药盛开","f":"七言律诗","c":["山店春光也自妍，芙容渡口数家村。","笋舆低过金沙架，篱落疏围芍药轩。","孤客倦游殊寂寞，两花作意与温存。","可怜经眼匆匆去，不折红香倒绿尊。"]},{"t":"芥齑","f":"七言律诗","c":["茈姜馨辣最佳蔬，孙芥芳辛不让渠。","蟹眼嫩汤微熟了，鹅儿新酒未醒初。","枨香醋酽作三友，露叶霜芽知几锄。","自笑枯肠成破瓮，一生只解贮寒菹。"]},{"t":"诏追供职学省晓发鸣山驿","f":"五言律诗","c":["数店疏仍密，千峰整复斜。","冰痕犹带浪，霜草自成花。","录录堪朝列，星星已鬓华。","帝城万事好，得似早还家。"]},{"t":"走笔和袁起岩元夕前一夜雪作","f":"七言律诗","c":["天公极意办元宵，顷刻挼云作雪飘。","茂苑长洲花剪玉，苏台香径砌成瑶。","千灯剩喜开红药，两鬓还惊插素标。","客子孤舟寒折骨，无端诗伯苦相撩。"]},{"t":"走笔送赵正则司户来访归觐亲庭","f":"七言律诗","c":["捧檄亲庭归帽斜，肯临破屋玉川家。","小留诗客三杯酒，试看山园几处花。","君到东湖与南浦，时当芍药替金沙。","却来书满参卿考，径泛银河犯斗槎。"]},{"t":"走笔谢吉守赵判院分饷三山生荔子","f":"七言律诗","c":["吾州五马住闽山，分我三山荔子丹。","甘露落来鸡子大，晓风冻作水晶团。","西川红锦无此色，南海绿罗犹带酸。","不是今年天不暑，玉肤照得野人寒。"]},{"t":"足痛无聊块坐读江西诗","f":"五言律诗","c":["两脚遍云水，群书久网丝。","却因三日痛，理得数编诗。","不借双高挂，毋追一任欹。","老来非爱病，不病亦何为。"]},{"t":"辛丑正月二十五日游蒲涧晚归","f":"五言律诗","c":["桃李深酣日，池塘浅试春。","霁晖摇远水，新暖软游人。","生酒清无色，青梅脆有仁。","烟钟能底急，催我入城闉。"]},{"t":"辛卯五月送丘宗卿太博出守秀州二首 其二","f":"五言律诗","c":["老矣渠怜我，超然我爱渠。","论诗春雨夜，解手藕花初。","梦只江湖去，情知伎俩疏。","未应五马贵，不寄一行书。"]},{"t":"辛卯五月送丘宗卿太博出守秀州二首 其一","f":"五言律诗","c":["冯翊端谁可，丘迟肯去么。","茧丝臣敢后，饥馑帝云何。","身达当难免，能称未要多。","但无田里叹，不必裤襦歌。"]},{"t":"辛亥元日送章德茂自建康移帅江陵二首 其二","f":"七言律诗","c":["西湖一别忽三年，白首相从岂偶然。","到得我来恰君去，政当腊后与春前。","醉馀犯雪追征帽，送了凭栏望去船。","待把衣冠挂神武，看渠勋业上凌烟。"]},{"t":"辛亥元日送章德茂自建康移帅江陵二首 其一","f":"七言律诗","c":["极知借寇未多时，道是徵黄有近期。","不割半青江令宅，却飞大白习家池。","湖山解语云来暮，淮水无情也去思。","莫近乡关动归兴，轻黄一点上双眉。"]},{"t":"近节","f":"五言律诗","c":["节里非无事，忙中自有闲。","因风烦白鸟，折简唤青山。","诗卷一两册，斋房三四间。","兴来长得句，却道在尘寰。"]},{"t":"近故太师左丞相魏国文忠京公挽歌辞三首 其三","f":"五言律诗","c":["柏府公峨豸，荆溪我把麾。","闻风无半面，折简两相知。","偕掾胶投漆，分襟云与泥。","楼成扁山浦，洒泪欠题诗。"]},{"t":"近故太师左丞相魏国文忠京公挽歌辞三首 其二","f":"五言律诗","c":["镇蜀双清献，回天再子明。","何曾动声色，一笑付权衡。","临绝缘忧国，平生不近名。","中兴贤相传，日月夺光精。"]},{"t":"近故太师左丞相魏国文忠京公挽歌辞三首 其一","f":"五言律诗","c":["孝庙深知己，今皇正宰官。","一言能定国，二圣得重欢。","立节山相似，容人海未宽。","至今死诸葛，虏使胆犹寒。"]},{"t":"近故魏国夫人卢氏挽歌辞三首 其三","f":"五言律诗","c":["素节勤仍俭，清风冷似冰。","秋衣孟光布，夜绩敬姜灯。","拱木霜何早，同茔雪政凝。","郎君一夔足，再看九霄鹏。"]},{"t":"近故魏国夫人卢氏挽歌辞三首 其二","f":"五言律诗","c":["唐代崔家母，升堂乳阿姑。","姑言吾报妇，孙孝妇如吾。","此段前无古，夫人独与俱。","祇看秦国语，更恐李唐无。"]},{"t":"近故魏国夫人卢氏挽歌辞三首 其一","f":"五言律诗","c":["胄出开元相，贤称魏国嫔。","祇教纪彤管，不见转鸿钧。","瓜葛春风里，蘋蘩南涧滨。","古今书列女，仁孝几何人。"]},{"t":"迓使客夜归四首 其四","f":"七言律诗","c":["病身已怯九秋凉，也复移樽下砌傍。","只爱杯中都是月，不知身上寸深霜。","清愁旧觉天来远，寒夜新添岁样长。","不是傍人俱欲睡，老人无睡亦何妨。"]},{"t":"迓使客夜归四首 其三","f":"七言律诗","c":["起视青天分外青，满天一点更无星。","忽惊平地化成水，乃是月华光满庭。","笔下何知有前辈，醉中未肯赦空瓶。","儿曹夜诵何书册，也遣先生细细听。"]},{"t":"迓使客夜归四首 其二","f":"七言律诗","c":["病后霜威不见饶，吟边月色苦相撩。","重帘垂地寒犹入，画烛无风影自摇。","谁遣尘埃空老去，何曾鸥鹭不吾招。","坐来已是愁无奈，草露虫声政寂寥。"]},{"t":"迓使客夜归四首 其一","f":"七言律诗","c":["去时岸树日犹明，归到州桥月已升。","水与天争一轮玉，市声人语两街灯。","迎来送往须成雪，索笔题诗砚欲冰。","净洗红尘烦碧酒，倦来不觉睡腾腾。"]},{"t":"连天观望春忆毗陵翟园","f":"七言律诗","c":["中和节后社前时，春到园林最晚枝。","弄水不冰携扇手，登台犹粟向风肌。","鸟乌声里山光湿，花柳阴中日脚迟。","北望翟园春正闹，海棠锦绕雪酴醾。"]},{"t":"闰五月十四日因哭小孙子蓬孙归志浩然","f":"七言律诗","c":["宪孙哭了哭蓬孙，老眼元枯也湿巾。","名宦何须深插脚，山林从此早抽身。","祸无避处唯辞福，命不如渠强学人。","吟了此诗还毁了，莫令一读一伤神。"]},{"t":"阻风乡口一日诘朝船进雨作再小泊雷江三首 其三","f":"五言律诗","c":["山已多姿了，云仍太劣生。","浓横半岭白，淡扫数峰青。","照水影颠倒，迎曦时晦明。","吾泓不孤杀，天赐碧瑶屏。"]},{"t":"阻风乡口一日诘朝船进雨作再小泊雷江三首 其二","f":"五言律诗","c":["幸自无多雨，其如不酽晴。","响窗疏复密，晕水灭还生。","燕竞波中影，山凝岛外情。","残春只五日，留取作江行。"]},{"t":"阻风乡口一日诘朝船进雨作再小泊雷江三首 其一","f":"五言律诗","c":["朔吹憎船进，东暾让雨行。","云移青嶂动，鸦度白云明。","淹泊宁吾愿，吟哦且客情。","江边一株柳，憔悴似馀生。"]},{"t":"阻风泊黄浦","f":"五言律诗","c":["回顾山阳北，前瞻宝应东。","又逢翻手雨，更著打头风。","不了行程债，从来赋命穷。","客愁无诉处，摇指画船篷。"]},{"t":"陈安行舍人阁学挽词三首 其三","f":"五言律诗","c":["我昔游璧水，公时宿石渠。","重来十钻火，两省共周庐。","小语趋丹陛，嘉招煮雪蔬。","破心搜诔些，泪落不能书。"]},{"t":"陈安行舍人阁学挽词三首 其二","f":"五言律诗","c":["循吏今为冠，高文妙草麻。","龚黄低一著，班左共三家。","风度春无价，身名玉绝瑕。","可怜人士泪，滴损紫薇花。"]},{"t":"陈安行舍人阁学挽词三首 其一","f":"五言律诗","c":["妫水祀百世，莆田生此公。","贤如太丘长，忠似了斋翁。","玉色犹山立，皇居折栋隆。","孝宗最知己，交臂火城红。"]},{"t":"陈商卿挽辞","f":"五言律诗","c":["远绪传妫水，高风似太丘。","萱堂鱼跃雪，兰砌鹗横秋。","杖屦疏金谷，莺花冷玉舟。","行看紫鸾纸，告第贲松楸。"]},{"t":"陈能之少卿殿撰挽诗","f":"五言律诗","c":["玉立颂台上，风生宪府中。","雪霜欺两鬓，日月照孤忠。","荷橐相将紫，铭旌作么红。","北堂萱草露，应洒碧梧桐。"]},{"t":"饭罢登山","f":"五言律诗","c":["树远通莺响，花晴带雨痕。","登山偶回首，隔水见前村。","澹往孤无伴，清归笑不言。","还家更迟著，松菊未应存。"]},{"t":"饭罢登净远亭","f":"五言律诗","c":["今岁寒应少，冬深气转和。","都缘径差曲，添得步行多。","柳色犹青在，霜威奈尔何。","忽然双野鸭，飞下一池波。"]},{"t":"到龙山头","f":"五言律诗","c":["影静长安道，凉风响辔衔。","海天低到水，江日晚明帆。","潮遣先驱壮，声吞绝岛巉。","黄尘征袖满，却愧著朝衫。"]},{"t":"周子及监簿挽诗二首 其二","f":"五言律诗","c":["投老欣相得，论心恨较迟。","披文流涕疏，分韵泛湖诗。","天夺过逢乐，人兴殄瘁悲。","何须金马客，解制玉楼辞。"]},{"t":"周子及监簿挽诗二首 其一","f":"五言律诗","c":["科目连双中，声名莫二渠。","手曾攀折槛，客有泣辞车。","速化非吾事，偷闲只古书。","黑头黄壤去，有昊定何如。"]},{"t":"和丁端叔喜雪","f":"七言律诗","c":["天将一雪净乾坤，便恐汤泉亦不温。","瑶草忽生无种子，梅花寒损要温存。","清游未到先回棹，高卧何如且闭门。","珍重故人贻妙语，追还正始最初元。"]},{"t":"和人七夕","f":"五言律诗","c":["爱月斜仍细，占星久未过。","浪传商用事，正苦汗成河。","蛛喜今宵缀，蝇憎昨日多。","吾文那乞巧，诗或拟阴何。"]},{"t":"和马公弼夜雨","f":"七言律诗","c":["一雨未辞泥至腰，新寒疠气喜全消。","都人得此正希阔，远客幡然成寂寥。","声在疏檐与黄叶，梦听禁漏近丹霄。","愁心却被诗勾引，始觉君家我里遥。"]},{"t":"和尤延之见戏触藩之韵以寄之","f":"七言律诗","c":["侬爱山行君水游，尊前风味独宜秋。","文戈却日玉无价，器宝罗胸金欲流。","欬唾清圜谈者诎，诗章精悍古人羞。","子房莫笑身三尺，会看功成自择留。"]},{"t":"和文远以作醮相疏","f":"五言律诗","c":["涉夏天勤雨，今年定有秋。","试思冲热出，何似带泥游。","轩冕关庄子，江湖著魏牟。","高人香火里，也到酒边不。"]},{"t":"和文远叔行春","f":"五言律诗","c":["行脚宜晴翠，看云恐夕黄。","何村不花柳，此社要柴桑。","一笑当谁领，同来得许忙。","老怀翻作恶，不剩半分狂。"]},{"t":"和文明主簿叔见寄之韵二首 其二","f":"五言律诗","c":["黄九陈三外，诸人总解诗。","甘心休作许，苦语竟何为。","所向公同我，何缘样入时。","从来大小阮，一笑更谁知。"]},{"t":"和文明主簿叔见寄之韵二首 其一","f":"五言律诗","c":["古声弹九寡，妙学足三多。","十载才重见，百年当几何。","入州非不肯，出伏即相过。","安得看云语，金盆仄白河。"]},{"t":"和王才臣","f":"七言律诗","c":["新诗不但不饶侬，便恐阴何立下风。","每与胜谈千古事，不知拨尽一炉红。","生儿底巧翁何恨，得子销愁我未穷。","剩欲苛留老三径，念渠何罪亦山中。"]},{"t":"和王才臣再病二首 其二","f":"五言律诗","c":["诗瘦知春瘦，时乖抑命乖。","病过三日雨，门掩半扉柴。","不面何曾久，于心便有怀。","端能暮出否，溪水减南涯。"]},{"t":"和王才臣再病二首 其一","f":"五言律诗","c":["燕外将心远，莺边与耳谋。","如何再卧病，对此两添愁。","赤壁还坡老，黄楼只子由。","二苏三赋在，一览病应休。"]},{"t":"和王元驹","f":"七言律诗","c":["向来淮海说三秦，脚踏苏门最绝尘。","莫道江山歇英气，如今文物有斯人。","黄埃九陌谁知子，青竹千年独问津。","未得相看已相识，只惭空叹蜀庄珍。"]},{"t":"和王司法雨中惠诗二首 其二","f":"七言律诗","c":["无那诗愁著莫人，风颠雨急更昏昏。","登临无地可散策，剥啄阿谁来叩门。","安得与渠呼玉酒，醉馀同看落金盆。","斋厨索寞如悬罄，惭愧酸寒遣一尊。"]},{"t":"和司法张仲良醉中论诗二首 其一","f":"五言律诗","c":["醉语醒犹记，来诗读转新。","不缘朋好密，其奈客居贫。","无乃阳秋误，云何鼠朴珍。","端令和者寡，敢以速为神。"]},{"t":"和司法张仲良醉中论诗二首 其二","f":"五言律诗","c":["相过宁嫌数，未行先畏辞。","要宽千里别，犹费几篇诗。","意得翻难售，声希只自奇。","此生诗社里，三折或知医。"]},{"t":"和仲良春晚即事五首 其四","f":"五言律诗","c":["贫难聘欢伯，病敢跨连钱。","梦岂花边到，春俄雨里迁。","一犁关五秉，百箔候三眠。","只有书生拙，穷年垦纸田。"]},{"t":"和仲良春晚即事五首 其二","f":"五言律诗","c":["春在已愁热，夏来还解凉。","一年又如许，万事更须忙。","情薄忘花减，心危愿岁穰。","平生只坐懒，何药疗嵇康。"]},{"t":"和仲良春晚即事五首 其三","f":"五言律诗","c":["欲与东风说，休吹堕絮飞。","吾行正无定，魂梦岂忘归。","花暖能醺眼，山浓欲染衣。","只嫌春已老，此景也应稀。"]},{"t":"和仲良病中耽睡","f":"五言律诗","c":["居士何曾病，群儿错见怜。","对床正风雨，落纸忽云烟。","欲夏花全退，犹寒柳尚眠。","如何睡乡里，只是著诗仙。"]},{"t":"和刘德脩用黄文叔韵赠行","f":"七言律诗","c":["碧玉长篙黄篾篷，两淮烟月五湖风。","金梭织锦烦诗匠，琼尺裁云补化工。","去路江山随意绿，归时桃杏断肠红。","岷峨二妙贻双璧，万丈光芒照病翁。"]},{"t":"和同年李子西通判","f":"七言律诗","c":["走马看花拂绿杨，曲江同赏牡丹香。","向来年少今俱老，君拜监州我作郎。","北阙小迟苍玉佩，南征聊制芰荷裳。","病身只作家山梦，径菊诗葩两就荒。"]},{"t":"和同年梁韶州寺丞次张寄诗","f":"七言律诗","c":["故人一别恰三年，谁与论诗更说禅。","忽报一麾官岭外，寄来七字雪梅前。","人惟南内班行旧，语带西湖山水鲜。","安得对床吟至晓，旋烹山茗试溪泉。"]},{"t":"和巩采若游蒲涧","f":"七言律诗","c":["南中道是岛夷居，也有安期宅一区。","屐齿苔痕犹故迹，霓旌鸾佩已清都。","元戎解领三千骑，胜日来寻九节蒲。","万壑松风和涧水，鸣琴漱玉自相娱。"]},{"t":"和庆长怀麻阳叔二诗 其二","f":"五言律诗","c":["自幼仍投老，相欢不解愁。","政缘湖外别，负却竹林秋。","佳政真馀事，闻人说甚休。","不应野水渡，横此济川舟。"]},{"t":"和庆长怀麻阳叔二诗 其一","f":"五言律诗","c":["旧雪才追送，新梅又作繁。","欣逢上林雁，聊免管城冠。","酒债多多在，诗盟久久寒。","忽思十年事，有枕不能安。"]},{"t":"和易公立投赠之句","f":"七言律诗","c":["日者论文各少年，中间岁月似风旋。","老来书册惟生睡，里许生涯未苦贤。","好句撩人那得懒，胜流觅纸便争传。","诗坛正欠风骚将，君合为真不用权。"]},{"t":"和余处恭赠方士阎都干","f":"七言律诗","c":["河出昆崙江出岷，风吹不断浪花春。","但看此水源无竭，底用玄谈谷有神。","老健便为仙放杖，斧斤祗在袜生尘。","东家自有仁山诀，方士何曾悟一真。"]},{"t":"和吴寺丞喜雪","f":"七言律诗","c":["珠唾银钩赠一通，炯如密雪堕寒空。","飞来数片不沾袖，剪出六花全是风。","骨冷魂清残醉里，日光玉洁晚晴中。","先生秀句今无敌，谁诵相如奏舜瞳。"]},{"t":"和张功父送黄蔷薇并酒之韵","f":"五言律诗","c":["海外蔷薇水，中州未得方。","旋偷金掌露，浅染玉罗裳。","已换桃花骨，何须贾氏香。","更烦曲生辈，同访墨池杨。"]},{"t":"和张功父闻子规","f":"七言律诗","c":["久雨今朝忽作晴，老人怀抱不胜清。","仲宣久作登楼赋，望帝更吟当殿声。","春去春来浑是梦，花开花落若为情。","归心不用渠催唤，自有江鸥与狎盟。"]},{"t":"和张功父桤木巴榄花韵","f":"七言律诗","c":["南湖窠木已交加，种榄栽桤更北涯。","生眼错呼为夜合，新莺知不是桃花。","绿阴四合藏云屋，翠浪全机织素纱。","桂隐主人臞见骨，不餐酥酪却餐茶。"]},{"t":"和张功父病中遣怀","f":"七言律诗","c":["人自穷通诗自诗，管渠人事与天时。","鹤长未便贤凫短，梅早那须笑杏迟。","公子近来忺说病，老夫秋至不曾悲。","人生随分堪行乐，何必兰亭与习池。"]},{"t":"和张功父梦归南湖","f":"七言律诗","c":["一生两事苦相关，从仕居贫并作难。","顾我雪穿行脚袜，羡君身作在家官。","晓分京兆月半璧，夕问南湖水几竿。","桃李能言春满坐，向人犹自诉霜寒。"]},{"t":"和李与贤投赠之韵","f":"七言律诗","c":["云海不教鹏怒飞，玉阶也合凤来仪。","如何天下李元礼，未遇人间钟子期。","夜诵子虚无路达，梦生春草只心知。","愿君更奏三千牍，金榜青衫染柳丝。"]},{"t":"和李天麟二首 其二","f":"五言律诗","c":["句法天难秘，工夫子但加。","参时且柏树，悟罢岂桃花。","要共东西王，其如南北涯。","肯来谈个事，分坐白鸥沙。"]},{"t":"和李天麟二首 其一","f":"五言律诗","c":["学诗须透脱，信手自孤高。","衣钵无千古，丘山只一毛。","句中池有草，子外目俱蒿。","可口端何似，霜螯略带糟。"]},{"t":"和陆务观用张季长吏部韵寄季长兼简老夫补外之行二首 其二","f":"五言律诗","c":["别去公怀我，诗来我梦公。","半轮笠泽月，一信镜湖风。","岂有诗名世，而无鬼作穷。","管城言晓事，犹欲策元功。"]},{"t":"和陆务观用张季长吏部韵寄季长兼简老夫补外之行二首 其一","f":"五言律诗","c":["今代老龟蒙，无书遗子公。","也能将好句，特地寄西风。","迟暮甘三已，飘零笑两穷。","绝怜张与陆，百战角新功。"]},{"t":"和陆务观惠五言","f":"五言律诗","c":["官缚春无分，髯疏雪更欺。","云间堕词客，事外得心期。","我老诗全退，君才句总宜。","一生非浪苦，酱瓿会相知。"]},{"t":"和陈蹇叔郎中乙巳上元晴和","f":"七言律诗","c":["御柳梢头晚不风，官梅面上雪都融。","如何阊阖新春夜，顿有芙蕖满眼红。","十里沙河人最闹，三千世界月方中。","买灯莫费东坡纸，今岁鳌山不入宫。"]},{"t":"和周子中病中代书之韵兼督胡季文季永游山之约","f":"五言律诗","c":["吟外今何病，愁边我索居。","昔无今样懒，新欠故人书。","只说游山去，谁令作计疏。","衡庐负我辈，我辈负衡庐。"]},{"t":"和周子中韵","f":"七言律诗","c":["清愁政尔喜逢兄，一笑那知客帝城。","海气不曾晴色好，梨花半落嫩寒生。","刑书夜诵端何苦，诗句春来想不平。","我亦有怀无处说，对床只欲为渠倾。"]},{"t":"和周元吉左司郊祀庆成韵","f":"七言律诗","c":["八觚泰畤六郊天，一柱明堂再飨先。","日月旂常寒映雪，冕旒珠玉暖生烟。","风回韶濩龙鳞外，花覆貔貅凤阙前。","喜溢天颜应未了，又迎庆寿入新年。"]},{"t":"和周元吉左司梦归之韵","f":"七言律诗","c":["半似清狂半白痴，不须人笑我心知。","烟霞平日真成癖，山水中年却语离。","错计浪随云出岫，感君能遣雨催诗。","居然唤起还家梦，橘刺藤梢隔槿篱。"]},{"t":"和周元吉省中新竹","f":"七言律诗","c":["青士何年下大荒，羽仪禁省立如墙。","锦绷半脱娟娟玉，粉节新涂拂拂霜。","带雨小酣三日后，出林忽喜一梢长。","今年秋闰防多暑，剩供先生格外凉。"]},{"t":"和周仲觉三首 其三","f":"五言律诗","c":["春在梅边动，寒从月外来。","贫于萤不暖，心与烛俱灰。","此意悠悠著，从谁细细开。","病来更忧患，泪尽只馀哀。"]},{"t":"和周仲觉三首 其二","f":"五言律诗","c":["月淡犹明树，霜严不剩云。","天寒一雁叫，夜半几人闻。","诗只令吾瘦，清聊与子分。","频来仍恨少，此去更离群。"]},{"t":"和周仲觉三首 其一","f":"五言律诗","c":["书懒聊遮眼，诗穷只掉头。","寒醒非不睡，薄醉奈何愁。","火细霜还重，风停叶自投。","半生灾疾里，谁遣未休休。"]},{"t":"和周仲容春日二律句 其一","f":"五言律诗","c":["饥民日夜去，也有不荒田。","旧雨仍新雨，今年胜去年。","未嫌诗得瘦，只苦茗妨眠。","花气薰人醉，来从若个边。"]},{"t":"和周仲容春日二律句 其二","f":"五言律诗","c":["今晨晴颇懒，昨夜雨犹声。","欲社燕先觉，半春莺未鸣。","诗非一字苦，句岂十分清。","参透江西社，无灯眼亦明。"]},{"t":"和昌英主簿叔久雨","f":"七言律诗","c":["积雨今晨也解休，殷勤日脚傍花流。","半明衣桁烘梅润，全为农家放麦秋。","更著好风堕清句，不知何地顿闲愁。","新晴佳处无人会，隔柳一声黄栗留。"]},{"t":"和昌英主簿叔社雨","f":"五言律诗","c":["愁已春相背，诗仍债未还。","雨声宜小睡，竹户且深关。","梦钓鸥边雪，衰忘镜里颜。","起来聊觅句，句在眼中山。"]},{"t":"和昌英主簿叔送花","f":"七言律诗","c":["去岁归时正牡丹，亲庭上寿撚花看。","共知春好毋虚掷，更复杯深肯剩残。","谁料今兹千万感，强从叔也两相宽。","风颠雨急关侬事，时序撩人只暗叹。"]},{"t":"和昌英叔夏至喜雨","f":"七言律诗","c":["清酣暑雨不缘求，犹似梅黄麦欲秋。","去岁如今禾半死，吾曹遍祷汗交流。","此生未用愠三已，一饱便应哦四休。","花外绿畦深没鹤，来看莫惜下邳侯。"]},{"t":"和罗巨济山居十咏 其九","f":"五言律诗","c":["且爱灯檠短，宁论剑铗长。","芝兰照春紫，编简著人香。","贺监聊吴语，昌黎岂楚狂。","豹文元炳蔚，未信雾能藏。"]},{"t":"和罗巨济山居十咏 其六","f":"五言律诗","c":["花柳春全盛，池塘燕学飞。","晚晴还小立，暮色不能归。","草远天无壁，苔深水有衣。","山居自清绝，不必扣禅扉。"]},{"t":"和罗巨济山居十咏 其五","f":"五言律诗","c":["园花皆手植，梅蕊独禁寒。","色与香无价，飞和雪作团。","数枝横翠竹，一夜绕朱栏。","不惜吟边苦，收将句里看。"]},{"t":"和罗巨济山居十咏 其一","f":"五言律诗","c":["世方争速化，渠独请真祠。","意在升沉外，官无冷热宜。","山如辋川画，地似习家池。","若道闲居懒，如何有十诗。"]},{"t":"和罗巨济山居十咏 其七","f":"五言律诗","c":["酒客来中散，诗僧约惠勤。","共听茅屋雨，添炷博山云。","万事休多问，三杯且一醺。","君看醉中语，不琢自成文。"]},{"t":"和罗巨济山居十咏 其四","f":"五言律诗","c":["漫浪真堪老，丁宁勿语人。","屐痕浑似齿，巾角小于纶。","从事固不恶，贤人也似醇。","空瓶未应卧，只恐恼比邻。"]},{"t":"和罗巨济山居十咏 其十","f":"五言律诗","c":["眼底无群子，毫端有百川。","脩名如揭月，馀事亦凌烟。","剩欲携藤去，相从听雨眠。","恐渠即霄汉，泉石罢潺湲。"]},{"t":"和罗巨济山居十咏 其二","f":"五言律诗","c":["老子朝慵起，春风苦唤行。","晴边犹著雪，寒后未闻莺。","偶见千峰翠，偏令两眼明。","倦来浑欲睡，无处避溪声。"]},{"t":"和罗巨济教授雪二首 其二","f":"五言律诗","c":["飞来须面旋，欲堕更横斜。","不遣诗人懒，惟禁酒力加。","镂冰初试手，剪水便成花。","谁会欧苏律，吟边别一家。"]},{"t":"和罗巨济教授雪二首 其一","f":"五言律诗","c":["天悭聊尔落，地暖未教深。","犹放遥岑碧，偏鸣密竹林。","似供愁里眼，小恼客边心。","诗卷开还阖，清寒溢素襟。"]},{"t":"和姜邦杰春坊再赠七字","f":"七言律诗","c":["可笑诗人死爱名，吻间长作候虫声。","鍊成九转丹砂著，赢得千茎白雪生。","政使古今传不朽，不知身世竟何成。","老夫老去真休去，一听梅山主夏盟。"]},{"t":"和济翁见寄之韵二首 其二","f":"五言律诗","c":["四海皆兄弟，何如真弟兄。","吾今有弟在，眼只为渠横。","剩欲驱涛壮，犹应倒峡清。","青春不可又，未欲傍长檠。"]},{"t":"和济翁见寄之韵二首 其一","f":"五言律诗","c":["只有高为累，元无俗可离。","正缘隔少面，添得许多诗。","杜老吟边树，山公醉处池。","犹须谋一笑，天许又何时。"]},{"t":"和济翁弟惠诗二首 其二","f":"五言律诗","c":["相思何所似，饥者食仁频。","此客非常客，诗人太逼人。","黄初那足过，子建巧能亲。","台阁俱知己，谁能荐子真。"]},{"t":"和济翁弟惠诗二首 其一","f":"五言律诗","c":["竟岁不得面，移书焉用频。","我方得吾弟，今岂有斯人。","海内友非少，谈间子独亲。","醉馀无浪语，尤见醉中真。"]},{"t":"和济翁惠诗","f":"五言律诗","c":["语妙浑忘夜，杯行未厌频。","平生憎俗子，胜处要吾人。","已结诗中社，仍居族里亲。","酒边不著句，何许见天真。"]},{"t":"和祝汝玉作举子语之句","f":"七言律诗","c":["玉奴何必减花奴，省识春风作画图。","临水隔花看走马，翻身射雁落彫弧。","词场君擅倾城色，诗社侬凋觅句须。","摩垒致师仰馀勇，政惭连叔答肩吾。"]},{"t":"和胡运干投赠","f":"七言律诗","c":["诗似离骚与国风，一襟尘土为君空。","来从月胁天心外，堕在冰瓯雪椀中。","判却青灯穷活计，早归紫禁策元功。","曲生未怕愁城峻，聊遣渠侬为九攻。"]},{"t":"和胡侍郎见简","f":"七言律诗","c":["花边雪里撚霜髭，怪底诗来妙一时。","聊复小吟开后悟，便应大用到前疑。","先生此曲难先和，著句如棋且著持。","每望南云尺有咫，其人甚远只嗟咨。"]},{"t":"和胡季永赴季文游园良集之韵聊以致私怨于独往云","f":"五言律诗","c":["有酒招元亮，无浆馈子居。","何曾三不速，焉用一行书。","乞饮殊无分，干时不已疏。","犹应慰大嚼，玉轴到吾庐。"]},{"t":"和贺升卿云庵升卿尝上书北阙既归去岁寄此诗今乃和以报之","f":"七言律诗","c":["贺子胸中自有山，结庵山底更云间。","遗才只道今无许，此士如何尚著闲。","未应万言直杯水，向来九虎守天关。","莫嫌久不还诗债，诗债从来隔岁还。"]},{"t":"和赵彦德旅怀是夕渠诵诗鼓琴","f":"七言律诗","c":["客间眼暗可逢人，公子诗琴却有神。","频掉乌纱知得句，快挥绿绮更留尘。","飘零不问今何夕，邂逅相欢意便亲。","作许生涯浑不恶，只愁我辈转须贫。"]},{"t":"和赵鼎辅府判投赠贺雪之句","f":"七言律诗","c":["登城放目雪光中，万水千山一色同。","逗晓月华犹在地，未春柳絮已随风。","忽传别驾赠佳句，道是频年当屡丰。","撚断冰须愁寡和，玉花飞绕正濛濛。"]},{"t":"和赵稷臣惠诗轴","f":"七言律诗","c":["今代宗英政骏贤，同居江介更同年。","别来十载长相忆，新听千诗喜欲颠。","爽似月华秋艳艳，韵如荷叶夏田田。","吹灯把玩舒还卷，老眼惺松夜不眠。"]},{"t":"和闽漕傅安道郎中送毛平仲诗韵寄谢惠书及诗","f":"七言律诗","c":["宣城讯后忽年馀，闽水风来又岁除。","人品只今推正始，诗声何止过黄初。","岂无天上同朝友，不寄山中半纸书。","珍重故人多问我，鬓毛半脱齿全疏。"]},{"t":"和徐衡仲惠诗","f":"七言律诗","c":["风骚坛上径雄趋，不作俳辞笑矣乎。","纸落云烟看醉旭，气含蔬笋薄僧殊。","夜来霜月千家满，雨后风埃半点无。","安得与君幽讨去，一觞一咏恼西湖。"]},{"t":"和益公见谢红都胜芍药之句","f":"七言律诗","c":["江西春好不关渠，只说平园绝世无。","牡丹百种移洛苑，海棠千树赛成都。","坐令浮花并浪蕊，谁敢涂铅更抹朱。","不应一朵翻阶艳，博得龙宫八十珠。"]},{"t":"和袁起岩郎中投赠七字二首 其二","f":"七言律诗","c":["道场山下弄山泉，餐菊纫兰万物先。","送眼飞鸿高四海，补天健笔震三川。","池塘碧草回春梦，衣钵黄梅肯夜传。","雨不饶人有新句，怨渠未许见全篇。"]},{"t":"和袁起岩郎中投赠七字二首 其一","f":"七言律诗","c":["故人一别两相思，不但平生痛饮师。","胸次五三真事业，笔端四六更歌诗。","闭门觅句今无己，刻意伤春古牧之。","卧雪高人家谱在，春风政著紫兰枝。"]},{"t":"和章汉直","f":"七言律诗","c":["宛水吹波解舫斋，南徐吊古上高台。","岸巾过我灯前语，赠句清于月底梅。","对著酒船手持蟹，管渠秋井骨生苔。","壁间挂舌那能许，一斗百篇真快哉。"]},{"t":"和章德茂少卿拉馆学之士四人访王德脩提干","f":"七言律诗","c":["西玉南金价则同，帝城相对落花风。","人如天上珠星聚，谈到尊中竹叶空。","白纻乌纱青宝玦，紫鸾黄鹄碧梧桐。","千龄此遇还孤往，恨杀灯前欠老翁。"]},{"t":"和符君俞卜邻","f":"七言律诗","c":["朱崖柳色欲春风，庾岭梅花尚雪容。","念子南归骑瘦马，只今谁解好真龙。","吾乡端是山水窟，何日来同丘壑胸。","白鹭青原不妨拣，诛茅结屋看何从。"]},{"t":"和萧伯和韵","f":"七言律诗","c":["桃李何忙开又零，老怀易感扫还生。","略无花片经人眼，谁道春风不世情。","睡去恐遭诗作祟，愁来当遣酒行成。","子能觅句庸非乐，未必胸中有不平。"]},{"t":"和萧伯振见赠","f":"七言律诗","c":["愁里真成日似年，懒边觅句此何缘。","雨荒山谷江西社，苔卧曹瞒台底砖。","顿有珠玑开病眼，旋生羽翼欲俱仙。","车斜韵险难为继，聊复酬公莫浪传。"]},{"t":"和萧伯振祷雨","f":"七言律诗","c":["云气微升又霍然，虚疑数点长三川。","渚东粳稻今无雨，社曲桑麻莫问天。","饿死何愁更平籴，野夫半去只荒田。","未辞托命长镵柄，黄独那能支一年。"]},{"t":"和傅景仁游清凉寺","f":"七言律诗","c":["旧时月过女墙头，风雨摧颓废不脩。","地老天荒无处问，松声滩响替人愁。","祥刑使者来何暮，吊古诗篇清更幽。","收拾江山入怀袖，却归讲席进鸿畴。"]},{"t":"和御制琼林宴赐进士余复等诗","f":"七言律诗","c":["圣主临轩士袖然，曲江花底宴群贤。","九天日月开清照，四海豪英看广延。","祗合致君上尧舜，不应侔德止宗宣。","草莱忧国从今始，记取云章第一篇。"]},{"t":"和曾无疑赠诗语及欧阳公事","f":"七言律诗","c":["乌帽红尘愧子陵，绿蓑青笠晚寻盟。","三千里外还家后，七十二回看月生。","与子两人长对酌，笑渠万古浪垂名。","醉翁若是真个醉，皂白何须镜样明。"]},{"t":"上巳日周丞相少保来访敝庐留诗为赠和谢","f":"七言律诗","c":["相国来临处士家，山间草木也光华。","高轩行李能过李，小队寻花到浣花。","留赠新诗光夺月，端令老子气成霞。","无论藏弆传诒厥，拈向田夫野老誇。"]},{"t":"和谢石湖先生寄二诗韵 其二","f":"七言律诗","c":["康鼎才来顿解颐，卢能自笑未经师。","分无枫落吴江句，博得池生春草诗。","木李抛将引琼玖，诗筒从此走符移。","蛤蜊龟壳非难办，只问先生汗漫期。"]},{"t":"和谢石湖先生寄二诗韵 其一","f":"七言律诗","c":["一张五色石湖云，天上吹来堕小轩。","化作虹桥倚钟阜，渡将老子到吴门。","黄钟路鼓鸣清庙，玉戚金支舞泰尊。","乃是寄侬诗数纸，却拈瑰怪向谁论。"]},{"t":"和韩子云惠诗","f":"五言律诗","c":["幸自同裘好，谁令异巷居。","恭承五个字，不但百车渠。","句法端何样，先生肯乞馀。","只容弹剑铗，敢道出无车。"]},{"t":"和虞军使易简字知能所寄唐律二首 其二","f":"七言律诗","c":["柴桑卧病一茅庐，或棹孤舟或命车。","道丧今朝逢祖谢，诗工独步过应徐。","万山不隔相思字，数月之间两得书。","廊庙方将访乔木，碧梧翠竹看新除。"]},{"t":"和虞军使易简字知能所寄唐律二首 其一","f":"七言律诗","c":["四海九州虞雍公，擎天一柱雪山峰。","厥孙俊逸诗无敌，下笔纵横剑有锋。","旧日门生今白发，故人书札照苍松。","掉头读得纱巾落，如对青云阮仲容。"]},{"t":"咏十里塘姜店水亭前竹林","f":"五言律诗","c":["一见此君面，荒村不是村。","斜阳与可笔，栖雀子猷魂。","客思方无那，诗愁得共论。","问渠能饮否，把酒酹霜根。"]},{"t":"咏绩溪道中牡丹二种 其一 丝头粉红","f":"七言律诗","c":["看尽徽苏谱与园，牡丹未见粉丝君。","春罗浅染醋红色，玉板蹙成裙摺纹。","头重醉馀扶不起，肌香淑处澹仍芬。","老夫生有栽花癖，客里相看为一醺。"]},{"t":"垂丝海棠盛开","f":"七言律诗","c":["垂丝别得一风光，谁道全输蜀海棠。","风搅玉皇红世界，日烘青帝紫衣裳。","懒无气力仍春醉，睡起精神欲晓妆。","举似老夫新句子，看渠桃杏敢承当。"]},{"t":"夜坐","f":"五言律诗","c":["欲雪天还惜，不风寒自生。","灯摇无定影，火作始然声。","又遣庭闱讯，悬知骨肉情。","履端犹几日，有梦未归程。"]},{"t":"夜坐","f":"七言律诗","c":["背壁青灯劝读书，窥窗素月唤看渠。","向来诸老端何似，未必千年便不如。","春后春前双雪鬓，江南江北一茅庐。","只愁夜饮无供给，小雨新肥半圃蔬。"]},{"t":"夜泊英州","f":"五言律诗","c":["旅病情先恶，愁眠梦更惊。","犬须终夕吠，月到五更明。","未解波头意，偏来枕底声。","平生厌行路，投老正追程。"]},{"t":"夜雨泊新淦","f":"五言律诗","c":["乱眼才迷树，回头已湿沙。","萧萧打篷急，点点入船斜。","此夕初为客，何时却到家。","馀樽曾卧否，唤取作生涯。"]},{"t":"夜热不寐晓起步溪上","f":"五言律诗","c":["夜气积到晓，微凉方满川。","老夫乘早起，落月正娟然。","拄杖丫疲檐，行人憩痛肩。","劳生谁独免，客路最堪怜。"]},{"t":"夜读诗卷","f":"五言律诗","c":["幽屏元无恨，清愁不自任。","两窗两横卷，一读一沾襟。","祗有三更月，知予万古心。","病来谢杯杓，吟罢重长吟。"]},{"t":"夜宿王才臣斋中睡觉闻风雪大作","f":"五言律诗","c":["雨外风非细，风中雪更飞。","夜声吹不尽，寒客卧相依。","一醉醒醒了，平生事事非。","终年才小款，明日又言归。"]},{"t":"夜寒独觉","f":"七言律诗","c":["儿啼惊觉梦中身，恰则华胥政问津。","脚到五更偏作冷，老来万事不如人。","若无窗月谁相伴，听尽鸡声不肯晨。","尚有布衾寒似铁，无衾似铁始言贫。"]},{"t":"姑苏馆上元前一夕陪使客观灯之集","f":"七言律诗","c":["节物催人又一年，银花莲炬照金尊。","麝䭔官样陪公宴，粉茧乡风忆故园。","何似儿孙谈草草，不妨灯火半昏昏。","人生行止谁能料，今夕苏州看上元。"]},{"t":"宛陵道中","f":"五言律诗","c":["溪缭双衣带，桥森百足虫。","伞声松径雨，巢影柳塘风。","犬误随行客，牛偏识牧童。","追程非要缓，路滑试匆匆。"]},{"t":"放船","f":"五言律诗","c":["岸岸人家住，门门面水开。","老翁扶杖立，稚子看船来。","一夜鸣春雨，诸滩涨绿醅。","顺流行自快，更著北风催。"]},{"t":"昌英叔门外小树木犀早开","f":"五言律诗","c":["触鼻无从觅，看林小缀黄。","旋开三两粟，已作十分香。","入夜偏相恼，搀先有底忙。","移床月枝下，坐对略传觞。"]},{"t":"明发弋阳县","f":"五言律诗","c":["灯市通宵沸，朝来解一空。","梅边霜似雪，雾外日如虹。","句妙元非作，人穷未必工。","忽惊家已远，身在大江东。"]},{"t":"明发石山","f":"五言律诗","c":["明发愁仍集，寒云又作屯。","悬知今定雨，正坐夜来暄。","便恐禾生耳，宁论客断魂。","山深更须入，闻有早梅村。"]},{"t":"明发周村弯","f":"七言律诗","c":["不住宽乡住瓮门，那知世上有乾坤。","环将峻岭包深谷，围出馀天与别村。","茅屋相挨无著处，花溪百摺不教奔。","江淮地迥寒无价，宣歙山寒更莫论。"]},{"t":"明发金陵晨炊义井","f":"五言律诗","c":["薄薄云收日，霏霏雨散池。","平波光去远，疏点晕来迟。","所部馀千里，初程第一诗。","先驱问行李，双堠且晨炊。"]},{"t":"明发青塘芦包","f":"七言律诗","c":["青塘无店亦无人，只有青蛙紫蚓声。","芦荻叶深蒲叶浅，荔支花暗楝花明。","船行两岸山都动，水入诸村海旋成。","回望越台烟雨外，万峰尽处五羊城。"]},{"t":"明发南屏","f":"七言律诗","c":["新晴在在野花香，过雨迢迢沙路长。","两度立朝今结局，一生行客老还乡。","犹嫌数骑传书札，剩喜千山入肺肠。","到得前头上船处，莫将白发照沧浪。"]},{"t":"明发黄土龛过高路","f":"七言律诗","c":["又过峥嵘两峡间，也无溪水也无田。","岭云放脚寒垂地，山麦掀髯翠拂天。","碧玉屏风吹不倒，青绫步障买无钱。","诗人富贵非人世，犹自凄凉意惘然。"]},{"t":"明发新淦晴快风顺约泊樟镇","f":"五言律诗","c":["雨到中宵歇，心知逗晓晴。","排云数峰出，漏日半江明。","风借轻帆便，天催懒客行。","不应樟镇酒，无意待人倾。"]},{"t":"松江晓晴","f":"七言律诗","c":["昨夜何缘不峭寒，今晨端要放晴天。","窗间波日如楼上，帘外霜风似腊前。","近水人家随处好，上春物色不胜妍。","归时二月三吴路，桃杏香中慢过船。"]},{"t":"松江莼菜","f":"七言律诗","c":["鲛人直下白龙潭，割得龙公滑碧髯。","晓起相传蕊珠阙，夜来失却水精帘。","一杯淡煮宜醒酒，千里何须更下盐。","可是士衡杀风景，却将膻腻比清纤。"]},{"t":"松江鲈鱼","f":"七言律诗","c":["鲈出鲈乡芦叶前，垂虹亭上不论钱。","买来玉尺如何短，铸出银梭直是圆。","白质黑章三四点，细鳞巨口一双鲜。","秋风想见真风味，祗是春风已迥然。"]},{"t":"枇杷","f":"五言律诗","c":["大叶耸长耳，一梢堪满盘。","荔支分与核，金橘却无酸。","雨压低枝重，浆流冰齿寒。","长卿今尚在，莫遣作园官。"]},{"t":"林宏才秉义挽辞","f":"五言律诗","c":["行尽江南北，于何隐去休。","福清好云谷，老子得菟裘。","风采今千古，英灵閟一丘。","庭阶俱玉树，仲氏立鳌头。"]},{"t":"欧阳伯威挽词","f":"五言律诗","c":["酒魄飞穿月，诗星流入脾。","豪来无一世，贫不上双眉。","泸水奇唐律，香城赏楚辞。","前身定东野，又得退之碑。"]},{"t":"武冈李簿回多问萧判官东夫","f":"七言律诗","c":["客有来从天一隅，相逢喜问子何如。","橘洲各自分马首，湘水更曾烹鲤鱼。","心近人遐长作恶，离多合少可无书。","得知安稳犹差慰，敢道韦郎迹也疏。"]},{"t":"泊平江百花洲","f":"七言律诗","c":["吴中好处是苏州，却为王程得胜游。","半世三江五湖棹，十年四泊百花洲。","岸傍杨柳都相识，眼底云山苦见留。","莫怨孤舟无定处，此身自是一孤舟。"]},{"t":"泊姑苏城外大雪二首 其二","f":"七言律诗","c":["今日晴光满碧空，也无雾雨也无风。","寂然窗户黄昏后，霍地琼瑶一望中。","千里湖山银作地，半篙舴艋玉为宫。","丁宁浮蚁非常绿，计会祥麟分外红。"]},{"t":"泊姑苏城外大雪二首 其一","f":"七言律诗","c":["夜烧银烛卷金卮，猛落天花醉未知。","若怯一寒都不看，却教六出更投谁。","开门片片洒人面，送眼山山呈玉肌。","才雪又晴晴又雪，吴中风物许清奇。"]},{"t":"泊樟镇","f":"五言律诗","c":["北地三接淅，重来四肃霜。","日斜秋树转，市散暮船忙。","波捲清中白，霞翻紫外黄。","汀沙浑换却，不记旧圜方。"]},{"t":"炙蒸饼","f":"五言律诗","c":["圆瑩僧何矮，清松絮尔轻。","削成琼叶片，嚼作雪花声。","炙手三家市，焦头五鼎烹。","老夫饥欲死，汝辈且同行。"]},{"t":"罗溪道中","f":"五言律诗","c":["每岁秋犹热，今年闰故凉。","松稀青有数，山远碧无常。","阵阵金风细，家家玉粒香。","祇言官路短，堠子暗添长。"]},{"t":"苦热登多稼亭二首 其二","f":"七言律诗","c":["吏散庭空便悄然，不须休日始偷闲。","鸥边野水水边屋，城外平林林外山。","偶见行人回首却，亦看老子立亭间。","暮蝉何苦催归急，只待凉生月半环。"]},{"t":"苦热登多稼亭二首 其一","f":"七言律诗","c":["日脚斜红欲暮天，倚栏垂手弄云烟。","两行相对树如许，一叶不摇风寂然。","剩欲啜茶还罢去，却愁通夕不成眠。","黑丝半把垂天外，白雨初生远岭边。"]},{"t":"视旱过雨","f":"五言律诗","c":["已旱何秋雨，无禾始水声。","病民岂天意，致此定谁生。","汤爪宁须剪，桑羊可缓烹。","小儒空自叹，得到凤凰城。"]},{"t":"诗人王季廉挽诗","f":"七言律诗","c":["手探卢溪颔下珠，词林再啸老于菟。","不餐烟火惟存骨，吟杀江山失却须。","锦里莺花馀故宅，灞桥风雪入新图。","只今醉卧长松下，犹要熊儿捉辔无。"]},{"t":"诗酒怀赵德庄","f":"五言律诗","c":["旧日张三影，今时赵半杯。","谁将牌印子，牒过草庐来。","一代风流尽，馀年鬓发催。","愁边对诗酒，怀抱向谁开。"]},{"t":"钓台","f":"五言律诗","c":["钓石三千丈，将何作钓丝。","肯离山水窟，去作帝王师。","小范真同味，玄英也并祠。","老夫归已晚，莫遣客星知。"]},{"t":"雨中问讯金沙","f":"词","c":["金沙道是殿群芳，不道荼?输一场。","十里红妆踏青出，一张锦被晒晴香。","只须旧荫已无暑，更走新条如许长。","若恨昨朝来草草，夜来风雨更禁当。"]},{"t":"雨后泊舟小箬回望灵山","f":"七言律诗","c":["灵山相识已平生，雨后精神见未曾。","一朵碧莲三万丈，数来花片八千层。","云姿雾态排天出，竹杖芒鞋欠我登。","羡杀峰头头上寺，厌山不看是诸僧。"]},{"t":"雨后郡圃行散","f":"七言律诗","c":["剑池一日百周遭，雨后闲来照鬓毛。","主管园林莺称意，巡行荷芰鹭宣劳。","不须见我还飞去，便与移文告汝曹。","一事恼人无问处，南山高是北山高。"]},{"t":"雨后清晓梳头读书怀古堂二首 其二","f":"五言律诗","c":["虫响馀宵寂，荷妆赴晓鲜。","梳头花雾里，照水柳风前。","旧雨仍今雨，新年胜故年。","登城有佳眺，秋稼正连天。"]},{"t":"雨后清晓梳头读书怀古堂二首 其一","f":"五言律诗","c":["宿雨犹凉在，晨阴欲霁初。","移床近秋水，正面对芙蕖。","团扇凄无彩，生衣凛觉疏。","欲归仍小住，更读数行书。"]},{"t":"雨夜","f":"五言律诗","c":["岁晚能无感，诗成只独哦。","萤光寒欲淡，秋雨暮偏多。","伴老贫无恙，留愁酒肯么。","吟虫将落叶，为我拍还歌。"]},{"t":"雨晴得毗陵故旧书","f":"七言律诗","c":["雀声只喜晚晴新，不管畦蔬雨未匀。","日与山光弄秋色，风将竹影扫窗尘。","多时浙右无消息，忽有书来问老人。","知我近来头白尽，寒暄语外更情亲。"]},{"t":"雨漱紫泥","f":"七言律诗","c":["道旁雨漱紫浮泥，高底成山下底溪。","谷转峰回云出岫，沙翻石走草缘堤。","波生蟋蟀漂新宅，水落蚍蜉识旧蹊。","大地山河亦如此，看来只是许高低。"]},{"t":"饯赵子直制置阁学侍郎出帅益州分未到五更犹是春二十八字为韵得犹字","f":"七言律诗","c":["锦水花潭照碧油，西清学士旧鳌头。","随身琴鹤如清献，治蜀功名更武侯。","无晚十行看暮召，不应三峡隔辰犹。","垂杨管得人离别，舞破春风劝玉舟。"]},{"t":"驾幸聚景晚归有旨次日歇泊","f":"七言律诗","c":["身在长安梦故山，故山未去且长安。","落红满地莫教扫，新绿隔墙聊借看。","竹叶劝人行乐事，榴花为我遣春寒。","赐休又得明朝睡，不问三竿与两竿。"]},{"t":"南海东庙浴日亭","f":"七言律诗","c":["南海端为四海魁，扶胥绝境信奇哉。","日从若木梢头转，潮到占城国里回。","最爱五更红浪沸，忽吹万里紫霞开。","天公管领诗人眼，银汉星槎借一来。"]},{"t":"南海陶令曾送水沈报以双井茶二首 其一","f":"七言律诗","c":["岭外书来谢故人，梅花不寄寄炉熏。","瓣香急试博山火，两袖忽生南海云。","苒惹须眉清入骨，萦盈窗几巧成文。","琼琚作报那能办，双井春风辍一斤。"]},{"t":"南海陶令曾送水沈报以双井茶二首 其二","f":"七言律诗","c":["沈水占城第一良，占城上岸更差强。","黑藏骨节龙筋瘠，斑出文章鹧翼张。","衮尽残膏添猛火，熬成熟水趁新汤。","素馨熏染真何益，毕竟输他本分香。"]},{"t":"雨霁登连天观","f":"七言律诗","c":["高台十日不曾登，雨后支藤拄晚晴。","城外诸峰迎落照，松根细草总斜明。","眼穿岭北书不到，秋入海南愁顿生。","只有荷花旧相识，风前翠盖为人倾。"]},{"t":"南溪早春","f":"七言律诗","c":["还家五度见春容，长被春容恼病翁。","高柳下来垂处绿，小桃上去末梢红。","卷帘亭馆酣酣日，放杖溪山款款风。","更入新年足新雨，去年未当好时丰。"]},{"t":"夏日杂兴","f":"七言律诗","c":["金陵六月晓犹寒，近北天时较少暄。","打尽来禽那待熟，半开萱草已先翻。","独龙冈顶青千摺，十字河头碧一痕。","九郡报来都雨足，插秧收麦喜村村。"]},{"t":"宣歙道中","f":"七言律诗","c":["天齐玉立万孱颜，三日深行紫翠间。","便是昨来千佛阁，望中见此两州山。","诗家寒刮少陵骨，宫样高梳西子鬟。","祗好遥看莫登览，今晨登处鬓都斑。"]},{"t":"将至醴陵","f":"五言律诗","c":["行尽崎岖峡，初逢熨帖坡。","寒从平野有，雨傍远山多。","也自长沙近，其如此路何。","披文浑不恶，冻手奈频呵。"]},{"t":"尝瓜二首 其二","f":"五言律诗","c":["风露盈篮至，甘香隔壁闻。","绿抟罂一搦，白裂玉平分。","藓甃开冰段，梅山失火云。","老夫供晚酌，不用办膻荤。"]},{"t":"尝瓜二首 其一","f":"五言律诗","c":["病骨那禁暑，衰年更作愁。","有风依旧热，初伏几时秋。","瓜果谁新饷，馋涎小忍休。","金盆井花水，且看玉双浮。"]},{"t":"尝枸杞","f":"七言律诗","c":["芥花菘莟饯春忙，夜吠仙苗喜晚尝。","味抱土膏甘复脆，气含风露咽犹香。","作齑淡著微施酪，芼茗临时莫过汤。","却忆荆溪古城上，翠条红乳摘盈箱。"]},{"t":"待次临漳诸公荐之易地毗陵自愧无济剧才上章丐祠","f":"五言律诗","c":["亦岂真辞禄，谁令自不才。","更须三釜恋，未放两眉开。","道我今贫却，何朝不饭来。","商量若为可，杜宇一声催。"]},{"t":"故太恭人董氏挽词五首 其五","f":"五言律诗","c":["溧县初栖凤，金陵复木牛。","重来喜城郭，一夕閟山丘。","终始非无数，东西岂自由。","铭旌二千里，处处哭归舟。"]},{"t":"故太恭人董氏挽词五首 其四","f":"五言律诗","c":["九秩开鸿算，前春祝寿觞。","秦淮作椒柏，钟阜当星香。","花压藤舆重，游回绣幰凉。","诸台谁有母，羡杀綵衣郎。"]},{"t":"故太恭人董氏挽词五首 其三","f":"五言律诗","c":["亲见卿为月，频移使者星。","藻虚南涧碧，萱落北堂青。","遗下新褕狄，空传训宁馨。","又孙还又子，玉树满阶庭。"]},{"t":"故太恭人董氏挽词五首 其二","f":"五言律诗","c":["贫是儒家事，谁贫奉直如。","也无一瓢饮，劣有半床书。","妇妇能攻苦，卿卿不负渠。","竟令鸿与侃，相继大吾闾。"]},{"t":"故太恭人董氏挽词五首 其一","f":"五言律诗","c":["谁别夫人孝，惟天与病姑。","每云吾妇在，底用别人扶。","愉色春相似，弥年倦更无。","苍苍不汝报，种黍定生菰。"]},{"t":"故少师张魏公挽词三章 其一","f":"五言律诗","c":["出昼民犹望，回军敌尚疑。","时非不吾以，天未胜人为。","自别知何恙，从谁话许悲。","一生长得忌，千载却空思。"]},{"t":"故少师张魏公挽词三章 其二","f":"五言律诗","c":["手麾日三舍，身驭月重轮。","始是岷峨秀，前无社稷臣。","向来元破斧，何用更洪钧。","只使江淮草，明年不作春。"]},{"t":"故少师张魏公挽词三章 其三","f":"五言律诗","c":["读易堂边路，曾闻赤舄声。","心从画前到，身在易中行。","忧国何缘寿，思亲岂欲生。","不应永州月，犹傍两窗明。"]},{"t":"故王氏令人挽诗二首 其二","f":"五言律诗","c":["西掖梧方茂，南濒藻已芜。","谢庭风絮远，潘室月窗孤。","有训才吾子，无人乳阿姑。","吊宾成白鹤，卜地得青乌。"]},{"t":"故王氏令人挽诗二首 其一","f":"五言律诗","c":["贝叶参祇树，蓍簪当副笄。","来嫔舍人样，如古大夫妻。","鸾诰金花湿，芝庭玉树齐。","药成奔月去，寂寞海山西。"]},{"t":"故恭人刘氏挽词","f":"五言律诗","c":["雨露低蘋沼，芝兰上桂林。","鱼轩帘蹙绣，鸾纸诰涂金。","死者夫何恨，归欤乃宿心。","不偕君子老，愁绝白头吟。"]},{"t":"春半雨寒牡丹殊无消息","f":"七言律诗","c":["今岁芳菲尽未忙，去年二月牡丹香。","寒暄不定春光晚，荣落俱迟花命长。","才一两朝晴炫野，又三四阵雨鸣廊。","鞓红魏紫拳如蕨，而况姚家进御黄。"]},{"t":"春尽有感","f":"七言律诗","c":["等春不到怨春迟，又是红稀绿满枝。","雨后晚花犹好在，槛前残醉欲醒时。","百年人事皆如许，千载诗声亦浪垂。","金印不争争钓石，更饶争得鬓边丝。"]},{"t":"春尽感兴","f":"七言律诗","c":["春事匆匆掠眼过，落花寂寂奈愁何。","故人南北音书少，野渡东西芳草多。","笋借一风争作竹，燕分数子别成窠。","青灯白酒长亭夜，不胜孤舟兀绿波。"]},{"t":"春夜无睡思虑纷扰","f":"七言律诗","c":["不堪万虑搅中肠，打破愁城入醉乡。","酒力尽时还又动，春宵短后却成长。","浮思闲念纷无数，飞絮游丝遍八荒。","看到东窗窗欲白，忽然一梦到羲皇。"]},{"t":"春雨呈袁起岩","f":"七言律诗","c":["昨日晴暄尽十分，无端寒湿复今晨。","苍颜华发差排老，急雨颠风屏当春。","只有观书堪遣日，从来病眼不如人。","诗名满世真何用，更赚先生愿卜邻。"]},{"t":"春晚往永和","f":"五言律诗","c":["春事已如许，山居殊未知。","绿光风度麦，白碎日翻池。","景好怀翻恶，人嬉我独悲。","郊行聊著眼，兴到漫成诗。"]},{"t":"春寒早朝","f":"词","c":["十载江湖今又归，朝鸡不许夙兴迟。","每闻扑鹿初鸣处，正是䰒松好睡时。","病眼生憎红蜡烛，晓光未到碧桃枝。","谁能马上追前梦，坐待金门放玉?。"]},{"t":"春晴怀故园海棠二首 其二","f":"七言律诗","c":["竹边台榭水边亭，不要人随只独行。","乍暖柳条无气力，淡晴花影不分明。","一番过雨来幽径，无数新禽有喜声。","只欠翠纱红映肉，两年寒食负先生。"]},{"t":"春晴怀故园海棠二首 其一","f":"七言律诗","c":["故园今日海棠开，梦入江西锦绣堆。","万物皆春人独老，一年过社燕方回。","似青如白天浓淡，欲堕还飞絮往来。","无那风光餐不得，遣诗招入翠琼杯。"]},{"t":"昨日访子上不遇裴回庭砌观木犀而归再以七言乞数枝","f":"七言律诗","c":["昨携儿辈扣云关，绕遍岩花恣意看。","苔砌落深金布地，水沉烝透粟堆盘。","寄诗北阮赊秋色，供我西窗当晚餐。","小朵出丛须折却，莫教折破碧团栾。"]},{"t":"泉声","f":"七言律诗","c":["初闻蟹眼雪花声，忽有仙人玉佩鸣。","时作微吟清入骨，又成幽咽怨多情。","问知古涧飞泉落，起看寒泓绕石行。","欲解尘缨聊一濯，无尘可濯濯谁缨。"]},{"t":"洪丞相挽辞二首 其二","f":"五言律诗","c":["家谱忠仍孝，词林博更宏。","牧羝无是子，雏凤有难兄。","谁谓身非达，其如道不行。","青蝇满天地，白日转清明。"]},{"t":"洪丞相挽辞二首 其一","f":"五言律诗","c":["乾道扶初旭，中台焕五云。","才登右丞相，已拜大观文。","胡不迟期月，看渠集茂勋。","一朝惊玉折，千载叹芝焚。"]},{"t":"癸巳省宿咏南宫小桃","f":"五言律诗","c":["孤坐南宫悄，桃花故故红。","晴曛半脸日，寒惨数须风。","昔岁山村里，春光痛饮中。","不烦渠伴宿，今我已衰翁。"]},{"t":"癸亥上巳即事","f":"五言律诗","c":["怪底风光好，还当上巳辰。","柳莺樊子口，梁燕赵家身。","花落春容瘦，阴浓夏意新。","晒书仍焙药，幽事也劳神。"]},{"t":"秋夕书怀","f":"五言律诗","c":["老去还多感，归来政倦游。","数峰愁外月，一叶静边秋。","偶忆平生事，真供独笑休。","灯花吾会得，村酒恰当篘。"]},{"t":"秋日见橘花二首 其二","f":"五言律诗","c":["不夜非关月，舞风也自香。","著花能许细，落子不多长。","玉糁开犹半，金须撚更强。","得秋何恨晚，映暑却生凉。"]},{"t":"秋日见橘花二首 其一","f":"五言律诗","c":["花净何须艳，林深不隔香。","初闻无处觅，小摘莫令长。","春落秋仍发，梅兼雪未强。","缥瓷汲寒甃，浅浸一枝凉。"]},{"t":"秋月","f":"五言律诗","c":["夜气凉于水，高斋可当楼。","古来除却月，此外更无秋。","寒入兰心劲，光随菊脚流。","惟愁清不极，清极却成愁。"]},{"t":"秋典","f":"五言律诗","c":["宿有青霞愿，惟应白鹭知。","风烟聊晚望，山水入秋宜。","老里还多病，贫中却剩诗。","浪愁馀热在，会自有凉时。"]},{"t":"秋怀","f":"七言律诗","c":["随分哦诗足散愁，老怀何用更冥搜。","聿来胥宇蚁移穴，无以为家燕入秋。","盖世功名吹剑首，平生忧患淅矛头。","从今归去便归去，未到无颜见白鸥。"]},{"t":"秋夜读书","f":"五言律诗","c":["稚子慵都睡，先生唤不应。","虫声窗外月，书册夜深灯。","半醉聊今古，千年几废兴。","有怀人未会，不乐我何曾。"]},{"t":"秋雨初霁","f":"七言律诗","c":["松竹阴寒分外苍，芭蕉花湿梦中香。","抽身朱墨尘埃里，入眼山林气味长。","今日更无秋热去，晓晴犹带雨馀凉。","却将白发三千丈，缲作霜丝补锦囊。"]},{"t":"秋凉晚酌","f":"七言律诗","c":["寄老山林度懒残，新秋又是一年年。","青编翠竹风窗月，白酒红蕖水槛天。","暑欲谢时偏更毒，侬当醉后恕渠颠。","者稀尚隔来年在，且釂今宵药玉船。"]},{"t":"秋圃","f":"五言律诗","c":["何处秋深好，山林处士家。","青霜红碧树，白露紫黄花。","一熟雠频雨，朝晴祷暮霞。","连宵眠不著，犹自爱新茶。"]},{"t":"秋热追凉池上","f":"五言律诗","c":["圃迥人全寂，池清虑自消。","萍根微著水，荷叶欲穿桥。","今岁知何故，秋阳尔许骄。","追凉犹有处，此老未无聊。"]},{"t":"秋晚过泉口","f":"五言律诗","c":["日色全无热，秋凉不似初。","行人惊翡翠，掠水度芙蕖。","平野一回顾，远山千有馀。","谁令贪眺望，却道废看书。"]},{"t":"胡季永挽词二首 其二","f":"五言律诗","c":["一昨官都下，同时寄客间。","相从湖上寺，览遍浙西山。","骏足应千里，彪文未一斑。","霜风吹病眼，老泪为渠潸。"]},{"t":"胡季永挽词二首 其一","f":"五言律诗","c":["澹庵潜圣学，未许外人传。","门里存衣钵，吟边可管弦。","浣花宗武辔，儋耳小坡船。","绿鬓成黄壤，从今更问天。"]},{"t":"荔枝堂昼憩","f":"七言律诗","c":["荔子阴中风绝凉，菖蒲节后日偏长。","落残数柄荷花蕊，浸得一瓶泉水香。","多病早衰非破砚，欲行复倦且胡床。","曲江近北差迟暑，不道江山胜五羊。"]},{"t":"蚤起秣陵镇二首 其二","f":"五言律诗","c":["山路祇言迥，农家俱夙兴。","短长群稚子，回避一田塍。","随犬能知路，骑牛底用绳。","兹行有胜事，何处不丰登。"]},{"t":"蚤起秣陵镇二首 其一","f":"五言律诗","c":["人趁村中市，鸡鸣担上笼。","忽看一天紫，未吐半轮红。","谁撼扶桑露，吹来杨柳风。","诗肩忍凉冷，已出两臞峰。"]},{"t":"蚤谒景灵宫闻子规","f":"七言律诗","c":["帝里都无个里宽，苑深地禁到应难。","蔚然绿树去天近，上有子规啼月残。","便觉恍如还故里，不知闻处是长安。","野蔷薇发桐花落，孤负南溪老钓竿。"]},{"t":"贺建康帅余处恭迎宝公祷雨随应","f":"七言律诗","c":["大士多时不入城，入城犹未炷炉熏。","忽吹淮水千峰雨，不费钟山半朵云。","桑叶秧苗俱起舞，葵花萱草亦欢欣。","尚书款送公归去，留下丰年二十分。"]},{"t":"贺皇太子九月四日生辰二首 其二","f":"七言律诗","c":["典学光阴璧不如，简编灯火卷还舒。","极知储后勤稽古，却是儒生懒读书。","心到帝王图籍外，手追雅颂国风初。","人间未见瑶山集，十倍曹丕尚有馀。"]},{"t":"贺皇太子九月四日生辰二首 其一","f":"七言律诗","c":["金茎分露与黄花，银汉非烟作瑞霞。","万国元良当诞节，重轮日月正光华。","祖尧父舜真千载，禹子汤孙更一家。","清晓寿觞天上至，蟠桃如瓮枣如瓜。"]},{"t":"贺皇太子九月四日生辰四首 其四","f":"五言律诗","c":["继照姿天纵，分阴学日勤。","橘中招绮夏，瓜处屏伾文。","老别鱼竿月，来依鹤禁云。","还将古为鉴，聊当野人芹。"]},{"t":"贺皇太子九月四日生辰四首 其三","f":"五言律诗","c":["重九吹花节，千龄梦日时。","东朝分菊水，南内赐萸枝。","禹酒无多酌，尧樽更一卮。","三宫千万寿，剩费若干诗。"]},{"t":"贺皇太子九月四日生辰四首 其二","f":"五言律诗","c":["代邸躬仁俭，汤孙世圣贤。","谁云无二日，今恰见三天。","甲观初寒夕，神光似昼然。","前星那解老，何但八千年。"]},{"t":"贺皇太子九月四日生辰四首 其一","f":"五言律诗","c":["地出雷初震，天升日更重。","高飞千里鹄，潜跃九渊龙。","隆准如高帝，虬须似太宗。","八荒阴赐里，户户是华封。"]},{"t":"贺皇孙平阳郡王十月十九日生辰","f":"五言律诗","c":["玉历当千运，天潢第一源。","本支尧百世，有道宋曾孙。","接武前星曜，依光太极尊。","年年会庆节，更庆茁兰孙。"]},{"t":"贺澹庵先生胡侍郎新居落成二首 其二","f":"七言律诗","c":["眼高不肯住清都，梦绕江南水竹居。","却入青原更青处，饱看黄本硬黄书。","剪裁风月聊堪醉，拆洗乾坤正要渠。","赐宅不应公得免，未知北第似林庐。"]},{"t":"贺澹庵先生胡侍郎新居落成二首 其一","f":"七言律诗","c":["清庙欹斜一笑扶，归来四壁亦元无。","可怜拙计输馀子，住破僧房始结庐。","三径非遥人自远，万间不恶我何须。","冥搜善颂终难好，贺厦真成燕不如。"]},{"t":"赴文德殿听麻仍拜表","f":"七言律诗","c":["苍龙观阙启槐宸，白玉阶除振鹭群。","仗外诸峰献松雪，霜前一雁度宫云。","舍人就日宣麻制，丞相瞻天进表文。","夙退自欣还自笑，素餐便当策殊勋。"]},{"t":"赵通判恭人周氏挽辞","f":"五言律诗","c":["早与梁鸿隐，中随士会归。","一门忠义气，千古日星晖。","紫告金花诏，青灯锦字机。","西峰今夜月，坟是昔人非。"]},{"t":"追和尤延之检详紫宸殿贺雪","f":"七言律诗","c":["锡山诗老立层霄，黄竹赓歌宴在瑶。","有客梦中闻雪作，曲肱篷底信船摇。","遥知端叶飘香袖，笑向梅花趁早朝。","未叹山人负猿鹤，负渠缩项与长腰。"]},{"t":"送丁子章将漕湖南三首 其三","f":"五言律诗","c":["半世行天下，同心寡友生。","故人今又去，此意向谁倾。","白发三更语，青灯一点明。","看渠还玉署，老我正归耕。"]},{"t":"送丁子章将漕湖南三首 其二","f":"五言律诗","c":["湖外游曾漫，荒馀好在么。","山应依样瘦，民岂似田多。","不是无风物，其如费拊摩。","人言补外乐，且道定如何。"]},{"t":"送丁子章将漕湖南三首 其一","f":"五言律诗","c":["岳麓猿声里，湘流雁影边。","自天持一节，到日是新年。","身退名逾重，今稀古则然。","黄花非不好，只是插离筵。"]},{"t":"送丁牧仲新除奉常寺簿入朝","f":"七言律诗","c":["帝念潜龙雪邸臣，宠光玉树照青春。","家藏履舄星辰旧，天借旂常日月新。","从此云霄君稳步，向来鹓鹭我曾邻。","曲台簿正多廊庙，西府璇枢是一人。"]},{"t":"送王季山主簿省觐枢府","f":"楚辞体","c":["六馆名流王季山，十年风雨短檠寒。","不曾文字饶群子，勉为庭闱就一官。","伯也腾身紫极上，叔兮著眼白云端。","会当再奏河东赋，姓字从头揭榜看。"]},{"t":"送乡余文明劝之以归","f":"七言律诗","c":["一别高人又十年，霜筋雪骨健依然。","席门未害车多辙，斗酒尚能诗百篇。","苍狗白衣俱昨梦，长庚孤月自青天。","故山松菊平安在，何日归欤解钓船。"]},{"t":"送子仁侄南归二首 其一","f":"五言律诗","c":["酒为吾人绿，花知九日黄。","风灯秋焰冷，霜雁夜声忙。","爱子文无对，嗟予老更狂。","相分即相见，不待半年强。"]},{"t":"送子仁侄南归二首 其二","f":"五言律诗","c":["再岁来相款，三杯忽语离。","忍将垂老泪，滴作送行诗。","子去侬犹住，身留梦亦随。","南溪旧风月，千万寄相思。"]},{"t":"送广帅秩满之官丹阳二首 其二","f":"七言律诗","c":["南海元戎禁从臣，却升北斗捧星辰。","回头五岭忽千里，屈指十贤添一人。","笑别广平堂下月，归看太极殿前春。","一尊话别端何有，绿水青山更白云。"]},{"t":"送广帅秩满之官丹阳二首 其一","f":"七言律诗","c":["北门卧护要耆英，小试胸中十万兵。","天借金山吟落月，身兼铁瓮作长城。","何如岭上因归路，摘取梅酸去作羹。","已有紫泥教诣阙，便应留住付钧衡。"]},{"t":"送马庄父游金陵","f":"七言律诗","c":["东华踏遍软红尘，却去秦淮钓月轮。","朱雀乌衣王谢宅，黄旗紫盖晋梁春。","江山拾得风光好，杖屦归来句子新。","祗恐参卿署军事，醲薰荐墨到槐宸。"]},{"t":"送文黼叔主簿之官松溪","f":"楚辞体","c":["乃翁只解日争晖，不解尘中脱叔兮。","杨簿故应过习簿，建溪好处说松溪。","此行诗句何须觅，满路春光总是题。","飞上金銮稳安脚，竹林分付一莺啼。"]},{"t":"送王文伯上舍归丰城兼简何侍郎","f":"七言律诗","c":["碧落先生少可人，银钩茧纸苦称君。","谈间口吸西江水，句里家传南浦云。","千里端能来命驾，一尊得与细论文。","还家剩草三千牍，看策平津第一勋。"]},{"t":"送王吉州宣子舍人知明州二首 其二","f":"五言律诗","c":["碧海翻词笔，清霜逼谊风。","不应盛名下，未著玉堂中。","剩欲公留此，其如帝望公。","从今摩病眼，看到火城红。"]},{"t":"送王吉州宣子舍人知明州二首 其一","f":"五言律诗","c":["满听除书好，明州胜吉州。","又为邦伯去，政坐治声优。","过阙端能遇，居中定作留。","新民莫漫喜，竹马不须休。"]},{"t":"送王成之中书舍人使虏","f":"七言律诗","c":["帝遣唐朝第一人，玉门关外赐金银。","使星芒动梅花早，汉月光垂塞草春。","故国山河迎诏旨，中原父老识词臣。","十分宣慰华戎了，归为君王转大钧。"]},{"t":"送王季德提刑宝文少卿","f":"七言律诗","c":["宝储依旧接英游，荡节何曾远藻旒。","卿月使星银汉晓，绣衣綵服太湖秋。","豺当道上狐何问，鹰击霜前兔已愁。","火急平反供一笑，紫荷玉笋待君侯。"]},{"t":"送王恭父监丞倅潼川","f":"七言律诗","c":["淡墨抡魁政少年，蓬山璧水得诗仙。","集贤学士看文笔，国子先生费酒钱。","濯锦江头频入梦，桃花水面送归船。","平分风月真聊尔，不日来朝尺五天。"]},{"t":"送丘宗卿帅蜀三首 其三","f":"七言律诗","c":["蜀人诧蜀不能休，花作江山锦作州。","老我无缘更行脚，羡君来岁领遨头。","碧鸡金马端谁见，酒肆琴台访昔游。","收入西征诗集里，忆侬还解寄侬不。"]},{"t":"送丘宗卿帅蜀三首 其二","f":"七言律诗","c":["谕蜀宣威百万兵，不须号令自精明。","酒挥勃律天西椀，鼓卧蓬婆雪外城。","二月海棠倾国色，五更杜宇说乡情。","少陵山谷千年恨，不遇丘迟眼为青。"]},{"t":"送丘宗卿帅蜀三首 其一","f":"七言律诗","c":["人似隆中汉卧龙，韵如江左晋诸公。","四川全国牙旗底，万里长江羽扇中。","玉垒顿清开宿雾，雪山增重起秋风。","近来廊庙多西帅，出相谁言只在东。"]},{"t":"送永州唐德明","f":"五言律诗","c":["忽报故人至，知从何许来。","满怀俱玉雪，半语不尘埃。","聚散千江月，悲驩一酒杯。","樯乌有底急，一夕百相催。"]},{"t":"送伍耀卿监庙西归","f":"七言律诗","c":["敬轩居士子胥孙，河出昆仑学有源。","秋鹗屡看书祢表，春风两度对尧轩。","钓竿已拂珊瑚树，拄笏新沾雨露恩。","暂作祝融香火吏，裹轮早晚到柴门。"]},{"t":"送刘孔章县尉得官西归","f":"七言律诗","c":["早宴黄花诣粉闱，晚挼春草染朝衣。","却提猛士弓弯月，去扫封狐雪打围。","绿鬓朱颜君胜我，青春白日我思归。","何时共瀹青原茗，下看江鸥来去飞。"]},{"t":"送刘童子","f":"七言律诗","c":["天上麒麟地上行，掌中珠玉月中生。","澜翻六籍吞诸子，声动三公及九卿。","别有诗书真事业，不应童子是勋名。","长成来奏三千牍，桃李春风冠集英。"]},{"t":"送刘德脩殿院直阁将漕潼川二首 其二","f":"七言律诗","c":["半世西风吹盛名，晚同朝路慰平生。","一言半语到金石，四海九州成弟兄。","雪岭锦城君理棹，青鞋黄帽我归耕。","长江万里通吴蜀，逢著双鱼各寄声。"]},{"t":"送刘德脩殿院直阁将漕潼川二首 其一","f":"七言律诗","c":["乌府何缘著佞臣，紫皇亲擢得斯人。","金丹半粒回元气，玉宇崇朝作好春。","不惜孤身轻一叶，坐令九鼎重千钧。","万牛回首求梁栋，未要沱江理钓缗。"]},{"t":"送孙从之司业持节湖南二首 其二","f":"七言律诗","c":["白头灯火共书林，自少论交老慰心。","官职坏人饧里鸩，忠贤到骨锻中金。","朝阳鸣凤祗今见，夜雨对床何日寻。","回雁峰前雁回后，紫薇红药待渠吟。"]},{"t":"送孙从之司业持节湖南二首 其一","f":"七言律诗","c":["全家先遁却谁知，匹马西归也大奇。","出昼莫嫌三宿恋，坏麻不待七年迟。","风生折槛人无古，水绕圜桥士有师。","六一澹庵乔木在，今秋新长雪霜枝。"]},{"t":"送孙检正德操龙图出知镇江二首 其二","f":"七言律诗","c":["看花走马绍兴间，彼此春风各少年。","黄甲诸儒今几许，白头同舍省东偏。","昨宵归梦月千里，馀债欠君诗两篇。","已乞闽山一窠阙，老身只要早归田。"]},{"t":"送孙检正德操龙图出知镇江二首 其一","f":"七言律诗","c":["润州太守去明州，谁寄长江万里流。","鸡省却烦三语掾，龙章卧护两淮秋。","古来北府多名酒，今复南徐说胜游。","聊奉双亲小行乐，即持荷橐侍宸旒。"]},{"t":"送朱师古龙图少卿帅潼川二首 其二","f":"七言律诗","c":["甲戌花时策集英，相看须鬓各青青。","曲江初别春三月，北阙重来再一星。","百石去官君似邴，千年归鹤我输丁。","因书若寄杨员外，莫道山寒少茯苓。"]},{"t":"送朱师古龙图少卿帅潼川二首 其一","f":"七言律诗","c":["璧水蓬山遍羽仪，颂台公府更光辉。","紫荷到眼垂持橐，黄菊关心便拂衣。","鬻子运筹年尚少，买臣衣绣日思归。","小烦谕蜀须还报，却袖香烟侍太微。"]},{"t":"送次公子之官安仁监税","f":"五言律诗","c":["汝仕今差晚，家庭莫恨离。","学须官事了，廉忌世人知。","争进非身福，临民只母慈。","关征岂得已，龙断欲何为。"]},{"t":"送何一之右司出守平江","f":"七言律诗","c":["十年一别再从游，又见鱼书拜彻侯。","人物只今何水部，风流不减柳苏州。","白蘋洲上春传语，乌鹊桥边草唤愁。","报政不应迟五月，莺花紫禁伫归舟。"]},{"t":"送何主簿归丰城","f":"五言律诗","c":["众里非无士，难中却几人。","如何新帅泽，偏作此邦春。","未要栖鸾恨，方看报主身。","青灯一樽酒，聊复话酸辛。"]},{"t":"送吴敏叔待制侍郎","f":"七言律诗","c":["脚踏鸡翘豹尾间，心飞碧岫白云端。","人看疏傅如图画，帝念严光返钓滩。","玉殿松班唐次对，竹宫茅立汉祠官。","自怜病鹤樊笼底，万羡冥鸿片影寒。"]},{"t":"送吴监丞季行知简州","f":"七言律诗","c":["勋烈涪阳异姓王，手扶西极汉天长。","有孙文武千人杰，透纸风骚万字香。","小涉移中公事笔，又怀剑外史君章。","同朝多日相从少，不唱阳关也断肠。"]},{"t":"送庐陵丞刘约之","f":"七言律诗","c":["忠显闻孙定不虚，西枢犹子故应殊。","鸾停梧上遗风在，雁进松间得句无。","剩有老农歌赞府，未多荐墨送清都。","晦翁若问诚斋叟，上下千峰不要扶。"]},{"t":"送庐陵宰赵材老","f":"七言律诗","c":["赵侯龙种秀天潢，金玉肝脾锦绣肠。","未复九人黄阁相，犹堪三字紫微郎。","饥餐兰菊枝枝月，醉洒云烟句句霜。","谁与邦民颂遗爱，老夫端欲续甘棠。"]},{"t":"送庐陵宰黄伯庸赴召","f":"七言律诗","c":["君寄梅花道别肠，我攀官柳送归艎。","东都循吏似名茂，南浦诗人更姓黄。","白鹭青原留惠爱，苍苔红药入篇章。","故人若问诚斋叟，化作沙鸥弄夕阳。"]},{"t":"送张元直尉盐官二首 其二","f":"五言律诗","c":["溧水孟东野，南昌梅子真。","平生一少府，千载两高人。","白马松梢寺，朱旗雪外春。","村行如得句，寄我大江滨。"]},{"t":"送张元直尉盐官二首 其一","f":"五言律诗","c":["璧水寒齑客，春闱擢桂郎。","折腰端小耐，整翮未须忙。","德进官无小，诗癯誉更香。","会看两鸂鶒，飞下蓼滩傍。"]},{"t":"送张定叟二首 其二","f":"七言律诗","c":["紫岩衣钵付南轩，介弟曾同半夜传。","师友别来真梦耳，江湖相对各潸然。","但令门户无遗恨，何必功名在早年。","君向潇湘我闽粤，寄书只在寄茶前。"]},{"t":"送张定叟二首 其一","f":"七言律诗","c":["直上云霄未遣休，分符京兆帝王州。","赤丸窟里无白额，碧落班中政黑头。","两地好官才半武，扁舟归兴恰中秋。","只应银信从天降，莫恋融峰与橘洲。"]},{"t":"送李伯珍主管西归","f":"七言律诗","c":["淡墨题名冠子衿，一星州县叹浮沈。","向来寄我南楼赋，不减古人东武吟。","几阁文书聊韫玉，兰台笔札即紬金。","李家兄弟鹓鸾侣，一日双飞入上林。"]},{"t":"送李制干季允擢第归蜀","f":"七言律诗","c":["玉立长身太史公，诸郎个个有家风。","高文大册传书种，怨句愁吟恼化工。","鸿雁双衔月宫桂，鹓雏独恋蜀山桐。","何如天网笼云表，三凤都归上苑中。"]},{"t":"送沈虞卿秘监脩撰将漕江东二首 其二","f":"七言律诗","c":["再入脩门访旧游，故人相见喜还愁。","茂林脩竹君髯碧，折苇枯荷我鬓秋。","莫把升沈著怀抱，古来贤圣几公侯。","一尊追送江东棹，梦逐清波弄白鸥。"]},{"t":"送沈虞卿秘监脩撰将漕江东二首 其一","f":"七言律诗","c":["蓬莱仙伯沈东阳，领袖诸儒太极旁。","东壁二星云汉近，西昆群玉简编香。","鸡翘豹尾无多子，锦缆牙樯有底忙。","建业江山入诗集，却归天上侍虚皇。"]},{"t":"送陆子静删定宫使","f":"七言律诗","c":["朝路江西不十人，又看一个奉仙真。","可怜议论长倾坐，不管声名解误身。","苦忆去年郊祀日，与渠并辔笑谈春。","何时相趁沧洲去，雪笠风蓑钓白蘋。"]},{"t":"送陈行之寺丞出守南剑二首 其二","f":"五言律诗","c":["我召公先到，公归我亦行。","三年如梦尔，一笑可怜生。","野店缘山去，春风并辔轻。","先愁饶水上，话别若为情。"]},{"t":"送陈行之寺丞出守南剑二首 其一","f":"五言律诗","c":["甫尔丞农扈，翩然牧剑津。","诸公谁不相，有子几何人。","气节霜馀凛，辞章玉样新。","飞腾可轻料，渠亦正青春。"]},{"t":"送陈婿履常县丞之官泰宁","f":"五言律诗","c":["玉润非冠玉，东床忽易东。","一官斯立样，五字后山风。","明月来宵共，清尊何日同。","看君即飞兔，老我自冥鸿。"]},{"t":"送周元吉显谟左司将漕湖北三首 其三","f":"七言律诗","c":["彼此江湖漫浪翁，相逢递宿省西东。","两穷握手论诗后，一笑投胶入漆中。","临水登山公别我，青鞋布袜我从公。","貂裘已博江西艇，只待黄花半席风。"]},{"t":"送周元吉显谟左司将漕湖北三首 其二","f":"七言律诗","c":["又见周郎携小乔，武昌赤壁醉娇饶。","蜀江雪水来三峡，吴苑风烟访六朝。","秋月春花出肝肺，新词丽曲入笙箫。","归来却侍金銮殿，好看霜毛映珥貂。"]},{"t":"送周元吉显谟左司将漕湖北三首 其一","f":"七言律诗","c":["君诗日日说归休，忽解西风一叶舟。","黄鹤楼前作重九，水精宫里过中秋。","职亲六阁仍金马，喜入千屯看木牛。","绣斧光华谁不羡，一贤去国欠人留。"]},{"t":"送周仲觉访来又别","f":"七言律诗","c":["酒边诗里久尘埃，见子令人病眼开。","无夕不谈谈不睡，看薪成火火成灰。","小留差胜匆匆别，欲去何如莫莫来。","渠政功名我岩壑，老身谁子共归哉。"]},{"t":"送周彦敷通判之官临川","f":"五言律诗","c":["益国今姬旦，治中小吕申。","留家视兰膳，疋马见州民。","慈训二六句，寒窗三十春。","校书天禄阁，才子即云津。"]},{"t":"送昌英叔知县之官麻阳","f":"七言律诗","c":["政坐诗无半点尘，天令著句锦江春。","远民蒙惠即真学，漫仕缘亲非为身。","许日相从今恨少，先生此别我谁邻。","不应更作徒劳叹，廊庙方寻密县人。"]},{"t":"送林子方直阁秘书将漕闽部三首 其三","f":"七言律诗","c":["亦闻小泊赞公房，清晓扶藜叩上方。","君与一僧游别嶂，我行百匝绕长廊。","风巾雾屦来云外，雪桧霜松满袖香。","政是炎官张火伞，不应多取海山凉。"]},{"t":"送林子方直阁秘书将漕闽部三首 其二","f":"七言律诗","c":["梅花国里荔枝村，颇记张灯作上元。","一别频蒙访生死，七年再见劣寒温。","属当闵雨祈群望，不得临风共一尊。","谁为君王留国士，吾衰犹拟叫天阍。"]},{"t":"送林子方直阁秘书将漕闽部三首 其一","f":"七言律诗","c":["才趁锋车入帝关，又持使节过家山。","作仙茶囿芝田里，寓直蓬莱藏室间。","握手清谈纱帽点，羡君白日绣衣还。","来年贡了云龙璧，便缀金鸾玉笋班。"]},{"t":"送罗永年归永丰","f":"五言律诗","c":["谁道三年聚，能胜一别多。","岁寒知子可，心折奈吾何。","所喜如椽笔，能挥却日戈。","老夫留病眼，看子中文科。"]},{"t":"送罗季周主簿之官八桂","f":"七言律诗","c":["忆昔相从夜诵时，子垂两髧我初髭。","梧桐叶落犹无睡，桃李春归总不知。","我已悬车老岩壑，子方敛板走阶墀。","莫嫌衰病人皆弃，桂岭梅花寄一枝。"]},{"t":"送罗春伯大著提举浙西","f":"七言律诗","c":["晁董声名彼一时，夫君下笔与渠齐。","承明厌直辞金马，英荡非关访碧鸡。","山岳动摇增气色，诏书宣布舞群黎。","归期只在千秋节，留赋苍苔凤掖西。"]},{"t":"送金元度教授辞满赴部改秩","f":"七言律诗","c":["金华唐吕两儒先，夜半黄梅君并传。","不日经筵重坐席，暂时黉舍冷无毡。","引班晓漏槐枫里，出宰春风桃李边。","莫遣垂杨知别恨，一篙新涨解归船。"]},{"t":"送俞漕子清大卿赴召二首 其二","f":"七言律诗","c":["自笑孤踪霜叶轻，宦游何幸并耆英。","合符先后分江郡，接武差池缀月卿。","爱我从来两胶漆，与公别是一亲情。","老身无用难提挈，尚有儿曹累使令。"]},{"t":"送俞漕子清大卿赴召二首 其一","f":"七言律诗","c":["帝求耆旧忆吾公，紫诏斜行下碧穹。","励操兰薰仍雪瑩，作民冬日与春风。","便登凤阁鸾台上，小试鸡翘豹尾中。","十载江湖访民瘼，一时倾倒沃天聪。"]},{"t":"送客既归晚登清心阁","f":"五言律诗","c":["谁不知侬懒，其如送客何。","叶声和雨细，山色上楼多。","出处俱为累，升沉尽听他。","疏钟暮相答，也解说愁么。"]},{"t":"送胡端明赴召","f":"七言律诗","c":["紫泥夜下日星晖，赤舄朝看衮绣归。","中国如今相司马，四夷见说问非衣。","金鱼玉带明霜鬓，斗极台符拱太微。","卫武年龄子仪考，一身双美古来稀。"]},{"t":"送赵民则少监提举二首 其二","f":"七言律诗","c":["座主门生四十年，江湖契阔几风烟。","同朝再接鸳行里，握手相看鹤发前。","误喜论诗追旧事，不知呼酒是离筵。","老怀只作还山梦，输与先生早著鞭。"]},{"t":"送赵民则少监提举二首 其一","f":"七言律诗","c":["汉庭近日少宗盟，博选宗英副匠卿。","高帝子孙谁宿德，翰林风月得先生。","又持一节湖南去，政是三湘雁北征。","但使远民蒙福了，早归词禁赋新莺。"]},{"t":"送赵宽之排岸之官章贡","f":"七言律诗","c":["监河曾赋鹿鸣篇，又奉潘舆上贡川。","五子循环迎一母，十分酌玉祝千年。","郁孤马祖饶行乐，柿栗来禽肥过拳。","兰膳馀闲翻故纸，曲江早趁燕花边。"]},{"t":"送叶叔羽寺丞持节淮东二首 其一","f":"五言律诗","c":["呼酒东西玉，探梅南北枝。","相逢长不款，此别有馀思。","古道寒如水，吾侪鬓已丝。","一生商略此，更待赠临岐。"]},{"t":"送叶叔羽寺丞持节淮东二首 其二","f":"五言律诗","c":["煮海谁为祟，沿淮困不胜。","民思贤使者，帝遣大农丞。","玉节寒侵斗，牙樯冻作冰。","来归闻早著，紫禁要渠登。"]},{"t":"送徐吉水解组造朝","f":"七言律诗","c":["我住南溪溪北涯，闭门草长不曾开。","风窗只怪灯花喜，雪径传呼县尹来。","道是朝廷举廉吏，如何江海尚遗才。","西枢东观俱知己，拜了除书却探梅。"]},{"t":"送徐宋臣监丞补外","f":"七言律诗","c":["出处何心一似云，世间万事不关身。","补天鍊石无虚日，忧国如家有几人。","千载芬香只忠孝，百年富贵竟埃尘。","看君两鬓青青在，不晚归来侍玉宸。"]},{"t":"送钱寺正出守广德军二首 其二","f":"七言律诗","c":["辛卯中书落笔年，曾陪学士堵墙间。","看渠手把州麾去，故里春迎昼绣还。","我似青蒿君玉树，君方绿鬓我苍颜。","一尊话别休辞醉，报政归来紫禁班。"]},{"t":"送钱寺正出守广德军二首 其一","f":"七言律诗","c":["四十专城古已稀，君侯五七更英奇。","九重临遣廷尉正，千里驩迎循吏师。","鸿雁同科金玉律，鹓雏先集凤凰枝。","少年勇退无人会，孤竹初心逊伯夷。"]},{"t":"送章汉卿归宣城","f":"五言律诗","c":["竹叶孤斟久，梅花远信疏。","如何穷巷辙，忽枉故人车。","伯仲俱佳士，云霄政望渠。","相从又相别，欲别重踌躇。"]},{"t":"送章德茂少卿使虏","f":"七言律诗","c":["雪后闻君策马蹄，长缨自请系撑犁。","光华剑佩伊吾北，弹压风涛瀚海西。","汉苑秦关愁外眼，边花塞月醉中题。","归来听履星辰上，谁道淮阴假镇齐。"]},{"t":"送萧瑞卿","f":"五言律诗","c":["异县二百里，分襟五十年。","肯来寻病者，相对各苍然。","举似儿时话，茫如梦里烟。","残花犹可醉，细酌未须眠。"]},{"t":"送黄仲秉少卿知泸州二首 其二","f":"五言律诗","c":["补外公何幸，求归我尚留。","还为万里别，又费半生愁。","安得欹黄帽，相从却白头。","醉中有话在，欲说忘来休。"]},{"t":"送黄仲秉少卿知泸州二首 其一","f":"五言律诗","c":["滟滪方如象，馀皇底似飞。","相将刺天去，收拾大名归。","西掖桐阴静，泸南荔子肥。","未应经世具，便欲闭山扉。"]},{"t":"送傅安道郎中将漕七闽二首 其二","f":"五言律诗","c":["把酒春如许，论诗夜未央。","相逢便金石，何必试冰霜。","离合知难免，愁思自不忘。","它年一茅屋，公肯访荒凉。"]},{"t":"送傅安道郎中将漕七闽二首 其一","f":"五言律诗","c":["一代风骚将，百年忠义家。","出关称使者，踏雪度梅花。","梦破南宫被，春生北斗槎。","悬知入奏日，不待贡新茶。"]},{"t":"送喻叔奇工部知处州","f":"七言律诗","c":["厌直含香与握兰，一麾江海溯冰滩。","括苍山水名天下，工部风烟入笔端。","新国小迟怀印绶，故园暂许理渔竿。","即看治行闻天听，紫诏徵还集孔鸾。"]},{"t":"送彭子山提刑郎中赴召二首 其二","f":"七言律诗","c":["琼树初瞻二纪中，玉京再别一星终。","我随病鹤欹黄帽，公驾云鸿上碧穹。","寄径丝纶紫薇阁，押班冠剑大明宫。","锦园尚欠桃栽否，儿辈河阳待晓风。"]},{"t":"送彭子山提刑郎中赴召二首 其一","f":"七言律诗","c":["帝想丹青忆老成，公兼竹润更兰馨。","独追洙泗人无讼，再使成康世措刑。","召节自天回使节，郎星朝斗作台星。","花边独坐黄昏句，剩寄江西白鹭汀。"]},{"t":"送彭元忠司户二首 其二","f":"五言律诗","c":["浯石高仍瘦，愚溪绀且寒。","凭君聊杖屦，道我问平安。","句好今逾进，书来剩寄看。","只言官舍小，檐下过湘滩。"]},{"t":"送彭元忠司户二首 其一","f":"五言律诗","c":["触热能相访，言归有底忙。","百闻才半面，一别又三湘。","诗入江西社，心传肘后方。","木天须此士，丹笔校官黄。"]},{"t":"送曾文卿入京","f":"七言律诗","c":["如君大似陆云龙，一喷词场万马空。","文透退之关捩子，骚传正则祖家风。","三年拄笏南云里，两手投竿西日中。","璧水蓬山剩虚席，儤筵趁取牡丹红。"]},{"t":"送曾秀才归永丰","f":"七言律诗","c":["白白茅柴强作春，青青灯火夜相亲。","超然似子真翘楚，旧矣逢人诵过秦。","觅举不应专嗜古，能文安得却嫌贫。","射科速化谁无术，误向南溪更问津。"]},{"t":"送朝士使虏","f":"七言律诗","c":["又见皇华赋北征，谪仙俊气似秋鹰。","诗成紫塞三更月，马渡黄河十丈冰。","赵北燕南有人否，禽胡归汉竟谁曾。","天家社稷英灵在，佳气时时起五陵。"]},{"t":"送谢子肃提举寺丞二首 其二","f":"七言律诗","c":["谁遣孤舟蓑笠翁，强随桃李竞春风。","交情顷刻云翻手，古意凄凉月印空。","可笑能诗今谢脁，也能载酒过扬雄。","待渠归直金銮日，我已烟沙放钓筒。"]},{"t":"送谢子肃提举寺丞二首 其一","f":"七言律诗","c":["天台山秀古多贤，晚向池塘识惠连。","十载江湖州县底，一言金石冕旒前。","方陪廷尉甘堂舍，又赋皇华小雅篇。","拾得澄江春草句，端能染寄仄釐笺。"]},{"t":"送韩子云检正将漕江东二首 其二","f":"五言律诗","c":["名下得佳句，梦中哦半生。","未逢心已契，相见眼偏明。","复此匆匆别，苍然惘惘情。","非关风外树，侬自作离声。"]},{"t":"送韩子云检正将漕江东二首 其一","f":"五言律诗","c":["宰士仍名士，诗人更德人。","还家桐树古，揽辔绣衣新。","不以髯边雪，而忘句里春。","登庸衣钵在，得恋大江滨。"]},{"t":"送简寿玉主簿之官临桂二首 其二","f":"七言律诗","c":["柴门草径尽莓苔，不放黄尘俗子来。","诗客清晨冲雨入，梅花一夜为君开。","飘萧落叶残灯火，陆续清谈浊酒杯。","二十六年才四见，骊驹抵死祗相催。"]},{"t":"送简寿玉主簿之官临桂二首 其一","f":"七言律诗","c":["兰溪倾盖杏风残，桂岭离裾菊露寒。","听子新诗过夜半，吹侬秋思入云端。","往吟平地千苍玉，还忆孤舟一钓竿。","四海如今习凿齿，大官莫作小官看。"]},{"t":"送詹进卿大监出宣城","f":"七言律诗","c":["今代稽山贺季真，前身江左谢宣城。","向来诏策无双手，已逼云霄尺五程。","银杏木瓜分我否，鸳鸯野鸭莫渠惊。","玉皇香案方虚伫，看即徵黄侍紫清。"]},{"t":"送蔡定夫赴湖南提刑二首 其二","f":"七言律诗","c":["方丈蓬莱第一人，星轺玉节正青春。","只今回雁峰头客，曾触神龙颔下鳞。","未遣五纹朝补衮，便应三字夜司纶。","湘江绿净不可唾，却要珠玑欬唾新。"]},{"t":"送蔡定夫赴湖南提刑二首 其一","f":"七言律诗","c":["菊后霜前换绣衣，湘南岭北看梅枝。","还将方策汗青语，拈出圜扉草绿时。","四海几人怜我老，三年两作送君诗。","借令贵杀衡阳纸，半幅无妨慰梦思。"]},{"t":"送颜几圣龙学尚书出守泉州二首 其二","f":"七言律诗","c":["我昔绫衾下直时，公为璧水大宗师。","清风明月行乐耳，布袜青鞋随所之。","颠倒壶觞留落日，翻腾山水入新诗。","我来公去如相避，送眼行尘不得追。"]},{"t":"送颜几圣龙学尚书出守泉州二首 其一","f":"七言律诗","c":["听履星辰北斗寒，三能只隔寸云间。","周家冢宰均四海，汉制尚书本百官。","鹓鹭班齐瞻进步，凤凰池近却飞还。","河图冠出西清上，莫作寻常五马看。"]},{"t":"送薛子约下第归永嘉","f":"七言律诗","c":["河东鸑鷟志青天，冀北麒麟受玉鞭。","二十年前元脱颖，五千人里又遗贤。","请君更草凌云赋，老我重看斫桂仙。","趁取春风双鬓绿，收科谁后复谁先。"]},{"t":"送赣守张子智左史进直敷文阁移帅八桂二首 其二","f":"七言律诗","c":["抛官九载卧柴荆，有底生涯底友生。","白鹭鸬鹚双属玉，青鞋布袜一笭箵。","赣江府主怜逋客，尊酒绨袍笃故情。","天上故人今又去，碧云西望暮天横。"]},{"t":"送赣守张子智左史进直敷文阁移帅八桂二首 其一","f":"七言律诗","c":["龙尾名臣进宝奎，虎头移镇赴榕溪。","握刀将帅迎牙纛，解辫戎蛮贡象犀。","翠浪玉虹馀昨梦，碧篸罗带入新题。","凤池鸡树公栖处，早个云飞不要梯。"]},{"t":"郡圃杏花二首 其二","f":"七言律诗","c":["迥出千花合受降，不然受拜亦何妨。","行穿小树寻晴朵，自挽芳条嗅暖香。","却恨来时差已晚，不如清晓看新妆。","朗吟清露温风句，恼杀诗翁只断肠。"]},{"t":"郡圃杏花二首 其一","f":"七言律诗","c":["小树嫣然一两枝，晴醺雨醉总相宜。","绝怜欲白仍红处，政是微开半吐时。","得幸东风无与对，主张春色更还谁。","海棠秾丽梅花淡，匹似渠侬别样奇。"]},{"t":"郡圃雪霁便有春意","f":"五言律诗","c":["腊傍梅梢尽，春从水底归。","草拳擎雪健，桃糁隔年肥。","夜夜还乡梦，心心逐雁飞。","谁言五斗米，便胜北山薇。"]},{"t":"闻莺","f":"五言律诗","c":["过雨溪山净，新晴花柳明。","来穿两好树，别作一家声。","故欲撩诗兴，仍添怀友情。","惊飞苦难见，那更绿阴成。"]},{"t":"除夕送次公子入京受县","f":"七言律诗","c":["过眼光阴又岁穷，相看父子一尊同。","春回雨点溪声里，人醉梅花烛影中。","汝趁暄和朝北阙，我扶衰病见东风。","弟兄努力思报国，放我沧浪作钓翁。"]},{"t":"除夕宿临川战平","f":"五言律诗","c":["一腊天频雪，千山梅未花。","终年不为客，除夕恰辞家。","雨又垂垂落，风仍故故斜。","难开愁里眼，只益鬓边华。"]},{"t":"除夜张功父惠诗索荆溪集次韵送往","f":"五言律诗","c":["早往荆溪集，应无桂隐诗。","梅边五字律，管底一斑窥。","新岁来朝是，流年去浪移。","谁能守除夕，妨我梦归时。"]},{"t":"除夜宿石塔寺","f":"七言律诗","c":["醉后先眠客莫嗔，谁能守岁费精神。","幸无爆竹惊寒梦，休羡椒花颂好春。","今岁明年才隔夕，人情物态顿趋新。","遥怜儿女团栾处，政欠屠酥第十人。"]},{"t":"食车螯","f":"七言律诗","c":["珠宫新沐净琼沙，石鼎初燃瀹井花。","紫壳旋开微滴酒，玉肤莫熟要鸣牙。","枨拖金线成双美，姜擘糟丘并一家。","老子宿酲无解处，半杯羹后半瓯茶。"]},{"t":"食鸡头子二首 其二","f":"七言律诗","c":["三危瑞露冻成珠，九转丹砂鍊久如。","鼻观温芳炊桂歇，齿根熟软剥胎馀。","半瓯鹰爪中秋近，一炷龙涎丈室虚。","却忆吾庐野塘味，满山柿叶正堪书。"]},{"t":"食鸡头子二首 其一","f":"七言律诗","c":["江妃有诀煮真珠，菰饭牛酥软不如。","手擘鸡腮金五色，盘倾骊颔琲千馀。","夜光明月供朝嚼，水府龙宫恐夕虚。","好与蓝田餐玉法，编归辟谷赤松书。"]},{"t":"食菱","f":"七言律诗","c":["鸡头吾弟藕吾兄，头角崭然也不争。","白璧中藏烟水晦，红裳左袒雪花明。","一生子木非知己，千载灵均是主盟。","每到炎官张火伞，西山未当圣之清。"]},{"t":"夏日书事","f":"五言律诗","c":["一字看成两，霜须摘转多。","既无书册分，奈此日长何。","荔子红初皱，春醅碧欲波。","醉来愁自去，不去亦从它。"]},{"t":"夏夜月下独酌二首 其二","f":"五言律诗","c":["月忿云遮却，云遭月辊翻。","斩新灯世界，特地玉乾坤。","兔舞催诗句，蟾醒笑醉魂。","姮家且莫睡，照管失金盆。"]},{"t":"夏夜月下独酌二首 其一","f":"五言律诗","c":["谁道今年热，今宵分外清。","竹风秋九夏，溪月昼三更。","此景天悭与，无人酒自倾。","明朝火伞上，别作一经营。"]},{"t":"夏夜喜雨","f":"五言律诗","c":["听雨初假寐，还成睡著休。","梦中檐奏乐，夜半簟知秋。","今岁应须熟，馀生有底愁。","无人知喜事，课仆织新篘。"]},{"t":"夏夜露坐二首 其二","f":"五言律诗","c":["山翠都成黑，天黄忽复青。","月肥过半璧，云瘦不遮星。","瓦鼓三四只，村酤一两瓶。","人皆笑我醉，我独笑渠醒。"]},{"t":"夏夜露坐二首 其一","f":"五言律诗","c":["火老殊未热，雨多还自晴。","暮天无定色，过鸟有归声。","坐久人将睡，更深月始明。","素娥欺我老，偏照雪千茎。"]},{"t":"除夕留子上伯玉子西小酌","f":"七言律诗","c":["诸弟山行归意忙，老夫雪卧病身僵。","维风及雨岁云暮，不醉无归夜未央。","五盏更搀三盏么，四更偏觉五更长。","也知柏酒明朝近，且为梅花尽此觞。"]},{"t":"徐氏太淑人挽词二首 其二","f":"五言律诗","c":["赤矢生名族，乌衣媲德门。","萱堂登九秩，兰砌颔重孙。","乐饮占蛇日，翻随药兔魂。","一生参贝叶，梦幻了无痕。"]},{"t":"徐氏太淑人挽词二首 其一","f":"五言律诗","c":["三子官期至，同时各致勤。","争迎阿潘母，独就大冯君。","喜入乌巢舍，惊传鹤吊坟。","伤心是廷尉，目断太行云。"]},{"t":"挽邹彦明","f":"五言律诗","c":["野渡无冰涉，荒民不木饥。","桥横侍郎记，墓立舍人碑。","自古谁无死，何人没后思。","淙淙富川水，便是挽歌词。"]},{"t":"挽封州太守赵次公二首 其二","f":"五言律诗","c":["雁峰三径古，融水贰车新。","自此相从后，还成永别晨。","只今耆旧传，谁是老成人。","剩欲书遗德，心悲语不真。"]},{"t":"挽封州太守赵次公二首 其一","f":"楚辞体","c":["国尔怀孤愤，麟兮嗣古风。","谓宜空冀北，何意召河东。","榕叶烝山祲，梨花惨殡宫。","传家今有子，身后未应穷。"]},{"t":"晓风","f":"五言律诗","c":["剩暑迟旋旆，新风急解纷。","白翻荞处雪，黄摆稻中云。","动地休多怒，披襟且一欣。","长松十里径，树树供清闻。"]},{"t":"晓出洪泽霜晴风顺","f":"七言律诗","c":["又从洪泽溯清淮，积雨连宵晓顿开。","霜冻水涯如雪厚，波摇日影入船来。","辛勤送客了未了，珍重顺风催复催。","明早都梁各分手，顺风便借一帆回。"]},{"t":"晓行东园","f":"七言律诗","c":["霜后前林一向疏，丹枫落尽况黄梧。","犯寒侵早看残菊，怕热平生不拥炉。","老眼读书长作睡，病身得酒忽全苏。","好诗排闼来寻我，一字何曾撚白须。"]},{"t":"晓过叶家桥二首 其二","f":"五言律诗","c":["圩峻愁今路，山行羡昨朝。","闭窗深坐轿，合眼过危桥。","岸近何由到，魂惊半欲销。","寄言薛丞相，最稳是轻舠。"]},{"t":"晓过叶家桥二首 其一","f":"五言律诗","c":["鸡唱嗔人睡，鸦啼唁客劳。","近山烟外远，矮竹苣边高。","老矣犹长铗，悠哉未大刀。","绕圩无杂树，一色柳新缫。"]},{"t":"晓过皂口岭","f":"七言律诗","c":["夜渡惊滩有底忙，晓攀绝磴更禁当。","周遭碧嶂无人迹，围入青天小册方。","半世功名一鸡肋，平生道路九羊肠。","何时上到梅花岭，北望螺峰半点苍。"]},{"t":"晓泊丹阳馆","f":"五言律诗","c":["夕冻朝还积，寒曦暖未多。","霜轻犹著草，冰重亦浮河。","山尽酣馀势，潮归殿去波。","六朝遗迹在，故老尚传么。"]},{"t":"晓泊舟庙山","f":"五言律诗","c":["平水长先晓，无风也自涛。","烟昏山易远，岸阔树难高。","去雁鸣相报，游鱼冷总逃。","轻寒容可忍，清眺得辞劳。"]},{"t":"晓经八盘岭赴东宫讲堂","f":"七言律诗","c":["至前至后恰多晴，山北山南间一登。","瘦石经霜乾脱藓，细泉滴涧旋成冰。","海波贯日红千丈，江雾萦楼玉万层。","资善堂前得春早，宫梅一朵掠觚棱。"]},{"t":"晓看芙蓉","f":"七言律诗","c":["两岁芙蓉无一枝，今年万朵压枝低。","半红半白花都闹，非短非长树斩齐。","临水酽妆新雨后，出墙背面晓风西。","春英笑杀秋英淡，祗恐秾于桃李蹊。"]},{"t":"晓望","f":"五言律诗","c":["暑退谁当忆，秋生喜此逢。","荒林失轻雾，寒日上危峰。","忽有吟边兴，忘看镜里容。","不须无鲍谢，始得擅诗宗。"]},{"t":"晓晴发黄杜驿二首 其二","f":"五言律诗","c":["巷竹欹将倒，林花湿不飞。","总将枝上雨，洒入轿间衣。","晴色犹全嫩，春寒肯便归。","祗能欺客子，户户闭荆扉。"]},{"t":"晓晴发黄杜驿二首 其一","f":"五言律诗","c":["望后月不落，偏于水底明。","对悬双玉镜，并照一金钲。","忽值山都合，浑无路可行。","多情小花径，导我度千萦。"]},{"t":"晓晴过猿藤径","f":"五言律诗","c":["厌雨欣初霁，贪程敢晏眠。","排天双壁起，受日一峰先。","入径惟逢树，无人况有烟。","藤深猿不见，声到客愁边。"]},{"t":"晓登子城","f":"五言律诗","c":["鞋响新霜后，襟暄野日初。","寒溪半湾落，远树一行疏。","老矣端何苦，归哉不愿馀。","终更犹半岁，作么度居诸。"]},{"t":"浮石清晓放船遇雨","f":"七言律诗","c":["破晓开船船正行，忽然头上片云生。","秋江得雨茶鼎沸，怒点打篷荷叶鸣。","远听滩喧心欲碎，近看浪战眼初明。","夜来暗长前村水，绝喜舟人好语声。"]},{"t":"海棠四首 其四","f":"七言律诗","c":["吾诗多为海棠哦，花意依前怨不多。","已拆未开浑是韵，乍浓还淡总由它。","留连春色能销底，请托东风定肯么。","岂是少陵无句子，少陵未见欲如何。"]},{"t":"海棠四首 其三","f":"七言律诗","c":["竞艳争娇最是他，教人嫌少不嫌多。","初酣晓日红千滴，晚笑东风淡一涡。","自是花中无国色，非关格外占春窠。","开时悭为渠侬醉，却恨飘零可若何。"]},{"t":"海棠四首 其二","f":"七言律诗","c":["暖醉寒醒各自奇，千花谁是复谁非。","燕支浓透春风面，翡翠新裁生色衣。","破落东皇能许劣，庄严西子较些肥。","痴儿犹恨无香在，紫蝶黄蜂政打围。"]},{"t":"海棠四首 其一","f":"七言律诗","c":["小园不到负今晨，晚唤娇红伴老身。","落日争明那肯暮，艳妆一出更无春。","树间露坐看摇影，酒底花光并入唇。","银烛不烧渠不睡，梢头恰恰挂冰轮。"]},{"t":"涉小溪宿淡山","f":"五言律诗","c":["径仄愁斜步，溪深怯正看。","破船能不渡，晴色敢辞寒。","白退山云细，青还玉宇宽。","险艰明已济，魂梦未渠安。"]},{"t":"留萧伯和仲和小饮二首 其二","f":"七言律诗","c":["谁曾白日上青天，谁羡千钟况万钱。","要入诗家须有骨，若除酒外更无仙。","三杯未必通大道，一斗真能出百篇。","李杜饥寒才几日，却教富贵不论年。"]},{"t":"留萧伯和仲和小饮二首 其一","f":"七言律诗","c":["野果山蔬未要多，浊醪清酒尽从他。","不于两盏三杯里，奈此千愁百恼何。","山倒莫教扶玉树，尊空别得借银河。","少陵一语君知么，不见堂前东逝波。"]},{"t":"留题筠庵以茅盖层出如蓑衣然","f":"七言律诗","c":["茂林脩竹翠光中，那得披蓑一老翁。","白石砌成珠子径，黄茅裹却水晶宫。","夏凉冬暖非人境，雪打霜封即钓篷。","老子明朝便东去，更携瓦枕享松风。"]},{"t":"留题碧落堂","f":"七言律诗","c":["仙人白日上青冥，千载如闻月下笙。","南北万山俱在下，中间一水独穿城。","江西个是绝奇处，天下几多虚得名。","滕阁孤台非不好，祇缘犹带市朝声。"]},{"t":"病中夜坐","f":"七言律诗","c":["月流银汉小徘徊，似恋空庭独树梅。","玉漏听来更二点，烛花剪了晕重开。","病身不饮看人醉，乾雪无端上鬓来。","后日老衰知健否，只今六九已摧隤。"]},{"t":"病中屏肉味独茹菜羹饭甚美","f":"七言律诗","c":["云子香抄玉色鲜，菜羹新煮翠茸纤。","人间脍炙无此味，天上酥陀恐尔甜。","浑是土膏含雨露，何须酱豉与醯盐。","茹毛祸首雍巫出，馋到熊蹯未属厌。"]},{"t":"病中春雨闻东园花盛","f":"七言律诗","c":["万类欣欣一老悲，物华岂是不佳时。","病夫自与春无分，好景非于我独遗。","花底报来开已闹，雨中过了更曾知。","风光九十今强半，又约芳菲隔岁期。"]},{"t":"病中喜雨呈李吉州","f":"七言律诗","c":["两日炎晖烈未收，连宵甘澍沛如流。","大田今日非昨日，多稼新秋赛旧秋。","凉气隔帘深亦透，香烟穿袖散难留。","史君小试为霖手，便作江西第一州。"]},{"t":"病中感春","f":"七言律诗","c":["老去春来已薄情，体中病后更竛竮。","海棠红酽飞成雪，杨柳金浓染作青。","到得当家饶景物，不如旧日借园亭。","一杯欲把还休去，遮莫莺花笑独醒。"]},{"t":"病中感秋","f":"七言律诗","c":["病中一刻抵三秋，况见西风再树头。","老去能禁几回病，秋来不为别人愁。","书帷梦觉疑僧榻，竹户凉侵似客舟。","寿外康宁方是福，不然徒寿不须休。"]},{"t":"病中感秋时初丧寿佺子","f":"五言律诗","c":["临晓睡偏重，不知窗已明。","高梧下清露，宿鸟有寒声。","愁岂关须事，秋来添雪茎。","病身仍哭子，并作老来情。"]},{"t":"病后觉衰","f":"五言律诗","c":["病著初无恼，安来始觉衰。","人谁长健底，老有顿来时。","山意凄寒日，秋光染瘦诗。","小松能许劣，学我弄吟髭。"]},{"t":"病起览镜二首 其二","f":"五言律诗","c":["览镜忽自问，何方一病翁。","生涯管城外，本贯醉乡中。","笔砚今都废，尊罍久屡空。","又将数茎雪，憔悴见西风。"]},{"t":"病起览镜二首 其一","f":"五言律诗","c":["病起长新骨，居然非旧容。","眼添佩环带，腰减采花蜂。","对面不相识，何人忽此逢。","吾身无定在，更要问穷通。"]},{"t":"益公和白花青缘牡丹王字韵诗再和以往","f":"七言律诗","c":["渠是花中异姓王，平园小试染花方。","冰霜洗出春风面，翡翠轻棱叠雪裳。","夜领素娥酌青女，晓看国色带天香。","更将秋菊潭心水，滴作䒠茸月蕊黄。"]},{"t":"益公新作三层百尺新楼署曰围山观贺以唐律二章 其二","f":"七言律诗","c":["崖谷求仙底有仙，金梯上去即仙源。","山川第一江西景，风月无边相国园。","十倍黄楼况黄阁，千寻青笔是青原。","写成脚力犹强句，灯火笙歌特地村。"]},{"t":"益公新作三层百尺新楼署曰围山观贺以唐律二章 其一","f":"七言律诗","c":["万峰飞入子城头，千里长江几上流。","外面周遭苍玉笋，虚空幻出水晶楼。","帘开雪月非三界，人立云霄更九州。","一骑红尘北来底，平章军国恼公不。"]},{"t":"真阳峡","f":"七言律诗","c":["清远虽佳未足观，真阳佳绝冠南蛮。","一泉岭背悬崖出，乱洒江边怪石间。","夹岸对排双玉笋，此峰外面万青山。","险艰去处多奇观，自古何人爱险艰。"]},{"t":"崇德道中望福严寺","f":"五言律诗","c":["一径青松露，三门白水烟。","殿横林外脊，塔漏隙中天。","地旷迎先见，村移眺更妍。","追程坐行役，不得泊春船。"]},{"t":"秧畴","f":"七言律诗","c":["田底泥中迹尚深，折花和叶插畦心。","晚秧初撚金狨线，先种输它绿玉针。","云垄雾畴俱水响，丝风毛雨政春阴。","莫听布谷相煎急，且为提壶强满斟。"]},{"t":"积雨小止暂到东园雨作急归","f":"七言律诗","c":["咫尺东园千里遥，欣逢小霁略逍遥。","鹭穿秧稻新黄脚，虫秃金沙嫩紫条。","城市檐间堪系缆，山溪夜半失危桥。","匆匆行散还归去，一阵飘萧不见饶。"]},{"t":"积雨新晴驾幸聚景园拟口号","f":"七言律诗","c":["帝心忧麦复忧桑，一念通天转雨旸。","五色日华销积霭，三春花草殿馀芳。","黄云暖照天颜喜，红药浓熏禁籞香。","见说都人争出郭，欢声舞倦万垂杨。"]},{"t":"荷池观鱼","f":"七言律诗","c":["截山剜沼贮泉流，旋种鯈鱼绝善游。","细数未齐还已乱，群嬉半没忽全浮。","荷钱荇带来复去，雪片银花稀却稠。","我乐自知鱼似我，何缘惠子会庄周。"]},{"t":"读张忠献公谥册感叹","f":"五言律诗","c":["恩视韩兼赵，名均献与忠。","礼中非不极，勋外若为同。","三圣无多学，千年仅一翁。","犹怜公议在，拚泪乞秋风。"]},{"t":"读罪己诏时有符离之溃 其二","f":"五言律诗","c":["乱起吾降日，吾将强仕年。","中原仍梦里，南纪且愁边。","陛下非常主，群公莫自贤。","金台尚未筑，乃至羡强燕。"]},{"t":"读罪己诏时有符离之溃 其三","f":"五言律诗","c":["只道六朝窄，渠犹数百春。","国家祖宗泽，天地发生仁。","历服端传远，君王但侧身。","楚人要能惧，周命正惟新。"]},{"t":"读罪己诏时有符离之溃 其一","f":"五言律诗","c":["莫读轮台诏，令人泪点垂。","天乎容此虏，帝者渴非罴。","何罪良家子，知它大将谁。","愿惩危度口，傥复雁门踦。"]},{"t":"郭母孺人李氏挽歌辞","f":"五言律诗","c":["李郭俱名族，华姻合两家。","藁砧巾角雨，郎罢笔头花。","树秀庭双玉，荪荣砌百芽。","半生冰雪节，再赋白山茶。"]},{"t":"郭汉卿母挽诗","f":"五言律诗","c":["妇节今安仰，斯人古有光。","鸡鸣不知雨，荠茂独凌霜。","未拜金花诰，空悲玉树郎。","藤舆帘蹙绣，无复出萱堂。"]},{"t":"都下食笋自十一月至四月戏题","f":"七言律诗","c":["竹祖龙孙渭上居，供侬樽俎半年馀。","斑衣戏綵春无价，玉版谈禅佛不如。","若怨平生食无肉，何如陋巷饭斯蔬。","不须庾韭元脩菜，吃到憎时始忆渠。"]},{"t":"钱仲耕殿撰侍郎挽诗二首 其二","f":"五言律诗","c":["使节三持玉，州轓两画熊。","雪山郇宝白，冰漕太仓红。","理世非轻士，才难会忆公。","石峰当西子，作殉送青枫。"]},{"t":"钱仲耕殿撰侍郎挽诗二首 其一","f":"五言律诗","c":["易髓三爻表，恩波九里强。","贯珠程氏传，炊玉范家庄。","荷橐中年紫，芸签到老香。","不应踰耳顺，便返白云乡。"]},{"t":"陪留守余处恭总领钱进思提刑傅景仁游清凉寺即古石头城三首 其三","f":"七言律诗","c":["已守台城更石城，不知并力或分营。","六师只遣环天阙，一垒真成借寇兵。","向者王苏俱解此，冤哉隗协可怜生。","若言虎踞浑堪倚，万岁千秋无战争。"]},{"t":"陪留守余处恭总领钱进思提刑傅景仁游清凉寺即古石头城三首 其二","f":"七言律诗","c":["万里长江天上来，石头却欲打江回。","青山外面周如削，紫府中间划洞开。","苏峻战场今草树，仲谋庙貌古尘埃。","多情白鹭洲前水，月落潮生声自哀。"]},{"t":"陪留守余处恭总领钱进思提刑傅景仁游清凉寺即古石头城三首 其一","f":"七言律诗","c":["山自新亭走下来，化为一虎首重回。","平吞雪浪三江水，卧对雨花千丈台。","点检故城遗址在，凄凉浩叹宿云开。","六朝踪迹登临遍，底事兹游独壮哉。"]},{"t":"高宗圣神武文宪孝皇帝挽诗二首 其二","f":"五言律诗","c":["更造今光武，中兴昔武丁。","云昭河洛画，天作典谟经。","立极馀三纪，颐神再一星。","尧山邻禹穴，松雪蔚争青。"]},{"t":"高宗圣神武文宪孝皇帝挽诗二首 其一","f":"五言律诗","c":["芒动长星帚，亲挥却日戈。","再令天有柱，一定海无波。","黄屋非尧乐，薰琴付舜歌。","祗书魏荡字，诔语不须多。"]},{"t":"高枧石岭雨中云气蔽亏山色隐显","f":"七言律诗","c":["绝顶仙人富宝熏，水沉山子不论斤。","堆从平地到天半，并作清香一炷焚。","烟绕翠鬟苍玉佩，身披白縠素罗裙。","更将万斛蔷薇露，酒作桑麻万顷云。"]},{"t":"宿乐平县北十里西塘","f":"五言律诗","c":["破店能无漏，孤灯肯更明。","中间通客路，终夜有人声。","坐又坐不得，眠来眠未成。","如何故山友，抵死怨躬耕。"]},{"t":"宿兰溪水驿前三首 其三","f":"五言律诗","c":["水色秋逾白，山光夜不青。","一眉画天月，万粟种江星。","小酌居然醉，当风不觉醒。","谁家教儿子，清诵隔疏棂。"]},{"t":"宿兰溪水驿前三首 其二","f":"五言律诗","c":["合眼波吹枕，开篷月入船。","奇哉一江水，写此二更天。","剩欲酣清赏，翻愁败醉眠。","今宵怀昨夕，雨卧万峰前。"]},{"t":"宿兰溪水驿前三首 其一","f":"五言律诗","c":["系缆兰溪岸，开襟柳驿窗。","人争趋夜市，月自浴秋江。","灯火疏还密，帆樯只更双。","平生经此县，今夕驻孤幢。"]},{"t":"宿白云山奉圣禅寺","f":"七言律诗","c":["径夹长松照地青，眼看高阁与云平。","出林殿脊先知寺，满路花枝未见莺。","上到峰头千嶂合，下临岭脚一溪横。","山寒入骨冰相似，冰杀人来却道清。"]},{"t":"宿龙回","f":"五言律诗","c":["大熟虚成喜，微生亦可嗟。","禾头已生耳，雨脚尚如麻。","顷者官收米，精于玉绝瑕。","四山云又合，奈尔老农家。"]},{"t":"宿池州齐山寺即杜牧之九日登高处","f":"七言律诗","c":["我来秋浦政逢秋，梦里曾来似旧游。","风月不供诗酒债，江山长管古今愁。","谪仙狂饮颠吟寺，小杜倡情冶思楼。","问著州民浑不识，齐山依旧俯寒流。"]},{"t":"宿鸡林坊二首 其一","f":"五言律诗","c":["路觉往而复，意迷东与西。","元来八九渡，只是一条溪。","亭午虽微暑，兹辰较少泥。","诸峰云上出，不但与云齐。"]},{"t":"宿鸡林坊二首 其二","f":"五言律诗","c":["草有清无俗，田生不用耘。","菰花雕品字，荇叶缺钱文。","出水浮难没，遥风净更芬。","物情岂难状，作么未前闻。"]},{"t":"宿查濑","f":"七言律诗","c":["寒流一带槛前横，落日诸峰霞外明。","水断新洲添五里，客寻旧路却重行。","江车自转非人踏，沙碓长舂彻夜鸣。","畴昔稚桑今秃树，如何白发不教生。"]},{"t":"宿牧牛亭秦太师坟庵","f":"七言律诗","c":["函关只有一穰侯，瀛馆宁无再帝丘。","天极八重心未死，台星三点坼方休。","只看壁后新亭策，恐作栘中属国羞。","今日牛羊上丘垄，不知丞相更嗔不。"]},{"t":"宿金陵镇栖隐寺望横山","f":"七言律诗","c":["再见横山滴眼新，山曾劝我脱官身。","灯笼箫鼓年年社，酒盏莺花处处人。","忽忆诸公牡丹会，转头五柞去年春。","野云墟月空荒寺，两袖寒风一帽尘。"]},{"t":"宿新丰坊咏瓶中牡丹因怀故园二首 其二","f":"七言律诗","c":["天下花王绝世无，侬家移得洛徽苏。","花头每朵一千叶，亲手前春五百株。","雪白猩红相映带，娇黄酽紫更敷腴。","乡魂开眼归将去，飞过长江彭蠡湖。"]},{"t":"宿新丰坊咏瓶中牡丹因怀故园二首 其一","f":"七言律诗","c":["客子泥涂正可怜，天香国色一枝鲜。","雨中晚敛寒如此，烛底宵暄笑粲然。","自觉玉容微婉软，急将翠掌护婵娟。","江南也有新丰市，未羡宾王酌圣贤。"]},{"t":"宿横冈","f":"七言律诗","c":["我岂忘怀一亩居，谁令爱读数行书。","秋南春北雁相似，柳思花情莺不如。","上市鱼虾村店酒，带花菘芥晚春蔬。","长亭一醉非难事，造物相撩莫管渠。"]},{"t":"寄广东提刑林谦之司业","f":"七言律诗","c":["玉节星槎下九天，祝融海若让云烟。","故人一别还三岁，新句如今更几篇。","忆昨待班南内否，论诗看雪未央前。","梦中若个韶州路，庾岭梅花正可怜。"]},{"t":"寄马会叔","f":"五言律诗","c":["影转郎官宿，春随刺史天。","相从忽相别，同舍况同年。","我爱吴儿说，兄如邵父然。","赐金真浪费，唤取从甘泉。"]},{"t":"寄中洲茶与尤延之延之有诗再寄黄檗茶仍和其韵","f":"七言律诗","c":["诗人可笑信虚名，击节茶芽意不轻。","尔许中洲真后辈，与君顾渚敢连衡。","山中寄去无多子，天上归来太瘦生。","更送玉尘浇锡水，为搜孔思搅周情。"]},{"t":"寄别何运判德献移闽宪二首 其一","f":"五言律诗","c":["再岁三移节，千山一据鞍。","梅花锦囊古，霜月绣衣寒。","民欲刑几措，公于此岂难。","谁令清庙器，未著侍臣冠。"]},{"t":"寄别何运判德献移闽宪二首 其二","f":"五言律诗","c":["薄技工奚取，知音一已多。","从公日几许，去我意如何。","梦里闽山月，吟边楚水波。","门阑万珠履，更试岁寒柯。"]},{"t":"寄张功父","f":"五言律诗","c":["问讯子张子，诗狂除未除。","年时一健步，寄我数行书。","旧矣哦招隐，谁欤诵子虚。","江湖隔京洛，不是爱相疏。"]},{"t":"寄张钦夫二首 其二","f":"五言律诗","c":["工瑟曾缘利，鸣琴岂负予。","发于贫里白，诗亦病来疏。","知己俱霄汉，孤踪且簿书。","三年知免矣，一饱会归欤。"]},{"t":"寄张钦夫二首 其一","f":"五言律诗","c":["作郡才佳政，留中即好音。","还将著书手，拈出正君心。","岳麓风霜饱，脩门雨露深。","登庸何恨晚，廊庙要山林。"]},{"t":"寄陆务观","f":"七言律诗","c":["君居东浙我江西，镜里新添几缕丝。","花落六回疏信息，月明千里两相思。","不应李杜翻鲸海，更羡夔龙集凤池。","道是樊川轻薄杀，犹将万户比千诗。"]},{"t":"寄周子充察院二首 其一","f":"五言律诗","c":["乡者豺当路，如今虎在山。","百年诸老尽，一段好风还。","谁谓永嘉末，人犹庆历间。","班心公定可，更可押廷班。"]},{"t":"寄周子充察院二首 其二","f":"五言律诗","c":["迹远公犹记，情亲势使疏。","忽思参研席，如许遽龙猪。","云步知无那，文盟肯弃予。","只哦五个字，不愈一行书。"]},{"t":"寄奉新钟宰","f":"五言律诗","c":["传语清心阁，欣逢诗主人。","莺花无恙否，风月一番新。","旧日行吟处，今来迹已陈。","应怜杨县尹，须鬓两如银。"]},{"t":"寄贺建康留守范参政端明二首 其二","f":"七言律诗","c":["一生狂杀老犹狂，只炷先生一瓣香。","不为渠侬在廊庙，无端将相更文章。","江南海北三千里，玉唾银钩十万行。","早整乾坤早岩壑，石湖风月剩分张。"]},{"t":"寄贺建康留守范参政端明二首 其一","f":"七言律诗","c":["寄衣不是未教归，不合威名满四夷。","天与中兴开日月，帝分万乘半旌旗。","春生锦绣山河早，秋到江淮草木迟。","卧护北门期月尔，却专堂印凤凰池。"]},{"t":"寄袁起岩枢密贺新除仍谢送四缣并诗集兼恳求陈婿荐书二首 其二","f":"五言律诗","c":["知己熙鸿化，阳和被九皋。","自怜今老病，无分恼钧陶。","独念东床客，犹沉左选曹。","春风半张纸，立地作宜敖。"]},{"t":"寄袁起岩枢密贺新除仍谢送四缣并诗集兼恳求陈婿荐书二首 其一","f":"五言律诗","c":["枢相身通贵，恩书意转亲。","四端香雪縠，一卷锦江春。","公即专堂印，侬方理钓缗。","五公今果六，诗谶也如神。"]},{"t":"寄萧仲和","f":"五言律诗","c":["贫里端何好，欣然肯不居。","诗臞将到骨，室陋得关渠。","我懒今仍老，谁能强著书。","谈间可无子，独判一秋虚。"]},{"t":"寄谢蜀帅袁起岩尚书阁学寄赠药物二首 其二","f":"七言律诗","c":["抛官归隐七经年，睡杀山云笑杀天。","剩雨残风黄帽底，颠诗中酒白鸥前。","少年行路今已矣，厚禄故人书寂然。","只有锦城袁阁学，寄诗赠药意悁悁。"]},{"t":"寄谢蜀帅袁起岩尚书阁学寄赠药物二首 其一","f":"七言律诗","c":["卧雪先生冰雪胸，小迂星履领元戎。","草堂衣钵风骚将，花屋笙箫造化工。","杜宇催归波正绿，海棠不睡烛斜红。","遨头未了词头下，四世重新六五公。"]},{"t":"寄题八桂张松卿义庄","f":"五言律诗","c":["张氏避毡裘，邢迁来桂州。","买田同族食，作计岂孙谋。","公艺君今是，希文古罕俦。","荆花再连理，萱草更千秋。"]},{"t":"寄题万安县刘元袭横秀阁","f":"七言律诗","c":["玉簪成阵雪成堆，秀气横空拨不开。","楚岫苍寒五云外，赣江白写九天来。","烟销日出皆诗句，月色波声唤梦回。","早晚携家过高阁，寄诗聊当一枝梅。"]},{"t":"寄题王梾德脩知县成都新居","f":"七言律诗","c":["子美百花潭北庄，君今占作咏归堂。","山分剑阁云根瘦，江送蓬婆雪汁香。","漱石枕流红锦浪，浮家泛宅白鸥行。","何人夜诵相如赋，给札兰台看堵墙。"]},{"t":"寄题周元吉左司山居三咏 其二 可止亭","f":"七言律诗","c":["金印龙章属市朝，清风明月属渔樵。","世皆蛮触君知止，渠自王公我岂骄。","真个归田何必赋，自家甘隐不缘招。","老夫三径都荒了，松菊虽存已半凋。"]},{"t":"寄题周元吉左司山居三咏 其三 适庵","f":"七言律诗","c":["莫道莼鲈不近名，尽谈鹏鴳未忘情。","醉中赌得苕溪月，醒后还输茂苑莺。","岂但二豪俱不见，向来三杰亦何成。","有人来问适庵趣，便是公荣也一觥。"]},{"t":"寄题周元吉左司山居三咏 其一 酣赋亭","f":"七言律诗","c":["诗酒如今谁主盟，须还酣赋老先生。","三杯两盏莺花底，一斗百篇谈笑成。","太白自翻新乐府，小蛮度入妙歌声。","生前身后名兼饮，二事何曾有重轻。"]},{"t":"寄题南昌尉厅思贤亭","f":"五言律诗","c":["有客栖霞外，无名涴党中。","南州一高士，东汉独清风。","旧国已禾女，荒阡犹石翁。","更烦吹笛魄，端为洗榛丛。"]},{"t":"寄题郭汉卿琴堂","f":"五言律诗","c":["著眼飞鸿外，欹巾韵磬边。","半忘今古操，岂校有无弦。","自适何须妙，能听也则贤。","如何划然里，犹露祖生鞭。"]},{"t":"寄题萧国贤佚我堂","f":"七言律诗","c":["软红尘里几时休，重碧杯中且拍浮。","坐看痴儿夸绝足，可怜到老不回头。","幅巾藜杖聊三径，明月清风自一丘。","我亦年来厌奔走，梦骑野鹤访沙鸥。"]},{"t":"寄题彭泽王尉名自适廨舍二境 其一 读书岩","f":"五言律诗","c":["不遇黄山谷，那传石橘林。","岩欺小孤顶，影落大江心。","试听秋虫语，如闻夜诵音。","梅仙癖嗜古，此外更幽寻。"]},{"t":"寄题彭泽王尉名自适廨舍二境 其二 潜玉洞","f":"五言律诗","c":["人道书岩好，谁知石洞奇。","外才一径尽，中忽万峰欹。","窍石天成屋，泓泉鬼斸池。","弘中远孙子，宴喜又添诗。"]},{"t":"寄题曾子与竞秀亭","f":"七言律诗","c":["老夫上下蓼花滩，每过君家辄系船。","尊酒灯前山入座，孤鸿月底水连天。","暄凉书问二千里，场屋声名三十年。","竞秀主人文似豹，不应雾隐万峰边。"]},{"t":"寄题程元成给事山居三咏 其二 秀野堂","f":"七言律诗","c":["梅竹来禽带月栽，牡丹菡萏照江开。","新安见底正如此，旧雨故人从不来。","秀色野香供雪饮，名章俊语用云裁。","无论独乐兼同乐，盏面春风翠作堆。"]},{"t":"寄题程元成给事山居三咏 其三 揽有亭","f":"七言律诗","c":["葵心一岫卓南涯，秀野诸峰走北来。","中起新亭双奄有，尽驱景物四边回。","木居士作煨尘叹，孤竹君真梁栋材。","知有此亭无此样，并烦与可洒松煤。"]},{"t":"寄题程元成给事山居三咏 其一 葵心堂","f":"七言律诗","c":["人笑戎葵定自痴，不愁曦景蚤兼迟。","便令隔雾光难到，也则倾心苦为谁。","卫足平生非我志，向阳一点只天知。","话头试问伯休父，休父丹衷便是葵。"]},{"t":"寄题福帅张子仪尚书禊游堂","f":"七言律诗","c":["祖孙接武禊堂前，风物重新六十年。","无恙钧衡旧棠荫，有光台斗继蒲鞭。","手提西郭三山月，下照南湖万顷天。","不要外人来作记，当家自有笔如椽。"]},{"t":"寄题儋耳东坡故居尊贤堂太守谭景先所作二首 其二","f":"七言律诗","c":["先生初落海南垂，茅屋三间不到伊。","更有高堂悬画像，幸无过客首新诗。","古来贤圣皆如此，身后功名属阿谁。","底事百年谭太守，却教宾主不同时。"]},{"t":"寄题儋耳东坡故居尊贤堂太守谭景先所作二首 其一","f":"七言律诗","c":["东坡无地顿危身，天赐黎山活逐臣。","万里鲸波隔希奭，千年桂酒吊灵均。","精忠塞得乾坤破，日月伴渠文字新。","祇个短檐高屋帽，青莲未是谪仙人。"]},{"t":"得寿仁寿俊二子书皆以病不及就试且报来期二首 其二","f":"五言律诗","c":["满望鹏飞上，谁令马不前。","草玄真浪苦，曳白亦无缘。","兄弟年二十，尘埃路四千。","速来饮官酒，不用一铜钱。"]},{"t":"得寿仁寿俊二子书皆以病不及就试且报来期二首 其一","f":"五言律诗","c":["二子何时到，三秋欲尽头。","收渠半张纸，洗我一年愁。","不得毛锥力，元非子墨羞。","海山寒更碧，整驾待同游。"]},{"t":"得亲老家问二首 其一","f":"五言律诗","c":["节里难为客，家中数有书。","慈亲问归否，意绪各何如。","强酒那能尽，添愁不更除。","旧来贫未仕，父子岂相疏。"]},{"t":"得亲老家问二首 其二","f":"五言律诗","c":["济世吾无策，迎亲仕屡惊。","乾坤裂未补，簪笏达何荣。","三径犹须禄，群飞不复情。","山林早回首，诗酒且平生。"]},{"t":"族人同诸友问疾二首 其二","f":"七言律诗","c":["摩诘沉痾未易排，文殊一问失妖灾。","老夫何幸群贤集，倒屣出迎双眼开。","语造极时全愈了，病知客去即重来。","呼儿细拣新书策，体不佳时看一回。"]},{"t":"族人同诸友问疾二首 其一","f":"七言律诗","c":["老无星事可营为，政是长闲好病时。","两脚倦行赢得坐，一生欠睡顿还伊。","梦闻有客欣然起，儿道勤翁乃尔痴。","抵掌纵谈天亦笑，此身安否更曾知。"]},{"t":"晚兴","f":"七言律诗","c":["老来怀抱向谁开，岁晚无花荐一杯。","处分新霜且留菊，辟差寒日早开梅。","只教诗句清如雪，看得荣名细似埃。","管葛诸人端解事，也曾遭我笑渠来。"]},{"t":"晚过侧溪山下","f":"七言律诗","c":["看山妙处几曾知，落照斜明始觉奇。","皱尽衣裳纹欲裂，争先头角远相追。","松梢别放六峰出，江底倒将千嶂垂。","一路诗篇浑漫与，侧溪端的不相亏。"]},{"t":"晚泊杨州","f":"七言律诗","c":["杨子桥西转綵航，粉城如练是维杨。","百年旧观兵戈后，近岁新开草木荒。","杰阁高台云上出，野梅官柳雪中香。","史君领客周遭看，走马归船欲夕阳。"]},{"t":"晚酌","f":"七言律诗","c":["暑天寒果饤来馊，水果清于木果休。","莲入新秋何便瘦，菱沉到底竟能浮。","山泉酿酒香仍冽，野蔌堆盘爽更幽。","方丈食前非不爱，风蝉一腹饱诗愁。"]},{"t":"晚寒","f":"五言律诗","c":["莫道今晨热，东风未得欺。","晚来作恶甚，寒似禁烟时。","约雨斜还整，吹花合且离。","不应如许峭，故故恼吾衰。"]},{"t":"晚寒炽炭","f":"七言律诗","c":["老子平生不附炎，雪间炉炭晚间添。","红光乱拆银花碎，翠燄双抽柳叶尖。","爱惜麒麟牢禁手，驱除盐絮密垂帘。","急分一炬牵船底，岸上霜风正似镰。"]},{"t":"晨炊旱塘","f":"七言律诗","c":["一岁官拘守一州，天将行役赐清游。","青山绿水留连客，碧树丹枫点缀秋。","夜梦昼思都是景，左来右去不胜酬。","我无韦偃丹青手，只向囊中句里收。"]},{"t":"晨炊泊杨村","f":"五言律诗","c":["沙步未多远，里名还异原。","对江穿野店，各路入深村。","秋水乘新汲，春芽煮不浑。","舟中争上岸，竹里有清樽。"]},{"t":"晨炊泉水塘村店无肉只卖笋蕨嘲亭父","f":"七言律诗","c":["屠门深闭底须愁，土锉无烟也莫羞。","笋便落林犹胜肉，蕨才出土更烧油。","万钱下箸今安在，一饭流匙饱即休。","吾道藜羹元不糁，至今讳杀古陈州。"]},{"t":"晨炊横塘桥酒家小窗","f":"七言律诗","c":["饥望炊烟眼欲穿，可人最是一青帘。","双渠走水穿三店，独树欹流荫两檐。","窗扇透明仍挂上，炉香未烬更多添。","山村祗苦无良酝，嫌杀芳醪似蜜甜。"]},{"t":"望姑苏","f":"七言律诗","c":["旷野平中天四垂，冻云罅里日平西。","水村人远看来短，茅屋檐长反作低。","最爱河堤能底巧，截他山脚不胜齐。","喜闻借得姑苏馆，百尺高台入杖藜。"]},{"t":"望楚州新城","f":"七言律诗","c":["已近山阳望渐宽，湖光百里见千村。","人家四面皆临水，柳树双垂便是门。","全盛向来元孔道，杂耕今是一雄藩。","金汤再葺真长策，此外犹须子细论。"]},{"t":"梅花下小饮","f":"七言律诗","c":["今年春在腊前回，怪底空山早见梅。","数点有情吹面过，一花无赖背人开。","为携竹叶浇琼树，旋折冰葩浸玉杯。","近节雨晴谁料得，明朝无兴也重来。"]},{"t":"梦种菜","f":"七言律诗","c":["背秋新理小园荒，过雨畦丁破块忙。","菜子已抽蝴蝶翅，菊花犹著郁金裳。","从教芦菔专车大，早觉蔓菁扑鼻香。","宿酒未销羹糁熟，析酲不用柘为浆。"]},{"t":"梨","f":"七言律诗","c":["挂冠大谷肯干时，饤坐风流特地奇。","骨里馨香衣不隔，胸中冰雪齿偏知。","卖浆碎捣琼为汁，解甲方怜玉作肌。","老子醉来浑谢客，见渠倒屣只嫌迟。"]},{"t":"淮河舟中晓起看雪二首 其二","f":"七言律诗","c":["梅花脑子撒成云，明月珠胎屑作尘。","爱水舞来飞就影，怯风斜去却回身。","真成一腊逢三白，并把三冬博一春。","开放船窗尽渠入，天差滕六访诗人。"]},{"t":"淮河舟中晓起看雪二首 其一","f":"七言律诗","c":["三日颠风刮地来，不成一雪肯空回。","何曾半点漏春信，只怪千花连夜开。","顷刻装严银世界，中间遍满玉楼台。","琼船撑入玻瓈国，琪树瑶林不用栽。"]},{"t":"清明日午憩黄池镇","f":"七言律诗","c":["莫笑孤村小市头，花边人出浦边游。","绿杨拂水双浮鸭，碧草粘天一落鸥。","懒困风光酣午睡，阴沉天气嫁春愁。","阿谁道是清明节，我对清明唤作秋。"]},{"t":"清明果饮二首 其二","f":"七言律诗","c":["深著炉香浅著杯，杯行尽缓莫教催。","可怜花树浑无赖，下却帘钩也入来。","雪藕新将削冰水，蔗霜只好点青梅。","明年寒食还家去，却忆荆溪花政开。"]},{"t":"清明果饮二首 其一","f":"七言律诗","c":["南溪春酒碧于江，北地鹅梨白似霜。","颓却老人山作玉，更加食邑醉为乡。","春光如许天何负，雨点殊疏燕不妨。","绝爱杞萌如紫蕨，为烹茗椀洗诗肠。"]},{"t":"清晓出城别王宣子舍人","f":"五言律诗","c":["月细惟愁落，阳升未要忙。","出门鸡未觉，夹路稻初香。","涉世宁容懒，侵星幸稍凉。","病来诗久废，觅句费商量。"]},{"t":"清晓趋郡早炊幽居延福寺","f":"五言律诗","c":["小轿欹还正，荒蹊细又纡。","危峰上金镜，远草乱琼珠。","雾外钟声近，花梢殿脊孤。","老僧知我冷，展席傍红炉。"]},{"t":"理蔬","f":"五言律诗","c":["小摘吾犹惜，频来径自成。","青虫捕仍有，蠹叶病还生。","贫里犹存灶，霜馀正可羹。","窥园未妨学，抱瓮更须营。"]},{"t":"船过灵洲","f":"七言律诗","c":["却缘野阔觉天低，政值潮平苦桨迟。","洲觜两船归别港，岸头数屋出疏篱。","江山惨淡真如画，烟雨空濛自一奇。","病酒春眠不知晓，开门拾得一篇诗。"]},{"t":"菜圃","f":"五言律诗","c":["此圃何其窄，于侬已自华。","看人浇白菜，分水及黄花。","霜熟天殊暖，风微旆亦斜。","笑摩桃竹杖，何日拄还家。"]},{"t":"萧照邻参政大资挽诗二首 其二","f":"五言律诗","c":["东府辞金印，南园伴赤松。","门阑无薏苡，泉石自从容。","忽作丁威鹤，云亡老子龙。","一哀缘殄瘁，不是涕无从。"]},{"t":"萧照邻参政大资挽诗二首 其一","f":"五言律诗","c":["父子双晁董，中兴只一家。","里刚金百鍊，表粹玉无瑕。","死力扶忠善，生平嫉佞邪。","古人少全传，公传即非夸。"]},{"t":"谒张安国","f":"七言律诗","c":["帝苑花秾记并游，万人回首看鳌头。","也知旬月应颛面，已逼云霄又作州。","别后闻公非故我，学林著脚到前修。","登门犹说同年话，未觉红鸾映白鸥。"]},{"t":"谒昌黎伯庙","f":"五言律诗","c":["南海行几遍，东潮欠一来。","若无韩子庙，只有越王台。","文字天垂日，兴亡草上埃。","聊吹鳄溪水，洒起六丁雷。"]},{"t":"谒范参政并赴袁起岩郡会坐中炽炭周围遂中火毒得疾垂死乃悟贵人多病皆养之太过耳","f":"七言律诗","c":["后炭前炉便是窑，饶君是铁也教销。","不须泉下火山狱，新制人间法外条。","今日晴明殊可喜，病夫意绪自无聊。","看来只欠刀圭药，脚踏层冰雪没腰。"]},{"t":"野炊猿藤径树下","f":"五言律诗","c":["径仄旁无地，林开忽有天。","丹枫明远树，黄叶暗鸣泉。","苔锦银枪灶，芦茸玉帐毡。","从军古云乐，乞与个山川。"]},{"t":"野菊","f":"七言律诗","c":["未与骚人当糗粮，况随流俗作重阳。","政缘在野有幽色，肯为无人减妙香。","已晚相逢半山碧，便忙也折一枝黄。","花应冷笑东篱族，犹向陶翁觅宠光。"]},{"t":"阊门外登溪船五首 其五","f":"七言律诗","c":["无家不住曲溪边，祗种高山不种田。","绝壁入天天入水，乱篙鸣石石鸣船。","百滩春浪雪头过，两岸林花镜底眠。","归路商量更舟楫，庐山彭蠡好风烟。"]},{"t":"阊门外登溪船五首 其四","f":"七言律诗","c":["选甚天时晴未晴，舟行终是胜山行。","篷忺雨点斜偏好，枕惯波声梦不惊。","幸自车徒小休息，又闻鼓笛闹将迎。","偶然回首来时路，一夜霜毛一倍生。"]},{"t":"阊门外登溪船五首 其三","f":"七言律诗","c":["当面峰头些子云，坐看吹作雨纷纷。","朝来山路能愁我，今者溪船正要君。","远岭轻盈横皱縠，明窗撩乱触惊蚊。","犹争新涨一篙碧，遮莫飘萧二十分。"]},{"t":"阊门外登溪船五首 其二","f":"七言律诗","c":["上得船来恰对山，一山顷刻变多般。","初堆翠被百千摺，忽拔青瑶三两竿。","夹岸儿童天上立，数村楼阁电中看。","平生快意何曾梦，老向阊门下急滩。"]},{"t":"阊门外登溪船五首 其一","f":"七言律诗","c":["步下新船试水初，打头揽载适逢予。","一椽板屋才经雨，两面油窗好读书。","剩买春风木芍药，乱篸棐几竹籧篨。","清溪浮取松亭子，赏遍千山不要驴。"]},{"t":"雪中登姑苏台","f":"七言律诗","c":["我亦闲来散病身，游人不用避车尘。","插天四塔云中出，隔水诸峰雪后新。","道是远瞻三百里，如何不见六千人。","吴亡越霸今安在，台下年年花草春。"]},{"t":"雪用欧阳公白战律仍禁用映雪访戴等故事赋三首示同社 其二","f":"五言律诗","c":["是雨还堪拾，非花却解飞。","儿童最无赖，抟弄肯言归。","向树翻投竹，欺人故点衣。","肩寒未妨耸，笔冻可能挥。"]},{"t":"雪用欧阳公白战律仍禁用映雪访戴等故事赋三首示同社 其三","f":"五言律诗","c":["细听无仍有，贪看立又行。","落时晨却暗，积处夜还明。","幸自漫山好，何如到夏清。","似知吾党意，未遣日华晴。"]},{"t":"雪用欧阳公白战律仍禁用映雪访戴等故事赋三首示同社 其一","f":"五言律诗","c":["夜映非真晓，山明不觉遥。","尽寒无奈爽，且落未须销。","体怯心仍爱，颜衰酒强潮。","毛锥自堪战，寸铁亦何消。"]},{"t":"雪后十日日暖雪犹未融","f":"五言律诗","c":["地冻雪起立，檐生冰倒垂。","日穿银笋透，风琢玉山欹。","今晓还差暖，清寒退尚迟。","生愁便销去，将底伴吟髭。"]},{"t":"雪后东园午望","f":"七言律诗","c":["天色轻阴小霁中，昼眠初醒未惺松。","梅横破屋无多雪，云放东山第一峰。","不道风光亏此老，将何功业答残冬。","土羔菜甲鹅儿酒，醉入梅林化作蜂。"]},{"t":"雪后陪使客游惠山寄怀尤延之","f":"七言律诗","c":["已到苏州未到常，惠山孤秀蔚苍苍。","一峰飞下如奔马，万木深围古道场。","锡骨中空都是乳，玉泉致远久偏香。","眠云跂石梁溪叟，恨杀风烟隔草堂。"]},{"t":"雪冻未解散策郡圃","f":"七言律诗","c":["积雪偏工霁后凝，不妨冷极不妨清。","静闻檐滴元无雨，倒挂冰牙未怕晴。","独往独来银粟地，一行一步玉沙声。","圃中散策饶君强，敢犯霜风上古城。"]},{"t":"雪夜候迎使客","f":"七言律诗","c":["六花不放一尘生，晴后犹馀十日凝。","新月未光输与雪，夜风尽冷只留冰。","候迎银汉槎头客，挑尽玉虫窗下灯。","纸帐蒲团地炉煖，自怜不及草庵僧。"]},{"t":"雪晴","f":"七言律诗","c":["天公有诏放朝晴，排遣云师懒未行。","头上忽张青玉伞，海东涌出紫金钲。","雪山冰谷居然暖，银屋瑶台分外明。","二十四船人笑语，寒声一变作春声。"]},{"t":"黄太守元授挽词二首 其二","f":"五言律诗","c":["我忝通家子，公如父行亲。","一书虽不欠，半面遂无因。","旅榇千江远，铭旌两竹新。","庆门宁有此，造物岂其仁。"]},{"t":"黄太守元授挽词二首 其一","f":"五言律诗","c":["五马新通贵，千牛旧不全。","岂渠才作祟，从古命悬天。","半世风波里，清名玉雪边。","诸郎俱伟器，枢属更人先。"]},{"t":"黄世成挽辞","f":"五言律诗","c":["文行高无对，功名莫动渠。","宁登逸民传，不著茂陵书。","谁谓风流尽，犹疑信息疏。","九京何所憾，玉树满庭除。"]},{"t":"黄司法妻欧阳氏孺人挽诗","f":"五言律诗","c":["法掾无双裔，夫人六一孙。","夙勤南涧藻，晚享北堂萱。","蒲圃严新槚，潘舆閟旧轩。","庭阶森玉树，驷马看高门。"]},{"t":"龚令国英约小集感冷暴下归卧感而赋焉二首 其一","f":"五言律诗","c":["客里何烦病，春馀不谓寒。","并来无计奈，那得有怀宽。","憎药犹须强，耽书更暇看。","两亲问消息，敢道不平安。"]},{"t":"龚令国英约小集感冷暴下归卧感而赋焉二首 其二","f":"五言律诗","c":["吏卒稀仍散，僮奴野自亲。","问吾适无恙，遽病此何因。","初觉身为客，还疑老逼人。","焚香发深省，一笑对残春。"]},{"t":"寒食雨作","f":"七言律诗","c":["双燕冲帘报禁烟，唤惊昼梦耸诗肩。","晚寒政与花为地，晓雨能令水作天。","桃李海棠聊病眼，清明寒食又来年。","老来不办雕新句，报答风光且一篇。"]},{"t":"寒食前三日行脚遇雨","f":"五言律诗","c":["信脚那知远，虽劳亦快哉。","如何寒食近，无数野花开。","碧草望中去，黑云头上来。","吾行吾自返，雨子不须催。"]},{"t":"寒食相将诸子游翟园得十诗 其一","f":"五言律诗","c":["雨罢饶晴色，松阴转午时。","堆成李花雪，开遍海棠枝。","旋酌新篘酒，留题细字诗。","不来真是枉，欲去更云迟。"]},{"t":"寓倅厅寒夜不寐","f":"七言律诗","c":["不堪斜雨打虚窗，只愿晴阳送晓光。","自是老人眠不著，近来春夜几曾长。","楼头吹动梅花曲，梦里犹疑燕寝香。","道是官居如客舍，等闲一宿两年强。"]},{"t":"岁晚出城","f":"五言律诗","c":["温饱能消底，奔忙自作痴。","平生脚已茧，今日鬓将丝。","山刻霜馀骨，梅临水底枝。","只嫌长落莫，不道许幽奇。"]},{"t":"惠泉分茶示正孚长老","f":"七言律诗","c":["寒泓不到十馀年，老眼重看意惘然。","漱裂苍崖玉龙口，堕成清镜雪花天。","须烦佛界三昧手，拈出茶经第二泉。","珍重赞公惊久别，且谈诗句未谈禅。"]},{"t":"普明寺见梅","f":"七言律诗","c":["城中忙失探梅期，初见僧窗一两枝。","犹喜相看那恨晚，故应更好半开时。","今冬不雪何关事，作伴孤芳却欠伊。","月落山空正幽独，慰存无酒且新诗。"]},{"t":"景灵宫闻子规","f":"七言律诗","c":["今年未有子规声，忽向宫中树上鸣。","告诉落花春不管，裴回晓月恨难平。","斜风细雨又三月，柳絮浮云空一生。","岂不怀归归未得，倩渠传语故园莺。"]},{"t":"晴后雪冻","f":"七言律诗","c":["负暄尚觉日无功，炙手仍愁火失红。","本是雪前风作雪，却缘雪后雪生风。","四郊冻合如相约，七日晴来不肯融。","旧说醉乡堪避暑，避寒也合此乡中。"]},{"t":"暑中待月小酌","f":"七言律诗","c":["火伞朝张复暮张，若教无月底禁当。","隔林欲上光先漏，窥户无多气已凉。","万里无云天似水，一奁新镜色如霜。","广寒宫里应无酒，挽住姮娥劝一觞。"]},{"t":"曾达臣挽词二首 其二","f":"五言律诗","c":["议论千千古，胸怀一一奇。","非关时弃我，不肯我干时。","老鹤云间意，长松雪外姿。","平生独知命，冷眼看人痴。"]},{"t":"曾达臣挽词二首 其一","f":"五言律诗","c":["珠冻兰溪水，冰封玉笥山。","是翁元不死，蜕骨此中间。","书画今存否，仪刑杳莫攀。","端令郡博士，陟岵泪斑斑。"]},{"t":"曾伯贡主簿挽诗二首 其二","f":"五言律诗","c":["我壮君初冠，相逢便定交。","即今俱白首，赴告忽黄茅。","人物王兼谢，诗声岛与郊。","病来无气力，不得奠兰肴。"]},{"t":"曾伯贡主簿挽诗二首 其一","f":"五言律诗","c":["练练兰溪秀，家家玉树荣。","兴安有才子，艮老是先生。","师与三冬学，诗专五字城。","一官才祭灶，作么便铭旌。"]},{"t":"朝饭罢登净远亭","f":"五言律诗","c":["近水孤亭迥，萦城一径斜。","霜林乌鹊国，冰岸鹭鸶家。","殊觉冬曦暖，还拈小扇遮。","传呼惠山水，来瀹建溪茶。"]},{"t":"登大鞋岭望大海","f":"五言律诗","c":["杖屦千崖表，波涛万顷前。","琼天吹不定，银地湿无边。","一石当流出，孤尖卓笔然。","更将垂老眼，何许看风烟。"]},{"t":"登凤凰台","f":"七言律诗","c":["千年百尺凤凰台，送尽潮回凤不回。","白鹭北头江草合，乌衣西面杏花开。","龙蟠虎踞山川在，古往今来鼓角哀。","只有谪仙留句处，春风掌管拂蛛煤。"]},{"t":"登牛渚蛾眉亭二首 其二","f":"七言律诗","c":["山拆江通万里流，菱花双照茧眉头。","扫除却月横云样，别有颦风蹙雨愁。","明月入波那可捉，长庚伴月本同游。","君看夜夜青天上，渠与姮家分管秋。"]},{"t":"登牛渚蛾眉亭二首 其一","f":"七言律诗","c":["谪仙携妓戏人寰，也被千花妒玉颜。","半点闲情千古恨，一波秋水两春山。","锦袍宫烛云霄上，白苧乌纱江海间。","欲寄双鱼招醉魄，月轮捉了蚤言还。"]},{"t":"程泰之尚书龙学挽词二首 其二","f":"五言律诗","c":["公弭江西节，侬横南浦舟。","相逢便金石，一别几春秋。","问讯频黄耳，归休各白头。","丰碑那忍读，未读涕先流。"]},{"t":"程泰之尚书龙学挽词二首 其一","f":"五言律诗","c":["庙器圭璋骨，儒林虎豹章。","韦编双辅嗣，禹迹再平当。","月冷谈经幄，尘昏弄笔床。","西州何处路，溪水咽梅乡。"]},{"t":"答陆务观佛祖道院之戏","f":"七言律诗","c":["老禅分得破丛林，薄供微斋也不曾。","道院敕差权院事，筠庵身是住庵僧。","人间赤日方如火，松下清风独似冰。","别有暮春沂水在，为君一滴洒千灯。"]},{"t":"答胡仲方赠诗","f":"七言律诗","c":["畴昔昭王渡楚江，得萍斗大嚼甘芳。","因君黄绶作此县，问古青蘋何处乡。","民乐弦歌爱言偃，天将桃李醉河阳。","望郎旧说为邑宰，邑宰今看为望郎。"]},{"t":"答胡伯圜赠诗","f":"七言律诗","c":["澹老郎君阿永贤，渥洼财驾折金鞭。","只今两子似连璧，一建双旌开二天。","白马将军震交阯，青钱学士即甘泉。","弟兄蕙茂仍兰发，顿有机云在眼前。"]},{"t":"答章汉直","f":"七言律诗","c":["诗人今代谢宣城，举手新年章子平。","雨剩风残忽春暮，花催草唤又诗成。","五湖烟水三冬卧，万里云霄一日程。","老里睡多吟里少，旧来句熟近来生。"]},{"t":"紫牡丹二首 其二","f":"七言律诗","c":["岁岁东风二月时，司花辛苦染晴枝。","夜输百斛蔷薇水，晓洗千层玉雪肌。","寒食清明空过了，姚黄魏紫不曾知。","春愁蹙得眉头破，何处如今更有诗。"]},{"t":"紫牡丹二首 其一","f":"七言律诗","c":["万花不分不春妍，至竟专春是牡丹。","紫锦香囊金屑暖，翠罗舞袖掌文寒。","恨无国色天香句，借与风条日萼看。","家有洛阳一千朵，三年归梦绕栏干。"]},{"t":"腊后二首 其二","f":"五言律诗","c":["云暗虚疑暮，江空分外寒。","如何山雨过，便尔岸沙乾。","奈此诗愁得，怀哉岁事阑。","梅残吾更忍，不折一枝看。"]},{"t":"腊夜普明寺睡觉二首 其二","f":"五言律诗","c":["作腊聊村酒，依人只短檠。","略无更可数，听到雨无声。","犬吠知何苦，鸡寒肯更鸣。","生来眠不足，老去梦难成。"]},{"t":"腊夜普明寺睡觉二首 其一","f":"五言律诗","c":["旅梦忘为客，檐声忽唤愁。","亲庭未差远，佛屋不胜秋。","只么功名是，如今悟解不。","十年行路饱，谁不遣吾休。"]},{"t":"蜑户","f":"七言律诗","c":["天公分付水生涯，从小教它踏浪花。","煮蟹当粮那识米，缉蕉为布不须纱。","夜来春涨吞沙觜，急遣儿童斸荻芽。","自笑平生老行路，银山堆里正浮家。"]},{"t":"谢人送常州草虫扇","f":"七言律诗","c":["生怕炎天老又逢，草虫扇子献奇功。","还将多稼亭前月，卷尽西湖柳上风。","蚱蜢翅轻涂翡翠，蜻蜓腰细滴猩红。","旧时绿鬓常州守，今作霜髯一秃翁。"]},{"t":"谢从善挽词","f":"五言律诗","c":["一腹储三箧，双钩挽万牛。","行身平中准，阅世澹于秋。","紫诰犹新墨，霜髯忽古丘。","清风未作记，挂剑泪川流。"]},{"t":"谢叶叔羽总领惠双淮白二首 其二","f":"七言律诗","c":["情知北味饮中瑰，暖律何缘到死灰。","去岁海红犹间识，今年淮白不曾来。","一寒尚有绨袍赠，双鲤仍随尺素回。","厚禄故人书尽绝，只馀计相解相哀。"]},{"t":"谢叶叔羽总领惠双淮白二首 其一","f":"七言律诗","c":["宝奁寡贡笑权臣，筠掩分甘荷故人。","天下众鳞谁出右，淮南双玉忽尝新。","未知丙穴果何似，只恐子鱼无此珍。","敢遣腹腴劝年少，一杯端合寿吾亲。"]},{"t":"谢永新大夫杨叔裕惠诗","f":"七言律诗","c":["今代吾家后子云，新诗也解乞陈人。","银河波浪痕痕玉，花县风光字字春。","大胜十年灯火读，更无半点簿书尘。","鹗章塞得公车破，便合留渠立紫宸。"]},{"t":"谢傅宣州安道郎中送宣城笔","f":"七言律诗","c":["忽惊骑吏叩柴荆，厚禄移书访死生。","今日犹迟傅岩雨，前身端是谢宣城。","解包兔颖霜盈把，试墨山泉月一泓。","老里苦吟翻作拙，撚须枉断两三茎。"]},{"t":"谢余处恭送七夕酒果蜜食化生儿二首 其二","f":"七言律诗","c":["新酿秦淮鸭绿坳，旋熬粔籹蜜蜂巢。","来禽浓抹日半脸，水藕初凝雪一梢。","岂有天孙千度嫁，枉同河鼓两相嘲。","渠侬有巧真堪乞，不倩蛛丝罥果肴。"]},{"t":"谢余处恭送七夕酒果蜜食化生儿二首 其一","f":"七言律诗","c":["踉蹡儿孙忽满庭，折荷骑竹臂春莺。","巧楼后夜邀牛女，留钥今朝送化生。","节物催人教老去，壶觞拜赐喜先倾。","醉眠管得银河鹊，天上归来打六更。"]},{"t":"谢张子仪尚书寄天雄附子北果十包","f":"七言律诗","c":["今古交情市道同，转头立地马牛风。","如何听履星辰客，犹念孤舟蓑笠翁。","馈药双奁芬玉雪，解包百果粲青红。","看渠即上三能去，大小毗陵说两公。"]},{"t":"谢张功父送近诗集","f":"七言律诗","c":["十年不梦软红尘，恼乱闲心得我嗔。","两夜连翻约斋集，双明再见帝城春。","莺花世界输公等，泉石膏肓叹病身。","近代风骚四诗将，非君摩垒更何人。"]},{"t":"谢李君亮赠陈中正墨","f":"七言律诗","c":["麝烟薰透大夫松，胶国吹成赤鲩公。","龙尾研磨碎苍璧，鼠须飞动出晴虹。","谁言陈子草玄手，突过蒲家读墨功。","老我久无椽样笔，为君小楷注鱼虫。"]},{"t":"谢岳大用提举郎中寄茶果药物三首 其一 日铸茶","f":"七言律诗","c":["瓷瓶蜡纸印丹砂，日铸春风出使家。","白锦秋鹰微露爪，青瑶晓树未成芽。","松梢鼓吹汤翻鼎，瓯面云烟乳作花。","唤醒老夫江海梦，呼儿索镜整乌纱。"]},{"t":"谢岳大用提举郎中寄茶果药物三首 其三 新松实","f":"七言律诗","c":["三韩万里半天松，方丈蓬莱东复东。","珠玉鍊成千岁实，冰霜吹落九秋风。","酒边腷膊牙车响，座上须臾漆櫑空。","新果新尝正新暑，绣衣使者念山翁。"]},{"t":"谢皇太子三月十九日召宴荣观堂颁赐金杯襭罗","f":"七言律诗","c":["春草池塘太液旁，水精宫殿牡丹香。","惭非绮里攀鸿翼，也侍承华宴凤庄。","玉唾银钩看落笔，绣袍金椀拜盈箱。","迎门儿女牵衣袖，搜得随侯与夜光。"]},{"t":"谢赵行之惠霜柿","f":"五言律诗","c":["红叶曾题字，乌椑昔擅场。","冻乾千颗蜜，尚带一林霜。","核有都无底，吾衰喜细尝。","惭无琼玖句，报惠不相当。"]},{"t":"谢淮东漕虞寿老宝文察院寄诗二首 其二","f":"七言律诗","c":["鹓行接翼复分襟，酒病诗愁老不禁。","十载江湖千里月，一生金石两知心。","悼亡君有安仁戚，归隐侬为梁父吟。","早晚故人天上去，未应廊庙忘山林。"]},{"t":"谢淮东漕虞寿老宝文察院寄诗二首 其一","f":"七言律诗","c":["诗吸三江捲五湖，彫琼为句字为珠。","前身谢守吟澄练，今代世南行秘书。","獬豸峨冠久尘醭，星辰听履即须臾。","夜来飞入东园去，梦里分明觉后虚。"]},{"t":"谢福建提举应仲实送新茶","f":"七言律诗","c":["词林应玚绣衣新，天上茶仙月外身。","解赠万钉苍玉胯，分尝一点建溪春。","三杯大道醺然后，七椀清风爽入神。","闻道闽山官况好，何时乞得两朱轮。"]},{"t":"谢蜀帅刘仲洪尚书龙学遣骑诒书之惠","f":"七言律诗","c":["紫衣军将打门来，云锦书从锦水回。","个是国西天一柱，早归斗下位三能。","致身将相黑头在，怜我渔樵青眼开。","旧日雪山寒刮骨，祇今移取上春台。"]},{"t":"谢潭帅余处恭左相遣骑惠书送酒三首 其三","f":"七言律诗","c":["相思命驾竟成休，投老寒盟岂自由。","雪后风涛难访戴，山间生死总依刘。","烦公赤手回青昊，容我清溪弄白鸥。","稚子尚堪驱使在，门阑桃李未应秋。"]},{"t":"谢潭帅余处恭左相遣骑惠书送酒三首 其二","f":"七言律诗","c":["鹊语灯花两太谩，三朝五夜强相驩。","打门军将还惊枕，破屋山人起著冠。","知己书从天上落，焚香手把月中看。","少陵泛爱虚名句，羡杀寒儒眼不寒。"]},{"t":"谢潭帅余处恭左相遣骑惠书送酒三首 其一","f":"七言律诗","c":["小烦上相领元戎，潭府千年一日雄。","镜样洞庭那得浪，身为天柱不须峰。","子房富贵云相似，中立安危国与同。","帝恐我公招不出，那时虚左到今冬。"]},{"t":"跋张功父通判直阁所惠约斋诗乙藁","f":"五言律诗","c":["句里勤分似，灯前得细尝。","孤芳后山种，一瓣放翁香。","苦处霜争涩，臞来鹤校强。","不应穷活计，公子也忙忙。"]},{"t":"跋陆务观剑南诗藁二首 其二","f":"七言律诗","c":["剑外归乘使者车，浙东新得左鱼符。","可怜霜鬓何人问，焉用诗名绝世无。","彫得心肝百杂碎，依前涂辙九盘纡。","少陵生在穷如虱，千载诗人拜蹇驴。"]},{"t":"跋陆务观剑南诗藁二首 其一","f":"七言律诗","c":["今代诗人后陆云，天将诗本借诗人。","重寻子美行程旧，尽拾灵均怨句新。","鬼啸狨啼巴峡雨，花红玉白剑南春。","锦囊翻罢清风起，吹仄西窗月半轮。"]},{"t":"跋姜春坊梅山诗集二首 其二","f":"七言律诗","c":["承华寮寀集鸳鸾，不减应徐宴魏园。","中有钓璜清渭叟，向来授钺少陵坛。","锦心绣口搴花草，雪椀冰瓯泻肺肝。","身到梅山得梅魄，老夫更借一枝看。"]},{"t":"跋姜春坊梅山诗集二首 其一","f":"七言律诗","c":["松风涧水打窗声，玉佩琼琚触眼明。","当昼如何挂秋月，未春特地转新莺。","只销一卷梅山集，幻出多般景物情。","老子平生有诗癖，为君焚却老陶泓。"]},{"t":"跋悟空道人墨迹","f":"五言律诗","c":["葱岭书如积，银钩墨尚新。","前身虞学士，今代卫夫人。","曲水脩兰禊，明珠采洛神。","更令添此帖，急就不须珍。"]},{"t":"跋萧彦毓梅坡诗集","f":"七言律诗","c":["西昌有客学南昌，衣钵真传快阁旁。","坡底诗人梅底醉，花为句子蕊为章。","想渠蹋月枝枝瘦，赠我盈编字字香。","若画江西后宗派，不愁禽贼不禽王。"]},{"t":"道旁槿篱","f":"七言律诗","c":["夹路疏篱锦作堆，朝开暮落复朝开。","抽心粔籹轻拖糁，近蒂燕支酽抹腮。","占破半年犹道少，何曾一日不芳来。","花中却是渠长命，换旧添新底用催。"]},{"t":"道逢王元龟阁学","f":"七言律诗","c":["秋日才升却雾中，先生更去恐群空。","古谁云远今犹古，公亦安知世重公。","轩冕何缘关此老，江山所过总清风。","我行安用相逢得，不得趋隅又北东。"]},{"t":"雁来红","f":"五言律诗","c":["开了元无雁，看来不是花。","若为黄更紫，乃借叶为葩。","藜苋真何择，鸡冠却较差。","未应犀菊辈，赤脚也容它。"]},{"t":"感兴","f":"五言律诗","c":["行役忘衰暮，逢春感物华。","一来梅岭外，三见木绵花。","山鹿宁游市，江鸥本卧沙。","红尘无了日，白发未还家。"]},{"t":"感兴","f":"七言律诗","c":["去国还家一岁阴，凤山锦水更登临。","别来蛮触几百战，险尽山川多少心。","何似闲人无藉在，不妨冷眼看升沉。","荷花正闹莲蓬嫩，月下松醪且满斟。"]},{"t":"感秋二首 其二","f":"五言律诗","c":["南国初凉日，东吴欲尽头。","露荷幽馥晓，云日澹光秋。","也爱西风爽，其如半老休。","蝉声与蛩响，计会两催愁。"]},{"t":"感秋二首 其一","f":"五言律诗","c":["今岁五十二，岂为年少人。","荷凉欣暑退，蝉苦怨秋新。","澹虑翻成感，彫诗不著尘。","小儿知得句，频掉小乌巾。"]},{"t":"新安江水自绩溪发源","f":"七言律诗","c":["金陵江水只咸腥，敢望新安江水清。","皱底玻璃还解动，瑩然酃渌却消酲。","泉从山骨无泥气，玉漱花汀作佩声。","水记茶经都未识，谪仙句里万年名。"]},{"t":"新亭送客","f":"七言律诗","c":["六朝岂是乏勋贤，为底京师不晏然。","柏壁置人天一笑，楚囚对泣后千年。","钟山唤客长南望，江水留人懒北还。","强管兴亡谈不尽，枉教吟杀夕阳蝉。"]},{"t":"新除广东常平之节感恩书怀","f":"七言律诗","c":["已愧双旌古晋陵，更堪一节古羊城。","偶逢旧治年频熟，忽署新衔手尚生。","山与君恩谁是重，身如秋叶不胜轻。","向来百鍊今绕指，一寸丹心白日明。"]},{"t":"新凉感兴","f":"七言律诗","c":["初退生衣进熟衣，新凉只与睡相宜。","草争人迹微疏处，荷怯秋风欲动时。","又是一年将过眼，如何两鬓不成丝。","中元节后新来懒，草册才抄第二诗。"]},{"t":"新栽德安牡丹透根生孙枝皆千叶种也即非接头二月二日瑞云红初开清晓起看喜而赋之","f":"五言律诗","c":["日上浑迟在，花乘绝早看。","精神百倍好，风露七分寒。","夜宴醒犹醉，晨妆湿未乾。","子孙更千亿，紫笋绕团栾。"]},{"t":"新晴","f":"七言律诗","c":["瑶霜珠露两相鲜，玉宇金钲万里宽。","欲作一晴多少日，早知祗费数朝寒。","暴禾场里鸡豚乐，试笔窗前纸墨乾。","儿女莫餐新淅饭，打头荷甔且输官。"]},{"t":"新晴东园晚步二首 其二","f":"七言律诗","c":["忙里清流也带尘，闲中底物不长新。","水将树影挥空帚，枫换秋容作好春。","自是不归归便得，老来下笔笔如神。","莺花煎煼无虚日，贱相诚斋一老人。"]},{"t":"新晴东园晚步二首 其一","f":"七言律诗","c":["一月秋阴一日晴，山禽相贺太丁宁。","不愁白发千茎雪，随喜黄庭一卷经。","晚雾薄情憎远岭，夕阳死命恋危亭。","孤吟道是无人觉，松竹喧传菊细听。"]},{"t":"新晴读樊川诗","f":"七言律诗","c":["江妃瑟里芰荷风，净扫痴云展碧穹。","嫩热便嗔疏小扇，斜阳酷爱弄飞虫。","九千刻里春长雨，万点红边花又空。","不是樊川珠玉句，日长淡杀个衰翁。"]},{"t":"新暑追凉","f":"七言律诗","c":["去岁冲炎横大江，今年度暑卧筠阳。","满园无数好亭子，一夏不知何许凉。","待等老夫亲勘当，更招幽鸟细商量。","朝慵午倦谁相伴，猫枕桃笙苦竹床。"]},{"t":"瑞香花新开五首 其五","f":"五言律诗","c":["馨德潜丘壑，春风是往还。","新从众香国，移种洞庭山。","孤韵真无对，千花夐莫攀。","骚经吾欲续，谱入芷蘅间。"]},{"t":"瑞香花新开五首 其四","f":"五言律诗","c":["雪里移苍斛，梢头点翠芒。","只销三日暖，便坼数花房。","紫袖染难透，琼肤晒转香。","小留供鼻观，开去未须忙。"]},{"t":"瑞香花新开五首 其三","f":"五言律诗","c":["短短熏笼小，团团锦帕围。","浮阳烘酒思，沈水著人衣。","抹利通家远，楠花具体微。","春愁浑瘦尽，别有瘦中肥。"]},{"t":"瑞香花新开五首 其二","f":"五言律诗","c":["老子观书倦，昏然睡思来。","梦中谁唤醒，窗外瑞香开。","只道花头细，能追国艳回。","殷勤伴幽独，渠与一瓶梅。"]},{"t":"瑞香花新开五首 其一","f":"五言律诗","c":["外著明霞绮，中裁淡玉纱。","森森千万笋，旋旋两三花。","小霁迎风喜，轻寒索幕遮。","香中真上瑞，兰麝敢名家。"]},{"t":"睡觉","f":"五言律诗","c":["小醉如无酒，寒宵似度年。","觉来因记梦，醒去不成眠。","万事从心下，三更到眼前。","清愁政无那，一雁叫霜天。"]},{"t":"睡起理发","f":"五言律诗","c":["老态随年觉，新凉与睡谋。","鹊惊茅屋晓，臂冷葛衣秋。","远岭元无约，开门便见投。","闲中多事在，一日一梳头。"]},{"t":"蒲萄架","f":"七言律诗","c":["才喜盘藤捲叶生，又惊压架暗阴成。","夏褰凉润青油幕，秋摘甘寒黑水精。","近竹犹争一尺许，抛须先罥两三茎。","今年乞种西江去，长是茅斋怯晚晴。"]},{"t":"虞丞相挽词三首 其三","f":"五言律诗","c":["一老堂堂日，诸贤得得来。","但令元气壮，患不塞尘开。","名大天难著，人亡首忍回。","东风好西去，吹泪到泉台。"]},{"t":"虞丞相挽词三首 其二","f":"五言律诗","c":["保奭方为左，希文自请西。","不劳三尺剑，已办一丸泥。","已矣归黄壤，伤哉梦白鸡。","清风谁作诵，何石不天齐。"]},{"t":"虞丞相挽词三首 其一","f":"五言律诗","c":["负荷偏宜重，经纶别有源。","雪山真将相，赤壁再乾坤。","奄忽人千古，凄凉月一痕。","世无生仲达，好手未须论。"]},{"t":"蜀士甘彦和寓张魏公门馆用予见张钦夫诗韵作二诗见赠和以谢之 其一","f":"五言律诗","c":["说著岷江士，未逢眉已申。","殷勤来相府，解逅得诗人。","不是胸中别，何缘句子新。","谈今还悼昔，喜罢反悲辛。"]},{"t":"蜀士甘彦和寓张魏公门馆用予见张钦夫诗韵作二诗见赠和以谢之 其二","f":"五言律诗","c":["夜把新诗读，灯前阖且开。","一行私独喜，两脚不虚来。","天似嫌梅晚，冬初遣雪催。","与君问花信，能绕百千回。"]},{"t":"解舟惠州东桥","f":"五言律诗","c":["南宦宁差北，西归敢再东。","猿声云树月，客枕露船风。","绿发春全白，苍颜酒不红。","莫憎愁与病，留取伴衰翁。"]},{"t":"解舟雷江过东流县","f":"五言律诗","c":["云散烟还合，天昏日半烘。","青山犹淡白，碧水欲轻红。","棹进欣恬浪，公无怨逆风。","回思五湖里，敢望大江东。"]},{"t":"路口回望方山","f":"五言律诗","c":["钟阜回头失，方山恋眼寒。","似巾檐短帽，如覆玉雕盘。","每恨青苍远，因行反覆看。","归时记面目，城里指云端。"]},{"t":"路逢故将军李显忠以符离之役私其府库士怨而溃谪居长沙","f":"五言律诗","c":["贪将如中使，兵书不误今。","只悲熊耳甲，谁怨袅蹄金。","贾傅奚同郡，朱游独折心。","书生何处说，诗罢自长吟。"]},{"t":"辞栖真室盖晋仙人李八百故居之址中有遗像云","f":"七言律诗","c":["李真宅子故依然，道院西偏古洞前。","一日身游八百里，三番花落九千年。","剑池丹井俱苍藓，绛节霓旌已碧天。","借问飞仙那用步，步行犹是地行仙。"]},{"t":"遣人探梅翟园云尚未开","f":"七言律诗","c":["传语翟园千树梅，不应藞苴索诗催。","今年雪后悄无信，去岁腊前强半开。","我欲明朝携酒去，花须连夜唤春回。","东风肯报南枝否，待釂东风三百杯。"]},{"t":"遣闷","f":"五言律诗","c":["江树深春色，村鸡薄晚声。","雨添青笠重，人减画船轻。","遣闷惟须睡，哦诗只强成。","独判连日雨，却惜半朝晴。"]},{"t":"鲈鱼","f":"七言律诗","c":["两年三度过垂虹，每过垂虹每雪中。","要与鲈鱼偿旧债，不应张翰独秋风。","买来一尾那嫌少，尚有杯羹慰老穷。","祗是莼丝无觅处，仰天大笑笑天公。"]},{"t":"鲎酱","f":"五言律诗","c":["忽有瓶罂至，捲将江海来。","玄霜冻龟壳，红雾染珠胎。","鱼鲊兼虾鲊，奴才更婢才。","平章堪一饭，断送更三杯。"]},{"t":"暮归","f":"五言律诗","c":["山色偏宜暮，桐声小作秋。","人行溪侧畔，天在树梢头。","学懒真成懒，知休却得休。","遣愁愁不去，愁尽自无愁。"]},{"t":"暮泊鼠山闻明朝有石塘之险","f":"七言律诗","c":["下水船逢上水船，夕阳仍更涩沙滩。","雁来野鸭却惊起，我与舟人俱仰看。","回望雪边山已远，如何篷底暮犹寒。","今宵莫说明朝路，万石堆心一急湍。"]},{"t":"暮雨既霁将儿辈登多稼亭","f":"七言律诗","c":["一霎滂沱一霎晴，檐间点滴尚残声。","水将树影乱揉碎，月与日光相对明。","试数六宵还五雨，坐令夏热作秋清。","儿曹小住休归去，更听风蝉子细鸣。"]},{"t":"暮寒","f":"五言律诗","c":["过雁双仍急，寒鸦只已多。","绝怜晴色好，无奈暮寒何。","眼病书休读，心劳句尚哦。","老生穷事业，此外岂无他。"]},{"t":"端午前一日含笑初拆","f":"七言律诗","c":["一点瓜香破醉眠，误它酒客枉流涎。","如何滴露牛心李，化作垂头玉井莲。","初喜晓光将莞尔，竟羞午影不嫣然。","忽看吐下金樱核，蔌蔌声乾暮叶边。"]},{"t":"端午前一日阻风鄱阳湖观竞渡","f":"七言律诗","c":["恶风夜半阻归船，端欲留人作胜缘。","千里携家观竞渡，五湖新涨政黏天。","棹翻波浪山如雪，醉杀儿郎喜欲颠。","得去更佳留亦好，吾曹何处不欣然。"]},{"t":"端午独酌","f":"七言律诗","c":["招得榴花共一觞，艾人笑杀老夫狂。","子兰赤口禳何益，正则红船看不妨。","团粽明朝便无味，菖蒲今日么生香。","一生幸免春端帖，可遣渔歌谱大章。"]},{"t":"翠樾亭前莺巢","f":"五言律诗","c":["仰听金衣语，偶窥莺妇巢。","深穿乔木里，危挂弱枝稍。","啄抱双双子，经营寸寸茅。","何时雏脱壳，新哢响交交。"]},{"t":"蜡梅","f":"五言律诗","c":["栗玉圆彫蕾，金钟细著行。","来从真蜡国，自号小黄香。","夕吹撩寒馥，晨曦透暖光。","南枝本同姓，唤我作它杨。"]},{"t":"嘲淮浪","f":"七言律诗","c":["碧琉璃地展青罗，横作一波仍万波。","突起银山倚空立，碎成雪阵掠人过。","争先打岸终谁胜，淘尽浮沙奈汝何。","借与楼船泄馀怒，摇来兀去尽从佗。"]},{"t":"横山","f":"五言律诗","c":["已过方山了，横山更绝奇。","争高一尖喜，妒逸众青追。","万马头惊拶，千旗脚恣吹。","娟峰恰三五，隔柳尚参差。"]},{"t":"横山塔","f":"五言律诗","c":["相识横山塔，于今十五年。","孤标立绝顶，秃影照清川。","寂寞无香火，将迎几舫船。","吾衰岂重过，珍重塔中仙。"]},{"t":"樱桃","f":"七言律诗","c":["樱桃一雨半彫零，更与黄鹂翠羽争。","计会小风留紫脆，殷勤落日弄红明。","摘来珠颗光如湿，走下金盘不待倾。","天上荐新旧分赐，儿童犹解忆寅清。"]},{"t":"潮阳海岸望海","f":"七言律诗","c":["动地惊风起海陬，为人吹散两眉愁。","身行岛北新春后，眼到天南最尽头。","众水更来何处著，千峰赴此却回休。","客间供给能消底，万顷烟波一白鸥。"]},{"t":"醉吟二首 其二","f":"七言律诗","c":["三春草草眼中过，未抵三冬乐事多。","烛焰双丫红再合，酒花半蕾碧千波。","孤寒霜月侬相似，跌宕雪风谁奈何。","道是闲人没勋绩，一枝樵斧一渔蓑。"]},{"t":"醉吟二首 其一","f":"七言律诗","c":["十载人间乐与忧，几曾半点到心头。","梧桐叶上秋无价，蟋蟀声中月亦愁。","暮角晓钟何日了，苍颜华发此生休。","吟颠醉蹶知无益，利走名奔有命不。"]},{"t":"题尤延之右司遂初堂二首 其二","f":"五言律诗","c":["诗瘦山如瘦，人遐室更遐。","荒林庾信宅，古木谢敷家。","医国君臣药，逃名子母瓜。","只愁归未得，绿却白鸥沙。"]},{"t":"题尤延之右司遂初堂二首 其一","f":"五言律诗","c":["漫仕风中絮，归心水上鸥。","把茅新结屋，藜杖旧经丘。","花底春勾引，灯前夜校雠。","何如添我住，二老更风流。"]},{"t":"题王宣子新作吉州学前咏归亭","f":"七言律诗","c":["使君见处我何言，且上斯亭一笑还。","便有醒然新气象，何曾改却旧江山。","咏归风味谁知点，克己工夫未减颜。","个里诸生高著眼，仕和不仕得相关。"]},{"t":"题东江刘长元勤有斋","f":"五言律诗","c":["蠹简三更寂，寒灯半点悭。","不知门外雪，已失月中山。","白璧非愁禹，黄金只铸颜。","时来漫拈出，掇取桂枝还。"]},{"t":"题永新吴景苏主簿梯云楼","f":"七言律诗","c":["谁道青云不可梯，君家楼阁与云齐。","诤臣内相名垂日，谏草词头字印泥。","我昔曾为禾水客，梦中犹忆义山西。","仇香自有家声在，岂使鸾皇棘上栖。"]},{"t":"题龙归寺壁","f":"五言律诗","c":["题字才前岁，冲寒又此行。","竹能知雨至，窗不隔江清。","走檄还曾了，禁人未肯晴。","息肩更须喜，问路可怜生。"]},{"t":"题刘寺僧房","f":"七言律诗","c":["曾醉山间金叵罗，山应识我我怀它。","顿添花竹明松桧，依旧菰蒲暗芰荷。","试问锦屏无恙否，向来梅树已无多。","未须看遍新亭榭，胜日重来一一过。"]},{"t":"题刘直卿崇兰轩","f":"五言律诗","c":["风亦何须过，林仍不厌深。","莫将春色眼，来看岁寒心。","政坐香通国，端令佩满襟。","楚人更饶舌，得免世间寻。"]},{"t":"题刘朝英进斋","f":"五言律诗","c":["灯火三更雨，诗书一古琴。","惟愁脚力软，未必圣门深。","莫笑云端树，初如涧底针。","不应将一第，用破半生心。"]},{"t":"题刘道原墓次刚直亭","f":"七言律诗","c":["山南山北蔚松楸，四海千年仰二刘。","迂叟馈缣宁冻死，伯夷种粟几时秋。","平生铁作三尺喙，土苴人间万户侯。","庐阜作江江作阜，始应父子不传休。"]},{"t":"题吉水余端蒙明府县门飞凫阁","f":"七言律诗","c":["尘外尘中尽静喧，阁前阁后且山川。","秋生疏雨微云处，月仄青原白鹭边。","眼冷庾楼聊复此，人如叶令更差贤。","从公欲往其如懒，著句无佳莫浪传。"]},{"t":"题吴江三高堂 其二 张季鹰","f":"七言律诗","c":["京洛缁尘点素衣，秋风日夕唤人归。","鲈鱼不解疏张翰，羊酪偏能留陆机。","二晋兴亡几春草，三吴人物尚渔矶。","空令千古华亭鹤，犹为诸贤说是非。"]},{"t":"题吴江三高堂 其三 陆鲁望","f":"七言律诗","c":["读尽诗书不要官，饥寒欲死岂无田。","生憎俗子慵开眼，逢著诗人便绝弦。","笠泽弁山三益友，笔床茶灶一鱼船。","羡渠赤脚弄明月，踏破五湖光底天。"]},{"t":"题吴江三高堂 其一 范蠡","f":"七言律诗","c":["霸越亡吴未害仁，不妨报国并酬身。","风云长颈无遗恨，雪月扁舟更绝尘。","还了君王采香径，须饶老子苧罗人。","鸱夷若是真高士，张陆何堪作近邻。"]},{"t":"题连沧观呈太守张几仲","f":"七言律诗","c":["开窗纳尽大江秋，天半飞楼不是楼。","独立南徐鳌绝顶，下临北固虎回头。","蒜山旧址空黄鹤，瓜步新城照白鸥。","好事主人酌诗客，风烟一眼到扬州。"]},{"t":"题龟山塔前一首唐律后一首进退格 其一","f":"七言律诗","c":["龟山独出压淮流，宝塔仍居最上头。","银笔书空天作纸，玉龙拔地海成湫。","向来一厄遭群犬，挽以六丁兼万牛。","逆血腥膻化为碧，空馀风雨鬼啾啾。"]},{"t":"题盱眙军东南第一山 其二","f":"七言律诗","c":["建隆家业大于天，庆历春风一万年。","廊庙谋谟出童蔡，笑谈京洛博幽燕。","白沟旧在鸿沟外，易水今移淮水前。","川后年来世情了，一波分护两涯船。"]},{"t":"题盱眙军东南第一山 其一","f":"七言律诗","c":["第一山头第一亭，闻名未到负平生。","不因王事略小出，那得高人同此行。","万里中原青未了，半篙淮水碧无情。","登临不觉风烟暮，肠断渔灯隔岸明。"]},{"t":"题盱眙军玻瓈泉","f":"七言律诗","c":["清如淮水未为佳，泉迸淮山好煮茶。","镕出玻瓈开海眼，更和月露瀹春芽。","仰看绝壁一千丈，削下青琼无点瑕。","从事不浇愁肺渴，临泓带雪吸冰花。"]},{"t":"题临川李子经文藁","f":"七言律诗","c":["圣经贤传紧关津，骚客诗家妙斧斤。","总被先生漏消息，不令后辈隔知闻。","都城一日纸增价，天下几人贫似君。","不要绨袍却归去，平生笑杀送穷文。"]},{"t":"题南雄驿外计堂","f":"七言律诗","c":["携家度岭夜乘槎，小泊凌江水北涯。","二月山城无菜把，一年春事又杨花。","举头海国星辰近，回顾梅山草树遮。","客子相逢闻好语，看山只欠到南华。"]},{"t":"题姜店水亭子","f":"五言律诗","c":["帘拂云间竹，窗摇水下天。","栏干斜倚处，风物正凄然。","送眼看群叟，收罾得小鲜。","可怜碧玉沼，不种一枝莲。"]},{"t":"题徐衡仲西窗诗编","f":"七言律诗","c":["江东诗老有徐郎，语带江西句子香。","秋月春花入牙颊，松风涧水出肝肠。","居仁衣钵新分似，吉甫波澜并取将。","岭表旧游君记否，荔支林里折桄榔。"]},{"t":"题浩然李致政义概堂","f":"七言律诗","c":["非侠非狂非逸民，读书谋国不谋身。","一封北阙三千牍，再活西州六万人。","雨露晚从天上落，芝兰亲见掌中新。","仁心义概丝纶语，长挂巴山月半轮。"]},{"t":"题族弟道卿贫乐斋","f":"七言律诗","c":["雪茹冰餐入骨香，帽欹驴瘦尽诗狂。","人传幼妇皆称绝，鬼笑家兄不姓方。","细雨寒灯初梦短，断丝枯木一声长。","上天已办河东赋，岂有长贫执戟郎。"]},{"t":"题曾良臣思堂","f":"五言律诗","c":["谢墅新成了，潘舆竟不归。","升堂仰遗像，下拜泣沾衣。","反哺乌何在，卧冰鱼自肥。","梦中环佩响，惊喜觉来非。"]},{"t":"题湘中馆二首 其一","f":"五言律诗","c":["清境故应好，新寒殊不胜。","征衣愁著尽，凭槛喜犹能。","乱眼船离岸，关心山见棱。","个中有句在，下语更谁曾。"]},{"t":"题谢昌国桂山堂","f":"七言律诗","c":["艮斋引袖出明光，归卧西江一草堂。","种满山中浑是桂，怪来月窟更无香。","九秋金粟供朝饭，三径黄花并夕粮。","履上星辰冠上豸，一时脱却濯沧浪。"]},{"t":"憩连岭店","f":"五言律诗","c":["此馆初明眼，前山正接眉。","热嫌连日甚，凉惜两朝迟。","雨竹何其重，风鸥不自持。","庭闱犹百里，早已豁愁思。"]},{"t":"赠节推学士","f":"七言律诗","c":["奏篇惊倒汉廷臣，一眼元无四海人。","天下无双聊小却，洛阳年少是前身。","云鹏飞上偏嫌早，雾豹深藏更几春。","宽作十年相见著，剩将风雪试松筠。"]},{"t":"赠刘景明来访","f":"七言律诗","c":["研席相从昔少年，白头谁信两苍然。","来从八桂三湘外，忆折双松十载前。","告我明朝还又别，对床终夕不成眠。","交游存没休休说，且为梅花釂玉船。"]},{"t":"赠别罗时清","f":"七言律诗","c":["四岁相从亦快哉，东游兴尽却西回。","诗中风月无疆界，圣处宫庭元洞开。","握手论文两凄断，登山临水重徘徊。","亦山亭下梅花径，明日先生独自来。"]},{"t":"赠周敬伯","f":"楚辞体","c":["万方英杰集桥门，作么吾州不数人。","之子独携一方策，短檠以外四无邻。","岁云暮矣犹为客，归去来兮未立身。","待上六鳌头上立，还家藉手拜双亲。"]},{"t":"赠尚长道签判","f":"七言律诗","c":["今代高人尚子平，风流文采旧家声。","合于玉笋班中立，却向红莲幕里行。","天色恼人浑欲雪，烛花照别若为情。","日边已办除书著，莫恋南楼秋月明。"]},{"t":"霜露","f":"五言律诗","c":["落照红犹剩，初星白未真。","霜威能夺月，寒力故欺人。","哀雁知谁怨，吟蛩独我亲。","老来忧患里，忍泪已沾巾。"]},{"t":"霰","f":"七言律诗","c":["雪花遣霰作前锋，势颇张皇欲暗空。","筛瓦巧寻疏处漏，跳阶误到暖边融。","寒声带雨山难白，冷气侵人火失红。","方讶一冬暄较甚，今宵敢叹卧如弓。"]},{"t":"赣守张子智舍人寄诗送酒和韵谢之","f":"七言律诗","c":["谁言天上张公子，飞下崆峒看晓晴。","为爱东坡题八境，却同严助厌承明。","诗来风雨荒凉后，语带江山紫翠横。","更遣曲生相暖热，十年同社再寻盟。"]},{"t":"代钱塘宰莫子章贺皇太子生辰","f":"五言古诗","c":["寒外乾坤净，霜前殿阁新。","如何震一索，顿有月重轮。","甲观堂初画，青宫榜更银。","三天同日晓，一气八荒春。","东序翻周学，南阳摘汉亲。","承祧英类祖，问寝孝通神。","帝子临京邑，藩寮著野人。","天将重九节，瑞应诞弥辰。","萸菊双为寿，山河总效珍。","前星环紫极，长照漆园椿。"]},{"t":"拟上舍寒江动碧虚诗","f":"五言古诗","c":["江远澄无底，秋深分外寒。","太虚元碧净，倒影动清湍。","浪雪翻空碎，天蓝落镜看。","光摇芦叶冷，声战蓼花乾。","画手雕心苦，诗脾觅句难。","人间那有许，我欲把渔竿。"]},{"t":"拟归院柳边迷诗","f":"五言古诗","c":["玉殿朝初退，金门马不嘶。","院深归有处，柳暗迹都迷。","紫陌春无际，青丝舞正齐。","风烟忘近远，楼阁问高低。","残雪莺声外，斜阳凤掖西。","少陵花底路，物物献诗题。"]},{"t":"拟玉水记方流诗","f":"五言古诗","c":["观水那无术，曾于往记求。","是间还韫玉，其外必方流。","缜栗渊潜久，英华气上浮。","清波皆中矩，宝祲直横秋。","金海芒相贯，璿源折以幽。","端如君子德，不病暗中投。"]},{"t":"拟吉州解试秋风楚竹冷诗","f":"五言古诗","c":["客子征行日，偏逢楚水秋。","一风来瑟瑟，万竹冷脩脩。","吹作清霜骨，声酣古渡头。","斑林寒欲裂，碧节爽还幽。","不复披襟快，长怀落帽愁。","少陵诗思苦，送别更冥搜。"]},{"t":"拟汲古得脩绠诗","f":"五言古诗","c":["学子研终古，难将短浅求。","汲深欣得得，操绠要脩脩。","远酌源千载，长缫思万周。","初如泉眼隔，忽若井花浮。","意到言前达，词于笔下流。","昌黎感秋句，圣处极冥搜。"]},{"t":"拟花蕊亚枝红诗","f":"五言古诗","c":["花密非无蕊，缤纷乱眼中。","千枝相亚闹，一色总成红。","赴晓桃如积，争晴杏欲烘。","金须迷不见，玉颊醉来同。","顿觉江山丽，都将锦绣笼。","春光谁画得，分付少陵翁。"]},{"t":"拟进士金波丽鳷鹊诗","f":"五言古诗","c":["曳练为银汉，镕金作月波。","桂华斜丽处，鳷鹊得光多。","云叶三秋净，菱花一镜磨。","宫檐晖水竹，观影澹星河。","雾湿残宵柝，霜明欲晓珂。","螭头馀映在，剑佩已相摩。"]},{"t":"鹅儿黄似酒","f":"五言古诗","c":["野水浮天碧，鹅儿弄日黄。","傍人殊秀色，似酒更风光。","破壳双翎嫩，眠沙百草香。","却将金郁鬯，试比菊衣裳。","未博山阴墨，先娱锦里觞。","沧波兼凤沼，莫遣后鹙鸧。"]},{"t":"丁未元日大庆殿拜表贺正","f":"五言古诗","c":["献岁朝未央，新霁快明发。","晨曦耿五色，宿霭欻四彻。","洗清万沟瓦，销尽一月雪。","素光从何来，晶荧落寒笏。","回瞻背阴处，犹藏半檐白。","夜来有微霜，雪上辨不得。","时于翠幕顶，拂掠见琼屑。","还将黄金日，正射白银阙。","忽然捲班出，红绿乱眼襭。","归来饮屠酥，笑向儿女说。"]},{"t":"丁酉初春和张钦夫榕溪阁五言","f":"五言古诗","c":["榕影下照水，翠蛟舒复樛。","溪光逆升檐，朱夏冻以幽。","高阁昔雨荒，奇观久风休。","南轩天遣来，山谷神与谋。","宇新址惟旧，景逝人为留。","不意猿饮潭，复见驷驾辀。","先生何孤往，野客欠从游。","愿携龙文璧，去瀹兔褐瓯。","垂手掬寒泚，移床听凉飕。","阁迥诗更超，古往今亦犹。","揽渠五字妙，觉我百疾瘳。","出山未遽误，在山未遽优。","如何近来梦，夜夜在钓舟。"]},{"t":"七月二十三日南极老人星歌上叔父十三致政一杯千岁之寿","f":"词","c":["淡溪居士登九龄，朱颜青鬓如后生。","横拖仙人绿玉杖，倒诵上帝黄庭经。","璇霄仙籍书姓名，丹霞染诰金花绫。","近来更觉双眼明，夜抄蝇头窗下灯。","登山临水两脚轻，御风骑气不用行。","何人有笔笔无尘，鹅溪一幅为写真。","乌纱白苧坐鼓琴，上有千岁长松青。","令威旁舞玄夫听，个是活底南极老人星。"]},{"t":"七月十一夜月下独酌","f":"七言古诗","c":["今岁秋阳晒人死，今宵秋月呼人起。","月光如水澡吾体，月色如霜冻吾髓。","老夫畏热如于菟，平生爱月如冰壶。","望舒可客不可孤，曲生可亲不可疏。","更招玉兔金蟾蜍，同酌山杯煮涧蔬。","来朝秋阳再作恶，今夕秋光且行乐。","遮莫参横并月落。"]},{"t":"七月十二日夜登清心阁醉吟","f":"七言律诗","c":["小楼秋夜月明底，仰不见天惟见水。","岸巾独立四无人，白月青天伴杨子。","谁知横玉作秋声，一声吹尽九陌尘。","月轮半仄吾未睡，楼角风生凉杀人。"]},{"t":"七月十日大雨晓霁登碧落堂","f":"五言古诗","c":["青天送归云，整如劳还师。","颜行有喜色，厮役争奔随。","晨曦映疏雨，宝灯贯银丝。","落面何曾湿，洒空不胜微。","老夫锐登山，半岭惊欲归。","仰视得奇观，徙倚为久之。","谁言李成巧，此画天下稀。","却登碧落堂，四面天风吹。","葛制忍秋寒，前夕酷暑时。"]},{"t":"七字长句敬饯提刑寺丞胡元之持节桂林","f":"词","c":["江西太守说谁子，只说吉州有新事。","棘闱照日动碧鳞，粉堞入云横烂银。","三年八邑邑邑熟，一任千日日日春。","君不见吉州太守清何似，白鹭江心秋见底。","除却太仓五升米，不曾遣人来向市。","四邻束脩来相看，不将入家将入官。","清名袭人冰霜寒，随风一夜入九关。","帝曰桂林五千里，象犀珠玉生海里。","安得使者人人皆如此，金捐于山珠抵水。","却从吉州夺吾侯，一州夺与三十州。","梅花一笑迎汉节，桂花八株吹岭雪。","使星归去作台星，跳过郎星与卿月。"]},{"t":"九日郡中送白菊","f":"七言律诗","c":["未应白菊减于黄，金作钿心玉作裳。","一夜西风开瘦蕾，两年南海伴重阳。","若言佳节如常日，为底寒花分外香。","挼蕊浮杯莫多著，一枝留插鬓边霜。"]},{"t":"九日招子上子西尝新酒进退格","f":"七言律诗","c":["但令有酒对篱东，管得山名不是龙。","榨里泼醅迎节里，雨中移菊自城中。","多时不饮今辞醉，一笑相欢古罕逢。","我辈明年当更健，不须子细看萸红。"]},{"t":"九日落莫忆同施少才集长沙","f":"七言古诗","c":["九月九日今朝是，五里十里正未已。","良辰美景只自美，不如且著黑棋子。","浊醪不贱有如无，黄花新寄绝交书。","三年客里两重九，去年却得登高友。","醉吟岳麓道林间，天风吹帽挂君山。","倒骑蹇驴下绝顶，眼花几落贾谊井。","如今悔狂亦懒游，不嫌清坐独醒休。"]},{"t":"九月十日同尤延之观净慈新殿","f":"五言古诗","c":["昨雨败重九，谓并败此行。","云师出小谲，垂晓偷放晴。","初愁落君后，我反先出城。","伫立已小倦，喜闻马来声。","南山有新观，大殿初落成。","入门山脊动，仰目天心横。","柱起龙活立，檐飞鹏怒升。","影入西湖中，失尽千峰棱。","天竺拉灵隐，骏奔总来庭。","老禅定何巧，幻此壮玉京。","书生茅三间，饥眠方曲肱。"]},{"t":"九月三日喜雨盖不雨四十日矣","f":"五言律诗","c":["玉帝愁闻旱，雷公怒见须。","搜龙无亸处，倒海不遗馀。","稻里云初活，荞梢雪再铺。","老农啼又笑，欲去且安居。"]},{"t":"二月二十四日寺丞田丈清叔及学中旧同舍诸丈拉予同屈祭酒颜丈几圣学官诸丈集于西湖雨中泛舟坐上二十人用迟日江山丽四句分韵赋诗余得融字呈同社","f":"词","c":["正月一度游玉壶，二月一度游真珠。","是时新霁晓光初，西湖献状无遗馀。","君王予告作寒食，来看孤山海棠色。","海棠落尽孤山空，湖上模糊眼中黑。","夜来三更湖月明，群仙下堕嬉殊庭。","东坡和靖相先后，李成郭熙在左右。","惠崇捧砚大如箕，大年落笔疾于飞。","磨墨为云洒为雨，湖波掀舞山倾欹。","画作西湖烟雨障，今晨挂在孤山上。","同来诸彦文章公，不数钱起兼吴融。","何如玉船一举百分满，一笑千峰烟雨散。"]},{"t":"二月十日留子西材翁二弟晚酌","f":"七言古诗","c":["丁流迷沉一小炷，聚作香云散香雾。","清尊相属对花前，政是一年春好处。","海棠初试川样妆，垂丝新出濯锦江。","杏花欲落桃李拆，牡丹未拆已国香。","酒行莫忙且一盏，一盏一番一行散。","遍行九径却重行，莫遣一花不相见。","酒教少酌花多看，看尽千花却深劝。","今宵无月不须灯，千树李花如昼明。"]},{"t":"人日诘朝从昌英叔出谒","f":"五言古诗","c":["四序各自佳，要不如春时。","何必花与柳，始爱春物熙。","今晨驾言出，从公南山西。","泥软屦自惬，风嫩面不知。","寒草动暖芽，晴山馀雨姿。","水日亦相媚，蹙纹生碎晖。","鸟声岂为我，我听偶自怡。","出门初惮烦，载涂乃忘归。","但令我意适，岂校出处为。","路人见我揖，属我有所思。","我不见其面，信口聊应之。","徐悟恐忤物，欲谢已莫追。","我率或似傲，彼愠独得辞。"]},{"t":"儿侄新亭相迎","f":"七言绝句","c":["送客新亭恰放灯，儿曹迎我复新亭。","百年事业何为者，送往迎来过一生。"]},{"t":"入陂子径","f":"词","c":["下一岭，上一岭，上如登天下如井，人言个是陂子径。","猿藤径里无居民，陂子径里无行人。","冷风萧萧日杲杲，露湿半青半黄草。","前日猿藤犹有猿，今此一鸟亦不喧。","树无红果草无蕊，纵有猿鸟将何餐。","两山如壁岸如削，一径缘空劣容脚。","溪声千仞撼林壑，崖石欲崩人欲落。","来日长峰径更长，陂子径荒未是荒。","蒋家三径未入手，岭南三径先断肠。"]},{"t":"入峡歌","f":"七言古诗","c":["峡山未到日日愁，峡山已到愁却休。","不是朝来愁便散，愁杀人来山不管。","昨宵远望最高尖，今朝近看云隔帘。","楼船冲雨过山下，两扇屏风生色画。","江神不遣客心惊，云去云来遮岩扃。","忽然褰云露山脚，仰见千丈翠玉削。","篙师相贺涨痕落，今夕可到鸦矶泊。"]},{"t":"八月十二日夜诚斋望月","f":"七言绝句","c":["才近中秋月已清，鸦青幕挂一团冰。","忽然觉得今宵月，元不黏天独自行。"]},{"t":"十一月二十八日雪至十二月十一日日色方暖积雪始融","f":"七言绝句","c":["日华今日始微暄，次第梅花暖更妍。","只有树阴偏得意，占它残雪不还天。"]},{"t":"十山歌呈太守胡平一 其八","f":"七言绝句","c":["贤尹如何受吏谩，青天白日万人看。","忽然一展霹雳手，尽杖偷魁窜远蛮。"]},{"t":"十山歌呈太守胡平一 其三","f":"七言绝句","c":["淦客前春荷一猪，城门卖得两千馀。","明朝回到石斧岭，连吃数刀今在无。"]},{"t":"十山歌呈太守胡平一 其二","f":"七言绝句","c":["群盗常山蛇势如，一偷捕获十偷扶。","十偷行赂一偷免，百姓如何奈得渠。"]},{"t":"十山歌呈太守胡平一 其五","f":"七言绝句","c":["后赵前丁两使君，群偷望见总星奔。","后人却笑渠侬猛，仁及偷儿不及民。"]},{"t":"十月四日同子文克信子潜子直材翁子立诸弟访三十二叔祖于小蓬莱酌酒摘金橘小集戏成长句","f":"七言古诗","c":["诚斋老子不奈静，偶拄乌藤出苔径。","独游无伴却成愁，群从同行还起兴。","每过一家添一人，须臾保社如烟云。","褰裳涉溪溪水浅，著屦度桥桥柱新。","蓬莱一点出尘外，南溪裹在千花里。","芙蓉照波上下红，琅玕绕屋东西翠。","槿篱竹户重复重，鸡鸣犬吠青霞中。","蓬莱老仙出迎客，朱颜绿发仍方瞳。","餐菊为粮露为醑，染雾作巾云作屦。","欣然领客到仙家，行尽蓬莱日未斜。","更倾仙瓢酌仙酒，酒外瓢边亦何有。","偶看小树双团栾，碧琉璃叶黄金丸。","主人忍吃不忍摘，笑道未霜犹带酸。","小僮随我勇过我，不管仙翁惜仙果。","争挽风枝拣霜颗，争献满盘来饤坐。","隔水蓬莱看绝奇，蓬莱看水海如池。","主人劝客对绝境，不饮令侬怒生瘿。","何如寄下未尽瓢，留待早梅赏疏影。"]},{"t":"又自赞","f":"五言绝句","c":["清风索我吟，明月劝我饮。","醉倒落花前，天地即衾枕。"]},{"t":"又和闻蛙","f":"五言律诗","c":["春来真底好，此辈政纵横。","身作泥中计，声从雨后增。","北人餐未惯，南食眼犹生。","灰洒知虚实，于渠似可行。"]},{"t":"又跋简斋与夫人帖","f":"七言绝句","c":["家在钱塘身在苏，扊扅消息近来疏。","极知薪水无钱买，且遣长须送乘壶。"]},{"t":"万花川谷海棠盛开进退格","f":"七言律诗","c":["四面周遭国艳丛，危亭顿在艳丛中。","天开锦幄三千丈，日透红妆一万重。","积雨乍晴偏楚楚，东风小缓莫匆匆。","为花一醉非难事，且道花醲复酒醲。"]},{"t":"三辰砚屏歌","f":"词","c":["天小紫，日淡红，月光正与日相通。","一星雪白大于黍，走近月旁无半武。","吾闻三辰不并明，如何日中见月星。","霜后梨花定非瑞，春秋获麟不应贵。","君不见八月十五夜向晨，东方亭亭升火轮，西有玉李伴金盆。","是时三辰正如许，君不著眼君莫论。","吾家大阮嗜文字，看书到晓那能睡。","三辰并光射窗几，影落砚屏不容洗。","就中月轮景特奇，桂树可数叶与枝。","炯如秋水涵荇藻，天巧此岂人能为。","怀璧未为罪，借书未为痴。","公当十袭古锦帕，如何传玩十手把，不防夜半有力者。"]},{"t":"上巳日予与沈虞卿尤延之莫仲谦招陆务观沈子寿小集张氏北园赏海棠务观持酒酹花予走笔赋长句 其一","f":"七言古诗","c":["东风吹我入锦幄，海堂点注燕支薄。","不论宜雨更宜晴，莫愁倾国与倾城。","半浓半淡晚明灭，欲开未开最奇绝。","只销一线日脚红，顷刻千株开绛雪。","伟哉诗人桑苧翁，持杯酌酒浇艳丛。","坐看玉颊添醉晕，为渠一醉何须问。"]},{"t":"上元夜里俗粉米为茧丝书吉语置其中以占一岁之福祸谓之茧卜因戏作长句","f":"七言古诗","c":["去年上元客三衢，冲雨看灯强作娱。","今年上元家里住，村落无灯惟有雨。","隔溪丛祠稍箫鼓，不知还有游人否。","儿女炊玉作茧丝，中藏吉语默有祈。","小儿祝身取官早，小女只求蚕事好。","先生平生笑儿痴，逢场亦复作儿嬉。","不愿著脚金华殿，不愿增巢上林苑。","只哦少陵七字诗，但得长年饱吃饭。","心知茧卜未必然，醉中得卜喜欲癫。"]},{"t":"上元前一日游东园看红梅三首 其二","f":"七言绝句","c":["偶看红梅到小园，凭栏送眼过前村。","山头茅屋隔孤树，篱外行人出半身。"]},{"t":"上元前一日游东园看红梅三首 其一","f":"五言绝句","c":["欲折红梅朵，看来不忍攀。","周回寻四处，恰得一枝繁。"]},{"t":"上严州乌石滩","f":"七言绝句","c":["人语相闻数尺间，其如滩恶费人牵。","已从滩下过滩上，却立前船待后船。"]},{"t":"与子上雪中入东园望春","f":"七言绝句","c":["草草东园未整齐，却于看雪最清奇。","莫嫌踏湿青鞋子，自有琼瑶隔路泥。"]},{"t":"与山庄子仁侄东园看梅四首 其三","f":"七言绝句","c":["手种江梅五百窠，小窠开早更花多。","就中一树尤清绝，恼杀先生看杀它。"]},{"t":"与次公幼舆二子登伏龟楼","f":"七言绝句","c":["周遭故国是山围，对境方知此句奇。","偶上伏龟楼上望，一环碧玉缺城西。"]},{"t":"久旱祷雨不应晴天忽落数点","f":"七言绝句","c":["烈日秋来晒杀人，青天半点更无云。","忽传天上真珠落，未到半空成水银。"]},{"t":"久病小愈雨中端午试笔四首 其四","f":"七言绝句","c":["月季元来插得成，瓶中花落叶犹青。","试将插向苍苔砌，小朵忽开双眼明。"]},{"t":"久病小愈雨中端午试笔四首 其三","f":"七言绝句","c":["春去无花可得攀，石榴不艳却明鲜。","昨朝花发今朝落，留得梢头一蒂看。"]},{"t":"久病小愈雨中端午试笔四首 其二","f":"七言绝句","c":["爱与陈玄酷作缘，馀波染指黑斓斑。","呼童汲水无来底，自掬垂檐一滴悭。"]},{"t":"之官江左舟中梳头","f":"七言绝句","c":["耐痒呼僮理乱丝，一梳一快胜千篦。","是中妙处无人会，合眼垂头到睡时。"]},{"t":"乡士李英才得老潘墨法善作墨梅复喜作诗艮斋目以三奇赠之七字予复同赋云","f":"七言古诗","c":["吾乡李君磊嵬胸，夜持云梯倚秋空。","月中夺得修月斧，斫倒南山千岁松。","束归丹灶和玉桂，燧出绿雾霏鸾龙。","捣成玄圭与苍璧，洒作横枝岁寒色。","庾岭霜林和靖园，掇入生绡供戏剧。","幻松作璧璧作梅，豪气勃郁尚不开。","琼艘满釂梅雪下，吐出西湖有声画。"]},{"t":"大儿长孺赴零陵簿示以杂言","f":"词","c":["好官易得忙不得，好人难做须著力。","汝要作好官，令公书考不可钻。","借令巧钻得，遗臭千载心为寒。","汝要作好人，东家也是横目民。","选官无选处，却与天地长青春。","老夫今年六十四，大儿壮岁初筮仕。","先人门户冷如冰，岂不愿汝取高位。","高位莫爱渠，爱了高位失丈夫。","老夫老则老，官职不要讨。","白头官里捉出来，生愁无面见草莱。","老夫不足学，圣贤有前作。","譬如著棋著到国手时，国手头上犹更尽有著。"]},{"t":"大孤山","f":"词","c":["小姑小年嫁彭郎，大姑不嫁空自孀。","小姑有夫似织女，大姑无夫如阿姮。","庐慈也曾作媒妁，执柯教与五老约。","东方一老差妙龄，匹似彭郎却老成。","大姑背面啼更道，岂有老人会年少。","大姑年来年去今亦老。"]},{"t":"子上弟折赠木犀数枝走笔谢之","f":"七言古诗","c":["我家殊未有秋色，君家先得秋消息。","西风夜入小池塘，木犀漏泄月中香。","一粒粟中香万斛，君看一梢几金粟。","门前双桂更作门，路人知是幽人屋。","数枝寄我开愁眉，欲状黄香无好诗。","君到广寒折一枝，香无两般君自知。"]},{"t":"小池荷叶雨声","f":"七言律诗","c":["午梦西湖泛烟水，画船撑入荷花底。","雨声一阵打疏篷，惊开睡眼初䰒松。","乃是池荷跳急雨，散了真珠又还聚。","幸然聚作水银泓，泻入清波无觅处。"]},{"t":"小舟","f":"七言绝句","c":["竖起青篙便是桅，片帆挂了即帆开。","渔郎袖手船头坐，一叶如飞不用催。"]},{"t":"小舟晚兴四首 其一","f":"七言绝句","c":["箬篷旧屋雨声乾，芦䕠新檐暖日眠。","枕底席边俱绿水，脚根头上两青天。"]},{"t":"小孤山","f":"词","c":["大姑老已丑，小姑少而秀。","婷婷独立水精宫，罗袜生尘飘翠袖。","彭郎坦腹方醉眠，小姑起舞春风前。","古来同室无双美，天壤乃有彭郎子。"]},{"t":"小滩三首 其二","f":"七言绝句","c":["水到滩头似语离，自知无复再归溪。","临流莫洒离人泪，幸自滩声未苦悲。"]},{"t":"小滩三首 其一","f":"七言绝句","c":["溪水无情知有情，落滩告诉不堪听。","前波到此方呜咽，后浪依前作许声。"]},{"t":"小憩二龙争珠盖两长岭夹一圜峰故名自此出官路入山路云","f":"五言古诗","c":["田路直复萦，肩舆斜还正。","如何晴三日，犹自滑一径。","缺岸有危践，方轸无稳兴。","不跌先独惊，稍坦深自庆。","肯信坐者安，不及行者病。","昨来九轨涂，可思不可更。","忽逢两苍虬，争此一照乘。","颇欲问故老，双争谁孤胜。","水声乱人语，一辞无真听。","轻风泛秧畴，众绿久未定。","崎岖从此始，辛苦何时竟。"]},{"t":"小憩土坊镇新店进退格","f":"五言律诗","c":["下轿逢新店，排门得小轩。","中间一棐几，相对两蒲团。","椽竹青留节，檐茅白带根。","明窗有遗恨，接处纸痕班。"]},{"t":"水螳螂歌","f":"七言古诗","c":["清晨洗面开篷门，巨螳螂在水上奔。","前怒两臂秋竹竿，后拖一腹春渔船。","偶然拾得破蛛网，挈取四角沉重渊。","柳上螳螂工捕蝉，水上螳螂工捕鳣。","捕蝉顿顿得蝉食，捕鳣何曾得鱼吃。"]},{"t":"己亥正月二日送李伯和提干归豫章","f":"词","c":["伯和来自西山西，西山爽气在睫眉。","胸中八索贮奇古，笔下九河走风雨。","君不见李家人物它家无，老蚌一产俱明珠。","郎罢致身已碧落，众雏争先见头角。","伯珍魁名北斗傍，仲简插脚鸳鹭行。","如何伯也袖两手，却去外台作宾友。","荆溪病守鬓星星，一见乡人双眼明。","白云飞处忽心动，不堪折柳还相送。","我自为客仍送君，梅边雪里正新春。","还家灯火更青简，给札兰台未渠晚。"]},{"t":"己酉上元后赠刘子才","f":"七言古诗","c":["书台城西幽绝处，古木排霄草荒路。","空斋深夜四无人，维予二人听春雨。","我如病鹤子茁兰，长幼不同同少年。","闻子诵书金应玉，看子落笔山飞泉。","别来几何如昨日，我老过前子非昔。","来年裹砚试集英，侧耳胪传第一声。"]},{"t":"中书胡舍人玉堂夜直用万里所和汤君雪韵和寄逆旅再和谢焉","f":"七言律诗","c":["紫禁仙人视草闲，宫云低到绮疏间。","玉妃为作回风舞，金炬高烧带笑看。","得句却嫌椽笔小，冲泥遣慰客毡单。","夜哦妙语锵鸾鹤，不觉梅梢霁日团。"]},{"t":"中元日晓登碧落堂望南北山二首 其二","f":"五言律诗","c":["米山不知重，近见三两叠。","远者淡不真，眇与天相接。","晨光染红云，正向山外贴。","映出青万层，还与云俱灭。"]},{"t":"中元日晓登碧落堂望南北山二首 其一","f":"五言律诗","c":["节里少公事，底忙起侵晨。","望秋怯残暑，及此东未暾。","登山俯平野，万壑皆白云。","身在白云上，不知云绕身。"]},{"t":"中秋月长句","f":"七言古诗","c":["西山走下丹砂丸，东山飞上黄金盘。","径从碧海升青天，半湿尚带波涛痕。","初辉淡淡寒不动，月华犹轻桂华重。","黄罗团扇暗花纹，蹙金突起双龙凤。","须臾正面天中央，银钲退尽向来黄。","乾坤镕入冰壶里，万象都无只有光。","平生爱月爱今夕，古人与我同此癖。","去年中秋天漆黑，今年中秋月雪白。","先生旧不论升斗，近来畏病不饮酒。","月下醒眼搔白首，明年月似今宵否。"]},{"t":"中涂小歇","f":"七言律诗","c":["山僮问游何许村，莫问何许但出门。","脚根倦时且小歇，山色佳处须细看。","道逢田父遮侬住，说与前头看山去。","寄下君家老瓦盆，它日重游却来取。"]},{"t":"丹阳舍舟登车渡江","f":"七言律诗","c":["小泊楼船铁瓮城，匆匆又作绝江行。","看他蜡烛几回剪，听尽鸡声不肯明。","水底霜寒还十倍，夜来月上恰三更。","篙师好语君知否，江面侵晨镜样平。"]},{"t":"为牡丹去草","f":"七言绝句","c":["手种名花梦亦随，一年年望好花枝。","为花去草优饶处，两袖青苔十指泥。"]},{"t":"书王右丞诗后","f":"七言绝句","c":["晚因子厚识渊明，早学苏州得右丞。","忽梦少陵谈句法，劝参庾信谒阴铿。"]},{"t":"书莫读","f":"词","c":["书莫读，诗莫吟。","读书两眼枯见骨，吟诗个字呕出心。","人言读书乐，人言吟诗好。","口吻长作秋虫声，只令君瘦令君老。","君瘦君老且勿论，傍人听之亦烦恼。","何如闭目坐斋房，下帘扫地自焚香。","听风听雨都有味，健来即行倦来睡。"]},{"t":"予因集杜句跋杜诗呈监试谢昌国察院谢丈复集杜句见赠予以百家衣报之","f":"楚辞体","c":["棘围深锁武成宫，华裾织翠青如葱。","谢公文章如虎豹，林间一啸四山风。","天下几人学杜甫，千江隔兮万山阻。","画地为饼未必似，更觉良工心独苦。","谁登李杜坛，浩如海波翻。","奄有二子成三人，古风萧萧笔追还。","我诗如曹郐，拆东补西裳作带。","令人还忆谢玄晖，昆崙虞泉入马蹄。","我愿四方上下逐东野，只有相逢无别离。"]},{"t":"云龙歌调陆务观","f":"词","c":["墨池杨子云，云间陆士龙。","天憎二子巧言语，只遣相别无相逢。","长安市上忽再值，向来一别三千岁。","王母桃花落几番，北斗柄烂银河乾。","双鬓成丝丝似雪，两翁对面面如丹。","借问别来各何向，渭水东流我西上。","金印斗大直几钱，锦囊山齐今几篇。","诗家不愁吟不彻，只愁天地无风月。","君不见汉家平津侯，东阁冠盖如云浮。","又不见当时大将军，公卿雅拜如星奔。","祗今云散星亦散，也无鹿登台榭羊登坟。","何时与君上庐阜，都将砚水供瀑布。","磨镰更斫扶桑树，捣皮作纸裁烟雾，云锦天机织诗句。","孤山海棠今已开，上巳未有游人来。","与君火急到一回，一杯一杯复一杯。","管他玉山颓不颓，诗名于我何有哉。"]},{"t":"五月三日早起步东园示幼舆子二首 其一","f":"七言绝句","c":["雨香不及露华香，竹液花膏馥葛裳。","侬与晓星成二客，更无人共上番凉。"]},{"t":"初二日苦热","f":"词","c":["人言“长江无六月，”我言六月无长江。","只今五月已如许，六月更来何可当。","船仓周围各五尺，且道此中底宽窄。","上下东西与南北，一面是水五面日。","日光煮水复成汤，此外何处能清凉。","掀篷更无风半点，挥扇只有汗如浆。","吾曹避暑自无处，飞蝇投吾求避暑。","吾不解飞且此住，飞蝇解飞不飞去。"]},{"t":"五羊官舍春尽晚步西园荷桥","f":"七言绝句","c":["波底金鸦夺眼明，脚根螮蝀界天横。","瘦藤欲度还休去，试数荷钱几个生。"]},{"t":"五更过无锡县寄怀范参政尤侍郎","f":"七言律诗","c":["苏州欲见石湖老，到得苏州发更了。","锡山欲见尤梁溪，过却锡山元不知。","起来灵岩在何许，回首惠山亦无处。","人生万事不可期，怏然却向常州去。"]},{"t":"六月十六日夜南溪望月","f":"五言古诗","c":["溪水留我住，溪月愁我归。","望后月更佳，昨宵未为奇。","大都月色好，一岁能几时。","人散长是早，月来长是迟。","初出如大瓮，才露金半规。","不知独何急，下如有人推。","忽然脱岭尖，行空安不危。","似爱溪水净，下浴青琉璃。","明珠径馀尺，沈在千顷陂。","我欲刺双手，就溪取团晖。","白小忽乱跳，碎作万金徽。","须臾波痕定，化为水银池。","夜久看未足，风露欺病肌。","我能尚小留，瘦藤歌式微。","一笑顾群从，来夕肯集兹。"]},{"t":"六月初四日往云际院田间雨足喜而赋之二首 其一","f":"七言绝句","c":["高下田畴水斗鸣，泥深路滑不堪行。","请君听取行人语，只个愁声是喜声。"]},{"t":"六月晦日","f":"七言绝句","c":["今年六月热全无，不是云阴即雨馀。","松叶落阶休扫动，黄金线织滑氍毹。"]},{"t":"午热","f":"七言绝句","c":["也无半点爽风吹，坐轿分明是甑炊。","宿处问来犹五里，火轮煽得正炎时。"]},{"t":"午睡起","f":"五言古诗","c":["永昼能不倦，亭午思小睡。","竹床热如晒，展转竟无寐。","起来搔白首，百匝绕檐际。","政当眊氉中，忽有一奇事。","一风北户来，穿度南窗外。","窗外蕙初花，披拂动香气。","老夫得一凉，洒然有生意。","来日当此时，未知复何似。"]},{"t":"午憩马家店","f":"五言律诗","c":["两日田间路，泥深恼杀侬。","却从平地上，再入乱山中。","水送随行日，窗留退后峰。","生衣兼草靸，年例试春风。"]},{"t":"午憩东塘近白干江西地尽于此","f":"五言律诗","c":["日以秋还短，涂缘热故长。","也知茅店小，奈此竹风凉。","更远终然到，而吾有底忙。","欲行犹小驻，咫尺便它乡。"]},{"t":"午憩筠庵","f":"五言古诗","c":["筠庵偶坐处，适当树阙间。","远山不见我，而我见远山。","清风隔江来，宛转入松关。","翠蕉自摇扇，白羽得暂闲。","可怜三竹床，睡遍复循环。","秋暑自秋暑，山寒自山寒。","小吟聊适意，美恶不必删。"]},{"t":"双峰定水璘老送木犀香五首 其五","f":"五言绝句","c":["谁言定水禅，入定似枯木。","飞入广寒宫，收得香万斛。"]},{"t":"双峰定水璘老送木犀香五首 其四","f":"五言绝句","c":["传语双峰老，汝师是如来。","如何一瓣香，却为杨诚斋。"]},{"t":"双峰定水璘老送木犀香五首 其三","f":"五言绝句","c":["山童不解事，著火太酷烈。","要输不尽香，急唤薄银叶。"]},{"t":"天丝行","f":"七言古诗","c":["天孙懒困抛云机，却倩月姊看残丝。","玉兔偷将乞风伯，和机失却天未知。","风伯得丝那解织，未尝躬桑那解惜。","掀髯一笑戏一吹，散入寒空收不得。","晓来翠岭瑩无痕，片云忽裂落岭根。","须臾吹作万缕银，乃是天丝不是云。","远山成练不曾捲，近林成纱未经剪。","坐看斜飞拂面来，分明是丝寻不见。","元来著面化成水，是水是丝问谁子。"]},{"t":"太平寺水郡人徐友画清济贯河","f":"词","c":["太平古寺劫灰馀，夕阳惟照一塔孤。","得得来看还不乐，竹茎荒处破殿虚。","偶逢老僧听僧话，道是壁间留古画。","徐生绝笔今百年，祖师相传妙天下。","壁如雪色一丈许，徐生画水才盈堵。","横看侧看只么是，分明是画不是水。","中有清济一线波，横贯万里浊浪之黄河。","雷奔电卷尽渠猛，独清元自不随它。","波痕尽处忽掀怒，搅动一河秋色暮。","分明是水不是画，老眼向来元自误。","佛庐化作金柁楼，银山雪堆风打头。","是身飘然在中流，夺得太一莲叶舟。","僧言此画难再觅，官归江西却相忆。","并州剪刀剪不得，鹅溪疋绢官莫惜，貌取秋涛悬坐侧。"]},{"t":"尤延之和予新凉五言末章有早归山林之句复和谢焉","f":"五言古诗","c":["投分讵云稀，会心谅亡几。","从君澹何奇，与我凛独至。","相逢情若忘，每别怀不已。","偶因新凉篇，令予懦全起。","藉草分涧芳，陟巘共石髓。","松阴俯逝波，不徐亦不駃。","平生还山约，终食能忘此。","可怜各异县，千里复三倍。","它日寄相思，百书那写意。","从今可相疏，却叹日为岁。"]},{"t":"尤延之检正直庐窗前红木犀一小株盛开戏呈延之","f":"七言律诗","c":["水沈国里御风归，栗玉肌肤不肯肥。","元是金华学仙子，新将柿叶染秋衣。","不应装束追时好，无乃清癯悔昨非。","为妒尤郎得尤物，故将七字恼芳菲。"]},{"t":"无讼堂观檐间蛛丝","f":"七言绝句","c":["蜘蛛作网祇愁疏，密了还遭小雨馀。","漏却飞虫浑细事，无妨网得万真珠。"]},{"t":"日出","f":"七言绝句","c":["散云作雾恰昏昏，收雾依前复作云。","一面红金大圆镜，尽销云雾照乾坤。"]},{"t":"木犀初发","f":"七言律诗","c":["可笑诗人山泽臞，平生枯淡不敷腴。","已搜杞菊到诒厥，绝与木犀亲友于。","挼入杯中金粟走，满浇天上桂华孤。","醉眠绕枕两三朵，香冰肝脾酒更无。"]},{"t":"诚斋步月止酒","f":"五言古诗","c":["止酒先立约，庶几守得坚。","自约复自守，事亦未必然。","约语未出口，意已惨不驩。","平生死爱酒，爱酒宁弃官。","忆昔少年日，与酒为忘年。","醉则卧香草，落花为绣毡。","觉来月已上，复饮落花前。","衰肠不禁酒，此事今莫论。","因酒屡作病，自祟非关天。","朝来腹告痛，饮药痛不痊。","锐欲绝伯雅，已书绝交篇。","如何酒未绝，告至愁已先。","我与意为仇，意惨我何便。","不如且快意，伯雅再遣前。","来日若再病，旋旋商量看。"]},{"t":"水仙盛开留子上弟小酌","f":"五言古诗","c":["手种凌波香，今岁便十斛。","要知诚斋中，富底水仙国。","有酒偏欠花，有花恨无客。","与子对花前，不醉便了得。","待劝已非真，不劝两自索。","安知醉与醒，今夕定何夕。"]},{"t":"水精脍","f":"词","c":["上饶灵山无它灵，空山满腹著水精。","炯然非石亦非玉，乃是阴崖绝壑千秋万岁之坚冰。","只知灵山有爽气，谁知水精有奇味。","诗人新试餐玉方，解遣坚凝作松脆。","银刀细下雪缕飞，金盘饤出琼瑶堆。","齿牙著处霜霰响，殽鲭厌后胸襟开。","尊前欢伯来督战，坐上嘉宾欲惊散。","胸中自有水精宫，不怕醉乡无畔岸。"]},{"t":"牛尾狸","f":"七言律诗","c":["狐公韵胜冰玉肌，字则未闻名季狸。","误随齐相燧牛尾，策勋封作糟丘子。","子孙世世袭膏粱，黄雀子鱼鸿雁行。","先生试与季狸语，有味其言须听取。"]},{"t":"见张定叟","f":"五言律诗","c":["蜀士冠朝士，最谈苏与张。","少公今是似，相国未应亡。","黄阁如寒素，青春已老苍。","新功知更进，馀事出文章。"]},{"t":"见澹庵胡先生舍人","f":"七言律诗","c":["澹翁家近醉翁家，二老风流莫等差。","黄帽朱耶饱烟雨，白头紫禁判莺花。","补天老手何须石，行地新堤早著沙。","三岁别公千里见，端能解榻瀹春芽。"]},{"t":"长句寄周舍人子充","f":"七言古诗","c":["省斋先生太高寒，肯将好官博好山。","又告君王觅闲散，要读短檠三万卷。","州家新画瑞雾图，渠莫错认何关渠。","青原两公复双起，山川出云不在此。","自怜无地寄病身，四海知己非无人。","老穷只是诗自误，春色撩人又成句。"]},{"t":"风花","f":"七言律诗","c":["海棠桃李雨中空，更著清明两日风。","风似病癫无藉在，花如中酒不惺松。","身行楚峤远更远，家寄秦淮东复东。","道是残红何足惜，后来并恐没残红。"]},{"t":"风雨","f":"七言律诗","c":["残风剩雨故欺人，垂箔关窗护病身。","自拾荷花揩面汗，新将笋箨制头巾。","梅天笔墨都生醭，棐几文书懒拂尘。","帽子一峰青可掇，隔墙不敢略开门。"]},{"t":"风急落梅","f":"七言绝句","c":["梅花已是不胜癯，无赖东风特地粗。","狼籍玉英浑不惜，强留嫣蒂与枯须。"]},{"t":"丙戌上元后和昌英叔李花","f":"七言律诗","c":["春暖何缘雪压山，香来初认李花繁。","露酣月蕊苍茫外，梅与山矾伯仲间。","剩雨残风底无赖，明朝后日不堪看。","泥深小忍春游脚，犹遣青童去一攀。"]},{"t":"丙寅人日送药者周叔亮归吉水县","f":"词","c":["拔草不拔根，塞水不塞源。","忽然草生更水长，败却禾稼仍滔天。","老夫昔岁得淋疾，初谓一日今两年。","服药六千六百盏，望舒二十二回圆。","偶逢周郎顾，一脉擒二竖。","发药何用多，刀圭起沉痼。","向来肝肠痛如割，今来疾痛全然脱。","捉著根源尽扫除，周郎神医天下无。"]},{"t":"东园幽步见东山四首 其一","f":"七言绝句","c":["日日花开日日新，问天乞得自由身。","不知白发苍颜里，更看南溪几个春。"]},{"t":"东园醉望暮山","f":"五言古诗","c":["我住北山下，南山横我前。","北山似怀抱，南山如髻鬟。","怀抱冬独暖，髻鬟春最鲜。","松鬈沐初净，山蘤插更妍。","我来犹斜阳，我望忽夕烟。","一望便应去，不合久凭栏。","山意本日惜，如何许人看。","急将白锦障，小隔青鬌颜。","近翠成远淡，缥渺天外仙。","谁知绝奇处，政在有无间。","顷刻万姿态，可玩不可传。"]},{"t":"东碛滩","f":"五言古诗","c":["江船初上滩，滩水政勃怒。","船工与水斗，水力拦船住。","琉璃忽破碎，冰雪迸吞吐。","竟令水柔伏，低头船底去。","朝来发盈川，已过滩十许。","但闻浪喧阗，未睹水态度。","却缘看后船，偶尔见奇处。","从此至三衢，犹有滩四五。"]},{"t":"兰花五言","f":"五言律诗","c":["护雨重重膜，凌霜早早春。","三菲碧弹指，一笑紫翻唇。","野竹元同操，官梅晚卜邻。","花中不儿女，格外更幽芬。"]},{"t":"兰溪女儿浦晓寒","f":"七言律诗","c":["前年寒早热亦早，去年寒迟热亦迟。","何曾寒暑有迟速，通融三年那兑支。","人生何必早得意，芍药荣时牡丹瘁。","荣枯迟速一笑休，顺风今日好行舟。"]},{"t":"兰溪双塔","f":"七言绝句","c":["高塔无尖低塔尖，一披锦衲一银衫。","问渠何故终不语，却倩滩声替佛谈。"]},{"t":"出蛱二首 其一","f":"七言绝句","c":["朝来入峡闷船迟，也有欣然出峡时。","山色亦如人送客，送行倦了自应归。"]},{"t":"古风送刘季游试艺南宫","f":"七言古诗","c":["西溪先生刘夫子，个是国士天下士。","家庭孝友春里风，义气高寒秋后水。","艮斋荐书叫九关，重华表闾上半天。","人冤有德却无位，天报芝兰满阶砌。","诸孙个个九凤雏，此郎轩轩千里驹。","槐花再登乡老书，桃花一跳化龙鱼。","堂上双亲黑头在，日唤子孙倚门待。","绿衣归上千岁觞，还我西溪读书债。"]},{"t":"古风敬饯吉州梁史君","f":"七言古诗","c":["南方儒先囿三山，山中豹蔚推伯鸾。","手拿枝桂下广寒，身作德星南斗间。","治行第一闻九关，再分鱼书朱两幡。","丰湖夜敲坡老门，螺浦晓酌六一泉，露冕期月惠化传。","青原改色白鹭妍，白叟鼓腹黄童颠。","曲生打开禁酒国，云子凑集移粟船。","向来醉人号一瑞，如今醉人横路眠。","满城米贱酒更贱，尽道人皆有一天。","如何癖爱香火缘，三章叫阍觅散仙。","定知不晚当赐环，金貂玉佩香案前。"]},{"t":"古风敬饯都运焕章雷吏部祗召入觐","f":"七言古诗","c":["高皇中兴社稷臣，紫岩先生第一人。","来从紫岩住紫盖，鸿钧转作湘中春。","风流人物被草木，香满橘洲连岳麓。","一时宾客盛邹枚，明月夜光和结绿。","雷家夫子龙凤章，优入其室升其堂。","朱幡玉节遍南纪，锦帐绫衾推望郎。","使星下照翼轸旁，西山南浦回风光。","渠侬别有经世具，袖却两手惟深藏。","玉皇唤渠登庙廊，小却犹在持橐行。","野人亦忝同门者，久挂衣冠卧林下。","病身只合钓烟波，儿辈犹堪累甄冶。"]},{"t":"古路","f":"五言古诗","c":["我生倦行路，此行欣不辞。","我岂与人异，厌闲乐驱驰。","王事当有行，忘身那自知。","闽盗入吾部，梅川作潢池。","白羽飞赤囊，碧油走红旗。","履霜戒不早，蔓草要勿滋。","士皆冲冠怒，人挟报国私。","我行梅始花，我归柳应丝。","会当挥蝥弧，一笑封鲸鲵。","休愁荦确路，即赋竞病诗。"]},{"t":"四月二十八日祠禄秩满喜罢感恩进退格","f":"七言律诗","c":["随牒江湖四十年，寄名台阁两三番。","全家廪食皆天赐，晚岁祠官是地仙。","匹似分司转闲散，也无拜表及寒温。","明朝更省毛锥力，十字名衔尚请钱。"]},{"t":"四月二日进士唱名万里以省试官待罪殿庐遇林谦之说诗夜归又得林柬因纪其事","f":"五言古诗","c":["清晓朝帝所，就列复少须。","不逢林夫子，于何得故吾。","宫云霁犹未，宸风爽亦初。","说诗怜新体，信美古则无。","将无古人拙，未必今制疏。","夜归辱良讯，送似谈笑馀。","病怀翻不乐，此意从谁舒。","短歌纪幽事，老矣复焉如。"]},{"t":"四月十三日度鄱阳湖","f":"五言古诗","c":["泊舟番君湖，风雨至夜半。","求济敢自必，苟安固所愿。","孤愁知无益，暂忍复永叹。","夜久忽自睡，倦极不知旦。","舟人呼我起，顺风不容缓。","半篙已湖心，一叶恰镜面。","仰见云衣开，侧视帆腹满。","天如琉璃钟，下覆水晶椀。","波光金汁泻，日影银柱贯。","康山杯中蛭，庐阜帆前幔。","豁然地无蒂，渺若海不岸。","是身若虚空，御气游汗漫。","初忧触危涛，不意拾奇观。","近岁六暄凉，此水三往返。","未涉每不宁，既济辄复玩。","游倦当自归，非为猿鹤怨。"]},{"t":"四月三日登度雪台感兴","f":"五言古诗","c":["高台喜登眺，登眺触老情。","入夏又涉三，馀春安得停。","雨栏漂耄丹，风架舞壮青。","秧生麦将熟，桑尽茧已成。","盛衰亦其常，无悴岂有荣。","古今非千载，一瞬即古今。","慨然顾八荒，此理谁与评。","我友谅无益，有益或曲生。","生虽不能言，其言如震霆。","但令我怀遣，未问醉与醒。"]},{"t":"四印室长句效刘信夫作呈信夫","f":"七言古诗","c":["广文眼力自超然，作室题诗字字研。","愤世嫉邪聊尔耳，未必崔君真鹤言。","涪州别驾亦浪语，渠家四印何曾铸。","漫向世人言养生，涪州却回宜州去。","广文平生不解愁，只将诗句敌清秋。","白浪如山风打头，江南江北一虚舟。","坐上无毡惟有客，青灯枉草强边策。","万言万当不如默，误人又指庭前柏。"]},{"t":"四美堂","f":"词","c":["义山禾水在处在，明月清风无地无。","光禄子孙宁底巧，不应造物独私渠。","君不见谢家名子取四字，段家作堂兼四美。","主人自有笔如椽，何用殷勤问杨子。"]},{"t":"圣笔石湖大字歌","f":"七言古诗","c":["石湖仙人补天手，整顿乾坤屈伸肘。","尔来化作懒卧龙，簸弄珠玑漱琼玖。","五云万里天九重，玉皇深拱蓬莱宫。","岂无九虎守阊阖，北门半扉当朔风。","夜令云师敕风伯，鞭起卧龙湖底月。","湖水卷上天中央，却烦北门护风雪。","仙人驭风乘绿云，玉宸殿上朝帝真。","帝将北斗酌天酒，冰桃碧藕脯麒麟。","传呼玉蜍吸银浦，黟霜调冰浇月兔。","洒成羲画河洛书，白璧一双浮雨露。","石湖二字天上归，奎星壁宿落山扉。","昭回下饰吴花草，姑苏台前近太微。","诗人不直一杯水，自是渠侬命如纸。","教人妒杀石湖仙，手揽星辰怀袖底。"]},{"t":"平望夜景","f":"词","c":["二鼕鼕，三当当。","夜泊平望更点长，新月无光湖有光。","昨宵一雪今宵霜，犬吠两岸归人忙。","夜深人静无一事，画烛泣残人欲睡。","忽有渔船外水来，一棹波声风雨至。","半生堕在红尘中，浮家东吴东复东。","楼船夜宿琉璃国，谁言别有水精宫。"]},{"t":"幼圃","f":"七言律诗","c":["寓舍中庭劣半弓，燕泥为圃石为墉。","瑞香萱草一两本，葱叶蔊苗三四丛。","稚子落成小金谷，蜗牛卜筑别珠宫。","也思日涉随儿戏，一径惟看蚁得通。"]},{"t":"归涂观刘寺新叠石山","f":"七言律诗","c":["风月肝脾冰雪胸，道人妙手凿虚空。","斸翻诸岭云烟骨，幻出山岩紫翠峰。","细看分明非饤饾，如何彫得许玲珑。","为谁苦死忙归去，知是斜阳是晚钟。"]},{"t":"戊子正月六日雷雨感叹示寿仁子","f":"五言古诗","c":["今晨忽雷雨，天地又发春。","草木閟红绿，生意察已欣。","蛰虫且徐动，馀寒未全仁。","先生起裹头，三叹一再颦。","春风吹万物，不吹先生贫。","靖怨一束书，只博两裤尘。","自倚文字工，竟取造物嗔。","小儿在傍笑，笑我浪苦辛。","去年作客子，椒柏羡主人。","在家不差胜，更用愁此身。","先生亦一莞，我不如儿真。","为我满眼酤，不问醨与醇。","杖头日百钱，无钱借诸邻。","不然衣可典，及此花柳新。"]},{"t":"正月十二日游东坡白鹤峰故居其北思无邪斋真迹犹存","f":"七言古诗","c":["诗人自古例迁谪，苏李夜郎并惠州。","人言造物困嘲弄，故遣各捉一处囚。","不知天公爱佳句，曲与诗人为地头。","诗人眼底高四海，万象不足供诗愁。","帝将湖海赐汤沐，仅仅可以当冥搜。","却令玉堂挥翰手，为提椽笔判罗浮。","罗浮山色浓泼黛，丰湖水光先得秋。","东坡日与群仙游，朝发昆阆夕不周。","云冠霞佩照宇宙，金章玉句鸣天球。","但登诗坛将骚雅，底用蚁穴封王侯。","元符诸贤下石者，祗与千载掩鼻羞。","我来剥啄王粲宅，鹤峰无恙江空流。","安知先生百岁后，不来弄月白蘋洲。","无人挽住乞一句，犹道雪乳冰湍不。","当年醉里题壁处，六丁已遣雷电收。","独遗无邪四个字，鸾飘凤泊蟠银钩。","如今亦无合江楼，嘉祐破寺风飕飕。"]},{"t":"正月三日宿范氏庄四首 其四","f":"五言古诗","c":["山历愁寡天，沙征恨多地。","两日行海滨，虽近弥不至。","遐瞻道旁堠，我进渠祗退。","大风来无隔，午燠皎安避。","今夕范氏庄，初觌三峰翠。","愈远故绝瑕，不多始足贵。","巉然半几出，蹙若一拳细。","轻霏澹晚秀，隤照烨春媚。","玩久有馀佳，绘苦未必似。","今夕勿掩扉，月中对山睡。"]},{"t":"正月三日宿范氏庄四首 其三","f":"五言古诗","c":["酒名忘忧物，未尽酒所长。","醉后忘我身，安得忧可忘。","我饮初不多，不可无一觞。","平生难为酒，甘醴断不尝。","要与水争色，仍复菊敌香。","气盎春午花，味凛秋旭霜。","三杯合自然，一滴诣醉乡。","朅来困行役，名酒安可常。","甘淡俱不择，芳冽那得将。","酒味何必佳，一醉径投床。","但令有可饮，不醉亦何妨。"]},{"t":"正月三日宿范氏庄四首 其二","f":"五言古诗","c":["野践得幽咏，不吐聊自味。","健步忽传呼，云有远书至。","开缄祗暄凉，此外无一事。","奇怀坐消泯，追省宁复记。","方驩遽成闷，俗物真败意。","山鹊下虚庭，对语含喜气。","一笑起振衣，吾心本无滞。"]},{"t":"正月三日宿范氏庄四首 其一","f":"五言古诗","c":["开岁又涉三，我征良未休。","沙行地一平，百里纵遐眸。","景穆物自欣，碛迥情反愁。","中田缅云庄，聊复税我辀。","追程有底急，行急能至不。","三峰从何来，骏奔若鸣驺。","当户不忍去，裴回为人留。","对之成四友，呼酒与献酬。","我醉山自醒，相忘却相求。"]},{"t":"正月五日以送伴借官侍宴集英殿十口号 其六","f":"七言绝句","c":["已赐仪鸾锦坐蒲，起来再立听传胪。","君王欲劝群臣酒，宣示天杯一滴无。"]},{"t":"正月晦日自英州舍舟出陆北风大作","f":"七言律诗","c":["北风吹得山石裂，北风冻得人骨折。","南来何曾识此寒，便恐明朝丈深雪。","今朝幸不就船行，白浪打船君更惊。","只是山行也不好，笋舆寸步风吹倒。"]},{"t":"永和遇风","f":"七言律诗","c":["未嫌春晚不多花，只爱青原绿似瓜。","剩欲开怀纳岩壑，可堪病眼著风沙。","待船小立看鸥没，倚杖微吟尽帽斜。","客里更无诗遣闷，不愁两鬓不成华。"]},{"t":"玉井亭观白莲二首 其二","f":"七言绝句","c":["白莲出水是青莲，昨日微舒带酒颜。","踏月来看开尽了，露华新洗玉杯寒。"]},{"t":"玉井亭观白莲二首 其一","f":"七言绝句","c":["红芙蕖杂白芙蕖，红底终稠白底疏。","速折当头一莲叶，莫令遮却雪肌肤。"]},{"t":"玉井亭观荷花","f":"五言古诗","c":["蕖仙初出波，照日稚犹怯。","密排碧罗盖，低护红玉颊。","馆之水精宫，环以琉璃堞。","珠明浮盘戏，酒漾流杯晔。","青笔尖欲试，绿笺皱还摺。","老龟大于钱，辛勤上团叶。","忽闻人履声，入水一何捷。"]},{"t":"瓜州遇风","f":"词","c":["金钲三声船欲发，天地苍茫忽开阖。","恶风吹倒多景楼，怒涛打碎金山塔。","涛头抛船入半空，船从空中落水中。","势如崩山同日二十九，声如推堕万石之簴千石钟。","岸人惊呼船欲没，舟人绝叫船复出。","平生所闻杨子江，无风已自波相撞。","莫教风动一波起，三日奔腾收不止。","君不见逆酋投鞭欲断流，藁街自送月氏头。"]},{"t":"甘露子一名地蚕","f":"词","c":["甘露子，甘露子，唤作地蚕亦良似。","不食柘叶不食桑，何须走入地底藏。","不能作茧不上簇，如何也蒙赐汤沐。","呼我果，谓之果，呼我蔌，谓之蔌。","唐林晁错莫逢它，高阳酒徒咀尔不摇牙。"]},{"t":"生酒歌","f":"词","c":["生酒清于雪，煮酒赤如血，煮酒不如生酒烈。","煮酒只带烟火气，生酒不离泉石味。","石根泉眼新汲将，曲米酿出春风香。","坐上猪红间熊白，瓮头鸭绿变鹅黄。","先生一醉万事已，那知身在尘埃里。"]},{"t":"白发叹","f":"词","c":["素丝久即黑，黑鬓久即丝。","丝黑有浣法，鬓丝无染期。","日月有底忙，昼夜驰向西。","江汉与之反，却向东方驰。","江汉西流日东落，鬓丝漆黑还如昨。","夜长何不秉烛游，自是人生不行乐。"]},{"t":"冬","f":"七言律诗","c":["祗愁穷腊雪作恶，不道雪天好行乐。","玻瓈盏底回青春，蒲萄锦外舞玉尘。","阳春一曲小垂手，劝君一杯千万寿。","今年斛谷才八钱，明年切莫羡今年。"]},{"t":"白纻歌舞四时词 春","f":"七言律诗","c":["人生春睡要足时，海波可乾山可移。","珠宫宴罢晓星出，不是天上无鸣鸡。","昨来坐朝到日落，君王何曾一日乐。","上林平乐半苍苔，桃花又去杨花来。"]},{"t":"秋","f":"七言律诗","c":["星芒欲灭天风急，月轮犹带银河湿。","青女椎冰作冷霜，吹到璇闺飞不入。","苧罗山下浣纱人，万妃无色抵一身。","娇馀贵极醉玉软，强为君王踏锦絪。"]},{"t":"夏","f":"七言律诗","c":["四月以后五月前，麦风槐雨黄梅天。","君王若道嫌五月，六月炎蒸又何说。","水精宫殿冰雪山，芙蕖衣裳菱芡盘。","老农背脊晒欲裂，君王犹道深宫热。"]},{"t":"立春日舟前细雨","f":"七言律诗","c":["急风阵阵吹白尘，著人怪底湿衣巾。","隔溪平林横素练，起从山脚萦山面。","近山如雾复如烟，远山失却只馀天。","今朝春日得春雨，润物无声非浪语。"]},{"t":"立春检校牡丹","f":"七言律诗","c":["牡丹又欲试春妆，恼得闲人也作忙。","新旧年头将替换，去留花眼费商量。","东风从我袖中出，小蕾已含天上香。","只道开时恐肠断，未开先自断人肠。"]},{"t":"记丘宗卿语绍兴府学前景","f":"七言律诗","c":["镜湖泮宫转街曲，才隔清溪便无俗。","竹桥斜度透竹门，墙根一竿半竿竹。","恰思是间宜看梅，忽然一枝横出来。","霜馀皴裂臂来大，只著寒花三两个。"]},{"t":"记张定叟煮笋经","f":"七言古诗","c":["江西猫笋未出尖，雪中土膏养新甜。","先生别得煮箦法，丁宁勿用醯与盐。","岩下清泉须旋汲，熬出霜根生蜜汁。","寒芽嚼作冰片声，馀沥仍和月光吸。","菘羔楮鸡浪得名，不如来参玉板僧。","醉里何须酒解酲，此羹一椀爽然醒。","大都煮菜皆如此，淡处当知有真味。","先生此法未要传，为公作经藏名山。"]},{"t":"辽车滩","f":"五言古诗","c":["东岸上不得，西岸上更难。","五船往复来，经纬滩两间。","一船初径进，当流为众先。","涛头打澎湃，退缩不敢干。","一船作后殿，忽焉突而前。","瞬息越湍险，回顾有矜颜。","老夫与寓目，亦为一粲然。"]},{"t":"丞相周公招王才臣中秋赏梅花寄以长句","f":"七言古诗","c":["素娥大作中秋节，一夜广寒桂花发。","天风吹堕绿野堂，夜半瑶阶丈深雪。","梅仙不知天尚秋，只惊香雪点搔头。","笑随玉妃照粉水，洗妆同入月中游。","晋公赏梅仍赏桂，独招子猷雪前醉。","明朝有客诉天公，不唤香山病居士。"]},{"t":"买菊","f":"七言古诗","c":["老夫山居花绕屋，南斋杏花北斋菊。","青春二月杏花开，抱瓶醉卧锦绣堆。","凉秋九月菊花发，自折寒枝插华发。","湘累落英曾几何，陶令东篱未是多。","吾家满山种秋色，黄金为地香为国。","就中更有一丈黄，霜葩月蕊耿出墙。","饮徒亡酒寻不得，寻得一身花露香。","如今小寓咸阳市，有口何曾问花事。","百钱担上买一株，聊伴诗人发幽意。"]},{"t":"仲冬诏追造朝供尚书郎职舟行阻风青泥三首 其三","f":"七言绝句","c":["江神风伯战方酣，北浪吹翻总向南。","未放人扶下江柁，却教眼看上江帆。"]},{"t":"仲冬诏追造朝供尚书郎职舟行阻风青泥三首 其一","f":"七言绝句","c":["东阙催人赴赤墀，北风栏我泊青泥。","会当老子有行日，未信北风无住时。"]},{"t":"休日清晓读书多稼亭","f":"五言古诗","c":["携家守荆溪，忽忽已一期。","官舍非不佳，怀抱长鲜怡。","若非僮仆病，定复儿女啼。","昔贫叹不饱，今愁岂缘饥。","晨起袖书册，急登亭上嬉。","露痕尚星月，风气无窗扉。","顿觉老病身，不禁絺绤衣。","昨暑何可度，朝凉乃尔奇。","白鸟远如蝶，玄蝉哦似诗。","松色雪我神，荷香冰我脾。","忧乐忽安在，形骸亦俱遗。","稚子不解事，朝餐呼我归。"]},{"t":"光口夜雨","f":"七言律诗","c":["峡江清空峡雨急，寒声夜半萧萧发。","玻瓈盆面跳万珠，一颗一声清入骨。","梦中搔首起来听，听来听去到天明。","一生听雨今头白，不识春江夜雨声。"]},{"t":"再入城宿张氏庄早起进退格","f":"五言律诗","c":["梦觉月如昼，误惊天欲明。","起吹松叶烬，自点臼花灯。","山轿已十里，谯门才四更。","脚根岂无火，须上也成冰。"]},{"t":"再并赋瑞香水仙兰三花","f":"七言古诗","c":["水仙头重力纤弱，碧柳腰支黄玉萼。","娉娉袅袅谁为扶，瑞香在旁扶著渠。","春兰初芽嫩仍短，娇如稚子无人管。","瑞香绿荫浓如云，风日不到况路尘。","生时各在一山许，畦丁作媒得相聚。","三花异种复异妆，三花同韵更同香。","诗人喜渠伴幽独，不道被渠教断肠。"]},{"t":"上巳日予与沈虞卿尤延之莫仲谦招陆务观沈子寿小集张氏北园赏海棠务观持酒酹花予走笔赋长句 其二 再和","f":"七言古诗","c":["太空无壁不可幄，颠风莫动花肌薄。","一春才有一日晴，帝里游人争出城。","青天如水绿烟灭，晴与海棠成两绝。","坐中宾主诗中仙，开口挥毫俱玉雪。","清泉白石欠此翁，若为插脚鹓鹭丛。","老眼作花花作晕，多惭猿鹤频相问。"]},{"t":"再和云龙歌留陆务观西湖小集且督战云","f":"词","c":["我愿身为云，东野化为龙。","龙会入渊云入岫，韩子却要长相逢。","作意相寻偏不值，不知今年是何岁。","剡藤玉板赠一番，廷圭乌丸洒未乾。","乃是故人陆浚仪，诗骨点化黄金丹。","谓宜天禄贮刘向，不然亦合云台上。","却令去索催租钱，枉却清风明月三千篇。","夜装明发走不彻，半篙刺碎严滩月。","老夫不愿万户侯，但愿与君酒船万斛同拍浮。","老夫不怯故将军，但怯与君笔阵千里相追奔。","少陵浣花旧时屋，太白青山何处坟。","二仙死可埋丘阜，二仙生可著韦布。","名挂广寒宫里树，非烟非云亦非雾，长使玉皇掉头诵渠句。","诗府谁得玉?开，诗坛谁授黄钺来。","留君不住君急回，不道西出阳关无此杯。","西山金盆尽渠颓，斯游明日方怀哉。"]},{"t":"再和","f":"七言古诗","c":["春风一夜吹滕六，旋落旋销不成簇。","只馀架上万天花，照影清池三两曲。","江东诗仙花下饮，小摘繁枝篸醉玉。","惊飞雪片万许点，乱落酒船百馀斛。","旧枝掠削自萦回，新枝奔迸无拘束。","诗仙诗满云梦胸，那更相逢此花触。","只愁毛颖倦驱使，一日屡向陶泓浴。","两章洗尽眼底尘，个字亦带花边馥。","凭谁说与柳柳州，休道一声山水渌。","愿参佳句法如何，夜雨何时对床宿。"]},{"t":"再赋石翁石婆","f":"七言律诗","c":["石翁谁怒犹睅目，石婆多愁鬓先秃。","荒山野水四无人，二老对立今几春。","珠襦玉匣化为土，金雁银凫亦飞去。","知是六朝何帝陵，摩娑碧藓俱无语。"]},{"t":"刘寺展绣亭上与尤延之久待京仲远不至再相待于灵芝寺","f":"五言古诗","c":["南山十日菊，秋酌有前诺。","东省三同舍，山行何用约。","也复相丁宁，彼此拨忙著。","清晨到刘寺，寸步辄倚薄。","望君久未来，细意拣岩壑。","上到展绣亭，聊复休倦脚。","回览西湖天，向我怀中落。","山幽人转孤，境胜情反恶。","昔贤愿独往，对影谁与乐。","或者欣群游，避喧那可却。","我随梁溪叟，觞次饶驩谑。","坐无山浦翁，谈间顿萧索。","斜阳更待渠，小向灵芝泊。"]},{"t":"华镗秀才著六经解以长句书其后","f":"词","c":["河图三画已剩却，尧典万言犹欠著。","向来潜圣天何言，六经非渠一手作。","杏花坛下拨不开，天公更遣麒麟催。","乾坤造化登青竹，洙泗光芒付绿苔。","堂上书生真苦相，蠹简嚼穿浑不放。","屋上架屋更屋上，后千万年作何样。","华元夜登子反床，华镗晨趋孔子堂。","当时浪说析骸骨，今日覃思彫肺肠。","华君将身博冻馁，毛颖可怜彼何罪。","君不见老农驱牛耕垄头，稻云割尽牛亦休。","毛颖为君秃尽发，问君何时放渠歇。","短檠青灯明复灭。"]},{"t":"合路马坊年年四月殿前诸军牧马于此十月复归都下","f":"七言律诗","c":["地迥湖宽春草酥，年年此地牧天驹。","玉花骢里龙归去，金粟堆前鸟自呼。","苑厩尚虚三万柱，柳林集得许多乌。","即今未有王良眼，山子飞黄岂是无。"]},{"t":"同主簿叔暮立","f":"五言律诗","c":["旋旋前山没，骎骎半臂寒。","鸥归势何懒，林近意先安。","待月迟云么，烦公小立看。","未知立玉笋，何似立江干。"]},{"t":"同刘季游登天柱冈四首 其三","f":"七言绝句","c":["穿青度碧白云中，山正奇时路忽穷。","引道老农辞我去，与君更上最高峰。"]},{"t":"同刘季游登天柱冈四首 其二","f":"七言律诗","c":["我行谁与报江枫，旋摆旌旗一路红。","朔吹崩腾危两耳，东山踊跃献诸峰。","松阴好处皆亭子，瑶草香边即坐狨。","渐陟渐高元不觉，忽然身在半天中。"]},{"t":"后苦寒歌","f":"七言古诗","c":["白鸥立雪胫透冷，鸬鹚避风飞不正。","一双野鸭欺晚寒，出没冰河底心性。","绝怜红船黄帽郎，绿蓑青箬牵牙樯。","生愁堕指脱两耳，芦花亦无何许藏。","遣骑前头买乾荻，速烘燄火与一炙。","三足老鸦寒不出，看云诉天天不泣。"]},{"t":"后圃散策","f":"五言古诗","c":["花径雨后凉，树声风外战。","杖屦顿轻松，儿女同行散。","少者前已失，老者后仍倦。","隔林吹笑语，相闻如对面。","明明去人近，眇眇弥步远。","松杉满地影，一瞬忽不见。","仰观紫日轮，偶度白云片。","佳处留再来，前山未须遍。"]},{"t":"回望惠山","f":"七言律诗","c":["惠山分明龙样活，玉脊琼腰百千折。","锡泉泉上吐一珠，簸弄太湖波底月。","苍石为角松为须，须里黄金古佛庐。","请君更向潘葑看，龙尾缴到珠南畔。"]},{"t":"回望摩舍那滩石峰","f":"七言绝句","c":["好山近看未为奇，远看全胜近看时。","回望七峰云外笋，两峰高绝五峰低。"]},{"t":"因种酴醾金沙作度雪台以下临之酴醾瘁而金沙独茂","f":"七言绝句","c":["独种酴醾冷却伊，金沙作伴暖相依。","酴醾枯了来年补，且看金沙也自奇。"]},{"t":"圩丁词十解 其四","f":"七言绝句","c":["南望双峰抹绿明，一峰起立一峰横。","不知圩里田多少，直到峰根不见塍。"]},{"t":"圩丁词十解 其十","f":"七言绝句","c":["圩上人牵水上航，从头点检万农桑。","即非使者秋行部，乃是圩翁晓按庄。"]},{"t":"圩丁词十解 其九","f":"七言绝句","c":["河水还高港水低，千枝万派曲穿畦。","斗门一闭君休笑，要看水从人指挥。"]},{"t":"圩丁词十解 其二","f":"七言绝句","c":["何代何人作此圩，石顽土腻铁难如。","年年二月桃花水，如律流归石臼湖。"]},{"t":"多稼亭前两株梅盛开","f":"词","c":["翟园看梅不满眼，载酒何曾倾一盏。","空有千株半未花，欲剪一枝无可拣。","归来却登多稼亭，玉妃骤降千娉婷。","素罗衣裳濯瑶水，珠宫楼阁开银屏。","国香万斛量不尽，雪岭诸峰互相映。","身骑白凤绕琼林，肝胆透寒骨毛冷。","看来只是两株梅，如何遣侬心眼开。","花头密密纷无数，萼萼枝枝砌成树。","夕阳斜照光烛天，微风欲度遮无路。","君不见侯门女儿真个痴，獭髓熬酥滴北枝。","又不见画工兔颖矜好手，冰水和铅描玉肌。","先生不能奄有二子者，报答风光只有诗。","今夕不醉仍无归。"]},{"t":"多稼亭前黄菊","f":"五言古诗","c":["危亭俯凉囿，落叶日夜深。","佳菊独何为，开花得我心。","韵孤自无伴，香净暗满襟。","根器受正色，非缘学黄金。","独违春光早，而俟秋寒侵。","岂不爱凋年，坐令淹寸阴。","奈此清苦操，愧入妍华林。","向来朱碧丛，亦复悴斯今。","清霜惨万象，幽芳耿森森。","持以寿君子，聊尔慰孤斟。"]},{"t":"安乐庙头","f":"七言律诗","c":["谁遣诗家酷爱山，爱山说得口澜翻。","千峰万岭争投奔，一陟三休却倦烦。","堆案满前何处著，枯肠饱后岂能餐。","残岚剩翠浑无用，包寄金陵同社看。"]},{"t":"岁之二日欲游翟园以寒风而止","f":"词","c":["岁前问讯翟园梅，不知作么不肯开。","岁后遣人访消息，春风一夜花都拆。","老夫闻此喜欲癫，小儿终夕不成眠。","南烹北果手自饤，漆櫑银瓶色相映。","千骑朝来填戟门，双旌已复指梅园。","东风无端动地起，横作清寒止游子。","老夫孤闷搔白头，小儿劝翁翁勿愁。","人言好事莫作意，雨妒风憎鬼神忌。","欲游不必言，阻游不必计。","从今只拣天色佳，走就梅花求一醉。"]},{"t":"岁暮归自城中一病垂死病起遣闷四首 其四","f":"五言古诗","c":["病起行不得，坐久情不舒。","倔强妻子前，欲扶羞索扶。","且呼斑竹君，寸步与我俱。","远行亦未决，聊复循庭除。","平地谁云觉，陟降即少徐。","平生四方志，八极视若无。","西飞折若木，东厉骑鲸鱼。","即今卧藜床，一起还九嘘。","力惫志犹在，床头寻湛卢。"]},{"t":"岁暮归自城中一病垂死病起遣闷四首 其三","f":"五言古诗","c":["食罢游东园，慨然伤我怀。","昨日卧病时，自谓不复来。","入门大风起，万松声顿哀。","病骨念不堪，欲行重徘徊。","裴徊南斋前，小倦坐苔阶。","斋前花不多，亦有两古梅。","似知我至此，顷刻忽尽开。","多情梅间竹，偃风特奇哉。","不知喜风舞，为复怯风回。","万象皆迎春，我独老病催。","明日能来否，且归拨炉灰。"]},{"t":"岁暮归自城中一病垂死病起遣闷四首 其二","f":"五言古诗","c":["出郭云尚明，及郊日忽暮。","不思日晷短，却信云色误。","骏奔六七里，逢店破亦住。","浇愁幸残尊，照睡聊短炬。","荒鸡唤野梦，晨起念速步。","升车乃复下，故疾动中腑。","昏眩懔欲绝，低徊不能去。","僮仆强我归，偶不陨中路。","老至犹倚强，疾在自不悟。","及慈一委顿，去死仅寸许。","人生信浮脆，可笑何足惧。","所惧弃官晚，行乐今已遽。"]},{"t":"岁暮归自城中一病垂死病起遣闷四首 其一","f":"五言古诗","c":["索居独寡欢，巾车入城闉。","亲旧久不见，一见交相欣。","挽衣招我饮，惟恐我出门。","不招我亦往，不留我亦存。","殷勤复如许，不住我岂真。","是时梅始花，吹香落金尊。","酒冽肴果富，咀啜俱芳珍。","丞相我知己，太守吾故人。","言非汰尘杂，尘杂不入言。","初谈圣贤髓，终谈天地根。","而况衔杯酒，不乐复何云。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其十","f":"七言绝句","c":["燕宁轩里集群仙，薄宦归来又两年。","梅影舞风风舞雪，劝人何苦怯金船。"]},{"t":"庆长叔招饮一杯未釂雪声璀然即席走笔赋十诗 其七","f":"七言绝句","c":["南烹北果聚君家，象箸冰盘物物佳。","只有蔗霜分不得，老夫自要嚼梅花。"]},{"t":"戏用禅观答曾无逸问山谷语","f":"七言绝句","c":["前说人间无漏仙，后说世上无眼禅。","衲子若全信佛语，生天定在灵运前。"]},{"t":"戏作司花谣呈詹进卿大监郎中","f":"七言古诗","c":["灵君觞客滕王家，鳌头仙人作司花。","仙人一笑春风起，开尽仙源万桃李。","李花冶白桃倡红，坐客桃霞李雪中。","仙人半酣舞造化，风吹雨打千花空。","嫣香烟色付一扫，病莟残英又嫌老。","落花已对春风羞，新花也对春风愁。","姚黄魏紫世无种，且据眼前桃李休。"]},{"t":"戏笔二首 其一","f":"七言绝句","c":["野菊荒苔各铸钱，金黄铜绿两争妍。","天公支与穷诗客，只买清愁不买田。"]},{"t":"戏题所见","f":"七言古诗","c":["田家不遣儿牧猪，老乌替作牧猪奴。","不羞卑冗颇得志，草根更与猪为戏。","一乌驱猪作觳觫，一乌骑猪作骐骥。","骑之不稳驱不前，坐看顽钝手无鞭。","人与马牛虽各样，一生同住乌衣巷。","叱声哑哑喙欲乾，猪竟不晓乌之言。","骑者不从驱者斗，争牛讼马傍无救。","猪亦自食仍自行，一任两乌双斗争。","不缘一童逐乌起，两乌顷刻斗至死。"]},{"t":"戏题常州草虫枕屏","f":"七言古诗","c":["黄蜂作歌紫蝶舞，蜻蜓蚱蜢如风雨。","先生昼眠纸帐温，无那此辈喧梦魂。","眼中了了华胥国，蜂催蝶唤到不得。","觉来忽见四摺屏，野花红白野草青。","勾引飞虫作许声，何缘先生睡不惊。"]},{"t":"早入东省残月初上","f":"五言古诗","c":["秉烛趋省署，两街犹闭门。","素娥独早作，碧沼浣黝盆。","宝扣剥见漆，半棱光剩银。","忽作青白眼，圜视向我嗔。","黑气贯瞳子，侧睨不敢真。","皎然一玉李，前行导征轮。","荧然数金粟，后扈从车尘。","朝鸡传三令，都骑争载奔。","星芒销欲无，月影澹失痕。","金鸦飞上天，吐出红龙鳞。"]},{"t":"早炊杨家塘","f":"五言律诗","c":["枯树藤为叶，遥峰石作鬟。","如何每行路，不劝自加餐。","浙界残零处，江东咫尺间。","炊烟恋茅店，飞出却飞还。"]},{"t":"早炊新林望见钟山","f":"七言绝句","c":["辞俸钟山一月前，如何知我北归轩。","不通姓字殷勤甚，忽到新林野店边。"]},{"t":"早起","f":"七言绝句","c":["黄菊花繁依旧臞，牡丹叶落恰如枯。","霜中蚱蜢冻欲死，紧抱寒梢不放渠。"]},{"t":"朱伯勤同子文弟幼楚侄来访书事","f":"七言律诗","c":["板桥再葺岸头横，茅屋新添树外明。","山势追回一溪水，波光飞到万花亭。","沉烟久冷炉犹馥，帘子闲垂脚自平。","坐看千林总黄落，只馀兰蕙向人青。"]},{"t":"次乞米韵","f":"七言律诗","c":["鲁公尚有粥为食，卢老今无僧作邻。","文字借令真可煮，吾曹从古不应贫。","诗肠幸自无烟火，句眼何愁著点尘。","俗子岂知贫亦好，未须容易向渠陈。"]},{"t":"次日醉归","f":"五言古诗","c":["日晚颇欲归，主人苦见留。","我非不能饮，老病怯觥筹。","人意不可违，欲去且复休。","我醉彼自止，醉亦何足愁。","归路意昏昏，落日在岭陬。","竹里有人家，欲憩聊一投。","有叟喜我至，呼我为君侯。","告以我非是，俛笑仍掉头。","机心久已尽，犹有不下鸥。","田父亦外我，我老谁与游。"]},{"t":"次东坡先生用六一先生雪诗律令龟字二十韵旧禁玉月梨梅练絮白舞鹅鹤等字新添访戴映雪高卧齧毡之类一切禁之","f":"词","c":["病身柴立手亦龟，不要人怜天得知。","一寒度夕抵度岁，恶风更将乾雨吹。","作祥只解诳饥腹，催老偏工欺短髭。","透屋旋生衾里铁，隔窗也送砚中澌。","揽衣起看端不恶，两耳已作冻菌危。","似明还暗静复响，索我黄绢挥乌丝。","误喜家贫屋骤富，不道天巧人能为。","忽思向来旅京国，瘦马断鞭包袖持。","红金何曾梦得见，茧生脚底粟生肌。","残杯冷炙自无分，不是不肯叩富儿。","独立西湖望东海，海神驾雪初来时。","眼花只怪失天地，风横并作翻帘帏。","飞来峰在水仙国，九里松无尘土姿。","只欠杖头聘欢伯，安得醉倒衣淋漓。","犹遭天子呼野客，催班声里趋丹墀。","如今四壁一破褐，雪花密密巾披披。","诗肩浑作远岭瘦，诗思浪与春江驰。","茅柴乞暖却得冷，聊复尔耳三两卮。","东坡逸足电雹去，天马肯放氂牛随。","君不见溧阳县里一老尉，一句曾饶韩退之。"]},{"t":"次东坡先生蜡梅韵","f":"七言古诗","c":["梅花已自不是花，冰魂谪堕玉皇家。","不餐烟火更餐蜡，化作黄姑瞒造物。","后山未觉坡先知，东坡勾引后山诗。","金花劝饮金荷叶，两公醉吟许孤绝。","人间姚魏漫如山，令人眼暗只欲眠。","此花寒香来又去，恼损诗人难觅句。","月兼花影恰三人，欠个文同作墨君。","吾诗无复古清越，万水千山一瓶钵。"]},{"t":"次主簿叔雪韵","f":"七言古诗","c":["向来一雪亦草草，天知诗人眼未饱。","相传南风为雪骨，此言未试吾不晓。","昨日忽惊冬作春，暖气吹人软欲倒。","惟馀桃李未著花，便恐蛰虫偷出窖。","南风未了却北风，一夜吹翻青玉昊。","今晨冷傍笔管生，似妒吟边事幽讨。","司寒作意欲再雪，冻雀求哀不容祷。","令人还忆柳柳州，解道千山绝飞鸟。","谁教爱雪却嫌寒，欢喜十分九烦恼。","诗人冻死不足怜，冻死犹应谈雪好。","寄声滕六何似休，净尽将云为侬扫。"]},{"t":"次秦少游梅韵","f":"七言古诗","c":["南枝外槁中不槁，未叶先花笑人倒。","已从寒里著诗愁，可复溪边被花恼。","非渠搀出百卉前，尔许清寒谁敢早。","有花无雪花只俗，有雪无梅雪何好。","冷蕊不风元自香，瘦柯写月真如扫。","但令一壑莳横斜，便挂竹皮为渠老。","秦七苏二冰玉词，绝唱寒盟几秋草。","梅边尚有句可搜，更撚衰髯仰清昊。"]},{"t":"次昌英主簿叔晴望韵","f":"五言律诗","c":["秋水冬全落，寒梅暖向荣。","烟林明又灭，风雁仄还平。","老岂愁能避，贫非懒不营。","犹须铲千嶂，剩与放双明。"]},{"t":"江山道中蚕麦大熟三首 其三","f":"七言绝句","c":["新晴户户有欢颜，晒茧摊丝立地乾。","却遣缲车声独怨，今年不及去年闲。"]},{"t":"江山道中蚕麦大熟三首 其二","f":"七言绝句","c":["黄云割露几肩归，紫玉炊香一饭肥。","却破麦田秧晚稻，未教水牯卧斜晖。"]},{"t":"江水","f":"五言律诗","c":["水色本正白，积深自成绿。","江妃将底药，软此千里玉。","诗人酒未醒，快吸一川渌。","无物咽清甘，和露嚼野菊。"]},{"t":"戏赠江干芦花","f":"五言律诗","c":["避世水云国，卜邻鸥鹭家。","风前挥玉麈，霜后幻杨花。","骨相缘诗瘦，秋声诉月华。","欲招卢处士，归共老生涯。"]},{"t":"池口移舟入江再泊十里头潘家湾阻风不止","f":"七言古诗","c":["北风五日吹江练，江底吹翻作江面。","大波一跳入天半，粉碎银山成雪片。","五日五夜无停时，长江倒流都上西。","计程一日二千里，今踰滟滪到峨眉。","更吹两日江必竭，却将海水来相接。","老夫蚤知当陆行，错料一帆超十程。","如今判却十程住，何策更与阳侯争。","水到峨眉无去处，下梢不到忘归路。","我到金陵水自东，只恐从此无南风。"]},{"t":"竹林","f":"七言绝句","c":["珍重人家爱竹林，织篱辛苦护寒青。","那知竹性元薄相，须要穿来篱外生。"]},{"t":"竹鱼","f":"词","c":["银鱼色如银，竹鱼色如竹。","渭川千亩秀可掬，都将染成一身绿。","鱼生竹溪中，家在竹根菱荇丛。","昼餐竹叶与竹米，夜饮竹露吹竹风。","前身王子猷，今身赤鲩公。","只知爱竹判却命，化作此君苍雪容。","渔翁夜傍竹溪宿，鱼惊钓丝冰底缩。","朝来钓得水苍玉，先生笑扪藜苋腹。"]},{"t":"纪罗杨二子游南岭石人峰","f":"七言古诗","c":["二子同游石人峰，深行翠筱黄茅中。","初嫌微径无人踪，行到半岭径亦穷。","来时犹自闻鸡犬，且行且语不觉远。","上头无梯下无岸，前头难攀后难返。","黄茅翠筱深复深，忽有笛声出暗林。","草根一把牛骨骼，血点溅地惊人心。","二子相看面无色，疾趋山后空王宅。","野僧闻此叫绝天，拊破禅床椎倒壁。","荒山岂有吹笛声，乃是卧虎鼻息鸣。","二子归来向侬说，犹道兹游最清绝。","兹游清绝岂不佳，二子性命如泥沙。"]},{"t":"自金陵得郡西归晓发梅根市舟中望九华山进退格","f":"五言律诗","c":["山外云浓白，峰头日浅红。","横拖一疋绢，直扫九芙蓉。","奔走来船里，提携入袖中。","寄言杜陵老，不用剪吴松。"]},{"t":"自嘲白须三首 其二","f":"五言绝句","c":["客传涅须法，老子付一笑。","借令白再玄，能令年再少。"]},{"t":"至洪泽","f":"七言古诗","c":["今宵合过山阳驿，泊船问来是洪泽。","都梁到此只一程，却费一宵兼两日。","政缘夜来到渎头，打头风起浪不休。","舟人相贺已入港，不怕淮河更风浪。","老夫摇手且低声，惊心犹恐淮神听。","急呼津吏催开闸，津吏叉手不敢答。","早潮已落水入淮，晚潮未来闸不开。","细问晚潮何时来，更待玉虫缀金钗。"]},{"t":"至鹧鸪洞","f":"五言古诗","c":["岸冻树逾瘦，日高林始明。","瑶草密如积，玉泉中暗鸣。","初至心为动，欲归脚还停。","江湖千万峰，穿侬两鞋青。","如何鹧鸪岭，咫尺来未曾。"]},{"t":"舟人吹笛","f":"七言古诗","c":["长江无风水平绿，也无靴文也无縠。","东西一望光浮空，瑩然千顷无瑕玉。","船上儿郎不耐闲，醉拈横笛吹云烟。","一声清长响彻天，山猿啼月涧落泉。","更打羊皮小腰鼓，头如青峰手如雨。","中流忽有一大鱼，跳破琉璃丈来许。"]},{"t":"舟中买双鳜鱼","f":"七言古诗","c":["金陵城中无纤鳞，一鱼往往重六钧。","脊梁专车尾梢云，肉如大武千秋筋。","小港阻风泊乌舫，舫前渔艇晨收网。","一双白锦跳银刀，玉质黑章大如掌。","洞庭枨子青欲黄，香肤作线醯作浆。","供侬朝吃复晚吃，秃尾槎头俱避席。","可怜秋浦好秋山，侬眼未饱即北还。","江神挈月作团扇，一夜挥风卷波面。","留侬看山仍看江，更荐鲜鱼庖玉霜。","江神好意那可忘，江神恶剧那可当。"]},{"t":"舟中排闷","f":"七言古诗","c":["江流一直还一曲，淮山一起还一伏。","江流不肯放人行，淮山只管留人宿。","老夫一出缘秋凉，半涂秋热难禁当。","却借楼船顺流下，逆风五日殊未央。","老夫平生行此世，不自为政听天地。","只今未肯放归程，安知天意非奇事。","平生爱诵谪仙诗，百诵不熟良独痴。","舟中一日诵一首，诵得遍时应得归。"]},{"t":"舟中望罗浮山","f":"七言古诗","c":["罗浮元不是罗浮，自是道家古蓬丘。","弱水只知断舟楫，葛仙夜偷来惠州。","罗浮山高七万丈，下视日月地上流。","黄金为桥接银汉，翠琳作阙横琼楼。","不知何人汗脚迹，触忤清虚涴寒碧。","天遣山鬼绝凡客，化金为铁琼为石。","至今石楼人莫登，铁桥不见空有名。","玉匙金籥牢锁扃，但见山高水泠泠。","我欲骑麟翳鸾凤，月为环佩星为从。","前驱子晋后安期，飞上峰头斸丹汞。"]},{"t":"舟中雪作和沈虞卿寄雪诗韵","f":"七言律诗","c":["霜风吹船著淮阴，淮山高高淮水深。","津亭饮散浪如屋，篷窗晓起雪满林。","两袖拂空捎舞片，数点落几撩孤吟。","卷舒东阳琢冰句，不羡销金歌浅斟。"]},{"t":"舟中新暑止酒","f":"五言古诗","c":["新暑酒不宜，作热妨夜睡。","不如看人饮，亦自有醉意。","彼饮吾为咽，所美过于味。","同舟笑吾痴，吾不羡渠醉。","安知醉与醒，谁似谁不似。"]},{"t":"舟至湖心望豫章西山云起风雨骤至","f":"七言律诗","c":["横洲送我忽俱还，四顾无边已惨颜。","雪浪撞天吞几子，炮云将雨起西山。","一声霹雳从空下，万丈金蛇掣斗间。","舟子惊呼总无色，平生忠信且今番。"]},{"t":"舟过大水旁罗滩渴甚小饮","f":"五言律诗","c":["熟水无多吃，烹茶未要来。","从教十分渴，连扫两三杯。","岸树背船走，江波闪日开。","灵山定能饮，分酹碧莲醅。"]},{"t":"舟过柴步寺","f":"五言古诗","c":["野寺隔疏樾，远舟见深殿。","独径通绝崖，长萦度微线。","曩游携童弱，攀岸已震眩。","前瞻足未到，下窥意先转。","朝来经云根，尘思起清羡。","野夫三二辈，走过疾于箭。","俛仰二十年，今老怀昔健。"]},{"t":"芍药宅","f":"词","c":["何以筑花宅，笔直松树子。","何以盖花宅，雪白清江纸。","纸将碧油透，松作画栋峙。","铺纸便成瓦，瓦色水精似。","金鸦暖未焰，银竹响无水。","汗容渍不泣，晴态娇非醉。","尽收香世界，关在闲天地。","风日几曾来，蜂蝶独得至。","劝春入宅莫归休，劝花住宅且小留。","昨日花开开一半，今日花飞飞数片。","留花不住春竟归，不如折插瓶中看。"]},{"t":"芗林五十咏 其十五 三老亭","f":"五言绝句","c":["双树有古色，一几非今样。","祗言此老亡，月夜闻屐响。"]},{"t":"芗林五十咏 其三十七 玉井","f":"五言绝句","c":["谁言玉井春，不作双井味。","会有眠云客，领略两相似。"]},{"t":"芗林五十咏 其二十九 企疏堂","f":"五言绝句","c":["堂上清如水，芗林对两疏。","只今诗社里，画作企疏图。"]},{"t":"芗林五十咏 其四十五 百花洲","f":"五言绝句","c":["茂苑犹香名，南阳已荒草。","更兼芗林中，三洲是三岛。"]},{"t":"芗林五十咏 其三十 梅坡","f":"五言绝句","c":["自昔花如雪，而今叶入云。","先生已仙去，谁与共天醇。"]},{"t":"芗林五十咏 其三十四 菊坡","f":"五言绝句","c":["西风破幽馥，东篱散清好。","渊明不可作，邂逅芗林老。"]},{"t":"芗林五十咏 其十三 墨坳","f":"五言绝句","c":["坳中一池墨，腕中百斛力。","洒作五十诗，千年照泉石。"]},{"t":"行役有叹 其二","f":"五言律诗","c":["百年几暄凉，再岁三征行。","却羡路旁叟，白首不到城。","人生如风花，去来能与争。","且随风吹起，会当风自停。"]},{"t":"行役有叹 其一","f":"五言律诗","c":["去年丐西归，谓可休馀生。","今年复东下，驾言入神京。","卧治方小安，趋召岂不荣。","何如还家乐，醉吟听溪声。"]},{"t":"行圃","f":"五言古诗","c":["饭罢来窥园，晴路忽流水。","石子净无尘，一一湿如洗。","夜来元无雨，霜消痕尚尔。","稚子有素约，杖屦从我戏。","老夫偶独先，稚子久不至。","初心一何乐，中路惨不喜。","怅望行复歇，回顾亦三四。","行逢木蕖开，攀翻嗅霜蕊。"]},{"t":"行路难五首 其五","f":"词","c":["造化小儿不耐闲，阿兄阿姊一似颠。","两手双弄赤白丸，来来去去绕青天。","赤丸才向西山没，白丸又向东山出。","只销三万六千回，雪色少年成皱铁，铁色头须却成雪。","双丸绕从地下复上天，少年一入地下更不还。","日日喜欢能几许，况有烦恼无喜欢。","莫言酒不到刘伶坟上土，刘伶在时一醉曾三年。","明珠一百斛，更添百斛也只心不足。","侯印十九枚，更添一倍也只眉不开。","先生笑渠不行乐，莫教人笑先生错。"]},{"t":"行路难五首 其四","f":"词","c":["长门陈阿娇，却要一生金屋贮娇饶。","长信班婕妤，却要一生纨扇从玉车。","妾心祗作专房地，别人亦有承恩意。","妾心不肯著别人，君心还肯如妾心。","春风秋月浑不管，花落花开空自怨。","千秋万岁一笑休，月明空照古今愁。"]},{"t":"行路难五首 其三","f":"词","c":["黄金筑台赐白璧，车前八驺门列戟。","彻侯万户秩万石，珠户玉房贮倾国。","传呼一声万人开，将军相国天上来。","不知道旁雍门子，已叹麋鹿登高台。","雍门解遣孟尝泣，孟尝不泣渠何急。","只知富贵如云浮，不知贫贱饥死寒死愁不愁。"]},{"t":"行路难五首 其二","f":"词","c":["老夫少时不信老，长笑老人恃年少。","如今老矣不笑人，却被少年开口笑。","少年何苦笑老人，老人旧日颜如春。","兴来百盏山隤玉，醉后千篇笔有神。","自古圣贤皆白骨，谁道今人不见古时月。","孔子盗蹠俱尘埃，杜陵老人今亦安在哉。"]},{"t":"行路难五首 其一","f":"词","c":["君不见河阳花，今如泥土昔如霞。","君不见武昌柳，春作金丝秋作帚。","人生马耳射东风，柳色桃花却长久。","秦时东陵千户侯，华虫被体腰苍璆。","汉初沛邑刀笔吏，折腰如磬头抢地。","萧相厥初谒邵平，中廷百拜百不应。","邵平后来谒萧相，故侯一拜一惆怅。","万事反覆何所无，二子岂是大丈夫。","穷通流坎皆偶尔，抟扶未必贤枪榆。","华胥别是一天地，醉乡何曾有生死。","侬欲与君归去来，千愁万恨付一杯。"]},{"t":"西园早梅二首 其二","f":"七言绝句","c":["小朵生来便瘦斜，蕊宫桂殿即渠家。","只言瘴雨无南雪，为底横枝雪作花。"]},{"t":"西斋旧无竹予归自毗陵斋前忽有竹满庭盖墙外之竹迸逸而生此也喜而赋之","f":"七言古诗","c":["平生取友孤竹君，馆之山崦与卜邻。","风衿月佩霜雪身，只谈风节不论文。","我开西斋对清润，每嫌隔窗不相近。","别来桃李一再花，我长在外君在家。","归来西斋挂窗处，此君忽在窗前住。","绕墙检校无来路，此君来路从何许。","向来先生初出去，遣猿看墙鹤看户。","如何鹤睡眼未开，此君一夜过墙来。","明朝稚子满庭砌，豹文玉骨龙苗裔。","春风吹堕锦衣裳，仰看青士冠剑长。","先生岂惜窗前地，与君同醒复同醉。"]},{"t":"观小儿戏打春牛","f":"七言古诗","c":["小儿著鞭鞭土牛，学翁打春先打头。","黄牛黄蹄白双角，牧童绿蓑笠青箬。","今年土脉应雨膏，去年不似今年乐。","儿闻年登喜不饥，牛闻年登愁不肥。","麦穗即看云作帚，稻米亦复珠盈斗。","大田耕尽却耕山，黄牛从此何时闲。"]},{"t":"观书","f":"五言古诗","c":["书册不可逢，逢得放不得。","看得眼昏花，放了还太息。","掩卷味方深，岂问忘与忆。","是身何曾动，忽然超八极。","祇言半窗间，不是华胥国。"]},{"t":"观书","f":"五言古诗","c":["客从远方至，遗我书一编。","览旧眼全痛，诵新神顿还。","初披愁欲尽，久玩翳不妍。","情知无佳处，闵免复竟篇。","庶几槁滓中，或沥腴一涓。","终然寂无获，所获倦且昏。","倦甚得佳睡，犹胜不得眠。"]},{"t":"观水叹二首 其二","f":"五言古诗","c":["乱石厄江水，要使水无路。","不知石愈密，激得水弥怒。","回锋打别港，勇往遮不住。","我舟历诸滩，阅尽水态度。","一闻一喜观，屡过屡惊顾。","不是见不多，观览不足故。","舟人笑我痴，痴黠未易语。"]},{"t":"观水叹二首 其一","f":"五言古诗","c":["我方卧舟中，仰读渊明诗。","忽闻滩声急，起视惟恐迟。","八月溅飞雪，清览良独奇。","好风从天来，翛然吹我衣。","凉生固足乐，气变亦可悲。","眷然慨此水，念我年少时。","迄今四十年，往来九东西。","此日顺流下，何日溯流归。","出处未可必，一笑姑置之。"]},{"t":"观张功父南湖海棠杖藜走笔三首 其一","f":"七言绝句","c":["看尽都城种海棠，只将一径引教长。","约斋妙出春风手，人在中央花四傍。"]},{"t":"观社","f":"七言律诗","c":["作社朝祠有足观，山农祈福更迎年。","忽然箫鼓来何处，走杀儿童最可怜。","虎面豹头时自顾，野讴市舞各争妍。","王侯将相饶尊贵，不博渠侬一饷癫。"]},{"t":"观鱼","f":"五言古诗","c":["老夫不奈热，跣足坐瓦鼓。","临池观游鱼，定眼再三数。","鱼儿殊畏人，欲度不敢度。","一鱼试行前，似报无他故。","众鱼初欲随，幡然竟回去。","时时传一杯，忽忽日将暮。"]},{"t":"观稼","f":"五言律诗","c":["井字行都整，花香远已甜。","穗肥黄俯首，芒劲紫掀髯。","风搅平云阵，声松缺月镰。","不愁禾把减，高廪却愁添。"]},{"t":"负丞零陵更尽而代者未至家君携老幼先归追送出城正值泥雨万感骤集","f":"七言古诗","c":["吾父先归吾未可，吾母已行犹顾我。","儿女喜归未解悲，我愁安得似儿痴。","墙头人看不须羡，居者那知行者叹。","昨日幸晴今又雨，天公管得行人苦。","吾母病肺生怯寒，晚风鸣屋正无端。","人家养子要作官，吾亲此行谁使然。"]},{"t":"过乌沙望大塘石峰","f":"词","c":["城中长恨不见山，出城见山如等闲。","曹溪过了过岑岭，不惟山粗石仍犷。","山如可师癞满顶，石如陈三瘿联颈。","一路令人眼不开，眼开令人闷不醒。","乌沙未到一溪横，水清见底心已清。","大塘六峰争出迎，水精笔架琉璃屏。","两峰玉笋初出土，三峰冰盘饤角黍。","一峰新琢金博山，雾作沈烟云作缕。","忽然前冈平截断，万丈青尖馀寸许。","山神解怜客子愁，平地跳出苍琳璆。","更借天公修月斧，神工一夜忙雕锼。","近看定何者，远看真可画。","山神自贺应自诧，古来此地无车马。"]},{"t":"过主岭","f":"七言律诗","c":["昨日山行尚有村，今朝岭塞更无门。","仰攀苔磴上绝顶，却倒篮舆下峻峦。","身觉去天才寸许，岸临无地不堪看。","前头尚有芙蓉在，此岭难登未是难。"]},{"t":"过白土岭望见芙蓉峰七八峰最东一峰特奇里人名为芙蓉尖云","f":"七言古诗","c":["看山须是高处看，低处看来元不见。","君看矮子仰高人，只识长身那识面。","今晨雨止升火轮，一光销尽千山云。","千山数日眼中失，今晨头角都争出。","初登峻岭也心惊，上到绝顶忽眼明。","天外数枝青玉笔，飞入锦囊寒突兀。","问来还是芙蓉尖，阔开两窗高捲帘。"]},{"t":"过白沙渡得长句呈澹庵先生","f":"七言古诗","c":["收红拾紫消几许，也费一春强半雨。","不辞长江万波阻，来听先生夜深语。","尚忆向来侍樽俎，微雪斜飞小梅吐。","先生半酣染霜兔，金章玉句空万古。","今年寒食还相聚，明年寒食知何处。","只道先生押班去，不道门生折腰苦。"]},{"t":"过石硊渡","f":"七言古诗","c":["峨桥小渡十里长，石硊小渡五里强。","斜风细雨寒芦里，下有深潭黑无底。","渡船劣似纸半张，五里却成一千里。","中流风作浪如山，前进不得后退难。","隔溪市井只咫尺，安得飞堕于其间。","大江风涛堪著力，小渡风涛更无格。","咫尺性命轻于毛，只恐一毛犹不直。"]},{"t":"过江州岸回望庐山","f":"七言古诗","c":["庐山山南刷铜绿，黄金锯解纯苍玉。","庐山山北泼蓝青，碧罗幛裹翡翠屏。","昨日山南身历遍，今朝山北舟中看。","山南是我所部民，山北是我乡中人。","部民乡人何厚薄，有人问我山美恶。","诧南赊得乡里嫌，评北又道月旦严。","两平只在一言内，山如西子破瓜岁，山南是面北是背。"]},{"t":"过池阳舟中望九华山","f":"五言律诗","c":["役役催行迈，匆匆过此春。","杯翻五湖月，笔扫九华云。","不是风烟好，何缘句子新。","兹游四千里，今日过三分。"]},{"t":"过西山","f":"七言律诗","c":["一年两踏西山路，西山笑人应解语。","胸中百斛朱墨尘，雨捲珠帘无半句。","殷勤买酒谢西山，惭愧山光开我颜。","鬓丝浑为催科白，尘埃满胸独遑惜。"]},{"t":"过严州章村放歌","f":"七言古诗","c":["石崖削得瘦到筋，半点也无尘土痕。","正如狻猊走得渴，下赴江水一口吞。","严滩过却乌龙觜，两岸秋山夹秋水。","舟中小酌亦不遑，眼底生愁失苍翠。","尖峰已自刺太虚，峰头更立玉浮屠。","好山千只复万只，家里门前一只无。"]},{"t":"过秀溪长句","f":"七言律诗","c":["去年来此上巳日，今年重来未寒食。","临溪照影老自羞，惭愧春光尚相识。","秀溪何许好春容，最是溪深树密中。","海棠开尽却成白，桃花欲落翻深红。"]},{"t":"过龟峰","f":"七言律诗","c":["大龟昂首瞻南天，仙人赤脚骑龟肩。","小龟一双走随母，指爪穿尽追不前。","仙人不知卜何事，踏脱绿毛纷满地。","老夫也要钻一钻，何日故园遂归计。"]},{"t":"过单竹洋径","f":"五言古诗","c":["两山何许来，此焉忽相寻。","摩肩不少让，争道各载骎。","乔木与脩竹，相招为茂林。","无风生翠寒，未夕起素阴。","天垂木末近，日到谷底深。","空山时自响，已动客子心。","行至幽绝处，更闻啼怪禽。"]},{"t":"过奔牛闸","f":"七言古诗","c":["春雨未多河未涨，闸官惜水如金样。","聚船久住下河湾，等待船齐不教放。","忽然三板两板开，惊雷一声飞雪堆。","众船遏水水不去，船底怒涛跳出来。","下河半篙水欲满，上河两平势差缓。","一行二十四楼船，相随过闸如鱼贯。"]},{"t":"过宝应县新开湖十首 其九","f":"七言绝句","c":["两只钓船相对行，钓车自转不须萦。","车停不转船停处，特地萦车手不停。"]},{"t":"过宝应县新开湖十首 其七","f":"七言绝句","c":["半浓黛汁点遥林，微淡铅膏抹暮云。","似白如青都不是，淮南弄色五湖春。"]},{"t":"过宝应县新开湖十首 其三","f":"七言绝句","c":["雨丝拂水不曾沉，一一如珠一一明。","乱走不停跳不住，忽然跳入水精瓶。"]},{"t":"过招贤渡","f":"七言律诗","c":["归船旧掠招贤渡，恶滩横将船阁住。","风吹日炙衣满沙，妪牵儿啼投店家。","一生憎杀招贤柳，一生爱杀招贤酒。","柳曾为我碍归舟，酒曾为我消诗愁。"]},{"t":"过松源晨炊漆公店六首 其一","f":"七言绝句","c":["侧塞千山缝也无，上天下井万崎岖。","昨朝曾过芙蓉渡，寻到溪源一线初。"]},{"t":"过松源晨炊漆公店六首 其六","f":"七言绝句","c":["政是行人肠断时，子规得得向人啼。","若能泪得居人脸，始信春愁总为伊。"]},{"t":"过松源晨炊漆公店六首 其三","f":"七言绝句","c":["后山勒水向东驰，却被前山勒向西。","道是水柔无性气，急声声怒慢声悲。"]},{"t":"过若山坊进退格","f":"五言律诗","c":["绿涨空中幄，黄铺地上云。","风条钩过轿，雨穟没行人。","夹路桑千树，平田稻十分。","泥行殊不恶，物色逐村新。"]},{"t":"过郑步","f":"七言绝句","c":["渐有人家松桂丛，韶州山水胜南雄。","未须青惜峰峦过，过了诸峰得好峰。"]},{"t":"过金台望横山塔","f":"五言律诗","c":["昨夜愁勤雨，今朝喜懒风。","金台斜岸北，玉塔正船东。","滩改呈新碛，山回隐暗峰。","兰溪水亭子，作意定留侬。"]},{"t":"过金沙洋望小海","f":"七言古诗","c":["海雾初开明海日，近树远山青历历。","忽然咫尺黑如漆，白昼如何成暝色。","不知一风何许来，雾开还合合还开。","晦明百变一弹指，特地遣人惊复喜。","海神无处逞神通，放出一斑夸客子。","须臾满眼贾胡船，万顷一碧波黏天。","恰似钱塘江上望，只无两点海门山。","我行但作游山看，减却客愁九分半。"]},{"t":"过胥口镇","f":"七言绝句","c":["桄榔叶垂翠羽鲜，木绵花暖紫霞翻。","疾雷急雨忽开霁，淡白云拂浓清山。"]},{"t":"过润陂桥三首 其三","f":"七言绝句","c":["历览溪中有底鸣，萧然芦叶蓼花汀。","元来轿顶呜呜响，将谓风声是雁声。"]},{"t":"过润陂桥三首 其一","f":"七言绝句","c":["润陂初上板桥时，欲入江东尚未知。","忽见桥心界牌子，脚根一半出江西。"]},{"t":"过铅山江口","f":"七言绝句","c":["下却诸滩水渐平，舟行已远上饶城。","酒家便有江乡景，绿柳梢头挂玉瓶。"]},{"t":"过淮阴县题韩信庙前用唐律后用进退格 其二","f":"七言律诗","c":["鸿沟祗道万夫雄，云梦何销武士功。","九死不分天下鼎，一生还负室前钟。","古来犬毙愁无盖，此后禽空悔作弓。","兵火荒馀非旧庙，三间破屋两株松。"]},{"t":"过笪桥","f":"七言绝句","c":["轻风欲动没人知，早被垂杨报酒旗。","行到笪桥中半处，钟山飞入轿窗来。"]},{"t":"过湖口县上下石钟山即东坡所记者是夕宿其下","f":"词","c":["上钟山，下钟山，两钟尔大何处悬。","沧波作杵天作簴，悬在江湖都会间。","蜀江西来一万里，章江南来会于此。","更著鄱阳与彭蠡，混同四水作一水。","万岁千秋撞不止，两钟可是难当抵。","上钟打得到骨髓，下钟打穿胸腹底。","世无坡老辨古器，谁知出自周与魏。","老夫不能认款识，愿闻大声开病耳，今夜月明正无滓。"]},{"t":"过谢家湾","f":"七言律诗","c":["行尽牛蹊兔径中，忽逢平野四连空。","意随白鹭一双去，眼过青山千万重。","近岭已看看远岭，连峰不爱爱孤峰。","一丘一壑知何意，疏尽官人著牧童。"]},{"t":"过横山塔下","f":"七言绝句","c":["六年三度过兰溪，总是残春首夏时。","最感横山山上塔，迎人东去送人西。"]},{"t":"过霅川大溪","f":"七言古诗","c":["菰蒲际天青无边，只堪莲荡不堪田。","中有一溪元不远，摺作三百六十湾。","政如绿锦地衣上，玉龙盘屈于其间。","前船未转后船隔，前湾望得到不得。","及至前湾到得时，只与后湾才咫尺。","朝来已度数百萦，问知德清犹半程。","老夫乍喜棹夫闷，管有到时君莫问。"]},{"t":"过磨盘得风挂帆","f":"七言律诗","c":["两岸黄旗小队兵，新晴归路马蹄轻。","全番长笛横腰鼓，一曲春风出塞声。","鹊噪鸦啼俱喜色，船轻风顺更兼程。","却思两日淮河浪，心悸魂惊尚未平。"]},{"t":"过甓社诸湖进退格东西长七十里南北阔五十里","f":"七言律诗","c":["为爱淮中掌似平，忽逢巨浸却心惊。","怪来万顷不生浪，冻合五湖都是冰。","碧玉湖宽容我到，白银地滑没人行。","兹游只道清无价，清杀诗翁老不胜。"]},{"t":"严陵决曹易允升自官下遣骑归写予老丑因题其额","f":"五言绝句","c":["玉泉半潭冰，钓台万壑雪。","汝往访客星，剩挟一磨衲。"]},{"t":"初十日早炊蕉步得家书并家酿二首 其一","f":"七言绝句","c":["潢池东定得西还，病后涂中竟鲜欢。","为许朝来有新喜，庭闱一骑报平安。"]},{"t":"初三日游翟园","f":"七言古诗","c":["羽衣晓谒玄元殿，霜封万屋明飞霰。","扶桑跳出丹砂丸，光射半天萦紫电。","归涂微暖春衫知，小风不动旗脚垂。","老夫掉头心独喜，翟园梅花招我嬉。","呼儿媻姗且勃窣，才出谯门寒刮骨。","东风十里卷黄尘，眼花头眩吹倒人。","劣到翟园风便止，猿鹤前导花迎门。","玉林亭子绝幽绝，江梅千树吹香雪。","茂松轩里清更清，松风一鼎煎茶声。","春光催柳未肯青，池水借日无留冰。","殷勤犯寒我不枉，分付胜游天岂轻。","主人看客眼不白，鹦鹉传呼饷肴核。","桃花碎片点鲈鲊，紫茸堆盘擘鹑腊。","霜馀橘颗金弹香，雪底笋芽玉版色。","老夫欲醉金叵罗，稚子先唱骊驹歌。","不羞冷面对风物，奈尔玉笋金柑何。"]},{"t":"初五日晓寒浙人谓之蚕寒盖麦秋寒也","f":"七言绝句","c":["岁岁春寒欲去时，麦牵蚕惹不教归。","早知今晓犹差冷，未肯疏它旧裌衣。"]},{"t":"初夏即事","f":"七言律诗","c":["今日风光定自佳，不寒不热恰清和。","百年人世行乐耳，一岁春归奈老何。","芍药晚花终是小，戎葵新莟许来多。","俸钱自笑浑无用，祗合文江买钓蓑。"]},{"t":"初秋戏作山居杂兴俳体十二解 其十","f":"七言绝句","c":["湖蜜青房蛹剥琼，沼犀紫抵脑藏冰。","先生病暑无多酌，堆饤金柈作么生。"]},{"t":"初秋戏作山居杂兴俳体十二解 其十二","f":"七言绝句","c":["月色如霜不粟肌，月光如水不沾衣。","一年没赛中元节，政是初凉未冷时。"]},{"t":"初秋戏作山居杂兴俳体十二解 其五","f":"七言绝句","c":["昨夜天垂破玉盆，今宵辛苦补盆唇。","看它补到十六七，满得十分亏二分。"]},{"t":"初秋玩月","f":"七言古诗","c":["月华只是寻常月，如何入秋顿清绝。","泼在中庭满地冰，飞上寒窗一堂雪。","今宵无雨风亦无，凉气却如风雨馀。","九州四海几人看，作意独来寻老夫。","仙人餐霞咽朝日，老夫不愿受此术。","不如掇月入杯中，酒浪月波供一吸。","老夫病肺怯清秋，对酒不饮月莫愁。","老夫未眠月未落，相伴且到三更头。"]},{"t":"初食太原生蒲萄时十二月二日","f":"词","c":["淮南蒲萄八月酸，只可生吃不可乾。","淮北蒲萄十月熟，纵可作羓也无肉。","老夫腊里来都梁，饤坐那得马乳香。","分明犹带龙须在，径寸玄珠肥十倍。","太原青霜熬绛饧，甘露冻作紫水精。","隆冬压架无人摘，雪打冰封不曾拆。","风吹日炙不曾腊，玉盘一朵直万钱。","与渠倾盖真忘年，君不见道逢曲车口流涎。"]},{"t":"初夏玉井亭晚立","f":"七言律诗","c":["冶蕊倡花一雨空，鲜晴新涨未亏侬。","竹兼树影眠天底，人凭栏干立镜中。","看尽水衣投北岸，方知今日是南风。","黄鹂对语无寻处，忽见双飞入别丛。"]},{"t":"初夏即事十二解 其八","f":"七言绝句","c":["东渚西陂万马奔，浪花吞尽旧波痕。","山童莫扫中庭水，要写钱钱雨点纹。"]},{"t":"初夏即事十二解 其五","f":"七言绝句","c":["槛中红药趁春归，瓶里苛留三两枝。","一片落来能恋我，叶梢阁住不教飞。"]},{"t":"初夏即事十二解 其七","f":"七言绝句","c":["玉磬金钟天半鸣，梦中惊我起来听。","万松花上三更雨，政事堂中有此声。"]},{"t":"初夏即事十二解 其十","f":"七言绝句","c":["柳外花梢啼乱莺，行人过尽不曾听。","得人听处君知么，天欲明时第一声。"]},{"t":"初晓明朗忽然雾起已而日出光景奇怪","f":"五言古诗","c":["明发望远山，一一粲可数。","幽人萌望心，便被山灵妒。","逡巡出神通，变化足惊怖。","初将兜罗绵，擘作霏微絮。","周遭裹世界，仰视失天宇。","高悬赤瑛盘，不计丈尺许。","下照空濛间，红光贯轻素。","中有人物影，纷纭竞来去。","亦各有所持，莫辨是何具。","犹嫌未奇怪，别出奇怪处。","珠立一路幢，瑶森四山树。","横空金桥梁，拔地玉窣堵。","骇目方谛观，捲地急收去。","恍疑刮眼膜，依旧认山路。","那知幻与真，不记梦兼寤。","神游峨眉山，诳俗笑佛祖。","笑诳却被诳，佛祖还笑汝。"]},{"t":"吴春卿郎中饷腊猪肉戏作古句","f":"七言古诗","c":["老夫畏热饭不能，先生馈肉香倾城。","霜刀削下黄水精，月斧斫出红松明。","君家猪红腊前作，是时雪没吴山脚。","公子彭生初解缚，糟丘挽上凌烟阁。","却将一脔配两螯，世间真有杨州鹤。"]},{"t":"张功父送牡丹续送酴醾且示酴醾长篇和以谢之","f":"词","c":["溪桃红霞作红雨，海棠飘尽春无处。","约斋锦幄一夜空，行李移归雪宫住。","只道青蛟弱无力，飞上朱檐还有翼。","贪看翡翠积成堆，忽吐琼瑶真作剧。","素影与月相将迎，绿云和露相扶擎。","南枝暗香久寂莫，此花与梅同一清。","老夫最爱嚼香雪，不但解酲仍涤热。","牡丹未要煎牛酥，酴醾相领入冰壶。","约斋知我春愁重，并遣二友来相娱。","惜无老盆一快举，淡日微风花自舞。","约斋诗瘦浪作痴，君不见酒不到刘伶坟上土。"]},{"t":"张功父索余近诗余以南海朝天二集示之蒙题七字","f":"七言律诗","c":["作者于今星样稀，凄其望古驷难追。","空桑孤竹陶元亮，玉佩琼琚杜拾遗。","自笑吟秋如懒妇，可能击鼓和冯夷。","报章不作南金直，惭愧君家丙藁诗。"]},{"t":"张功父请祠甚力得之简以长句","f":"词","c":["老夫不及朱师古，纳却太常少卿得潼府。","老夫不及张约斋，乞得华州仙观名云台。","金印如斗床满笏，富贵何曾膏白骨。","一世穷忙为阿谁，终日逢人皱两眉。","卖身长须仍赤脚，忍面墦间乞东郭。","添丁德曜喜欲颠，孤竹一箪真个错。","张君有宅复有田，朱君归去无一钱。","老夫老矣不归去，五柳先生应笑汝。"]},{"t":"忧患感叹二首 其二","f":"七言绝句","c":["老去情怀已不胜，愁边灾患更相仍。","胸中莫著伤心事，东处销时西处生。"]},{"t":"折杏子","f":"五言古诗","c":["天暖酒易醺，春暮花难觅。","意行到南园，杏子半红碧。","轻风动高枝，可望不可摘。","耸肩跂一足，偶尔攀翻得。","攀条初亦喜，折条还复惜。","小苦已自韵，未酸政堪吃。","聊将插鬓归，空樽有馀沥。"]},{"t":"旱后郴寇又作","f":"七言律诗","c":["自怜秋蝶生不早，只与夜蛩声共悲。","眼边未觉天地宽，身后更用文章为。","去秋今夏旱相继，淮江未净郴江沸。","饿夫相语死不愁，今年官免和籴不。"]},{"t":"李圣俞郎中求吾家江西黄雀醝法戏作醝经遗之","f":"七言古诗","c":["江夏无双小道士，一丘一壑长避世。","裁云缝雾作羽衣，芦花柳绵当裘袂。","身骑鸿鹄太液池，脚踏金蟆攀桂枝。","渴饮南阳菊潭水，饥啄蓝田栗玉芝。","今年天田秋大熟，紫皇遣刈神仓谷。","一双凫舄堕云罗，夜随弋人卧茅屋。","卖身不直程将军，却与彭越俱策勋。","解衣戏入玉壶底，壶中别是一乾坤。","水精盐山两岐麦，身在椒兰众香国。","玉条脱下澡凝脂，金叵罗中酌琼液。","平生学仙不学禅，刳心洗髓糟床边。","诸公俎豆惊四筵，犹得留侯借箸前。","昔为飞仙今酒仙，更入太史滑稽篇。"]},{"t":"李师儒上舍稽古堂","f":"七言古诗","c":["青枫金刹依然在，黄石圯桥元不改。","只有谪仙稽古堂，兵烧水毁草树荒。","二大夫家有孙子，去珠复还堂再起。","朱甍碧瓦拂金波，牙签玉轴拄银河。","山鬼吹灯听夜诵，秋兔献颖供晨哦。","向来二李名父子，今来二李佳兄弟。","鹡鸰双去集上林，李家大夫看二二。"]},{"t":"村店竹床","f":"五言绝句","c":["村店事事无，秋热夜夜至。","一双好竹床，无人将去睡。"]},{"t":"社日南康道中","f":"七言律诗","c":["东风试暖却成寒，春恰平分又欲残。","淡著烟云轻著雨，近遮草树远遮山。","人行柳色花光里，天接江西岭北间。","管领社公须竹叶，在家在外匹如闲。"]},{"t":"苏木滩","f":"五言古诗","c":["滩雪清溅眸，滩雷怒醒耳。","落洪翠壁立，跳波碧山起。","船进若战胜，船退亦游戏。","若非篙师苦，进退皆可喜。","忽逢下滩舟，掀舞快云駃。","何曾费一棹，才瞬已数里。","会有上滩时，得意君勿恃。"]},{"t":"走笔谢张功父送似酴醾","f":"七言古诗","c":["西湖野僧誇藏冰，半年化作真水精。","南湖诗人笑渠拙，不如侬家解乾雪。","藏冰窨子山之幽，镵透九地山鬼愁。","侬家藏雪有妙手，分明晒在翡翠楼。","向来巽二拉滕六，玉妃夜投玉川屋。","剪水作花吹朔风，揉云为粉散寒空。","醉挥两袖拂银汉，梢头万斛冷不融。","琼田挈月拾翠羽，砌成重楼天半许。","盘作青蛟吐绿雾，乱飘六出薰沉炷。","人间雪脆那可藏，天上雪落何曾香。","三月尽头四月首，南湖香雪今谁有，分似诚斋老诗叟。","碎挼玉花泛春酒，一饮一石更五斗。"]},{"t":"近岸","f":"七言绝句","c":["十日都无一日晴，牵船客子总斜行。","一川黄犊朝朝饱，岸草何曾减寸青。"]},{"t":"迓新守值雨","f":"七言古诗","c":["春雨不大又不晴，只与行人禁送迎。","小溪绿涨竟何曾，官路黄泥滑不胜。","今年送迎乃尔苦，去年送迎正如许。","风严火灭未五更，暗行十里鸡三鸣。","行路最难仍最恶，平生历尽今更觉。","前人失脚后人笑，后人失脚那可料。"]},{"t":"还家秋夕饮中喜雨","f":"七言绝句","c":["好风有意入金台，白酒无声落玉杯。","秋雨亦嫌秋热在，打荷飘竹为人来。"]},{"t":"进退格寄张功父姜尧章","f":"七言律诗","c":["尤萧范陆四诗翁，此后谁当第一功。","新拜南湖为上将，更差白石作先锋。","可怜公等俱痴绝，不见词人到老穷。","谢遣管城侬已晚，酒泉端欲乞移封。"]},{"t":"远峰","f":"五言绝句","c":["孤巘秀何似，碧莲含未开。","谁将脩月斧，斸取一尖来。"]},{"t":"连岭遇雨","f":"七言律诗","c":["肩舆正好看山色，雨里两窗开不得。","此外只有书可观，斜点又来湿书册。","一月秋晴一月泥，南翁此谚似可疑。","山寒却要日暴背，吾衰不用雨催诗。"]},{"t":"阻风泊舒州长风沙二首 其一","f":"五言律诗","c":["苦被淮西市，苛留江表船。","闻村红酒贱，看网白鱼鲜。","元是沧浪客，况逢花柳天。","山川嗔老我，醒眼对风烟。"]},{"t":"饮酒","f":"五言古诗","c":["今日偶不饮，无事亦有思。","偶然举一杯，事至我不知。","岂独忘万事，此身亦如遗。","此酒本何物，秫先曲还随。","饭秫祗醒眼，嚼曲无醉时。","秫曲偶相逢，清泉媒妁之。","不知独何神，幻出忘世姿。","庄周不须周，惠施不须施。","贵贱与死生，不齐元自齐。","我本非搢绅，金华牧羊儿。","祗坐读诗礼，一出不得归。","归来今四年，似早其实迟。","海中无蓬莱，蓬莱在酒池。","今夕一杯酒，乘风驾云旗。","犹遭世缘缚，未挂神武衣。"]},{"t":"龟峰","f":"词","c":["明发大琛山，龟峰引颈来对面。","亭午过弋阳，龟峰缩头不相见。","绿毛蒙茸净如染，紫壳轮囷有斑点。","不知七十二钻神不神，桃花市里看最真。"]},{"t":"使客不至夜归独酌","f":"五言律诗","c":["使客夜不至，还舍欣小歇。","杯盘只草草，足可相暖热。","庭前雪夜明，道是帘外月。","及见盘中酥，唤作庭前雪。"]},{"t":"侧溪解缆","f":"七言律诗","c":["梦里喧声定不凡，顺风解缆破晴岚。","起来职事惟洗面，此外功名是挂帆。","莫笑一蔬兼半菽，饱餐万壑与千岩。","蓬莱云气君休望，且向严滩濯布衫。"]},{"t":"卧治斋晚坐","f":"五言古诗","c":["闭户坐不得，开窗伫微凉。","树林荫白日，几研生碧光。","信手取诗卷，细哦三数章。","初披颇欣惬，再揽忽感伤。","废卷不能读，起行绕胡床。","古人恨如山，吾心澹于江。","本不与彼谋，云何断我肠。","感罢翻自笑，一蝉催夕阳。"]},{"t":"和王道父山歌二首 其一","f":"七言绝句","c":["东家娘子立花边，长笑花枝脆不坚。","却被花枝笑娘子，嫁期已是蹉春前。"]},{"t":"和丁端叔岁晚书怀","f":"词","c":["嗟予不能知止如邴曼容，又不能毕昏如尚子平。","软红尘里白双鬓，坐见岁律空峥嵘。","催科抚字两何有，伎俩已穷惭九九。","拔薤一本水一杅，多谢同朝金石友。","雪欺老病忽抵巇，西山冻裂不留薇。","诗坛老将更黩武，我已三北犹穷追。","老怀不中数怊怅，急漉鹅黄翻瓮盎。","苛留残雪更些时，为我装严丽谯上。"]},{"t":"和九叔知县昨游长句","f":"七言古诗","c":["诗穷不但两鬓霜，白发缘愁千丈长。","一年强半走道路，归来又见橘柚黄。","不如南邻更此里，醉折梅花照溪水。","扶藜时蹑大阮踪，觅句深参少陵髓。","昨游过眼不可留，今朝欲再亦何由。","新诗已落万人口，不应更著锦囊收。"]},{"t":"和马公弼雪","f":"七言律诗","c":["洒竹穿梅湖更山，客间得此未嫌寒。","髯疏也被轻轻点，齿冷犹禁细细餐。","晴了还成三日冻，销馀留得半庭看。","凭谁说似王郎妇，盐絮吟来总未安。"]},{"t":"和文黼主簿叔惠诗之韵","f":"七言律诗","c":["薄宦江湖苦异途，十年骨肉隔音书。","此行政尔见公面，又迫归欤巾我车。","安得从容林下去，相从漫浪物之初。","念公不是渔竿客，合结丝絇立玉除。"]},{"t":"和王司法雨中惠诗二首 其一","f":"七言古诗","c":["绝怜法曹三尺喙，不办太仓五升米。","胡奴走送今寂然，公路如何令至此。","春花秋月千首诗，一字不曾堪疗饥。","黄独已空镵底用，玉徽冻脱琴为炊。","穷鬼偏随天下士，再结柳车君但试。","不应满腹贮六奇，岂有逐贫无一计。","诗中哀怨海样深，青灯搔首夜沉沉。","一尊往慰风雨晚，莫管带围宽一眼。"]},{"t":"和丘宗卿赠长句之韵","f":"七言古诗","c":["君入脩门才一见，我出脩门风刮面。","归来急问有新诗，句句举似君不疑。","殿门握手冠缨绝，炯如云破瞻秋月。","老怀勃郁久不开，为君倾豁情既竭。","君诗元自过黄初，古雅可敬丽可娱。","诗坛端是一敌国，乃不自惜下取予。","向来交游半生死，悼往喜今同彼此。","老夫懒性不便书，毛颖为君浴清泚。","圣贤何时同一中，纵谈社燕与秋鸿。","芒鞋藤杖寻春风，天竺灵隐九里松。","古来乐事天悭与，怪珍未必逢良贾。","即今又欲驾官船，淮水中流送归虏。","金山独上妙高台，再与海若相诙谐。","归时藉手无一字，教君笑杀老诚斋。"]},{"t":"和石湖居士范至能与周子充夜游石湖松江诗韵","f":"七言古诗","c":["石湖醉眼小太空，乌纱白纻双鬓蓬。","翰林来从昭回上，满袖天香山水中。","青山半边日欲没，珠宫涌出初圜月。","两仙一棹软琉璃，碎撼广寒桂花雪。","中流浪作凛不回，两手播洒千银堆。","不知浩浩洪流后，曾有兹游奇特来。","古人今人烟一抹，谁煎麟角续弦绝。","一生句里万斛愁，只白秋来千丈发。"]},{"t":"和仲良分送柚花沉三首 其一","f":"七言绝句","c":["薰然真腊水沉片，烝以洞庭春雪花。","只得掾曹作南董，国香未向俗人誇。"]},{"t":"和仲良春晚即事五首 其五","f":"五言律诗","c":["笋改斋前路，蔬眠雨后畦。","晴江明处动，远树看来齐。","我语真彫朽，君诗妙斲泥。","殷勤报春去，恰恰一莺啼。"]},{"t":"和仲良春晚即事五首 其一","f":"五言律诗","c":["几许春才好，谁令绿遽深。","风光曾著眼，时序只惊心。","永日便甘寝，羁怀怯苦吟。","春归犹作客，晴少更多阴。"]},{"t":"和汤叔度雪","f":"七言律诗","c":["道得闲来尽未闲，颇缘幽事搅心间。","卧听雪作披衣起，不待天明带月看。","更觉梅枝殊摘索，只惊蓬鬓却羁单。","飞花岂解知人意，风里时时戏作团。"]},{"t":"和余处恭尚书清凉寺劝农","f":"七言古诗","c":["石城诸峰入天半，曾随骑吹经行遍。","梅花换岁初不惊，惊报行春再出城。","官甑晨炊云子玉，兵厨夜压秦淮绿。","尚书亲饷老农夫，塞道夫须兼独速。","劝农文字不怪奇，知道尚书愁我饥。","有如山农出南溪，老稚随观韩退之。","叟携群稚稚扶叟，一生祗识茅柴酒。","尚书赐酒谁得尝，瓦盆满引无升斗。","今年好风来自东，五风十雨尧日同。","尚书归去作相公，当寄丰年书一封。"]},{"t":"和吴伯承提宫孟冬风雨","f":"五言古诗","c":["旧雨新更寒，昼歇夜复陨。","我行十日泥，屦迹故未泯。","吟声正酸苦，已似琴促轸。","更遭雪作祟，不由弦不紧。","与公无诗债，何得便见窘。","半生领盛名，一面辱倾囷。","眼底过浮云，谁见柳下悯。","觅句许奇险，有底恼肝肾。","开怀爱我多，落笔为渠尽。","独怜禾头湿，可欢不可哂。"]},{"t":"和张器先十绝 其一","f":"七言绝句","c":["旧闻我里子张子，七字端能出六奇。","穷巷有门无剥啄，怪来佳客肯差池。"]},{"t":"和沈子寿还朝天集之韵","f":"七言古诗","c":["愁城不著狂诗客，径超天外华胥国。","苦海惟愁热恼人，别有月中水精域。","浣花一老已九京，何人再筑五言城。","竹斋衣钵传锦里，咄咄云烟飞落纸。","胸中磊磈有馀地，语下飘萧无俗气。","诗坛笔阵制中权，势如常山看率然。","观者堵墙颜色沮，惊闻柘弹金盘句。","老夫性癖耽此趣，被渠夜半赤手取。","重阳过了元不知，犹有黄花三两枝。"]},{"t":"和周元吉左司东省培竹","f":"五言古诗","c":["鸡省有贞植，鹜行销昼烦。","憎柳媚绿暗，伴梅耿黄昏。","何须雪贸贸，始爱渠轩轩。","坚守孤竹国，肯折先轸元。","如何桃李时，笋短不出垣。","周郎夜入直，挟策携酒尊。","为渠问玄夫，乃遇震为坤。","喜渠必蕃昌，吟到落金盆。","晓唤郭橐驼，提耳细细言。","汲水龙井泓，辇土天竺原。","妙偷造化窟，仁及冰霜根。","为赋淇奥诗，绝去笔墨痕。","何时淮阴市，能报漂母恩。","周郎顾之笑，吾自哀龙孙。"]},{"t":"和昌英叔觅松枝作日棚 其一","f":"七言绝句","c":["先人手种一川松，为栋为杗似未中。","只合茅斋听驱使，为公六月唤秋风。"]},{"t":"和昌英叔雪中春酌","f":"词","c":["南溪春寒强似冬，南溪春水走玉虹。","雷公戏手行春雪，诗人嘲词便飞屑。","只嫌春雪趁春雷，春容正要渠栽培。","冻作玉花销作雨，多般点缀春庭户。","酒杯如海醉即休，醉中看雪忘却愁。","如何呼酒不痛饮，可令诗肩受凄凛。","少时狂杀老更狂，长恐此意堕渺茫。","醉乡有地分一席，且与先生十分梨花注大白。"]},{"t":"和昌英主簿叔求潘墨","f":"七言律诗","c":["颇怯冥搜恼藏神，却思瘗砚学元宾。","墨家何以得公重，诗债又来欺我贫。","镜面松身纷楚楚，金华笏样本陈陈。","懒边此宝端无用，送似草玄扬子云。"]},{"t":"和罗巨济山居十咏 其三","f":"五言律诗","c":["只拥书千卷，何须屋万间。","新堂傍溪水，大字署蓬山。","恰有乘风客，来分半日闲。","自煎虾蟹眼，同瀹鹧鸪斑。"]},{"t":"和罗巨济山居十咏 其八","f":"五言律诗","c":["秀溪何处好，腊尾与春初。","山色梅边净，人家竹里居。","先生来得得，一笑意舒舒。","归路无灯火，冰轮挂岭隅。"]},{"t":"和罗武冈钦若酴醾长句","f":"七言古诗","c":["花飞十不啻五六，青子团枝失红簇。","江南桃李总成阴，不论少城与韦曲。","酴醾珍重不浪开，晚堆绿云点冰玉。","体薰山麝非一脐，水洗银河费千斛。","滴成小蓓密于糁，乱走长条柔可束。","醉眸须及月下来，破鼻细从风处触。","先生未必被花恼，偶与门人暮春浴。","为怜压架十万枝，小立傍边领新馥。","剩拚妙语宠琼蕤，更掇清英酿酃渌。","先生何得便杜门，霜鬓犹烦玉堂宿。"]},{"t":"和姜邦杰春坊续丽人行","f":"词","c":["玉人自惜如花面，不许黄鹂鹦鹉见。","若令画史识倾城，写遍人间屏与扇。","春光懒困扶不起，吹残玉笙也慵理。","是谁瞥见一梳云，微月影中扫秾李。","阿昉姓周不姓顾，笔端那得莲生步。","无妨正面与渠看，看了丹青无画处。","古来妍丑知几何，嫫母背面谩人多。","君不见汉宫六六多少人，画图枉却王昭君。","是时当面看写真，却遣琵琶弹塞尘。","不如九京唤起文与可，麝煤醉与竹传神。"]},{"t":"和徐盈赠诗二首 其一","f":"七言绝句","c":["不谒长安众富儿，不随举子脱麻衣。","片云出岫元无事，催我诗成翻手归。"]},{"t":"和萧伯和春兴","f":"七言律诗","c":["只道韶华不到侬，不妨软日媚柔风。","愁心自对春无味，老面可能花似红。","逢著诗狂兼酒圣，又忘人厄或天穷。","圣人枉索方兄价，我与贤人也一中。"]},{"t":"和萧判官东夫韵寄之","f":"七言律诗","c":["湘江晓月照离裾，目送车尘至欲晡。","归路新诗合千首，几时乘兴更三吾。","眼边俗物只添睡，别后故人何似臞。","尚策爬沙追历块，未甘直作水中凫。"]},{"t":"和彭仲庄七言","f":"七言古诗","c":["向来年少今老翁，随身不去只有穷。","请君与我共看镜，岂复平生冰雪容。","秋霖暗天瘦日色，满掇黄花当朝食。","何人裹饭问子桑，穷里逢君自为客。","空山冻吟只自奇，故人之外谁相知。","今年相从岂不好，安得到老长追随。","喜君诗思未渠薄，秋后花鹰兔边落。","惭我短才涩欲无，霜馀冰涧流还涸。","君游宣溪何日来，愁城封闭待君开。","定知此行脱寒谷，领取阳春一并回。"]},{"t":"和曾克俊惠诗","f":"七言律诗","c":["眼底春光正入年，社前燕子已言旋。","雨多厌听鸠夫妇，病起全疏酒圣贤。","旧喜作诗今已懒，君能得句我先传。","略无好语偿嘉惠，只么从权只么权。"]},{"t":"咏绩溪道中牡丹二种 其二 重台九心淡紫进退格","f":"七言律诗","c":["紫玉盘盛碎紫绡，碎绡拥出九娇饶。","却将些子郁金粉，乱点中央花片梢。","叶叶鲜明还互照，婷婷风韵不胜妖。","折来细雨轻寒里，正是东风拆半包。"]},{"t":"咏齑","f":"词","c":["庾郎晚菘翡翠茸，金城土酥玉雪容。","如何俱堕瑶瓮中，却与醯鸡同閟宫。","金井银床水清泚，雪山冰谷盐轻脆。","秋风一月酿得成，字曰受辛非曲生。","太学儒生朝复暮，茹冷啜寒那可度。","十年雪汁冻蔬肠，一夜饥雷听更鼓。","不如瓮头吏部瓮头醒，一逢受辛还一醒，毕卓与尔同死生。"]},{"t":"夜过五牧","f":"七言律诗","c":["船头更鼓打两声，如何未到常州城。","道旁火炬如昼明，道上牵夫如蚁行。","今宵到得荆溪馆，我欲眠时夜还短。","明朝拥被窥船窗，百尺柳条垂两岸。"]},{"t":"夜坐","f":"五言律诗","c":["夜永留清坐，诗臞称病容。","溪鸣风处竹，月湿露中松。","喜事何曾梦，灯花诳杀侬。","欲归归已得，归得却无悰。"]},{"t":"夜饮二首 其二","f":"五言律诗","c":["饮酒无奇诀，且斟三四分。","初头只嫌浅，忽地有馀春。","身外多少事，灯前子细论。","绝怜青女老，忍冷撒琼尘。"]},{"t":"夜饮二首 其一","f":"五言律诗","c":["夜饮空斋冷，移归近竹炉。","酒新今晚榨，烛短昨宵馀。","紫蔗椽来大，黄柑蜜不如。","醉中得五字，索笔不能书。"]},{"t":"夜饮以白糖嚼梅花","f":"七言律诗","c":["剪雪作梅只堪嗅，点蜜如霜新可口。","一花自可咽一杯，嚼尽寒花几杯酒。","先生清贫似饥蚊，馋涎流到瘦胫根。","赣江压糖白于玉，好伴梅花聊当肉。"]},{"t":"夜雨","f":"五言古诗","c":["幽人睡正熟，不知江雨来。","惊风飒然起，声若山岳摧。","起坐不复寐，万感集老怀。","忆年十四五，读书松下斋。","寒夜耿难晓，孤吟悄无侪。","虫语一灯寂，鬼啼万山哀。","雨声正如此，壮心滴不灰。","即今踰知命，已先十年衰。","不知后此者，壮心肯更回。","旧学日疏芜，书册久尘埃。","圣处与天似，而我老相催。","坐念慨未已，东窗晨光开。"]},{"t":"夜雨不寐","f":"五言律诗","c":["雨急点不疏，瓦乾声可数。","滴破江湖梦，合眼无复补。","更长酒力短，睡甜诗思苦。","已自不成眠，如何更遭许。"]},{"t":"夜雨晓发横冈","f":"五言律诗","c":["酝造通宵雨，殷勤数日风。","加三浓稚绿，第一淡蔫红。","润物初非惠，司春岂有功。","老农私独喜，不羡去年丰。"]},{"t":"夜宿东渚放歌三首 其三","f":"七言律诗","c":["天公要饱诗人眼，生愁秋山太枯淡。","旋裁蜀锦展吴霞，低低抹在秋山半。","须臾红锦作翠纱，机头织出暮归鸦。","暮鸦翠纱忽不见，只见澄江净如练。"]},{"t":"夜宿东渚放歌三首 其二","f":"七言律诗","c":["看山须看山表里，不然看山还误事。","平时只爱万峰青，落日惟存数尖紫。","浙江船上多少人，往来看山谁识真。","丁宁舟人莫浪语，却恐儿辈不肯去。"]},{"t":"夜宿东渚放歌三首 其一","f":"七言律诗","c":["前山欺我船兀兀，结约江妃行小谲。","乘我船摇忽远逃，见我船定还孤出。","老夫敢与山争强，受侮不可更禁当。","醉立船头看到夕，不知山于何许藏。"]},{"t":"夜宿杨溪晓起见雪","f":"七言古诗","c":["茅檐无声风不起，误喜夜来雨应止。","开门送眼忽心惊，失却前山万堆翠。","江南只说浙西山，更令著雪与人看。","诸峰尽处一峰出，凛然玉立最高寒。","溪声细伴吟声苦，客心冷趁波心去。","掉头得句恐天嗔，且唤征夫问前路。"]},{"t":"夜宿房溪饮野人张珦家桂叶鹿蹄酒其法以桂叶为饼以鹿蹄煮酒酿以八月过是则味减云","f":"七言律诗","c":["桂叶揉青作曲投，鹿蹄煮醁趁凉篘。","落杯瑩滑冰中水，过口森严菊底秋。","玉友黄封犹退舍，齑汤蜜汁更输筹。","野人未许传醅法，剩买双瓶过别州。"]},{"t":"姑苏馆上元前一夕观灯","f":"七言律诗","c":["茂苑元宵亦盛哉，千红百紫雪中开。","牡丹自是吴门有，莲莟移从都下来。","光射琉璃最精彩，吐成螮蝀贯昭回。","归船尚有残灯在，更与儿曹饮一杯。"]},{"t":"姑苏馆夜雪","f":"七言律诗","c":["昨朝晴色动春熙，入夜星河弄碧漪。","谁信雪花能样巧，等它人睡不教知。","起来红日恍开霁，照得玉花光陆离。","归去中都说奇事，姑苏馆里上元时。"]},{"t":"岭云","f":"七言绝句","c":["好山幸自绿崭崭，须把轻云护浅岚。","天女似怜山骨瘦，为缝雾縠作春衫。"]},{"t":"岸柳","f":"七言律诗","c":["柳梢拂入溪云阴，柳根插入溪水深。","祗今立岸一弊帚，归时弄日千黄金。","人生荣谢亦如此，谢何足怨荣何喜。","秋霜春雨自四时，老夫问柳柳不知。"]},{"t":"庚寅正月送罗季周游学禾川","f":"七言律诗","c":["眼边相识蚕样密，如子岁寒万才一。","我往西山子义山，老里一别堪三年。","外舅阴功不知数，诸孙太半廊庙具。","学文先要学忍饥，明年看子刺天飞。"]},{"t":"怪菌歌","f":"七言古诗","c":["雨前无物撩眼界，雨里道边出奇怪。","数茎枯菌破土膏，即时便与人般高。","撒开圆顶丈来大，一菌可藏人一个。","黑如点漆黄如金，第一不怕骤雨淋。","得雨声如打荷叶，脚如紫玉排粉节。","行人一个掇一枚，无雨即阖有雨开。","与风最巧能向背，忘却头上天倚盖。","此菌破来还可补，只不堪餐不堪煮。"]},{"t":"招陈益之李兼济二主管小酌益之指蚕豆云未有赋者戏作七言盖豌豆也吴人谓之蚕豆","f":"七言律诗","c":["翠荚中排浅碧珠，甘欺崖蜜软欺酥。","沙瓶新熟西湖水，漆櫑分尝晓露腴。","味与樱梅三益友，名因蚕茧一丝絇。","老夫稼圃方双学，谱入诗中当稼书。"]},{"t":"明发五峰寺","f":"五言古诗","c":["归时路何近，去时路何远。","山路无短长，人心有往返。","每因赴官期，一出谒乡县。","若非人事牵，无奈老身懒。","初心作此行，夜雨醒醉眼。","孤愁念群驺，尺泥滑双趼。","首涂天全湿，回辙云半捲。","投寺借松床，呼僧同野饭。","颓然佳眠足，得此行役倦。","暂劳新不堪，遐征旧所叹。","松菊岂不怀，樊笼何时免。","瘦藤要觅闲，到了古道院。"]},{"t":"明发四望山过都昌县入彭蠡湖","f":"五言古诗","c":["众船争取疾，直赴两山口。","吾船独横趋，甘在众船后。","问来风不正，法当走山右。","不辞用尽力，要与风相就。","忽然挂孤帆，吾船却先走。"]},{"t":"明发平坦市","f":"五言古诗","c":["花霏滋晓寒，叶哢新野听。","万象宿雨馀，洁斋无欠净。","霁曦耿欲吐，远峰忽复暝。","林庐居者谁，户与碧山映。","蔷薇上木末，不架得初性。","彼卧晏未兴，我征漂靡定。","悁然怀吾庐，花竹幽更盛。","兹焉独足羡，自视不差胜。","顾瞻江之西，心速路逾夐。","似闻前溪水，尽还旧沙径。"]},{"t":"明发生米市西林寺进退格","f":"五言律诗","c":["贪睡能无起，挑灯强未残。","舂声忙野店，月色澹柴门。","又踏黄尘路，前追红叶村。","秋衣那敢薄，病骨自难温。"]},{"t":"明发白沙滩闻布谷有感","f":"五言古诗","c":["提壶劝我饮，杜鹃劝我归。","不如布谷子，劝我勤耘耔。","我少贫且贱，不但无置锥。","笔耒垦纸田，黑水导墨池。","借令字堪煮，识字亦几希。","啼饥如不闻，饥惯自不啼。","骏奔三十年，辛勤竟何为。","发从道涂白，面为风雪黧。","夜来白沙滩，老命轻如丝。","洪涛舞一叶，呼天叫神祇。","生全乃偶然，人力初何施。","晓闻布谷声，如在故山时。","坐令万感集，初悟半世非。","一险靡不悔，数悔庸何追。","有田不归耕，布谷真吾师。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其十","f":"五言古诗","c":["南中山绝佳，所恨人烟稀。","略无好事人，结茅临深溪。","峰顶可月亭，岸石即钓矶。","空令烟中猿，挂崖弄涟漪。","山多人自少，人远山益奇。","我舟行不留，过眼山如驰。","过眼意已足，久留亦何为。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其九","f":"五言古诗","c":["我从灵洲来，惟见芳草渡。","蒹葭随水远，旷野无立树。","挂席上真阳，好山忽无数。","好山如隐士，避世不自露。","不应官道傍，乃有见山处。","借识卫叔玠，未睹乐彦辅。","石峰难再得，舟过更回顾。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其八","f":"五言古诗","c":["城中安得山，无山安得诗。","我入五羊城，遂与山水辞。","有镜不敢览，尘面我自知。","解维来归亭，山水奔相随。","水光动我巾，山色染我衣。","舟行将一月，恨速不恨迟。","山云来未已，江月皎无滓。","开怀放之入，出语颇似之。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其七","f":"五言古诗","c":["危峰瑩无土，平地岌孤石。","如何半岩间，亦有小树碧。","走空根苦辛，倚险干寒瘠。","芳兰间丛生，紫蕤濯幽色。","近香许世闻，远秀绝人摘。","而我云外身，方兹喟行役。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其六","f":"五言古诗","c":["山转江亦转，江行山亦行。","风鬟照玉镜，素练萦青屏。","我本山水客，澹无轩冕情。","尘中悔一来，事外怀孤征。","忽乘沧浪舟，仰高俯深清。","餐翠腹可饱，饮渌身顿轻。","鹧鸪不相识，还作故园声。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其五","f":"五言律诗","c":["澄潭涌暗晕，不风自成花。","回流如倦客，出门复还家。","江晴已数日，新涨没旧沙。","知是前溪雨，湿云尚横斜。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其四","f":"五言古诗","c":["后顾江已远，前睨山若塞。","棹进岸自回，天水未有极。","帘欣入绝巘，舟愕触潜石。","东暾澹未熹，北吹寒更寂。","岸草不知愁，向人弄晴碧。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其三","f":"五言古诗","c":["昨宵望石峰，相去无一尺。","今日行终朝，祇绕石峰侧。","石峰何曾远，江路自不直。","仰瞻碧孱颜，清峻如立壁。","反覆得细看，何必更登陟。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其二","f":"五言古诗","c":["地迥人绝影，山僻虎留迹。","下有无底潭，上有欲落石。","是间一径横，夹以万松直。","树从何时有，陈公所手植。","陈公今焉在，径松自寒碧。"]},{"t":"明发陈公径过摩舍那滩石峰下十首 其一","f":"五言律诗","c":["遥松烟未销，近竹露犹滴。","石峰矜孤锐，喜以江自隔。","清潭涵曦紫，碧岫过云白。","回瞻宿处堤，路转不可觅。"]},{"t":"明发茅田见鹭有感","f":"七言绝句","c":["自叹平生老道涂，不堪泥雨又驱车。","鹭鸶第一清高底，拂晓溪中有干无。"]},{"t":"明发荆溪馆下","f":"七言古诗","c":["常州太守曾独弄，回首向来真一梦。","五月炎天十月寒，东亭迎客西亭送。","自从别却翟家园，岂谓三经金斗门。","莫教物色有欠处，剩与新诗三五句。","犹有归涂更一来，是时百花开未开。"]},{"t":"明发栖隐寺","f":"词","c":["木鱼一呼众僧聚，老夫登车欲前去。","仰头见天俯见路，明明是昼不是暮。","如何今晨天地间，咄咄怪事满眼前。","将为是夜著，月轮已没星都落。","将谓是昼休，银河到晓烂不收。","皎如江练横天流，中流点缀金沙洲。","元来海底蚤浴日，云师闭关不教出。","羲和挥斧斫云关，取将一道天光还。","天光淡青日光白，道是银汉也则得。","云师强很赶不奔，堆作沙洲是碎云。"]},{"t":"明发康郎山下亭午过湖入港小泊棠阴砦回望豫章西山慨然感兴","f":"楚辞体","c":["大江日东流，我坐自向西。","亦复拜新月，不为学蛾眉。","恭惟月生处，下临故园池。","青松一万株，牡丹三千枝。","床下枕北山，檐前漱南溪。","岁岁身不到，夜夜魂必归。","魂归谅何益，梦觉心自怡。","魂梦尚如许，而况真归兮。","前日至邬子，西山出湖湄。","如见乡人面，一笑相娱嬉。","旅情得暂欣，乡愁动长思。","今朝发康郎，一路能相随。","我船趋都昌，回首尚见之。","偶尔转港汊，极目烟水迷。","不得一揖别，悔懊庸可追。"]},{"t":"易允升画像赞","f":"五言绝句","c":["疏髯撚欲无，短鬓搔已秃。","定知得句来，暗喜见眉目。"]},{"t":"枕上闻子规二首 其二","f":"七言绝句","c":["去年借宅寄生儿，今岁群儿又学伊。","羞面见它莺与燕，向人强道不如归。"]},{"t":"枕上闻子规二首 其一","f":"七言绝句","c":["半世征行怕子规，一闻一叹一沾衣。","如今听著浑如梦，我自高眠汝自啼。"]},{"t":"林景思寄赠五言以长句谢之","f":"词","c":["华亭沈虞卿，惠山尤延之。","每见无杂语，只说林景思。","试问景思有何好，佳句惊人人绝倒。","句句飞从月外来，可羞王公荐穹昊。","若人乘云驾天风，秋衣剪菊裁芙蓉。","暮宿银汉朝蓬宫，我欲从之东海东。","西湖柳色二三月，相逢一笑冠缨绝。","醉招和靖叫东坡，一吸西湖湖欲竭。","我醉自眠君自颠，路人往往指作仙。","此辈何曾识此乐，识与不识俱可怜。","别时花开今已落，思君令人瘦如鹤。","梦里随君携酒瓢，同登天台度石桥。","瀑泉界天泻云窟，长松拔地搀烟霄。","与君联句章未了，帝城钟动西峰晓。","海风吹堕珊瑚枝，乃是先生寄我诗。","火云烧江江水沸，君诗清凉过于水。","定知来自雪巢底，恍然坐我天台寺。"]},{"t":"泊舟临平二首 其二","f":"七言古诗","c":["拂溪十点五点雨，縠纹织出团花缕。","花头细大虽不匀，一花销时一花吐。","北风卷云如卷帘，忽然收尽玉廉纤。","天光却在水光下，天水镕作镜一奁。","好山隔市望不见，祗有清溪照人面。"]},{"t":"泊舟临平二首 其一","f":"七言律诗","c":["前窗向市下却帘，后窗临水开却门。","岸头杨柳报春动，溪底云天随浪翻。","隔溪数间黄草屋，绕屋千竿翠琼竹。","三老鸣钲舣柂楼，今宵又向临平宿。"]},{"t":"泊冷水浦","f":"七言律诗","c":["前夕放船湘口步，约到衡州来日午。","五程一减作三程，谢渠江涨半篙清。","今日雨来三四五，又闭疏篷听暮雨。","长年商量泊船所，雨外青山更青处。"]},{"t":"盱眙军东山飞步亭和太守霍和卿韵","f":"七言律诗","c":["杏花岩左斸东岩，驱使淮山指顾间。","招信上流总奔赴，僧伽孤塔政弯环。","今来古往空陈迹，远草斜阳祇惨颜。","走马看山真懡㦬，忙中拾得片时閒。"]},{"t":"经和宁门外卖花市见菊","f":"词","c":["病眼仇冤一束书，客舍葭莩菊一株。","看来看去两相厌，花意索寞恰似无。","清晓肩舆过花市，陶家全圃移在此。","千株万株都不看，一枝两枝谁复贵。","平地拔起金浮屠，瑞光千尺照碧虚。","乃是结成菊花塔，蜜蜂作僧僧作蝶。","菊花障子更玲珑，生采翡翠铺屏风。","金钱装面密如积，金钿满地无人拾。","先生一见双眼开，故山三径何独怀。","君不见内前四时有花卖，和宁门外花如海。"]},{"t":"罗元通挽诗","f":"五言律诗","c":["奏赋曾三北，兴能竟二南。","如何双桂子，枉著拜亲衫。","旧事馀诗酒，何人续笑谈。","生前孝友在，伐石为公镵。"]},{"t":"罗仲宪送蔊菜谢以长句","f":"词","c":["学琴自有谱，相鹤自有经。","蔬经我翻尽，不见蔊菜名。","金华诗里初相识，玉友尊前每相忆。","坐令芥孙姜子芽，一见风流俱避席。","取士取名多失真，向来许靖亦误人。","君不见郑花不得半山句，却参鲁直称门生。"]},{"t":"罗价卿母李氏挽诗","f":"五言律诗","c":["孝岂天无报，慈如古所称。","百年得偕老，二子看同升。","未拜鸾回纸，先虚绣蹙藤。","他时颍考叔，清泪落君羹。"]},{"t":"苦吟","f":"七言律诗","c":["蚁无秋衣雁有裘，霜天谋食各自愁。","雁声寒死叫不歇，蚁膝冻僵行复休。","先生苦吟日色晚，老铃来催吃朝饭。","小儿诵书呼不来，案头冷却黄齑面。"]},{"t":"英石铺道中","f":"七言古诗","c":["一路石山春更绿，见骨也无斤许肉。","一峰过了一峰来，病眼将迎看不足。","先生尽日行石间，恰如蚁子缘假山。","穿云渡水千万曲，此身元不离岩峦。","莫嫌宿处破茅屋，四方八面森冰玉。","孤峰高绝连峰低，圜者如廪尖如锥。","苍然秀色借不得，春风领入玉东西。","英州那得许多石，误入天公假山国。"]},{"t":"视旱憩镜田店","f":"五言律诗","c":["走檄堪频捧，严程敢少徐。","虽晴恐非久，犹热未全无。","憩息翻增倦，驰驱减壮图。","诗成兼利害，失闷得清臞。"]},{"t":"试毗陵周寿墨池样笔","f":"七言古诗","c":["旧来鸡距说宣城，近来墨池说毗陵。","不知阿谁喜柔懦，毛颖只今泥样软。","笔头政要挽千钧，渠自无力随人转。","兔尖如针利如锥，方能幻出抉石猊。","少年免冠已秃鬓，老去种种将奚为。","就中周寿差可意，锐头将军殊解事。","铦锋不用洮州砺，刚肠颇学汲都尉。","先生焚香坐明窗，中书奋髯猬毛张。","愿翻墨汁诗战场，先生一挥十万行。","梅花微笑看在旁，吾诗虽非云锦章，中有梅花玉雪香。"]},{"t":"试蜀中梁杲桐烟墨书玉板纸","f":"七言古诗","c":["木犀煮泉漱寒齿，残滴更将添砚水。","子规乡里桐花烟，浣花溪头琼叶纸。","先生老去怯苦吟，琢无肝肺呕无心。","芙蓉在左木犀右，漫与七言真藉手。","秋光一点入骨清，有笔如椽描不就，先生不瘦教谁瘦。"]},{"t":"题三老图二首 其一","f":"七言绝句","c":["旦奭行间著季真，黄冠不合附青云。","二南风里君知么，添个委蛇退食人。"]},{"t":"钓雪舟中霜夜望月","f":"七言古诗","c":["溪边小立苦待月，月知人意偏迟出。","归来闭户闷不看，忽然飞上千峰端。","却登钓雪聊一望，冰轮正挂松梢上。","诗人爱月爱中秋，有人问侬侬掉头。","一年月色只腊里，雪汁揩磨霜水洗。","八荒万里一青天，碧潭浮出白玉盘。","更约梅花作渠伴，中秋不是欠此段。"]},{"t":"雨中春山","f":"七言古诗","c":["谁作春山新幛子，尖峰为笔天为纸。","近看点缀八九山，山外远山三万里。","纸痕惨淡远山昏，上有长松青到云。","自嫌松色太青在，旋拈粉笔轻轻盖。","须臾粉淡松复青，至竟远山描不成。"]},{"t":"雨中送客","f":"七言绝句","c":["闲人也解有忙时，送客谁令作许痴。","一夜黑风吹白雪，昨朝紫陌总黄泥。"]},{"t":"雨后子文伯庄二弟相访同游东园","f":"五言律诗","c":["北阮稀相见，东园肯到无。","鞋留沙迹浅，扇答雨声疏。","新长水三尺，倒漂梅一株。","炊烟起山崦，好个晚村图。"]},{"t":"雨后至溪上","f":"七言律诗","c":["夜雨无端忽晓晴，南溪便长半篙清。","斜冲乱石雪霜碎，快泻深陂金玉声。","慢处回头萦作漩，急边眨眼不留行。","李成觑著如何画，却是诗中画得成。"]},{"t":"雨后晓起问讯梅花","f":"七言古诗","c":["前日看梅风吹倒，昨日看梅雨沾帽。","近梅一日或再来，远梅隔年才一到。","夜来为梅愁雨声，挑灯起坐至天明。","不知消息平安否，早来问讯还疾走。","横枝雨后转清妍，玉容洗妆晨更鲜。","绝似孤山半峰雪，不羡玉井十丈莲。","十事八九不如意，人生巧堕天公计。","簿书海底白人头，孤负江南风月秋。","忆昔少年命同社，月里传觞梅影下。","一片花飞落酒中，十分便罚琉璃钟。","如今老病不饮酒，梅花也合怜衰翁。"]},{"t":"雨后晓起看山","f":"五言古诗","c":["晨起出蓬户，换却隔水峰。","细看只旧山，色与昨不同。","虽经夜来雨，末必有许功。","云师挈众巉，置在蓝水中。","沙土俱绿净，草树添青葱。","不然近秋衰，那得还春容。","此意殊不浅，要将调诗翁。","判断索一语，可惜语不工。","正使语工著，不如山色浓。"]},{"t":"雨后晓登碧落堂","f":"五言古诗","c":["清晨上碧落，亲手启后户。","斜东见西山，粹碧无纤雾。","须臾半崦间，冉冉动微絮。","吹作千峰云，立变万姿度。","正北寻米山，遥隔一片雨。","亭亭如仙子，晓起浣月露。","天衣异人世，一色制轻素。","两山谁不奇，裴回未能去。"]},{"t":"雨霁幽兴寄张钦夫","f":"五言古诗","c":["大官有重荷，丰廪无薄忧。","草茹我岂腴，饱亦与彼侔。","积雨久自霁，曙光清以幽。","欣然出荆扉，不出旬已周。","初意欲看竹，信步偶临流。","北惊失故岸，东见生新洲。","怀哉古与今，与此岂不犹。","归来翻不乐，隐几到昔游。","平生忘年友，草草相应酬。","暂梦不多款，唤人苦鸣鸠。","山林本无事，亦复扰扰休。"]},{"t":"雨霁看东园桃李行溪上进退格","f":"七言律诗","c":["药裹关心正腹烦，强排孤闷到东园。","行穿一一三三径，来往红红白白间。","绕树仰看浑不见，隔溪回望不胜繁。","村村桃李家家柳，脚力酸时坐看山。"]},{"t":"饯洪帅张伯子华学尚书移镇京口","f":"词","c":["周家天球祇一只，张家今有双白璧。","前称紫薇后文昌，衙官二陆仆两唐。","金章玉句迭清锵，天孙云机织锦裳。","松心竹节争老苍，冰壶水镜明秋霜。","君不见于湖先生掌纶綍，二典三谟才一笔。","君不见笃素先生立朝端，五臣十乱半武间。","听履星辰践台斗，翻身凤池屈伸肘。","梦入飞云卷雨帘，袖却筑岩作霖手。","滕王阁上唐阿舒，春生秋杀震江湖。","吏部未见张尚书，春生尽有秋杀无。","江西十州百万户，父非姓召母非杜。","也祇周人两句诗，岂弟君子民父母。","又去南徐作好春，落霞秋水亦眉颦。","南徐父老错欣欣，玉皇催渠转鸿钧。"]},{"t":"临平解舟","f":"七言律诗","c":["竹篱短短门小小，少年独立春风晓。","柳芽缩爪尚怯寒，金粟斑斑满枝了。","过船桥下桥绝高，波清深见一截篙。","市人夹水争出看，无数渔舟避东岸。"]},{"t":"临贺别驾李子西同年寄五字诗以杜句君随丞相后为韵和以谢焉五首 其五","f":"五言律诗","c":["买山艺花竹，长恐落人后。","不见竹林人，山王非俎豆。","市门能几许，掉臂日奔凑。","迟子来朝天，商略陈薄陋。"]},{"t":"临贺别驾李子西同年寄五字诗以杜句君随丞相后为韵和以谢焉五首 其四","f":"五言律诗","c":["曲江与临武，彼此昔相望。","一岭大如砺，谁云隔寻丈。","离合非人力，此事要天相。","升沈亦偶然，岂问优与脏。"]},{"t":"临贺别驾李子西同年寄五字诗以杜句君随丞相后为韵和以谢焉五首 其三","f":"五言律诗","c":["谪仙几代孙，今日临贺丞。","风月三千首，吾子岂未能。","长把脩月斧，细彫玉壶冰。","天池羽翼就，即看垂天鹏。"]},{"t":"临贺别驾李子西同年寄五字诗以杜句君随丞相后为韵和以谢焉五首 其二","f":"五言律诗","c":["老拙谁肯伴，束书自相随。","此外无长物，犹有一鸱夷。","小醉即孤咏，自遣不要奇。","西湖妙天下，未羡习家池。"]},{"t":"临贺别驾李子西同年寄五字诗以杜句君随丞相后为韵和以谢焉五首 其一","f":"五言律诗","c":["我本南溪老，手弄溪中云。","诵诗爱招隐，读骚续湘君。","忽捧公府檄，遂远先人坟。","春暮归未得，落花政纷纷。"]},{"t":"前苦寒歌","f":"七言古诗","c":["四大海潮打清淮，三万里风平地来。","龟山横身拦不住，潮波怒飞风倒回。","欲晴不晴雪不雪，并作苦寒冻人绝。","古寺大钟十字裂，东山石崖一峰蹶。","劝君莫出君须出，冰脱君髯折君骨。"]},{"t":"南斋前梅花二首 其一","f":"七言绝句","c":["山园腊里日疏芜，只有南斋最起予。","竹映梅花花映竹，翠毛障子玉妃图。"]},{"t":"南溪细陂","f":"七言古诗","c":["仙家有药世无比，能乾水银作银子。","老夫却把水晶环，镕作南溪一溪水。","闲随稚子作儿嬉，金沙玉砾磊细陂。","水从陂上泻涧底，椎碎水晶声满耳。","忽然流下片苍苔，一朵碧云影千里。"]},{"t":"南溪堰滩","f":"七言律诗","c":["为爱溪流箭样湍，戏抛乱石障清澜。","忽如亚父撞玉斗，又似仲尼鸣象环。","整北移南教尽怒，从朝至午不知还。","便饶滟滪三巴峡，也当龙门八节滩。"]},{"t":"南溪暮立","f":"七言绝句","c":["溪影明霞新月底，水声乱石嫩沙间。","欲归小为鱼儿住，更看跳波玉一环。"]},{"t":"城上野步用辘轳体","f":"五言律诗","c":["寒劲无遗暖，晴行失老怀。","叶飞枫骨立，萍尽沼奁开。","路好仍回首，泥残敢放鞋。","登临不须尽，留眼要重来。"]},{"t":"将至地黄滩","f":"五言古诗","c":["未到地黄滩，十里先闻声。","樯竿已震掉，未敢与渠争。","舟人各整篙，有如大敌临。","搴篷试一望，溅雪纷淙琤。","乃是水硙港，为滩作先鸣。","真滩定若何，老夫虚作惊。"]},{"t":"尝荼?酒","f":"七言律诗","c":["月中露下摘荼糜，泻酒银瓶花倒垂。","若要花香薰酒骨，莫教玉醴湿琼肌。","一杯堕我无何有，百罚知君亦不辞。","敕赐深之能几许，野人时复一中之。"]},{"t":"尝诸店酒醉吟二首 其二","f":"五言律诗","c":["我饮无定数，一杯复一杯。","醉来我自止，不须问樽罍。","白眼望青天，青天为我开。","青天不开时，我醉眠苍苔。"]},{"t":"尝诸店酒醉吟二首 其一","f":"五言律诗","c":["饮酒定不醉，尝酒方有味。","清浊与醇醨，杂酌注愁肺。","偶尔遇真趣，颓然得佳寐。","醒人作醉语，语好终不是。"]},{"t":"峡中得风挂帆","f":"七言古诗","c":["楼船上水不寸步，两山惨惨愁将暮。","一声霹雳天欲雨，隔江草树忽起舞。","风从海南天外来，怒吹峡山山倒开。","百夫绝叫椎大鼓，一夫飞上千尺桅。","布帆挂了却袖手，坐看水上鹅毛走。"]},{"t":"幽居三咏 其二 云卧庵","f":"七言绝句","c":["十年两袖软红尘，归濯沧浪且幅巾。","不是白云留我住，我留云住卧闲身。"]},{"t":"度小桥","f":"五言律诗","c":["危桥度中半，深溪动人心。","欲返业至此，将进眩下临。","已涉尚回顾，溪水知几深。","谁能大此桥，以安往来人。"]},{"t":"待家酿未至且买姜店村酒","f":"五言律诗","c":["奔走人都倦，檐檠酒未来。","那能待竹叶，随喜唤茅柴。","芦菔仍多煮，庵摩带浅煨。","深村市无肉，草草两三杯。"]},{"t":"春兴","f":"七言律诗","c":["窗底梅花瓶底老，瓶边破砚梅边好。","诗人忽然诗兴来，如何见砚不见梅。","急磨玄圭染霜纸，撼落花须浮砚水。","诗成字字梅样香，却把春风寄谁子。"]},{"t":"春兴","f":"七言绝句","c":["著尽工夫是化工，不关春雨更春风。","已拚腻粉涂双蝶，更费雌黄滴一蜂。"]},{"t":"春菜","f":"词","c":["雪白芦菔非芦菔，吃来自是辣底玉。","花叶蔓菁非蔓菁，吃来自是甜底冰。","三馆宰夫传食籍，野人蔬谱渠不识。","用醯不用酸，用盐不用咸。","盐醯之外别有味，姜牙枨子仍相参。","不甑亦不釜，非蒸亦非煮。","坏尽蔬中腴，乃以烟火故。","霜根雪叶细缕来，瓷瓶夕羃朝即开。","贵人我知不官样，肉食我知无骨相。","祗合南溪嚼菜根，一尊径醉溪中云。","此诗莫读恐咽杀，要读此诗先捉舌。"]},{"t":"春晴","f":"五言绝句","c":["日透微风暖，风揉嫩日佳。","祇知趱桃李，不道落梅花。"]},{"t":"昼睡闻雁","f":"七言绝句","c":["梦里霜鸿叫绝天，䰒松睡眼起来看。","殷勤甓社湖中客，送我南归到惠山。"]},{"t":"柳絮","f":"七言律诗","c":["寒勒花迟却速残，暖将絮过忽吹还。","雪翻霁日光风急，毬衮回廊曲榭闲。","万里云天皆去处，群飞踪迹恣中间。","道渠催得春阑著，春不缘渠独不阑。"]},{"t":"栀子花","f":"五言律诗","c":["树恰人来短，花将雪样看。","孤姿妍外净，幽馥暑中寒。","有朵篸瓶子，无风忽鼻端。","如何山谷老，只为赋山矾。"]},{"t":"残雪","f":"七言绝句","c":["残雪堆成山数重，悬崖幽窦玉玲珑。","如何借得仙人掌，擎取琼瑶三四峰。"]},{"t":"毗陵郡斋追忆乡味","f":"七言古诗","c":["坐无黄雀牛尾狸，荆溪日日思江西。","若无鹅梨与海错，江西却恐思荆溪。","旧居江西不自惜，到得荆溪却追忆。","明年官满归江西，却忆荆溪难再得。","江珍海错各自奇，冬裘何曾羡夏絺。","鹅梨黄雀无不可，荆溪江西不关我。"]},{"t":"牵牛花三首 其二","f":"七言绝句","c":["莫笑渠侬不服箱，天孙为织碧云裳。","浪言偷得星桥巧，只解冰盘染茈姜。"]},{"t":"牵牛花三首 其一","f":"七言绝句","c":["素罗笠顶碧罗檐，晚卸蓝裳著茜衫。","望见竹篱心独喜，翩然飞上翠琼篸。"]},{"t":"癸未上元后永州夜饮赵敦礼竹亭闻蛙醉吟","f":"七言古诗","c":["茅亭夜集俯万竹，初月未光让高烛。","主人酒令来无穷，恍然堕我醉乡中。","草间蛙声忽三两，似笑吾人悭酒量。","只作蛙听故自佳，何须更作鼓吹想。","尚忆同登万石亭，倚栏垂手望寒青。","只今真到寒青里，吾人不饮竹不喜。"]},{"t":"省宿题天官厅后竹林","f":"七言绝句","c":["秋声偷入翠琅玕，叶叶竿竿玉韵寒。","声在树间元未是，秋声只在竹林间。"]},{"t":"看刘寺芙蓉","f":"五言古诗","c":["初约山寺游，端为怪奇石。","那知云水乡，化作锦绣国。","入门径深深，过眼秋寂寂。","隔竹小亭明，稠红漏疏碧。","山僧引幽践，绝巘恣佳陟。","三步绮为障，十步霞作壁。","烂如屏四围，搭以帔五色。","满山尽芙蓉，山僧所手植。","秋英例臞淡，此花独腴泽。","却忆补外时，朝士作祖席。","是间万株梅，冷射千崖白。","旧游不可寻，雪枝半榛棘。"]},{"t":"秋夕雨馀","f":"七言古诗","c":["虚堂无人独自行，画檐雨歇残点声。","朝来馀暑忽然过，昨来初暑谁能那。","一生畏暑如于菟，老年畏暑菟不如。","人言岭南分外热，匹似江南犹可说。","今年六月雨如秋，只今七月当更愁。","短檠幸未卧墙角，唤取渠来相博约。","老眼那能舒简编，只要玉虫伴杯酌。"]},{"t":"秋山","f":"七言绝句","c":["梧叶新黄柿叶红，更兼乌臼与丹枫。","只言山色秋萧索，绣出西湖三四峰。"]},{"t":"秋日早起","f":"五言古诗","c":["我眠亦甚安，梦中初无惊。","如何作梦语，反侧意不平。","起来不复寐，郡楼挝五更。","窗纸尚昏昏，看到渐次明。","卷帘启后户，披衣步中庭。","汲井漱新泉，满面吹寒冰。","仰看天宇旷，微白复淡青。","犹挂烂银梳，未升紫金钲。","砌蛩馀夜唧，树鹊作晓鸣。","群动俱扰扰，竞若有所营。","而人居其间，独欲免夙兴。","出山三见秋，一年一征行。","今兹秋又至，归心捺还生。","会当挂其冠，高卧听松声。"]},{"t":"秋日早起","f":"五言律诗","c":["鸡鸣钟未鸣，不知乡晨否。","起来恐惊众，未敢启户牖。","残灯吐芒角，上下两银帚。","定眼试谛观，散作飞电走。"]},{"t":"秋日晚望","f":"五言律诗","c":["村落丰登里，人家笑语声。","溪霞晚红湿，松日暮黄轻。","只么秋殊浅，如何气许清。","不应久闲散，便去羡功名。"]},{"t":"秋衣","f":"五言古诗","c":["晨兴换新衣，视身忽潜愕。","腹皮皱百摺，髀肉宽一握。","沈痾两年馀，衰体半标落。","且留宿尘垢，莫遣新澡濯。","未澡体尚肥，既濯肌转削。","无发已是僧，有骨不如鹤。","明年方八十，似觉九十著。","寡食幸自清，辟谷底须学。","便可作飞仙，御风上云幕。","如何肥瘠想，犹有秋衣作。"]},{"t":"秋夜","f":"七言绝句","c":["挑落寒灯一点青，方知斜月半窗明。","无端一阵秋声起，唤作铜瓶蟹眼鸣。"]},{"t":"秋雨蚤作有叹","f":"五言古诗","c":["细雨澹无质，安得更有声。","如何却作泥，亦能妨晨征。","宿昔忽过暄，心知非坚晴。","何须暄晴极，然后寒雨生。","寒暄使人觉，妙物亦何曾。","剪剪自神妙，无乃与物矜。","造物本非作，观者或强名。","老夫近稍聋，此事无暇听。","平生感秋至，此意念已平。","独念老病身，颇不耐夙兴。","何时归故园，晏眠闭柴荆。","鸣鸡亦不留，好梦无吾惊。","他年忆此诗，惘如宿酒醒。","思归已可喜，而况真归耕。"]},{"t":"秋浦登舟阻风泊池口","f":"七言古诗","c":["午眠化蝶化未成，梦中澒洞发大声。","军鼙雷鼓百千面，援桴齐下作一鸣。","起来推窗无一物，海潮打入齐山窟。","数洲翻覆相荡摩，四山动摇皆突兀。","钱塘潮来声惊天，金陵潮来声寂然。","此去金陵一千里，那得潮声来到此。","长年三老笑复嘲，云是波声不是潮。","清溪波头高过屋，大江波头泼日毂。","清溪去江一步地，大江可望不可至。","北风向晚动地来，跳出银峰万万堆。","侬船莫管行不得，且看银峰永今夕。"]},{"t":"秋暑","f":"五言古诗","c":["夏暑减未曾，秋暑增愈剧。","老翁避无处，茅斋聊憩息。","银盆满注水，银水同一色。","中涵双桂影，倒卧一天碧。","清光湛不动，欲弄还复惜。","偶然一播洒，树影碎相激。","洗面凉已滋，漱齿痛仍逼。","平生畏秋暑，老去畏弥极。"]},{"t":"类试所戏，集杜句跋杜诗，呈监试谢昌国察院","f":"词","c":["有客有客字子美，日籴太仓五升米。","锦官城西生事微，尽醉江头夜不归。","青山落日江湖白，嗜酒酣歌拓金戟。","语不惊人死不休，万草千花动凝碧。","稚子敲针作钓钩，老夫乘兴欲东流。","巡檐索共梅花笑，还如何逊在杨州。","老去诗篇浑漫与，蛱蝶飞来黄鹂语。","往时文采动人主，来如雷霆收震怒。","一夜水高数尺强，濯足洞庭望八荒。","阊阖晴开映荡荡，安得仙人九节杖。","君不见西汉杜陵老，脱身事幽讨。","下笔如有神，汝与山东李白好。","儒术于我何有哉，愿吹野水添金杯。","焉知饿死填沟壑，如何不饮令心哀。","名垂万古知何用，万牛回首丘山重。"]},{"t":"给事葛楚辅侍郎余处恭二詹事招储禁同寮沈虞卿秘监谕德尤延之右司侍讲何自然少监罗春伯大著二宫教及予泛舟西湖步登孤山五言","f":"五言古诗","c":["晓雨捣珠屑，吹作空中尘。","拂水无落晕，映峦有遮痕。","承华两端尹，嘉招出城闉。","一尊浇云师，借风开昼昏。","诸鬟忽脱帽，孤镜亦捲裀。","西湖翳复皎，南山洗如新。","舍舟步柳堤，曳杖啄松门。","乃是小上林，亦有虎守阍。","桂落剩金粟，蓉妆浓绣屏。","高堂竹梢上，幽榭荷叶滨。","群仙此小憩，呼酒领一欣。","秋花隔水笑，笑我堕纱巾。","更酬不知筹，互嘲还作春。","行乐戒多取，况复仄羲轮。","归鬉兀颓玉，那知醉与醒。"]},{"t":"胡达孝水墨妙绝一世为余作枯松孙枝石间老柏谢以长句","f":"词","c":["东斋归自浣花里，访我弄泉惠山趾。","随身万里只孤舟，一簪不曾著行李。","忽拈远物出袖中，乃是孔明庙前古柏阆州松。","径从平地便起立，上穿屋瓦到青穹。","老蛟脱鳞乾见骨，厥孙碧丝作须发。","石间霜皮二千尺，石似孤根根似石。","硬根瘦干未要论，叶间犹带汉唐春。","岁久亦无苔藓痕，只有雪山之雪玉垒云。","却收松柏半天里，几上捲来一张纸。"]},{"t":"胡季亨赠集句古风效其体奉酬","f":"五言古诗","c":["秋气集南涧，清风来故人。","遗我一端绮，桃李不成春。","大句斡元造，高词媲皇坟。","百衲收寸锦，一字买堪贫。","苦恨邻里间，良觌渺无因。","今日是何朝，始闻扣柴荆。","黄菊有佳色，寒水各依痕。","且共欢此饮，重与细论文。","何以报佳惠，山中有白云。"]},{"t":"胡英彦得欧阳公二帖盖训其子仲纯叔弼之语其一公自书之其一东坡书之英彦刻石以遗朋友吾叔父春卿得一本有诗谢英彦和焉万里用其韵以简英彦","f":"五言古诗","c":["圣处眇安在，谈者一何易。","注瓦矜细巧，岑鼎丧良贵。","群儿有新舌，六学无故意。","向来孟韩息，不有欧苏继。","庸知后死者，未渠乡愿弃。","同时鸱鸦噪，并起爪觜利。","两公察膏肓，与世作姜桂。","挟山初作难，破竹忽乘势。","双明日配月，再立仁与义。","我有香一瓣，恨不生并世。","厥今圣域里，澹叟真守器。","怪来兰玉秀，渠以清白遗。","当家有学林，满腹惟典记。","人间市井言，眼底寇雠视。","独于两公帖，费此半生喜。","麝煤叩山骨，卧听丁丁美。","令我竹林老，亦复拜嘉惠。","敢云赓绝唱，颇欲与兹事。","朝来窗几爽，尽室问何瑞。","宝帖更新诗，小子汝其志。"]},{"t":"荔枝歌","f":"七言古诗","c":["粤犬吠雪非差事，粤人语冰夏虫似。","北人冰雪作生涯，冰雪一窖活一家。","帝城六月日卓午，市人如炊汗如雨。","卖冰一声隔水来，行人未吃心眼开。","甘霜甜雪如压蔗，年年窨子南山下。","去年藏冰减工夫，山鬼失守嬉西湖。","北风一夜动地恶，尽吹北冰作南雹。","飞来岭外荔枝梢，绛衣朱裳红锦包。","三危露珠冻寒泚，火伞烧林不成水。","北人藏冰天夺之，却与南人销暑气。"]},{"t":"贺必远叔四月八日洗儿","f":"七言古诗","c":["年年四月初八日，水沉汤浴黄金佛。","今年大阮当此时，真珠水洗白玉儿。","吾家英杰相间起，胄出关西老夫子。","公家宣和中大夫，大江之西推名儒。","六十年来谁继渠，愿儿长成读祖书，再起门户光乡闾。"]},{"t":"贺吉州李守腊雪","f":"词","c":["仁侯妙手作庐陵，民歌敏惠如神明。","歌声动天天降瑞，一夜幻出琼瑶城。","丽谯一新玉楼观，郡治别起银设厅。","晓上青原台上望，千门万户皆水晶。","八邑山川一千里，尽种琪树玑为英。","幕僚秉烛争入贺，老夫抱病独僵卧。","寄言贺客此未奇，来年玉粒滑流匙。","万艘真珠贡京师，老夫已草周颂丰年诗。"]},{"t":"贺张功父寺丞新长凤雏","f":"七言律诗","c":["念君只欠一英雏，万事今君足也无。","想见碧梧森翠竹，敢嘲老蚌出明珠。","只今小德转春鸟，后日熊儿捉蹇驴。","自古相门长出相，烟楼一撞莫教输。"]},{"t":"贺胡守寺正祷雪响应","f":"七言古诗","c":["庐陵新事一奇绝，老农七年不识雪。","史君领取六花来，一夜九天开玉阙。","万家铸作银楼台，千峰琢出琼崔嵬。","频岁魃儿祟䆉稏，来秋云子如芋魁。","老夫与雪亦久别，滕六参侬求普说。","为渠拈此一瓣香，今身胡姓前身黄。","只愁颍川归庙堂，不愁寰宇无丰穰。","东阁官梅应解语，绿毛么凤仍能舞。","合词再拜寿史君，满为天花中玉醑。"]},{"t":"赴调宿白沙渡族叔文远携酒追送走笔取别","f":"七言律诗","c":["扁舟斜缆白沙虚，欲行未发小踟蹰。","吾家子云来得得，为携碧酒买白鱼。","谊风多年冷似铁，非公其谁主风月。","尊前醉倒定不嗔，同来多半个中人。"]},{"t":"送丁卿季吏部赴召","f":"七言古诗","c":["吾州史君五十年，不曾召节来日边。","老夫送人作太守，不曾送人上九天。","玉皇去年选丁宽，遣来螺浦苏茕鳏。","玉皇今年唤渠还，州民遮道不得前。","文儒佳政万口传，近世能吏了不关。","道渠岂弟父母然，凛如冰霜照人寒。","道渠明断神一般，秋毫不扰田里安。","一州天下孰后先，要渠笔橐侍甘泉。","尚书履声再接连，更进一步百尺竿。","紫枢黄閤半武间，梅花满枝雪满山。","雪花能舞梅能言，满饯史君金玉船。"]},{"t":"送子上弟之石井","f":"五言古诗","c":["我生苦终鲜，四海皆弟兄。","四海尚如许，而况吾宗盟。","君年甫弱冠，已有俊异声。","作赋拟三都，著论追过秦。","平生一瓣香，何曾举似人。","子上与济翁，真若吾同生。","我穷无人共，二子慰眼明。","济翁往荆州，君作石井行。","一老便落莫，有话从谁评。","怀哉勿重陈，呼酒且细倾。"]},{"t":"送子上弟赴郴州史君罗达甫寺正之招","f":"七言古诗","c":["郴山奇变水清写，郴江幸绕郴山下。","韩秦妙语久绝弦，谁煎凤觜续此篇。","君章词客山水主，云锦聘君君好赴。","为寻两公旧游处，得句寄侬侬不妒。","休道郴阳和雁无，也曾避雪罗浮去。"]},{"t":"送分宁主簿罗宏材秩满入京","f":"七言古诗","c":["要知诗客参江西，政似禅客参曹溪。","不到南华与脩水，于何传法更传衣。","吾家亲党子罗子，只今四海习凿齿。","花红玉白几百篇，塞破锦囊脱无底。","三年簿领脩水涯，夜半亲传双井芽。","定知诵向百僚上，不道长江与落霞。"]},{"t":"送王子林节推之官融水","f":"七言古诗","c":["桂岭梅花欲争发，融水幕宾来访别。","可怜疋马犯霜风，吟遍梅花更吟雪。","我如病蚕已三眠，作茧不就黏壁乾。","君如云表秋健鹘，政好抟扶整羽翰。","中书落笔看给札，归时过我聊投辖。"]},{"t":"送王子林节推归融州","f":"词","c":["吾州佳士子王子，深入黄茅作从事。","捧檄还家侍老亲，端能过我诵近文。","问渠鹗表几张纸，笑道孤寒那得此。","老夫已把钓月竿，安能为子插羽翰。","似闻融水新二天，外台使星俱好贤。","愿子西去早著鞭，归来荐墨满袖犹未乾。"]},{"t":"送王长文赴上庠","f":"七言古诗","c":["吾乡前辈王南宾，读书万卷笔有神。","屡登天府献和璞，玉工过眼珉夺真。","祇今有孙又奇绝，踏雪携书诣金阙。","玉皇书院璧水中，赐子半窗桃玉虫。","端能健笔追乃祖，斗薮寸心写千古。","广寒掇取第一枝，早为双亲开两眉。"]},{"t":"送王监簿民瞻南归","f":"七言古诗","c":["潮头打云云不留，月波泼窗窗欲流。","夜寒报晴岂待晓，天公端为卢溪老。","卢溪在山不知年，卢溪出山即日还。","黄纸苦催得高卧，青霞成癖谁能那。","诏谓先生式国人，掉头已复烟林深。","路旁莫作两疏看，老儒不用橐中金。"]},{"t":"送左元规三诣太常","f":"七言律诗","c":["晋侯三驾楚莫争，薛侯三箭天山平。","江西今代再丘明，亲到杏坛授麟经。","笔阵独扫万人军，两魁槐花再荐名。","来年兰省与集英，三元不数冯家京。"]},{"t":"送永新杜宰解印还朝","f":"七言古诗","c":["去年摘山初弄兵，永新县前戈剑腥。","杜侯不持一寸铁，闭阁坚卧民不惊。","军前米作山谷聚，木牛流马安用许。","但令绿林无点尘，何须烂额画麒麟。","紫皇急才宵不寐，斯人合著班行里。","速骑匹马谒明光，夜来溪风吹玉霜。"]},{"t":"送刘子思往衡湘","f":"词","c":["浩斋先生第一孙，秀峰后进第一人。","向来著论三分国，唤起阿瞒戮奸魄。","有司手持金粟尺，越罗蜀锦遗道侧。","洞庭昨夜起霜风，翩然欲登石廪与祝融。","归来定有惊人句，肯寄江西道院翁。"]},{"t":"送刘生谈命","f":"词","c":["学兵先学策，谈命先谈格。","君看前辈富贵人，岂与寒士校日辰。","星家者流有刘子，进人退人若翻水。","谈何容易验他年，却是直言差可喜。"]},{"t":"送刘茂材主簿之官理定","f":"词","c":["陆机二十作文赋，刘群二十诣太常。","桃花浪险阿香怒，点破龙额归西江。","平津六十策第一，刘君五十赐袍笏。","一官初入八桂林，官无早晚在努力。","大帅大漕两德星，总是青原旧使君。","若问公堂阶下吏，便是三瑞堂前门生前进士。"]},{"t":"送刘觉之归蜀","f":"七言古诗","c":["大江东西湖南北，鹄袍学子森如竹。","何人开口不伊川，阿谁初道此水源。","清纯先生刘夫子，冷笑俗儒钻故纸。","梦中亲见大小程，为渠刺船入洙泗。","嗟我结发从先生，日日看子趋鲤庭。","先生命子却从我，小窗短檠共灯火。","陋巷柴扉共寒饿，安知头上天几大。","子今行李寄大宁，翩然束书游帝城。","袖中一卷经济策，天关九虎叫不应。","朝来忽见毛生刺，看来看去惊且喜。","风花聚散三十年，何许飞堕老眼前。","相逢几日又相别，珍重两字不忍说。","我有故山江之西，祗遣思归不遣归。","赠行聊借退之诗，石头城下一杯酒，便是此生长别离。"]},{"t":"送吉守赵山父移广东提刑","f":"七言古诗","c":["越台海山清更雄，曲江间出曲江公。","宪台师表光且耿，濂溪留下濂溪井。","赵侯端是宋间平，妙年策名千佛经。","阳春有脚来江城，银汉乘槎移使星。","岭上梅花莫迟发，先遣北枝迎玉节。","寄声多贺帽子峰，今岁峰头有霜雪。"]},{"t":"送吉州太守胡平一寺正赴召","f":"七言古诗","c":["忆昔乾道游璧水，君为秀孝侬博士。","逮今嘉泰归青原，侬为州民君刺史。","人生离合风中云，白发相逢有几人。","与君相逢又相别，不待折柳眉先颦。","如君岂弟民父母，春风风人夏雨雨。","忽然一夜飞秋霜，惊杀雁鹜兼豺狼。","政声无翼到天上，玉皇诏君登庙廊。","郎星卿月小借路，金华玉堂即高步。","中兴贤关育凤麟，向来未有秉鸿钧。","祗今丞相破荒了，第一衣钵当传君。"]},{"t":"送吉州通判赵德辉上印赴阙","f":"词","c":["太守九秋霜，通守三春风。","太守镜照胆，通守渊涵空。","古来人才在寒士，皇家人才在宗子。","君看二赵作庐陵，宽猛晦明两相济。","太守已乘八使车，通守合分五马符。","行看二赵俱法从，老夫别献中和颂。"]},{"t":"送吉州解魁左人杰诣太常","f":"七言古诗","c":["高皇一马化龙日，临轩策士谁第一。","玉山山下汪端明，年财十八第一人。","圣上来年集英殿，黄伞中央横玉案。","何人再续老尚书，禾水左家千里驹。","春秋三传贮胸臆，买纸待传晁董策。","君才盍与汪相先，君年更少汪两年。"]},{"t":"送安成罗茂忠","f":"七言古诗","c":["书台佳士君章孙，句法来自西溪门。","向来家住金谷园，珊瑚四尺蜡作薪。","床头黄金已散尽，买书却铸文章印。","印成一字不疗饥，仰天大笑还哦诗。","诸老先生总参遍，只欠一瞻晦翁面。","晦翁今已作贵人，君从何许去问津。","劝君努力战今举，来年拜渠为座主。"]},{"t":"送庆基叔往上犹二绝 其一","f":"七言绝句","c":["南溪不住住犹溪，别驾贤孙法掾儿。","莫以甘棠南国荫，便忘萱草北堂诗。"]},{"t":"送西昌大夫赵嘉言上印赴阙","f":"词","c":["西昌难作自古传，卓令赵令不作难。","二令来时民顿宽，二令去日官馀钱。","从来美政人难继，二君双美今谁似。","卓令已作中都官，赵令也合即缀卓令班。"]},{"t":"送别吕令圣与","f":"七言古诗","c":["一门三相千子孙，后有公家前诸袁。","有治国谱无县谱，种爱在堂铭在门。","谁能不徼鬻爵恩，民乃不识田亩钱。","姓名堕在诸公口，去去云霄稳著鞭。","三年为寮无间然，公行何得搀吾先。","取别当愁今更喜，定知同醉西湖莲。"]},{"t":"送别吴帅","f":"七言古诗","c":["我公四海不数人，小烦江西作好春。","落霞秋水只似旧，如何入笔事事新。","即今诸公方衮衮，一老不应闲里顿。","政缘山水太殷勤，日夜叫阍乞此身。","二天去人忽觉远，两地起公端不免。","苍生未要怨东山，未必东山当此怨。"]},{"t":"送医家孟宗良汉卿","f":"七言古诗","c":["医家者流多卢人，亦如许靖浪得名。","有眼何曾识内经，有手何曾赦方兄。","一丸足可杀一命，却道良医逢死病。","荆溪此辈端不稀，向来吾儿命如丝。","孟君谈笑能起死，吾儿更生一弹指。","我今挂帆上江西，君来送我别荆溪。","赠别只有七字诗，千万珍重慰相思。","它年荆溪说神医，非吾孟君更阿谁，仓公华佗何必奇。"]},{"t":"送张倅","f":"七言古诗","c":["山西劲气何曾歇，秦汉迄今几奇杰。","张公长身须鬓苍，斜飞不入鹓鹭行。","狂卒叫欢民震扰，不劳谈笑斯须了。","皇上方披舆地图，烦公赤手系单于。","捕逐虎豹公则老，坐运筹策公尚少。"]},{"t":"送李君亮大著出守眉州","f":"词","c":["老夫丐外自缘老，复闻建邺江山好。","不应夫子亦翩然，一柁江花更江草。","黄金宫阙三神山，蓬莱五云霄汉间。","仍将弱水三万里，隔断尘世无往还。","西州名胜李太史，岂徒国士天下士。","玉皇催入道山堂，知费台家几黄纸。","似闻郎罢对薰风，忽思锦江荔枝红。","人生奉亲行乐耳，金印斗大何关侬。","峨眉山月却入手，影落庭闱一杯酒。","蚤赋中和乐职宣布诗，会看夔龙集凤池。"]},{"t":"送李童子西归","f":"七言古诗","c":["江西李家童子郎，腹载五车干玉皇。","选德殿后春昼长，天子呼来傍御床。","口角诵书如布谷，眼光骨法俱冰玉。","紫绡轻衫发锦束，万人回头看不足。","莫言幼慧长不奇，杨文公与晏临淄。","老翁笞儿也太痴，欲鞭辕下追霜蹄。","六岁取官曲肱似，春风昼绣归吾里。","生子当如李童子，至如吾儿豚犬耳。"]},{"t":"送邹元升归安福","f":"七言古诗","c":["我昔见子卢溪南，炯如玉雪照晴岚。","子今访我南溪北，凛如騄骥成骨骼。","袖中文字细作行，读来病眼生寒光。","尖新句子入时样，故应破阵翰墨场。","春风春雨春山路，喜子能来愁子去。","故人一别二十年，且对青灯夜深语。"]},{"t":"送周起宗经干赴桂林帅幕","f":"七言古诗","c":["乃翁昔梦飞入月，东字分明篆银阙。","明朝占梦占者云，一甲八人更何说。","绍兴大对奏集英，天风吹下胪传声。","作者七人拜恩了，乃翁甲科第八名。","十年一武可凤沼，邵阳别驾今宿草。","子今端能读父书，伏犀美髯一似渠。","当时父执今左相，鸿钧播作幕府梧。","问天一雪乃翁屈，早入鹓行缀簪笏。"]},{"t":"送奔医时亨往攸县省觐","f":"七言律诗","c":["雪恰来时子恰行，白云飞边双眼明。","阿母几年不相见，阿兄唤渠来作伴。","探囊半粒黄金丹，湘南小儿开病颜。","江西两奔留不住，并被湘南夺将去。"]},{"t":"送抹利花与庆长","f":"七言律诗","c":["江梅去去木犀晚，萱草石榴刺人眼。","抹利独立幽更佳，龙涎避香雪避花。","朝来无热夜凉甚，急遣山童问花信。","一枝带雨折来归，走送诗人觅好诗。"]},{"t":"送林谦之司业出为桂路提刑","f":"五言古诗","c":["雨眠起宵坐，搔首偶不欣。","孤念元无感，怀我同社人。","昨日林先生，抱经出成均。","初闻为渠喜，忽悟谁我亲。","缅然记宿昔，夜款水际门。","微月耿秋寂，幽蛩慨凉新。","论诗煮豆粥，粥熟天已晨。","先生补天手，万象焉能春。","若非千载仰，却要今世珍。","圣门旧传业，不在先生身。","雪前何有松，燬中谅非珉。","论思尺有咫，决去曾逡巡。","谁言我无耳，老矣未有闻。","先生又舍我，离别尚足云。","桂山玉笋立，桂水罗带纹。","得句能寄似，不须持岭云。"]},{"t":"送罗必高赴省","f":"词","c":["印山先生罗天文，一卷周雅遗子孙。","一门三世六七人，月中桂枝斫到根。","近来书种将绝却，两度秋天虚一鹗。","今年有孙康鼎来，问天还我北斗魁。","印山草木也驩喜，印山风云有生气。","君不见普州衣钵付仇香，仇香衣钵付此郎。","年未三十笔力强，百斛龙鼎一笔扛。","殿前春风更努力，莫放别人居第一。"]},{"t":"送罗正夫主簿之官馀干","f":"七言古诗","c":["君家人物已数世，后有秘丞前给事。","近来复见乡先生，武冈使君五经笥。","君才自是一世英，珠玉照乘仍连城。","妙年已号万人敌，强仕初登千佛名。","番君小屈习凿齿，且与刺头簿书底。","即看给札试兰台，飞上木天校文字。"]},{"t":"送罗仲仁试艺南宫","f":"词","c":["绍兴廉吏谁第一，君家郎罢真无匹。","腰缠墨绶不请钱，妻啼儿号穷刮骨。","清无人知有天知，四囝三个攀桂枝。","不应一个独见遗，今秋君与一鹗飞。","君不见吾州状元晚得意，董公五十有三岁。","君今加渠更三年，春风射策君勉旃。"]},{"t":"送罗宣卿主簿之官巴陵","f":"七言古诗","c":["印孙三子十一孙，六人擢桂两特恩。","惟君有子又擢桂，父子仇香仍一门。","君今初泛洞庭柂，湖水黏天天更大。","请君先上岳阳楼，送眼君山最上头。","将诗写取一湖秋，将秋寄来销我愁，为君酒船卷拍浮。"]},{"t":"送姜夔尧章谒石湖先生","f":"七言古诗","c":["钓璜英气横白蜺，欬唾珠玉皆新诗。","江山愁诉莺为泣，鬼神露索天泄机。","彭蠡波心弄明月，诗星入肠肺肝裂。","吐作春风百种花，吹散濒湖数峰雪。","青鞋布袜软红尘，千诗只博一字贫。","吾友夷陵萧太守，逢人说君不离口。","袖诗东来谒老夫，惭无高价当璠玙。","翻然却买松江艇，径去苏州参石湖。"]},{"t":"送客夜归呈萧岳英县丞","f":"七言律诗","c":["并舍频过亦几曾，却因送客得同行。","风船逆水四十里，雪屋吹灯三二更。","老去病身禁底苦，向来危宦若为情。","天台香火侬当觅，且伴先生学养生。"]},{"t":"送施少才赴试南宫二首 其二","f":"五言律诗","c":["十日九奔命，同行半倦游。","出城愁不早，思子悔何由。","脚底已衡岳，眼中犹橘洲。","似嫌疏过子，吾过更谁尤。"]},{"t":"送胡圣闻入太学","f":"七言律诗","c":["春风吹开孝廉船，撞星犯斗上九天。","夜书细字灯前月，朝茹寒齑瓮中雪。","何蕃省亲间一归，陆畅擢第各一时。","此行归来上亲寿，桂枝满把香满袖。"]},{"t":"送胡季永赴漕试","f":"七言古诗","c":["兔目著花官样黄，冰轮飘子秋风香。","谁骑瘦马踏词场，澹翁庭阶玉雪郎。","天于贤佞真不省，不应阿翁有阿永。","景升儿子漫谷量，未识一丁惟啖饼。","阿永胸中几许书，石渠奄有仍更馀。","毛锥半点不籧篨，羽镞一脱无犀渠。","当家衣钵更谁付，锁厅小借梯云路。","澹翁严冷纵不嬉，归来膝上安文度。"]},{"t":"送药者陈国器","f":"词","c":["窦宪一举空朔野，曹霸一笔空凡马。","吾乡药者有陈生，一丸洗空万药者。","庸医皆笑道旁莎，陈生拈出便是玉山禾。","庸医皆笑涧下水，陈生酌来便是上池底。","也只不离神农书，书外别得一亡珠。","也只不出歧伯论，论外别得舌一寸。","旧遭痔疾恼杀侬，新遭淋疾与合纵。","恰如住在圃田国，晋楚腹背来夹攻。","陈生赠我玉菌子，乃是华阳洞中乖龙耳。","陈生赠我绀叶纱，乃是金鸦脚底扶桑花。","汲泉亲手煮蟹眼，一浣枯肠如浣沙。","平生旧疾蝉壳退，秋风吹落青天外。","更传枕中鸿宝方，戒勿浪传泄天藏。","君不见回岩仙客逢贫子，指石成金吾济尔。","贫子再拜不要金，祇觅指头吾自指。"]},{"t":"送赵文友知府谒告省亲","f":"七言古诗","c":["邦人宁食三斗葱，莫逢向来虿尾公。","邦人宁卧文江路，莫放今侯霅川去。","今侯个是隆准孙，蚤排月胁斸桂根。","所至与民作阳春，帝遣来活庐陵人。","是时虿尾正摇毒，邦人生愁总鱼肉。","今侯下车荫未移，春台载民爷与儿。","鸠鸣雀乳一千里，鸱枭半声不到耳。","今侯冰檗清到底，一粒不嚼庐陵米。","一芽只瀹青原水，玉皇知渠是廉吏。","如何尊公小愆和，何恙靡已应无它。","侯望白雪泪双落，弃印谒告归侍药。","尊公喜归即日安，一见綵服还加餐。","玉皇诏侯结丝屦，径上金门簉鹓鹭。","借令小缓作尚书，也合追趋赵工部。"]},{"t":"送赵吉州判院器之移利路提刑","f":"七言古诗","c":["赵侯迈往隆准孙，未年五十专三城。","千里秋豪无遁情，两眼洞照如秋鹰。","何须奋髯走百吏，棠阴昼寂清如水。","年年州人吃贱米，侲子踏歌冻黎喜。","去冬苦暖未有梅，使君一笑梅花开。","夜吹平地一尺雪，留下丰年今岁回。","使星移照天西去，白鹭青原遮不住。","即随丹诏归握兰，遂持紫橐甘泉班。"]},{"t":"送赵判官端国趁班改秩","f":"七言古诗","c":["金陵一见恍如梦，君为过客侬相送。","庐陵再见春欲残，君来入幕侬挂冠。","是时猛虎初出境，赤子凛如兵在颈。","帝选良牧苏疲民，前赵后丁廉且仁。","更得君作幕下宾，四年千里日日春。","与君相逢又相别，人生聚散如霜叶。","桂林一枝三十年，诸公交章荐遗贤。","去揖侍郎趁立班，端能别我南溪边。","为我一醉春风前，看君抟风上九天。"]},{"t":"送赵英仲司户","f":"七言古诗","c":["绍兴人物赵户部，身作长城护瓜步。","佛狸送死缘有人，猿臂不侯得非数。","只今曾孙户掾公，吏能官政有祖风。","南山可摇判难夺，东海不冤阴有功。","吾州上了本曹印，谒帝明光当得觐。","秋风正紧送抟扶，九万程涂人莫问。"]},{"t":"送项圣与诣太常","f":"七言古诗","c":["卢溪书院一番新，千里学子来如云。","天教书院名日起，速化先从主人始。","主人主盟为阿谁，楚汉名家今项斯。","胸中五车载书卷，笔端三峡倾冰砚。","鲁秉周礼说一经，有司把烛题秋荐。","鹄袍诣阙柳袍归，来年书院更光辉。"]},{"t":"送聂士友通判上印入朝","f":"七言古诗","c":["君家枢相扶天极，气凌霜雪忠贯日。","史家有笔叹无人，今有此人无此笔。","君侯名家千里驹，拱璧盈尺径寸珠。","合登清庙荐六瑚，合参豹尾随属车。","胡为小缓云间翮，朅来螺浦分风月。","开轩不与俗客谈，明月清风入牙颊。","只今上印去朝天，春风玉笋催缀班。","相门有相君勉旃，凌烟再写进贤冠。"]},{"t":"送谈命周从龙","f":"七言绝句","c":["周子囊萤初学儒，学儒不就学星书。","五丸玉李无逃处，折得今年锥也无。"]},{"t":"送钱文季佥判","f":"七言古诗","c":["东海珠胎清庙珍，璧水秀孝第一人。","胡为俯首莲泛渌，如有用我试治民。","古来幕中要婉画，君乃不肯作此客。","囊箧细碎吾不能，玉壶清冰朱丝直。","梅花雪片迎新年，送君抟风上九天。","凤池鸡树只咫尺，致君尧舜更努力。"]},{"t":"送族弟子西赴省","f":"七言律诗","c":["吾家词伯达斋翁，阿季文名有父风。","笔阵千军能独扫，马群万古洗来空。","嗟予还笏归林下，看子乘船入月中。","淡墨榜头先快睹，泥金帖子不须封。"]},{"t":"送清江王守赴召","f":"词","c":["世言富贵易得家世难，有贤父兄子弟未渠贤。","君不见祖孙父子兄与弟，根兰树玉枝亦桂。","魏晋以来谁子家，只数江淮一王氏。","世言淮水若绝渠不昌，不知淮水有绝渠更长。","请看南朝到吾宋，中间人物无阙空。","有曾有旦继茂弘，即今紫枢继子明。","昔才一人今三人，后者玉振前金声。","阿枢更有金玉阿兄子，两有刚方兼岂弟。","清江五马来自东，三年一日一春风。","又闻一节唤归去，父老拦街遮不住。","唤它父老且细听，朝家也要好公卿。","父老莫与朝家争，打鼓发船催速行。"]},{"t":"送萧仲和往长沙见张钦夫","f":"七言古诗","c":["萧家伯氏难为兄，萧家仲氏难为弟。","御史子孙今有谁，眼中乃见此二士。","阿兄采兰寿梅堂，阿弟束书参蜀张。","圣门九钥天为守，玉匙密付蜀张手。","子到长沙渠问侬，为言真成一老翁。","功名妄念雪销了，只爱吟诗恼鱼鸟。","子归好在中秋前，看子新年胜故年。"]},{"t":"送黄几先司户","f":"五言古诗","c":["吾友黄编修，用不究其挟。","有子传父书，潜心泣麟业。","胸中石渠剩，笔底秋鹰捷。","蟾兔赠一枝，衣钵续四叶。","不应千里来，乃欲一揖别。","恰当新酒熟，幸与故人接。","细酌且短檠，软语更长铗。","去去谒九扉，天路看高蹑。"]},{"t":"送黄岩老通判全州","f":"词","c":["潇湘之山可当一枝笔，潇湘之水可充一砚滴。","白石得官斑竹林，天锡笔砚供醉吟。","好将湘山点湘水，洒满青天一张纸。","台家旁搜清庙珍，奇珍堕在湘水滨。","乌衣枢相今水镜，手提一道人材柄。","外台况复有三贤，看即吹嘘送上天。","归来肯过诚斋里，分似锦囊新句子。"]},{"t":"送彭元忠县丞北归","f":"词","c":["君从循州来，却向饶州去。","拍天海浪拂日峰，琼尺裁成锦机句。","学诗初学陈后山，霜皮脱尽山骨寒。","近来别具一只眼，要踏唐人最上关。","三春弱柳三秋月，半溪清冰半峰雪。","只今六月无此物，君能唤渠来入笔。","恰则新莺百啭声，忽有寒蛩终夜鸣。","潇湘故人江汉客，为君一夜头尽白。","我欠天公诗债多，霜髭撚尽未偿它。","君怀玉盘金叵罗，合骑天驷超天河。","如何也铸一大错，自古诗人多命薄。","黄茅起烟如黄沙，瘴母照永曼陀花。","广东之游乐复乐，劝君不如早还家。"]},{"t":"送曾无逸入为掌故","f":"七言古诗","c":["吉文江水走玉虹，我家水西君水东。","有时相思即命驾，连床夜两听松风。","中间薄宦各分散，南飞鴐鹅北飞雁。","朝来驿骑打谯门，有客有客来相见。","闻君携家入帝京，椎鼓发船天上行。","也能枉辙九十里，来访江西道院僧。","诗家两仙宿台省，红药苍苔紫薇影。","若问山僧作么生，日晏莺啼眠不醒。"]},{"t":"送蔡定夫提举正字使广东","f":"七言古诗","c":["国朝以来妙人物，近世独数乾道年。","后皇乃武再开辟，欲倾东海洗乾坤。","九渊探珠岩采璞，天地为纲罝群贤。","玉堂金铉贮稷契，蓬山璧水俱崔班。","追还庆历元祐初，突过贞观开元前。","麟台正字蔡夫子，乃祖元是四谏官。","风流文采已碧梧，忠义慷慨仍青毡。","折槛旧痕故无恙，后皇是日动龙颜。","严霜烈日照鹓鹭，一身似叶飘淮堧。","柴门僵卧三腊雪，鱼釜仅续一线烟。","后皇九重念五岭，生愁雨露南方乾。","诏谓正字当居中，肯为朕行绥百蛮。","梅花迎笑锦囊古，南斗退避文星寒。","动摇山岳细事耳，约束海若收波澜。","坐令百姓万里外，堕在二陕三辅间。","槟榔红时芝泥紫，归来径著侍臣冠。","我家江西更西处，白鹭洲对青原山。","公归肯访老翁否，酤酒满眼未必然，青刍白饭聊随缘。"]},{"t":"送韩漕华文移节江东","f":"七言古诗","c":["公家文公天斗星，可双孟氏再六经。","姓名不上凌烟去，只与日月争光明。","君家魏国天一柱，拄天无倾日无雾。","唯天唯尧唯永昭，皋旦以还俱避路。","只今百年三百年，文献衣被芝与兰。","华文使者典刑存，一生流坎晚乃骞。","台家拔士兼人门，如君两有今谁先。","德星才照翼轸地，寒士驩呼细民喜。","钟山石城何物神，夺与东民天不嗔。","寄语东民也未稳，渠是鸾台凤阁人。"]},{"t":"送蜀士张之源二子维焘中童子科西归","f":"词","c":["岷山玉样清，岷水眼样明。","风流文彩故应尔，又见张家双骥子。","小儿八岁骨未成，诵书新作鸾鹤声。","大儿十二气已老，觅句谈经人绝倒。","豫章七年人得知，駃騠三日世便奇。","天生异材能几许，更饱风霜也未迟。"]},{"t":"送戴良辅药者归城郛 其一","f":"词","c":["君欲问淋疾，便是法外刑。","刲剔备百毒，更以虐焰烹。","玉皇夜半敕六丁，押差戴君为药丞。","倒囊刺手探玉札，一洗愁肺冰雪清。"]},{"t":"郡中送春盘","f":"七言古诗","c":["饼如茧纸不可风，菜如缥茸劣可缝。","韭芽捲黄苣舒紫，芦菔削冰寒脱齿。","卧沙压玉割红香，部署五珍访诗肠。","野人未见新历日，忽得春盘还太息。","新年五十奈老何，霜须看镜几许多。","曲生嗔人不解事，且为春盘作春醉。"]},{"t":"郡治燕堂庭中梅花","f":"七言古诗","c":["林中梅花如隐士，只多野气无尘气。","庭中梅花如贵人，也无野气也无尘。","不疏不密随宜了，旋落旋开无不好。","珠帘遣风细为吹，画檐护霜寒更微。","诗翁绕阶未得句，先送诗材与翁语。","有酒如渑谁伴翁，玉雪对饮惟渠侬。","翁欲还家即明发，更为梅兄留一月。"]},{"t":"重九日雨仍菊花未开用辘轳体","f":"七言律诗","c":["良辰巧与赏心违，四者能并自古稀。","恰则今年重九日，也无黄菊两三枝。","闭门幸免吹乌帽，有酒何须望白衣。","政坐满城风雨句，平生不喜老潘诗。"]},{"t":"重九后二日同徐克章登万花川谷月下传觞","f":"七言古诗","c":["老夫渴急月更急，酒落杯中月先入。","领取青天并入来，和月和天都蘸湿。","天既爱酒自古传，月不解饮真浪言。","举杯将月一口吞，举头见月犹在天。","老夫大笑问客道，月是一团还两团。","酒入诗肠风火发，月入诗肠冰雪泼。","一杯未尽诗已成，诵诗向天天亦惊。","焉知万古一骸骨，酌酒更吞一团月。"]},{"t":"重九前五日再游翟园","f":"七言古诗","c":["翟园不到才几日，寒梢冷叶秋萧瑟。","只有黄花数点明，上照青松下苍石。","记得春头来此嬉，梅花太瘦杏花肥。","巷南巷北皆春色，恰似吾人年少时。","忽怪翟园如许老，园应笑我衰容早。","来岁春光更一来，我衰依旧园还少。"]},{"t":"重九前四日昼睡独觉","f":"七言律诗","c":["睡思初酣过午强，起来四顾已斜阳。","添糊窗隔无风气，旋晒衣裘有日香。","旧雨不来从草绿，新丰独酌又花黄。","去年重九穷忙过，可遣今年更作忙。"]},{"t":"闻一二故人相继而逝感叹书怀","f":"五言古诗","c":["故人昔同朝，与游每甚欢。","岂缘势利合，相得文字间。","有顷各补外，不见今六年。","我来荆溪上，敲榜索租钱。","故人复双入，飞上青云端。","我虽世味澹，羡心能恝然。","忽传故人去，得书墨未乾。","又传故人亡，惊悼摧肺肝。","鼎贵良独佳，安贫未遽贤。","向以我易彼，安知不作难。","今以彼易我，试问谁当悭。","如何捐此躯，必要博好官。","顾谓妻与子，官满当归田。","我贱汝勿羞，我贫汝勿叹。","从汝丐我身，百年庶团栾。","妻子笑答我，脩短未易言。","富贵必速殒，郭令当夭残。","贫贱果永算，颜子寿必延。","我复答渠道，薄命我自怜。","我福肯如郭，我德敢望颜。","造物本啬与，我乃多取旃。","借令彼不怒，退省我独安。","汝言自有理，我意不可还。"]},{"t":"除夕前一日归舟夜泊曲涡市宿治平寺","f":"七言古诗","c":["江宽风紧折绵寒，滩多岸少上水船。","市何曾远船不近，意已先到灯明边。","夜投古寺冲泥入，湿薪烧作虫声泣。","冷窗冻笔更成眠，也胜疏篷仰见天。","市人歌呼作时节，诗人两膝高于颊。","还家儿女问何如，明日此怀犹忍说。"]},{"t":"食蛤蜊米脯羹","f":"七言律诗","c":["倾来百颗恰盈奁，剥作杯羹未属厌。","莫遣下盐伤正味，不曾著蜜若为甜。","雪揩玉质全身瑩，金缘冰钿半缕纤。","更淅香粳轻糁却，发挥风韵十分添。"]},{"t":"食蒸饼作","f":"七言律诗","c":["何家笼饼须十字，萧家炊饼须四破。","老夫饥来不可那，只要鹘崙吞一个。","诗人一腹大于蝉，饥饱翻手覆手间。","须臾放箸付一莞，急唤龙团分蟹眼。"]},{"t":"食鹧鸪","f":"七言律诗","c":["江南厌听鹧鸪曲，岭南初尝鹧鸪肉。","年年细雨落花春，钩辀格磔恼杀人。","竹鸡泥滑报行客，鹧鸪更道行不得。","方兄百辈买一只，可惜羽衣锦狼藉。"]},{"t":"题龟山塔前一首唐律后一首进退格 其二","f":"七言律诗","c":["旧岁新年来往频，孤标数面便多情。","独将白发三千丈，上到瑶台十二层。","万里海风吹不动，半轮淮月为谁明。","东坡旧迹无寻处，试问龛中锦帽僧。"]},{"t":"夏日小饮分题得菱用辘轳体","f":"七言律诗","c":["不是齐堂觳觫生，如何双抵独峥嵘。","犀中忽有红尖角，天上也无甜底冰。","只爱衣裳桃杏浅，谁知肌骨雪霜明。","酒徒苦问渠名姓，无姓无名字子陵。"]},{"t":"夏夜玩月","f":"五言古诗","c":["仰头月在天，照我影在地。","我行影亦行，我止影亦止。","不知我与影，为一定为二。","月能写我影，自写却何似。","偶然步溪旁，月却在溪里。","上下两轮月，若个是真底。","唯复水是天，唯复天是水。"]},{"t":"夏夜诚斋望月","f":"七言律诗","c":["山居道是没空庭，不道诚斋敞更明。","万里青天元是水，半轮皎月忽成冰。","只今夏热已如此，若到秋高何似生。","玉兔素娥兼老子，三家一样雪鬅鬙。"]},{"t":"悯旱","f":"七言古诗","c":["鸣鸠唤雨知唤晴，水车夜啼声彻明。","乖龙懒睡未渠醒，阿香推热呼不应。","下田半湿高全坼，幼秧欲焦老差碧。","书生所向便四壁，卖浆逢寒步逢棘。","还家浪作饱饭谋，买田三岁两无秋。","一门手指百二十，万斛量不尽穷愁。","小儿察我惨不乐，旋沽村酒聊相酌。","更哦子美醉时歌，焉知饿死填沟壑。","水车哑哑止复作。"]},{"t":"挽郑恭老少卿","f":"五言律诗","c":["天不遗耆老，人谁尚典刑。","向来卿月白，无复史天青。","诗派回风雪，心源贝叶经。","故应书带草，和露泣康成。"]},{"t":"挽谢母安人胡氏","f":"五言律诗","c":["玉树仍双桂，金花不一书。","雪封青竹笋，雾失白藤舆。","天下谁无母，江西未有渠。","西峰半轮月，松槚政疏疏。"]},{"t":"斋房戏题","f":"七言古诗","c":["长瓶举我充自代，短檠留人为莫逆。","醉乡无日不瓜时，书囿何朝无菜色。","欲从举者便弹冠，回顾石交难割席。","子墨客卿善运筹，更问渠侬决去留。","墨卿转问子虚子，欲说还忘一笑休。"]},{"t":"晒衣","f":"七言绝句","c":["亭午晒衣晡褶衣，柳箱布襆自携归。","妻孥相笑还相问，赤脚苍头更阿谁。"]},{"t":"晓行山烟","f":"七言绝句","c":["晓烟横抹碧山隅，只在松梢疋练如。","作意行前寻一看，远浓近淡忽都无。"]},{"t":"晓行望云山","f":"七言绝句","c":["霁天欲晓未明间，满目奇峰总可观。","却有一峰忽然长，方知不动是真山。"]},{"t":"晓过新安江望紫阳山怀朱元晦","f":"七言绝句","c":["紫阳山下紫阳翁，今住闽山第几峰。","退院归来罢行脚，被他强占一江风。"]},{"t":"晓泊兰溪","f":"七言古诗","c":["金华山高九天半，夜雪装成珠玉案。","兰溪水清千顷强，朔风冻作琉璃釭。","日光雪光两相射，病眼看来忘南北。","恨身不如波上鸥，脚指为楫身为舟。","恨身不如沙上雁，芦花作家梅作伴。","折绵冰酒未是寒，晓寒真欲冰我肝。","急闭箬篷拥炉去，竹叶梨花十分注。"]},{"t":"晓经潘葑","f":"七言律诗","c":["油窗著雨光不湿，东风忽转西风急。","篷声萧萧河水涩，牵船不行人却立。","雨中篙师风堕笠，潘葑未到眼先入。","岸柳垂头向人揖，一时唤入诚斋集。"]},{"t":"晓看牡丹呈彭仲庄","f":"七言律诗","c":["牡丹新植旧来无，早起看花花更苏。","晴翠满空天政晓，暖红蒸雾汗成珠。","绝怜嫩日偏催老，犹喜轻寒为给扶。","来岁一株应百朵，只今紫笋绕根须。"]},{"t":"晓起","f":"七言绝句","c":["霜挟清寒冻杀人，袖中十指怯头巾。","金篦落地拾不得，却是穿窗晓日痕。"]},{"t":"晓登万花川谷看海棠二首 其一","f":"七言绝句","c":["夜雨朝晴花睡馀，海棠倾国万花无。","馆娃一样三千女，露滴燕脂洗面初。"]},{"t":"晓登小楼雾失南高峰塔","f":"五言古诗","c":["日日南高峰，知我登小楼。","笑回紫翠面，擎献新鲜秋。","独将诗魂去，恣绕月胁游。","得句寄与渠，月姊不敢搜。","绝顶珥琼笔，仰空书银钩。","今晨招不来，开窗得孤愁。","折简呼屏翳，能为追亡不。"]},{"t":"晓登水亭","f":"五言绝句","c":["露气仍荷气，秋风更晓风。","身兼水亭子，双堕玉壶中。"]},{"t":"晓登怀古堂","f":"五言律诗","c":["度暑过于岁，初凉别是天。","独穿秋露草，来看晓风莲。","病骨殊轻甚，幽襟一洒然。","不妨聊吏隐，何必更林泉。"]},{"t":"柴步滩","f":"五言古诗","c":["江阔水不聚，分为三五滩。","遂令客子舟，上滩一一难。","小沙已成洲，大洲已成山。","山有树百尺，树围屋数间。","水底复生洲，沙湿犹未乾。","从此洲愈多，安得水更宽。","忆从严陵归，水落不能湍。","拖以数童仆，折却十竹竿。","今兹过吾舟，念昔犹胆寒。"]},{"t":"海岸沙行","f":"七言古诗","c":["海滨半程沙上路，海风吹起成烟雾。","行人合眼不敢觑，一行一步愁一步。","步步沙痕没芒屦，不是不行行不去。","若为行到无沙处，宁逢石头齧足拇。","宁踏黄泥溅袍裤，海滨沙路莫再度。"]},{"t":"烛下和雪折梅","f":"七言律诗","c":["梅兄冲雪来相见，雪片满须仍满面。","一生梅瘦今却肥，是雪是梅浑不辨。","唤来灯下细看渠，不知真个有雪无。","只见玉颜流汗珠，汗珠满面滴到须。"]},{"t":"烛下瓶中江蜡二梅","f":"七言绝句","c":["江梅蜡梅同日折，白昼看来两清绝。","如何对立烛光中，只见江梅白于雪。"]},{"t":"烧香七言","f":"七言古诗","c":["琢瓷作鼎碧于水，削银为叶轻如纸。","不文不武火力匀，闭阁下帘风不起。","诗人自炷古龙涎，但令有香不见烟。","素馨忽开抹利拆，低处龙麝和沉檀。","平生饱识山林味，不奈此香殊妩媚。","呼儿急取烝木犀，却作书生真富贵。"]},{"t":"瓶中梅杏二花","f":"七言律诗","c":["梅花耿耿冰玉姿，杏花淡淡注燕脂。","两花相娇不相下，各向春风同索价。","折来双插一铜瓶，旋汲井花浇使醒。","红红白白看不足，更遣山童烧蜡烛。"]},{"t":"瓶中梅花长句","f":"七言古诗","c":["幽人蚤作月满阶，月随幽人登舫斋。","推门欲开犹未开，猛香排门扑我怀。","径从鼻孔上灌顶，拂拂吹尽发底埃。","恍然堕我众香国，欲问何祥无处觅。","冥搜一室一物无，瓶里一枝梅的皪。","平生为梅判断肠，何曾知渠有许香。","夜来偶忘挂南窗，贮此幽馥万斛强。","却忆去年西湖上，锦屏下瞰千青嶂。","谷深梅盛一万株，十顷雪花浮欲涨。","是时雨后初晴前，日光烘花香作烟。","政如新火炷博山，烝出沉水和龙涎。","醉登绝顶撼疏影，掇蕊餐花照冰井。","蜀人老张同舍郎，唤作谪仙侬笑领。","如今茅屋卧山村，更无载酒来叩门。","一尊孤斟懒论文，犹有梅花是故人。"]},{"t":"病中七夕","f":"七言律诗","c":["良辰美景底须来，苦恼如山正满怀。","蝉度清歌侑溪柳，花吹黄雪洒官槐。","新秋风物俱堪赏，久病心情自不佳。","说与儿童休乞巧，老夫守拙尚多乖。"]},{"t":"病中止酒","f":"五言古诗","c":["平生万事轻，惟以酒自娱。","当其爱酒时，一日不可无。","老来因属疾，不饮五月馀。","客饮我不羡，而况逢曲车。","见杯不思斟，见樽不思酤。","终日但清坐，此心长泊如。","只悟世人情，逐物非一途。","仕者嫭貂蝉，货者珍金珠。","赐泰嗤原贫，由勇诮孔迂。","何物真乐忧，何人定巧愚。","病后得反身，旷然同太虚。","其馀君莫问，曲生尚可疏。"]},{"t":"病中复脚痛终日倦坐遣闷","f":"七言律诗","c":["满眼生花雪满颠，者稀又过四双年。","谁知病脚妨行步，只见端居道坐禅。","堕扇几旁犹懒拾，检书窗下更能前。","世人总羡飞仙侣，我羡行人便是仙。"]},{"t":"罢丞零陵忽病伤寒谒医两旬如负担者日远日重改谒唐医公亮九日而无病矣谢以长句","f":"词","c":["料病如料敌，用药如中的。","淮阴百战有百胜，由基百发无一失。","老唐脉法明更高，阅人二竖可得逃。","探囊起死无德色，掉臂不为曳裾客。","但使乡邻少卧痾，眼底名医麻竹多。","嗟予诗瘦仍多病，两旬进尺退不寸。","逢君已晚亦未恨，扫除何曾费馀刃。","长句藉手聊尔耳，真成不直一杯水。"]},{"t":"荷亭倚栏","f":"七言绝句","c":["鱼跳龟戏不曾闲，萍尽荷生尚未繁。","水面圜纹乱相入，玻瓈盆旋玉连环。"]},{"t":"莲子","f":"七言绝句","c":["蜂儿来自宛溪中，两翅虽无已是虫。","不似荷花窠底蜜，方成玉蛹未成蜂。"]},{"t":"袁州路遇晴","f":"五言律诗","c":["晴意久不果，天容今一新。","如何半轮日，销却许多云。","积雨还休雨，小春真似春。","客心君莫问，山鸟亦欣欣。"]},{"t":"读书","f":"五言古诗","c":["读书不厌勤，勤甚倦且昏。","不如卷书坐，人书两忘言。","兴来忽开卷，径到百圣源。","说悟本无悟，谈玄初未玄。","当其会心处，只有一欣然。","此乐谁为者，非我亦非天。","自笑终未是，拨书枕头眠。"]},{"t":"读天宝事","f":"七言绝句","c":["日晚无烟起御厨，野人豆饭未嫌粗。","问知云子炊香日，政是梨花带雨初。"]},{"t":"读白氏长庆集","f":"五言古诗","c":["每读乐天诗，一读一回好。","少时不知爱，知爱今已老。","初哦殊驩欣，熟味忽烦恼。","多方遣外累，半已动中抱。","事去何必追，心净不须扫。","追叹欲扫愁，自遣还自扰。","不如卷此诗，唤酒一醉倒。","狂歌谪仙词，三杯通大道。"]},{"t":"读诗","f":"七言绝句","c":["船中活计只诗编，读了唐诗读半山。","不是老夫朝不食，半山绝句当朝餐。"]},{"t":"读唐人于濆刘驾诗","f":"五言古诗","c":["刘驾及于濆，死爱作愁语。","未必真许愁，说得乃尔苦。","一字入人目，蜇出两睫雨。","莫教雨入心，一滴一痛楚。","坐令无事人，吞刃割肺腑。","我不识二子，偶览二子句。","儿曹劝莫读，读著恐愁去。","我云宁有是，试读亦未遽。","一篇读未竟，永慨声已屡。","忽觉二子愁，并来遮不住。","何物与解围，伯雅烦尽护。"]},{"t":"读唐人及半山诗","f":"七言绝句","c":["不分唐人与半山，无端横欲割诗坛。","半山便遣能参透，犹有唐人是一关。"]},{"t":"读渊明诗","f":"五言古诗","c":["少年喜读书，晚悔昔草草。","迨今得书味，又恨身已老。","渊明非生面，稚岁识已早。","极知人更贤，未契诗独好。","尘中谈久睽，暇处目偶到。","故交了无改，乃似未见宝。","貌同觉神异，旧玩出新妙。","雕空那有痕，灭迹不须扫。","腹腴八珍初，天巧万象表。","向来心独苦，肤见欲幽讨。","寄谢颍滨翁，何谓淡且槁。"]},{"t":"轿中看山","f":"五言古诗","c":["买山安得钱，有钱价不贱。","住山如冠玉，人见我不见。","世言游山好，一峰足双茧。","峰外复有峰，历尽独能遍。","不如近看山，近看不如远。","请山略退步，容我与对面。","我行山欣随，我住山乐伴。","有酒唤山饮，有蔌分山馔。","隔水绝高寒，萦云偏茜绚。","雨滋青弥深，日炫紫还浅。","端居忽飞动，遐逝即回转。","孤秀呈复逃，层尖隐还显。","掇入轿中来，置在几上玩。","劣行三两驿，已阅百千变。","非我去旁搜，皆渠来自献。","寄言有山人，勿卖亦勿典。","金多汝安用，价重山亦怨。","估若为我低，伤廉又非愿。","山已在胸中，岂复有馀羡。","羡心固无馀，更借山一看。"]},{"t":"都下和同舍客李元老承信赠诗之韵","f":"七言古诗","c":["论交何必星霜久，白头得似倾盖友。","长安市上李将军，挽弓旧不论石斗。","只今有子似渠长，清夜读书雪边牖。","云端烽烟半点无，怪来将军不好武。","遗我骊珠三百颗，字字镌镵未曾苟。","得得且看钱塘潮，莫莫言攀渭城柳。","朝家金印斗样大，情知不上书生肘。","儒冠多误侬饱谙，毛锥焉用君知否。","便应早请终军缨，径须系取单于首。","居延蒲类水如天，吹作春风一杯酒。","归来冠剑上凌烟，剩作功名落人口。","如何收敛许光芒，也趁槐花黄里走。","献璞虽真不救胫，绝弦何如只停手。","人生匹似风中花，荣瘁升沈岂非偶。","与君早赋归去来，名垂万古知何有。","不如耳热歌呜呜，醉帽欹倾衣不纽。","诗流唱和秋虫鸣，僧房问答狮子吼。","尽令俗客不妨来，白眼相看勿分剖。"]},{"t":"偶生得牛尾狸献诸丞相益公侑以长句","f":"七言古诗","c":["风林露圃天欲霜，柿红栗紫橘弄黄。","老夫忍馋不忍尝，丁宁笾人莫取将。","朝来栗姬羽化去，逋其木奴三百户。","乌椑士子散如烟，检校不知渠去处。","山僮相传皂衣郎，字曰季狸氏奇章。","上树千回一霎强，连夜剽掠积乃仓。","并吞又向黎侯国，罗人救黎遂禽获。","白茅面缚来献俘，玄端貂裘瓠肥白。","解骖荐渠登相门，立谈封作糟丘君。","旁招披绵拉通印，日侍尊俎嬉平园。","玉肌生憎粗手削，须防东坡诵冤著。"]},{"t":"偶成","f":"五言绝句","c":["珍禽饮盆池，将扇扑窗户。","一声惊得飞，再声惊不去。"]},{"t":"宿花斜桥见鸡冠花二首 其二","f":"七言绝句","c":["陈仓金碧夜双斜，一只今栖纪渻家。","别有飞来矮人国，化成玉树后庭花。"]},{"t":"宿花斜桥见鸡冠花二首 其一","f":"七言绝句","c":["出墙那得丈高鸡，只露红冠隔锦衣。","却是吴儿工料事，会稽真个不能啼。"]},{"t":"宿月岩","f":"七言律诗","c":["月华无满亦无亏，天借寒光劣半规。","长挂冰盘下弦魄，新生丹桂出轮枝。","偏令南省登金客，争赋东堂片玉诗。","传语姮娥还有妹，请分一个住幽奇。"]},{"t":"宿长乐县驿驿皆用葵叶盖屋状如棕叶云","f":"七言绝句","c":["都将葵叶盖亭中，树似桄榔叶似棕。","欲问天公觅微雪，装成急响打船篷。"]},{"t":"宿四望山下望庐山","f":"五言古诗","c":["过湖见远岫，澹若横碧烟。","晨蔚动霁晖，春滋涵雨鲜。","人世那有此，必疑是庐山。","宿惊恍未定，欲问无暇言。","落日泊四望，诸峰森在前。","老夫急亲指，舟子答果然。","平地起屏障，倚空开旗旃。","潜抱秀润质，不露奇怪颜。","乃知名山尊，未与凡岭班。","严重王公体，雍容德人贤。","何必出锋锐，要骇俗子观。","坐令我生敬，瞻仰忘忧端。","更待孤月出，开篷望晴峦。"]},{"t":"宿庐山栖贤寺示如清长老","f":"词","c":["清风迎衣襟，白云捧脚底。","飘然径上庐山头，谁道栖贤三十里。","乡禅引到狮子峰，旃檀喷出香雾浓。","此一瓣香为五老，一笑问我颜犹红。","右看南岳左东海，方丈祝融抹轻黛。","群仙遥劝九霞觞，金盘玉箸鲸鱼脍。","急呼清风与白云，送我更往会列真。","乡禅恐我忽飞去，挽著衣襟复留住。","下视落星石一拳，长江一线湖一涓。","醉掬玉渊亭下泉，磨作墨汁洒醉篇。"]},{"t":"宿杨塘店","f":"七言律诗","c":["吾生行路何时了，旧馆重来身渐老。","路旁松桂只十年，如今脩脩旧小小。","昨宵宿处又云边，来宵还似今宵然。","陈迹更待俛仰间，有酒不饮要称贤。"]},{"t":"宿皂口驿","f":"七言绝句","c":["倦投破驿歇征骖，喜见山光政蔚蓝。","不奈东风无检束，乱吹花片点春衫。"]},{"t":"宿度息","f":"五言古诗","c":["薄云翳佳月，风为作金篦。","我行以事役，云行亦忙为。","如何今夕寒，只与客子期。","忘情岂我辈，能禁秋兴悲。","短檠不解事，唤我哦新诗。"]},{"t":"宿徐元达小楼","f":"五言律诗","c":["楼迥眠曾著，秋寒夜更加。","市声先晓动，窗月傍人斜。","役役名和利，憧憧马又车。","如何泉石耳，禁得许諠哗。"]},{"t":"宿黄土龛五更闻子规","f":"七言律诗","c":["通宵不睡睡方奇，梦里惊闻新子规。","祗是一声已肠断，况当三月落花时。","不论客子愁无那，便遣家人听亦悲。","归到江西归始了，江东归得未为归。"]},{"t":"宿湖甫山","f":"五言古诗","c":["夜泊湖甫山，绿杨护危堤。","迅雷将残雨，似猛竟复微。","晓月解风缆，熟睡初不知。","起来问宿处，千山翠相围。","霁峰有剩谒，旭溪无停辉。","远树芦外出，若与船争驰。","多情东林塔，寸步不相离。","后送欣已远，前迎复在兹。","不知塔意厚，为复船行迟。","谁能仆此塔，庶不淹吾归。","独感夜来雨，政作朝凉资。"]},{"t":"宿潭石步","f":"七言古诗","c":["三更无月天正黑，电光一掣随霹雳。","雨穿天心落篷脊，急风横吹斜更直。","疏篷穿漏湿床席，波声打枕一纸隔。","梦中惊起眠不得，揽衣危坐三叹息。","行路艰难非不历，平生不曾似今夕。","天公嚇客恶作剧，不相关白出不测。","收风拾雨猝无策，如何乞得东方白。","垂头缩脚正偪仄，忽然头上复一滴。"]},{"t":"寄王用之判府监簿","f":"词","c":["寅清堂上初相识，君如玉树逢春碧。","滕王阁下重相从，君如天骥追秋风。","九州四海王鲁公，有子不减汉八龙。","君才况是廊庙具，登庸衣钵亲分付。","笋班小试云霄步，州麾妙琢湖山句。","君不见西京韦家父子间，阿成官职似阿贤。","皇朝吕家也不恶，大申小申相后先。","看君一武超韦吕，奄有龟蒙再封鲁。"]},{"t":"寄朱元晦长句以牛尾狸黄雀冬猫笋伴书","f":"七言古诗","c":["大武尾裔名季狸，目如点漆肤凝脂。","江夏无双字子羽，九月授衣先著絮。","何如苗国孤竹君，排霜傲雪高拂云。","子孙总角遁归根，金相玉质芝兰芬。","三士脂韦与风节，借箸酒池俱胜绝。","先生胸次有皂白，一醉不须向人说。"]},{"t":"寄吴宜之","f":"七言古诗","c":["罨画溪头老诗伯，夜榜仙槎郁林石。","要令南斗避文星，却归北辰捧天极。","顷逢桂江双鲤鱼，殷勤两寄尺素书。","山长水远到不到，未必韦郎迹也疏。","书中只有相思字，更及融州一寒士。","泮水曾参冷似冰，等待春风放桃李。"]},{"t":"寄饯湖广总领张子仪少卿赴召","f":"词","c":["君不见绍兴初载毗陵公，乱后身作夹日龙。","功存社稷报不尽，祇遣千载高清风。","当家衣钵付谁子，兰砌孙枝浑是似。","哦诗五字如渊明，读书万卷如子美。","士饱木牛今几年，月升金掌归九天。","胡不令舍人咄咄趣行李，早上星辰听珠履。"]},{"t":"寄题万元享舍人园亭七景 其五 也贤","f":"五言绝句","c":["架亭元用木，一夕化为竹。","醉眼碧成朱，若个是苍玉。"]},{"t":"寄题万元享舍人园亭七景 其四 闲世界","f":"五言绝句","c":["要寻闲世界，不在世界外。","明月与清风，何朝不相对。"]},{"t":"寄题万元享舍人园亭七景 其三 溪云","f":"五言绝句","c":["阁前三面山，阁下一溪水。","云出戏作霖，却归宿檐里。"]},{"t":"寄题万元享舍人园亭七景 其二 蒲鱼港","f":"五言绝句","c":["蒲牙长几何，已足庇玉尺。","只恐如主人，潜逃逃不得。"]},{"t":"寄题万安萧和卿云冈书院","f":"词","c":["君不见南轩先生以道鸣，岳麓书院陶诸生。","君不见晦庵先生妙经学，庐山书院榜白鹿。","吾乡萧君八叶孙，云冈筑斋高入云。","芝兰玉树争绩文，江湖鹄袍争骏奔。","愿师朱张两先生，驷马高盖塞里门。"]},{"t":"寄题分宜李克明上舍高居二咏 其二 东塾","f":"五言绝句","c":["一凤领四雏，夜作吾伊声。","梧桐高拂日，好去瑞尧庭。"]},{"t":"寄题天台临海县白鹤庙西泉","f":"七言古诗","c":["东泉千年流不休，西泉千年秘不流。","临海令君一念作，猿鸟未知泉已觉。","殿脚西头苍石根，向来元无泉眼痕。","一朝擘崖迸膏乳，却与东泉作宾主。","令君已升金掌中，白鹤古祠烟雨濛。","父老思君难再得，登亭饮泉三叹息，祝君公台寿千百。"]},{"t":"寄题太和丞公沈君公馆亭台四咏 其三 成蹊亭","f":"五言绝句","c":["红雨未随风，白雪忽满枝。","祇今正月尾，政是断肠时。"]},{"t":"寄题太和丞公沈君公馆亭台四咏 其二 特秀亭","f":"五言绝句","c":["秋月弄长江，平地点远岫。","赞府诗句中，字字江山秀。"]},{"t":"寄题太和丞公沈君公馆亭台四咏 其一 真清亭","f":"五言绝句","c":["苍髯秦大夫，瘦骨孤竹君。","主人似二子，二子似主人。"]},{"t":"寄题太和丞公沈君公馆亭台四咏 其四 读书台","f":"五言绝句","c":["庭散纸尾鹜，窗聚案头萤。","无端循除水，也学夜诵声。"]},{"t":"寄题开州史君陈师宋柴扉","f":"五言古诗","c":["屋是茅一把，门是柴一束。","是间著宇宙，太仓半粒粟。","吾闻陈家扉，样似陶家屋。","孤松不须双，五柳何用六。","竹篱东复东，添种数丛菊。","剩肯蚤归来，盈尊酒初绿。"]},{"t":"寄题王亚夫检正不啻足斋","f":"词","c":["既得陇，复望蜀，未求宝剑先求玉。","秦相后车一千毂，唐相胡椒八百斛。","黄金肘印驾黄鹄，身前佞佛身后福。","九潦泻入无底谷，匹似人心犹易足。","九州四海王同年，三江五湖春水船。","便应犯斗入月边，馀事犹堪济巨川。","天风吹来堕人寰，水精宫里作诗仙。","寄笺排云叫穹昊，愿赐江湖散人号。","玉皇留渠作丰年，早晚唤归香案前。","诗仙掉头不肯住，田园将芜梦归去。","括苍山胜道场山，向来结茅非雾间。","斋房恰则斗来大，中藏世界三千个。","门前蛮触战方酣，鼻息如雷政高卧。"]},{"t":"寄题永新昊天观贺知宫方外轩","f":"七言古诗","c":["君家秘监唐诗客，饮中八仙渠第一。","君家水部晋仙真，曾拜东封玉路尘。","祗今孙子方外士，羽衣霞佩云为袂。","月下缑山吹凤笙，雾里华阳割龙耳。","何当踞龟食蛤蜊，大嚼碧藕嬉瑶池。","若见君家两仙伯，为侬寄声好将息。"]},{"t":"寄题石湖先生范至能参政石湖精舍二首 其一","f":"七言律诗","c":["万顷平湖石琢成，尚存越垒对吴城。","如何豪杰干戈地，却入先生杖屦声。","古往今来真一梦，湖光月色自双清。","东风不解谈兴废，只有年年春草生。"]},{"t":"寄题龙泉李宗儒师儒槐阴书院","f":"七言古诗","c":["龙泉二李继谪仙，朝议朝散相后先。","凤雏二妙继乃祖，宗儒师儒贤弟昆。","手种兔目今几年，日茹叶淘呻断编。","阴似王家三树绿，异时官职追前躅。","花作唐人八月黄，来岁能书催趣装。"]},{"t":"寄题龙泉项圣与卢溪书院","f":"七言古诗","c":["三顾先生得麟笔，付嘱遗经谁第一。","独将麟髓饭澹翁，项家阿英亦其乙。","澹翁孤忠贯两仪，阿英卓行彻九扉。","旌门一日插天半，却把此笔传阿宜。","阿宜阿囝续弓冶，卢溪书院声无价。","不论当家与外人，不日天池看浑化。"]},{"t":"寄题刘巨卿家六咏 其四 西隐","f":"五言绝句","c":["山林与朝市，隐处俱未是。","只个西枝西，默坐且求志。"]},{"t":"寄题刘巨卿家六咏 其六 来薰轩","f":"五言绝句","c":["薰风自南来，万象皆披襟。","老子本不热，看他度青林。"]},{"t":"寄题刘巨卿家六咏 其三 拙庵","f":"五言绝句","c":["天下无个事，巧著事便生。","濂溪一赋在，座右不须铭。"]},{"t":"寄题刘巨卿家六咏 其五 壶天","f":"五言绝句","c":["其大弥九苍，其小贮一壶。","静观性中天，大小竟何如。"]},{"t":"寄题刘巨卿家六咏 其二 蒙斋","f":"五言绝句","c":["是心如维斗，万物所取正。","蒙之以微云，孤光更渊靓。"]},{"t":"寄题刘正卿双清轩","f":"七言律诗","c":["吾乡今代刘更生，新序说苑落笔成。","问渠才思宁底巧，玉泉绕屋供双清。","此泉来从何境界，银河飞下双罗带。","便好乘槎犯斗星，斫桂广寒天上行。"]},{"t":"寄题刘成功锦里","f":"七言古诗","c":["嘉林市中尘一丈，嘉林寺后竹千竿。","先君授徒竹窗底，我初识君俱少年。","同师同舍同笔砚，火冷灯青飞雪片。","春风一夜吹林花，南北飘零各星散。","我今头白苦思归，羡君山园芋栗肥。","为君题作小锦里，君应一笑巾堕几。"]},{"t":"寄题刘凝之坟山壮节亭用辘轳体","f":"七言律诗","c":["见了庐山想此贤，此贤见了失庐山。","胸中书卷云凌乱，身外功名梦等闲。","一点目光牛背上，五弦心在雁行间。","欲吟壮节题崖石，笔挟风霜齿颊寒。"]},{"t":"寄题安福刘道协涌翠楼","f":"七言古诗","c":["读书台南山绕屋，恰如万簪削青玉。","读书台北山更多，又似碧海跃万波。","台边高人子刘子，架楼南北山围里。","醉中领客上上头，忽惊平地翠浪浮。","一浪抛云入天半，众浪翻空湿银汉。","砰轰打到栏干前，天跳地踔乾坤颠。","主宾拍手呼钓船，定眼看来还不然，只是南北几点山。"]},{"t":"寄题朱元晦武夷精舍十二咏 其五 石门坞","f":"五言绝句","c":["乱石堆成玉，双峰便是门。","莫将尘底脚，踏涴坞中云。"]},{"t":"寄题朱元晦武夷精舍十二咏 其六 观善斋","f":"五言绝句","c":["观棋不作秋，观斲不作石。","要知丽泽功，祇个是消息。"]},{"t":"寄题朱元晦武夷精舍十二咏 其十 钓矶","f":"五言绝句","c":["月夜乘醉来，垂竿曲溪曲。","水清无寸鳞，钓得半轮玉。"]},{"t":"寄题朱元晦武夷精舍十二咏 其十一 茶灶","f":"五言绝句","c":["茶灶本笠泽，飞来摘茶国。","堕在武夷山，溪心化为石。"]},{"t":"寄题朱元晦武夷精舍十二咏 其九 铁笛亭","f":"五言绝句","c":["谁将点漆金，铸作孤竹笛。","林外吹一声，震落千峰石。"]},{"t":"寄题朱元晦武夷精舍十二咏 其十二 渔艇","f":"五言绝句","c":["精舍何曾远，祗在九曲北。","渔艇若不来，弱水万里隔。"]},{"t":"寄题朱元晦武夷精舍十二咏 其三 隐求堂","f":"五言绝句","c":["梦里长逢孟，羹中亦见颜。","痴儿入吾室，真作采薇看。"]},{"t":"寄题吴仁杰架阁玩芳亭","f":"七言古诗","c":["洞庭波上木叶脱，巫山宅前野花发。","子规啼杀不见人，空令千载忆灵均。","春兰九畹百亩蕙，自荣自落谁能佩。","泽国东山最上头，有客玩芳杜若洲。","扁舟夜上人鲊瓮，手掇骚人众芳种。","归来梦到阆风台，灵均花草和露栽。","寄言众芳未要开，更待诚斋老子来。"]},{"t":"寄题庐山楞伽寺三贤堂呈南康太守曾致虚","f":"七言古诗","c":["山房牙签三万轴，六丁下取归群玉。","空馀坡老枯木枝，雪骨霜筋插云屋。","楞伽老僧怀两贤，作堂要与祠千年。","只供清风荐明月，不用秋菊兼寒泉。","江西社里曾常伯，李家玉润苏家客。","并遣巫阳招取来，分坐庐山泉上石。"]},{"t":"寄题张仲寅甘老堂","f":"词","c":["屏山十论抉圣心，甘老十论刮古今。","古今刮得都见髓，持献玉工逢刖趾。","玉皇左相华阳封，上与阿旦双周公。","荐渠金门可登仕，金门送渠外台试。","渠侬掉头不肯行，有雪可钓月可耕。","恩山紫蕨椽来大，恩江白鱼船样个。","绿蓑青箬霞上卧，不知毕逋明视东西过。"]},{"t":"寄题张县尉敬之南昌官寺重新子真祠堂","f":"七言古诗","c":["梅郎绛节朝玉台，朝游五城暮九垓。","遗民香火答遗爱，何年祠屋荒苍苔。","剑津诗客子张子，住持仙坛判山水。","上书台斗大居士，作缘水漕皇华使。","二台并檄孔家兄，经始新祠不日成。","西山南浦作贺宾，野梅官柳俱驩声。"]},{"t":"寄题张钦夫春风楼","f":"七言古诗","c":["乐斋先生子张子，独立春风望洙泗。","四海无人万古空，咏歌一声满天地。","不应东阁胜东山，浮云于渠了不关。","只馀平生医国手，未忍旁观缩袖间。","楼中古书积至斗，楼外春江绿如酒。","权门得似圣门寒，万波横流独回首。","向来沂上瑟声希，由求相顾只心知。","至今留取一转语，不知何咏亦何归。"]},{"t":"寄题李与贤似剡庵","f":"词","c":["四明狂客一茅屋，敕赐剡川才一曲。","安福诗人李与贤，大书似剡山扉前。","我曾著脚勾践国，奉诏昭陵省松柏。","是时八月欲半头，镜湖不是人间秋。","稽山影落水精阙，荷花露滴波中月。","季真茅屋荒苍苔，古木哀猿啼禹穴。","今君结屋阿那边，疋似剡川若个言。","我到剡川君未到，似和不似然不然。","君不见兴公旧草天台赋，元不曾识天台路。","一俛仰间已再升，何用瘦藤与芒屦。"]},{"t":"寄题李俊臣南楼","f":"词","c":["庾家南楼天下无，李家南楼何似渠。","玉篸碧山罗带水，眼界风烟且千里。","何须横陈鹦鹉洲，月挂栏干西角头。","谪仙子孙五凤手，安得长江化作一杯酒。"]},{"t":"寄题邵武张汉杰运干万卷楼","f":"词","c":["书生都将命乞书，愿身化作蠹书鱼。","蠹鱼生得针来大，日啖银钩三万个。","书生一腹无十围，经炊史酌不曾饥。","君家一编本黄石，积书至今与山齐。","玉川搜肠才一半，邺侯插架端无羡。","如何万卷楼上人，却去黄鹤楼前作宾赞。"]},{"t":"寄题邹公桥","f":"七言律诗","c":["吾侪一事办不曾，邹公一桥了此生。","省斋先生三大字，此桥便有千载意。","今年天亦与护持，桃花春水不多肥。","济川题柱吾无梦，梦借新桥作钓矶。"]},{"t":"寄题邹有常爱莲亭","f":"七言律诗","c":["道乡先生有族子，卜筑富川弄江水。","更穿两沼磨碧铜，分种芙蕖了秋事。","一沼花白一沼红，新亭恰当红白中。","此花不与千花同，吹香别是濂溪风。"]},{"t":"寄题邹虞卿觌仙阁","f":"七言律诗","c":["仙山去天才一握，与山相高邹氏阁。","月波吹面寒欲冰，斗柄挂檐危不落。","叶县双凫那复飞，缑山一鹤何时归。","王仙肯来阁上否，共丝麟脯倾天酒。"]},{"t":"寄题周子中监丞万象台","f":"七言古诗","c":["昔从永和望青原，永和在地山在天。","今从青原望万象，青原在下台在上。","乘成先生学海龙，眼高四海空复空。","如登中天骛八极，下视积苏同绛宫。","万物一马喻多少，漆园小家穷计校。","须弥芥子亦未妙，葱岭老胡乌知道。","此诗解嘲仍索闹，举似先生应绝倒。"]},{"t":"寄题周元吉湖北漕司志功堂","f":"七言古诗","c":["周郎昨赞元戎幕，夜眺秦川登剑阁。","函关不用一丸泥，谈笑生风扫河洛。","君王尺一唤渠回，贮之凤阁与鸾台。","不赞元戎赞丞相，笔补造化裨盐梅。","龙媒志在横八极，天闲玉鞯羁不得。","又挥白羽岸纶巾，却去武昌寻赤壁。","一览亭前山月明，志功堂下大江横。","前称公瑾后元吉，君家世有千人英。","公瑾小乔在何许，元吉小蛮花解语。","看君一箭落胡星，如皋一笑倾人城。","金印如斗带万钉，何人为作燕然铭。"]},{"t":"寄题临武知县李子西公廨君子亭","f":"七言古诗","c":["王家唤竹作此君，周家唤莲作君子。","泥中怀玉避俗尘，水上开花超大地。","红裳翠盖在眼中，欲往从之隔秋水。","牡丹贵人非吾徒，篱菊隐士堪邻居。","李侯岸巾对芙蕖，不寄新诗来起予。"]},{"t":"寄题保静庵","f":"七言古诗","c":["洙泗九渊閟玄珠，没人下取龙怒须。","迂叟勃兴章甫徒，刺手一探珠炯如。","正心保躬四颗馀，一颗光照千乘车。","艮斋竖起麈拂子，保静居士一笑喜。","试著此珠狂波底，波自拍天珠在水。","江南江北起秋风，庵前庵后吹霜松。","居士焚香于其中，手挥五弦送归鸿。"]},{"t":"寄题南城吴子直子常上舍兄弟社仓","f":"七言古诗","c":["有虞有宋双重华，两圣一心民一家。","绿针刺水农事起，重华愁早从此始。","黄云登场万宝秋，重华对天失却愁。","二十八年临玉座，太半光阴愁里过。","天颜忧喜丞相知，常平使者陈便宜。","倡为社仓首建溪，旴江吴札承君师。","伯霜仲雪发尔私，支奇虐魃手莫施。","活几侲子几冻黎，诏子文孙孙又子。","个是重华圣人意，无论十世百千世。"]},{"t":"寄题赵漕秘阁东山堂","f":"七言古诗","c":["阿旦东山著乾坤，十雨世界三登村。","阿安东山著一身，白云保社明月邻。","此山祗合馆此客，千载阿谁敢争席。","赵侯玉立隆准孙，洗空凡马追古人。","千山万水略行遍，一锥卓住东洋岸。","东洋山麓东复东，筑堂折简招两公。","倒提北斗酌银汉，灵山作樽江作钟。","浩歌小袖经纶手，笑与两公举天酒。","东山今属赵家庄，敬请两公迁别乡。"]},{"t":"寄题袁机仲侍郎殿撰建溪北山四景 其四 抗云亭","f":"五言绝句","c":["脚底一朵云，乘之绕空碧。","前身王子乔，今代李太白。"]},{"t":"寄题萧民望齐云楼","f":"七言律诗","c":["下泳山尖碧云起，添得奇峰三四觜。","老人登楼来看云，下瞰云端在平地。","急呼云师令执鞭，我欲乘此追群仙。","蓬莱阆风遍游览，归来落月满晴川。"]},{"t":"寄题萧邦怀步芳园","f":"七言律诗","c":["群莺乱飞春昼长，极目千里春草香。","幽人自煮蟹眼汤，茶瓯影里见山光。","欣然药囿聊步屧，戏随蜜蜂与蝴蝶。","杨花糁径白于雪，桃花夹径红于襭。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十九 曲水","f":"七言绝句","c":["名园曲水费工夫，玉甃琼磨滴水无。","谁把流觞借诗老，天生九曲一冰渠。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其十五 药畦","f":"七言绝句","c":["雨馀想见药苗肥，薯蓣堪羹杞可齑。","老贼何须投益智，先生只要买当归。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其三 钓矶","f":"七言绝句","c":["乌龙滩下白云堆，上有狂奴旧钓台。","一夕被君偷取去，至今犹带汉莓苔。"]},{"t":"寄题喻叔奇国博郎中园亭二十六咏 其八 荼蘼洞","f":"七言绝句","c":["旧绕新萦绿万蟠，架馀篱剩复垂栏。","先生醉帽堆香雪，知自荼蘼洞里还。"]},{"t":"得小儿寿俊家书","f":"七言古诗","c":["父子初别双泪垂，别我既久忘却思。","忽得一书喜且悲，恰似向来初别时。","汝翁在官缘索米，吾儿在家勉经史。","举头二千四百里，亘山啼鸟偏入耳。","诗成自哦只自知，便风不敢寄吾儿。","汝望白云穿却眼，若得此诗恐肠断。","径须父子早归田，粗茶淡饭终残年。"]},{"t":"得寿仁寿俊二子中涂家书三首 其三","f":"五言古诗","c":["我昔如汝长，壮志在四方。","集贤给笔札，秉烛促夜装。","平明出门去，振衣不徬徨。","先君泫然泣，感我令我伤。","先君顾我语，汝行勿断肠。","它日汝养子，此悲会身当。","老怀追陈迹，心折涕泗滂。"]},{"t":"得寿仁寿俊二子中涂家书三首 其二","f":"五言古诗","c":["子壮祇觉幼，子学祇觉迟。","二子忽颀然，语离又作悲。","今年来官下，二子暂我随。","悬知住不久，且复相从嬉。","鹤书自天降，槐花呼汝归。","伯也恐我愁，愿留不忍辞。","仲也惨不释，飞鸣思及时。","岂有凤将雏，雏长禁其飞。","决焉遣还家，一笑更不疑。","傍人怪无泪，泪入肝与脾。"]},{"t":"得寿仁寿俊二子中涂家书三首 其一","f":"五言古诗","c":["二子别我归，兼旬无消息。","客有馈荔枝，盈篮风露色。","绛罗蹙宝髻，冰弹溅柘液。","老夫非不馋，忍馋不忍吃。","急呼两健步，为我致渠侧。","默数川陆程，几日当返役。","惟愁香味坏，色变那敢惜。","十日两骑还，千里一纸墨。","把书五行下，废书双泪滴。","不如未到时，当喜翻不怿。"]},{"t":"族叔祖彦通所居宛在水中央名之曰小蓬莱为作长句","f":"七言古诗","c":["侬爱南溪不减公，南溪亲公却疏侬。","为侬只作一两曲，为公绕尽云边屋。","屋后有竹前有花，断桥才整已半斜。","客来不恶去亦好，莫将汗脚涴瑶草。","俗子只道无蓬莱，请渠且洗睫上埃。","蓬莱不大亦不小，作诗示公公一笑。"]},{"t":"晚出郡城往值夏谒胡端明泛舟夜归","f":"五言古诗","c":["郡城至值夏，两日非宽程。","奔走岂吾愿，诏书促南征。","出郭星未已，归棹月已生。","问人水深浅，舟子喧未应。","水石代之对，淙然落滩声。","危峰起夕苍，暗潭生夜清。","江转风飒至，病肩难隐棱。","添衣初懒寻，忍寒良不能。","近城一二里，远岸三四灯。","望关恐早闭，驱舟祗迟行。","多情半环月，久矣将西倾。","欲落且小留，知我要入城。","月细光未多，大星助之明。","至舍心未稳，丽谯才一更。"]},{"t":"晚立西湖惠照寺石桥上","f":"七言绝句","c":["船于镜面入烟丛，寺在湖心更柳中。","暮色欲来吾欲去，其如南北两高峰。"]},{"t":"晚立普明寺门时已过立春去除夕三日尔将归有叹","f":"七言古诗","c":["萧萧淅淅荻花风，惨惨澹澹云物容。","欲雪不雪关得侬，得归未归一莞中。","年华纵留春已换，半生作客今何恨。","夜来飞霰打僧窗，便恐雪真数尺强。","催科不拙亦安出，吾民沥髓不濡骨。","边头犀渠未晏眠，天不雨粟地流钱。"]},{"t":"晚过常州","f":"七言律诗","c":["常州曾作两年住，一别重来十年许。","岸头杨柳记得无，总是行春系船处。","自笑恍如丁令威，老怀成喜亦成悲。","人民城郭依然是，只有向来须鬓非。"]},{"t":"晚过黄洲铺二绝 其二","f":"七言绝句","c":["仆夫已倦路犹赊，脚底殊劳眼底佳。","绿锦堆中半团雪，千枫拥出一桐花。"]},{"t":"晚步南溪弄水","f":"五言古诗","c":["吾庐在南溪，溪北北山半。","山空谁肯邻，影静鹤为伴。","万松当篱落，千岩上几案。","花草岂厌多，不多亦堪玩。","一丘万事足，半点无外羡。","如何濯双缨，独欠泉一眼。","晚晴漫野步，偶到溪侧畔。","颇怪清浅流，雪后劣如线。","相将二三子，一笑出奇观。","琼砂杂瑶砾，掇拾作微堰。","锵然便淙琤，清若奏琴阮。","当流立孤石，滟滪忽童丱。","不塞势何怒，惟激声故远。","从今日日来，愁肺要湔浣。","儿童俾勿坏，鸥鹭好看管。"]},{"t":"晚饮","f":"五言律诗","c":["大醉或伤生，不醉又伤情。","此事两难处，后先有重轻。","醉后失天地，馀生底浮萍。","愁城不须攻，醉乡无此城。"]},{"t":"晚饮","f":"七言绝句","c":["旋旋哦诗旋旋抄，一尊野蔌更山肴。","春风略不扶人醉，月到梅花最末梢。"]},{"t":"晚春行田南原","f":"七言古诗","c":["西畴前日尘作雾，南村今日波生路。","云子从来疏广文，冲雨学稼当辞勤。","农言秧好殊胜麦，其如绿针未堪吃。","吾生十指不拈泥，毛锥便得傲蓑衣。","只愿边头长无事，把耒耕云且吾志。","不愁官马送还官，借牛骑归不用鞍。"]},{"t":"晚春即事二绝 其一","f":"七言绝句","c":["尺许新条长杏栽，丈馀斑笋出墙隈。","浪愁草草酴醾过，不道婷婷芍药来。"]},{"t":"晚宿小罗田四首 其二","f":"七言绝句","c":["倒尽菰蒲折尽荷，芙蓉临水恨无多。","一花却有两花影，东卧斜阳西卧波。"]},{"t":"晚望","f":"七言绝句","c":["天堕楸枰作稻畦，啼乌振鹭当枯棋。","不论胜负端何似，黑子终多白子稀。"]},{"t":"晚晴","f":"七言律诗","c":["日光射雪雪透红，雪光射日日吐虹。","何人铸银作大地，万象都入银光中。","诗翁两眼老病里，爱看晚晴聊仰视。","眼睛空花忽乱起，紫晕一轮三万里。"]},{"t":"晚登清心阁望雨","f":"五言律诗","c":["悯雨喜见云，喜云愁不雨。","长风将怒点，慰此楼中暮。","喜雨不但人，松竹亦鼓舞。","未知今年熟，得似去年否。"]},{"t":"晚照","f":"七言绝句","c":["闲对斜阳数隙尘，何曾万事一关身。","汤瓶得火自相语，酒盏为人先作春。"]},{"t":"晨炊叱驭驿观海边野烧","f":"七言绝句","c":["南海惊涛卷玉缸，北山野烧展红幢。","山神海伯争新巧，并慰诗人眼一双。"]},{"t":"晨炊白升山","f":"七言律诗","c":["千峰为我旋生妍，我为千峰一洒然。","云掠石崖啼鸟树，雨添山涧落花泉。","心知僮仆多饥色，目断茅檐半穗烟。","只道晨炊食无肉，竹根斤笋两三钱。"]},{"t":"晨炊光口砦","f":"七言律诗","c":["泊船光口荐晨炊，野饭匆匆不整齐。","新摘柚花薰熟水，旋捞莴苣浥生齑。","尽教坡老食无肉，未害山公醉似泥。","过了真阳到清远，好山自足乐人饥。"]},{"t":"晨炊杜迁市煮笋","f":"七言古诗","c":["金陵竹笋硬如石，石犹有髓笋不及。","杜迁市里笋如酥，笋味清绝酥不如。","带雨斸来和箨煮，中含柘浆杂甘露。","可齑可脍最可羹，绕齿蔌蔌冰雪声。","不须咒笋莫成竹，顿顿食笋莫食肉。"]},{"t":"晨炊皂径","f":"五言律诗","c":["问路无多子，驱车半日间。","行穿崖石古，踏破藓花斑。","绿语莺边柳，青眠水底山。","人家岂无地，争住小溪湾。"]},{"t":"晨炊浦村","f":"五言律诗","c":["水出何村尾，桥横乱筱丛。","隔溪三四屋，对面一双峰。","过午非常暖，疑他不是冬。","疏梅照清浅，作意为谁容。"]},{"t":"望多稼亭","f":"七言古诗","c":["遥望城头多稼亭，亭边霜桧老更青。","当年老守携稚子，芒鞋葵扇绕城行。","腊前移梅春插柳，蹋雪冲泥不停手。","柳未成阴梅稚花，著帽又迎新太守。","后来新守复迎新，到今新旧知几人。","向来手植今在否，寄与此诗聊问春。"]},{"t":"望雨","f":"五言古诗","c":["云兴惠山顶，雨放太湖脚。","初愁望中远，忽在头上落。","白羽障乌巾，衣袖已沾渥。","归来看檐溜，如泻万仞壑。","霆裂大瑶瓮，电萦湿银索。","须臾水平阶，花坞失半角。","定知秧畴满，想见田父乐。","向来春夏交，旱气亦太虐。","山川已遍走，云物竟索寞。","双鬓愁得白，两膝拜将剥。","早知有今雨，老怀枉作恶。"]},{"t":"梅花下遇小雨","f":"七言古诗","c":["偶来花下聊散策，落英满地珠为席。","绕花百匝不忍归，生怕幽芳怨孤寂。","仰头欲折一枝斜，自插白鬓明乌纱。","傍人劝我不用许，道我满头都是花。","初来也觉香破鼻，顷之无香亦无味。","虚疑黄昏花欲睡，不知被花薰得醉。","忽然细雨湿我头，雨落未落花先愁。","三点两点也不恶，未要打空花片休。"]},{"t":"梅花数枝篸两小瓷瓶雪寒一夜二瓶冻裂剥出二水精瓶梅花在焉盖冰结而为此也","f":"词","c":["何人双赠水精瓶，梅花数枝瓶底生。","瘦枝尚带折痕在，隔瓶照见透骨明。","大枝开尽花如雪，小枝未开更清绝。","争从瓶口迸出来，其奈堪看不堪掇。","人言水精初出万壑时，欲凝未凝如冻脂。","上有江梅花正盛，吹折数枝堕寒镜。","玉工割取到人间，琢出瓶子和梅看。","至今犹有未凝处，瓶里水珠走来去。","只愁窗外春日红，瓶子化作亡是公。"]},{"t":"梦亡友黄世永梦中犹喜谈佛既觉感念不已因和梦李白韵以记焉二首 其二","f":"五言古诗","c":["去年客京都，子去我未至。","得书不得面，安用殷勤意。","犹矜各未老，相见当亦易。","不知此蹉跎，交道遽云坠。","一抔胡不仁，埋此经世志。","弦绝谅何益，蕙叹庸不悴。","吾闻佛者流，正以生作累。","梦中尚微言，子岂悲世事。"]},{"t":"梦亡友黄世永梦中犹喜谈佛既觉感念不已因和梦李白韵以记焉二首 其一","f":"五言古诗","c":["子在人每憎，子亡憎者恻。","自吾失此友，但觉生意息。","犹解梦里来，岂子馀此忆。","死生知有无，贤圣或未测。","浑作白日看，不记夜许黑。","尚怜紫鸾姿，未举先折翼。","只惊玉雪容，冷面带古色。","梦泪觉犹湿，悲罢喜有得。"]},{"t":"淋疾复作医云忌文字劳心晓起自警二首 其一","f":"七言绝句","c":["半似枯禅半似痴，也无何虑与何思。","偶看清晓双双蝶，飞遍黄花一一枝。"]},{"t":"淮河再雪二首 其一","f":"七言绝句","c":["风打波头波打船，并来枕底搅清眠。","先生夜起篷窗看，月满长淮雪满天。"]},{"t":"淳熙甲辰十月一日拟省试万民观治象诗","f":"五言古诗","c":["魏阙春风里，王城晓日端。","三朝垂治象，万姓得荣观。","老稚看如堵，章程炳若丹。","九天新雨露，一札妙龙鸾。","远览周官旧，重瞻汉诏宽。","欢声将喜气，销尽柳边寒。"]},{"t":"清远峡四首 其四","f":"五言律诗","c":["谁开峡山寺，政要避世喧。","深潭无来路，断崖有青天。","疗饥摘山果，击磬烦岭猿。","人迹今扰扰，祗缘一渔船。"]},{"t":"清远峡四首 其三","f":"五言律诗","c":["清远望峡山，山脚无半里。","小舟行其间，五日翠未已。","并驰两苍龙，中夹一玉水。","送我到英州，渠当自回辔。"]},{"t":"清远峡四首 其二","f":"五言律诗","c":["清晨雾雨重，不敢开船门。","小窗试微启，逗入一船云。","何曾烧龙麝，香霏绕吾身。","身在云水上，何许觅点尘。"]},{"t":"清远峡四首 其一","f":"五言律诗","c":["峡水都是泉，非雨元自足。","不知几滴珠，成此一川玉。","旁将山染翠，仰为天写绿。","何当雪月夜，孤艇苇间宿。"]},{"t":"清晓行散","f":"七言绝句","c":["清晓东园政好嬉，忽然伫立小迟迟。","为逢咫尺青松上，无数群莺政乱啼。"]},{"t":"渎头阻风","f":"七言古诗","c":["天寒春浅蛰未开，船头一声出地雷。","老夫惊倒卷帘看，白浪飞从东海来。","东海复东几万里，扶桑顷刻到长淮。","琉璃地上玉山起，玉山自走非人推。","似闻海若怒川后，雨师风伯同抽差。","夜提横水明光甲，大呼一战龟山颓。","老夫送客理归棹，适逢奇观亦壮哉。","岂不怀归船不进，系缆古柳依云堆。","须臾惊定却成喜，分付客愁金缕杯。"]},{"t":"猎桥午憩坐睡","f":"五言律诗","c":["路是山腰带，苔为石面花。","隔溪闻鸟语，疏竹见人家。","雨足晴须耐，神劳睡却佳。","睡魔推不去，知我怯新茶。"]},{"t":"移床","f":"七言绝句","c":["清晨暑气已愁予，何况晹虫午及晡。","寻得松风小凉处，移床来坐又还无。"]},{"t":"船中蔬饭","f":"七言律诗","c":["食蕨食臂莫食拳，食笋食梢莫食根。","何曾万钱方下箸，先生把菜亦饱去。","岭南风物似江南，笋如束薪蕨作篮。","先生食籍知几卷，千岩万壑皆厨传。"]},{"t":"船过砚石步","f":"七言律诗","c":["雨中初厌箬篷遮，撑起篷来景更佳。","岸上长松立如笔，波中寒影走成蛇。","忽看云外吐银镜，一点晨光射玉沙。","却出船头聊放目，远峰无数碧横斜。"]},{"t":"菱沼","f":"七言绝句","c":["柄似蟾蜍股样肥，叶如蝴蝶翼相差。","蟾蜍翘立蝶飞起，便是菱花著子时。"]},{"t":"谒永祐陵归途游龙瑞宫观禹穴","f":"七言律诗","c":["我昔骑凤超九疑，今复御风登会稽。","禹穴下窥正深黑，地老天荒知是非。","好峰高处偏薄雾，秋热苦时恰轻雨。","回头却望昭陵松，云气成龙或成虎。"]},{"t":"野炊白沙沙上","f":"七言律诗","c":["半日山行底路涂，欲炊无店籴无珠。","旋将白石支燃鼎，却展青油当野庐。","一望平田皆沃壤，只生枯苇与寒芦。","风餐露宿何亏我，玉馔琼楼合属渠。"]},{"t":"雪小霁顺风过谢阳湖","f":"七言古诗","c":["都梁三日雪没屋，小船行水如行陆。","山阳一朝帆遇风，大船行水如行空。","昨来牵夫冻得泣，买芦燎衣芦自湿。","朝来牵夫皆上船，收缆脱巾篷底眠。","楼船忽然生两翼，横飞直过阳侯国。","千村一抹片子时，四岸人家眼中失。","似闻咫尺是杨州，更数宝应兼高邮。","青天万里当径度，不堪回首都梁路。"]},{"t":"雪中送客过清水闸二首 其二","f":"七言绝句","c":["肩舆九步十倾欹，下有冰河不敢窥。","冰上水禽行似箭，忽逢缺处得鱼儿。"]},{"t":"雪中送客过清水闸二首 其一","f":"七言绝句","c":["雪中出去雪中回，深闭窗棂偶一开。","墙里人家扫檐瓦，玉尘打入轿窗来。"]},{"t":"雪后寻梅","f":"七言古诗","c":["去年看梅南溪北，月作主人梅作客。","今年看梅荆溪西，玉为风骨雪为衣。","腊前欲雪竟未雪，梅花不惯人间热。","横枝憔悴涴晴埃，端令羞面不肯开。","缟裙夜诉玉皇殿，乞得天花来作伴。","三更滕六驾海神，先遣东风吹玉尘。","梅仙晓沐银浦水，冰肤别放瑶林春。","诗人莫作雪前看，雪后精神添一半。"]},{"t":"雪后寄谢济翁材翁联骑来访进退格","f":"七言律诗","c":["封胡连璧雨中来，目送归鞍怅独回。","隐几读书寒入骨，开门落雪皓平阶。","急寻火阁温双手，自唤儿郎共一杯。","念汝野梅官柳路，地炉松叶买茅柴。"]},{"t":"雪后领儿辈行散","f":"五言古诗","c":["今日意不惬，出游聊逍遥。","父子自为伴，何须外招邀。","过溪足小倦，临流坐危桥。","回头顾吾庐，竹树翳草寮。","独有万花亭，岿然出山椒。","高陂泻溪水，环佩锵琼瑶。","飞流迸空起，平水和天摇。","舂淙到潭底，势尽自浮漂。","蟹眼沸不停，雪山涌还消。","近观绝汹汹，远听渐萧萧。","忽逢绿头公，携孥鼓丹桡。","喧呼苇间出，得意似见骄。","我行为小立，流鱼偶双跳。","人物各自适，兹游定谁超。"]},{"t":"雪后霜晴元宵月色特奇","f":"七言古诗","c":["玻璃盆泻琉璃水，素娥晚妆欲梳洗。","报道虚皇筑雪宫，一架半间三万里。","却嫌广寒未苦宽，要借新宫作上元。","先烦玉妃整羽卫，次遣青女褰云关。","渠侬旧有七宝藏，封在琼楼楼顶上。","中藏脑子万斛强，轻明片片梅花样。","急呼滕六取将来，更和端叶挼作埃。","狂抛乱撒不停手，满空碎下真珠胎。","乾坤立变水精阙，云衢透冷天街滑。","姮家催索水霜袍，肌粟衣铢添不彻。","银轮冻作一团冰，望舒堕指推不行。","兔啼蟾泣滴成露，海东飞上金鸦精。"]},{"t":"雪晓舟中生火二首 其二","f":"七言古诗","c":["乌银玉质金石声，见火忽学爆竹鸣。","腷腷膊膊久不停，白日坐上飞繁星。","不知何怒泄不平，不知何喜唧唧吟。","待渠自静勿与争，切莫借箸怒复生。","到渠缄口两耳热，铜瓶在旁却饶舌。"]},{"t":"雪晓舟中生火二首 其一","f":"七言古诗","c":["乌银见火生绿雾，便当水沉一浓炷。","却因断续更氤氲，散作霏微暖袍裤。","须臾雾霁吐红光，炯如云表升扶桑。","阳春和日曛满室，苍颜渥丹疑醉乡。","忽然火冷雾亦灭，只见红炉堆白雪。","窗外雪深三尺强，窗里雪深一寸香。"]},{"t":"雪晴","f":"五言律诗","c":["银色三千界，瑶林一万重。","新晴天嫩绿，落照雪轻红。","儿劣敲冰柱，身清堕蕊宫。","何须师鲍谢，诗在玉虚中。"]},{"t":"雪霁晓登金山","f":"词","c":["焦山东，金山西，金山排霄南斗齐。","天将三江五湖水，并作一江字杨子。","来从九天上，泻入九地底。","遇岳岳立摧，逢石石立碎。","乾坤气力聚此江，一波打来谁敢当。","金山一何强，上流独立江中央。","一尘不随海风舞，一砾不随海潮去。","四旁无蒂下无根，浮空跃出江心住。","金宫银阙起峰头，槌鼓撞钟闻九州。","诗人踏雪来清游，天风吹侬上琼楼，不为浮玉饮玉舟。","大江端的替人羞，金山端的替人愁。"]},{"t":"喜雨","f":"七言律诗","c":["欲知一雨惬群情，听取溪流动地声。","风乱万畴青锦褥，云摩千嶂翠瑶屏。","行人隔水遥相语，立鹭摧枝忽自惊。","岁岁只愁炊与酿，今愁无甑更无瓶。"]},{"t":"富阳晓望","f":"七言绝句","c":["江氛海雾暗前村，四望秋空一白云。","忽有数峰云上出，好山何故总无根。"]},{"t":"寒灯","f":"七言绝句","c":["老稚都眠我独醒，寒灯半点伴三更。","双花忽作蜻蜓眼，孤焰仍悬玉胆瓶。"]},{"t":"寒食上冢","f":"五言律诗","c":["径直夫何细，桥危可免扶。","远山枫外淡，破屋麦边孤。","宿草春风又，新阡去岁无。","梨花自寒食，时节只愁予。"]},{"t":"寒食日晨炊姜家林初程之次日也","f":"七言律诗","c":["百五佳辰匹似无，合教追节却离居。","万家寒食初归燕，一老春衫政蹇驴。","耄柳已僧何再发，孺槐才爪可迟蔬。","儿书早问归程日，不用嗔渠只笑渠。"]},{"t":"寒食对酒","f":"五言古诗","c":["荔支园园花，寒食日日雨。","先生老多病，颇已疏绿醑。","儿童喜时节，笑语治樽俎。","南烹俱前陈，北果亦草具。","蝤蛑方绝甘，笋蕨未作苦。","先生欲独醒，儿意难多拒。","初心且一杯，三杯亦漫许。","醒时本强饮，醉后忽快举。","一杯至三杯，一二三四五。","偶然问儿辈，卒爵是何处。","儿言翁但醉，已忘酒巡数。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其十","f":"七言绝句","c":["忽见金丝袅绮疏，又惊寒食到来初。","不知折尽西湖柳，插遍长安万户无。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其七","f":"七言绝句","c":["三峰小石一方池，下有机泉仰面飞。","坐看跳珠复抛玉，忽然一喷与檐齐。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其九","f":"七言绝句","c":["城里哦诗枉断髭，山中物物是诗题。","欲将数句了天竺，天竺前头更有诗。"]},{"t":"寒食雨中同舍约游天竺得十六绝句呈陆务观 其三","f":"七言绝句","c":["住山何敢望他僧，只是游山也不曾。","可惜一条杉桧路，都将湿了不教行。"]},{"t":"寓仙林寺待班戏题","f":"七言绝句","c":["听尽钟鱼半月声，浪传移住竟何曾。","莫教少欠丛林债，更作今宵旦过僧。"]},{"t":"惠山云开复合","f":"七言古诗","c":["二年常州不识山，惠山一见开心颜。","只嫌雨里不子细，髣髴隔帘青玉鬟。","天风忽吹白云坼，翡翠屏开倚南极。","政缘一雨染山色，未必雨前如此碧。","看山未了云复还，云与诗人偏作难。","我船自向苏州去，白云稳向山头住。"]},{"t":"惠州丰湖亦名西湖二首 其一","f":"七言绝句","c":["左瞰丰湖右瞰江，五峰出没水中央。","峰头寺寺楼楼月，清杀东坡锦绣肠。"]},{"t":"惠泉酒熟","f":"五言古诗","c":["敲冰汲山泉，炊玉酿霜醅。","忽然油成泓，失却琼作堆。","抱瓮输竹渠，挈瓶注银杯。","银杯不解饮，倾泻入我怀。","酒圣凡五传，道统到吾侪。","谁云孟氏醇，轲死不传来。","醉乡天张幕，糟丘曲为台。","吾欲往相宅，今夕未拟回。"]},{"t":"插秧歌","f":"七言律诗","c":["田夫抛秧田妇接，小儿拔秧大儿插。","笠是兜鍪蓑是甲，雨从头上湿到胛。","唤渠朝餐歇半霎，低头折腰只不答。","秧根未牢莳未匝，照管鹅儿与雏鸭。"]},{"t":"和陆务观见贺归馆之韵","f":"五言古诗","c":["君诗如精金，入手知价重。","铸作鼎及鼒，所向一一中。","我如驽并骥，夷涂不应共。","难追紫蛇电，徒掣青丝鞚。","折胶偶投漆，异榻岂同梦。","不知清庙茅，可望明堂栋。","平生怜坡老，高眼薄萧统。","渠若有猗那，心肯师晋宋。","破琴聊再行，新笛正三弄。","因君发狂言，湖山春已动。"]},{"t":"偶送西归朝天二集与尤延之蒙惠七言和韵以谢之","f":"七言律诗","c":["梁溪归自镜湖天，笔捲湖光入大篇。","倾出锦囊和雨湿，炯如柘弹走盘圆。","许分句法何曾付，自笑芜辞敢浪传。","两集不须求序引，祇将妙语冠陈编。"]},{"t":"游水月寺","f":"七言绝句","c":["烟日蔫云乍暑天，倦投山寺借床眠。","清凉世界谁曾到，却在红尘紫陌边。"]},{"t":"游蒲涧呈周帅蔡漕张舶","f":"词","c":["胜日从公蒲涧游，万壑声满千崖秋。","一径如蛇三百曲，绕尽山腹到山头。","穹岩千仞欹欲裂，仰看飞泉泻云窟。","锵成环佩奏成琴，溅作珠玑霏作雪。","步穿危磴攀苍藤，忽上穹岩顶上行。","人在半天泉在井，不敢下瞰惟闻声。","只怪前驱深不见，须臾却向前山转。","海风吹袖万丈长，海水去人一弓远。","老僧云卧晏未兴，先遣长松夹道迎。","小参古殿黄面老，不见旧日安期生。","景泰上方半堵壁，城中望之雪山白。","却从景泰望城中，晓日楼台焕金碧。","君不见中流千金博一壶，不如游山饥时粥一盂。","金印系肘大如斗，不如游山倦时一杯酒。","安期飞升今几年，祖龙不是不求仙。","至今年年七月二十五，倾城游人来访古。"]},{"t":"登乌石寺","f":"七言古诗","c":["回头身忽在树杪，一览千山万山小。","怪崖不落欹欲摧，令人仰看怯眼开。","小亭解事知侬倦，翼然飞出青山半。","上头最上却镜平，百亩金碧千衲僧。","高峰高寺更高阁，进步竿头若为脚。","兹游胜绝庸非天，山下虚行二十年。"]},{"t":"登度雪台","f":"七言绝句","c":["金沙岁岁占先回，不等荼糜一并来。","今岁香红与香雪，两花同日忽齐开。"]},{"t":"登度雪台观金沙荼?","f":"七言律诗","c":["金沙瓶子荼糜粟，一一尖红映圜绿。","只销三日雨和风，化作真珠堆锦褥。","饶渠飞度雪前开，开了却吹香雪来。","红红白白照天半，醉倚雕栏眼凌乱。"]},{"t":"登度雪台下临桃李径","f":"七言绝句","c":["桃花夹外李当中，三径花开两径红。","独绕画檐无个事，自携团扇扑黄蜂。"]},{"t":"登楚州城","f":"七言绝句","c":["望中白处日争明，个是淮河冻作冰。","此去中原三里许，一条玉带界天横。"]},{"t":"答赋永丰宰黄岩老投赠五言古句","f":"五言古诗","c":["吾友萧东夫，今日陈后山。","道肥诗弥瘦，世忙渠自闲。","不见逾星终，每思即凄然。","邻邑黄永丰，与渠中表间。","黄语似萧语，已透最上关。","道黄不是萧，萧乃堕我前。","佳句鬼所泣，盛名天甚悭。","诗人只言黠，犯之取饥寒。","端能不惧者，放君据诗坛。"]},{"t":"紫宸殿拜表贺雪二首 其二","f":"七言律诗","c":["稍缓鸣靴不住催，一声再拜忽如雷。","封章进了仪曹退，文武班齐上相来。","白发两年陪贺雪，紫衣数辈小传杯。","赐休退食端何恨，未到西湖探早梅。"]},{"t":"腊后二首 其一","f":"五言律诗","c":["待腊惊还过，留年惜欲除。","雨才三日有，雪更一冬无。","游屐妨缘泞，寒威恋为炉。","未须排旅闷，犹足助诗娱。"]},{"t":"腊前月季","f":"七言律诗","c":["只道花无十日红，此花无日不春风。","一尖已剥胭脂笔，四破犹包翡翠茸。","别有香超桃李外，更同梅斗雪霜中。","折来喜作新年看，忘却今晨是季冬。"]},{"t":"董主簿正道壁间作水墨老梅一枝宿鹊缩脰合半眼栖焉","f":"五言绝句","c":["斜枝饱风雪，疏花淡冰玉。","一鹊忍清寒，居然伴幽独。"]},{"t":"蒋莲店有书柳子厚寄吴武陵琴诗三读敬哦五言","f":"五言古诗","c":["秋晴得凉行，壁阅遇佳读。","已咽犹馀滋，将烬忽剩馥。","语妙古未多，听难今良独。","追诵惜去眼，信步遑拟足。","惊心一鸟鸣，隔溪两峰绿。"]},{"t":"谢丁端叔直阁惠永嘉髹研句容香鬲","f":"七言古诗","c":["元珍先生茁云孙，雪竹有节豹有文。","染云作句本天巧，镂冰生花无手痕。","鹓鹭行边旧联翼，天禄阁中今独直。","半竿淮水将渠归，一笑荆溪岂人力。","赠我阿泓非姓陶，木家居士漆园曹。","急呼陈玄导黑水，花晕千层吹海涛。","句容铜山捣金屑，幻出羽渊三足鳖。","两耳踰肩一腹皤，解吐黄云香刮骨。","双珍投赠感故人，秃翁有笔今无神。","杯水博诗元不直，酱瓿覆却那作嗔。","阿泓处分蛛丝裹，延置铜君居上坐。","煮茶剥芡对炉薰，遮莫白驹隙中过。"]},{"t":"谢尤延之提举郎中自山间惠访长句","f":"词","c":["淮南使者郎官星，瑞光夜烛荆溪清。","平生庞公不入城，令我折却屐齿迎。","交游云散别如雨，同舍诸郎半为土。","二老还将两鬓霜，三更重对孤灯语。","向来南宫绫锦堆，南窗北窗桃李开。","先生诵诗舌起雷，一字不似人间来。","剡藤染出梅花赋，句似梅花花似句。","几年金钥秘银钩，玉?不施恐飞去。","秋风呼酒荷边亭，主人自醉客自醒。","侬能痛饮渠不饮，饮与不饮俱忘形。","鬓今如霜心如水，功名一念扶不起。","侬归螺山渠惠山，来岁相思二千里。"]},{"t":"谢木韫之舍人分送讲筵赐茶","f":"七言古诗","c":["吴绫缝囊染菊水，蛮砂涂印题进字。","淳熙锡贡新水芽，天珍误落黄茅地。","故人鸾渚紫微郎，金华讲彻花草香。","宣赐龙焙第一纲，殿上走趋明月珰。","御前啜罢三危露，满袖香烟怀璧去。","归来拈出两蜿蜒，雷电晦冥惊破柱。","北苑龙芽内样新，铜围银范铸琼尘。","九天宝月霏五云，玉龙双舞黄金鳞。","老夫平生爱煮茗，十年烧穿折脚鼎。","下山汲井得甘冷，上山摘芽得苦硬。","何曾梦到龙游窠，何曾梦吃龙芽茶。","故人分送玉川子，春风来自玉皇家。","锻圭椎璧调冰水，烹龙庖凤搜肝髓。","石花紫笋可衙官，赤印白泥牛走尔。","故人气味茶样清，故人风骨茶样明。","开缄不但似见面，叩之咳唾金石声。","曲生劝人堕巾帻，睡魔遣我抛书册。","老夫七椀病未能，一啜犹堪坐秋夕。"]},{"t":"谢王恭父赠梁杲墨","f":"词","c":["君不见蜀人文字天下工，前有相如后扬雄。","君不见蜀人乌丸天下妙，前有蒲韶后梁杲。","初得梁墨黐摹糊，老夫道渠不及蒲。","蓬山藏室王校书，笑我未识真玄菟。","两圭水苍笏，双团点漆璧。","一并赠老夫，此意已金石。","洮州绿玉试松花，星潭黑云走风沙。","龙蛇起陆鹰入骨，却愁雷电夺神物。"]},{"t":"谢张功父送牡丹","f":"七言律诗","c":["病眼看书痛不胜，洛花千朵唤双明。","浅红酽紫各新样，雪白鹅黄非旧名。","抬举精神微雨过，留连消息嫩寒生。","蜡封水养松窗底，未似雕栏倚半酲。"]},{"t":"谢苏州史君张子仪尚书赠衣服送酒钱","f":"五言古诗","c":["香山老益窭，欲卖宅与田。","荆南赠春服，侍中送酒钱。","何如韦苏州，一日兼两贤。","酒钱随春服，并至南溪边。","寄物已不轻，意更在物先。","仆也拙生理，巧亦营不前。","病废非为高，抛官馀十年。","纸田蜗牛庐，纵卖谁作缘。","故人岂云少，衮衮青云端。","王弘不可作，范叔空自寒。","忽揽苏州书，冷窗回春暄。","急褫九月絺，径追八酒仙。","竹烟为我喜，波月为我妍。","篱菊冻不花，一笑亦粲然。","醉中化为蝶，飞堕虎丘山。","齐云已在眼，忽然远于天。"]},{"t":"谢邵德称示淳熙圣孝诗","f":"七言古诗","c":["古人浪语笔如椽，何人解把笔题天。","昆崙为笔点海水，青天借作一张纸。","作商猗那周皇矣，廷尉簿正邵夫子。","淳熙圣孝贯三光，题大如天谁敢当。","夫子一洒金玉章，银河吹笙间琳琅。","吉甫奚斯鸿雁行，彼何人哉唐漫郎。","夜来玉虫杂金粟，老夫春寒眠不足。","起来拾得圣孝诗，灯花阿那圣得知。"]},{"t":"谢陈希颜惠兔羓","f":"七言古诗","c":["东郭阿㕙驼褐裳，清腹不著烟火香。","姮娥唤入广寒殿，诏许捣药不许尝。","金丹炼成紫皇喜，玉臼自携银汉洗。","偷将缺吻吸琼浆，蜕尽骨毛作仙子。","鬓丝吹落桂枝风，人间封作管城公。","先生何许得尸解，貌如枯蟾带玄疥。","麒麟擘脯未必如，耶律晒羓差不大。","先生锦心冰雪肠，银钩珠唾千万章。","管城奔命困书囿，阿㕙漆身嬉醉乡。","老夫去年左车脱，匙抄烂饭犹戛戛。","太息再拜谢阿㕙，尚堪挂壁萦蛛尘，一饭瞻仰齿生津。"]},{"t":"谢岳大用提举郎中寄茶果药物三首 其二 紫团参","f":"七言律诗","c":["新罗上党各宗枝，有两曾参果是非。","入手截来花晕紫，闻香已觉玉池肥。","旧传饮子安心妙，新捣珠尘看雪飞。","珍重故人相问意，为言老矣只思归。"]},{"t":"谢亲戚寄黄雀","f":"七言古诗","c":["万金家书寄中庭，牍背仍题双掩并。","不知千里寄底物，白泥红印三十瓶。","瓷瓶浅染茱萸紫，心知亲宾寄乡味。","印泥未开出馋水，印泥一开香扑鼻。","江西山间黄羽衣，纯绵被体白如脂。","偶然一念随世网，身插两翼那能飞。","误蒙诸公相俎豆，月里花边一杯酒。","先生与渠元不疏，两年眼底不见渠。","端能访我荆溪曲，愿借前筹酌酃渌。"]},{"t":"谢胡子远郎中惠蒲大韶墨报以龙涎心字香","f":"七言古诗","c":["墨家者流老蒲仙，碧梧采花和麝烟。","华阳黑水煎胶漆，太阴玄霜作肌骨。","龙尾磨肌饮鼠须，落点髹几几不如。","夷甫清瞳光敌日，一见墨卿惊自失。","后来夔川有梁杲，尔来黟川有吴老。","亦追时好得时名，竟为蒲生竖降旌。","吴滋往往玄尚白，梁墨湿湿黐黏壁。","南宫先生来自西，惠然赠我四玄圭。","我无鹊返鸾回字，我无金章玉句子。","得君此赠端何似，兀者得靴僧得剃。","安得玉案双鸣珰，金刀绣段底物偿。","送似龙涎心字香，为君兴云绕明窗。"]},{"t":"谢唐德明惠笋","f":"七言古诗","c":["高人爱笋如爱玉，忍口不餐要添竹。","云何又遣十辈来，昏花两眼为渠开。","贩夫束缚向市卖，外强中乾美安在。","锦纹犹带落花泥，不论烧煮两皆奇。","猪肝累人真可怍，以笋累公端不恶。"]},{"t":"谢曹宗臣惠双溪集","f":"词","c":["君不见东阳沈隐侯，君不见宣城谢玄晖。","两处双溪清彻底，二子诗句清于溪。","千载却有曹夫子，天借古人作诗地。","家在东阳宝婺边，官在宣城莲幕里。","溪光滴作两眼明，溪秀吐作五字清。","开卷看来掩卷坐，词波跳作双溪声。","无人写作双溪操，收拾新篇句中妙。","莫将沈谢鸿雁行，便与猗那荐清庙。"]},{"t":"谢湖州太守王成之给事送百花春糟蟹","f":"七言古诗","c":["乌衣巷里批敕手，整顿乾坤渠尽有。","天风吹入水精宫，一夜阳和遍花柳。","爱杀苕溪波底云，揉云酿出蒲萄春。","更挼百花作香尘，小槽溅破真珠痕。","一杯吸尽太湖月，郡斋忽念山中客。","远浇白首草玄人，伯雅仲雅俱清绝。","一介不肯遣长须，却遣郭索持尺书。","二执戈者争走趋，登彼糟丘劝腹腴，可怜郭索与陆谞。","不傍贵人热门户，却访诚斋老病翁，多谢苕溪贤地主。"]},{"t":"谢福建茶使吴德华送东坡新集","f":"七言古诗","c":["黄金白璧明月珠，清歌妙舞倾城姝。","他家都有侬家无，却有四壁环相如。","此外更有一床书，不堪自饱饱蠹鱼。","故人远送东坡集，旧书避席皆让渠。","儿时作剧百不懒，说著读书偏起晚。","乃翁作恶嗔儿痴，强遣饥肠馋蠹简。","老来万事落人后，浪取故书遮病眼。","病眼逢书辄著花，笔下蝇头成老鸦。","病眼将奈故书何，故书一开一长嗟。","东坡文集侬亦有，未及终篇已停手。","印墨模糊纸不佳，亦非鱼网非科斗。","富沙枣木新雕文，传刻疏瘦不失真。","纸如雪茧出玉盆，字如霜雁点秋云。","老来两眼如隔雾，逢柳逢花不曾觑。","只逢书册佳且新，把玩崇朝那肯去。","东坡痴绝过于侬，不将一褐易三公。","只将笔头挂月胁，万古凡马不足空。","故人怜我老愈拙，不寄金丹扶病骨。","却寄此书来恼人，挑落青灯搔白发。"]},{"t":"谢谭德称国正惠诗","f":"词","c":["今年日瘦天不喜，玉皇颜惨方诸泪。","草木无光红紫迟，春半何曾有春意。","谁将好手挽春回，割取锦江春色来。","七星桥边杨柳动，百花潭上桃李开。","乃是国子先生赠诗卷，笔下东风随手转。","君不见李家谪仙吟掉头，解道峨眉山月半轮秋。","又不见苏家老仙冰啄句，更说只恐夜深花睡去。","先生办著锦绣肠，朅来西湖山水乡。","乞君湖山入诗囊，法嗣两仙一瓣香。"]},{"t":"谢襄阳帅杨侍郎用辘轳体","f":"七言律诗","c":["合志同宗忆嗣清，寻盟继好感难兄。","关西伯起今夫子，后世子云重易经。","金薤银钩诒妙墨，貂裘玉札寄交情。","本朝未有杨家相，留待公归两两星。"]},{"t":"赋金盘露椒花雨","f":"七言古诗","c":["金盘夜贮云表露，椒花晓滴山间雨。","一涓不用鸭绿波，双清酿出鹅黄乳。","老妻知我憎官壶，还家小槽压真珠。","江西担取来西湖，遣我醉倒不要扶。","更携数尊往淮上，要誇亲旧尝家酿。","祗堪独酌不堪分，老夫犹要入脩门。"]},{"t":"赋益公平园牡丹白花青缘","f":"七言律诗","c":["东皇封作万花王，更赐珍华出尚方。","白玉杯将青玉缘，碧罗领衬素罗裳。","古来洛口元无种，今去天心别得香。","涂改欧家记文著，此花未出说姚黄。"]},{"t":"跋马公弼省干出示山谷草圣浣花醉图歌","f":"七言古诗","c":["涪翁浣花醉图歌，歌词自作复自写。","少陵无人张颠死，此翁奄有二子者。","不论钗股与锥沙，更数旱蛟及惊蛇。","诗仙不合兼草圣，鬼妒天嗔教薄命。","人言爱书缘爱贤，紫眉未必胜青编。","旧时鬼门关外客，如今一字抵尺璧，何须千载空相忆。"]},{"t":"跋尤延之左司所藏光尧御书歌","f":"词","c":["鸾台长史老野僧，月前病鹤霜后蝇。","文书海里衮不了，黑花乱发双眼睛。","故人同舍尤太史，敲门未揖心先喜。","袖中倾下十斛珠，五色光芒射窗几。","自言天风来帝旁，拾得复古殿中云一张。","向来太上坐朝罢，胜日光风花柳暇。","浣花仄理冰雪容，宣城鸡距针芒锋。","天颜有喜聊小试，西京书目供游戏。","韩彭卫霍欣挂名，舒向卿云感书字。","汉廷多少失意人，九京寸恨不作尘。","一朝翻入圣笔底，昭回之光唤渠起。","小臣滥巾缝掖行，手抄孝经不彻章。","何曾下笔写史汉，再拜恭览汗透裳。","太史结庐伴鸥鹭，锡山山下荆溪渡。","红光紫气上烛天，个是深藏宝书处。"]},{"t":"跋王顺伯所藏欧公集古录序真迹","f":"词","c":["遂初欣遇两诗伯，临川先生一禅客。","三人情好元不疏，祇是相逢逢不得。","渠有贞观碑，侬有永和词。","真赝争到底，未说妍与蚩。","珊瑚击得如粉碎，赵璧博城翻手悔。","不似三家斗断碑，夜半战酣莫先退。","皇朝爱碑首欧阳，集古万卷六一堂。","玄圭漆玉堆墨宝，黟霜黑水涂缁裳。","临川无端汲古手，席卷欧家都奄有。","岣山科斗不要论，峄山野火不经焚。","尤家沈家喙如铁，未放临川第一勋。","不知临川何许得尤物，集古序篇出真笔。","遂初心妒口不言，君看跋语犹怅然。"]},{"t":"跋丘宗卿侍郎见赠使北诗一轴","f":"词","c":["太行界天二千里，清晨跳入寒窗底。","黄河动地万壑雷，却与太行相趁来。","青崖颠狂白波怒，老夫惊倒立不住。","乃是丘迟出塞归，赠我大轴出塞诗。","手持汉节娖秋月，弓挂天山鸣积雪。","过故东京到北京，泪滴禾黍枯不生。","誓取胡头为饮器，尽与遗民解魋髻。","诗中哀怨诉阿谁，河水呜咽山风悲。","中原万象听驱使，总随诗句归行李。","君不见晋人王右军，龙跳虎卧笔有神。","何曾哦得一句子，自哦自写传世人。","君不见唐人杜子美，万草千花句何绮。","祗以诗传字不传，却羡别人云落纸。","莫道丘迟一轴诗，此诗此字绝世奇。","再三莫遣鬼神知，鬼神知了偷却伊。"]},{"t":"跋写真刘敏叔八君子图","f":"五言律诗","c":["一代一两人，国已九鼎重。","如何八君子，一日集吾宋。","古人三不朽，诸老一一中。","久别忽相逢，相对恍如梦。"]},{"t":"跋吴箕秀才诗卷","f":"词","c":["君家子华翰林老，解吟芳草夕阳愁。","开红落翠天为泣，覆手作春翻手秋。","晚唐异味今谁嗜，耳孙下笔参差是。","一径芙蓉十万枝，唤作春风二月时。","旁人笑渠眼花恐落井，渠方掉头得句呼不醒。","老夫向来守荆溪，郡有诗人元不知。","赠我连城杂照乘，一夜空斋横白蜺。"]},{"t":"跋京仲远所藏杨补之红绫上所作著色掀篷梅","f":"词","c":["朔云暗天垂到地，朔风裂山吹脱耳。","长江万顷一艇子，一夜雪寒不成睡。","诗翁晓起鬓髼松，缩颈微掀黄篾篷。","夜来急雪已晴了，东方一抹轻霞红。","江梅的皪开独树，篷间截入梅尺许。","老干新枝紫复青，花雕白玉须黄金。","满身满面都是雪，梅雪却与霞争明。","不知诗翁何处得霜锯，和雪和梅斸将去。","恐是并州快剪刀，不然吴刚修月斧。","下无根干上无梢，一眼横陈梅半腰。","东省拈出寒萧萧，至今花头雪未销。"]},{"t":"跋忠敏任公遗帖","f":"七言绝句","c":["市中货鸩作参苓，遮莫秦和苦口争。","杀尽苍生消底物，卞京两把老蔓菁。"]},{"t":"跋罗春伯所藏高氏乐毅论","f":"词","c":["右军乐毅论，大令洛神赋。","王家小楷天取将，祗馀惊鸾尚双翥。","昭陵银海閟银钩，秦王卧看偷儿偷。","秣陵井苔剥山骨，祝融复遣山鬼搜。","裂琼划玉各分散，遗下宝圭三五段。","墨卿收拾骊颔珠，仅仅一百八十馀。","江西今代韩吏部，古心古道生好古。","雷电勃兴急捉取，阿那精灵会飞去。"]},{"t":"跋眉山程仁万言书草","f":"词","c":["峨眉山下三苏乡，至今草木文章香。","近时英妙有程郎，数寸管底翻锦江。","向来曾草三千牍，流涕太息仍痛哭。","九虎当关北斗深，十年买桂炊白玉。","荆溪溪上相识初，君犹少年我壮夫。","帝城再见各白须，袖中一纸梁溪书。","剡藤方策一万字，犹带权书衡论味。","君不见古来富贵扫无痕，只有文章照天地。"]},{"t":"跋袁起岩所藏后湖帖并遗像一轴诗中语皆檃括帖中语也","f":"词","c":["先生向来落异县，故人十载不相闻。","归来不但荒三径，点检松菊无一存。","裹轮加璧岂不好，朝廷礼数优遗老。","红旗黄纸久罢休，青山白云苦死留，咫尺西冈归未得。","只待桃花水生半篙碧，便拿短艇归结茅，共寻赤松与黄石。","风烟之表非人间，别有天地宽且闲。","周山卖却不要钱，袁家送酒一破颜。","犹嫌孤斟太落莫，更觅高人共杯杓。","银钩四纸墨尚鲜，妙处难与俗人言。","忽逢先生自天降，手扶太一青藜杖。","仙容可望不可亲，飘然飞去青霞上。","白蘋满棹何时归，秋著芦花知不知。"]},{"t":"跋符发所录上蔡语二首 其一","f":"七言绝句","c":["洙泗渊源一线寒，再从伊洛起涛澜。","偶看上蔡先生语，满目淙淙八节滩。"]},{"t":"跋葛子固题苏道士江行图","f":"七言绝句","c":["江行图上指君山，寄语烟波不用看。","蒸水买船归霅水，全家搬入画图间。"]},{"t":"跋蜀人魏致尧抚干万言书","f":"七言绝句","c":["雨里短檠头似雪，客间长铗食无鱼。","上书恸哭君何苦，政是时人重子虚。"]},{"t":"过宝应县新开湖十首 其八","f":"七言绝句","c":["天上云烟压水来，湖中波浪打云回。","中间不是平林树，水色天容拆不开。"]},{"t":"遍游庐山示万杉长老大琏","f":"五言古诗","c":["肩舆小斑筠，地志古青册。","初穿千长松，忽仰万绝壁。","观山不知名，披志失山色。","行行问不住，一一渐可识。","何代五老人，登峰化为石。","年龄今几春，齿牙谅无力。","天赐五玉乳，与渠供朝食。","渊明醉眠处，石上印耳迹。","逸少养鹅池，藓花渍馀墨。","鹤鸣南天青，龟拜北斗白。","栖贤缘不浅，月枕借云席。","万杉与开先，弄泉碎珠璧。","病眸贪穷眺，趼趾怯周历。","同游多俊人，淡话半禅伯。","兹来殆天假，不尔岂人及。","归船载晓星，回首两相忆。"]},{"t":"道傍小松","f":"五言律诗","c":["小松如小儿，能坐未能立。","乱发覆地皮，劲气排雪汁。","谁将救暍手，种此青戢戢。","秋阳暴行人，清荫何时及。"]},{"t":"道傍小桃","f":"七言绝句","c":["吹尽残桃无可残，也无地上落花痕。","独行寻到青苔处，拾得嫣红一片看。"]},{"t":"道旁竹","f":"五言绝句","c":["竹竿穿竹篱，却与篱为柱。","大小且相依，荣枯何足顾。"]},{"t":"微雨玉井亭观荷","f":"五言古诗","c":["猛雨打万荷，怒声战秋鼙。","水银忽成泓，一写无复遗。","不如微雨来，翠盘万珠玑。","荷翻珠不落，细响密更稀。","清如雪触窗，三更梦闻时。","语君君不信，对境当自知。"]},{"t":"感秋五首 其五","f":"五言古诗","c":["平生畏长夏，一念愿清秋。","如何遇秋至，不喜却成愁。","书册秋可读，诗句秋可搜。","永夜宜痛饮，旷野宜远游。","江南万山川，一夕入寸眸。","请办双行缠，何处无一丘。"]},{"t":"感秋五首 其四","f":"五言古诗","c":["秋晓寒可忍，秋夕永难度。","青灯照书册，两眼如隔雾。","掩卷却孤坐，块然与谁语。","倒卧卧不得，起行行无处。","屋角忽生明，山月到庭户。","似怜幽独人，深夜约清晤。","我吟月解听，月转我亦步。","何必更读书，且与月联句。"]},{"t":"感秋五首 其三","f":"五言古诗","c":["隤照趣夕黯，孤灯启宵明。","老夫倦欲睡，似醉复如醒。","寸心无寸恨，坦如江海清。","秋蛩何为者，四面作怨声。","凄恻竟未已，抑扬殊不平。","切切百千语，递递三四更。","绕砌寻不得，静坐复争鸣。","有口汝自苦，我醉不汝听。"]},{"t":"感秋五首 其二","f":"五言古诗","c":["盥漱已云毕，危坐正冠衣。","揽镜忽见我，不识我为谁。","自倚身尚强，不悟年已衰。","举头视嘉木，向人惨无姿。","我欲诉渠老，渠乃怀秋悲。","木悲不解饮，瑟瑟声怨咨。","我且呼曲生，细细斟酌之。","我醉不知我，更知春秋为。"]},{"t":"感秋五首 其一","f":"五言古诗","c":["昨扇犹午携，今裳觉晨单。","起来且复卧，未敢窥柴关。","不知病至此，为复老使然。","平生性刚燥，畏热长喜寒。","念昔忝乡赋，践雪诣春官。","布褐背不纩，芒鞋茧且穿。","长亭夜濯足，吹灯呻故编。","买酒破孤闷，浩歌殷屋椽。","何曾悲廪秋，山棱耸臞肩。","秋风吹我髓，秋露滴我肝。","我欲与秋敌，秋先令我酸。","叹息复叹息，谁是长少年。"]},{"t":"新秋晚酌","f":"五言古诗","c":["胡床东乡坐，秋风忽凄其。","老夫衰病骨，急令闭东扉。","西扉亦半掩，压风作东吹。","何必风及我，风入凉自驰。","晚蝉见谁说，我饮渠便知。","飞从何方来，径集庭树枝。","三叹复九咏，话尽新秋悲。","我老悲已忘，汝语复为谁。","老乌啼一声，不知蝉所之。"]},{"t":"新凉","f":"七言绝句","c":["毛空两日散霏微，勒住阴云且四垂。","一路新凉君会否，晴无日色雨无泥。"]},{"t":"新凉五言呈尤延之","f":"五言古诗","c":["暑极无可增，夏馀亦复几。","幽人暍欲腊，日日望秋至。","秋至凉不随，夏去热未已。","一夕睡美馀，秋从簟波起。","新凉来何方，洒若清到髓。","夕前轻雨作，雨后微风駃。","凉偶与之偕，未必凉因此。","向来亦风雨，既止暑更倍。","但令暑为凉，老病有生意。","何必问所来，亦莫悲徂岁。"]},{"t":"新酒歌","f":"词","c":["酸酒齑汤犹可尝，甜酒蜜汁不可当。","老夫出奇酿二缸，生民以来无杜康。","桂子香，清无底。","此米不是云安米，此水祗是建邺水。","瓮头一日绕数巡，自候酒熟不倩人。","松槽葛囊才上榨，老夫脱帽先尝新。","初愁酒带官壶味，一杯径到天地外。","忽然玉山倒瓮边，只觉剑铓割肠里。","度撰酒法不是侬，此法来自太虚中。","酒经一卷偶拾得，一洗万古甜酒空。","酒徒若要尝侬酒，先挽天河濯渠手。","却来举杯一中之，换君仙骨君不知。"]},{"t":"新寒戏简尤延之检正","f":"七言律诗","c":["逗晓添衣并数重，隔晡剩热尚斜红。","秋生露竹风荷外，寒到云窗雾閤中。","半点暄凉能几许，古来豪杰总成空。","木犀香杀张园了，雪嗅金挼欠两翁。"]},{"t":"新路店道中","f":"七言律诗","c":["去秋行部惨山容，得似春山意态浓。","嫩绿峰当新雨后，乱红花发烂晴中。","仙姿玉骨丹青写，雾鬓风鬟锦绣幪。","染得笔头生五色，急将描取入诗筒。"]},{"t":"新霜","f":"七言律诗","c":["得得今年未有寒，天公小靳不全判。","欲呈瑞雪飞花样，先遣浓霜起草看。","瓦脊生尘总琼玉，梅梢著粉忽琅玕。","老夫到老嫌冬热，十指朝来出袖难。"]},{"t":"暖热两生行","f":"七言古诗","c":["秃颖冻得须作冰，老泓饮汤成水精。","先生定交两书生，两生号寒语不能。","先生自作饥虫鸣，夜檄祝融战玄冥。","更遣红玉十麒麟，相与部领有脚春，暖热两生出精神。","两生炙手泪纵横，彊和先生仄仄平。"]},{"t":"瑞庆节日同王式之诣云际寺满散","f":"七言律诗","c":["金刹深藏翠巘间，钟声吹下白云端。","谁知东浙能诗客，也到南溪祝圣山。","重碧清池染衣湿，软红香雾袭人寒。","祝君来岁千秋节，著脚含元鹓鹭班。"]},{"t":"瑞香","f":"七言律诗","c":["买断春光与晓晴，幽香逸艳独婷婷。","齐开忽作栾枝锦，未坼犹疑紫素馨。","绝爱小花和月露，折将一朵篸银瓶。","今年偶忆年时句，倦倚彫栏酒半醒。"]},{"t":"瑞香盛开呈益国公二首 其二","f":"七言律诗","c":["针来大笋束仍攒，作么开时色两般。","荀令金炉炷沉水，昭容紫袖衬中襌。","同花异叶株株异，一种栾枝节节栾。","雪里寒香得三友，溪边梅与畹边兰。"]},{"t":"瑞香盛开呈益国公二首 其一","f":"七言律诗","c":["近看丁香万粒攒，远看却与紫毬般。","谁将玉胆蔷薇水，新濯琼肤锦绣襌。","净界薰脩尔芬馥，无人剪剔自团栾。","下元前至上元后，省得龙沉与麝兰。"]},{"t":"督诸军求盗梅州宿曹溪呈叶景伯陈守正溥禅师","f":"七言律诗","c":["南斗东偏第一山，白头初得扣禅关。","祖衣半似云来薄，金钥才开雾作团。","一钵可能盈尺许，千年有底万人看。","今宵雪乳分龙焙，明日黄泥又马鞍。"]},{"t":"筠庵","f":"五言古诗","c":["故老谈李仙，晋日上寥廓。","随身无长物，止跨一只鹤。","鹤本非胎生，古卵尚遗壳。","千年石似坚，覆在凤山脚。","寒宵晦风雨，神光照岩壑。","犬嘷鸡夜鸣，龙泣人寝愕。","祇今筠庵是，因物非绳削。","当时抱破处，作门不关钥。","盖以一把茅，聊以护霜雹。","遐瞻如钓翁，蓑衣逐层著。","我来验幽讨，意尚疑谚谑。","雾中披羽衣，砌下脱芒屩。","入户环仰观，中空生响诺。","不见朱顶雏，犹存雪色膜。","松梢双老鹳，戛然下檐角。","老夫忽心惊，不敢小盘礴。"]},{"t":"筠庵午憩","f":"五言古诗","c":["筠庵稍不至，一至一回好。","风从林梢落，吹乱竹根草。","巾屦上下凉，莺鹊左右噪。","市声元不近，静听远亦到。","石磴坐来温，藓径净如扫。","书空作愁字，已忘偏旁了。","犹自忘了愁，而况记得老。","客来谈世事，欲笑还懒笑。"]},{"t":"蜂儿","f":"词","c":["蜜蜂不食人间仓，玉露为酒花为粮。","作蜜不忙采花忙，蜜成犹带百花香。","蜜成万蜂不敢尝，要输蜜国供蜂王。","蜂王未及享，人已割蜜房。","老蜜已成蜡，嫩蜜方成蜜。","蜜房蜡片割无馀，老饕更来搜我室。","老蜂无味祗有滓，幼蜂初化未成儿。","老饕火攻不知止，既毁我室取我子。"]},{"t":"解舟棠阴砦","f":"五言古诗","c":["湖尽有残渺，情知无博澜。","纵眺犹杳空，至竟济者安。","回思遇险时，分晷过亦难。","亦岂有奇画，死生听之天。","安知天矜否，此外无控抟。","一风动旬月，三日忽自阑。","未涉浪自怖，既涉焉用驩。","畏涂已数践，老命偶再全。","还家切勿诉，空遗儿女潸。","亦勿诉同列，同列已预言。"]},{"t":"遣骑迎家久稽来讯","f":"五言古诗","c":["还家家尚缅，迎家家未来。","去住两不知，安否更相猜。","偶思十年事，谁谓今岁乖。","始我离高安，述职朝天街。","中外理难必，骨肉心与偕。","同室忽分涂，老情非不怀。","入京就一列，汲汲营尺榱。","墙屋亟求完，妇子岂我催。","前知来期杳，更用辛苦为。","属以王事出，寒舲如江淮。","风霜厉宵泳，山水荐晓瑰。","六朝几宿草，事往空馀哀。","梦收儿女书，喜极睫为开。","一欣虽非实，差慰肠九回。","归帆拂惠山，良讯传荆涯。","启缄复非真，旅思弥不佳。","船门且看雪，呼僮涤荷杯。"]},{"t":"雾中见灵山依约不真","f":"七言绝句","c":["东来两眼不曾寒，四顾千峰掠晓鬟。","天欲恼人消几许，只教和雾看灵山。"]},{"t":"暮经新丰市望远山","f":"五言律诗","c":["小市寒仍静，斜阳澹欲晡。","偶看平野去，不是远山无。","处处遮船住，家家有酒酤。","朱楼临碧水，曾驻玉銮舆。"]},{"t":"暮宿半涂","f":"五言古诗","c":["朝日在我东，夕日在我西。","我行日亦行，日归我未归。","势须就人宿，远近或难期。","平生太疏放，似黠亦似痴。","如何今日行，不以衾枕随。","幸逢春小暄，倒睡莫解衣。","借令今夕寒，我醉亦不知。"]},{"t":"榕树","f":"七言绝句","c":["直不为楹圜不轮，斧斤亦复赦渠薪。","数株连碧真成菌，一胫空肥总是筋。"]},{"t":"题漱玉亭示开先长老师序","f":"七言律诗","c":["山根玉泉仰面飞，飞出山顶却下驰。","自从庐阜泻双练，至今银湾乾两支。","雷声惊裂龙伯眼，雪点溅湿姮娥衣。","寄言苏二李十二，莫愁瀑布无新诗。"]},{"t":"碧落洞前滩水三首 其三","f":"七言绝句","c":["碧落峰前上一滩，篙师叫得口都乾。","开门将谓船行远，只在峰头芦荻湾。"]},{"t":"碧落洞前滩水三首 其一","f":"七言绝句","c":["水知山近已先狂，箭往星奔趁下泷。","滩下洄流能耐事，漩沤百转看它忙。"]},{"t":"碧落堂晓望荷山","f":"五言古诗","c":["荷山非不高，城里自不见。","一登碧落堂，山色正对面。","如人卧平地，跃起立天半。","指挥出伏兵，万骑横隔岸。","后乘来未已，前驱瞻已远。","晨光到岩壑，人物俱茜绚。","绿屏纷开阖，翠旗闪舒卷。","安得垂天虹，桥虚度云巘。","老铃偶报事，郡庭集宾赞。","匆匆换山巾，默默下林坂。"]},{"t":"碧落堂暮景辘轳体","f":"七言律诗","c":["碧落堂中夕眺馀，一声哀角裂晴虚。","满城烟霭忽然合，隔水人家恰似无。","坐看荷山沉半脊，急归道院了残书。","意行花底寻灯处，失脚偏嗔小史扶。"]},{"t":"端午病中止酒","f":"七言绝句","c":["病里无聊费扫除，节中不饮更愁予。","偶然一读香山集，不但无愁病亦无。"]},{"t":"蜡梅","f":"七言绝句","c":["天向梅梢别出奇，国香未许世人知。","殷勤滴蜡缄封却，偷被霜风拆一枝。"]},{"t":"酴醾","f":"七言律诗","c":["以酒为名却谤他，冰为肌骨月为家。","借令落尽仍香雪，且道开时是底花。","白玉梢头千点韵，绿云堆里一枝斜。","休休莫斸西庄柳，放上松梢分外佳。"]},{"t":"酷暑观小僮汲水浇石假山","f":"七言律诗","c":["堂后檐前小石山，一峰瘦削四峰攒。","忽腾绝壁三千丈，飞下清泉六月寒。","乃是家僮聊戏事，倒倾古井作惊湍。","老夫畏热年来甚，更借跳珠裂玉看。"]},{"t":"嘲淮风进退格","f":"七言律诗","c":["絮帽貂裘莫出船，北窗最紧且深关。","颠风无赖知何故，做雪不成空自寒。","不去扫清天北雾，只来捲起浪头山。","便能吹倒僧伽塔，未直先生一笑看。"]},{"t":"嘲道旁枫松相倚","f":"七言古诗","c":["双枫一松相后前，可怜老翁依少年。","少年翡翠新衫子，老翁深衣青布被。","更看秋风清露时，少年再换轻红衣。","莫教一夜霜雪落，少年赤立无衣著，老翁深衣却不恶。"]},{"t":"德寿宫庆寿口号 其七","f":"七言绝句","c":["花外班行雾外天，何缘子细望龙颜。","小窥玉色真难老，底用臞仙九转丹。"]},{"t":"德远叔坐上赋肴核八首 其三 蔊菜","f":"七言绝句","c":["齑臼文辞粲受辛，子牙为祖芥为孙。","劝君莫谒独醒客，只谒高阳社里人。"]},{"t":"德远叔坐上赋肴核八首 其四 蜜金橘","f":"七言绝句","c":["风餐露饮橘洲仙，胸次清于月样圜。","侠客偶遗金弹子，蜂王撚作菊花钿。"]},{"t":"德远叔坐上赋肴核八首 其七 糖霜","f":"七言绝句","c":["亦非崖蜜亦非饧，青女吹霜冻作冰。","透骨清寒轻著齿，嚼成人迹板桥声。"]},{"t":"德远叔坐上赋肴核八首 其五 藕","f":"七言绝句","c":["荷衣芰制雪为容，家住云烟太华峰。","外面看来真璞玉，胸中雕出许玲珑。"]},{"t":"横山江岸","f":"七言绝句","c":["近船古岸不胜高，浪划涛剜似削刀。","层石层砂层腻土，僧厨蒸出栗黄糕。"]},{"t":"樱桃煎","f":"五言古诗","c":["含桃丹更圜，轻质触必碎。","外看千粒珠，中藏半泓水。","何人弄好手，万颗捣虚脆。","印成花钿薄，染作冰澌紫。","北果非不多，此味良独美。"]},{"t":"蕈子","f":"七言古诗","c":["空山一雨山溜急，漂流桂子松花汁。","土膏松暖都渗入，蒸出蕈花团戢戢。","戴穿落叶忽起立，拨开落叶百数十。","蜡面黄紫光欲湿，酥茎娇脆手轻拾。","响如鹅掌味如蜜，滑似莼丝无点涩。","伞不如笠钉胜笠，香留齿牙麝莫及。","菘羔楮鸡避席揖，餐玉茹芝当却粒。","作羹不可疏一日，作腊仍堪贮盈笈。"]},{"t":"蕙花初开五言","f":"五言古诗","c":["幽人非爱山，出山将何之。","山居种兰蕙，岁寒久当知。","初艺止百亩，馀地惜奚为。","先生无广居，千岩一茅茨。","四面祇艺蕙，中间才置锥。","锐绿纷宿丛，脩紫擢幼枝。","孤干八九花，一花破初蕤。","西风澹无味，微度成香吹。","灯梦得幽馥，月写传静姿。","我欲掇芳英，和露充晨炊。","眷然恻不忍，环玩自忘饥。","岂无众花草，不愿秋不迟。","种时乱不择，岁晚悔可追。"]},{"t":"豫章王集大成惠我思古人实获我心八诗谢以五字","f":"五言古诗","c":["孤嗜难众悦，今听非昔弦。","美人西山秀，蕨茹饮涧泉。","雪蓑韫明月，冰棹刺野船。","宝祲耿不掩，球声忽复珊。","闻者已瞠若，鬻之谅悠然。","良瑰彼何憎，击缶俗所便。","老我讵能聪，妙音误至前。","古人子所思，而我岂古贤。","借不满子赏，能不聊子叹。","故家富彦士，梧竹映芝兰。","紫馀乃祖橐，朱遍群从轓。","迅趾岂地行，逸翎当云鶱。","勖哉抟羊角，何必怀西山。"]},{"t":"豫章光华馆苦雨","f":"五言古诗","c":["阻水水不退，苦雨雨不收。","天不遣人行，我岂愿此留。","客间亦何娱，胜践或销忧。","西山天下奇，东湖尘外幽。","驾言欲一往，雨湿且复休。","怀哉滕王阁，咫尺城南陬。","举武便可至，登临亦无由。","平陆幻成海，高屋瞬失楼。","南浦水正长，何时放归舟。"]},{"t":"醉后题壁","f":"七言绝句","c":["夜寒星斗挂屋椽，我辈把酒不问天。","语声未怕惊天上，只愁惊起白鸥眠。"]},{"t":"醉吟","f":"词","c":["古人亡，古人在，古人不在天应改。","不留三句五句诗，安得千人万人爱。","今人只笑古人痴，古人笑君君不知。","朝来暮去能几许，叶落花开无尽时。","人生须要印如斗，不道金槌控渠口。","身前只解皱两眉，身后还能更杯酒。","李太白，阮嗣宗，当年谁不笑两翁。","万古贤愚俱白骨，两翁天地一清风。"]},{"t":"醉卧海棠图歌赠陆务观","f":"词","c":["帝城二三月，海堂一万株。","向来青女拉滕六，戏与一撼即日枯。","东皇夜遣司花女，手挼红蓝滴清露。","染成片片净练酥，乱点梢梢酣日树。","蓬莱仙人约老翁，寄笺招唤陆龟蒙。","为花一醉也不惜，就中一事最奇特。","海棠两岸绣帷裳，是间横著双胡床。","龟蒙踞床忽倒卧，乌纱自落非风堕。","落花满面雪霏霏，起来索笔手如飞。","卧来起来都是韵，是醉是醒君莫问。","好个海棠花下醉卧图，如今画手谁姓吴。"]},{"t":"醉笔呈尚长道","f":"七言古诗","c":["晚风一雨生新涨，只送仙槎到天上。","十年相别一相逢，和气春风谈笑中。","如今耆旧晨星似，犹及先生说遗事。","舌端往往疏九河，只有剩浪无欠波。","汉渠周柱几青竹，却在先生一泓腹。","诸公道是今乏才，如何此士尚尘埃。","此行青规更黄阁，拭目孤鸿径寥廓。","能念南溪病客无，风来肯寄半行书。"]},{"t":"镊白","f":"五言绝句","c":["止酒愁无那，哦诗意已阑。","镊髭非急务，也遣半时闲。"]},{"t":"题十里塘夜景","f":"五言律诗","c":["物色当秋半，登临更夜阑。","山光倒眠水，水影上摇山。","宿鹭都飞去，渔人独未还。","老夫与明月，分割一清湾。"]},{"t":"题子文弟南溪奇观","f":"七言律诗","c":["行尽三江与五湖，江湖元只近吾居。","一陂秋水镕银汁，万里青天落玉壶。","每约弟兄人定后，恣看风露月来初。","老夫诗句休拈出，漏泄南溪奇观图。"]},{"t":"题小沙溪郑氏店江亭","f":"七言绝句","c":["隔水千山又万山，大江仍合小溪湾。","岸巾独立东风里，眼趁凫雏下急滩。"]},{"t":"题分宜李少度燕谷","f":"词","c":["君不见向来吹律谈天衍，能令寒谷回春暖。","君不见祗今桂山谢艮斋，能回燕谷为春台。","谪仙耳孙有仙骨，家传谪仙好风月。","斸开别墅一谷中，管领春光醉烟雪。","艮斋作记印此山，山与主人千载传。","谷中花柳莫放过，乞取风月三千篇。"]},{"t":"题太和主簿赵昌父思隐堂","f":"七言古诗","c":["西昌主簿如禅僧，日餐秋菊嚼春冰。","西昌官舍如佛屋，一物也无唯有竹。","俸钱三月不曾支，竹阴过午未晨炊。","大儿叫怒小儿啼，乃翁对竹方哦诗。","诗人与竹一样瘦，诗句与竹一样秀。","故山苍玉摇绿云，月梢风叶最关身。","劝渠未要思旧隐，且与西昌作好春。"]},{"t":"题文发叔所藏潘子真水墨江湖八境小轴 其二 武昌春色","f":"五言绝句","c":["花外庾楼月，莺边吴宫柳。","我欲问废兴，春风独无口。"]},{"t":"题无讼堂屏上袁安卧雪图","f":"五言古诗","c":["云窗避三伏，竹床横一丈。","退食急袒跣，病身聊偃仰。","有梦元无梦，似想亦非想。","满堂变冥晦，寒阴起森爽。","门外日如焚，屏间雪如掌。","萧然耸毛发，皎若照襟幌。","拔地排瑶松，倚天立银嶂。","遥见幽人庐，茅栋压欲响。","有客叩柴门，高轩隘村巷。","剥啄久不闻，徙倚觉深怅。","幽人寐政熟，何知有令长。","谁作卧雪图，我得洗炎瘴。"]},{"t":"题水月寺寒秀轩","f":"七言律诗","c":["小寺深门一径斜，绕身萦面总烟霞。","低低檐入低低树，小小盆盛小小花。","经藏中间看佛画，竹林外面是人家。","山僧笑道知侬渴，其实迎宾例瀹茶。"]},{"t":"题王子宣主簿青山读书堂","f":"七言律诗","c":["谢家青山李家据，王家青山当家住。","上头新作读书堂，牙签玉轴古锦囊。","万夫攘臂侬掉臂，万事无味书有味。","时挑野菜煮一字，儿辈不须来染指。"]},{"t":"题王才臣南山隐居六咏 其四 竹亭","f":"五言绝句","c":["春亦只如是，冬亦只如是。","别有一清风，请君参此味。"]},{"t":"题王才臣南山隐居六咏 其二 格斋","f":"五言绝句","c":["读书轮何知，问羊马何与。","二理仍两心，终无研究处。"]},{"t":"题王才臣南山隐居六咏 其六 腴亭","f":"五言绝句","c":["蜀张与蜀花，乡人相解后。","人存花更腴，人去花亦瘦。"]},{"t":"题王亚夫检正岘湖堂","f":"七言律诗","c":["西岘山光照旧庐，北湖水色漾新居。","翠鬟夜欲凌波去，玉镜晨当扫黛初。","万壑千岩双不借，轻风细浪一夫须。","来书便当催诗雨，雪后灯前卷复舒。"]},{"t":"题王晋辅专春亭","f":"七言古诗","c":["向来王家癖于马，今来王家癖于花。","洛阳城里花如海，一半移取来君家。","此花就中最秾丽，姚家黄兼魏家紫。","花王更有王中王，看却姚魏千花降。","一春好处君知否，上巳前头寒食后。","千花不用妒渠伊，此外春光更属谁。"]},{"t":"题王晋辅桂堂","f":"七言古诗","c":["诸天别有金色界，金粟如来更奇怪。","玉露洗面晞金风，黄云迎下月姊宫。","未与群芳较颜色，寒香世界谁较得。","一个世界一粟中，万粟世界香无穷。","诗人梦入广寒殿，香杀诗人天不管。"]},{"t":"题长沙钟仲山判院岫云舒卷楼二首 其一","f":"七言绝句","c":["天柱峰尖半点云，散为岳麓橘洲春。","尽供诗客挥毫里，怪底春空态度新。"]},{"t":"题丘成之司理明远阁","f":"七言律诗","c":["决曹据按尘似海，高阁退食心如冰。","夜将官本校家本，万山围里短檠灯。","能文未得傲能吏，好官不应博丁字。","何时著脚最高层，目送归鸿挥绿绮。"]},{"t":"题左正卿寿慈堂","f":"七言古诗","c":["万事丝窠黏露珠，奉亲最乐天下无。","丘明远孙千里驹，有母七十发漆如。","雪底笋生冰底鱼，人间无觅天赐渠。","三更月落堂西隅，母自挑灯儿读书。","去年生日不用扶，今年生日健过初。","冰桃碧藕脆如酥，一觞千岁母子俱。"]},{"t":"题永丰刘伯英双清亭","f":"七言古诗","c":["银河一派天上来，霜松万本水际栽。","公干作亭占佳处，拦住清风入窗户。","醉馀绿绮膝上横，学得松声与水声。","更待九秋月亭午，白玉壶中有新句，烦君赤手双拾取。"]},{"t":"题玄潭观雪浪阁","f":"七言古诗","c":["赣江西来千里许，流到阁前虎须怒。","旌阳横剑居上头，却喝长江教倒流。","跳作漩花雪山立，溅得琳房满山湿。","即今水落未足观，桃花浪起君来看，一波打窗君胆寒。"]},{"t":"题兴宁县东文岭瀑泉在夜明场驿之东","f":"词","c":["笋舆路转崖欹倾，只闻满山泉水呜。","卷书急看已半失，眼不停注耳细听。","石如铁色黑，壁立镜面平。","水从镜面一飞下，蕲笛织簟风漪生。","石知水力倦，半壁钟作天一泓。","水行到此欲小憩，后水忽至前水惊。","分清裂白两派出，跳珠跃雪双龙争。","不知落处深几许，千丈井底碎玉声。","安得好事者，泉上作小亭。","酿泉为酒不用曲，春风吹作蒲萄绿。","醉写泉声入柘木，何处更寻响泉曲。"]},{"t":"题刘子远春风堂","f":"七言律诗","c":["艮斋先生门下士，寒星向晓今馀几。","春风堂上刘更生，十年桂山问奇字。","艮斋正派谁真传，更生得髓仍得肝。","春风卷著两袖里，放出抟扶天地间。"]},{"t":"题刘子远宴坐画图楼","f":"七言律诗","c":["大年小景真儿戏，郭熙远山闲故纸。","东山一塔作毛锥，试点卢溪一溪水。","洒出楼前千万峰，一一奔腾入楼里。","金华仙翁强解事，攘我楼中新句子。"]},{"t":"题吕子明国谕退庵","f":"五言律诗","c":["笔砚工为祟，湖山苦约盟。","坐忘非圣处，行乐且吾生。","一笑谁当会，孤斟句恰成。","何时却乘兴，雪外叩柴荆。"]},{"t":"题孙舜俞府判瑞石图","f":"词","c":["鸡冠山青龟浦碧，松桂捎云三万尺。","何年星霣化为石，风吹未凝冰玉色。","仙人擘开光烛天，山下人家夜不眠。","松花桂子落如雪，飞入石中坚似铁。","石中种树人不知，石中生树人始奇。","君不见只今瑞图满四海，骚人诗卷牛腰大。"]},{"t":"题安成刘伯深爵瑞里报德堂上白爵图","f":"词","c":["君不见书台之北爵瑞里，安成令君旌孝子。","报德堂前松造天，卜宅浩然老居士。","居士元无一物遗，子孙只有牙签三万存。","郎君饭此三万轴，落纸云烟动场屋。","雪中负土成先茔，感得路人双涕零。","更传雪爵云上堕，天表孝子踏雪行。","即看黄告来告弟，是时雪爵应再至。"]},{"t":"题安城赵宽之慈顺堂","f":"七言律诗","c":["天潢龙种与人殊，五凤仍传万卷书。","象服在堂萱草暖，綵衣上寿棣华初。","雪中密竹能抽笋，冰底寒江更跃鱼。","赵氏弟兄俱玉树，艮斋文字即琼琚。"]},{"t":"题安福刘虞卿敏斋","f":"词","c":["君不见杜家阿宜开雪窗，日读十纸月一箱。","君不见崔家阿立染霜兔，暮作千诗朝百赋。","读书台北卯金刀，斋前不种李与桃。","满阶只种书带草，黄金非宝书为宝。","郎君玉树临风前，咀嚼青竹夜不眠。","何须多羡崔与杜，诸郎努力青云路。"]},{"t":"题巩仲至脩辞斋","f":"七言古诗","c":["人道庄周梦蝴蝶，我言蝴蝶梦庄周。","庄周解飞蝶解语，说向蝴蝶应点头。","脩辞斋中子巩子，年少诗狂狂到底。","蹇驴破帽冲达官，白眼清谈对馀子。","东莱一翁印斯人，世人皆憎翁不嗔。","为渠落笔三大字，政自不妨诗入神。"]},{"t":"题朱伯勤千峰紫翠楼二首 其一","f":"七言绝句","c":["秀岭西头凤岭东，周遭略数一千峰。","商量没顿新楼处，顿著秾蓝酽紫中。"]},{"t":"题毕少董翻经图","f":"词","c":["宋生把卷读且指，李生把卷问奇字。","榻上坐著一老子，右手秉笔袒左臂。","春秋论语训传成未成，胸中有话颇欲告两生。","欲呼小白拉重耳，同讨犬戎尊帝京。","蚕妾不解事，两生未可语。","冬郎政儿痴，谁能复怜许。","翻经未了报归期，携书归来献玉墀。","胡沙满面无人识，回首两生斗南北。"]},{"t":"题严州新堂","f":"七言古诗","c":["新堂略有次第否，忙里从公一来觑。","是时新晴收旧雨，小风吹花掠巾屦。","江山只道不解语，云何惠然堂上聚。","北山故挽南山住，东溪不遣西溪去。","向来天藏在何处，遭公拈出天不拒。","旧亭不为山作主，背山起楼何以故。","更烦好手铲东阜，放出钓台寸来许。"]},{"t":"题吴梦与古乐府","f":"七言律诗","c":["金麦褰帷银蒜钩，水光殿后月华楼。","莺歌花笑柳起舞，何处人间更有愁。","吴郎那得吴宫语，梦里苧罗人道许。","低红掩翠曲未终，小儿索饭啼门东。"]},{"t":"题张以道上舍寒绿轩","f":"词","c":["菊芽伏土糁青粟，杞笋傍根埋紫玉。","雷声一夜雨一朝，森然迸出如蕨苗。","先生饥肠诗作梗，小摘珍芳汲冰井。","风炉蟹眼候松声，笊篱亲捞微带生。","烂炊凋胡淅青精，芼以天随寒绿萌。","饥时作齑仍作羹，饱后龙凤同庖烹。","太官蒸羔压花片，宰夫胹蹯削琼软。","豹胎熬出祸胎来，贵人有眼何曾见。","天随尚有愁作魔，愁杞作棘菊作莎。","君不见黄金钱照红玉豆，秋高更觉风味多。","先生酿金鍊红玉，自莎自棘如予何。","金空玉尽苗复出，吃苗吃花并吃实。","天随白眼屠沽儿，不道有人头上立。"]},{"t":"题张兴伯主簿经训堂","f":"七言古诗","c":["范家尚有釜生鱼，张家无鱼釜也无。","屠沽儿亦莫笑渠，渠有至富汝不如。","一翁冻吟拥竹炉，诸郎映雪夜读书。","山鬼来听鹤惊起，万壑无人霁月孤。","不论取官大门闾，始是经训为菑畬。","父子每腹百斛珠，出门掩鼻马牛裾。"]},{"t":"题张季长少卿饰庵庵名取告词云学足以自饰","f":"五言古诗","c":["吾友张饰庵，学到贲上白。","真贲初非文，至饰亦无色。","君看瑄玉姿，岂借青黄饰。","宝气不自中，白虹贯空碧。","饰庵隐岷岭，英名震京国。","鲁论感凤叹，春秋辩麟获。","孝庙聘丘园，有来校坟籍。","光皇访忠贤，再起贰卿棘。","未应两朝旧，不侍九重侧。","训词揭昭回，圣意深记忆。","盍归赞人文，小却犹讲席。","未要从子真，带月耕岩石。"]},{"t":"题李子立知县问月台","f":"七言古诗","c":["高台走上青天半，手弄银盘濯银汉。","唤起谪仙同醉吟，一面问月一面斟。","初头混沌鹘崙样，阿谁凿开一为两。","是时燧人犹未胎，那得火铸银盘来。","此盘能团复能缺，团是谁磨缺谁齧。","中有桂枝起秋风，何处移来秧此中。","谪仙似痴还似黠，把酒问月月无说。","老夫代月一转语，月却问君君领否。","君能饮酒更能诗，一夕无月君不嬉。","月能伴君饮百斛，月能照君诗万玉。","君但一斗百篇诗，莫问有月来几时。","谪仙远孙證明著，笑脱乌纱看月落。"]},{"t":"题李季章中书舍人石林堂","f":"七言古诗","c":["紫微仙人今太白，不爱好官爱奇石。","顷从道山归雪山，一叶渔船一横笛。","船过宣池月满空，乘云飞上九华峰。","十指一掇九芙蓉，和月擎取归船中。","归到雁湖秋水碧，万斛酒船觞九客。","蟆颐诸峰作不速，不待折简登几席。","侬与石兄殊不疏，问讯别来安稳无。"]},{"t":"题汪圣锡坟庵真如轩在玉山常山之间","f":"七言古诗","c":["东吴南垂楚北际，中央不合大如砺。","百滩千嶂自一川，清空不是人间世。","玉山先生携老禅，把茅结庵开小轩。","身前身后来醉眠，一醉不醒三千年。","先生杖屦半宇宙，每到此轩去还又。","为怜雪立孤竹君，月骨风筋如许瘦。","向来种笋今排天，先生手痕故依然。","骑龙帝旁为飞仙，玉棺寂寞空寒烟。"]},{"t":"题陆子泉上祠堂","f":"七言古诗","c":["先生吃茶不吃肉，先生饮泉不饮酒。","饥寒祗忍七十年，万岁千秋名不朽。","惠泉遂名陆子泉，泉与陆子名俱传。","一瓣佛香炷遗像，几多衲子拜茶仙。","麒麟图画冷似铁，凌烟冠剑消如雪。","惠山成尘惠泉竭，陆子祠堂始应歇，山上泉中一轮月。"]},{"t":"题周鲠臣浩斋","f":"七言古诗","c":["浩翁曲肱一浩斋，焉知廊庙与蒿莱。","此翁定复死不死，旧斋又新有贤子。","斋前种树初如椽，如今过云欲造天。","作人谁无半点气，草动风惊便心醉。","回山倒海不关身，古人与我各何人。","杉溪老人是翁友，拈出问渠渠领否。"]},{"t":"题罗巨济教授蓬山堂","f":"七言古诗","c":["蓬莱藏室盛东都，只著古书并老儒。","后来许事晓星疏，登车不落问何如。","广文先生自有饭，诸公衮衮端无羡。","著脚金坡不作难，问津木天何足办。","作堂聊尔题蓬山，此岂有意亦偶然。","登瀛仙人多姓许，未必先生肯为伍。","书生饶舌定可憎，此话姑置莫葛藤。","先生诸孙皆玉冰，诵书已作鸾鹤声，请来欹枕细细听。"]},{"t":"题金山妙高台","f":"词","c":["金山未到时，羡渠奄有万里之长江。","金山既到了，长江不见只见千步廊。","老夫平生不奈事，点检风光难可意。","老僧觉我见睫眉，引入妙高台上嬉。","不知老僧有妙手，卷舒江山在怀袖。","挂上西窗方丈间，长江浮在炉烟端。","长江南边千万山，一时飞入两眼寒。","最爱檐前绝奇处，江心巉然景纯墓。","僧言道许乃浪传，龙宫特书珠贝编。","初云谢灵运，爱山如爱命。","掇取天台雁荡怪石头，叠作假山立中流。","又云王逸少，草圣入神妙。","天赐琉璃笔格玉砚屏，仍将大江作陶泓。","老夫闻二说，沉吟未能决。","长年抵死催上船，徘徊欲去空茫然。"]},{"t":"题青山市汪家店","f":"七言绝句","c":["小小楼临短短墙，长春半架动红香。","杨花知得人孤寂，故故飞来入竹窗。"]},{"t":"题南屏山兴教寺清旷楼赠择讷律师","f":"七言绝句","c":["清旷楼中夕眺间，落晖残雨两生寒。","楼中占尽南山了，更占西湖与北山。"]},{"t":"题南海东庙","f":"七言古诗","c":["罗浮山如万石钟，一股南走如渴龙。","雷奔电迈遮不住，直抵海滨无去处。","低头饮海吐绛霞，举头戴著祝融家。","珠宫玉室水精殿，万水一日朝再衙。","青山四围作城郭，海涛半浸青山脚。","客来莫上浴日亭，亭上见海君始惊。","青山缺处如玉玦，潮头飞来打双阙。","晴天无云溅碎雪，天下都无此奇绝。","大海更在小海东，西庙不如东庙雄。","南来若不到东庙，西京未睹建章宫。","海神喜我著绮语，为我改容收雾雨。","乾坤轩豁未能许，小试日光穿漏句。"]},{"t":"题峡江谭温父咏斋","f":"七言律诗","c":["渔郎载我下峡水，夜寻故人有谭子。","柴门竹屋断崖底，艮斋手题咏斋字。","巴丘花草一番新，玉笥峰头月半轮。","如今政是暮春者，三叹春风舞雩下。"]},{"t":"题星子县黄宰世高问政堂","f":"词","c":["黄子侬故人，危子侬门生。","向来同登漱玉亭，银河洗面醉不醒。","四年二子不见面，过眼光阴掣飞电。","今晨忽得问政碑，黄子作堂危子词。","危子笔力乃尔进，黄子佳政不须问。","寄言二子各努力，古人也是人作得。"]},{"t":"题浏阳县柳仲明致政云居山书院","f":"七言古诗","c":["云居山高三万尺，下插浏江上撞日。","柳下和风百世师，有孙避地来筑室。","奕叶隐居三百年，栽桃种杏今满川。","当家相传一破砚，此外文字九千卷。","旄头毕方书散亡，维仲明父再耿光。","木叶衣裳野蕨肠，牙签玉轴还堆床。","更于山下起高阁，竹户松窗照林壑。","阁上诸郎夜诵声，太一真人降云鹤。","向来有子中文科，泮宫弹琴咏菁莪。","柳氏门闾人刮目，仲明依旧一渔蓑。"]},{"t":"题眉山程侅所藏山谷写杜诗帖","f":"七言古诗","c":["杜家碧山银鱼诗，黄家虎卧龙跳字。","六丁难取真宰愁，程家十袭今三世。","程家苏家元舅甥，子瞻正辅外弟兄。","正辅有孙文百鍊，笔倒三江胸万卷。","公车献策五十篇，玉札国体航化源。","远谋小扣囊底智，瑰词未出海内传。","三年抱璞咸阳市，子虚无因达天帝。","如今却买巴峡船，峨眉山月秋正圆。","丈夫身健恐不免，即召枚皋未渠晚。"]},{"t":"题赵昌父山居八咏 其四 两峰堂","f":"五言绝句","c":["踏得草鞋穿，行得汗脚损。","却换一枝藤，拄到双玉笋。"]},{"t":"题赵昌父山居八咏 其八 青毡堂","f":"五言绝句","c":["客来借毡看，笑指一书策。","不管卖不行，且图偷不得。"]},{"t":"题唐德明秀才玉立斋","f":"七言古诗","c":["坡云无竹令人俗，我云俗人正累竹。","玉立斋前一万竿，能与主人相对寒。","看竹哦诗笔生力，山童怪予遽忘食。","不但不可一日无，斯须无此看何如。","诗成欲写且复歇，恐竹嫌诗未清绝。","丁宁一竿不可除，竹亦何曾减风月。"]},{"t":"题唐德明建一斋","f":"七言律诗","c":["城南前江后山趾，竹斋正对寒江启。","不嫌渔火乱书灯，只苦橹声惊睡美。","平生刺头钻故纸，晚知此道无多子。","从渠散漫汗牛书，笑倚江枫弄江水。"]},{"t":"题徐载叔双桂楼","f":"七言古诗","c":["遥怜天上桂华孤，月中何不种两株。","唐人此句真绝唱，后来诗人半语无。","向来何夕秋风起，吹脱广寒双桂子。","落向君家楼阁前，种玉开花今几年。","清宵双影写窗户，却兼月里成三树。","年年八月九月时，黄金粟缀青瑶枝。","秋风吹香入月去，风回却带天香归。","容斋仙人为作碑，诚斋老人为作诗。","金蟆玉兔已传诵，莫问姮娥知不知。"]},{"t":"题栖贤寺三峡桥","f":"五言古诗","c":["栖贤与楞伽，初本共一山。","古潭宅神龙，睡醒厌久跧。","是夕起雷雨，震得天地翻。","此山拆为两，一溪断中间。","下窥黑无地，上攀青到天。","从此两禅寺，路绝不往还。","祖师见之笑，弹指降神奸。","问天借横蜺，搭渡溪两边。","倒倾千崖雪，飞下一玉渊。","馀怒尚雷吼，声拔诸峰根。","我来不能去，轻生倚危栏。","忽然心为动，毛骨森以寒。","上人指断岸，犹带初拆痕。"]},{"t":"题益公丞相天香堂","f":"词","c":["君不见沉香亭北专东风，谪仙作颂天无功。","君不见君王殿后春第一，领袖众芳捧尧日。","此花司春转化钧，一风一雨万物春。","十分整顿春光了，收黄拾紫归江表。","天香染就山龙裳，馀芬却染山水乡。","青原白鹭万松竹，被渠染作天上香。","人间何曾识姚魏，相公新移洛中裔。","呼酒先招野客看，不醉花前为谁醉。"]},{"t":"题曹仲本出示谯国公迎请太后图自肃天仗以下皆纪画也","f":"词","c":["德寿宫前春昼长，宫中花开宫外香。","太皇颐神玉霄上，都人久不瞻清光。","今晨忽见肃天仗，翠华黄屋从天降。","一声清跸万人看，天街冰销楼雪残。","北来又有一红伞，八鸾三騑金毂端。","辇中似是瑶池母，凤舄霞裳剪云雾。","太皇望见天开颜，万国春风百花舞。","乃是慈宁太母回鸾图，母子如初千古无。","朔云边雪旗脚湿，御柳宫梅寒影疏。","向来慈宁隔沙漠，倩雁传书雁难托。","迎还騩驭彼何人，魏武子孙曹将军。","将军元是一缝掖，忽攘两臂挽五石。","长揖单于如小儿，奉归慈辇如折枝。","功盖天下只戏剧，笑随赤松蜡双屐，飘然南山之南北山北。","君不见岳飞功成不抽身，却道秦家丞相嗔。"]},{"t":"题望韶亭","f":"七言古诗","c":["新隆寺后看韶石，三三两两略依稀。","金坑津头看韶石，十十五五不整齐。","一来望韶亭上看，九韶八音堆一案。","金钟大镛浮水涯，玉瑟瑶琴倚天半。","尧时文物也粗疏，礼乐犹带鸿荒馀。","茅茨殿上槌土鼓，苇籥声外无笙竽。","黄能郎君走川岳，领取后夔搜礼乐。","峄山桐树半夜鸣，泗水石头清昼跃。","山祇川后争献珍，姚家制作初一新。","帝思南岳来时巡，宫琛庙宝皆骏奔。","曲江清澈碧琼软，海山孤尖翠屏展。","天颜有喜后夔知，一奏云韶供亚饭。","帝登九疑忘却归，不知斑尽湘笛枝。","后夔一胫跛莫随，坐委众乐江之湄。","仪凤舞兽扫无迹，独留一狻守其侧。","至今唤作狮子石，雨淋日炙烂不得。","洞庭张乐已莓苔，犍为获磬亦尘埃。","不如九韶故无恙，戛击尚可冬起雷。","何时九秋霜月里，来听湘妃瑟声美。","曲终道是不见人，江上数峰是谁子。"]},{"t":"题清江胡民瞻忍堂","f":"词","c":["俗物茫茫奈我何，儿女昵昵不用呵。","先生笑问有酒么，醉来得句自长哦。","家风孝友春风软，床无黄金且青简。","君不见多愁多恼张公艺，枉却御前百馀字。"]},{"t":"题萧端虚和乐堂","f":"七言律诗","c":["玉笥风回峡山雨，两公对床方软语。","少公一生吟样臞，长公半醉少公扶。","白头兄弟不多有，面如橘红不关酒。","紫荆花开连理枝，孝友未要时人知。"]},{"t":"题黄才叔看山亭","f":"七言律诗","c":["春山华润秋山瘦，雨山点黯晴山秀。","湖湘山色天下稀，零陵乃复白其眉。","作亭不为俗人好，个竹把茅吾事了。","朝来看山佳有馀，为渠更尽一编书。"]},{"t":"题黄辰告愚斋","f":"七言律诗","c":["圣门如天不可梯，诸子欲以智取之。","杏坛独立无个事，只有回愚也大奇。","吾党少年子黄子，问津陋巷参颜氏。","只今此事冷如浆，来年八月槐花黄。"]},{"t":"题黄唐伯一经堂","f":"七言古诗","c":["人言天地生仲尼，不知仲尼生两仪。","易中先自有太极，生天生地谁得知。","一经以后派为六，六经以前一经足。","学子要探天地心，诗书执礼皆可寻。","吾乡后身黄叔度，教子一经有佳处。","寄言韦家父子间，浪比籯金良汗颜。"]},{"t":"题彭孝求碧云飞观","f":"七言律诗","c":["寸云如絮起青原，飞空化作一碧山。","天风吹上南斗边，砰然堕在快阁前。","老彭有孙拉云住，海蜃吐楼压云去。","日暮佳人来不来，朗诵汤休断肠句。"]},{"t":"题曾无愧月窗","f":"词","c":["阿兄作云巢，阿弟作月窗。","乾坤清气只云月，一家两手并取将。","作巢不用木，只架云为屋。","作窗不用棂，只掇月为庭。","兜罗绵上住兄子，银色界中著吾弟。","阿兄云向笔下生，阿弟月向诗中明。","弟兄云月两清绝，云月何曾有分别。","不知云月入胸中，为复胸中有云月。"]},{"t":"题曾无疑云巢","f":"七言古诗","c":["兰芷溪头子曾子，日饭兰花饮溪水。","犹嫌尘土涴荷衣，移家龙山西复西。","清晨芒屦上山觜，瞥见寸云石边起。","急追捉得絮一毬，襟包袖裹不放休。","须臾奔腾触怀出，散满晴空那可收。","云师却与曾子戏，展为大幕褰为帔。","独携曾子登云巢，其上无天下无地。","忽闻阿香笑一呼，曾子惊顾巢亦无。","归来作巢学云样，夜夜云来宿巢上。"]},{"t":"题曾世夫颐斋","f":"五言古诗","c":["吾友子曾子，滋兰涧溪幽。","药房动波底，韦编著床头。","梦吞六画香，身从三圣游。","上瞻岐山开，下聆雷声收。","告于閟灵龟，潜渊骑玉虬。","食菲足自养，朵颐非所求。","一朝浮洛书，绿字献禹畴。","分半啖虞翻，相视一笑休。"]},{"t":"题曾景山通判寿衍堂","f":"七言古诗","c":["人家具庆已燕喜，人家重庆更奇伟。","宜春台上贤治中，妙龄斫桂广寒宫。","亲年九十身六二，芝兰玉树森庭砌。","上堂綵衣称寿觞，下堂绣口喧雪窗。","紫枢相公喜嘉祥，大书寿衍名其堂，五世其昌未渠央。"]},{"t":"题湖北唐宪桂林义学","f":"词","c":["梅花五岭八桂林，青罗带绕碧玉簪。","祥刑使者两唐裔，亲领诸生到洙泗。","七星岩畔筑斋房，独秀峰尖作笔床。","买书堆上天中央，海表学子来奔忙。","中州淑气无间断，南斗文星方炳焕。","君不见日南姜相曲江张，万古清风裂云汉。"]},{"t":"题湘中馆二首 其二","f":"五言律诗","c":["江欲浮秋去，山能渡水来。","娵隅蛮语杂，欸乃楚声哀。","寒早当缘闰，诗成未费才。","愁边正无奈，欢伯一相开。"]},{"t":"题瘦牛岭","f":"词","c":["牛头定何向，牛尾定何指。","我不炙汝心，我不穿汝鼻。","如何不许见全牛，雾隐云藏若相避。","行行上牛背，上下三十里。","一雨生新泥，寸步不自致。","胡不去作牵牛星，渴饮银河天上水。","胡不去作帝藉牛，天田春风牵黛耜。","却来蛮村天尽头，塞路长遣行人愁。","夕阳芳草只依旧，瘦牛何苦年年瘦。"]},{"t":"题潘彦政叔侄濯缨斋","f":"七言古诗","c":["愚溪之口湘江左，茅斋不小亦不大。","斋前看江江只流，江中望斋斋更幽。","两潘读书韵清壮，湘妃出听鱼吹浪。","大潘皎如鹤出林，小潘不减在沙金。","向来姓名到天府，市人莫笑渠尘土。","濯缨当属最闲人，两潘且弹冠上尘。"]},{"t":"题薰陾中兴庆寿颂","f":"词","c":["炎晖十叶生太皇，即宋光武赵少康。","皇穹柱折地无轴，再辟三极纪八荒。","与天同仁自同寿，八十万岁登九九。","淳熙天子驾苍龙，春王三朝领群后。","是时雪花晓尚飘，日华飞来雪即销。","玉卮滟海泛椒柏，宝册错锦凋琼瑶。","虞典汉仪照亿世，可无鸿笔描天地。","下帷窥园几代孙，浓墨大书三万字。","点窜封禅典引辞，涂改皇武贞符诗。","珠玑金玉槌作屑，铸出夏鼎仍商彝。","歧阳石鼓鱼贯柳，浯溪石崖非好手。","谁将臣陾中兴庆寿篇，刻之玉版藏名山，何千万年千万年。"]},{"t":"憩怀古堂","f":"五言古诗","c":["新葺怀古堂，旧临郭璞池。","去岁夏徂秋，无日不此嬉。","茨菰无暑性，芙蕖有凉姿。","今年池水乾，老子来遂稀。","岂惟来不留，亦复去靡思。","朝来偶一到，又觉景特奇。","水含霁后光，荷于风处欹。","便有白鸥下，惊起翠羽飞。","方池滟窗东，长池横檐西。","红绿向背看，觞咏朝夕宜。","此堂初无情，此池谅何知。","如何涉斯世，乖逢亦有时。"]},{"t":"檃括东坡瓶笙诗序","f":"七言古诗","c":["饯饮东坡月三更，中觞忽闻笙箫声。","杳杳若在云霄间，抑扬往返中八音。","徐而察之出双瓶，水火相得自啸吟。","食顷乃已不可寻，坐客惊叹得未曾。","八月四七岁庚辰。"]},{"t":"澹庵坐上观显上人分茶","f":"七言古诗","c":["分茶何似煎茶好，煎茶不似分茶巧。","蒸水老禅弄泉手，隆兴元春新玉爪。","二者相遭兔瓯面，怪怪奇奇真善幻。","纷如擘絮行太空，影落寒江能万变。","银瓶首下仍尻高，注汤作字势嫖姚。","不须更师屋漏法，只问此瓶当响答。","紫微仙人乌角巾，唤我起看清风生。","京尘满袖思一洗，病眼生花得再明。","汉鼎难调要公理，策勋茗椀非公事。","不如回施与寒儒，归续茶经传衲子。"]},{"t":"瘴雾","f":"七言绝句","c":["午时犹未识金乌，对面看人一似无。","腊月黄茅犹尔许，不知八月却何如。"]},{"t":"羲娥谣","f":"七言古诗","c":["羲和梦破欲启行，紫金毕逋啼一声。","声从天上落人世，千村万落鸡争鸣。","素娥西征未归去，簸弄银盘浣风露。","一丸玉弹东飞来，打落桂林雪毛兔。","谁将红锦幕半天，赤光绛气贯山川。","须臾却驾丹砂毂，推上寒空辗苍玉。","诗翁已行十里强，羲和早起道无双。"]},{"t":"薛舍人母方氏太恭人挽章二首 其二","f":"五言律诗","c":["赋感东征句，诗愁陟屺篇。","生前九龄梦，眼底五朝天。","锦告浑无恙，云车忽杳然。","不堪青竹笋，归路不迎船。"]},{"t":"薛舍人母方氏太恭人挽章二首 其一","f":"五言律诗","c":["熊胆平生苦，鱼轩晚岁荣。","芝兰今柱史，苗裔古玄英。","寒食花争泣，元宵烛半明。","从今好时节，萱砌罢君羹。"]},{"t":"赠玉婿时可","f":"七言古诗","c":["忠襄先生有贤甥，卢溪先生有贤孙。","只今二十能缀文，超然下笔如有神。","忠襄大节争日月，卢溪清风敌霜雪。","两家不是无家法，何须外人问衣钵。","老夫卧病南溪旁，芙蓉红尽菊半黄。","子来问讯维摩诘，分似家风一瓣香。"]},{"t":"赠写真水鉴处士王温叔","f":"词","c":["我不如森森千丈松，我不如濯濯春月柳。","髯疏鬓秃已雪霜，皮皱肉皴真老丑。","叶生画时颜尚朱，王生画时骨更臞。","一生爱山吟不就，两肩化作秋山瘦。","君不见褒公鄂公图凌烟，腰间羽箭大如椽。","君不见浣花醉图粉墨落，日斜泥滑驴失脚。","贵人寒士两相嗤，画图犹在人已非。","王生王生且停手，不如生前一杯酒。"]},{"t":"赠左元规","f":"七言律诗","c":["谁道古人今不如，龙生龙驹凤凤雏。","太冲千载有孙子，笔端真可四三都。","向来鹿鸣首送渠，至今银袍双袖乌。","会逢玄晏为拈出，殿前作赋声第一。"]},{"t":"赠尚献之","f":"五言古诗","c":["老凤苍然姿，雏凤锵然鸣。","一见渠父子，令人英气生。","大尚傲一世，不肯揖公卿。","小尚刷羽毛，势欲追风鹏。","吾州八千士，下笔电雹声。","小尚洒墨汁，一笑万人惊。","姓名登天府，纸价高帝城。","勖哉更摩厉，制胜在此行。","相遭又相别，勿作儿女情。","舟行得秀句，寄我增双明。"]},{"t":"赠法才师","f":"五言律诗","c":["才公南华别，不见八年许。","瓣香宗混融，只眼半唐举。","聊将笋蕨觜，戏作冠剑语。","天还在壶中，云却归何处。"]},{"t":"赠旴江谢正之","f":"七言古诗","c":["旴江天上银河冰，麻姑人间白玉京。","不生金珠不生玉，只生命代千人英。","前有泰伯后子固，后无来者前无古。","九州四海何同年，浓墨大字荐惠连。","君家春草池塘句，只今又见君著语。","袖中绣出诗一编，清新不减春草篇。","愿君努力古人事，再光麻姑与旴水。"]},{"t":"赠临川严泰伯秀才","f":"五言律诗","c":["临汝严夫子，支筇扣敝庐。","文如漆园壮，人似客星孤。","善相遗驎瘦，深参得腹腴。","行看最先进，辨论诎诸儒。"]},{"t":"赠倪正甫令子阿麟","f":"七言古诗","c":["精神玉雪眼点漆，总角两髦锦缠碧。","郎君未出客已惊，隔窗读书鸾鹤声。","松烟兔颖小三昧，虿尾银钩略无对。","钟王笔法老始成，阿麟今才十二龄。","七十列传十二纪，白头书生不能记。","乱抽架上聊试渠，横诵倒诵如流水。","二雅三颂已作笺，要与毛郑争先鞭。","吟诗作赋更馀事，不论五言兼七字。","奉常先生有阴功，翰苑仙人有家风。","高科好官手可唾，更看声名塞天破。","老夫还曾浪语么，老夫还曾浪语么。"]},{"t":"赠都下写真叶德明","f":"词","c":["我昔山林人不识，或疑谪仙或狂客。","仰看青天不看人，醉里那知眼青白。","一携破砚入长安，素衣成缁绿鬓斑。","上林麒麟著野马，沧洲鸥鹭缀孔鸾。","汉宫威仪既不入贵人样，灞桥风雪又不见诗人相。","不须览镜照清溪，我亦自憎尘俗状。","叶君著眼秋月明，叶君下笔秋风生。","市人请画即唾骂，只写龙章凤姿公与卿。","肯来为予写衰貌，掷笔掉头欣入妙。","相逢可惜迟十年，不见诗翁昔年少。"]},{"t":"赠高德顺","f":"七言律诗","c":["儿时同客水中蟹，鸭脚林间索诗债。","只今白发共青灯，一尊浊酒话平生。","我才不及君才美，毛颖负君真差事。","见说君家千里驹，看渠高大君门闾。"]},{"t":"赠彭云翔长句","f":"七言古诗","c":["读书台边士如云，卢溪门下士如麟。","定知此地难为士，后来之秀说彭子。","雪里能来访我为，当阶下马雪满衣。","赠我文章无不有，出入欧苏与韩柳。","如今场屋号作家，相州红缬洛中花，岂如彭子有律令。","会当一书取张景，今年谁子司文柄。"]},{"t":"赠蜀中相士范思齐往全州见万先之教授","f":"七言古诗","c":["两脚那解上金銮，两手只合把钓竿。","比身管乐儿时态，已翻九河洗我肝。","范生来自浣花里，眼中之人定谁贵。","百鍊未必贤绕指，贵人正要老于事。","斜风细雨又春休，落花啼鸟总春愁。","试问谈间立封侯，何如百钱挂杖头。"]},{"t":"赠墨工张公明","f":"七言古诗","c":["庐陵旧墨说潘衡，庐陵新墨说张生。","潘家衣钵嗣苏子，张家苗裔出易水。","易水松花烟一螺，涨起倒流三峡波。","人言天下无白墨，那知真有玄尚白。","磨光漆几夺眼睛，试点一点倾人城。"]},{"t":"餐霜醒酒","f":"七言绝句","c":["宿酒朝来醉尚残，胸怀眊氉腹仍烦。","牡丹坛上栏干脚，自刮霜毬衮舌端。"]},{"t":"壕上感春","f":"七言古诗","c":["长壕无事不耐静，若非织绡便磨镜。","竹君不作五斗谋，风前折腰也如磬。","先生节里城上嬉，朝游暮游不肯归。","晴空大声斗作恶，万鸦退飞一鸦落。","乃是黑风江北来，更将黑云头上堆。","翻手为晴覆手雨，自晴自雨何须怒。","先生不妨且觅句，挽之不来推不去。","坐看梅花一万枝，化成粉蝶作团飞。","纷纷掠面收不得，稍稍积砌吹还稀。","落尽梅花天不管，晚来许寒朝许暖。","一年待春春不回，一年探梅梅不开。","春回今才几许日，梅开如何顿萧瑟。","少壮几时奈老何，落花未抵春愁多。"]},{"t":"檄风伯","f":"七言律诗","c":["峭壁呀呀虎擘口，恶滩汹汹雷出吼。","溯流更著打头风，如撑铁船上牛斗。","风伯劝尔一杯酒，何须恶剧惊诗叟。","端能为我霁威否，岸柳掉头荻摇手。"]},{"t":"濠原路中","f":"七言律诗","c":["长亭短亭三复五，总是儿时行底路。","尚忆天寒日小黄，先君前行我后顾。","如今悲不为涂穷，病雁孤飞失老鸿。","三年闭户松风里，行路又还从此始。"]},{"t":"霜塞辘轳体二首 其二","f":"五言律诗","c":["今晓难离火，平生不拥炉。","只缘青女降，便与管城疏。","淡日明还暗，微暄有似无。","谁能忍寒得，苦死去看书。"]},{"t":"霜塞辘轳体二首 其一","f":"五言律诗","c":["滴地酒成冻，喧天鸦诉寒。","窗风经怒响，帘日漏温痕。","偶尔寻梅去，其如驻屐难。","沙鸥脚不袜，故故踏冰翻。"]},{"t":"露坐戏嘲星月","f":"五言古诗","c":["东生定西归，月岂不识路。","何须倩长庚，夜夜引行步。","星住月不行，星行月不住。","无人问阿姊，此事竟谁主。","不知听金蟆，无乃由玉兔。","来夜偷此星，看月归何处。"]},{"t":"太守赵山父命刘秀才写予老丑索赞","f":"词","c":["香山有个狂客，恣游三十六峰。","不是河南贤尹，谁赠明月清风。"]},{"t":"农家六言","f":"词","c":["插秧已盖田面，疏苗犹逗水光。","白鸥飞处极浦，黄犊归时夕阳。"]},{"t":"看笋六言","f":"词","c":["笋如滕薛争长，竹似夷齐独清。","只爱锦绷满地，暗林忽两三茎。"]},{"t":"宴客夜归六言","f":"词","c":["月在荔支梢上，人行抹利花间。","但觉胸吞碧海，不知身落南蛮。"]},{"t":"演雅六言二首 其二","f":"词","c":["果蠃周公作诰，鷾鸸由也升堂。","白鸥比德于玉，黄鹂巧言如簧。"]},{"t":"演雅六言二首 其一","f":"词","c":["觳觫受田百亩，蛮触有宅一区。","蚍蜉戒之在斗，蝇蚋寔繁有徒。"]},{"t":"蝇虎六言","f":"词","c":["长有青蝇入梦，初无白额负嵎。","传业羲皇网罟，齐名斗谷于菟。"]},{"t":"糟蟹六言二首 其二","f":"词","c":["别业抛离水国，失身堕在糟丘。","莫笑草泥郭索，策勋作醉乡侯。"]},{"t":"糟蟹六言二首 其一","f":"词","c":["霜前不落第二，糟馀也复无双。","一腹金相玉质，两螯明月秋江。"]},{"t":"忆秦娥 初春","f":"词","c":["新春早。","春前十日春归了。","春归了。","落梅如雪，野桃红小。","老夫不管春催老。","只图烂醉花前倒。","花前倒。","儿扶归去，醒来窗晓。"]},{"t":"水调歌头 贺广东漕蔡定夫母生日","f":"词","c":["玉树映阶秀，玉节逐年新。","年年九月，好为阿母作生辰。","涧底蒲芽九节，海底银涛万顷，酿作一杯春。","泛以东篱菊，寿以漆园椿。","对西风，吹鬓雪，炷香云。","郎君入奏，又迎珠幰入修门。","看即金花紫诰，并举莆常两国，册命太夫人。","三点台星上，一点老人星。"]},{"t":"归去来兮引/归去来兮","f":"楚辞体","c":["侬家贫甚诉长饥。","幼稚满庭闱。","正坐瓶无储粟，漫求为吏东西。","偶然彭泽近邻圻。","公秫滑流匙。","葛巾劝我求为酒，黄菊怨、冷落东篱。","五斗折腰，谁能许事，归去来兮。","老圃半榛茨。","山田欲蒺藜。","念心为形役又奚悲。","独惆怅前迷。","不谏后方追。","觉今来是了，觉昨来非。","扁舟轻扬破朝霏。","风细漫吹衣。","试问征夫前路，晨光小，恨熹微。","乃瞻衡宇载奔弛。","迎候满荆扉。","已荒三径存松菊，喜诸幼、入室相携。","有酒盈尊，引觞自酌，庭树遣颜怡。","容膝易安栖。","南窗寄傲睨。","更小园日涉趣尤奇。","尽虽设柴门，长是闭斜晖。","纵遐观矫首，短策扶持。","浮云出岫岂心思。","鸟倦亦归飞。","翳翳流光将入，孤松抚处凄其。","息交绝友堑山溪。","世与我相违。","驾言复出何求者，旷千载、今欲从谁。","亲戚笑谈，琴书觞咏，莫遣俗人知。","邂逅又春熙。","农人欲载菑。","告西畴有事要耘耔。","容老子舟车，取意任委蛇。","历崎岖窈窕，丘壑随宜。","欣欣花木向荣滋。","泉水始流澌。","万物得时如许，此生休笑吾衰。","寓形宇内几何时。","岂问去留为。","委心任运无多虑，顾皇皇、将欲何之。","大化中间，乘流归尽，喜惧莫随伊。","富贵本危机。","云乡不可期。","趁良辰、孤往恣游嬉。","独临水登山，舒啸更哦诗。","除乐天知命，了复奚疑。"]},{"t":"好事近 七月十三日夜登万花川谷望月作","f":"词","c":["月未到诚斋，先到万花川谷。","不是诚斋无月，隔一林修竹。","如今才是十三夜，月色已如玉。","未是秋光奇绝，看十五十六。"]},{"t":"芭蕉雨","f":"词","c":["芭蕉得雨便欣然，终夜作声清更妍。","细声巧学蝇触纸，大声锵若山落泉。","三点五点俱可听，万籁不生秋夕静。","芭蕉自喜人自愁，不如西风收却雨即休。"]},{"t":"念奴娇 上章乞休致，戏作念奴娇以自贺","f":"词","c":["老夫归去，有三径、足可长拖衫袖。","一道官衔清彻骨，别有监临主守。","主守清风，监临明月，兼管栽花柳。","登山临水，作诗三首两首。","休说白日升天，莫夸金印，斗大悬双肘。","且说庐陵传盛事，三个闲人眉寿。","拣罢军员，归农押录，致政诚斋叟。","只愁醉杀，螺江门外私酒。"]},{"t":"武陵春 老夫茗饮小过，遂得气疾，终夕越吟，而长孺子有书至，答以武陵春，因呈子西","f":"词","c":["长铗归乎逾十暑，不著鵔鸃冠。","道是今年胜去年。","特地减清欢。","旧赐龙团新作祟，频啜得中寒。","瘦骨如柴痛又酸。","儿信问平安。"]},{"t":"昭君怨 赋松上鸥","f":"词","c":["偶听松梢扑鹿。","知是沙鸥来宿。","稚子莫喧哗。","恐惊他。","俄顷忽然飞去。","飞去不知何处。","我已乞归休。","报沙鸥。"]},{"t":"昭君怨 咏荷上雨","f":"词","c":["午梦扁舟花底，香满西湖烟水。","急雨打篷声，梦初惊。","却是池荷跳雨，散了真珠还聚。","聚作水银窝，泛清波。"]},{"t":"与主簿叔蔬饮联句","f":"七言绝句","c":["蕨含春味紫如椽，酒入春风浪似山。","未信乾坤非细物，小吞螺浦半杯间。"]},{"t":"晓出净慈送林子方二首 其二","f":"七言绝句","c":["毕竟西湖六月中，风光不与四时同。","接天莲叶无穷碧，映日荷花别样红。"]},{"t":"大司成颜几圣率同舍招游裴园泛舟绕孤山赏荷花晚泊玉壶得十绝句 其七","f":"七言绝句","c":["城中担上买莲房，未抵西湖泛野航。","旋折荷花剥莲子，露为风味月为香。"]},{"t":"陈蹇叔郎中出闽漕别送新茶李圣俞郎中出手分似","f":"七言律诗","c":["头纲别样建溪春，小璧苍龙浪得名。","细泻谷帘珠颗露，打成寒食杏花饧。","鹧斑椀面云萦字，兔褐瓯心雪作泓。","不待清风生两腋，清风先向舌端生。"]},{"t":"贺皇太子九月四日生辰 其一","f":"七言绝句","c":["日日龙楼问寝时，鸡人未动漏花迟。","前星一点朝天帝，只有清台太史知。"]},{"t":"贺皇孙平阳郡王十月十九日生辰","f":"七言律诗","c":["前星炳焕领孙星，环拱中天日两轮。","四叶重光同圣世，千秋佳节近生辰。","本支秀茂旦复旦，典学熙明新又新。","喜入威颜天一笑，寿觞分赐一枝椿。"]},{"t":"三月十日","f":"七言律诗","c":["才看桃李锦成围，忽便园林绿作堆。","远草将人双眼去，飞花引蝶过墙来。","簿书节里无多著，怀抱朝来得好开。","已是七分春去了，何须鸟语苦相催。"]},{"t":"灯下读山谷诗","f":"七言律诗","c":["天下无双双井黄，遗编犹作旧时香。","百年人物今安在，千载功名纸半张。","使我诗篇如许好，关人身事亦何尝。","地炉火暖灯花喜，且只移家住醉乡。"]},{"t":"夜雨独觉","f":"七言律诗","c":["枕上还乡枕上回，更更点点把人催。","雨将苔砌滴到晓，风拣荻帘疏处来。","每到凋年每多感，不教睡眼不曾开。","来宵我识华胥路，莫近茶瓯近酒杯。"]},{"t":"夜闻风声","f":"七言律诗","c":["作寒作暑无处避，开花落花尽他意。","只有夜声殊可憎，偏搅愁人五更睡。","幸自无形那有声，无端树子替渠鸣。","斫尽老槐与枯柳，更看渠侬作么生。"]},{"t":"郡圃残雪三首 其一","f":"七言绝句","c":["半依篱脚半依城，多傍梅边水际亭。","最是晚晴斜照里，黄金日射万银星。"]},{"t":"郡圃残雪三首 其二","f":"七言绝句","c":["南风融雪北风凝，晚日城头已可登。","莫道雪融便无迹，雪融成水水成冰。"]},{"t":"送施少才赴试南宫二首 其一","f":"五言律诗","c":["我岂登名晚，今仍作吏卑。","文能追古作，子未要人知。","取第真成漫，危言良独奇。","新知谁不乐，所要白头期。"]},{"t":"和昌英叔觅松枝作日棚 其二","f":"七言绝句","c":["欲和新诗且撚髯，岸巾百匝绕前檐。","茅斋或恐清阴薄，更遣苍官去一添。"]},{"t":"寄题石湖先生范至能参政石湖精舍二首 其二","f":"七言律诗","c":["不关白眼视青云，四海如今几若人。","渭水傅岩看后代，东坡太白即前身。","整齐宇宙徐挥手，点缀湖山别是春。","解遣双鱼传七字，遥知掉脱小乌巾。"]},{"t":"初十日早炊蕉步得家书并家酿二首 其二","f":"七言绝句","c":["年年自漉雪前醅，今岁无缘得一杯。","政是荒村愁绝处，家中送得六尊来。"]},{"t":"惠州丰湖亦名西湖二首 其二","f":"七言绝句","c":["三处西湖一色秋，钱塘颍水更罗浮。","东坡元是西湖长，不到罗浮便得休。"]},{"t":"淮河再雪二首 其二","f":"七言绝句","c":["昨晡日脚荡波红，今早天花舞镜中。","雪了又晴晴又雪，海神浑不惜神通。"]},{"t":"夜过高邮","f":"七言律诗","c":["水鸟舟人两不栖，波声风响总堪悲。","觉来枕上三更后，梦到江南一霎时。","邵伯问来还渐近，高邮过了不曾知。","满天星月银河湿，明早新晴也大奇。"]},{"t":"秀州嘉兴馆拜赐春幡胜","f":"七言律诗","c":["中使传宣下紫宸，镞头浓染御香云。","綵幡耐夏宜春字，宝胜连环曲水纹。","痴似土牛鞭不动，老登金马愧无闻。","强簪华发知难称，只有新诗颂万分。"]},{"t":"观张功父南湖海棠杖藜走笔三首 其二","f":"七言绝句","c":["百株都好却嫌渠，拣中东边第一株。","开与未开相间著，浓红密密淡疏疏。"]},{"t":"观张功父南湖海棠杖藜走笔三首 其三","f":"七言绝句","c":["天工信手洒明霞，若遣停匀未必佳。","却得数株多叶底，殷勤衬出密边花。"]},{"t":"和徐盈赠诗二首 其二","f":"七言绝句","c":["无鬼玄谈彫苦空，端能问字过杨雄。","韩琮不生王驾死，乞君明月与清风。"]},{"t":"安乐坊牧童","f":"七言古诗","c":["前儿牵牛渡溪水，后儿骑牛回问事。","一儿吹笛笠簪花，一牛载儿行引子。","春溪嫩水清无滓，春洲细草碧无瑕。","五牛远去莫管它，隔溪便是群儿家。","忽然头上数点雨，三笠四蓑赶将去。"]},{"t":"和王道父山歌二首 其二","f":"七言绝句","c":["阿婆辛苦住西邻，岂爱无家更愿贫。","秋月春风担阁了，白头始嫁不羞人。"]},{"t":"阻风泊舒州长风沙二首 其二","f":"五言律诗","c":["解缆鸾溪北，浮舟雁汊东。","才逢一日顺，却阻四程风。","万事乘除里，千年瞬息中。","请君明著眼，造物一狙公。"]},{"t":"东园幽步见东山四首 其二","f":"七言绝句","c":["何曾一日不思归，请看诚斋八集诗。","到得归来身已病，是侬归早是归迟。"]},{"t":"东园幽步见东山四首 其三","f":"七言绝句","c":["为爱东园日日来，未曾动脚眼先开。","南溪顷刻都行遍，更到东山顶上回。"]},{"t":"东园幽步见东山四首 其四","f":"七言绝句","c":["天赐东园食实封，东山加赐在园东。","东山山色浑无定，阴处青苍晒处红。"]},{"t":"六月初四日往云际院田间雨足喜而赋之二首 其二","f":"七言绝句","c":["去年今日政迎神，祷雨朝朝祷得晴。","今岁神祠免煎炒，更饶箫鼓赛秋成。"]},{"t":"与山庄子仁侄东园看梅四首 其四","f":"七言绝句","c":["步绕梅花遍一园，得花妙处忽欣然。","元来别有看花眼，笑向山庄死不传。"]},{"t":"题长沙钟仲山判院岫云舒卷楼二首 其二","f":"七言绝句","c":["入夜云来宿两窗，明朝云去照三湘。","也知远岫无心出，解后为霖亦不妨。"]},{"t":"题三老图二首 其二","f":"七言绝句","c":["刘郎写照妙通神，三老图成又一新。","只道老韩同传好，被人指点也愁人。"]},{"t":"淋疾复作医云忌文字劳心晓起自警二首 其二","f":"七言绝句","c":["荒耽诗句枉劳心，忏悔莺花罢苦吟。","也不欠渠陶谢债，夜来梦里又相寻。"]},{"t":"题朱伯勤千峰紫翠楼二首 其二","f":"七言绝句","c":["一色千峰翠作围，忽然齐换紫绡衣。","客来欲识楼中景，祇等金鸦浴海时。"]},{"t":"送戴良辅药者归城郛 其二","f":"七言绝句","c":["一生百病都好去，不但膏肓驱二竖。","寄言仲景与安常，古今何代无医王。"]},{"t":"五月三日早起步东园示幼舆子二首 其二","f":"七言绝句","c":["筠箕苕帚两无踪，窃果畦丁职不供。","老子不来才几曰，松花槲叶满亭中。"]},{"t":"张丞相咏归亭词二首 其一","f":"楚辞体","c":["湘之山兮幽幽，湘之水兮舒舒，我来兮桂之阳。","春聿云莫兮，上下绿净而交如。","鸟鸣兮花乾，彼湘之人士兮咏游而鱼鱼。","长者兮矩步，童子玉雪兮趋亦趋。","挟策兮抱琴，若将游兮物之初。","野风兮脩脩，吹万而不可执兮，所过而敷腴。","长者顾谓童子曰：快哉此风，吾为汝援琴而歌之。","歌曰：沧浪兮濯缨，风凉兮舞雩。","微德人兮焉归，以斯道兮金玉。","予欲问津兮沂之水，其则不远兮，又焉知湘江之非欤。"]},{"t":"张丞相咏归亭词二首 其二","f":"楚辞体","c":["茝兰圃兮沼芙蕖，有美君子兮何斯其燕居。","孚尹兮袖间，升白虹兮斗之虚。","章甫兮深衣，御风骑气而天游兮，与造化而为徒。","独立万物之表兮，室迩而人甚远。","山立而渊靓兮，道德燕及乎虫鱼。","韦编兮在手，隐几而卧兮，梦一丈夫。","首肖乎尼山兮河其目，莞尔而笑兮告予以下学而上达，知我者其天乎。","忽寤兮四顾，欸乃一声兮亭之西隅。"]},{"t":"和张钦夫望月词","f":"楚辞体","c":["玉虫晕以贯虹兮学林之颠，阒其宵兮圣贤毕参于前。","心超兮千载，忽乎纳自牖兮光寒而静娟。","吾兴视兮何祥，望舒推毂兮辚大圜。","生两仪兮虚白，饰万物兮清妍。","彼何居兮轃兹，挈一规兮破幽偏。","代天兮宣精，㧖欹兮恶盈。","似道兮日损，缩于一晦弦兮，万斯年而求伸。","宅天下兮至晦，镜天下兮至明。","烛吾心中之月兮，贯地纬而洞天经。","吾奉月兮周旋，月踵吾兮后先。","夫君寄我兮三章，招月而与寓目兮，炯笔势之翩翩。","想他日之独立兮，过庭而侍侧。","谁其耳剽于玉振兮，惟此月知其然。","月不予留兮，予亦咏而归。","歌三终兮谢明月，何夕复惠然兮临我于亭乎而。"]},{"t":"延陵怀古三首 其一 延陵季子","f":"楚辞体","c":["荆之溪兮澹以幽，惠之山兮云侔。","思君子兮不见，莽草树兮脩脩。","面句吴兮东而坐，背朱方兮北卧。","齐楚岂不强而大兮吾王以妥。","贤于国其无裨兮，不曰季子存而吴贺。","彼懵者之躗言兮，谓兆亡于让王。","弗丕承于考心兮，用永五湖之与三江。","祀太伯其忽诸兮，顾袭誉于子臧。","曾不知民无让而不立兮，自古皆有亡。","诹屺岵与锄箕兮，畴莫知其重轻。","若千乘暨箪豆兮，絜丰约而则明。","迨躬逢而利怵兮，亦几何而靡争。","谓吾札之不懿兮，札亦恬受而茹声。","思复思兮君子，乾坤毁而日月息兮，则君子之亦死。"]},{"t":"延陵怀古三首 其二 兰陵令","f":"楚辞体","c":["密云兮终风，健顺闭兮罔寸蹊之通。","喟葵丘践土而迹熄兮，矧冀方岐山之与逢。","单棠溪以铸兵兮，靡遗蒲于董泽。","燕簴无趾而造齐庙兮，楚氓而秦其魄。","斗六王于一说兮，微仪衍之舌而不国。","嗟若先生兮，鸡知时之不如。","储唐虞之故冕兮，鬻洙泗之敝裾。","乘方轮与折轴兮，欲先鞭而疾驱。","岂不家捐而人弃兮，载之万世之亨衢。","繄素王兮中都，若兰陵兮圣之徒。","征九伯而佩六印兮，晞二邑宰而不得俱。","傥不欲以天球玉磬而贸康瓠兮，嗟尔后死者其舍诸。"]},{"t":"延陵怀古三首 其三 东坡先生","f":"楚辞体","c":["吹赤壁之月笛兮，瞻黄州之雪堂。","弹湘妃之玉瑟兮，织天孙之锦裳。","招先生其来归兮，何必怀眉山之故乡。","历九州而犹隘兮，诞寘之祝融之汪。","酌乳泉以当醴兮，餐荔子以为粮。","葺榕叶以作屋兮，托桄榔之荫以为堂。","驱海涛以入砚滴兮，挽南斗文星于笔铓。","昌黎兮欧阳，视先生兮雁行。","韫不泄兮忠愤，炯不掩兮文章。","乞镜湖兮九关，营菟裘兮是邦。","予之来兮云暮，与先生兮相望。","视履迹兮焉在，问故宫兮就荒。","俯仰兮永怀，渺山川兮苍苍。"]},{"t":"跋李允蹈思故山赋辞","f":"楚辞体","c":["月岩含章兮，噫。","熟贳之璜兮，噫。","逋不其偿兮，噫。","眉山之下兮，噫。","既亿其价兮，噫。","胡漏于罅兮，噫。","吁于眉山兮，噫。","山吁于天兮，噫。","天蹙其颜兮，噫。","有斐孙子兮，噫。","花披秀启兮，噫。","烈祖是似兮，噫。","笔似其锋兮，噫。","骨似其穷兮，噫。","栖栖其逢兮，噫。","尔词则古兮，噫。","尔骚则楚兮，噫。","尔璞孰估兮，噫。","招招巫咸兮，噫。","有篿尔占兮，噫。","曷焯尔潜兮，噫。","曷窞不济兮，噫。","曷蔀不贲兮，噫。","咷初笑既兮，噫。"]},{"t":"和渊明归去来兮辞","f":"楚辞体","c":["归去来兮，平生怀归今得归。","有未归而不怿，岂当怿而更悲。","愧一陶之不若，庶二疏兮可追。","肖令威之归辽，喟物是而人非。","捐水苍兮今佩，反芰制兮昨衣。","恋岂谖夫太紫，分敢踰于少微。","如鹿得草，望绿斯奔。","如鹤出笼，岂复入门。","屦虽未得，而趾故存。","谓予不信，有如泰樽。","月喜予之言归，隤清晖而照颜。","山喜予以出迎，相劳苦其平安。","江喜予而舞波，击碎雪于云关。","纷邻曲之老稚，羌堵墙以来观。","沸里巷之犬鸡，亦喜翁之蚤还。","惊鬓髯之两霜，尚赳赳而桓桓。","归去来兮，半天下以倦游。","饥予驱而予出，奚俟饱而无求。","观一箪之屡空，躬自乐而人忧。","暨一区之草玄，娱羲画与箕畴。","岂慕胥靡，济川作舟。","矧先人之敝庐，有一壑兮一丘。","后千寻兮茂林，前十里兮清流。","耿靡羡而载营，蹇何骛而不休。","已矣乎！","用舍匪吾，行止匪时。","何至啜醨如渔父，何必乎誓墓兮如羲之。","吾行可枉涂，吾止可预期。","应耘耔而端委，犹端委而耘籽。","对天地而一哂，酢风光以千诗。","抵槁茎与朽壳，岂复从詹尹而决疑。"]},{"t":"黄世永哀辞","f":"楚辞体","c":["圣门际天而不可径兮，子聚粮以疾趋。","古文熄而哇郑兮，子独追而雅诸。","众皆赏其襮而遗其里兮，知全者不在予。","仕者谓赣民之嚚兮，不啻沬邦之夫。","何子之仁以莅兮，若膝下之乳雏。","予惟子之观兮，则未知封屋之迂。","沐猴豸而罔腼兮，子发上而衡盱。","舍己躁进而谓子躁进兮，宜不曰沽名之非愚。","世切齿于彼之晚霣兮，流涕于子之不晚殂。","庸知天之不子祉兮，不厚彼之辜。","惟师友之恩纪兮，一饭而九其吁。","天不予棐而夺予朋兮，半其济而亡舻。","决汝汉而东之兮，曾足为予泪之馀。","若子之死而不死兮，不亦名星日而骨幽墟。"]},{"t":"曾叔谦哀辞","f":"楚辞体","c":["岁绍兴之壬午兮，余负丞于零陵。","汩夫君之南征兮，临二松之寒厅。","闻跫然于逃虚兮，辞未接而情亲。","分一日之光景兮，载鸱夷乎吾与行。","沛吾击其兰桡兮，乱湘江以扬舲。","维余笮于愚溪兮，叩柳子之柴荆。","陟西山以茹芳兮，降钴鉧以漱泠。","风吹衣以拂云兮，举手揽乎南斗之星。","君与我其俱醉兮，夜解手于丘亭。","余未几而北归兮，君忽返乎铭旌。","曾合离之俛仰兮，奄古今乎死生。","羌夫君之渊伟兮，允江山之载英。","蔚豫章之离奇兮，森楩梓其峥嵘。","自拱把而培溉兮，俟百围乎千寻。","崒雪山与冰谷兮，凛霜影而雨声。","细犹堪于薄栌兮，岂大者之不可杗。","仰神皋于太紫兮，矩厚载而规圜。","清屹建章以亘明光兮，连蕙草与兰林。","诏班尔以骏奔兮，旁搜岩崖之欹倾。","缔皇居及帝室兮，将涓休乎落吾成。","蹇栋干槁乾于空山兮，匠不获以督绳。","纷后皇之揠材兮，壑何幽之不徵。","喟一撷而万捐兮，夫孰有遭而无营。","君方舍斯世而去之兮，岂达欣而穷憎。","耿精爽之未泯兮，嗤彼啄腐而吞腥。","裁斯文以寄哀兮，聊复写久要平生之情。"]},{"t":"范女哀辞","f":"楚辞体","c":["有齐石湖之季女兮，肇葰茂而青葱。","兰茁芽以芬播兮，玉在璞而光融。","茹采蘋以为粻兮，筑内则为之宫。","乐彤管以俶载兮，逝将眇青竹而论功。","制菡萏以为裾兮，裼之以秋江之芙蓉。","纷蕙纕而菊佩兮，岂江蓠揭车之与缝。","掇袤丈之朔雪以澡德兮，袭万壑之清冰而在躬。","耿吾独传中郎之素业兮，岂曰矜萧然林下之风。","沛吾乘乎桂舟兮，无小无大焉从吾公。","何若而人之不淑兮，奄一疢而长终。","忍舍兰陔之孝养兮，莽玉女宓妃之与从。","父曰嗟予膳之孰视兮，母曰嗟予命之畴同。","衋两亲之哀潸兮，遗九宗之长恫。","蹇石湖之恸而莫之释兮，小极而隐几乎书之丛。","梦漂漂而行远兮，求吾儿乎四方上下之青穹。","杳碧海之际天兮，岿三山之倚空。","蓬莱方丈之攸宅兮，浮金宫银阙之崇崇。","若有人乎山之阿兮，飞腾往来而不可逢。","羌可逢而不可执兮，若迥映乎复朣胧。","摘玉李而弄金波兮，遨嬉乎倒景有无之濛鸿。","忽临睨乎旧乡兮，望见石湖之仙翁。","泫初咷而后哂兮，唁吾翁乎奚戚容。","繄天地万物之逆旅兮，儿与翁父子适相值于逆旅之中。","汩倏合而忽分兮，邈千变万化而何穷。","淬割愁之剑而不满一笑兮，非我翁春日览镜大篇之舂容。","翁顾笑而惊寤兮，皦寒日其生于东。"]},{"t":"悼双珍辞","f":"楚辞体","c":["有傅者岭兮，有玄者潭。","崒乎琼台与玉堂兮，天垂光而蔚蓝。","宝祲下蟠乎九渊兮，瑰彩上绚乎千岩。","羌旁砖轇轕而不漓兮，耿虹贯乎晴岚。","劬玉衡之望气兮，九载旭考而宵参。","曰西江之轸墟兮，孕双珍乎泥之潜。","匪珠胎之双止兮，则瑴玉其美兼。","帝令雷公以持斧兮，敕阳侯以发函。","逝将修贡于玉府兮，旅清庙而尔瞻。","夫何夔魖獝狂之予妒兮，肆为伯明之谗。","蹇诉帝以不好兮，未听六丁之穷探。","飞巨石以载震兮，汹怒涛以有严。","连璧毁于石韫兮，双珠裂于波涵。","卞和恸以叫帝阍兮，随侯泣以衣沾。","帝亦悲伤而末如之何兮，磔不若魑魅而不厌。","安得双珍之再芒兮，迥映乎西江之北南。"]},{"t":"有宋死孝毛子仁哀辞","f":"词","c":["灏穹眷宋，方郅隆些。","笃生仁皇，实睿聪些。","二尧两舜，复时雍些。","杜韩富范，再夔龙些。","巍荡奋熙，起丕功些。","欧阳伯仲，轲与雄些。","云昭汉回，炳文风些。","麟在灵囿，凤在桐些。","金芝专车，朱草丛些。","悬藜结绿，牣紫宫些。","灵蛇照乘，玉府充些。","大江之西，文江东些。","毛伯苗裔，河岳钟些。","三辰五纬，韫心胸些。","如汉贾生，与终童些。","年未弱冠，收科崇些。","连收制科，天动容些。","玉映汉台，惊群公些。","弃官如泥，子职恭些。","死孝倚庐，神明通些。","文行有炜，垂无穷些。","与宋一经，相始终些。","冻黎百年，养万钟些。","草腐菌朽，花霣空些。","有宋孝子，蔚岱嵩些。"]},{"t":"赵平甫幽居八操 其一 筠居操","f":"词","c":["公子诛茅，不木不土。","此君惠然，聿来胥宇。"]},{"t":"赵平甫幽居八操 其二 我娱斋操","f":"词","c":["一室容膝，纳万壑而有馀。","一几凝尘，载千古而不重。","暮四朝三，吾不复梦。"]},{"t":"赵平甫幽居八操 其三 醉石操","f":"词","c":["望之温其玉，即之寒于冰。","一饮五斗，一石解酲。","众人皆醉石独醒。"]},{"t":"赵平甫幽居八操 其四 竹斋操","f":"词","c":["客来何闻，客去何嗔。","左右前后惟此君。","德不孤，必有邻。"]},{"t":"赵平甫幽居八操 其五 北窗操","f":"词","c":["一枕之甘，万户不愿。","清风之快，万玉不价。","为我谢避俗翁，谁在羲皇之下。"]},{"t":"赵平甫幽居八操 其六 梅亭操","f":"词","c":["竹屋夜明，竹户寒声。","幽人舍琴而起视，香通国而白连城。","梅耶雪乎，四问而四不应。"]},{"t":"赵平甫幽居八操 其七 棋台操","f":"词","c":["争名不亢则朝者嘻，争利不赢则市者吁。","君子无所争，必也弈乎。"]},{"t":"赵平甫幽居八操 其八 龟潭操","f":"词","c":["风耆其武，波赫斯怒。","油然者渊，未遽如许。"]},{"t":"题曾景山通判寿衍堂","f":"五言绝句","c":["风月暂平分，为霖喜有人。","斯堂非浪扁，佐主寿跻民。"]},{"t":"送刘茂才主簿之官理定","f":"七言绝句","c":["梅子青青荔未丹，葵丘缩戍便之官。","莫言屋矮位卑甚，早晚高人振羽翰。"]},{"t":"萧照邻参政大资挽诗","f":"七言绝句","c":["公如月欠一分圆，生死应同昼与昏。","鼎鼐□□□□□，□□露□留好□。"]},{"t":"赠旴江谢正之","f":"五言绝句","c":["策马访柴扉，庭前草亦□。","谈今复谈古，如子□□□。"]},{"t":"太守赵山父命刘秀才写予老丑索赞","f":"七言绝句","c":["□□如斯兼儿丑，丹青写出十分真。","凌烟绘像吾无望，喜在山林老此身。"]},{"t":"寄题舒州宿松知县戴在伯重新紫霄亭","f":"七言绝句","c":["高高亭耸紫霄端，借榻高眠廛市间。","轮奂重新无俗□，何如来此伴云闲。"]},{"t":"雨后至溪上三首 其一","f":"七言绝句","c":["□□□□一番□，□□风光□□□。","□□渭川公子在，此时□□理丝纶。"]},{"t":"雨后至溪上三首 其二","f":"七言绝句","c":["扁舟一叶泊溪弯，一雨初收篷未乾。","风浪依然平帖后，渔翁□出把渔竿。"]},{"t":"雨后至溪上三首 其三","f":"七言绝句","c":["拟借丹青画作图，退休老子作渔夫。","凤凰池上虽荣贵，何似清闲看浴凫。"]},{"t":"寄题太和宰赵嘉言勤民二图 其一","f":"七言绝句","c":["特借丹青写二图，二图之意果何如。","请君细看□□□，是亦□求无逸书。"]},{"t":"寄题太和宰赵嘉言勤民二图 其二","f":"七言绝句","c":["□民勿视作□□，勉力耕桑贵及时。","上古□□犹画像，老夫喜赠二篇诗。"]},{"t":"上元前一日游东园看梅三首 其一","f":"七言绝句","c":["谁占百花头上魁，花神推许□□□。","东园春信知多少，今日喜晴拚一来。"]},{"t":"上元前一日游东园看梅三首 其二","f":"七言绝句","c":["东园把酒问东皇，何事梅花压众芳。","和靖当年一题品，到今几载句犹香。"]},{"t":"上元前一日游东园看梅三首 其三","f":"七言古诗","c":["春到东园恰□□，腊前闻已破南枝。","□□□□□□□，□旦元□□□诗。"]},{"t":"李原之主簿投赠长篇谢以唐律","f":"楚辞体","c":["宝气亭前双太阿，龙光再吐射银河。","伯兮西啸巴山月，仲氏南嬉楚水波。","赠以四愁真绝唱，不如一诣听长哦。","簿书何至烦勾校，归校芸香蠹简讹。"]},{"t":"寄题西昌彭孝求求志堂","f":"七言古诗","c":["西江山水何处好，观山夜泉快阁风。","山奇水秀产瑰宝，彭氏四杰隐此中。","斗间异气如白虹，少微芒寒摇太空。","占言非剑亦非玉，长松下有幽人屋。","似闻鸣驺入空谷，篱边老却陶潜菊。"]},{"t":"句 其一","f":"五言古诗","c":["露窠蛛恤纬，风语燕怀春。"]},{"t":"句 其二","f":"五言古诗","c":["立岸风大壮，还舟灯小明。"]},{"t":"句 其三","f":"七言古诗","c":["疏星煜煜沙贯日，绿云扰扰水舞苔。"]},{"t":"句 其四","f":"七言古诗","c":["坐忘日月三杯酒，卧护江湖一钓船。"]},{"t":"含笑花","f":"七言律诗","c":["菖蒲节序芰荷时，翠羽衣裳白玉肌。","暗折花房须日暮，遥将香气报人知。","半开微吐长怀宝，欲说还休竟俛眉。","树脆枝柔惟叶健，不消更画只消诗。"]},{"t":"雨后至溪上三首","f":"七言古诗","c":["□□□□一番□，□□风光□□□。","□□渭川公子在，此时□□理丝纶。","扁舟一叶泊溪弯，一雨初收篷未乾。","风浪依然平帖后，渔翁□出把渔竿。","拟借丹青画作图，退休老子作渔夫。","凤凰池上虽荣贵，何似清闲看浴凫。"]},{"t":"句","f":"词","c":["露窠蛛恤纬，风语燕怀春。","立岸风大壮，还舟灯小明。","疏星煜煜沙贯日，绿云扰扰水舞苔。","坐忘日月三杯酒，卧护江湖一钓船。"]},{"t":"武陵春","f":"词","c":["长铗归乎逾十暑，不著鵕鸃冠。","道是今年胜去年。","特地减清欢。","旧赐龙团新作祟，频啜得中寒。","瘦骨如柴痛又酸。","儿信问平安。"]}]};